\section{Formalism for bosons}
There are mainly two differences in the formulation for bosons as opposed to fermions. The first one is the difference between symmetry and antisymmetry of $\hat{S}_{\bm{q}}$.
In the bosonic case, we can symmetrize the Hamiltonian matrix elements:
\begin{align}
    \mathcal{P}_{\alpha}H_{\rm int}\mathcal{P}_{\alpha}&=\frac{1}{2}\sum_{\bm{k}_1,\bm{k}_2,\bm{q}}[\hat{S}^{\dagger}_{\bm{q}}\hat{S}_{\bm{q}}]_{\bm{k}_1,\bm{k}_2}c^{\dagger}_{\bm{k}_1}c^{\dagger}_{\bm{q}-\bm{k}_1}c_{\bm{q}-\bm{k}_2}c_{\bm{k}_2},\\
    [\hat{S}_{\bm{q}}]_{a,\bm{k}}&=\frac{[\hat{A}_{\bm{q}}]_{a,\bm{k}}+[\hat{A}_{\bm{q}}]_{a,\bm{q}-\bm{k}}}{\sqrt{2}}.
\end{align}
The bosonic symmetry is encoded into the following relation:
\begin{align}
    [\hat{S}_{\bm{q}}]_{a,\bm{k}}=[\hat{S}_{\bm{q}}]_{a,\bm{q}-\bm{k}}~.\label{bosonsymmetry}
\end{align}

Another important difference is the absence of the Pauli principle. 
In the bosonic case, $\bm{k}\equiv\bm{q}-\bm{k}$ modulo a reciprocal lattice vector is allowed. 
Thus, the following basis spans the two-particle Hilbert space:
\begin{align}
    \ket{\bm{q};\bm{k}}:=
    \begin{cases}
    c^{\dagger}_{\bm{q}-\bm{k}}c^{\dagger}_{\bm{k}}\ket{0}&\mathrm{for}~n(\bm{k})< n(\bm{q}-\bm{k})\\
    c^{\dagger}_{\bm{k}}c^{\dagger}_{\bm{k}}\ket{0}/\sqrt{2}&\mathrm{for}~n(\bm{k})= n(\bm{q}-\bm{k})
    \end{cases}~~~~.
\end{align}
For this reason, the large Hamiltonian is modified as follows.
\begin{align}
&[\hat{\mathcal{H}}_{\bm{q}}]_{\bm{k},{\bm{k}'}}:=\bra{\bm{q};\bm{k}}\mathcal{P}_{\alpha}H_{\rm int}\mathcal{P}_{\alpha}\ket{\bm{q};\bm{k}'}=2~[\hat{S}'^{\dagger}_{\bm{q}}\hat{S}'_{\bm{q}}]_{\bm{k},\bm{k}'},\notag\\
&[\hat{S}'_{\bm{q}}]_{a,\bm{k}}=
    \begin{cases}
[\hat{S}_{\bm{q}}]_{a,\bm{k}}&\mathrm{for}~n(\bm{k})< n(\bm{q}-\bm{k})\\
    [\hat{S}_{\bm{q}}]_{a,\bm{k}}/\sqrt{2}&\mathrm{for}~n(\bm{k})= n(\bm{q}-\bm{k})
    \end{cases}~~~~.
\end{align}
While the large Hamiltonian is modified, the small Hamiltonian has the same expression as in the case of fermions:
\begin{align}
    &[\hat{h}_{\bm{q}}]_{a,a'}:=\sum_{\{\bm{k}|n(\bm{k})\leq n(\bm{q}-\bm{k})\}}2[\hat{S}'_{\bm{q}}]_{a,\bm{k}}[\hat{S}'^{\dagger}_{\bm{q}}]_{\bm{k},a'}\notag\\
    =&\sum_{\{\bm{k}|n(\bm{k})<n(\bm{q}-\bm{k})\}}[\hat{S}_{\bm{q}}]_{a,\bm{k}}[\hat{S}^{\dagger}_{\bm{q}}]_{\bm{k},a'}
    +[\hat{S}_{\bm{q}}]_{a,\bm{q}-\bm{k}}[\hat{S}^{\dagger}_{\bm{q}}]_{\bm{q}-\bm{k},a'}\notag\\
    +&\sum_{\{\bm{k}|n(\bm{k})=n(\bm{q}-\bm{k})\}}2\times\left(\frac{1}{\sqrt{2}}\right)^2[\hat{S}_{\bm{q}}]_{a,\bm{k}}[\hat{S}^{\dagger}_{\bm{q}}]_{\bm{k},a'}\notag\\
    =&\sum_{\bm{k}}[\hat{S}_{\bm{q}}]_{a,\bm{k}}[\hat{S}^{\dagger}_{\bm{q}}]_{\bm{k},a'}.
\end{align}

\section{Formalism for multiple target bands}
The extension for the case where there are multiple target bands for the projection is almost trivial.
Let us consider the following projection Hamiltonian:
\begin{align}
    \mathcal{P}H_{\rm int}\mathcal{P}
    =&\frac{1}{2N_{\rm unit}}\sum_{i,j}\sum_{\bm{q},\bm{k}_1,\bm{k}_2,\Delta\bm{r}}e^{-i(\bm{k}_1-\bm{k}_2)\cdot\Delta\bm{r}}V^{ij}(\Delta\bm{r})\notag\\
    &\sum_{\alpha,\beta,\gamma,\delta}u^{*}_{\bm{k}_1,\alpha}(i)u^{*}_{\bm{q}-\bm{k}_1,\beta}(j)u_{\bm{q}-\bm{k_2},\gamma}(j)u_{\bm{k}_2,\delta}(i)\notag\\
    &c^{\dagger}_{\bm{k}_1,\alpha}c^{\dagger}_{\bm{q}-\bm{k}_1,\beta}c_{\bm{q}-\bm{k}_2,\gamma}c_{\bm{k}_2,\delta},
\end{align}
where $\mathcal{P}$ is the projection operator onto the bands of interest.
The following basis spans the two-particle Hilbert space:
\begin{align}
    \ket{\bm{q};\bm{k},\alpha\beta}:=c^{\dagger}_{\bm{q}-\bm{k},\beta}c^{\dagger}_{\bm{k},\alpha}\ket{0}~~\mathrm{for}~n(\bm{k},\alpha)< n(\bm{q}-\bm{k},\beta),
\end{align}
where $n(\cdot)$ labels the set $\{\bm{k},\alpha\}$.
The matrix $\hat{A}_{\bm{q}}$ and $\hat{S}_{\bm{q}}$ are extended as follows:
\begin{align}
    &[\hat{A}_{\bm{q}}]_{a,\bm{k}\alpha\beta}=\sqrt{\frac{V^{ij}(\Delta\bm{r})}{N_{\rm unit}}}e^{i\bm{k}\cdot\Delta\bm{r}}u_{\bm{k},\alpha}(i)u_{\bm{q}-\bm{k},\beta}(j),\notag\\
    &[\hat{S}_{\bm{q}}]_{a,\bm{k}\alpha\beta}=\frac{[\hat{A}_{\bm{q}}]_{a,\bm{k}\alpha\beta}-[\hat{A}_{\bm{q}}]_{a,\bm{q}-\bm{k}\beta\alpha}}{\sqrt{2}}.
\end{align}
With this new $\hat{S}_{\bm{q}}$, one can define the scattering matrix $\hat{S}^{\dagger}_{\bm{q}}\hat{S}_{\bm{q}}$ and the small/large Hamiltonians, following the formulation in the main text.




