As an interacting part, we consider the following repulsive Hamiltonian:
\begin{align}
    H_{\rm int}&=\frac{1}{2}\sum_{i,j,\bm{r},\bm{r}'}V^{ij}(\bm{r}-\bm{r}')\rho_{\bm{r},i}\rho_{\bm{r}',j}\notag\\
    &=\frac{1}{2N_{\rm unit}}\sum_{i,j}\sum_{\bm{q}}V^{ij}(-\bm{q})\rho_{\bm{q},i}\rho_{-\bm{q},j}\notag\\
    &=\frac{1}{2N_{\rm unit}}\sum_{i,j}\sum_{\bm{q},\bm{k},\bm{k}',\Delta\bm{r}}e^{i\bm{q}\cdot(\Delta\bm{r})}V^{ij}(\Delta\bm{r})\notag\\
    &~~~~c^{\dagger}_{\bm{k},i}c_{\bm{k}+\bm{q},i}c^{\dagger}_{\bm{k}',j}c_{\bm{k}'-\bm{q},j}.
\end{align}
The density operators are defined as
\begin{align}
    &\rho_{\bm{r},i}=c^{\dagger}_{\bm{r},i}c_{\bm{r},i}=\frac{1}{N_{\rm unit}}\sum_{\bm{q}}e^{i\bm{q}\cdot\bm{r}}\rho_{\bm{q},i},\\
    &\rho_{\bm{q},i}=\sum_{\bm{r}}e^{-i\bm{q}\cdot\bm{r}}\rho_{\bm{r},i},\label{densityoperator}\\
    &V^{ij}(-\bm{q})=\sum_{\Delta\bm{r}}e^{i\bm{q}\cdot(\Delta\bm{r})}V^{ij}(\Delta \bm{r}),
\end{align}
where $\Delta\bm{r}:=\bm{r}-\bm{r}'$. 

Note that the following holds:
\begin{align}
    :H_{\rm int}:~&=\frac{1}{2}\sum_{i,j,\bm{r},\bm{r}'}V^{ij}(\bm{r}-\bm{r}')c^{\dagger}_{\bm{r},i}c^{\dagger}_{\bm{r}',j}c_{\bm{r}',j}c_{\bm{r},i}\notag\\
    &=H_{\rm int}-\frac{1}{2}\sum_{\bm{r},i}V^{ii}(\Delta\bm{r}=0)c^{\dagger}_{\bm{r},i}c_{\bm{r},i}\notag\\
    &=H_{\rm int}.
\end{align}
We have used the Pauli exclusion principle.
Thus, 
\begin{align}
    H_{\rm int}&=\frac{1}{2N_{\rm unit}}\sum_{i,j}\sum_{\bm{q},\bm{k},\bm{k}',\Delta\bm{r}}e^{i\bm{q}\cdot(\Delta\bm{r})}V^{ij}(\Delta\bm{r})\notag\\
    &~~~~c^{\dagger}_{\bm{k},i}c^{\dagger}_{\bm{k}',j}c_{\bm{k}'-\bm{q},j}c_{\bm{k}+\bm{q},i}\notag\\
    &=\frac{1}{2N_{\rm unit}}\sum_{i,j}\sum_{\bm{q},\bm{k}_1,\bm{k}_2,\Delta\bm{r}}e^{-i(\bm{k}_1-
    \bm{k}_2)\cdot\Delta\bm{r}}V^{ij}(\Delta\bm{r})\notag\\
    &~~~~c^{\dagger}_{\bm{k}_1,i}c^{\dagger}_{\bm{q}-\bm{k}_1,j}c_{\bm{q}-\bm{k}_2,j}c_{\bm{k}_2,i}.
\end{align}

The projected Hamiltonian is given by
\begin{align}
    \mathcal{P}_{\alpha}H_{\rm int}\mathcal{P}_{\alpha}
    =&\frac{1}{2N_{\rm unit}}\sum_{i,j}\sum_{\bm{q},\bm{k}_1,\bm{k}_2,\Delta\bm{r}}e^{-i(\bm{k}_1-\bm{k}_2)\cdot\Delta\bm{r}}V^{ij}(\Delta\bm{r})\notag\\
    &u^{*}_{\bm{k}_1,\alpha}(i)u^{*}_{\bm{q}-\bm{k}_1,\alpha}(j)u_{\bm{q}-\bm{k_2},\alpha}(j)u_{\bm{k}_2,\alpha}(i)\\
    &c^{\dagger}_{\bm{k}_1,\alpha}c^{\dagger}_{\bm{q}-\bm{k}_1,\alpha}c_{\bm{q}-\bm{k}_2,\alpha}c_{\bm{k}_2,\alpha}.
\end{align}
\section{Models}
In this section, we write down the Bloch Hamiltonians for the Chern insulators used in the main text.
\subsection{Checkerboard-lattice model}
This model was studied in terms of the fermionic FCI \cite{Neupert-Santos-Chamon-Mudry-11}. 
The Bloch Hamiltonian matrix is given by
\begin{align}
    H(\bm{k})=
    \begin{pmatrix}
    2t_2(\cos k_1-\cos k_2)&t_1f^*(\bm{k})\\
    t_1f(\bm{k})&-2t_2(\cos k_1-\cos k_2)\\
    \end{pmatrix},
\end{align}
where
\begin{align}
    &f(\bm{k})=e^{-i\pi/4}\left[1+e^{i(k_2-k_1)}\right]+e^{i\pi/4}\left[e^{-ik_1}+e^{ik_2}\right].
\end{align}
In numerical calculations, we set $t_1=1,t_2=\sqrt{2}/2$. For this parameter, the band structure becomes almost flat.

\subsection{Qi-Wu-Zhang (QWZ) model}
This model was proposed in Ref.~\cite{Qi-Wu-Zhang-06} and is also referred to as the Wilson-Dirac model. 
The Bloch Hamiltonian matrix is given by
\begin{align}
    &H(\bm{k})=\sin k_1 \sigma_x+\sin k_2 \sigma_y+(m-\cos k_1-\cos k_2)\sigma_z, \label{eq:QWZ_Bloch}
\end{align}
where $\sigma_{x,y,z}$ are the Pauli matrices. 
In numerical calculations, we set $m=1$.

