\title{Fractal dimensions of complex networks: advocating for a topological approach}




\author[1]{Rayna Andreeva}
\author[2]{Hayde\'e Contreras-Peruyero}
\author[3]{Sanjukta Krishnagopal}
\author[4]{Nina Otter}
\author[5]{Maria Antonietta Pascali}
\author[6]{Elizabeth Thompson}

