\subsection{Joint Target Detection}
Formally, joint target detection can be recast as a composite binary hypothesis test \cite{9362239,4441739}, yielding
\begin{equation}
\begin{aligned}
    \left\{\begin{array}{l}
    \mathcal{H}_0: \mathbf{y}_{n}=\bar{\boldsymbol{\epsilon}}_{n}, \quad n=1,\ldots,N,\\
    \mathcal{H}_1: \mathbf{y}_{n}=\gamma_{n}\boldsymbol{\eta}_{n}+\bar{\boldsymbol{\epsilon}}_{n}, \quad n=1,\ldots,N,
    \end{array}\right.
\end{aligned}
\end{equation}
where $\boldsymbol{\eta}_{n} \buildrel\textstyle.\over =\mathbf{H}_{n} \mathbf{w}$ is defined as the reflected signal vectors for the $n$-th receive AP.
The null hypothesis $\mathcal{H}_0$ represents the case that the sensing area contains only disturbance, which encompasses background clutter and noise, with no actual target present. Conversely, the alternative hypothesis $\mathcal{H}_1$ asserts the presence of a target within the sensing area in addition to any existing clutter and noise.

Since $\bar{\boldsymbol{\epsilon}}_{n}$ are independent of each other for different $n$, $\forall n \in \{1, \ldots, N\}$, the joint probability density function (PDF) of the spatially filtered sequence $\{\mathbf{y}_{n}\}_{n}$ under $\mathcal{H}_0$ is
\begin{equation}\label{PDF H0}
\begin{aligned}
    f_0(\{\mathbf{y}_{n}\}_{n}|\mathcal{H}_0)=\frac{1}{(\pi\sigma_\epsilon^2)^{MN}}\mathrm{exp}\left\{-\frac{\sum_{n}c_{0_{n}}}{\sigma_\epsilon^2}\right\},
\end{aligned}
\end{equation}
where
\begin{equation}\label{c0}
    c_{0_{n}}\buildrel\textstyle.\over=\|\mathbf{y}_{n}\|^2.
\end{equation}
Similarly, the joint PDF of the spatially filtered sequence $\{\mathbf{y}_{n}\}_{n}$ under $\mathcal{H}_1$ is
\begin{equation}\label{PDF H1}
\begin{aligned}
    f_1(\{\mathbf{y}_{n}\}_{n};\gamma_{n}|\mathcal{H}_1)=\frac{1}{(\pi\sigma_\epsilon^2)^{MN}}\mathrm{exp}\left\{-\frac{\sum_{n}c_{1_{n}}(\gamma_{n})}{\sigma_\epsilon^2}\right\},
\end{aligned}
\end{equation}
where
\begin{equation}\label{c1}
    c_{1_{n}}(\gamma_{n})\buildrel\textstyle.\over=\|\mathbf{y}_{n}-\gamma_{n}\boldsymbol{\eta}_{n}\|^2.
\end{equation}

Subsequently, we aim to derive the estimation over the unknown $\gamma_n$ from $f_1(\{\mathbf{y}_{n}\}_{n}; \gamma_{n}|\mathcal{H}_1)$. The negative log-likelihood function of \eqref{PDF H1} under $\mathcal{H}_1$ is proportional to
\begin{equation}
    V_1(\gamma_{n})=\mathrm{ln}(\sigma_\epsilon^2)+\frac{\sum_{n}c_{1_{n}}(\gamma_{n})}{\sigma_\epsilon^2}.
\end{equation}
Thus, minimizing $V_1$ with respect to $\gamma_{n}$ is equivalent to minimizing
\begin{equation}
\begin{aligned}
    V_2(\gamma_{n})&=\sum_{n}c_{1_{n}}(\gamma_{n})\\
    &=\sum_{n}\left(c_{0_{n}}-\gamma_{n}\bar{y}_{n}^*-\gamma_{n}^*\bar{y}_{n}+|\gamma_{n}|^2 \|\boldsymbol{\eta}_{n}\|^2\right),
\end{aligned}
\end{equation}
where $\bar{y}_{n}=\boldsymbol{\eta}_{n}^\mathrm{H}\mathbf{y}_{n}$. 
Thus, the minimization of $V_2$ with respect to $\gamma_{n}$ gives
\begin{equation}\label{hat gamma}
    \hat{\gamma}_{n}=\frac{\bar{y}_{n}}{\|\boldsymbol{\eta}_{n}\|^2}.
\end{equation}
% then the residual of the function $V_2$ is
% \begin{equation}
% \begin{aligned}
%      V_3&=\sum_{n}c_{1_{n}}(\gamma_{n})|_{\gamma_{n}=\hat{\gamma}_{n}}\\
%      &=\sum_{n}(c_{0_{n}}-|\hat{\gamma}_{n}|^2\|\boldsymbol{\eta}_{n}\|^2).
% \end{aligned}
% \end{equation}

In order to differentiate between $\mathcal{H}_0$ and $\mathcal{H}_1$, the generalized likelihood ratio test (GLRT) for the joint target detection is obtained as
\begin{equation}\label{GLRT before ln}
    \bar{\Lambda}\left(\mathbf{y}_{n}\right)=\frac{f_1(\{\mathbf{y}_{n}\}_{n};\gamma_{n}|\mathcal{H}_1)}{f_0(\{\mathbf{y}_{n}\}_{n}|\mathcal{H}_0)} \stackrel{\mathcal{H}_1}{\underset{\mathcal{H}_0}{\gtrless}} \bar{\lambda},
\end{equation}
where $\bar{\lambda}$ is the threshold and is chosen to satisfy the control of CFAR. Substituting the expressions for $f_0$ and $f_1$ formulated in \eqref{PDF H0} and \eqref{PDF H1}, and replacing the $\gamma_{n}$ with $\hat{\gamma}_{n}$ in \eqref{hat gamma}, the
decision rule can be simplified as 
\begin{equation}\label{Lambda}
\begin{aligned}
    \Lambda(\mathbf{y}_{n})& \buildrel\textstyle.\over=\ln\bar{\Lambda}(\mathbf{y}_{n})\\
    &=\frac{1}{\sigma_\epsilon^2}\left(\sum_{n} c_{0_{n}}-\sum_{n} c_{1_{n}}\left(\hat{\gamma}_{r, n}\right)\right)\\
    &=\frac{1}{\sigma_\epsilon^2}\sum_{n}\left(|\hat{\gamma}_{n}|^2 \|\boldsymbol{\eta}_{n}\|^2\right)\\
    &=\frac{1}{\sigma_\epsilon^2}\sum_{n}\left(\frac{|\bar{y}_{n}|^2}{\|\boldsymbol{\eta}_{n}\|^2}\right)\stackrel{\mathcal{H}_1}{\underset{\mathcal{H}_0}{\gtrless}} \lambda,
\end{aligned}
\end{equation}
where $\lambda\buildrel\textstyle.\over=\ln\bar\lambda$.

Under the null hypothesis $\mathcal{H}_0$ that contains only AWGN, the squared magnitude of the complex Gaussian variable $\bar{y}_{n}$ obeys
\begin{equation}
    \left|\bar{y}_{n}\right|^2\sim\sigma_\epsilon^2 \|\boldsymbol{\eta}_{n}\|^2\cdot \chi^2_2,
\end{equation}
where $\chi^2_2$ is a chi-squared random variable with $2$ degrees of freedom. Since $\Lambda(\mathbf{y}_{n})$ is the sum of $N$ chi-squared random variables, we have
\begin{equation}
	\Lambda(\mathbf{y}_{n}) \sim \chi^2_{2N},
\end{equation}
which follows a chi-squared distribution with $2N$ degrees of freedom. To ensure CFAR, we set the threshold $\lambda$ such that
\begin{equation}\label{P_FA}
\operatorname{Pr}\left\{\Lambda(\mathbf{y}_{n})>\lambda \mid \mathcal{H}_0\right\}\!=\!\int_\lambda^{\infty} p_{\Lambda \mid \mathcal{H}_0}\left(a \mid \mathcal{H}_0\right) d a \buildrel\textstyle.\over=P_{\mathrm{FA}},
\end{equation}
where $p_{\Lambda \mid \mathcal{H}_0}$ is the PDF of $\Lambda\left(\mathbf{y}_{n}\right)$ under $\mathcal{H}_0$ and
$P_{\mathrm{FA}}$ is defined as the false alarm rate. For the chi-squared distribution,
\begin{equation}
    P_{\mathrm{FA}}=1-F_{\chi^2_{2N}}\left(\lambda\right),
\end{equation}
where $F_{\chi^2_{2N}}(\cdot)$ is the cumulative distribution function (CDF) of the chi-squared distribution. Thus, the threshold $\lambda$ is given by the inverse of the CDF function.

Under the hypothesis $\mathcal{H}_1$, since the projected value obeys $\bar{y}_{n}=\hat{\gamma}_{n}\|\boldsymbol{\eta}_{n}\|^2+\boldsymbol{\eta}_{n}^\mathrm{H}\bar{\boldsymbol{\epsilon}}_{n} \sim \mathcal{CN}\left(\hat{\gamma}_{n}\|\boldsymbol{\eta}_{n}\|^2, \sigma_\epsilon^2 \|\boldsymbol{\eta}_{n}\|^2\right)$, we have
\begin{equation}
    \left|\bar{y}_{n}\right|^2\sim\sigma_\epsilon^2 \|\boldsymbol{\eta}_{n}\|^2\cdot \chi^2_2(\lambda^\mathrm{nc}_{n}),
\end{equation}
which follows a non-central chi-squared distribution, where $\lambda^\mathrm{nc}_{n}$ denotes the non-centrality parameter and is formulated as
\begin{equation}
	\lambda^\mathrm{nc}_{n}=\frac{|\hat{\gamma}_{n} \|\boldsymbol{\eta}_{n}\|^2|^2}{\sigma_\epsilon^2 \|\boldsymbol{\eta}_{n}\|^2}.
\end{equation}
In this case, $\Lambda(\mathbf{y}_{n})$ is a weighted sum of non-central chi-squared variables and obeys
\begin{equation}
    \Lambda(\mathbf{y}_{n}) \sim \sum_{n}\chi^2_2(\lambda^\mathrm{nc}_{n}),
\end{equation}
which has the following non-central chi-squared distribution properties. The sum of non-central chi-squared distributions with different non-centrality parameters $\lambda^\mathrm{nc}_{n}$ results in another non-central chi-squared distribution, i.e.,
\begin{equation}
    \Lambda(\mathbf{y}_{n})\sim \chi^2_{2N}\left(\sum\nolimits_{n}\lambda^\mathrm{nc}_{n}\right).
\end{equation}
Finally, the detection probability $P_D$ is calculated by
\begin{equation}\label{P_D}
	\operatorname{Pr}\left\{\Lambda(\mathbf{y}_{n})>\lambda \mid \mathcal{H}_1\right\}=\int_\lambda^{\infty} p_{\Lambda \mid \mathcal{H}_1}\left(a \mid \mathcal{H}_1\right) d a \buildrel\textstyle.\over=P_D,
\end{equation}
where $p_{\Lambda \mid \mathcal{H}_1}$ is the PDF of $\Lambda\left(\mathbf{y}_{n}\right)$ under $\mathcal{H}_1$.
\begin{remark}
    For a special case when $N=1$, $P_D = Q_M(\sqrt{\lambda_\mathrm{nc}},\sqrt{\lambda})$, where $Q_M(\cdot,\cdot)$ is the generalized Marcum-Q function \cite{1055327} expressing the complementary CDF (CCDF) of the non-central chi-squared distribution.
\end{remark}

So far,  the detection probability under the GLRT detection scheme has been derived, with the CFAR property ensured as specified in \eqref{P_FA}. Notably, for target detection at a specific position or within the same block, beamforming serves as a pivotal factor in determining the detection probability.

\subsection{Problem Formulation}
Unlike the case with perfect knowledge of $\{\mathbf{H}_n\}_{n = 1}^N$, where the detection probability $P_D$ can be maximized by directly optimizing the beamforming vector $\mathbf{w}$, this study addresses a beam selection problem based on a predefined codebook $\mathcal{W}$, without requiring accurate CSI, which would otherwise introduce substantial overhead.
Without loss of generality, we simply adopt the discrete Fourier transform (DFT)-based codebook in this work. 

Mathematically, the optimization problem is formulated to minimize the total number of beam tracking steps as follows
\begin{subequations}
\begin{align}
    (P1): \min _{T, \{\mathbf{w}_t\}_{t=1}^T} & {T} \notag\\
     \text{ s.t. } \quad & \mathbf{w}_t \in \mathcal{W}, \quad t= 1, \ldots, T,\label{constrain w}\\
     & P_{D}^t < \zeta, \quad t = 1, \ldots, T-1, \label{constrain Pd2}\\ 
     & P_{D}^T \geq \zeta,\label{constrain Pd}
\end{align}
\end{subequations}
where $T$ denotes the total number of tracking steps required in a specific scenario. The constraint in \eqref{constrain w} ensures that all the beamforming vectors are selected from the predefined DFT codebook. $\zeta$ in \eqref{constrain Pd2} and \eqref{constrain Pd} specifies a threshold set to guarantee satisfactory detection performance, which is ultimately achieved at the final tracking step $T$.
We propose our beam tracking policy by sequentially adjusting the transmitted beam codeword in response to environmental feedback. This approach obviates the need for exhaustive beam sweeping, thereby significantly reducing the communication overhead while maintaining efficient target detection. 

\textbf{Since the detection result from the previous decision directly impacts the subsequent action, rendering this process well-suited for modeling as an MDP.} To tackle this sequential decision-making problem, we utilize DRL to develop an interactive beam tracking strategy. DRL is particularly advantageous in this context due to its ability to handle high-dimensional state spaces and learn optimal policies through interactions with the environment, making it highly effective for complex beam tracking tasks.


\section{Online DRL-Based Beam Tracking Method}\label{section_online}
In this section, we establish the online DRL framework, which is trained using an online policy that iteratively interacts with the actual environment. The beam tracking procedure is first analyzed and modeled as an MDP. Subsequently, the optimization problem $(P1)$ is addressed by systematically designing the key components of the DRL model, including the agent, the state-action transition, and the reward function. Furthermore, considering the sparsity features, reward shaping is introduced to facilitate agent learning. Finally, the network architecture and training process are illustrated.

\subsection{MDP Formulation}
MDP is defined by a 4-tuple $\{\mathcal{S},\mathcal{A},\mathcal{P},\mathcal{R}\}$, where $\mathcal{S}$ is the state space, $\mathcal{A}$ is the action space, $\mathcal{R}: \mathcal{S}\times\mathcal{A}\rightarrow \mathbb{R}$ is the immediate reward after executing action $a_t\in\mathcal{A}$ at state $\mathbf{s}_t\in\mathcal{S}$, and $\mathcal{P}$ is the state transition probability function. According to Markov property, the condition $p(\mathbf{s}_{t+1}|\mathbf{s}_t,a_t,\mathbf{s}_{t-1},a_{t-1},\ldots,\mathbf{s}_0,a_0)= p(\mathbf{s}_{t+1}|\mathbf{s}_t,a_t)$ is satisfied. During the process of beam tracking, the transmit AP acts as an agent to learn decision-making and control policies in the system. It continuously interacts with the environment by transmitting beam codewords $\mathbf{w}_t$, receiving feedback in the form of detection probability $P_D^t$, and adjusting its subsequent beam codewords $\mathbf{w}_{t+1}$. Based on these foundations, the specific design of MDP in our considered beam tracking strategy is as follows.

\subsubsection{State}
The state vector at $t$-th stage is composed of three parts: the index of beam codeword selected at the current stage $\mu_{t}$, the corresponding detection probability $P_D^{t}$, and the feedback flag $f_g^t$. To be specific, $\mu_t$ is defined as the selected column index of the codebook $\mathcal{W}$, i.e., $\mathbf{w}_t=[\mathcal{W}]_{\mu_t}$. Furthermore, an feedback flag $f_g^t$ is introduced to mark the effectiveness of the previous action, expressed as
\begin{equation}
    f_g^t = 
    \begin{cases}
        0, &t = 0,\\
        \operatorname{sgn}\left(\left({P}_D^t-{P}_D^{t-1}\right) \cdot a_t\right), &t \ge 1,
    \end{cases}
\end{equation}
where $\operatorname{sgn}\left(\cdot\right)$ is the sign function, $a_t$ is the action operated at $t$-th stage. Consequently, the state vector at $t$-th stage is mathematically defined as $\mathbf{s}_t \buildrel\textstyle.\over=[\mu_t, {P}_D^t,f_g^t]^\mathrm{T}$.

\subsubsection{Action}
The action is defined as the change in the beam codeword index $a_t=\Delta\mu_t\in\{-\tau_\mu,\ldots,-1,1,\ldots,\tau_\mu\}$. This implies that the agent selects a column by either advancing or retreating within a maximum predefined range $\{-\tau_\mu,\tau_\mu\}$.

\subsubsection{Reward}
Since our goal is to minimize the total number of tracking steps for the agent accomplishing the target sensing task, we consider the term `$-1$' as the reward to penalize the agent to finish the task as soon as possible. Maximizing the cumulative reward is equivalent to minimizing the tracking steps. Therefore, the reward function is designed as follows:
\begin{equation}
r_t = \begin{cases}
            -1, & {P}_D(t) < {\zeta}, \\
		b_0, & \text { otherwise},\end{cases}\label{reward_ori}
\end{equation}
where a positive reward $b_0 > 0$ is designed to indicate the accomplishment of the target sensing task. This achievement is a constant for any policy, thus, does not influence the optimality of the optimization problem. 

\subsubsection{State Transition Probability}
$p(\mathbf{s}_{t+1}|\mathbf{s}_t,a_t)$ represents the transition probability from state $\mathbf{s}_t$ to state $\mathbf{s}_{t+1}$ after executing action $a_t$. Particularly, the transitions the beam codeword index $\mu_t \to \mu_{t+1}$ and the feedback flag $f_g^t \to f_g^{t+1}$ are deterministic. The transition of the detection probability $P_D^t \to P_D^{t+1}$ is influenced by stochastic factors, including AWGN, the estimation errors in $\{\hat{\gamma}_n\}_{n=1}^N$, and the mobility of the target.


\subsection{Reward Shaping}
\begin{figure}[t]
    \centering
    \includegraphics[width=2in]{Figures/list_pd}
    \caption{The CDF curve of detection probability.}
    \label{CDF of Pd}
\end{figure}
As illustrated by the CDF curve in Fig. \ref{CDF of Pd}, most beam codewords fail to detect the target, with only a few satisfying the detection performance criteria. Thus, the designed reward function in \eqref{reward_ori} closely aligns with the optimization objective, however, is severely sparse, exhibiting a flat landscape at $-1$ with a single peak at $b_0$ when the goal is achieved. Such a situation will require the agent to spend a significant amount of time on exploration.

Reward shaping \cite{ng1999policy} is defined as the addition of an extra reward signal that encodes some heuristic knowledge of the system  designer or domain expert, addressing the reward sparsity problem.

\begin{proposition}
The optimality is guaranteed if and only if the introduced shaping reward is a potential-based shaping function in terms of anteroposterior states. In this work, we define the shaping reward for transition from $\mathbf{s}_t$ to $\mathbf{s}_{t+1}$ as
\begin{equation}
    r_t^\mathrm{sh} = \rho \Phi(\mathbf{s}_{t+1}) - \Phi(\mathbf{s}_{t}),
\end{equation}
where $\rho$ is the discount factor, and the potential-based function
\begin{equation}
    \Phi(\mathbf{s}_{t}) = \frac{b_1}{1 + e^{-b_2 \cdot {P}_D(t)}}
\end{equation}
is designed only related to the current state. Sigmoid function is employed to emphasize slight variations in low values of ${P}_D(t)$. 
\end{proposition}
The reward function after applying the reward shaping can be expressed as $r_t + r_t^\mathrm{sh}$, which physically means that we encourage the agent to increase the detection probability as much as possible. Reward shaping is proposed in this paper as a way to \textbf{speed up learning and make the agent gain better knowledge of the ISAC environment}. 

Consequently, our objective is to maximize the cumulative reward across all stages, expressed as $\sum_t (r_t+r_t^\text{sh})$. While DRL lacks explicit knowledge of the mathematical relationship between the beamforming vector and the target detection probability, it effectively optimizes the beam tracking strategy through iterative interactions with the environment.


\subsection{Online Deep Reinforcement Learning-Based Beamforming}
The action-value function of the agent executing action $a_t$ at state $\mathbf{s}_t$ is defined as
\begin{equation}
    Q(\mathbf{s}_t, a_t; \theta_q) \buildrel\textstyle.\over = \mathbb{E} \left[\sum_{t'=0}^{\infty}  \rho^{t'}r_{t'}|\mathbf{s}_{0}=\mathbf{s}_{t}, a_{0}=a_t; \theta_q\right],
\end{equation}
which represents the expected long-term cumulative reward achievable under current policy characterized by the trainable parameters of the Q-network $\theta_q$. The purpose of our algorithm is to learn a policy that obtains the maximum action-value function. Subsequently, the designs of the Q-network structure and the interactive process are demonstrated as follows.

\subsubsection{Q-Network Structure}
The network design is demonstrated in Fig \ref{GAN-DQN-Network}. Specifically, for its input, to enable the column index value to serve as learnable parameters during training, we transform them into a sinusoidal embedding $\boldsymbol{\mu}_t = [\bar{\mu}_{t,1}, \ldots, \bar{\mu}_{t,I}]^\mathrm{T} \in \mathbb{R}^{I\times 1}$ using sine and cosine functions with varying frequencies, inspired by the transformer model \cite{vaswani2017attention}, yielding
\begin{equation}\label{sinusoidal}
    \bar{\mu}_{t,2i}=\sin\left(\frac{\mu_t}{1000^{\frac{2i}{I}}}\right), \quad
    \bar{\mu}_{t,2i-1}=\cos\left(\frac{\mu_t}{1000^{\frac{2i}{I}}}\right),
\end{equation}
where $I$ represents the total dimensions, allowing for a more effective representation of the index value in the neural network. By mapping these discrete indices into a continuous embedding space, the model can better capture and leverage the underlying relationships between indices during training. Additionally, to emphasize changes in $P_D^t$ when its value is relatively low, a variant sigmoid function is employed as follows
\begin{equation}
    \bar{P}_D^t = \sigma_v(P_D^t) \buildrel\textstyle.\over= \frac{\frac{1}{1 + e^{-b_3 \cdot {P}_D^t}} - \frac{1}{2}} {\frac{1}{1 + e^{-b_3}} - \frac{1}{2}}.
\end{equation}
This design guarantees a continuous mapping of values within $[0,1]$ to the same range, while significantly enhancing the sensitivity of the network to capture subtle variations in ${P}_D^t$ around $0$.

As for the output, a dueling network structure is used to split the Q-value into two components: a value function $U(\mathbf{s}_t)$ representing how good the state is, and an advantage function $A(\mathbf{s}_t, a_t)$ representing how much better an action is compared to others in that state. Its mathematical representation is  \cite{wang2016dueling} 
\begin{equation}
 Q(\mathbf{s}_t,a_t)=U(\mathbf{s}_t)+A(\mathbf{s}_t,a_t)-\max_{a} A(\mathbf{s}_t,a),
 \end{equation}
which allows the network to separately estimate the value of being in a state and the relative advantages of each action, helping improve learning efficiency, especially in states where multiple actions have similar Q-values.
\subsubsection{Interactive Process}
In this work, we employ the double DQN (DDQN) framework to mitigate the overestimation bias commonly encountered in standard value-based DRL policy when estimating Q-values, which decouples the action selection from Q-value estimation. To be exact, for a given state $\mathbf{s}_t$, the target for the Q-value is computed as
\begin{equation}
    V_t=r_{t}+\rho Q^{-}\left(\mathbf{s}_{t+1}, \arg \max _{a} Q\left(\mathbf{s}_{t+1}, a; \theta_q\right); \theta^{-}_q\right),
\end{equation}
where $Q^-(\cdot)$ is the target Q-value computed using the target network $Q^-$ with parameters $\theta^-_q$. $Q(\cdot)$ represents the Q-value function for the next state $\mathbf{s}_{t+1}$ and action $a$, computed using the current network. Consequently, the loss function in Dueling DDQN is defined as the mean squared error (MSE) between the predicted and target Q-values:
\begin{equation}\label{Q loss}
    \mathcal{L}_Q=\mathbb{E}\left[\left(V_t-Q(\mathbf{s}_t,a_t;\theta_q)\right)^2\right].
\end{equation}

However, such trial-and-error method often requires a lot of interaction costs. As a result, we introduce offline DRL and enhance the training efficiency by employing the digital twin technique.

