\section{Preliminaries}

\subsection{Basic Concepts}
In this section, we recall several fundamental definitions and constructions that will be used throughout the paper.

\begin{definition}[Category]
A \emph{category} $\mathcal{C}$ consists of:
\begin{enumerate}
    \item A class of objects $\operatorname{Ob}(\mathcal{C})$.
    \item For any two objects $A,B\in\operatorname{Ob}(\mathcal{C})$, a set of morphisms $\operatorname{Hom}_\mathcal{C}(A,B)$.
    \item For any three objects $A,B,C\in\operatorname{Ob}(\mathcal{C})$, a composition law
    \[
    \circ \colon \operatorname{Hom}_\mathcal{C}(B,C) \times \operatorname{Hom}_\mathcal{C}(A,B) \to \operatorname{Hom}_\mathcal{C}(A,C)
    \]
    which is associative.
    \item For each object $A\in\operatorname{Ob}(\mathcal{C})$, an identity morphism $\operatorname{id}_A\in\operatorname{Hom}_\mathcal{C}(A,A)$ such that for every $f\in\operatorname{Hom}_\mathcal{C}(A,B)$, one has
    \[
    \operatorname{id}_B \circ f = f \quad \text{and} \quad f\circ\operatorname{id}_A = f.
    \]
\end{enumerate}
\end{definition}

\begin{definition}[Cartesian Closed Category]
A category $\mathcal{C}$ is said to be \emph{Cartesian closed} if it satisfies the following:
\begin{enumerate}
    \item There exists a terminal object $1$ in $\mathcal{C}$.
    \item For any two objects $A$ and $B$ in $\mathcal{C}$, there exists a product $A \times B$.
    \item For any two objects $A$ and $B$ in $\mathcal{C}$, there exists an \emph{exponential object} $B^A$ together with an evaluation morphism
    \[
    \operatorname{ev}\colon B^A \times A \to B,
    \]
    satisfying the following universal property: For any object $C$ and any morphism $f\colon C \times A \to B$, there exists a unique morphism $\Lambda f\colon C \to B^A$ such that the diagram
    \[
    \begin{array}{c}
    \xymatrix{
    C \times A \ar[r]^{f} \ar[d]_{\Lambda f \times \operatorname{id}_A} & B\\
    B^A \times A \ar[ur]_{\operatorname{ev}} & 
    }
    \end{array}
    \]
    commutes.
\end{enumerate}
\end{definition}

\begin{definition}[First-Order Theory]
A \emph{first-order theory} $T$ consists of:
\begin{enumerate}
    \item A \emph{signature} $\Sigma$, which comprises a set of constant symbols, function symbols, and predicate symbols.
    \item A set of axioms (sentences) expressed in the language determined by $\Sigma$.
\end{enumerate}
\end{definition}

\begin{definition}[Model of a First-Order Theory]
Given a first-order theory $T$ with signature $\Sigma$, a \emph{model} $\mathcal{M}$ of $T$ is a structure
\[
\mathcal{M} = \bigl(M, \{ f^{\mathcal{M}} \}_{f \in \Sigma_f}, \{ P^{\mathcal{M}} \}_{P \in \Sigma_P}\bigr),
\]
where:
\begin{enumerate}
    \item $M$ is a non-empty set, called the \emph{domain} of the model.
    \item For each function symbol $f \in \Sigma_f$, the interpretation $f^{\mathcal{M}}$ is a function on $M$ of appropriate arity.
    \item For each predicate symbol $P \in \Sigma_P$, the interpretation $P^{\mathcal{M}}$ is a relation on $M$.
    \item The structure $\mathcal{M}$ satisfies all axioms of $T$, that is, every sentence in $T$ is true in $\mathcal{M}$.
\end{enumerate}
\end{definition}


\subsection{Categories of Theories and Models}

In this section, we define two fundamental categories that will be used throughout the paper: the category of first-order theories, denoted by $\mathbf{Th}$, and the category of models, denoted by $\mathbf{Mod}$.

\begin{definition}[Category of Theories, $\mathbf{Th}$]
The category $\mathbf{Th}$ is defined as follows:
\begin{enumerate}
    \item \textbf{Objects:} An object in $\mathbf{Th}$ is a first-order theory, which we formalize as a pair $(\Sigma, T)$ where $\Sigma$ is a signature (a collection of constant, function, and predicate symbols) and $T$ is a set of sentences (axioms) in the language $L_{\Sigma}$.
    \item \textbf{Morphisms:} Given two theories $T = (\Sigma, T)$ and $T' = (\Sigma', T')$, a \emph{theory translation} (or interpretation) $\phi \colon T \to T'$ is a mapping that assigns to each symbol in $\Sigma$ a corresponding symbol in $\Sigma'$ in such a way that the translation preserves the logical structure. In particular, if $\varphi$ is a sentence in $L_{\Sigma}$ and $T \vdash \varphi$, then the translated sentence $\phi(\varphi)$ in $L_{\Sigma'}$ must satisfy $T' \vdash \phi(\varphi)$. Composition of translations and the identity translation are defined in the obvious way, thereby endowing $\mathbf{Th}$ with the structure of a category.
\end{enumerate}
\end{definition}

\begin{definition}[Category of Models, $\mathbf{Mod}$]
The category $\mathbf{Mod}$ is defined as follows:
\begin{enumerate}
    \item \textbf{Objects:} An object in $\mathbf{Mod}$ is a model $\mathcal{M}$ of a first-order theory. Concretely, if $T$ is a theory with signature $\Sigma$, then a model $\mathcal{M}$ is a structure
    \[
    \mathcal{M} = \bigl(M, \{ f^{\mathcal{M}} \}_{f \in \Sigma_f}, \{ P^{\mathcal{M}} \}_{P \in \Sigma_P}\bigr),
    \]
    where $M$ is a nonempty set (the domain), and for each function symbol $f \in \Sigma_f$ and predicate symbol $P \in \Sigma_P$, the interpretations $f^{\mathcal{M}}$ and $P^{\mathcal{M}}$ are assigned appropriately such that $\mathcal{M}$ satisfies every sentence in $T$.
    \item \textbf{Morphisms:} Given two models $\mathcal{M}$ and $\mathcal{N}$ of the same theory $T$, a \emph{model homomorphism} is a function $h \colon M \to N$ satisfying:
    \begin{itemize}[leftmargin=2em]
        \item For every function symbol $f \in \Sigma_f$ and all $a_1,\dots,a_n \in M$, 
        \[
        h\bigl(f^{\mathcal{M}}(a_1,\dots,a_n)\bigr) = f^{\mathcal{N}}\bigl(h(a_1),\dots,h(a_n)\bigr).
        \]
        \item For every predicate symbol $P \in \Sigma_P$ and all $a_1,\dots,a_n \in M$, if $(a_1,\dots,a_n) \in P^{\mathcal{M}}$, then 
        \[
        \bigl(h(a_1),\dots,h(a_n)\bigr) \in P^{\mathcal{N}}.
        \]
    \end{itemize}
    Composition of model homomorphisms and identity maps are defined in the standard manner, giving $\mathbf{Mod}$ the structure of a category.
\end{enumerate}
\end{definition}


\subsection{Existing Construction Methods}

In this section, we review two fundamental methods that underpin our work: the Henkin construction, which plays a central role in the proof-theoretic approach to the Completeness Theorem, and Lawvere's Fixed-Point Theorem, a categorical formulation that captures the essence of self-reference and diagonalization.

\begin{itemize}[leftmargin=2em]
    \item \textbf{The Henkin Construction:}
    \begin{itemize}[leftmargin=2em]
        \item \emph{Overview:} The Henkin construction is a classical proof-theoretic technique used to prove the Completeness Theorem for first-order logic.
        \item \emph{Key Steps:}
        \begin{enumerate}[leftmargin=2em]
            \item \textbf{Extension of the Theory:} Given a consistent first-order theory $T$, extend the language by adding a new constant (Henkin constant) for every existential formula. This yields an extended theory $T^*$.
            \item \textbf{Maximal Consistency:} Extend $T^*$ to a maximal consistent theory so that for every formula $\varphi$, either $\varphi$ or its negation is provable.
            \item \textbf{Term Model Construction:} Define the term model by considering the set of all terms in the extended language, modulo the equivalence relation induced by provable equality in $T^*$. That is, the model is given by
            \[
            F(T) := \mathrm{Term}(T^*)/\sim_T,
            \]
            where $t \sim_T s$ if and only if $T^* \vdash t = s$.
        \end{enumerate}
        \item \emph{Proof-Theoretic Background:} This method relies on ensuring that every existential statement in $T$ is witnessed in the extended theory $T^*$, thus guaranteeing that the constructed model satisfies all sentences of the theory.
    \end{itemize}

    \item \textbf{Lawvere's Fixed-Point Theorem:}
    \begin{itemize}[leftmargin=2em]
        \item \emph{Formal Statement:} Let $\mathcal{C}$ be a Cartesian closed category and let $Y$ be an object in $\mathcal{C}$. Suppose that for some object $X$ there exists a morphism
        \[
        \operatorname{ev} \colon Y^X \times X \to Y
        \]
        (the evaluation map). Then, for every endomorphism $f\colon Y \to Y$, there exists a morphism $d\colon 1 \to Y^X$ such that the composite
        \[
        \xymatrix{
        1 \ar[r]^{d} & Y^X \ar[r]^{\operatorname{ev}} & Y
        }
        \]
        yields a fixed point of $f$, i.e., $f(y) = y$ for $y = \operatorname{ev}(d(1), x)$ for an appropriate choice of $x \in X$.
        \item \emph{Discussion:}
        \begin{itemize}[leftmargin=2em]
            \item The theorem generalizes the classical diagonal argument and demonstrates that the structure of Cartesian closed categories naturally gives rise to fixed points.
            \item The existence of the exponential object $Y^X$ and the universal property of the evaluation map are crucial for the construction of such fixed points.
            \item This result encapsulates the self-referential (diagonal) nature of certain constructions in logic, bridging the gap between syntactic self-reference and semantic fixed points.
        \end{itemize}
    \end{itemize}
\end{itemize}


\subsection{Notation and Conventions}

In this paper, we adopt the following notation and conventions:

\begin{itemize}[leftmargin=2em]
    \item \textbf{Theories and Their Henkin Expansions:}
    \begin{itemize}[leftmargin=2em]
        \item Let $T$ denote a first-order theory, consisting of a signature $\Sigma$ and a set of axioms written in the language $L_\Sigma$.
        \item The \emph{Henkin expansion} of $T$, denoted by $T^*$, is obtained by augmenting the language $L_\Sigma$ with a new constant symbol (a \emph{Henkin constant}) for each existential formula of $T$. This expansion ensures that every existential statement has a corresponding witness in the extended theory.
    \end{itemize}

    \item \textbf{Term Algebra and Equivalence Relation:}
    \begin{itemize}[leftmargin=2em]
        \item The set of all terms in the extended language (of $T^*$) is denoted by $\mathrm{Term}(T^*)$.
        \item An equivalence relation $\sim_T$ is defined on $\mathrm{Term}(T^*)$ by declaring that for terms $t,s \in \mathrm{Term}(T^*)$, 
        \[
        t \sim_T s \quad \text{if and only if} \quad T^* \vdash t = s.
        \]
        \item The \emph{term model} associated with $T$ is then given by the quotient
        \[
        F(T) := \mathrm{Term}(T^*)/\sim_T.
        \]
    \end{itemize}

    \item \textbf{Functors $F$ and $G$:}
    \begin{itemize}[leftmargin=2em]
        \item The functor
        \[
        F \colon \mathbf{Th} \to \mathbf{Mod}
        \]
        assigns to each theory $T \in \mathbf{Th}$ the term model $F(T)$ constructed via the Henkin expansion and quotienting by $\sim_T$. On morphisms, $F$ acts by translating terms according to the given theory translation.
        \item The functor
        \[
        G \colon \mathbf{Th} \to \mathbf{Mod}
        \]
        assigns to each theory $T$ a model $G(T)$ obtained via alternative methods (e.g., using the Compactness Theorem, ultraproducts, or saturation techniques). It is assumed that $G(T)$ is unique up to isomorphism. On morphisms, $G$ is defined in a manner that is compatible with the semantic interpretations of the theories.
    \end{itemize}
\end{itemize}


