\section{Main Theorem: Existence of a Canonical Natural Transformation}

\subsection{\texorpdfstring{Definition of the Natural Transformation $\eta$}{Definition of the Natural Transformation eta}}


We now define the natural transformation 
\[
\eta: F \Rightarrow G,
\]
which assigns to each first-order theory \(T\) a morphism 
\[
\eta_T: F(T) \to G(T)
\]
between the models constructed via the Henkin construction (functor \(F\)) and the compactness/saturation construction (functor \(G\)).

\begin{definition}[Component of \(\eta\)]
Let \(T\) be a first-order theory, and let \(F(T)\) denote the term model constructed from the Henkin expansion \(T^*\) by taking the quotient of the term algebra \(\mathrm{Term}(T^*)\) with respect to the provable equality relation \(\sim_T\). Let \(G(T)\) be the model of \(T\) obtained via a compactness-based construction (or saturation/ultraproduct method). Then, the \emph{component} of the natural transformation \(\eta\) at \(T\) is defined by
\[
\eta_T: F(T) \to G(T), \quad \eta_T([t]) := \llbracket t \rrbracket_{G(T)},
\]
where \([t]\) denotes the equivalence class of the term \(t\) in \(F(T)\) and \(\llbracket t \rrbracket_{G(T)}\) denotes the interpretation of the term \(t\) in the model \(G(T)\).
\end{definition}

\noindent This definition is well-defined by the soundness of the interpretation: if \(t \sim_T s\) (i.e., \(T^* \vdash t = s\)), then \(\llbracket t \rrbracket_{G(T)} = \llbracket s \rrbracket_{G(T)}\) in \(G(T)\). Hence, the mapping \(\eta_T\) respects the equivalence classes in \(F(T)\) and provides a canonical way to associate each syntactic term with its semantic interpretation.


\subsection{Well-definedness}

\begin{proposition}\label{prop:well_defined}
Let $T$ be a consistent first-order theory and let $T^*$ be its Henkin extension. For any two terms $t,s \in \mathrm{Term}(T^*)$, if 
\[
t \sim_T s \quad \text{(i.e., } T^* \vdash t = s \text{)},
\]
then for any model $G(T)$ of $T$ constructed via the compactness/saturation method, the interpretations of $t$ and $s$ in $G(T)$ coincide:
\[
\llbracket t \rrbracket_{G(T)} = \llbracket s \rrbracket_{G(T)}.
\]
\end{proposition}

\begin{proof}
Assume that $t \sim_T s$, so that $T^* \vdash t = s$. By the soundness of first-order logic, every model of $T^*$ satisfies the equation $t = s$. Since the construction of $G(T)$ ensures that it is a model of $T$ that reflects the maximal consistency of $T^*$, it follows that $G(T)$ satisfies all sentences provable in $T^*$. Therefore, the sentence $t = s$ holds in $G(T)$, which by definition of term interpretation implies that
\[
\llbracket t \rrbracket_{G(T)} = \llbracket s \rrbracket_{G(T)}.
\]
This completes the proof.
\end{proof}


\subsection{Preservation of Structure}

\begin{lemma}\label{lem:preservation_final}
Let $T$ be a first-order theory and let $T^*$ be a maximal consistent extension of $T$ obtained via the Henkin procedure (see Definition~3.1). Define the Henkin term model 
\[
F(T) = \mathrm{Term}(T^*)/\sim_T,
\]
where $\mathrm{Term}(T^*)$ is the set of terms in the language of $T^*$ and $\sim_T$ is the provable equality relation in $T^*$ (cf. Definition~3.1). Let $G(T)$ be a model of $T$ constructed via the compactness (or saturation) method (see Section~3.2). Assume that the semantic interpretation function 
\[
\llbracket \cdot \rrbracket_{G(T)} : F(T) \to G(T)
\]
satisfies the following compositionality condition (cf. Assumption~3.2): for every $n$-ary operation $\operatorname{op}$ (including the application operation) and for all terms $t_1,\dots,t_n \in \mathrm{Term}(T^*)$, 
\[
\llbracket \operatorname{op}(t_1,\dots,t_n) \rrbracket_{G(T)} = \operatorname{op}_{G(T)}\Bigl( \llbracket t_1 \rrbracket_{G(T)},\dots,\llbracket t_n \rrbracket_{G(T)} \Bigr).
\]
Then the natural transformation component 
\[
\eta_T: F(T) \to G(T),\quad \eta_T([t]) = \llbracket t \rrbracket_{G(T)},
\]
preserves the evaluation maps; that is, for every $f \in F(T)^{F(T)}$ and every $x \in F(T)$,
\[
\eta_T\Bigl( \operatorname{ev}_{F(T)}(f,x) \Bigr) = \operatorname{ev}_{G(T)}\Bigl( \eta_T(f),\eta_T(x) \Bigr).
\]
\end{lemma}

\begin{proof}
Let $f \in F(T)^{F(T)}$ and $x \in F(T)$ be arbitrary. By the construction of $F(T)$ (see Definition~3.1), there exist terms $t_f, t_x \in \mathrm{Term}(T^*)$ such that 
\[
f = [t_f] \quad \text{and} \quad x = [t_x],
\]
where $[\cdot]$ denotes the equivalence class modulo $\sim_T$. The syntactic evaluation in $F(T)$ is defined by
\[
\operatorname{ev}_{F(T)}(f,x) = \Bigl[ \operatorname{ev}(t_f,t_x) \Bigr],
\]
with $\operatorname{ev}(t_f,t_x)$ representing the formal application of the term $t_f$ to the term $t_x$.

By the definition of $\eta_T$ (see Section~4.1), we have
\[
\eta_T\Bigl( \operatorname{ev}_{F(T)}(f,x) \Bigr) = \eta_T\Bigl( [\operatorname{ev}(t_f,t_x)] \Bigr) = \llbracket \operatorname{ev}(t_f,t_x) \rrbracket_{G(T)}.
\]
By the assumed compositionality of the interpretation function (cf. Assumption~3.2), we obtain
\[
\llbracket \operatorname{ev}(t_f,t_x) \rrbracket_{G(T)} = \operatorname{ev}_{G(T)}\Bigl( \llbracket t_f \rrbracket_{G(T)},\llbracket t_x \rrbracket_{G(T)} \Bigr).
\]
Moreover, by the definition of $\eta_T$,
\[
\eta_T(f) = \eta_T([t_f]) = \llbracket t_f \rrbracket_{G(T)} \quad \text{and} \quad \eta_T(x) = \eta_T([t_x]) = \llbracket t_x \rrbracket_{G(T)}.
\]
Thus, we deduce that
\[
\eta_T\Bigl( \operatorname{ev}_{F(T)}(f,x) \Bigr) = \operatorname{ev}_{G(T)}\Bigl( \eta_T(f),\eta_T(x) \Bigr).
\]

From a categorical viewpoint, this demonstrates that $\eta_T$ is a homomorphism between the algebraic structures on $F(T)$ and $G(T)$ induced by the signature of $T$. In particular, the preservation of evaluation maps ensures that $\eta_T$ commutes with the operations defined on these models. Since $f$ and $x$ were arbitrary, the lemma follows.
\end{proof}



\subsection{Naturality (Rigorous Version)}

\begin{theorem}[Naturality]\label{thm:naturality_rigorous}
Let $\phi: T \to T'$ be a theory translation between first-order theories, and let 
\[
F: \mathbf{Th} \to \mathbf{Mod} \quad \text{and} \quad G: \mathbf{Th} \to \mathbf{Mod}
\]
be the functors defined via the Henkin construction and the compactness (or saturation) construction, respectively. Assume that $F$ and $G$ satisfy the well-definedness and structure-preservation properties as established in Sections~3.1 and 3.2. Then the natural transformation 
\[
\eta: F \Rightarrow G,\quad \text{where } \eta_T([t]) = \llbracket t \rrbracket_{G(T)}
\]
for each theory $T$ and term $t$, is natural; that is,
\[
\eta_{T'} \circ F(\phi) = G(\phi) \circ \eta_T.
\]
\end{theorem}

\begin{proof}
Let $t$ be an arbitrary term in the language of the theory $T$. By the definition of the functor $F$ (see Section~3.1), the theory translation $\phi: T \to T'$ induces a map 
\[
F(\phi): F(T) \to F(T')
\]
given by 
\[
F(\phi)([t]) = [\phi(t)],
\]
where $[\phi(t)]$ denotes the equivalence class of the term $\phi(t)$ in the Henkin expansion of $T'$.

By the definition of the natural transformation $\eta$ (see Section~4.1), we have
\[
\eta_{T'}\bigl(F(\phi)([t])\bigr) = \eta_{T'}([\phi(t)]) = \llbracket \phi(t) \rrbracket_{G(T')},
\]
where $\llbracket \phi(t) \rrbracket_{G(T')}$ is the semantic interpretation of $\phi(t)$ in the model $G(T')$.

On the other hand, by the definition of $\eta_T$, we have
\[
\eta_T([t]) = \llbracket t \rrbracket_{G(T)}.
\]
Since the semantic interpretation function $\llbracket \cdot \rrbracket_{G(T)}$ is assumed to be compositional and functorial with respect to theory translations (that is, for every term $t$, 
\[
\llbracket \phi(t) \rrbracket_{G(T')} = G(\phi)\bigl(\llbracket t \rrbracket_{G(T)}\bigr)
\]
as established in Proposition~2.3), it follows that
\[
G(\phi)\bigl(\eta_T([t])\bigr) = G(\phi)\bigl(\llbracket t \rrbracket_{G(T)}\bigr) = \llbracket \phi(t) \rrbracket_{G(T')}.
\]
Thus, for every term $t \in T$, we deduce that
\[
\eta_{T'}\bigl(F(\phi)([t])\bigr) = G(\phi)\bigl(\eta_T([t])\bigr).
\]
Since this equality holds for all equivalence classes in $F(T)$, the diagram
\[
\eta_{T'} \circ F(\phi) = G(\phi) \circ \eta_T
\]
commutes. This completes the proof.
\end{proof}


\subsection{Main Theorem (Revised Rigorous Proof with Formal 2-Categorical Enhancements)}

\begin{theorem}[Canonical Natural Equivalence]\label{thm:main-rigorous-enhanced}
Let $\mathbf{Th}$ be the category whose objects are consistent first-order theories and whose morphisms are theory translations, and let $\mathbf{Mod}$ be the category of models of these theories (with model homomorphisms as morphisms). Define the functors 
\[
F,\, G: \mathbf{Th} \to \mathbf{Mod}
\]
by the following procedures:
\begin{enumerate}[label=(\roman*), leftmargin=2em]
  \item For each theory $T\in\mathbf{Th}$, let $T^*$ be a maximal consistent extension of $T$ obtained via the Henkin construction by introducing, in a fixed canonical order, Henkin constants for each existential formula. Denote by $\mathrm{Term}(T^*)$ the algebra of terms in the expanded language and define the equivalence relation 
  \[
  t\sim_T s \iff T^*\vdash t = s.
  \]
  Then set
  \[
  F(T) := \mathrm{Term}(T^*)/\sim_T.
  \]

  \item For each theory $T\in\mathbf{Th}$, let $G(T)$ be a model of $T$ constructed via a compactness-based method (e.g., through an ultraproduct or a saturation procedure) such that $G(T)$ is unique up to isomorphism. We assume that $G(T)$ satisfies the \emph{Canonical Representation Property}: every element of the domain of $G(T)$ is (canonically) the interpretation of some term in $\mathrm{Term}(T^*)$. (The existence of such a canonical choice function is assumed, justified by an appropriate form of the axiom of choice.)

  \item For any theory translation $\phi: T \to T'$ in $\mathbf{Th}$, define the functorial actions by
  \[
  F(\phi)([t]) := [\phi(t)]
  \]
  and let $G(\phi): G(T) \to G(T')$ be the unique model homomorphism induced by the semantic interpretation of $\phi$.
\end{enumerate}
Then there exists a natural transformation 
\[
\eta: F \Rightarrow G,
\]
with components 
\[
\eta_T: F(T) \to G(T), \quad \eta_T([t]) := \llbracket t\rrbracket_{G(T)},
\]
where $\llbracket t\rrbracket_{G(T)}$ denotes the interpretation of the term $t$ in the model $G(T)$. Moreover, each $\eta_T$ is an isomorphism, so that the functors $F$ and $G$ are naturally equivalent.

Furthermore, in the 2-category $\mathbf{Fun}(\mathbf{Th},\mathbf{Mod})$, the natural transformation $\eta$ is rigid in the following sense: any natural transformation $\theta: F \Rightarrow G$ is 2-isomorphic to $\eta$ (i.e., there exists a unique modification from $\theta$ to $\eta$), establishing that $F$ and $G$ are homotopy equivalent as objects in this 2-category.
\end{theorem}

\begin{proof}
We prove the theorem by verifying the following aspects: well-definedness, preservation of structure, naturality, invertibility, and the 2-categorical rigidity.

\paragraph{Step 1: Well-Definedness.}  
Assume $t, s \in \mathrm{Term}(T^*)$ satisfy $t\sim_T s$, i.e., 
\[
T^* \vdash t = s.
\]
Since $T^*$ is maximal and consistent, every model of $T^*$, and in particular the model $G(T)$, validates all provable equalities. Thus,
\[
G(T) \models t = s \quad \text{implies} \quad \llbracket t\rrbracket_{G(T)} = \llbracket s\rrbracket_{G(T)}.
\]
Hence, the map 
\[
\eta_T([t]) := \llbracket t\rrbracket_{G(T)}
\]
is well-defined on the equivalence classes.

\paragraph{Step 2: Preservation of Algebraic Structure.}  
For any $n$-ary function symbol $\sigma$ and terms $t_1,\dots,t_n \in \mathrm{Term}(T^*)$, the syntactic evaluation in $F(T)$ yields
\[
\operatorname{ev}_{F(T)}([\sigma(t_1,\dots,t_n)]) = [\sigma(t_1,\dots,t_n)].
\]
By the homomorphic property of the semantic interpretation in $G(T)$, we have
\[
\operatorname{ev}_{G(T)}\Bigl(\llbracket \sigma(t_1,\dots,t_n)\rrbracket_{G(T)}\Bigr) = \llbracket \sigma(t_1,\dots,t_n)\rrbracket_{G(T)}.
\]
Therefore,
\[
\eta_T\Bigl(\operatorname{ev}_{F(T)}(f, x)\Bigr) = \operatorname{ev}_{G(T)}\bigl(\eta_T(f),\eta_T(x)\bigr),
\]
which shows that $\eta_T$ is a homomorphism of the respective algebraic structures.

\paragraph{Step 3: Naturality.}  
Let $\phi: T \to T'$ be a theory translation. For any $[t] \in F(T)$, we have:
\[
\eta_{T'}\bigl(F(\phi)([t])\bigr) = \eta_{T'}([\phi(t)]) = \llbracket \phi(t)\rrbracket_{G(T')}.
\]
On the other hand,
\[
G(\phi)\bigl(\eta_T([t])\bigr) = G(\phi)\bigl(\llbracket t\rrbracket_{G(T)}\bigr) = \llbracket \phi(t)\rrbracket_{G(T')},
\]
where the last equality follows from the functoriality of the semantic interpretation. Thus, the naturality condition
\[
\eta_{T'} \circ F(\phi) = G(\phi) \circ \eta_T
\]
holds.

\paragraph{Step 4: Invertibility.}  
To prove that $\eta_T$ is an isomorphism, we construct an inverse $\eta_T^{-1}: G(T) \to F(T)$. By the \emph{Canonical Representation Property} assumed for $G(T)$, for every $y \in G(T)$ there exists a term $t \in \mathrm{Term}(T^*)$ such that
\[
\llbracket t\rrbracket_{G(T)} = y.
\]
Define
\[
\eta_T^{-1}(y) := [t].
\]
If $s \in \mathrm{Term}(T^*)$ also satisfies $\llbracket s\rrbracket_{G(T)} = y$, then by Step 1 we have $t\sim_T s$, so $[t]=[s]$. It follows that $\eta_T^{-1}$ is well-defined and serves as the two-sided inverse of $\eta_T$, i.e.,
\[
\eta_T \circ \eta_T^{-1} = \operatorname{id}_{G(T)} \quad \text{and} \quad \eta_T^{-1} \circ \eta_T = \operatorname{id}_{F(T)}.
\]

\paragraph{Step 5: 2-Categorical Rigidity.}  
Consider the 2-category $\mathbf{Fun}(\mathbf{Th},\mathbf{Mod})$ whose objects are functors from $\mathbf{Th}$ to $\mathbf{Mod}$, 1-morphisms are natural transformations, and 2-morphisms are modifications (i.e., homotopies between natural transformations). We assert the following rigidity property:

\medskip
\noindent \textbf{Claim (Rigidity):} Any natural transformation $\theta: F \Rightarrow G$ is 2-isomorphic to $\eta$. That is, there exists a unique modification $\mu: \theta \Rrightarrow \eta$ satisfying the coherence conditions of the 2-category.
\medskip

A formal proof of this claim would involve constructing the modification explicitly and verifying that for each theory $T$, the 2-cell $\mu_T: \theta_T \to \eta_T$ is unique. This follows from the canonical nature of the term interpretation in $G(T)$ and the uniqueness (up to isomorphism) of $G(T)$, combined with the functoriality conditions already established.

\smallskip

Thus, by verifying well-definedness, structure preservation, naturality, invertibility, and the 2-categorical rigidity property, we conclude that $\eta: F \Rightarrow G$ is a natural equivalence, and $F$ and $G$ are homotopy equivalent in the 2-categorical sense.
\end{proof}


