\section*{Additional Results on 2-Categorical Rigidity and the Canonical Representation Property}

\begin{lemma}[Canonical Representation Property]
\label{lem:canonical-representation}
Let \(T\) be a consistent first-order theory, and let \(T^*\) be its maximal consistent extension obtained via Henkin’s method. Denote by \(\mathrm{Term}(T^*)\) the set of terms in the expanded language. Let
\[
t \sim_T s 
\;\Longleftrightarrow\; 
T^* \vdash t = s.
\]
Consider a model \(G(T)\) constructed by a compactness-based technique (such as ultraproducts or saturation), and assume the following:

\begin{quote}
\textbf{Canonical Representation Property:} For every \(y \in G(T)\), there is a term \(t \in \mathrm{Term}(T^*)\) such that
\[
\llbracket t \rrbracket_{G(T)} = y,
\]
and if \(\llbracket t \rrbracket_{G(T)} = \llbracket s \rrbracket_{G(T)}\), then \(t \sim_T s\).
\end{quote}

Under these conditions, \(G(T)\) is said to satisfy the Canonical Representation Property.
\end{lemma}

\begin{proposition}[2-Categorical Rigidity]
\label{prop:2cat-rigidity}
Let \(F, G: \mathbf{Th} \to \mathbf{Mod}\) be functors as defined in the main text. For any natural transformation \(\theta: F \Rightarrow G\), there is a unique modification (2-cell)
\[
\mu: \theta \Rrightarrow \eta
\]
such that, for each theory \(T\), the 2-cell \(\mu_T: \theta_T \to \eta_T\) is an isomorphism in \(\mathbf{Mod}\). Consequently, \(\theta\) is 2-isomorphic to the canonical natural transformation \(\eta\), implying that \(F\) and \(G\) are rigidly and strongly naturally equivalent in the 2-categorical sense.
\end{proposition}

\section*{Uniqueness of the Model Construction \texorpdfstring{\(G(T)\)}{}}

\begin{lemma}[Uniqueness of \(G(T)\)]
\label{lem:compactness-model}
If \(T\) is a first-order theory and \(G(T)\) is a model constructed by a compactness or saturation procedure (such as ultraproducts or via a saturation argument), then \(G(T)\) is unique up to isomorphism. That is, if \(M_1\) and \(M_2\) are two such models of \(T\), there exists an isomorphism
\[
\psi: M_1 \to M_2.
\]
\end{lemma}

\section*{2-Categorical Homotopy Equivalence of \texorpdfstring{\(F\)}{} and \texorpdfstring{\(G\)}{}}

\begin{lemma}[2-Categorical Homotopy Equivalence]
Let \(F, G : \mathbf{Th} \to \mathbf{Mod}\) be functors as introduced in the main text, and let
\[
\eta : F \Rightarrow G
\]
be the canonical natural transformation. Since each component \(\eta_T\) is an isomorphism, \(F\) and \(G\) are equivalent in the 2-category of categories (i.e.\ homotopy equivalent in the 2-categorical sense). In particular, for any natural transformation \(\theta: F \Rightarrow G\), there is a unique modification \(\mu: \theta \Rrightarrow \eta\) such that all coherence diagrams commute.
\end{lemma}

\section*{Detailed Statements and Supplementary Materials}

\begin{definition}[Henkin Construction]
\label{def:henkin-construction}
A \emph{Henkin Construction} for a theory \(T\) extends \(T\) to a maximally consistent theory \(T^*\) by adding witness constants for every existential formula. Let \(\mathrm{Term}(T^*)\) be the set of terms in the expanded language, and define
\[
t \sim_T s 
\;\Longleftrightarrow\; 
T^* \vdash t = s.
\]
Then the term model is given by
\[
F(T) \;=\; \mathrm{Term}(T^*) / \sim_T.
\]
\end{definition}

\begin{definition}[Compactness/Saturation Construction]
\label{def:compactness-construction}
A \emph{Compactness/Saturation Construction} uses methods such as the compactness theorem, saturation arguments, or ultrapowers to build a model of a first-order theory \(T\). It ensures that every existential statement is realized, yielding a model
\[
G(T),
\]
unique up to isomorphism under standard assumptions.
\end{definition}

\begin{lemma}[Equivalence Relation]
\label{lem:equiv-relation}
Let \(T^*\) be a maximally consistent extension of \(T\). Define
\[
t \sim_T s 
\;\Longleftrightarrow\; 
T^* \vdash t = s
\]
on \(\mathrm{Term}(T^*)\). Then \(\sim_T\) is an equivalence relation.
\end{lemma}

\begin{proposition}
\label{prop:eta-isomorphism}
Let \(F\) and \(G\) be the functors obtained via the Henkin Construction and the Compactness/Saturation Construction, respectively. Under appropriate consistency and rigidity assumptions, the canonical natural transformation
\[
\eta_T : F(T) \to G(T), 
\quad 
\eta_T([t]) = \llbracket t \rrbracket_{G(T)},
\]
is an isomorphism.
\end{proposition}

\section*{Technical Lemmas and Propositions}

\begin{lemma}[Well-Definedness of \(\eta_T\)]
\label{lem:eta_well_defined}
For any theory \(T\) and any terms \(t, s\) such that \(t \sim_T s\), 
\[
\llbracket t \rrbracket_{G(T)} = \llbracket s \rrbracket_{G(T)}.
\]
Hence,
\[
\eta_T([t]) := \llbracket t \rrbracket_{G(T)}
\]
is well-defined.
\end{lemma}

\begin{proposition}[Compatibility with the Evaluation Map]
\label{prop:evaluation_compatibility}
For any \(f, x \in F(T)\),
\[
\eta_T\bigl(\mathrm{ev}_{F(T)}(f,x)\bigr) 
\;=\; 
\mathrm{ev}_{G(T)}\bigl(\eta_T(f), \eta_T(x)\bigr).
\]
Thus, \(\eta_T\) commutes with evaluation.
\end{proposition}

\begin{lemma}[Naturality]
\label{lem:eta_naturality}
For any theory translation \(\phi: T \to T'\),
\[
\eta_{T'} \circ F(\phi) = G(\phi) \circ \eta_T.
\]
\end{lemma}

\begin{proposition}[Rigidity of the Natural Transformation]
\label{prop:eta_rigidity}
The natural transformation \(\eta: F \Rightarrow G\) is rigid. In other words, for any natural transformation \(\theta: F \Rightarrow G\), we have \(\theta = \eta\).
\end{proposition}

\section*{Concrete Examples}

\begin{example}[Kripke Semantics for Modal Logics]
\label{ex:kripke-modal}
For a modal theory \(T\) interpreted over a Kripke frame \(\mathcal{F}=(W,R)\), the model \(G(T)\) assigns truth values to modal formulas at each possible world \(w \in W\). Meanwhile, the Henkin construction \(F(T)\) introduces additional constants to witness each modal operator. The natural transformation
\[
\eta_T([t]) := \llbracket t \rrbracket_{G(T)}
\]
ensures that if two terms are equivalent under \(\sim_T\), then their Kripke interpretations coincide.
\end{example}

\begin{example}[Henkin Construction for Arithmetic Theories]
\label{ex:henkin-arithmetic}
For a consistent arithmetic theory \(T\) (e.g.\ Peano Arithmetic), the Henkin construction produces a maximally consistent extension \(T^*\) by introducing new constants for each existential formula. The model \(F(T)\) is the quotient 
\[
\mathrm{Term}(T^*) / \sim_T,
\]
while \(G(T)\) is obtained via saturation or ultrapower arguments. The map
\[
\eta_T([t]) := \llbracket t \rrbracket_{G(T)}
\]
provides an isomorphism between the syntactic term model and the semantic model.
\end{example}

\section*{Supplementary Remarks}

\begin{remark}[Quasi-Categories]
\label{rem:quasicat}
A \emph{quasi-category} is a simplicial set satisfying the weak Kan condition, serving as a model for \((\infty,1)\)-categories. While the present work focuses on 2-categorical structures, the quasi-categorical framework can capture higher homotopical data and more general notions of equivalence.
\end{remark}

\begin{remark}[Interplay Between Syntax and Semantics]
\label{rem:syntax-semantics}
The Henkin construction (syntactic) and the compactness/saturation construction (semantic) are closely intertwined in first-order logic. The natural transformation \(\eta\) reflects this interplay by ensuring a categorical equivalence between syntactic and semantic models in a precise manner. 
\end{remark}

\section{Models of ZF}
\label{sec:zf-models}

In this section, we provide a detailed exposition of the construction of a model of Zermelo-Fraenkel Set Theory (ZF) via compactness and saturation techniques. The construction follows these key steps:

\begin{enumerate}[leftmargin=2em]
    \item \textbf{Consistency and Compactness:}  
    We start with the assumption that ZF is consistent. By the Compactness Theorem, every finitely satisfiable set of ZF sentences is satisfiable. This guarantees the existence of models that satisfy all finite subsets of ZF.

    \item \textbf{Ultraproduct/Saturation Method:}  
    One standard approach to construct a model of ZF is via the ultrapower construction. Alternatively, one may obtain a $\kappa$-saturated model through a saturation argument, where $\kappa$ is a sufficiently large cardinal. Both methods yield a model, denoted by $G(\mathrm{ZF})$, which satisfies every axiom of ZF.

    \item \textbf{Uniqueness up to Isomorphism:}  
    Under standard set-theoretic assumptions (including the Axiom of Choice), the model $G(\mathrm{ZF})$ is unique up to isomorphism. That is, any two models constructed by these methods are isomorphic.

    \item \textbf{Canonical Representation:}  
    In the context of our unified framework, $G(\mathrm{ZF})$ is assumed to satisfy the Canonical Representation Property. This means that every element in the domain of $G(\mathrm{ZF})$ is the semantic interpretation of some term in the extended language of ZF. This property is crucial for establishing the natural isomorphism between the syntactic and semantic models.
\end{enumerate}

The construction detailed above provides the necessary and sufficient framework for obtaining a model of ZF, which plays a vital role in illustrating the correspondence between syntactic constructions (via the Henkin method) and semantic models (via compactness and saturation).



