\section{Preliminaries and Notation}\label{PreLim}


\subsection{Banach Spaces and Operator algebras}

We remind the reader that a \textit{Banach space} is a 
complex vector space $E$ equipped with a norm $\|-\|_E$ that makes $E$ 
a complete metric space. 
If $E$ is a Banach space, we will denote its closed unit ball by 
$\B(E)$, that is
\[
\B(E) = \{ \xi \in E \colon \| \xi\|_E \leq 1 \}.
\]

A Banach space $A$, that is also a complex algebra, is called a \textit{Banach algebra} if the norm is submultiplicative, that is $\| a b \|_A \leq \|a\|_A\|b\|_A$ for all $a,b \in A$. 
If $E_0$ and $E_1$ are Banach spaces, we write $\Li(E_0,E_1)$
for the space of bounded linear maps from $E_0$ to $E_1$, 
which comes equipped with the operator norm, that is for $a \in \Li(E_0,E_1)$, 
\[
\|a\| = \sup \{ \| a \xi \|_{E_1} \colon { \xi \in \B(E_0)}\}.
\]
In particular, we write $\Li(E)=\Li(E,E)$, 
which is a Banach algebra. 
The dual of a Banach space $E$ will be denoted by $E'$, that is 
$E'=\Li(E, \C)$. 

A \textit{Hilbert space} $\Hi$ is a Banach space whose norm is induced by a 
complex valued inner product on $\Hi$ via
\[
\|\xi \|_\Hi = \langle \xi, \xi \rangle ^{1/2}.
\]
If $\Hi_0$ and $\Hi_1$ are Hilbert spaces, any 
$a \in \Li(\Hi_0, \Hi_1)$ is characterized by the existence of its adjoint
$a^* \in \Li(\Hi_1, \Hi_0)$ 
satisfying 
\[
\langle a\xi, \eta \rangle = \langle \xi, a^*\eta \rangle
\]
for any $\xi \in \Hi_0$, $\eta \in \Hi_1$. 
\begin{definition}
A \textit{concrete C*-algebra} $A$ is a closed and selfadjoint subalgebra 
of $\Li(\Hi)$ for a Hilbert space $\Hi$. An \textit{abstract C*-algebra}
is a Banach algebra $A$ with an involution $a\mapsto a^*$ such that the 
C*-equation holds: that is $\| a^*a\|=\|a\|^2$ for all $a \in A$. 
\end{definition}

\begin{remark}
It is well known, and not hard to check, that any concrete C*-algebra is also an abstract one.
The celebrated GNS construction, see for instance Theorem 3.4.1 in \cite{Murphy90}, shows that any abstract C*-algebra 
is $*$-isomorphic to a concrete C*-algebra. That is, 
if $A$ is any abstract C*-algebra, then there is a Hilbert space $\Hi$ 
and an injective $*$-preserving algebra homomorphism 
$\varphi \colon A \to \Li(\Hi)$. Furthermore, an important result in C*-algebras (see Theorem 3.1.5 in \cite{Murphy90}) says that since 
$\varphi$ is injective, then $\varphi$ is also isometric. 
Thus, we can and will identify 
$A$ with its isometric copy $\varphi(A)$ in 
$\Li(\Hi)$. 
\end{remark}
If $(\Omega, \mathfrak{M}, \mu)$ is a measure space, two complex valued measurable functions are equivalent when their difference vanishes almost everywhere with respect to $\mu$. Then we define $L^0(\Omega, \mathfrak{M}, \mu)$ to be the vector space of equivalence classes of complex-valued measurable functions. For $p \in [1, \infty)$, we denote  by 
$L^p(\Omega, \mathfrak{M}, \mu)$ 
the Banach space of $p$-integrable functions equipped 
with the usual $p$-norm. That is, 
\[
 L^p(\Omega, \mathfrak{M}, \mu) = \left\{
f \in L^0(\Omega, \mathfrak{M}, \mu) \colon \int_\Omega |f|^p d\mu < \infty
 \right\}
\]
and 
\[
\|f \|_p =  \| f \|_{L^p(\Omega, \mathfrak{M}, \mu)} = 
\left( \int_\Omega |f|^p d\mu \right)^{1/p}.
\]
If $p=\infty$, we have 
\[
 L^p(\Omega, \mathfrak{M}, \mu) = \left\{
f \in L^0(\Omega, \mathfrak{M}, \mu) \colon \| f \|_\infty < \infty
 \right\}
\]
where
\[
\| f \|_\infty = \| f \|_{L^\infty(\Omega, \mathfrak{M}, \mu)}=
\inf \{ \alpha > 0 \colon \mu(\{w \in \Omega \colon |f(w)|>\alpha\})=0\}.
\]
For $p \in [1, \infty]$, we will often
write $L^p(\mu)$ instead of $L^p(\Omega, \mathfrak{M}, \mu)$. 
When $\nu$ is the counting measure on a set $\Omega$, 
we simply write $\ell^p(\Omega)$ to refer to $L^p(\Omega, 2^\Omega, \nu)$. 
In particular, when $d \in \Z_{\geq 1}$
we write $\ell_d^p$ instead of $\ell^p(\{1, \ldots, d\})$. 
\begin{definition}
For $p \in [1, \infty]$, an \textit{$L^p$-operator algebra} is 
a Banach algebra $A$ such that there is a measure space 
$(\Omega, \mathfrak{M}, \mu)$ and an isometric 
algebra homomorphism $\varphi \colon A \to \Li(L^p(\mu))$. 
\end{definition}
 Note that any C*-algebra is an $L^2$-operator 
algebra, but the converse is not true as $L^2$-operator 
algebras can fail to be selfadjoint. There is, currently, not a known abstract characterization of $L^p$-operator algebras, therefore we always work on the concrete setting by specifying a representation on an $L^p$-space. 

\begin{notation}\label{MatrixCOnv}
We will be mostly working with spaces of matrices equipped 
with $p$-operator norms. Specifically, for $d, n \in \Z_{\geq 1}$ 
and $p \in [1, \infty]$, we fix the following notation
\[
M_{n,d}^p(\C) = \Li(\ell_d^p, \ell_n^p), \ 
M_d^p(\C) =M_{d,d}^p(\C) =  \Li(\ell_d^p). 
\]
\end{notation}
\subsection{Hölder Duality} 

For reference, we briefly recall basic well known statements about Hölder duality 
that will be used throughout this paper. For each $p \in [1, \infty]$ we 
let $p' \in [1,\infty]$ be its Hölder conjugate, that is 
$p'=\frac{p}{p-1}$ so that $\frac{1}{p}+\frac{1}{p'}=1$. 
For a measure space $(\Omega, \mathfrak{M}, \mu)$
we have the dual pairing 
$\langle -, - \rangle_p \colon L^{p'}(\mu) \times L^{p}(\mu) \to \C$
given by
\begin{equation}\label{LqLpPairing}
  \langle \eta, \xi \rangle_p =  \int_\Omega \xi\eta  d\mu.  
\end{equation}
We remark that if $\Hi=\ell^2(J)$ is any Hilbert space, 
then the inner product on $\Hi$ is recovered by 
$\langle \xi, \eta \rangle = \langle  \eta, \cj{\xi} \rangle_2$.
The following result is folklore:

\begin{theorem}\label{HoldDual}
Let $p \in [1,\infty]$ and let $(\Omega, \mathfrak{M}, \mu)$ be a measure space. 
Define  $\Phi \colon L^{p'}(\mu) \to L^{p}(\mu)'$ by 
$\Phi(\eta)(\xi)=\langle \eta, \xi\rangle_p$,
for $\eta \in  L^{p'}(\mu)$ and $\xi \in  L^{p}(\mu)$. 
\begin{enumerate}
    \item If $p \in (1,\infty)$, then $\Phi$ is an isometric isomorphism 
    from $L^{p'}(\mu)$ to $L^{p}(\mu)'$
   \item  If $p=1$ and $\mu$ is sigma-finite, then $\Phi$ 
   is an isometric isomorphism from $L^\infty(\mu)$ to $L^1(\mu)'$. 
   \item If $p=\infty$ and $\mu$ is the counting measure on $\{1, \ldots, d\}$ 
   for $d \in \Z_{\geq 1}$, then $\Phi$ 
   is an isometric isomorphism from $\ell^1_d$ to $(\ell^\infty_d)'$.
\end{enumerate}
\end{theorem}
\begin{proof}
Parts (1) and (2) follow from Theorem 6.15 in \cite{FollGB99}.
 For Part (3), since we are working in finite dimension, 
 a direct check shows that $\Phi \colon \ell^1_d \to (\ell_d^\infty)'$ is indeed an isometric isomorphism. 
\end{proof}

An immediate consequence of the previous result, which we will often use, is that 
the norm of a matrix as an operator in $\Li(\ell_d^p, \ell_n^q)$
can be obtained by solving a double maximization problem:
\begin{corollary}\label{FiniteDopNorm}
Let $d, n \in \Z_{\geq 1}$, let $p, q \in [1, \infty]$, and let 
$a \in \Li(\ell_d^p, \ell_n^q)$. 
Then
\[
\|a \|_{ \Li(\ell_d^p, \ell_n^q)} = \max \left\{ |\langle \eta, a\xi \rangle_q|
\colon 
\xi \in \B(\ell_d^p), \eta \in \B\big(\ell_n^{q'}\big) \right\}.
\]
\end{corollary}

From the last corollary, we also obtain a particular case of the well known result that the norm of an operator agrees with the one of its dual (See Proposition VI.1.4 in \cite{ConFA90} for instance). In our scenario, this means that the $p \to q$ operator norm of any matrix agrees with the $q' \to p'$ operator norm of its transpose:

\begin{corollary}\label{a_p=a^T_q}
    Let $d, n \in \Z_{\geq 1}$, let $p, q \in [1, \infty]$, and let 
$a \in \Li(\ell_d^p, \ell_n^q)$. Then $a^T \in \Li(\ell_n^{q'}, \ell_d^{p'})$ and 
\[
\| a \|_{ \Li(\ell_d^p, \ell_n^q)} = \| a^T \|_{\Li(\ell_n^{q'}, \ell_d^{p'})}
\]
\end{corollary}
\begin{proof}
    Follows at once from Corollary \ref{FiniteDopNorm} after observing that 
    \[
    \langle \eta, a\xi \rangle_{q} = \langle \xi , a^T \eta \rangle_{p'}
    \]
    for any $\eta \in \ell_n^{q'}$ and $\xi \in \ell_d^p$.
\end{proof}

\subsection{Spatial Tensor Product}\label{pTenProd}

For $p \in [1, \infty)$, there is a tensor product, called the 
\textit{spatial tensor product} and denoted by $\otimes_p$. 
We refer the reader to Section 7 of \cite{defflor1993} for complete 
details on this 
tensor product. We only describe below the properties we will need. 
If $(\Omega_0, \mathfrak{M}_0, \mu_0)$ is a measure space and $E$ is a 
Banach space, 
then there is an isometric isomorphism 
\[
L^p(\mu_0) \otimes_p E \cong L^p(\mu_0, E)=
\{ g \colon \Omega_0 \to E \mbox{ measurable} 
\colon 
\textstyle{\int_{\Omega_0}} \|g(x)\|^p \  d\mu_0(x) < \infty\}
\]
such that for any $\xi \in L^p(\mu_0)$ and $\eta \in E$, 
the elementary tensor $\xi \otimes \eta $ 
is sent to the function $\omega \mapsto \xi(\omega)\eta$. 
Furthermore, if $(\Omega_1,  \mathfrak{M}_1, \mu_1)$
is another measure space and $E=L^p(\mu_1)$, then there is 
an isometric isomorphism
\begin{equation}\label{LpTensor}
L^p(\mu_0) \otimes_p L^p(\mu_1) \cong 
L^{p}(\Omega_0 \times \Omega_1, \mu_0 \times \mu_1),
\end{equation}
sending $\xi \otimes \eta$ to the function 
$(\omega_0,\omega_1) \mapsto \xi(\omega_0)\eta(\omega_1)$ 
for every $\xi \in L^p(\mu_0)$
and $\eta \in L^p(\mu_1)$. 
We describe its main properties below. 
The following is Theorem 2.16 in \cite{ncp2012AC}, 
except that we have removed the $\sigma$-finiteness assumption 
as in the proof in Theorem 1.1 in \cite{figiel1984}. 
\begin{theorem}\label{SpatialTP}
Let $p \in [1, \infty)$ and for $j \in \{0,1\}$ let 
$(\Omega_j, \mathfrak{M}_j, \mu_j)$, 
$(\Lambda_j, \mathfrak{N}_j, \nu_j)$ be measure spaces.
\begin{enumerate}
\item Under the identification in \eqref{LpTensor}, 
$\op{span}\{ \xi \otimes \eta  \colon \xi \in L^p(\mu_0), \eta \in L^p(\mu_1)\}$ 
is a dense subset of 
$L^{p}(\Omega_0 \times \Omega_1, \mu_0 \times \mu_1)$.  \label{denseTensor_p}
\item $\| \xi \otimes \eta \|_p = \| \xi\|_p\|\eta\|_p$  for every 
$\xi \in L^p(\mu_0)$ and $\eta \in L^p(\mu_1)$. \label{LpTensorNorm}
\item Suppose that 
$a \in \Li(L^p(\mu_0), L^p(\nu_0))$
and $b \in \Li(L^p(\mu_1), L^p(\nu_1))$. 
Then there is a unique map 
$a\otimes b \in \Li(L^p(\mu_0 \times \mu_1),
 L^p( \nu_0 \times \nu_1))$ 
such that 
\[
(a \otimes b)(\xi \otimes \eta)=a\xi \otimes b\eta
\]
for every $\xi \in L^p(\mu_0)$ and $\eta \in L^p(\mu_1)$. 
Further, $\| a\otimes b\|=\|a\|\|b\|$. \label{LpTensorOp}
\item The tensor product of operators defined in 
\eqref{LpTensorOp} is associative, bilinear, 
and satisfies (when the domains are appropriate) 
$(a_1 \otimes b_1)(a_2 \otimes b_2) = a_1 a_2 \otimes b_1b_2$. \label{LpTensorOpProp}
\end{enumerate}
\end{theorem}
