\title{Pricing American Parisian Options under General Time-Inhomogeneous Markov Models}

\author{Yuhao Liu\thanks{School of Science and Engineering, The Chinese University of Hong Kong, Shenzhen, China. Email: oxhowardliu@outlook.com} \and Nian Yang\thanks{Corresponding author. Department of Finance and Insurance, Nanjing University. Email: yangnian@nju.edu.cn} \and Gongqiu Zhang\thanks{Corresponding author. School of Science and Engineering, The Chinese University of Hong Kong, Shenzhen, China. Email: zhanggongqiu@cuhk.edu.cn.}}

