\begin{proof}[Proof of Proposition \ref{prop:htx-linear-system}]
    We first consider the case $x<L$ and note that,
    \begin{align}\label{eq:htxsy-two-cases}
h(t,x; s,y) = \mathbb{P}_{t,x}\big[  \zeta_{\tau_{L,D}^-} =s, Y_{\tau_{L,D}^-} = y, \tau_L^+ < D \big]+\mathbb{P}_{t,x}\big[  \zeta_{\tau_{L,D}^-} =s, Y_{\tau_{L,D}^-} = y, \tau_L^+ \ge D \big].
		\end{align}
  For the first term, it represents the scenario where $Y$ crosses $L$ from below before time $D$. By the strong Markov property, the process restarts at $\tau_L^+$ from $Y_{\tau_L^+}$ and $\zeta_{\tau_L^+}$, and the clock $t-g^-_{L,t}$ is reset to zero. Therefore,
  \begin{align}
      &\mathbb{P}_{t,x}\big[  \zeta_{\tau_{L,D}^-} =s, Y_{\tau_{L,D}^-} = y, \tau_L^+ < D \big]\\
      &=1_{\{ x < L \}} \sum_{z \ge L, s' \ge t} \mathbb{P}_{t,x} \big[  \tau_L^+ < D, Y_{\tau_L^+} = z,\zeta_{\tau_L^+} = s' \big] h(s',z; s,y).
  \end{align}
For the second term in \eqref{eq:htxsy-two-cases}, $\tau_{L,D}^-=D$ when $\tau_L^+ \ge D$, and we have that,
\begin{align}
    \mathbb{P}_{t,x}\big[  \zeta_{\tau_{L,D}^-} =s, Y_{\tau_{L,D}^-} = y, \tau_L^+ \ge D \big]=1_{\{ x < L \}}  \mathbb{P}_{t,x} \big[  \tau_L^+ \ge D, Y_D = y, \zeta_D = s \big].
\end{align}
For the case when $x\ge L$, the length of excursion will not start to accumulate until $\tau_L^-$ and we restart the process at that time:
\begin{align}
    h(t,x;s,y)=1_{\{ x \ge L \}} \sum_{z < L, s' \ge t} \mathbb{P}_{t,x} \big[ \zeta_{\tau_L^-} = s', Y_{\tau_L^-} = z \big] h(s', z; s, y).
\end{align}
Putting the above results together, we obtain the linear system for $h(t,x;s,y)$. 
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop:cfi-linear-system}]
     By the linear system for $h(t,x; s,y)$ in Proposition \ref{prop:htx-linear-system}, we have that:
     \begin{align}
         \widetilde{C}_{fi}(t,x)&=\sum_{(s,y) \in \mathbb{T} \times \mathbb{S}} e^{-rs} h(t,x; s,y) c_f(s,y) \\
         &=1_{\{ x < L \}} \sum_{z \ge L, s' \ge t} \mathbb{P}_{t,x} \big[  \tau_L^+ < D, Y_{\tau_L^+} = z,\zeta_{\tau_L^+} = s' \big] h(s',z; s,y)e^{-rs}c_f(s,y) \\
			&\quad + 1_{\{ x < L \}}  \mathbb{P}_{t,x} \big[  \tau_L^+ \ge D, Y_D = y, \zeta_D = s \big]e^{-rs}c_f(s,y) \\
			&\quad + 1_{\{ x \ge L \}} \sum_{z < L, s' \ge t} \mathbb{P}_{t,x} \big[ \zeta_{\tau_L^-} = s', Y_{\tau_L^-} = z \big] h(s', z; s, y)e^{-rs}c_f(s,y)\\
       &=1_{\{ x < L \}} \sum_{z \ge L, s' \ge t} \mathbb{P}_{t,x} \big[  \tau_L^+ < D, Y_{\tau_L^+} = z,\zeta_{\tau_L^+} = s' \big] \widetilde{C}_{fi}(s',z) \\
			&\quad + 1_{\{ x < L \}} \sum_{(s,y) \in \mathbb{T}\times \mathbb{S}}  \mathbb{P}_{t,x} \big[  \tau_L^+ \ge D, Y_D = y,\zeta_D = s \big] e^{-rs} c_f(s, y) \\
			&\quad + 1_{\{ x \ge L \}} \sum_{z < L, s' \ge t} \mathbb{P}_{t,x} \big[ \zeta_{\tau_L^-} = s', Y_{\tau_L^-} = z \big] \widetilde{C}_{fi}(s', z).
     \end{align}
 \end{proof}

\begin{proof}[Proof of Proposition \ref{prop:v-system}]
    For $t\le T$, $D>0$ and $x<L$, following the same arguments in the proof of Proposition 2.3 in \cite{zhang2023general}, we have 
    \begin{align}
        \partial_D v(D, t, x) &= \mathcal{G}^{\zeta, Y}v(D,t,x)\\
        &=\frac{v(D, t+\delta_t, x) - v(D, t, x)}{\delta_t} + \mathcal{G}_t^Y v(D, t, x).
    \end{align}
    We recall that $v(D, t, x) = \sum_{(s,y) \in \mathbb{T}\times \mathbb{S}}  \mathbb{P}_{t,x} \big[  \tau_L^+ \ge D, Y_D = y,\zeta_D = s \big] e^{-rs} c_f(s, y)$ and $\mathbb{P}_{t,x} \big[  \tau_L^+ \ge D, Y_D = y,\zeta_D = s \big] = 0$ for $D>0$, $x\ge L$ or $t>T$. Then $v(D,t,x)=0$ in these cases. And for $D=0$, $\mathbb{P}_{t,x} \big[  \tau_L^+ \ge D, Y_D = y,\zeta_D = s \big] = 1_{\{ x = y, s = t \}}$. Then $v(0,t,x)=e^{-rt}c_f(t,x)$.
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop:h^+-system}]
For $x <L$, $t \le T$ and $D > 0$,
	\begin{align}
		\partial_D h^+(D,t,x, z) &= \mathcal{G}^{\zeta, Y} \mathbb{P}_{t,x} \big[  \tau_L^+ < D, Y_{\tau_L^+} = z,\zeta_{\tau_L^+} = t \big]\\
		&= \frac{\mathbb{P}_{t+\delta_t,x} \big[  \tau_L^+ < D, \widetilde{Y}_{\tau_L^+} = z,\zeta_{\tau_L^+} = t \big] - \mathbb{P}_{t,x} \big[ \tau_L^+ < D, Y_{\tau_L^+} = z,\zeta_{\tau_L^+} = t \big]}{\delta_t} \\
		&\quad + \mathcal{G}^{Y}_t \mathbb{P}_{t,x} \big[ \tau_L^+ < D, Y_{\tau_L^+} = z,\zeta_{\tau_L^+} = t \big] \\
		&= (\mathcal{G}_t^Y - 1/\delta_t) h^+(D,t,x, z).
	\end{align}
 The equations for other cases can be easily obtained by the definition of $h^+(D,t,x, z)$. By combining each pair of corresponding terms in the equations for $h_1^+(t, x, z)$ and $h_2^+(D, t, x, z)$, we see that $h_1^+(t, x, z)-h_2^+(D, t, x, z)$ satisfies the equations for $h^+(D,t,x, z)$. 
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop:h^-system}]
    For $x \ge L$ and $t \le T$,
	\begin{align}
		&\mathcal{G}^{\zeta, Y}\mathbb{P}_{t,x} \big[ \zeta_{\tau_L^-} = t, Y_{\tau_L^-} = z \big] \\
		&= \frac{\mathbb{P}_{t+\delta_t,x} \big[\zeta_{\tau_L^-} = t, Y_{\tau_L^-} = z \big] - \mathbb{P}_{t,x} \big[ \zeta_{\tau_L^-} = t, Y_{\tau_L^-} = z \big]}{\delta_t} + \mathcal{G}_t^Y \mathbb{P}_{t,x} \big[ \zeta_{\tau_L^-} = t, Y_{\tau_L^-} = z \big]  \\
		&= -\frac{h^-(t,x,z)}{\delta_t} + \mathcal{G}_t^Y h^-(t,x,z) = 0.
	\end{align}
	For $x < L$, $\zeta_{\tau_L^-} = 0$ and hence $h^-(t, x, z) = 1_{\{ x = z \}}$ in this case.
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop:u^+-system}]
    For $x < L$, $t \le T$ and $D>0$,
	\begin{align}
		&\partial_D u^+(D,t,x) \\
		&= \sum_{z \ge L, s' > t} \partial_D \mathbb{P}_{t,x} \big[ \tau_L^+ < D, Y_{\tau_L^+} = z,\zeta_{\tau_L^+} = s' \big] \widetilde{C}_{fi}(s',z) \\
		&= \sum_{z \ge L, s' > t}  \frac{ \mathbb{P}_{t+\delta_t,x} \big[ \tau_L^+ < D, Y_{\tau_L^+} = z,\zeta_{\tau_L^+} = s' \big] -  \mathbb{P}_{t,x} \big[ \tau_L^+ < D, Y_{\tau_L^+} = z,\zeta_{\tau_L^+} = s' \big]}{\delta_t}  \widetilde{C}_{fi}(s',z) \\
		&\quad + \sum_{z \ge L, s' > t} \mathcal{G}_t^{Y} \mathbb{P}_{t,x} \big[ \tau_L^+ < D, Y_{\tau_L^+} = z,\zeta_{\tau_L^+} = s' \big] \widetilde{C}_{fi}(s',z) \\
		&= \frac{1}{\delta_t} \sum_{z \ge L} h^+(D, t+\delta_t, x, z) \widetilde{C}_{fi}(t+\delta_t, z) + \frac{u^+(D,t+\delta_t,x) - u^+(D,t,x)}{\delta_t} + \mathcal{G}_t^Y u^+(D,t,x).
	\end{align}

	For $t >T$ or $D=0$, $1_{\{ \tau_L^+ < D \}} = 0$ and then	$u^+(D, t, x) = 0$. And for $x \ge L$ and $D >0$, $\tau_L^+ = 0$ and $\zeta_{\tau_L^+} = t$. Then $u^+(D, t, x) = 0$ in this case.
\end{proof}


\begin{proof}[Proof of Proposition \ref{prop:u^-system}]
    For $t \le T$ and $x \ge L$,
	\begin{align}
		&\sum_{z < L, s' > t} \mathcal{G}^{\zeta, Y} \mathbb{P}_{t,x} \big[ \zeta_{\tau_L^-} = s', Y_{\tau_L^-} = z \big] \widetilde{C}_{fi}(s', z) \\
		&= \sum_{z < L, s' > t} \frac{\mathbb{P}_{t+\delta_t,x} \big[ \zeta_{\tau_L^-} = s', Y_{\tau_L^-} = z \big] - \mathbb{P}_{t,x} \big[ \zeta_{\tau_L^-} = s', Y_{\tau_L^-} = z \big]}{\delta_t} \widetilde{C}_{fi}(s', z) \\
		&\quad + \sum_{z < L, s' > t} \mathcal{G}^Y_t \mathbb{P}_{t,x} \big[ \zeta_{\tau_L^-} = s', Y_{\tau_L^-} = z \big] \widetilde{C}_{fi}(s', z) \\
		&= \frac{1}{\delta_t}\sum_{z < L}\mathbb{P}_{t+\delta_t,x} \big[ \zeta_{\tau_L^-} = t+\delta_t, Y_{\tau_L^-} = z \big] \widetilde{C}_{fi}(s', z) + \frac{u^-(t+\delta_t,x)-u^-(t,x)}{\delta_t} + \mathcal{G}^Y_t u^-(t,x) \\
		&= \frac{1}{\delta_t}\sum_{z < L} h^-(t+\delta_t, x, z) \widetilde{C}_{fi}(s', z) + \frac{u^-(t+\delta_t,x)-u^-(t,x)}{\delta_t} + \mathcal{G}^Y_t u^-(t,x) \\
		&= 0.
	\end{align}
	We note that $\mathbb{P}_{t,x} \big[ \zeta_{\tau_L^-} = s', Y_{\tau_L^-} = z \big] = 1_{\{t = s', x = z\}}$ when $x < L $ and $\mathbb{P}_{t,x} \big[ \zeta_{\tau_L^-} = s', Y_{\tau_L^-} = z \big] = 0$ for all $s' > t$ when $t = T+\delta$. Therefore, $u^-(t,x) = 0$ in these cases.
\end{proof}

\begin{proof}[Proof of Lemma \ref{lem:perpetual-American-option-intermedia}] We have
    \[
    \begin{aligned}
        &\Big|c^{\hat{\delta}}(0,x)-c^{\hat{\delta}}(x)\Big|\\
        &=\sup_{\tau\in\mathcal{T}^X}\mathbb{E}_{0,x}\Big[e^{-r\tau^{\hat{\delta}}}f(X_{\tau^{\hat{\delta}}})\Big]-\sup_{\tau\in\mathcal{T}^X_{0,T}}\mathbb{E}_{0,x}\Big[e^{-r\tau^{\hat{\delta}}}f(X_{\tau^{\hat{\delta}}})\Big]\\
        &\leq  \sup_{\tau\in\mathcal{T}^X_{0,T}}\mathbb{E}_{0,x}\Big[\Big|e^{-r\tau^{\hat{\delta}}}f(X_{\tau^{\hat{\delta}}})\Big|\Big]+\sup_{\tau\in \mathcal{T}^X \setminus \mathcal{T}_{0,T}^X} \mathbb{E}_{0,x}\Big[\Big|e^{-r\tau^{\hat{\delta}}}f(X_{\tau^{\hat{\delta}}})\Big|\Big]-\sup_{\tau\in\mathcal{T}^X_{0,T}}\mathbb{E}_{0,x}\Big[\Big|e^{-r\tau^{\hat{\delta}}}f(X_{\tau^{\hat{\delta}}})\Big|\Big]\\
       &=  \sup_{\tau\in \mathcal{T}^X \setminus \mathcal{T}^X_{0,T}} \mathbb{E}_{0,x}\Big[\Big|e^{-r\tau^{\hat{\delta}}}f(X_{\tau^{\hat{\delta}}})\Big|\Big]
    \end{aligned}
    \]
    By Assumption \ref{assump:payoff-growth}, there exists a $T_\epsilon$, such that for any $\tau^{\hat{\delta}}>T>T_\epsilon$, $|e^{-r\tau^{\hat{\delta}}}f(X_{\tau^{\hat{\delta}}})|<\epsilon$, and
    \[
    \begin{aligned}
        &\Big|c^{\hat{\delta}}(0,x)-c^{\hat{\delta}}(x)\Big|
        \leq  \sup_{\tau\in \mathcal{T}^X \setminus \mathcal{T}^X_{0,T}} \mathbb{E}_{0,x}\Big[\Big|e^{-r\tau^{\hat{\delta}}}f(X_{\tau^{\hat{\delta}}})\Big|\Big]
        <  \epsilon.
    \end{aligned}
    \]
    Similarly, we can show that $\Big|\widetilde{c}^{\hat{\delta}}_f(0,x)-c_p^{\hat{\delta}}(x)\Big|< \epsilon$. So the lemma is proved.
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop:perpetual-down-in-Amer-option-convergence}]
    We first prove the following claims:

    \begin{itemize}
    \item[(1)] $c^{\hat{\delta}}_p(x)\rightarrow c^{\hat{\delta}}(x)$ as $n\rightarrow \infty$ for any $\hat{\delta}$. 

    \item[(2)] There exists some constant $\widetilde{C}$ independent of $n$ and $\hat{\delta}$ such that 
    \[
    |c^{\hat{\delta}}(x)-c(x)|\leq \widetilde{C}{\hat{\delta}}^{\frac{1}{2}}.
    \]

    \item[(3)] There exists some constant $\widetilde{D}$ independent of $n$ and $\hat{\delta}$ such that
    \[
    |c_p^{\hat{\delta}}(x)-c_p(x)|\leq \widetilde{D}{\hat{\delta}}^{\frac{1}{2}}.
    \]
    \end{itemize}

    We will only show the proof for claim (1). The proofs of claim (2) and (3) are analogous to the proof of Theorem 3 in \cite{zhang2021pricing}. 

    Proof of (1): Let $\mathrm{H}$ be the filtration generated by the process $(X,Y)$. $\widetilde{\mathcal{T}}_{s,T}$ is the set of $\mathrm{H}$ stopping times taking values in $[s,T] \cup \{\infty\}$. $\tau^{\hat{\delta}}$ is the stopping time taking the form $\tau^{\hat{\delta}}=\inf\{ t\ge \tau: t\in \mathbb{T}^{\hat{\delta}}\}$ with $\mathbb{T}^{\hat{\delta}}=\{i\Hat{\delta}: i\in \mathbb{N}\}$  for some stopping time $\tau \in \widetilde{\mathcal{T}}_{s,T}$. We first show that $\Big|\widetilde{c}^{\hat{\delta}}_f(s,x)-c^{\hat{\delta}}(s,x)\Big|\rightarrow 0$ as $n\rightarrow \infty$.  
    \begin{align}
        \Big|\widetilde{c}^{\hat{\delta}}_f(s,x)-c^{\hat{\delta}}(s,x)\Big|
        &\leq  \bigg| \sup_{\tau\in \widetilde{\mathcal{T}}_{s,T}}\mathbb{E}_{s,x}\Big[ e^{-r(\tau^{\hat{\delta}}-s)}f(Y_{\tau^{\hat{\delta}}}) - e^{-r(\tau^{\hat{\delta}}-s)} f(X_{\tau^{\hat{\delta}}}) \Big]  \bigg|\\
        &\leq  \mathbb{E}_{s,x}\bigg[\sup_{t\in \mathbb{T}^{\hat{\delta}}\cap [s,T+\hat{\delta}]}  \Big|e^{-r(t - s)} f(Y_{t})-e^{-r(t-s)}f(X_{t})\Big| \bigg]\\
        &\leq  K\mathbb{E}_{s,x}\bigg[\sup_{t\in \mathbb{T}^{\hat{\delta}}\cap [s,T+\hat{\delta}]} \Big|X_{t}-Y_{t}\Big|\bigg]
    \end{align}
    By the assumption that $Y$ converges weakly to $X$ as $n\rightarrow \infty$, $Y_t$ converges to $X_t$ in distribution for any fixed $t\in \mathbb{T}^{\hat{\delta}}\cap [s,T+\hat{\delta}]$. By \cite{eriksson2015american}. Further with the uniform integrability of the collection $(Y_t, X_t, t\in \mathbb{T}^{\hat{\delta}}\cap [s,T+\hat{\delta}], n\in \mathbb{N})$, we have
    \[
    \mathbb{E}_{s,x}\Big[\big|Y_t-X_t\big|\Big]\rightarrow 0,
    \]
    as $n\rightarrow \infty$ for any $t\in \mathbb{T}^{\hat{\delta}}\cap [s,T+\hat{\delta}]$. Noting that $\mathbb{T}^{\hat{\delta}}\cap [s,T+\hat{\delta}]$ contains finite number of elements, we have
    \[
    K\mathbb{E}_{s,x}\Big[\sup_{t\in \mathbb{T}^{\hat{\delta}}\cap [s,T+\hat{\delta}]}\big|X_{t}-Y_{t}\big|\Big]\rightarrow 0
    \]
    as $n\rightarrow \infty$ which implies that $\Big|\widetilde{c}^{\hat{\delta}}_f(s,x)-c^{\hat{\delta}}(s,x)\Big|\rightarrow 0$.
    Then,
    \[
    \begin{aligned}
        &\Big|c^{\hat{\delta}}_p(x)-c^{\hat{\delta}}(x)\Big|\\
        &=\Big|c^{\hat{\delta}}_p(x)-c^{\hat{\delta}}(x)+\widetilde{c}^{\hat{\delta}}_f(0,x)-\widetilde{c}^{\hat{\delta}}_f(0,x)+c^{\hat{\delta}}(0,x)-c^{\hat{\delta}}(0,x)\Big|\\
        &\leq\Big|c^{\hat{\delta}}(0,x)-c^{\hat{\delta}}(x)\Big|+\Big|\widetilde{c}_f^{\hat{\delta}}(0,x)-c_p^{\hat{\delta}}(x)\Big|+\Big|\widetilde{c}_f^{\hat{\delta}}(0,x)-c^{\hat{\delta}}(0,x)\Big|.
    \end{aligned} 
    \]
    By Lemma \ref{lem:perpetual-American-option-intermedia}, for any $\epsilon>0$, there exists a $T_\epsilon$ independent of $n$, such that for any $T>T_\epsilon$,
    \[
    \text{max}\left \{ \Big|c^{\hat{\delta}}(0,x)-c^{\hat{\delta}}(x)\Big|, \Big|\widetilde{c}^{\hat{\delta}}_f(0,x)-c^{\hat{\delta}}_p(x)\Big| \right \}<\epsilon. 
    \]
    And for any fixed $T>T_\epsilon$, there exists an $N_\epsilon$ such that for $n>N_\epsilon$, 
    \[
    \Big|\widetilde{c}^{\hat{\delta}}_f(0,x)-c^{\hat{\delta}}(0,x)\Big|<\epsilon.
    \]
    Combining the results, we have $|c^{\hat{\delta}}_p(x)-c^{\hat{\delta}}(x)|<3\epsilon$. Since $\epsilon$ can be arbitrarily small, (1) is proved. 

    Combining the claims (1), (2) and (3), we get that,
    \[
    \begin{aligned}
    &\Big|c_p(x)-c(x)\Big| \\
    &\leq \Big|c_p(x)-c^{\hat{\delta}}_p(x) \Big|+\Big|c^{\hat{\delta}}_p(x) -c^{\hat{\delta}}(x)  \Big|+\Big|c^{\hat{\delta}}(x)-c(x)   \Big| \\
    &\le (\widetilde{C} + \widetilde{D}){\hat{\delta}}^{\frac{1}{2}} + \Big|c^{\hat{\delta}}_p(x) -c^{\hat{\delta}}(x)  \Big|.
    \end{aligned}
    \]
    We note that $\hat{\delta}$ can be arbitrarily small and for each $\hat{\delta}$, we can select a sufficiently large $N$ such that for all $n > N$, $\big|c^{\hat{\delta}}_p(x) -c^{\hat{\delta}}(x)\big| < \epsilon$ for any $\epsilon>0$. This concludes the proof.
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:perpetual-down-in-Amer-Pari-option-convergence}]
    Firstly, we note that:
    \[
    \begin{aligned}
     \sup_{\tau \in \mathcal{T}^Y}\mathbb{E}_x \big[ e^{-r\tau}  f( Y_\tau) 1_{\{ \tau \ge \tau_{L, D}^{Y,-} \}} \big]=\mathbb{E}_x\big[\sup_{\tau\in\mathcal{T}^Y}\mathbb{E}_x\big[e^{-r\tau}f(Y_{\tau})1_{\{ \tau\ge \tau_{L, D}^{Y,-} \}}|\tau_{L, D}^{Y,-}\big]  \big].
    \end{aligned}
    \]
For the quantity inside the expectation, $\sup_{\tau\in\mathcal{T}^Y}\mathbb{E}_x\big[e^{-r\tau}f(Y_{\tau})1_{\{ \tau\ge \tau_{L, D}^{Y,-} \}}|\tau_{L, D}^{Y,-}\big]$ is the approximate value function of a perpetual American option with initial time $\tau_{L, D}^{Y,-}$. Therefore, by Proposition \ref{prop:perpetual-down-in-Amer-option-convergence} and Proposition \ref{prop:parisian-stopping-time-weak-convergence}, as $n \to \infty$,
    \[
    \begin{aligned}
\mathbb{E}_x\big[\sup_{\tau\in\mathcal{T}^Y}\mathbb{E}_x\big[e^{-r\tau}f(Y_{\tau})1_{\{ \tau\ge \tau_{L, D}^{Y,-} \}}|\tau_{L, D}^{Y,-}\big]  \big]
        &\rightarrow \mathbb{E}_x\big[\sup_{\tau\in\mathcal{T}^X}\mathbb{E}_x\big[e^{-r\tau}f(X_{\tau})1_{\{ \tau\ge \tau_{L, D}^{X,-} \}}|\tau_{L, D}^{X,-}\big]\big] \\
        &=\sup_{\tau \in \mathcal{T}^X}\mathbb{E}_x\big[e^{-r\tau}f(X_{\tau})1_{\{ \tau\ge \tau_{L, D}^{X,-} \}}\big].
    \end{aligned}
    \]
\end{proof}

\begin{proof}[Proof of Proposition \ref{prop:finite-American-option-converge}]
To prove Proposition \ref{prop:finite-American-option-converge}, we first establish the following results: 
\begin{itemize}
    \item[(1)] There exists some constant $\widetilde{C}$ independent of $n$, $\delta_t$ and $\hat{\delta}$ such that
\[
\Big|c(s,x)-c^{\hat{\delta}} (s,x)\Big|\le \widetilde{C}\Hat{\delta}^{\frac{1}{2}}.
\]

    \item[(2)] There exists some constant $\widetilde{D}$ independent of $n$, $\delta_t$ and $\hat{\delta}$ such that
\[
\Big|c_f(s,x)-c_f^{\hat{\delta}} (s,x)\Big|\le \widetilde{D}\Hat{\delta}^{\frac{1}{2}}.
\]


    \item[(3)] For any fixed $\hat{\delta}$, as $\delta_t\rightarrow 0$ and $n\rightarrow \infty$,
\[
c_{f}^{\hat{\delta}} (s,x)\rightarrow c^{\hat{\delta}} (s,x).
\]
\end{itemize}


We will show the details for the proofs of (2) and (3). The proof of (1) is similar to that of (2). 

Proof of (2): We note that $\zeta$ is  $\delta_t$ times a Poisson process with intensity $1/\delta_t$ and $\zeta_t\rightarrow t$ almost surely as $\delta_t\rightarrow 0$. By definition, $0 \le \tau^{\hat{\delta}} - \tau \le \hat{\delta}$ and then it is not difficult to see that for any $\tau\in \mathcal{T}_s$, $\mathbb{E}_{s, x}\big[\zeta_{\tau^{\hat{\delta}}}-\zeta_{\tau} \big]\le \hat{\delta}$. Next, we analyze $c_f(s,x)-c_f^{\hat{\delta}} (s,x)$. By the triangle inequality, we have that
    \[
    \begin{aligned}
     & \left|c_f(s,x)-c_f^{\hat{\delta}} (s,x)\right| \\
&\leq  \sup _{\tau \in \mathcal{T}^{\zeta,Y}_{s}} \mathbb{E}_{s, x}\bigg[\Big|e^{-r (\zeta_{\tau}-s)} f\big(Y_{\tau}\big)-e^{-r (\zeta_{\tau^{\hat{\delta}}}-s)} f\left(Y_{\tau^{\hat{\delta}}}\right)\Big|\bigg] \\
&\leq  \sup _{\tau \in \mathcal{T}^{\zeta,Y}_{s}} \mathbb{E}_{s, x}\bigg[\Big|\left(e^{-r (\zeta_{\tau}-s)}-e^{-r (\zeta_{\tau^{\hat{\delta}}}-s)}\right) f\left(Y_{\tau}\right)\Big|+\Big|e^{-r (\zeta_{\tau^{\hat{\delta}}}-s)}\left(f\left(Y_{\tau}\right)-f\left(Y_{\tau^{\hat{\delta}}}\right)\right)\Big|\bigg] \\
&\leq  r \sup _{\tau \in \mathcal{T}^{\zeta, Y}_{s}} \mathbb{E}_{s, x}\big[\zeta_{\tau^{\hat{\delta}}}-\zeta_{\tau}  \big]\sup _{\tau \in \mathcal{T}^{\zeta,Y}_{s}} \mathbb{E}_{s, x}\Big[e^{-r (\zeta_{\tau}-s)}\big|f\left(Y_{\tau}\right)\big|\Big]\\
&\;\;\;\;+K\sup _{\tau \in \mathcal{T}^{Y}_{s}} \mathbb{E}_{s, x}\Big[\big|Y_{\tau}-Y_{\tau^{\hat{\delta}}}\big|\Big] \quad \text { (by Lipschitz continuity) } \\
&\leq  \Hat{\delta} r C+K\sup _{\tau \in \mathcal{T}^Y_{s}}\bigg(\mathbb{E}_{s, x}\Big[\big|Y_{\tau}-Y_{\tau^{\hat{\delta}}}\big|^2\Big]\bigg)^{\frac{1}{2}} \quad \text {(by Assumption \ref{assump:payoff-growth} and the Cauchy-Schwartz inequality) }\\
&=  \Hat{\delta} r C+K\sup _{\tau \in \mathcal{T}^Y_{s}}\bigg(\mathbb{E}_{s, x}\Big[\mathbb{E}_{\tau, Y_{\tau}}\Big[\big|Y_{\tau}-Y_{\tau^{\hat{\delta}}}\big|^2\Big]\Big]\bigg)^{\frac{1}{2}} \\
&\leq  \Hat{\delta} r C+K\sup _{\tau \in \mathcal{T}^Y_{s}}\bigg(\mathbb{E}_{s, x}\Big[\mathbb{E}_{\tau, Y_{\tau}}\Big[\langle Y\rangle_{\Hat{\delta}}\Big]\Big]\bigg)^{\frac{1}{2}} \\
&\leq  \Hat{\delta} r C+K\Hat{\delta}^{\frac{1}{2}} K_{Y}^{\frac{1}{2}}, \quad \text {(by Assumption \ref{assump:moment-quadratic-variation}} )
    \end{aligned}
    \]
    where $C$ is a constant independent of $n$ and $\delta_t$, $K$ is the Lipschitz constant of $f(x)$, and $K_Y$ is the Lipschitz constant of $\mathbb{E}_{t, x}\big[\langle Y\rangle_{\Hat{\delta}}\big]$ w.r.t. $\hat{\delta}$.


    Proof of (3): Let $\mathrm {H}$ and $\mathrm{F}^{\zeta,X}$ be the filtration generated by the processes $(X, Y)$ and $(\zeta, X)$, respectively. We introduce the following additional intermediate quantities:
    \[
    \hat{c}_f^{\hat{\delta}}(s,x)=\sup_{\tau\in \mathcal{T}^{\zeta, Y} _{s}}\mathbb{E}_{s,x}\Big[e^{-r(\tau^{\hat{\delta}} - s)} f(Y_{\tau^{\hat{\delta}}})1_{\{ \zeta_{\tau}\le T \}} \Big],
    \]
    \[
    \hat{c}^{\hat{\delta}}(s,x)=\sup_{\tau\in \mathcal{T}^{\zeta, X} _{s}}\mathbb{E}_{s,x}\Big[e^{-r(\tau^{\hat{\delta}} - s)} f(X_{\tau^{\hat{\delta}}})1_{\{ \zeta_{\tau}\le T \}} \Big],
    \]
    \[
    \Bar{c}_f^{\hat{\delta}}(s,x)=\sup_{\tau\in \mathcal{T}^{\zeta,Y} _{s}}\mathbb{E}_{s,x}\Big[e^{-r(\zeta_{\tau}^{\hat{\delta}} - s)} f(Y_{\tau^{\hat{\delta}}})1_{\{ \zeta_{\tau}\le T \}}1_{\{\tau\le \overline{T} \}} \Big],
    \]
    \[
    \tilde{c}_f^{\hat{\delta}}(s,x)=\sup_{\tau\in \mathcal{T}^{\zeta, Y} _{s}}\mathbb{E}_{s,x}\Big[e^{-r(\tau^{\hat{\delta}} - s)} f(Y_{\tau^{\hat{\delta}}})1_{\{ \zeta_{\tau}\le T \}}1_{\{\tau\le \overline{T} \}} \Big],
    \]
    \[
    \tilde{c}^{\hat{\delta}}(s,x)=\sup_{\tau\in \mathcal{T}^{\zeta, X} _{s}}\mathbb{E}_{s,x}\Big[e^{-r(\tau^{\hat{\delta}} - s)} f(X_{\tau^{\hat{\delta}}})1_{\{ \zeta_{\tau}\le T \}}1_{\{\tau\le \overline{T} \}} \Big],
    \]
    where $\mathcal{T}^{\zeta, X} _{s}$ and $\mathcal{T}^{\zeta, Y} _{s}$ are the sets of $\mathrm{F}^{\zeta, X}$ and $\mathrm{F}^{\zeta, Y}$ stopping times taking values in $[s,\infty]$.

    Since 
    \begin{align}
        &\Big|c_f^{\hat{\delta}} (s,x)-\hat{c}_f^{\hat{\delta}} (s,x)\Big|\\
         &=  \Big|c_f^{\hat{\delta}} (s,x)- \Bar{c}_f^{\hat{\delta}}(s,x)+\Bar{c}_f^{\hat{\delta}}(s,x)-\tilde{c}_f^{\hat{\delta}}(s,x)+\tilde{c}_f^{\hat{\delta}}(s,x)-\hat{c}_f^{\hat{\delta}} (s,x)  \Big|\\
        & \leq  \Big|c_f^{\hat{\delta}} (s,x)- \Bar{c}_f^{\hat{\delta}}(s,x)\Big| + \Big| \Bar{c}_f^{\hat{\delta}}(s,x)-\tilde{c}_f^{\hat{\delta}}(s,x)\Big| +\Big| \tilde{c}_f^{\hat{\delta}}(s,x)-\hat{c}_f^{\hat{\delta}} (s,x)\Big| \\
        &\leq \bigg| \sup_{\tau\in \mathcal{T}^{\zeta,Y} _{s}}\mathbb{E}_{s,x}\Big[e^{-r\zeta_{\tau^{\hat{\delta}}}} f(Y_{\tau^{\hat{\delta}}})-e^{-r\zeta_{\tau^{\hat{\delta}}}} f(Y_{\tau^{\hat{\delta}}})1_{\{ \tau\le \overline{T} \}}\Big]\bigg|\\
        &\;\;\;\;+\bigg| \sup_{\tau\in \mathcal{T}^{\zeta, Y} _{s}}\mathbb{E}_{s,x}\Big[e^{-r\zeta_{\tau^{\hat{\delta}}}} f(Y_{\tau^{\hat{\delta}}})1_{\{ \tau\le \overline{T} \}}-e^{-r\tau^{\hat{\delta}}} f(Y_{\tau^{\hat{\delta}}})1_{\{ \tau\le \overline{T} \}}\Big]\bigg|\\
        & \;\;\;\; + \bigg| \sup_{\tau\in \mathcal{T}^Y _{s}}\mathbb{E}_{s,x}\Big[e^{-r\tau^{\hat{\delta}}} f(Y_{\tau^{\hat{\delta}}})1_{\{ \tau\le \overline{T} \}}-e^{-r\tau^{\hat{\delta}}} f(Y_{\tau^{\hat{\delta}}}) \Big]\bigg|\\
        &\leq   \sup_{\tau\in \mathcal{T}^{\zeta,Y} _{s}\setminus \mathcal{T}^{\zeta,Y} _{s,\overline{T}}}\mathbb{E}_{s,x}\bigg[\Big|e^{-r\zeta_{\tau^{\hat{\delta}}}} f(Y_{\tau^{\hat{\delta}}})\Big|\bigg]+\mathbb{E}_{s,x}\bigg[\sup_{t\in \mathbb{T}^{\hat{\delta}}\cap [s,\overline{T}+\hat{\delta}]}  \Big|e^{-r\zeta_t} f(Y_{t})-e^{-rt}f(Y_{t})\Big| \bigg]\\
        & \;\;\;\;\; +\sup_{\tau\in \mathcal{T}^Y _{s}\setminus \mathcal{T}^Y _{s,\overline{T}}}\mathbb{E}_{s,x}\bigg[\Big|e^{-r\tau^{\hat{\delta}}} f(Y_{\tau^{\hat{\delta}}})\Big|\bigg], \label{eq:convergence-of-discount-factor}
    \end{align}
    we will show that for any $\epsilon>0$, there exist a $\overline{T}_{\epsilon}$ independent of $n$ and $\delta_t$, and there exists a $\delta_t^{\epsilon}$ independent of $n$, such that for any $\overline{T}>\overline{T}_{\epsilon}$ and $\delta_t<\delta_t^{\epsilon}$,  $|c_f^{\hat{\delta}} (s,x)- \hat{c}_f^{\hat{\delta}}(s,x)|<\epsilon$.
    For the first and last terms of \eqref{eq:convergence-of-discount-factor}, we can use the same arguments in the proof of Lemma \ref{lem:perpetual-American-option-intermedia} and show that for any $\epsilon>0$, there exists a $\overline{T}_{\epsilon}$ independent of $n$ and $\delta_t$ such that for any $\overline{T}>\overline{T}_{\epsilon}$, 
    \[
    \max\Big\{\sup_{\tau\in \mathcal{T}^{\zeta,Y} _{s}\setminus \mathcal{T}^{\zeta,Y} _{s, \overline{T}}}\mathbb{E}_{s,x}\bigg[\Big|e^{-r\zeta_{\tau^{\hat{\delta}}}} f(Y_{\tau^{\hat{\delta}}})\Big|\bigg], \sup_{\tau\in \mathcal{T}^Y _{s}\setminus \mathcal{T}^Y _{s,\overline{T}}}\mathbb{E}_{s,x}\bigg[\Big|e^{-r\tau^{\hat{\delta}}} f(Y_{\tau^{\hat{\delta}}})\Big|\bigg] \Big\}<\frac{\epsilon}{3}.
    \]
    And for the second term in \eqref{eq:convergence-of-discount-factor}, we fix $\overline{T}=\overline{T}_{\epsilon}$. We further note that inside the expectation the supremum is taken over a finite set $\mathbb{T}^{\hat{\delta}}\cap[s,\overline{T}+\hat{\delta}]$ which implies that there exists a $\delta_t^{\epsilon}$ independent of $n$ such that for any $\delta_t<\delta_t^{\epsilon}$, 
    \[
    \mathbb{E}_{s,x}\bigg[\sup_{t\in \mathbb{T}^{\hat{\delta}}\cap [s,\overline{T}+\hat{\delta}]}  \Big|e^{-r\zeta_t} f(Y_{t})-e^{-rt}f(Y_{t})\Big| \bigg]<\frac{\epsilon}{3}.
    \]
Combining the estimates above, we get that $|c_f^{\hat{\delta}} (s,x)- \hat{c}_f^{\hat{\delta}}(s,x)|<\epsilon$.

Moreover,
\begin{align}
   & \Big|\hat{c}_f^{\hat{\delta}}(s,x)-\hat{c}^{\hat{\delta}}(s,x)\Big|\\
   &\leq  \Big|\hat{c}_f^{\hat{\delta}}(s,x) -\tilde{c}_f^{\hat{\delta}}(s,x)\Big|+\Big|\tilde{c}_f^{\hat{\delta}}(s,x)-\tilde{c}^{\hat{\delta}}(s,x)\Big| +\Big|\tilde{c}^{\hat{\delta}}(s,x)-\hat{c}^{\hat{\delta}}(s,x)\Big| \\
   &\leq \bigg| \sup_{\tau\in \mathcal{T}^Y _{s}}\mathbb{E}_{s,x}\Big[e^{-r\tau^{\hat{\delta}}} f(Y_{\tau^{\hat{\delta}}})-e^{-r\tau^{\hat{\delta}}} f(Y_{\tau^{\hat{\delta}}})1_{\{ \tau\le \overline{T} \}}\Big]\bigg|+\bigg| \sup_{\tau\in \widetilde{\mathcal{T}} _{s}}\mathbb{E}_{s,x}\Big[e^{-r\tau^{\hat{\delta}}} f(Y_{\tau^{\hat{\delta}}})1_{\{ \tau\le \overline{T} \}}-e^{-r\tau^{\hat{\delta}}} f(X_{\tau^{\hat{\delta}}})1_{\{ \tau\le \overline{T} \}}\Big]\bigg|\\
        &\; \;\;\;+ \bigg| \sup_{\tau\in \mathcal{T}^X _{s}}\mathbb{E}_{s,x}\Big[e^{-r\tau^{\hat{\delta}}} f(X_{\tau^{\hat{\delta}}})1_{\{ \tau\le \overline{T} \}}-e^{-r\tau^{\hat{\delta}}} f(X_{\tau^{\hat{\delta}}}) \Big]\bigg|,
\end{align}
where $\widetilde{\mathcal{T}}_{s}$ is the set of $\mathrm {H}$ stopping times taking values in $[s,\infty]$.
Then we can use the same arguments as before and show that $\hat{c}_f^{\hat{\delta}}(s,x)\rightarrow \hat{c}^{\hat{\delta}}(s,x)$ as $n\rightarrow \infty$ for any fixed $\overline{T}$.

Now we show that $\hat{c}^{\hat{\delta}}(s,x)\rightarrow c^{\hat{\delta}}(s,x)$ as $\delta_t\rightarrow 0$. Let $T^{\delta_t}=\inf \{t\ge 0: \zeta_t=T \}$, which follows a Gamma distribution with mean $T$ and $T^{\delta_t}\rightarrow T$ as $\delta_t\rightarrow 0$. We note that,
\begin{align}
    \sup_{\tau\in \mathcal{T}^{\zeta,X} _{s}}\mathbb{E}_{s,x}\Big[e^{-r(\tau^{\hat{\delta}} - s)} f(X_{\tau^{\hat{\delta}}})1_{\{ \zeta_{\tau}\le T \}} \Big]&= \sup_{\tau\in \mathcal{T}^{\zeta,X} _{s}}\mathbb{E}_{s,x}\Big[e^{-r(\tau^{\hat{\delta}} - s)} f(X_{\tau^{\hat{\delta}}})1_{\{ \tau\le T^{\delta_t} \}} \Big]\\
    &=  \mathbb{E}_{s,x} \bigg[\sup_{\tau\in \mathcal{T}^{X} _{s}}\mathbb{E}_{s,x}\Big[e^{-r(\tau^{\hat{\delta}} - s)} f(X_{\tau^{\hat{\delta}}})1_{\{ \tau\le T^{\delta_t} \}}\Big| T^{\delta_t} \Big]   \bigg].
\end{align}
For the quantity above, $\sup_{\tau\in \mathcal{T}^X _{s}}\mathbb{E}_{s,x}\Big[e^{-r(\tau^{\hat{\delta}} - s)} f(X_{\tau^{\hat{\delta}}})1_{\{ \tau\le T^{\delta_t} \}}\Big| T^{\delta_t} \Big]$ is the value function of a finite-maturity Bermudan option with maturity $T^{\delta_t}$. As $\delta_t\rightarrow 0$, 
\begin{align}
    \mathbb{E}_{s,x} \bigg[\sup_{\tau\in \mathcal{T}^X _{s}}\mathbb{E}_{s,x}\Big[e^{-r(\tau^{\hat{\delta}} - s)} f(X_{\tau^{\hat{\delta}}})1_{\{ \tau\le T^{\delta_t} \}}\Big| T^{\delta_t} \Big]   \bigg] &\rightarrow  \mathbb{E}_{s,x} \bigg[\sup_{\tau\in \mathcal{T}^X _{s}}\mathbb{E}_{s,x}\Big[e^{-r(\tau^{\hat{\delta}} - s)} f(X_{\tau^{\hat{\delta}}})1_{\{ \tau\le T \}}\Big| T \Big]   \bigg]\\
    &=  \sup_{\tau\in \mathcal{T}^X _{s}}\mathbb{E}_{s,x}\Big[e^{-r(\tau^{\hat{\delta}} - s)} f(X_{\tau^{\hat{\delta}}})1_{\{ \tau\le T \}}\Big].
\end{align}
Now we are ready to establish the claim (3) by collecting the intermediate estimates above:
    \begin{align}
    \Big|c_f^{\hat{\delta}} (s,x)-c^{\hat{\delta}} (s,x)\Big|
    &= \Big|c_f^{\hat{\delta}} (s,x)-\hat{c}_f^{\hat{\delta}} (s,x)+\hat{c}_f^{\hat{\delta}} (s,x)-\hat{c}^{\hat{\delta}} (s,x)+\hat{c}^{\hat{\delta}} (s,x)-c^{\hat{\delta}} (s,x) \Big| \\
    &\leq  \Big|c_f^{\hat{\delta}} (s,x)-\hat{c}_f^{\hat{\delta}} (s,x)\Big|+ \Big|\hat{c}_f^{\hat{\delta}} (s,x)-\hat{c}^{\hat{\delta}} (s,x)\Big|+\Big|\hat{c}^{\hat{\delta}} (s,x)-c^{\hat{\delta}} (s,x) \Big| \to 0,
    \end{align}
    as $n\rightarrow \infty$ and $\delta_t\rightarrow 0$ for any fixed $\hat{\delta}$.

    Finally, we note that
     \begin{align}
     \big| c^{\hat{\delta}}_f(s,x)-c^{\hat{\delta}}(s,x)\big|
     \leq \Big|c_f^{\hat{\delta}} (s,x)-\hat{c}_f^{\hat{\delta}} (s,x)\Big|+ \Big|\hat{c}_f^{\hat{\delta}} (s,x)-\hat{c}^{\hat{\delta}} (s,x)\Big|+\Big|\hat{c}^{\hat{\delta}} (s,x)-c^{\hat{\delta}} (s,x) \Big|.
     \end{align}
   Then the proof is concluded by combining the claims (1), (2) and (3).
\end{proof}



\begin{proof}[Proof of Theorem \ref{thm:finite-down-in-Amer-Pari-option-converge}]
    We note that
    \[
    \begin{aligned}
        \sup_{\tau \in \mathcal{T}_t^{\zeta,Y}}\mathbb{E}_{t,x} \big[ e^{-r(\zeta_{\tau} - t)}  f( Y_\tau) 1_{\{ \tau_{L, D}^{Y,-} \le \tau, \zeta_{\tau} \le T \}} \big]
        &=\mathbb{E}_{t,x}\big[\sup_{\tau\in \mathcal{T}_t^{\zeta,Y}}\mathbb{E}_{t,x}\big[e^{-r(\zeta_{\tau} - t)}  f( Y_{\tau}) 1_{\{\zeta_{\tau} \le T \}}1_{\{\tau\ge \tau_{L, D}^{Y,-} \}}|\tau_{L, D}^{Y,-}\big] \big],
    \end{aligned}
    \]
    where $\mathcal{T}_t^{\zeta,Y}$ is the set of stopping times taking values in $[t,\infty]$. 

    For the above, $\sup_{\tau\in \mathcal{T}_t^{\zeta,Y}}\mathbb{E}_{t,x}\big[e^{-r(\zeta_{\tau} - t)}  f( Y_{\tau}) 1_{\{\zeta_{\tau} \le T \}}1_{\{\tau\ge \tau_{L, D}^{Y,-} \}}|\tau_{L, D}^{Y,-}\big]$ is the approximate value function of a finite-maturity American option with initial time $\tau_{L, D}^{Y,-}$. Then by Proposition \ref{prop:finite-American-option-converge} and Proposition \ref{prop:parisian-stopping-time-weak-convergence}, we have
    \[
    \begin{aligned}
        &\mathbb{E}_{t,x}\big[\sup_{\tau\in \mathcal{T}_t^{\zeta,Y}}\mathbb{E}_{t,x}\big[e^{-r(\zeta_{\tau} - t)}  f( Y_{\tau}) 1_{\{\zeta_{\tau} \le T \}}1_{\{\tau\ge \tau_{L, D}^{Y,-} \}}|\tau_{L, D}^{Y,-}\big] \big] \\
        &\rightarrow \mathbb{E}_{t,x}\big[\sup_{\tau\in \mathcal{T}_t^X}\mathbb{E}_{t,x}\big[e^{-r(\tau - t)}  f( X_{\tau}) 1_{\{\tau \le T \}}1_{\{\tau\ge \tau_{L, D}^{X,-} \}}|\tau_{L, D}^{X,-}\big] \big]\quad (n\rightarrow \infty, \delta_t\rightarrow 0)\\
        &=\sup_{\tau \in \mathcal{T}_t^X}\mathbb{E}_{t,x} \big[ e^{-r(\tau - t)}  f( X_{\tau}) 1_{\{\tau \le T \}}1_{\{\tau\ge \tau_{L, D}^{X,-} \}} \big].
    \end{aligned}
    \]
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:finite-down-out-Amer-Pari-option-converge}]
We will first prove the following claims:

(1) There exists some constant $\widetilde{C}$ independent of $\hat{\delta}$, $n$, $\delta_d$ and $\delta_t$ such that
\[
\Big|\overline{C}_{fo}(s,d,x)-\overline{C}^{\hat{\delta}}_{fo}(s,d,x)\Big|\le \widetilde{C}\hat{\delta}^{\frac{1}{2}}.
\]

(2) There exists some constant $\widetilde{D}$ independent of $\hat{\delta}$, $n$, $\delta_d$ and $\delta_t$ such that
\[
\Big|C_{fo}(s,d,x)-C_{fo}^{\hat{\delta}}(s,d,x)\Big|\le \widetilde{D}\hat{\delta}^{\frac{1}{2}}.
\]

(3) We consider an arbitrary fixed $\hat{\delta}$. Let $\widetilde{\mathrm {H}}$ be the filtration generated by the process $(X, Y,D )$. Let $\tau^{\bar{\delta},-}=\sup\{ t< \tau: t\in \mathbb{T}^{\bar{\delta}}\}$ with $\mathbb{T}^{\bar{\delta}}=\left \{i\bar{\delta}: i\in \mathbb{N}  \right \} $ for some stopping time $\tau$. We set $\bar{\delta}=\frac{T-s}{2^m}$ for some $m\in \mathbb{N}$. For the quantities
\[
\widehat{C}_{fo}^{\hat{\delta}} (s,d,x)=\sup_{\tau\in \widetilde{\mathcal{T}} _{s}}\mathbb{E}_{s,d,x}\Big[e^{-r(\tau^{\hat{\delta}}-s)}f(X_{\tau^{\hat{\delta}}})1_{\{\tau\le T  \}}1_{\{ \tau\le \widetilde{\tau}_{L, D}^{Y,-}\}}\Big],
\]
\[
{C}_{fo}^{\hat{\delta},-} (s,d,x)=\sup_{\tau\in \widetilde{\mathcal{T}} _{s}}\mathbb{E}_{s,d,x}\Big[e^{-r(\tau^{\hat{\delta}}-s)}f(X_{\tau^{\hat{\delta}}})1_{\{\tau\le T  \}}1_{\{ \tau^{\bar{\delta},-}\le \widetilde{\tau}_{L, D}^{Y,-}\}}\Big]
\]
and
\[
\overline{C}_{fo}^{\hat{\delta},-} (s,d,x)=\sup_{\tau\in \widetilde{\mathcal{T}}^X _{s}}\mathbb{E}_{s,d,x}\Big[e^{-r(\tau^{\hat{\delta}}-s)}f(X_{\tau^{\hat{\delta}}})1_{\{\tau\le T  \}}1_{\{ \tau^{\bar{\delta},-}\le \widetilde{\tau}_{L, D}^{X,-}\}}\Big], 
\]
where $\widetilde{\mathcal{T}}^X _{s}$ is the set of $\widetilde{\mathrm{F}}^X$ stopping times taking values in $[s,\infty]$. For any $\epsilon>0$, there exists a $\bar{\delta}_{\epsilon}$ independent of $\delta_d$, $\hat{\delta}$ and $n$ such that for $\bar{\delta}<\bar{\delta}_{\epsilon}$, 
\[
\max\Big\{\big|\overline{C}_{fo}^{\hat{\delta},-} (s,d,x)-\overline{C}_{fo}^{\hat{\delta}} (s,d,x)\big|, \big|\widehat{C}_{fo}^{\hat{\delta}} (s,d,x)- {C}_{fo}^{\hat{\delta},-} (s,d,x) \big|   \Big\}<\epsilon.
\]
Moreover, for any fixed $\bar{\delta}$, 
\[
{C}_{fo}^{\hat{\delta},-} (s,d,x)\rightarrow \overline{C}_{fo}^{\hat{\delta},-} (s,d,x)
\]
as $\delta_d\rightarrow 0$ and $n\rightarrow \infty$. 

(4) For any fixed $\hat{\delta}$, as $\delta_t \to 0$ and $n\rightarrow \infty$, 
\[
C^{\hat{\delta}}_{fo}(s,d,x)\rightarrow \widehat{C}_{fo}^{\hat{\delta}} (s,d,x).
\] 

We will show the proof details for (3) and (4). The proofs of (1) and (2) are similar to those in the proof of Proposition \ref{prop:finite-American-option-converge}.


Proof of (3):  
We first show that $\overline{C}_{fo}^{\hat{\delta},-} (s,d,x)\rightarrow \overline{C}_{fo}^{\hat{\delta}} (s,d,x)$ as $\bar{\delta}\rightarrow 0$.
\begin{align}
    &\Big|\overline{C}_{fo}^{\hat{\delta}} (s,d,x)-\overline{C}_{fo}^{\hat{\delta},-} (s,d,x) \Big|\\
    &\leq \bigg|\sup_{\tau\in \widetilde{\mathcal{T}}^X _{s}}\mathbb{E}_{s,d,x}\Big[e^{-r(\tau^{\hat{\delta}}-s)}f(X_{\tau^{\hat{\delta}}})1_{\{\tau\le T  \}}1_{\{ \tau\le \widetilde{\tau}_{L, D}^{X,-}\}}-e^{-r(\tau^{\hat{\delta}}-s)}f(X_{\tau^{\hat{\delta}}})1_{\{\tau\le T  \}}1_{\{ \tau^{\bar{\delta},-}\le \widetilde{\tau}_{L, D}^{X,-}\}}\Big]\bigg|\\
    &\leq  C \bigg|\sup_{t\in [s,T]}\mathbb{E}_{s,d,x}\Big[1_{\{ t\le \widetilde{\tau}_{L, D}^{X,-}\}}-1_{\{ t^{\bar{\delta},-}\le \widetilde{\tau}_{L, D}^{X,-}\}}\Big]\bigg|\\
    &= C \sup_{t\in [s,T]}\bigg|\mathbb{P}\Big(t\le \widetilde{\tau}_{L, D}^{X,-}\Big)-\mathbb{P}\Big(t^{\bar{\delta},-}\le \widetilde{\tau}_{L, D}^{X,-}\Big)\bigg|\\
   & =  C \sup_{t\in [s,T]\cap \mathbb{T}^{\bar{\delta}}}\bigg(\mathbb{P}\Big(t-\bar{\delta}\le \widetilde{\tau}_{L, D}^{X,-}\Big)-\mathbb{P}\Big(t\le \widetilde{\tau}_{L, D}^{X,-}\Big)\bigg)\\
    &=  C \sup_{t\in [s,T]\cap \mathbb{T}^{\bar{\delta}}}\mathbb{P}\Big(t-\bar{\delta}\le \widetilde{\tau}_{L, D}^{X,-}<t\Big).
\end{align}
The reason for the above is that $\mathbb{P}\big(t\le \widetilde{\tau}_{L, D}^{X,-}\big)$ decreases as $t$ increases and hence by the definition of $t^{\bar{\delta},-}$, the maximum value of the difference in probabilities occurs in $t\in [s,T]\cap \mathbb{T}^{\bar{\delta}}$. Therefore, for any $\epsilon>0$, there exists an $m_{\epsilon}\in \mathbb{N}$ such that for all $\frac{T-s}{2^m}=\bar{\delta}<\bar{\delta}_{\epsilon}=\frac{T-s}{2^{m_{\epsilon}}}$, 
\begin{align}
\sup_{t\in [s,T]\cap \mathbb{T}^{\bar{\delta}}}\mathbb{P}\Big(t-\bar{\delta}\le \widetilde{\tau}_{L, D}^{X,-}<t\Big)<\sup_{t\in [s,T]\cap \mathbb{T}^{\bar{\delta}_{\epsilon}}}\mathbb{P}\Big(t-\bar{\delta}_{\epsilon}\le \widetilde{\tau}_{L, D}^{X,-}<t\Big)\le \epsilon,
\end{align}
which implies that claim to prove. With the same arguments, we can show that ${C}_{fo}^{\hat{\delta},-} (s,d,x)\rightarrow \widehat{C}_{fo}^{\hat{\delta}} (s,d,x)$ as $\bar{\delta}\rightarrow 0$. 

Then we will show that for any fixed $\bar{\delta}$, ${C}_{fo}^{\hat{\delta},-} (s,d,x)\rightarrow \overline{C}_{fo}^{\hat{\delta},-} (s,d,x)$ as $\delta_d\rightarrow 0$ and $n\rightarrow \infty$. The arguments are as follows:
\begin{align}
    &\Big|{C}_{fo}^{\hat{\delta},-} (s,d,x)-\overline{C}_{fo}^{\hat{\delta},-} (s,d,x)  \Big|\\
    &\leq  \bigg|\sup_{\tau\in \widetilde{\mathcal{T}} _{s}}\mathbb{E}_{s,d,x}\Big[ e^{-r(\tau^{\hat{\delta}}-s)}f(X_{\tau^{\hat{\delta}}})1_{\{\tau\le T  \}}1_{\{ \tau^{\bar{\delta},-}\le \widetilde{\tau}_{L, D}^{Y,-}\}}-e^{-r(\tau^{\hat{\delta}}-s)}f(X_{\tau^{\hat{\delta}}})1_{\{\tau\le T  \}}1_{\{ \tau^{\bar{\delta},-}\le \widetilde{\tau}_{L, D}^{X,-}\}}\Big]\bigg|\\
    &\leq  C \sup_{t\in [s-\bar{\delta},T-\bar{\delta}]\cap \mathbb{T}^{\bar{\delta}}}\bigg| \mathbb{P}\Big(t\le \widetilde{\tau}_{L, D}^{Y,-}\Big)- \mathbb{P}\Big( t\le \widetilde{\tau}_{L, D}^{X,-} \Big) \bigg| \rightarrow  0,
\end{align}
as $\delta_d\rightarrow 0$ and $n\rightarrow \infty$ by Proposition \ref{prop:down-out-parisian-time-weak-convergence}. $\widetilde{\mathcal{T}} _{s}$ is the set of $\widetilde{\mathrm {H}}$ stopping times taking values in $[s,\infty]$.



Proof of (4): Let $\widetilde{\mathrm{H}}^{\zeta}$ be the filtration generated by the process $(\zeta, X, Y, D)$. We introduce the following intermediate quantities:
\[
\breve{C}_{fo}^{\hat{\delta}} (s,d,x)=\sup_{\tau \in \widetilde{\mathcal{T}}^{\zeta,Y}_{s}} \mathbb{E}_{s,d,x} \Big[ e^{-r(\tau^{\hat{\delta}} - s)} f(Y_{\tau^{\hat{\delta}}})1_{\{ \zeta_{\tau}\le T \}}1_{\{ \tau\le \widetilde{\tau}_{L, D}^{Y, -} \}} \Big],
\]
\[
\overrightarrow{C}_{fo}^{\hat{\delta}} (s,d,x)=\sup_{\tau \in \widetilde{\mathcal{T}}^\zeta_{s}} \mathbb{E}_{s,d,x} \Big[ e^{-r(\tau^{\hat{\delta}} - s)} f(X_{\tau^{\hat{\delta}}})1_{\{ \zeta_{\tau}\le T \}}1_{\{ \tau\le \widetilde{\tau}_{L, D}^{Y, -} \}} \Big],
\]
where $\widetilde{\mathcal{T}}^{\zeta,Y}_{s}$ and $\widetilde{\mathcal{T}}^\zeta_{s}$ are the sets of $\widetilde{\mathrm{F}}^{\zeta, Y}$ stopping times and $\widetilde{\mathrm{H}}^{\zeta}$ stopping times, respectively, taking values in $[s,\infty]$. With the same arguments in the proof of Proposition \ref{prop:finite-American-option-converge}, we can show that $C^{\hat{\delta}}_{fo}(s,d,x)\rightarrow \breve{C}_{fo}^{\hat{\delta}} (s,d,x)$ as $\delta_t\rightarrow 0$, and $\breve{C}_{fo}^{\hat{\delta}} (s,d,x)\rightarrow \overrightarrow{C}_{fo}^{\hat{\delta}} (s,d,x)$ as $n\rightarrow \infty$. 

Next we show that $\overrightarrow{C}_{fo}^{\hat{\delta}} (s,d,x)\rightarrow \widehat{C}_{fo}^{\hat{\delta}} (s,d,x)$ as $\delta_t \rightarrow 0$.
\begin{align}
    \overrightarrow{C}_{fo}^{\hat{\delta}} (s,d,x)
    &=\sup_{\tau \in \widetilde{\mathcal{T}}^\zeta_{s}} \mathbb{E}_{s,d,x} \Big[ e^{-r(\tau^{\hat{\delta}} - s)} f(X_{\tau^{\hat{\delta}}})1_{\{ \tau\le T^{\delta_t} \}}1_{\{ \tau\le \widetilde{\tau}_{L, D}^{Y, -} \}} \Big]\\
    &= \mathbb{E}_{s,d,x} \bigg[ \sup_{\tau \in \mathcal{T}^X_{s}} \mathbb{E}_{s,d,x} \Big[ e^{-r(\tau^{\hat{\delta}} - s)} f(X_{\tau^{\hat{\delta}}})1_{\{ \tau\le T^{\delta_t} \}}1_{\{ \tau\le \widetilde{\tau}_{L, D}^{Y, -} \}} \Big|T^{\delta_t}, \widetilde{\tau}_{L, D}^{Y, -}  \Big]  \bigg]\\
    &=  \mathbb{E}_{s,d,x} \bigg[ \sup_{\tau \in \mathcal{T}^X_{s}} \mathbb{E}_{s,d,x} \Big[ e^{-r(\tau^{\hat{\delta}} - s)} f(X_{\tau^{\hat{\delta}}})1_{\{ \tau\le \widetilde{\tau}_{L, D}^{Y, -} \}} \Big|T^{\delta_t}, \widetilde{\tau}_{L, D}^{Y, -}  \Big]1_{\{ \widetilde{\tau}_{L, D}^{Y, -}\le T^{\delta_t} \}}\\
    &\;\;\;\; + \sup_{\tau \in \mathcal{T}^X_{s}} \mathbb{E}_{s,d,x} \Big[ e^{-r(\tau^{\hat{\delta}} - s)} f(X_{\tau^{\hat{\delta}}})1_{\{ \tau\le T^{\delta_t}\}} \Big|T^{\delta_t}, \widetilde{\tau}_{L, D}^{Y, -}  \Big]1_{\{ \widetilde{\tau}_{L, D}^{Y, -}> T^{\delta_t} \}} \bigg]\\
    &= \mathbb{E}_{s,d,x} \bigg[ \sup_{\tau \in \mathcal{T}^X_{s}} \mathbb{E}_{s,d,x} \Big[ e^{-r(\tau^{\hat{\delta}} - s)} f(X_{\tau^{\hat{\delta}}})1_{\{ \tau\le \widetilde{\tau}_{L, D}^{Y, -} \}} \Big|T^{\delta_t}, \widetilde{\tau}_{L, D}^{Y, -}  \Big]1_{\{ \widetilde{\tau}_{L, D}^{Y, -}\le T^{\delta_t} \}}\bigg]\\
    &\;\;\;\; + \mathbb{E}_{s,d,x} \bigg[\sup_{\tau \in \mathcal{T}^X_{s}} \mathbb{E}_{s,d,x} \Big[ e^{-r(\tau^{\hat{\delta}} - s)} f(X_{\tau^{\hat{\delta}}})1_{\{ \tau\le T^{\delta_t}\}} \Big|T^{\delta_t}, \widetilde{\tau}_{L, D}^{Y, -}  \Big]1_{\{ \widetilde{\tau}_{L, D}^{Y, -}> T^{\delta_t} \}} \bigg]\\
    &= \mathbb{E}_{s,d,x} \Big[ V\big( \widetilde{\tau}_{L, D}^{Y, -}, s,d,x\big)1_{\{ \widetilde{\tau}_{L, D}^{Y, -}\le T^{\delta_t} \}}\Big]+\mathbb{E}_{s,d,x} \Big[ V\big( T^{\delta_t}, s,d,x\big)1_{\{ T^{\delta_t}<  \widetilde{\tau}_{L, D}^{Y, -} \}}\Big]
\end{align}
Here $V\big(T,s,d,x\big)=\sup_{\tau \in \mathcal{T}^X_{s}} \mathbb{E}_{s,d,x} \Big[ e^{-r(\tau^{\hat{\delta}} - s)} f(X_{\tau^{\hat{\delta}}})1_{\{ \tau\le T \}} \Big]$ is the value function of a finite maturity Bermudan option with maturity $T$. Suppose that $\mathbb{P}\big[\widetilde{\tau}_{L, D}^{Y, -}=T \big]=0$ for any $T>0$. Because $T^{\delta_t}\rightarrow T$ as $\delta_t\rightarrow 0$, we have that 
\[
\mathbb{E}_{s,d,x} \Big[ V\big( \widetilde{\tau}_{L, D}^{Y, -}, s,d,x\big)1_{\{ \widetilde{\tau}_{L, D}^{Y, -}\le T^{\delta_t} \}}\Big]\rightarrow \mathbb{E}_{s,d,x} \Big[ V\big( \widetilde{\tau}_{L, D}^{Y, -}, s,d,x\big)1_{\{ \widetilde{\tau}_{L, D}^{Y, -}\le T \}}\Big]
\]
and
\[
\mathbb{E}_{s,d,x} \Big[ V\big( T^{\delta_t}, s,d,x\big)1_{\{ T^{\delta_t}<  \widetilde{\tau}_{L, D}^{Y, -} \}}\Big]\rightarrow \mathbb{E}_{s,d,x} \Big[ V\big( T, s,d,x\big)1_{\{ T<  \widetilde{\tau}_{L, D}^{Y, -} \}}\Big]
\]
as $\delta_t\rightarrow 0$. Note that 
\begin{align}
   &\mathbb{E}_{s,d,x} \Big[ V\big( \widetilde{\tau}_{L, D}^{Y, -}, s,d,x\big)1_{\{ \widetilde{\tau}_{L, D}^{Y, -}\le T \}}\Big]+\mathbb{E}_{s,d,x} \Big[ V\big( T, s,d,x\big)1_{\{ T<  \widetilde{\tau}_{L, D}^{Y, -} \}}\Big]\\
    &=  \mathbb{E}_{s,d,x} \bigg[ \sup_{\tau \in \mathcal{T}_{s}^X} \mathbb{E}_{s,d,x} \Big[ e^{-r(\tau^{\hat{\delta}} - s)} f(X_{\tau^{\hat{\delta}}})1_{\{ \tau\le \widetilde{\tau}_{L, D}^{Y, -} \}} \Big|T, \widetilde{\tau}_{L, D}^{Y, -}  \Big]1_{\{ \widetilde{\tau}_{L, D}^{Y, -}\le T \}}\\
    &\;\;\;\;  + \sup_{\tau \in \mathcal{T}^X_{s}} \mathbb{E}_{s,d,x} \Big[ e^{-r(\tau^{\hat{\delta}} - s)} f(X_{\tau^{\hat{\delta}}})1_{\{ \tau\le T  \}}\Big|T, \widetilde{\tau}_{L, D}^{Y, -}\Big]1_{\{ \widetilde{\tau}_{L, D}^{Y, -}> T\}}\bigg]\\
    &=  \mathbb{E}_{s,d,x} \bigg[ \sup_{\tau \in \mathcal{T}^X_{s}} \mathbb{E}_{s,d,x} \Big[ e^{-r(\tau^{\hat{\delta}} - s)} f(X_{\tau^{\hat{\delta}}})1_{\{ \tau\le T  \}}1_{\{ \tau\le \widetilde{\tau}_{L, D}^{Y, -} \}} \Big|T, \widetilde{\tau}_{L, D}^{Y, -}  \Big]1_{\{ \widetilde{\tau}_{L, D}^{Y, -}\le T \}}\\
    & \;\;\;\; + \sup_{\tau \in \mathcal{T}^X_{s}} \mathbb{E}_{s,d,x} \Big[ e^{-r(\tau^{\hat{\delta}} - s)} f(X_{\tau^{\hat{\delta}}})1_{\{ \tau\le T  \}}1_{\{ \tau\le \widetilde{\tau}_{L, D}^{Y, -} \}}\Big|T, \widetilde{\tau}_{L, D}^{Y, -}\Big]1_{\{ \widetilde{\tau}_{L, D}^{Y, -}> T\}}\bigg]\\
    &=  \mathbb{E}_{s,d,x} \bigg[ \sup_{\tau \in \mathcal{T}^X_{s}} \mathbb{E}_{s,d,x} \Big[ e^{-r(\tau^{\hat{\delta}} - s)} f(X_{\tau^{\hat{\delta}}})1_{\{ \tau\le T  \}}1_{\{ \tau\le \widetilde{\tau}_{L, D}^{Y, -} \}} \Big|T, \widetilde{\tau}_{L, D}^{Y, -}  \Big]\bigg]\\
    &=  \widehat{C}_{fo}^{\hat{\delta}} (s,d,x).
\end{align}
Therefore, we have that $\overrightarrow{C}_{fo}^{\hat{\delta}} (s,d,x)\rightarrow \widehat{C}_{fo}^{\hat{\delta}} (s,d,x)$ as $\delta_t \rightarrow 0$. 

We further note that
\begin{align}
    &\Big| \widehat{C}_{fo}^{\hat{\delta}} (s,d,x)-C^{\hat{\delta}}_{fo}(s,d,x) \Big|\\
    &\leq  \Big|\widehat{C}^{\hat{\delta}}_{fo}(s,d,x)-\overrightarrow{C}_{fo}^{\hat{\delta}} (s,d,x)\Big| + \Big| \overrightarrow{C}_{fo}^{\hat{\delta}} (s,d,x)-\breve{C}_{fo}^{\hat{\delta}} (s,d,x)\Big| +  \Big|\breve{C}_{fo}^{\hat{\delta}} (s,d,x)-{C}_{fo}^{\hat{\delta}} (s,d,x)\Big|.
\end{align}
Combining the results obtained to the above and we conclude that
\[
\Big| \widehat{C}_{fo}^{\hat{\delta}} (s,d,x)-C^{\hat{\delta}}_{fo}(s,d,x) \Big|\rightarrow 0
\]
as $\delta_t\rightarrow 0$ and $n\rightarrow \infty$ for any fixed $\hat{\delta}$.

Finally, we note that
    \[
    \begin{aligned}
    &\Big|C_{fo}(s,d,x)-\overline{C}_{fo}(s,d,x)\Big|\\
    &\leq  \Big|C_{fo}(s,d,x)-C^{\hat{\delta}}_{fo}(s,d,x)\Big|+\Big|C^{\hat{\delta}}_{fo}(s,d,x)-\widehat{C}_{fo}^{\hat{\delta}} (s,d,x)\Big|+\Big|\widehat{C}_{fo}^{\hat{\delta}} (s,d,x)-{C}_{fo}^{\hat{\delta},-} (s,d,x)\Big|\\
    &  \; \; \; \;    + \Big|{C}_{fo}^{\hat{\delta},-} (s,d,x)-\overline{C}_{fo}^{\hat{\delta},-} (s,d,x)\Big|+\Big|\overline{C}_{fo}^{\hat{\delta},-} (s,d,x)-\overline{C}_{fo}^{\hat{\delta}} (s,d,x)\Big|+\Big|\overline{C}_{fo}^{\hat{\delta}} (s,d,x)-\overline{C}_{fo}(s,d,x)\Big|.
    \end{aligned}
    \]
    Then the proof of Theorem \ref{thm:finite-down-out-Amer-Pari-option-converge} is concluded by combining the claims (1), (2), (3) and (4).  
\end{proof}


\begin{proof}[Proof of Lemma \ref{lem:perpetual-down-out-American-option-intermedia}]
    \[
    \begin{aligned}
        &\big| \overline{C}_{fo}(0,d,x)-\overline{C}^{\hat{\delta}}_{po}(d,x)\big|\\
        &=\sup _{\tau \in \widetilde{\mathcal{T}}^X}\mathbb{E}_{d, x}\big[e^{-r\tau^{\hat{\delta}}} f(X_{\tau^{\hat{\delta}}})1_{\{ \tau\le \widetilde{\tau}_{L, D}^{X,-} \}} \big]-\sup _{\tau \in \widetilde{\mathcal{T}}^X_{0,T}} \mathbb{E}_{0,d, x}\left[e^{-r\tau^{\hat{\delta}}} f\left(X_{\tau^{\hat{\delta}}}\right) 
 1_{\{ \tau\le \widetilde{\tau}_{L, D}^{X,-} \}} \right]\\
 &\leq  \sup _{\tau \in \widetilde{\mathcal{T}}^X_{0,T}} \mathbb{E}_{0,d, x}\left[e^{-r\tau^{\hat{\delta}}} f\left(X_{\tau^{\hat{\delta}}}\right) 
 1_{\{ \tau\le \widetilde{\tau}_{L, D}^{X,-} \}} \right]+\sup _{\tau \in \widetilde{\mathcal{T}}^X\setminus \widetilde{\mathcal{T}}^X_{0,T}} \mathbb{E}_{0,d, x}\left[e^{-r\tau^{\hat{\delta}}} f\left(X_{\tau^{\hat{\delta}}}\right) 
 1_{\{ \tau\le \widetilde{\tau}_{L, D}^{X,-} \}} \right]\\
 &\;\;\;\;-\sup _{\tau \in \widetilde{\mathcal{T}}^X_{0,T}} \mathbb{E}_{0,d, x}\left[e^{-r\tau^{\hat{\delta}}} f\left(X_{\tau^{\hat{\delta}}}\right) 
 1_{\{ \tau\le \widetilde{\tau}_{L, D}^{X,-} \}} \right]\\
 &=\sup _{\tau \in \widetilde{\mathcal{T}}^X\setminus \widetilde{\mathcal{T}}^X_{0,T}} \mathbb{E}_{0,d, x}\left[e^{-r\tau^{\hat{\delta}}} f\left(X_{\tau^{\hat{\delta}}}\right) 
 1_{\{ \tau\le \widetilde{\tau}_{L, D}^{X,-} \}} \right].
    \end{aligned}
    \]

    By Assumption \ref{assump:payoff-growth}, there exists a $T_\epsilon$, such that for any $\tau^{\hat{\delta}}>T_\epsilon>T$, $\big| e^{-r\tau^{\hat{\delta}}} f\left(X_{\tau^{\hat{\delta}}}\right)\big|<\epsilon$, and 
    \[
    \begin{aligned}
        \big| \overline{C}_{fo}(0,d,x)-\overline{C}^{\hat{\delta}}_{po}(d,x)\big|
        &\leq  \sup _{\tau \in \widetilde{\mathcal{T}}^X\setminus \widetilde{\mathcal{T}}^X_{0,T}} \mathbb{E}_{0,d, x}\left[e^{-r\tau^{\hat{\delta}}} f\left(X_{\tau^{\hat{\delta}}}\right) 
 1_{\{ \tau\le \widetilde{\tau}_{L, D}^{X,-} \}} \right]\\
 &< \epsilon \sup _{\tau \in \widetilde{\mathcal{T}}^X\setminus \widetilde{\mathcal{T}}^X_{0,T}} \mathbb{E}_{0,d, x}\left[
 1_{\{ \tau\le \widetilde{\tau}_{L, D}^{X,-} \}} \right] \leq \epsilon.
    \end{aligned}
    \]

    Using similar arguments, we can show that $\big| \widetilde{C}^{\hat{\delta}}_{fo}(0,d,x)-C^{\hat{\delta}}_{po}(d,x)\big|<\epsilon$. This concludes the proof.
\end{proof}


\begin{proof}[Proof of Theorem \ref{thm:perpetual-down-out-Amer-Pari-option-converge}]
    We will first prove the following claims: 

    (1) There exists some constant $\widetilde{C}$ independent of $\hat{\delta}$, $n$ and $\delta_d$  such that
\[
\left|\overline{C}_{po}(d, x)-\overline{C}^{\hat{\delta}}_{po}(d, x)\right|\le \widetilde{C}\hat{\delta}^{\frac{1}{2}}
\]

(2) There exists some constant $\widetilde{D}$ independent of $\hat{\delta}$, $n$ and $\delta_d$ such that
\[
\left|C_{po}(d, x)-C^\delta_{po}(d, x)\right|\le \widetilde{D}\hat{\delta}^{\frac{1}{2}}
\]

(3) For any fixed $\hat{\delta}$, as $n\rightarrow \infty$ and $\delta_d\rightarrow 0$, we have 
\[
C_{po}^{\hat{\delta}}(d, x)\rightarrow \overline{C}_{po}^{\hat{\delta}}(d, x).
\]  

We will show details for (3). The proofs of (1) and (2) are similar to the proof of Proposition \ref{prop:perpetual-down-in-Amer-option-convergence}. 

Proof of (3): 
With the same arguments in the proof of Theorem \ref{thm:finite-down-out-Amer-Pari-option-converge}, we can show that $\big|\widetilde{C}^{\hat{\delta}}_{fo}(s,d,x)-\overline{C}^{\hat{\delta}}_{fo}(s,d,x)  \big|\rightarrow 0$ as $n\rightarrow \infty$ and $\delta_d\rightarrow 0$. Then we have 
\[
\begin{aligned}
    &\big| C_{po}^{\hat{\delta}}(d, x)- \overline{C}_{po}^{\hat{\delta}}(d, x) \big|\\
    &=  \big| C_{po}^{\hat{\delta}}(d, x)-\overline{C}_{po}^{\hat{\delta}}(d, x)+\widetilde{C}^{\hat{\delta}}_{fo}(0,d,x)-\widetilde{C}^{\hat{\delta}}_{fo}(0,d,x)+\overline{C}^{\hat{\delta}}_{fo}(0,d,x)-\overline{C}^{\hat{\delta}}_{fo}(0,d,x) \big|\\
    &\leq  \big|\overline{C}^{\hat{\delta}}_{fo}(0,d,x)- \overline{C}_{po}^{\hat{\delta}}(d, x) \big|+\big| \widetilde{C}^{\hat{\delta}}_{fo}(0,d,x)- C_{po}^{\hat{\delta}}(d, x)\big|+\big| \widetilde{C}^{\hat{\delta}}_{fo}(0,d,x)-\overline{C}^{\hat{\delta}}_{fo}(0,d,x)   \big|.
\end{aligned}
\]
By Lemma \ref{lem:perpetual-down-out-American-option-intermedia}, with the same arguments in the proof of Proposition \ref{prop:perpetual-down-in-Amer-option-convergence}, the claim (3) is proved.

Finally we note that,
\[
\begin{aligned}
    &\big| C_{po}(d, x)-\overline{C}_{po}(d, x) \big|\\
    &\leq  \big| C_{po}(d, x)-C^{\hat{\delta}}_{po}(d,x)  \big|+\big| C^{\hat{\delta}}_{po}(d,x)-\overline{C}^{\hat{\delta}}_{po}(d,x) \big|+\big|\overline{C}^{\hat{\delta}}_{po}(d,x)-\overline{C}_{po}(d, x)  \big|.
\end{aligned}
\]
Then the proof of Theorem \ref{thm:perpetual-down-out-Amer-Pari-option-converge} is concluded by combining the results in the claims (1), (2) and (3). 

\end{proof}




