    \label{fig:AlphaArea}
\end{figure}



\begin{figure}
    \centering
    \includegraphics[width=1\linewidth]{VariationofOverlappingRegionVertices_mu1mu2.pdf}
    \caption{Illustration of the most common overlapping region of coexistence in the $\mu_1-\mu_2$ plane from $k=15$ to $k=20$ for various values of parameter $\alpha$. In (a), the most common overlapping region of coexistence is shown denoting a six sided polygon for $\alpha = 0.65$. In (b), the most common overlapping region of coexistence is shown denoting a seven sided polygon for $\alpha = 0.6$. In (c), the most common overlapping region of coexistence is shown denoting a nine sided polygon for $\alpha = 0.7$. We observe that for minor change in parameter $\alpha$, the number of vertices of the most common overlapping polygon changes drastically.}
