\section{Preliminaries: the F-method}
\label{sec:Fmethod}

The aim of this section is to give a quick review on the F-method,
which plays a central role in this paper. In the next section 
we shall discuss the truncated symbol $\symb_0(\mathbb{D})$ 
of a DSBO $\mathbb{D}$. 
In this section we mainly take the expositions from \cite{Kubo24+, KuOr25a}.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Notation}\label{sec:prelim}

Let $G$ be a real reductive Lie group and $P=MAN_+ $ a Langlands decomposition of a parabolic subgroup $P$ of $G$. We denote by $\fg(\R)$ and 
$\fp(\R) = \fm(\R) \oplus \fa(\R) \oplus \fn_+(\R)$ the Lie algebras of $G$ and 
$P=MAN_+$, respectively.


 For a real Lie algebra $\f{y}(\R)$, we write $\f{y}$
and $\Cal{U}(\fy)$ for its complexification and the universal enveloping algebra of 
$\fy$, respectively. 
For instance, $\fg, \fp, \fm, \fa$, and $\fn_+$ are the complexifications of $\fg(\R), \fp(\R), \fm(\R), \fa(\R)$, and $\fn_+(\R)$, 
respectively.

For $\lambda \in \fa^* \simeq \Hom_\R(\fa(\R),\C)$,
we denote by $\C_\lambda$ 
the one-dimensional representation of $A$ defined by 
$a\mapsto a^\lambda:=e^{\lambda(\log a)}$. 
For a finite-dimensional irreducible 
representation $(\xi, V)$ of $M$ and $\lambda \in \fa^*$,
we denote by $\xi_\lambda$ the outer tensor product 
representation $\xi \boxtimes \C_\lambda$
on $V$,
namely, 
$\xi_\lambda \colon
ma \mapsto a^\lambda\xi(m)$. By letting $N_+$ act trivially, we regard 
$\xi_\lambda$ as a representation of $P$. Let $\Cal{V}:=G \times_P V \to G/P$
be the $G$-equivariant vector bundle over the real flag variety $G/P$
 associated with the 
representation $(\xi_\lambda, V)$ of $P$. We identify the Fr{\' e}chet space 
$C^\infty(G/P, \Cal{V})$ of smooth sections with 
\begin{equation*}
C^\infty(G, V)^P:=\{f \in C^\infty(G,V) : 
f(gp) = \xi_\lambda^{-1}(p)f(g)
\;\;
\text{for any $p \in P$}\},
\end{equation*}
the space of $P$-invariant smooth functions on $G$.
Then, via the left regular representation $L$ of $G$ on $C^\infty(G)$,
we realize the parabolically induced representation 
$\pi_{(\xi, \lambda)} = \Ind_{P}^G(\xi_\lambda)$ on $C^\infty(G/P, \Cal{V})$.
We denote by $R$ the right regular representation of $G$ on $C^\infty(G)$.

Let $G'$ be a reductive subgroup of $G$ and $P'=M'A'N_+'$ 
a parabolic subgroup of $G'$
with $P' \subset P$, $M'A' \subset MA$, and $N_+' \subset N_+$,
so that there is a natural morphism $p\colon G'/P' \to G/P$
from the real flag variety $G'/P'$ into $G/P$.

As for $G/P$, for a finite-dimensional irreducible
representation $(\varpi_\nu, W)$ of $M'A'$, we define
an induced representation $\pi'_{(\varpi, \nu)}=\Ind_{P'}^{G'}(\varpi_\nu)$ on the 
space $C^\infty(G'/P', \Cal{W})$ of smooth sections for the
$G'$-equivariant vector bundle $\Cal{W}:=G'\times_{P'}W \to G'/P'$.

Via the morphism $p\colon G'/P' \to G/P$, one can define 
differential operators $\bD\colon C^\infty(G/P, \Cal{V}) \to C^\infty(G'/P', \Cal{W})$
with respect to $p$
although $G/P$ and $G'/P'$ are different manifolds 
(see, for instance, \cite[Def.\ 2.1]{KP1}).
As $C^\infty(G/P, \Cal{V})$ is a $G$-representation and $G' \subset G$,
the space $C^\infty(G/P, \Cal{V})$ is also a $G'$-representation.
We then write $\Diff_{G'}(\Cal{V},\Cal{W})$ for the space of 
\emph{differential symmetry breaking operators} 
(differential $G'$-intertwining operators)
$\bD \colon C^\infty(G/P, \Cal{V}) \to C^\infty(G'/P', \Cal{W})$.
When $G=G'$ and $P=P'$, we also simply refer to 
them as \emph{differential intertwining operators}
(or intertwining differential operators).

Let 
$\mathfrak{g}(\R)=\mathfrak{n}_-(\R) \oplus \mathfrak{m}(\R) 
\oplus \mathfrak{a}(\R) \oplus \mathfrak{n}_+(\R)$ 
be the 
Gelfand--Naimark decomposition of $\mathfrak{g}(\R)$
with $\fp(\R) = \mathfrak{m}(\R) \oplus \mathfrak{a}(\R) \oplus \mathfrak{n}_+(\R)$,
and write $N_- = \exp(\fn_-(\R))$. We identify $N_-$ with the 
open Bruhat cell $N_-P$ of $G/P$ via the embedding 
$\iota\colon N_- \hookrightarrow G/P$, $\bar{n} \mapsto \bar{n}P$.
Via the restriction of the vector bundle $\Cal{V} \to G/P$ to the open Bruhat cell
$N_-\stackrel{\iota}{\hookrightarrow} G/P$,
we regard $C^\infty(G/P,\mathcal{V})$ as a subspace of 
$C^\infty(N_-) \otimes V$.

Likewise,
let 
$\mathfrak{g}'(\R)=\mathfrak{n}_-'(\R) \oplus \mathfrak{m}'(\R) 
\oplus \mathfrak{a}'(\R) \oplus \mathfrak{n}_+'(\R)$ 
be the
Gelfand--Naimark decomposition of $\mathfrak{g}'(\R)$ with
$\fp(\R)'= \mathfrak{m}'(\R) 
\oplus \mathfrak{a}'(\R) \oplus \mathfrak{n}_+'(\R)$,
and write $N_-' = \exp(\fn_-'(\R))$.
As for $C^\infty(G/P,\Cal{V})$, we regard $C^\infty(G'/P',\Cal{W})$
as a subspace of $C^\infty(N_-')\otimes W$.

We often view differential symmetry breaking operators
$\bD \colon
C^\infty(G/P,\mathcal{V})
\to C^\infty(G'/P',\mathcal{W})$
as differential operators 
$\w{\bD} \colon C^\infty(N_-) \otimes V
\to C^\infty(N_-') \otimes W$ 
%(in the sense of \cite[Def.\ 2.1]{KP1})
such that
the restriction $\w{\bD}\vert_{C^\infty(G/P,\mathcal{V})}$
to $C^\infty(G/P,\mathcal{V})$ is a map
$\w{\bD}\vert_{C^\infty(G/P,\mathcal{V})}\colon
C^\infty(G/P,\mathcal{V})
\to C^\infty(G'/P',\mathcal{W})$ (see \eqref{eqn:21} below).
\begin{equation}\label{eqn:21}
\begin{aligned}
\xymatrix{
C^\infty(N_-) \otimes V 
\ar[r]^{\w{\bD} } 
& C^\infty(N_-') \otimes W\\ 
C^\infty(G/P,\mathcal{V}) 
\;\; \ar[r]_{\stackrel{\phantom{a}}{\hspace{20pt}\bD=\w{\bD} \vert_{\small{C^\infty(G/P,\mathcal{V})}}} }
 \ar@{^{(}->}[u]^{\iota^*}
& \;\; C^\infty(G'/P',\mathcal{W}) \ar@{^{(}->}[u]_{\iota^*}
}
\end{aligned}
\end{equation}

\noindent
In particular, we often regard $\Diff_{G'}(\Cal{V},\Cal{W})$ as 
\begin{equation}\label{eqn:DN}
\Diff_{G'}(\Cal{V},\Cal{W}) \subset 
\Diff_\C(C^\infty(N_-)\otimes V, C^\infty(N_-')\otimes W).
\end{equation}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Duality theorem}\label{sec:duality}

For a finite-dimensional irreducible representation $(\xi_\lambda,V)$ of $MA$,
we write $V^\vee = \Hom_\C(V,\C)$ and $((\xi_\lambda)^\vee, V^\vee)$ for
the contragredient representation of $(\xi_\lambda,V)$. By letting $\fn_+$ act 
on $V^\vee$ trivially, we regard the infinitesimal representation 
$d\xi^\vee \boxtimes \C_{-\lambda}$ of $(\xi_\lambda)^\vee$ as a $\fp$-module. For a finite-dimensional irreducible representation 
$(\varpi_\nu, W)$ of $M'A'$, a $\fp'$-module 
$d\varpi^\vee \boxtimes \C_{-\nu}$ is defined similarly.
We write
\begin{equation*}
\Mp(V^\vee) = \Cal{U}(\fg)\otimes_{\Cal{U}(\fp)}V^\vee
\quad
\text{and}
\quad
\Mpp(W^\vee) = \Cal{U}(\fg')\otimes_{\Cal{U}(\fp')}W^\vee
\end{equation*}
for generalized Verma modules for $(\fg, \fp)$ and $(\fg',\fp')$ induced from 
$d\xi^\vee \boxtimes \C_{-\lambda}$ and $d\varpi^\vee \boxtimes \C_{-\nu}$,
respectively.
Via the diagonal action of $P$ on $\Mp(V^\vee)$, we regard
$M_\fp^\fg(V^\vee)$ as a $(\fg, P)$-module. Likewise, we regard 
$\Mpp(W^\vee)$ as a $(\fg', P')$-module.


The following theorem is often called the \emph{duality theorem}. 
For the proof, see \cite{KP1}.

\begin{thm}[Duality theorem]\label{thm:duality}
There is a natural linear isomorphism
\begin{equation}\label{eqn:duality1}
\EuD
\colon
\operatorname{Hom}_{P'}(W^\vee,\Mp(V^\vee))
\stackrel{\sim}{\To} 
\operatorname{Diff}_{G'}(\mathcal V, \mathcal W).
\end{equation}
Equivalently,
\begin{equation}\label{eqn:duality2}
\EuD
\colon
\operatorname{Hom}_{\fg', P'}(\Mpp(W^\vee),\Mp(V^\vee))
\stackrel{\sim}{\To} 
\operatorname{Diff}_{G'}(\mathcal V, \mathcal W).
\end{equation}
\end{thm}

Given bases 
$\{v_1^\vee,\ldots, v_\ell^\vee\}$ and $\{w_1, \ldots, w_m\}$
for $V^\vee$ and $W$, respectively, 
the map 
\begin{equation*}
\Phi \in \Hom_{P'}(W^\vee, \Mp(V^\vee)) 
\simeq (\Mp(V^\vee) \otimes W)^{P'} \subset 
\Cal{U}(\fn_-)\otimes V^\vee \otimes W
\end{equation*}
is of the form
\begin{equation*}
\Phi = \sum_{i,j}u_{i,j}\otimes v^\vee_i \otimes w_j.
\end{equation*}
Then, under the identification \eqref{eqn:DN},
the differential operator 
\begin{equation*}
\EuD(\Phi)\colon C^\infty(N_-)\otimes V\to C^\infty(N_-')\otimes W
\end{equation*}
is given by 
\begin{equation}\label{eqn:HD}
\EuD(\Phi) = \sum_{i,j}dR(u_{i,j})\vert_{N_-'} \otimes v^\vee_i \otimes w_j,
\end{equation}
where $dR$ is the infinitesimal right translation.
(See \cite[Thm.\ 2.9]{KP1} for a basis-free expression of $\EuD(\Phi)$.)



%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Algebraic Fourier transform $\widehat{\;\;\cdot\;\;}$ of Weyl algebras}
\label{sec:Weyl}

Let $U$ be a complex finite-dimensional vector space with $\dim _\C U=n$.
Fix a basis $u_1,\ldots, u_n$ of $U$ and let 
$(z_1, \ldots, z_n)$ denote the coordinates of $U$ with respect to the basis.
Then the algebra
\begin{equation*}
\C[U;z, \tfrac{\partial}{\partial z}]:=
\C[z_1, \ldots, z_n, 
\tfrac{\partial}{\partial z_1}, \ldots, \tfrac{\partial}{\partial z_n}]
\end{equation*}
with relations $z_iz_j = z_jz_i$, 
$\frac{\partial}{\partial z_i}\frac{\partial}{\partial z_j} 
=\frac{\partial}{\partial z_j}\frac{\partial}{\partial z_i}$,
and $\frac{\partial}{\partial z_j} z_i=\delta_{i,j} + z_i \frac{\partial}{\partial z_j}$
is called the Weyl algebra of $U$, where $\delta_{i,j}$ is the Kronecker delta.
Similarly,
let $(\zeta_1,\ldots, \zeta_n)$ denote the coordinates of 
the dual space $U^\vee$ of $U$ with respect to the dual basis of 
$u_1,\ldots, u_n$. We write 
$\C[U^\vee;\zeta, \tfrac{\partial}{\partial \zeta}]$
for the Weyl algebra of $U^\vee$.
Then the map determined by
\begin{equation}\label{eqn:Weyl}
\widehat{\frac{\partial}{\partial z_i}}:= -\zeta_i, \quad
\widehat{z_i}:=\frac{\partial}{\partial \zeta_i}
\end{equation}
gives a Weyl algebra isomorphism 
\begin{equation}\label{eqn:Weyl2}
\widehat{\;\;\cdot\;\;}\;\colon\C[U;z, \tfrac{\partial}{\partial z}] 
\stackrel{\sim}{\To} 
\C[U^\vee;\zeta, \tfrac{\partial}{\partial \zeta}], 
\quad T \mapsto \widehat{T}.
\end{equation}
\vskip 0.1in
\noindent
The map \eqref{eqn:Weyl2} is called
the \emph{algebraic Fourier transform of Weyl algebras}
(\cite[Def.\ 3.1]{KP1}).

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Fourier transformed representation $\widehat{d\pi_{(\xi,\lambda)^*}}$}
\label{sec:dpi2}

For a representation $\eta$ of $G$, we denote by $d\eta$ 
the infinitesimal representation of $\fg(\R)$. 
For instance,  $dL$ denotes the infinitesimal representation of
the left regular representation of $G$ on $C^\infty(G)$.
As usual, we naturally extend representations of $\fg(\R)$ 
to ones for the universal enveloping algebra $\Cal{U}(\fg)$ of its complexification $\fg$.
The same convention is applied for closed subgroups of $G$.

For $g \in N_-MAN_+$, we write
\begin{equation*}
g = p_-(g)p_0(g)p_+(g),
\end{equation*}
where $p_\pm(g) \in N_{\pm}$ and $p_0(g) \in MA$. 
Similarly, for $Z \in \fg = \fn_- \oplus \fl\oplus \fn_+$ with $\fl= \fm \oplus \fa$,
we write
\begin{equation*}
Z=Z_{\fn_-} + Z_{\fl} + Z_{\fn_+},
\end{equation*}
where $Z_{\fn_{\pm}} \in \fn_{\pm}$ and $Z_\fl \in \fl$.

For $2\rho\equiv 2\rho(\fn_+)= \mathrm{Trace}(\ad\vert_{\fn_+})\in \mathfrak{a}^*$,
we denote by  $\C_{2\rho}$ the one-dimensional representation of $P$
defined by
$p \mapsto \chi_{2\rho}(p)=
\abs{\mathrm{det}(\mathrm{Ad}(p)\colon 
\mathfrak{n}_+ \to \mathfrak{n}_+)}$.
For the contragredient representation
$((\xi_\lambda)^\vee, V^\vee)$ of $(\xi_\lambda,V)$,
we put
$\xi^*_\lambda := \xi^\vee \boxtimes \C_{2\rho-\lambda}$.
As for $\xi_\lambda$, we regard $\xi^*_\lambda$ as a representation of $P$.
Define the induced representation
$\pi_{(\xi, \lambda)^*} = \mathrm{Ind}_P^G(\xi^*_\lambda)$
on the space $C^\infty(G/P,\mathcal{V}^*)$ of smooth sections 
for the vector bundle $\mathcal{V}^*=G\times_P (V^\vee\otimes \C_{2\rho})$
associated with $\xi^*_\lambda$, which is isomorphic to the tensor bundle
of the dual vector bundle $\mathcal{V}^\vee = G\times_PV^\vee$ and the bundle
of densities over $G/P$.
Then the integration on $G/P$ gives a 
$G$-invariant non-degenerate bilinear form
$
\mathrm{Ind}^G_P(\xi_\lambda) 
\times \mathrm{Ind}^G_P(\xi^*_\lambda) \to \C
$
for $\mathrm{Ind}^G_P(\xi_\lambda)$ and 
$\mathrm{Ind}^G_P(\xi^*_\lambda)$.

As for $C^\infty(G/P,\mathcal{V})$,
the space $C^\infty(G/P,\mathcal{V}^*)$ can be regarded as 
a subspace of $C^\infty(N_-) \otimes V^\vee$.
Then the infinitesimal representation $d\pi_{(\xi,\lambda)^*}(Z)$
on $C^\infty(N_-)\otimes V^\vee$
for $Z \in \fg$ is given by
\begin{equation}\label{eqn:dpi3}
d\pi_{(\xi,\lambda)^*}(Z)f(\bar{n})
=d\xi_\lambda^*((\Ad(\bar{n}^{-1})Z)_\fl)f(\bar{n})
-\left(dR((\Ad(\cdot^{-1})Z)_{\fn_-})f\right)(\bar{n}).
\end{equation}
(For the details, see, for instance, \cite[Sect.\ 2]{KuOr25a}.)

Via the exponential map $\exp\colon \fn_-(\R) \stackrel{\sim}{\to} N_-$, one can regard
$\dpi_{(\xi,\lambda)^*}(Z)$ as a representation 
on $C^\infty(\mathfrak{n}_-(\R)) \otimes V^\vee$.
It then follows from \eqref{eqn:dpi3} that 
$\dpi_{(\xi,\lambda)^*}$ gives a Lie algebra homomorphism
\begin{equation*}
d\pi_{(\xi,\lambda)^*}\colon \mathfrak{g} \To 
\C[\fn_-(\R);x, \tfrac{\partial}{\partial x}]  \otimes \mathrm{End}(V^\vee),
\end{equation*}
where $(x_1, \ldots, x_n)$ are given coordinates of $\fn_-(\R)$ with $n=\dim \fn_-(\R)$.
We extend the coordinate functions $x_1,\ldots, x_n$ for $\fn_-(\R)$ 
holomorphically to the ones $z_1, \ldots, z_n$ for $\fn_-$.
Thus we have 
\begin{equation*}
d\pi_{(\xi,\lambda)^*}\colon \mathfrak{g} \To 
\C[\fn_-;z, \tfrac{\partial}{\partial z}]  \otimes \mathrm{End}(V^\vee).
\end{equation*}

Now we fix a non-degenerate $\Ad$-invariant 
symmetric bilinear form $\kappa$ on $\fg$.
Via $\kappa$, we identify $\fn_+$  with the dual space $\fn_-^\vee$ of 
$\fn_-$. Then
the algebraic Fourier transform $\widehat{\;\;\cdot\;\;}$
of Weyl algebras \eqref{eqn:Weyl2} gives a Weyl algebra isomorphism
\begin{equation*}
\widehat{\;\;\cdot\;\;}\;\colon
\C[\fn_-;z, \tfrac{\partial}{\partial z}] 
\stackrel{\sim}{\To} 
\C[\fn_+;\zeta, \tfrac{\partial}{\partial \zeta}].
\end{equation*}
In particular, it gives a Lie algebra homomorphism
\begin{equation}\label{eqn:hdpi}
\widehat{d\pi_{(\xi,\lambda)^*}}\colon \mathfrak{g} \To 
\C[\fn_+;\zeta, \tfrac{\partial}{\partial \zeta}]\otimes \mathrm{End}(V^\vee).
\end{equation}

Let 
$\Cal{D}'_{[o]}(G/P,\Cal{V}^*)$ 
denote the space of 
$\mathcal{V}^*$-valued
distributions on $G/P$ supported at the identity coset $[o]=eP$ of $G/P$.
Likewise, we write $\Cal{D}'_{0}(\fn_-(\R),V^\vee)$ for the space 
of $V^\vee$-valued distributions on $\fn_-(\R)$ supported at $0$.
Then the following chain of $(\fg,P)$-isomorphisms holds:
\begin{alignat}{4}\label{eqn:VP}
M_\fp(V^\vee)
&\stackrel{\sim}{\To} \Cal{D}'_{[o]}(G/P,\Cal{V}^*) 
&&\stackrel{\sim}{\To} \Cal{D}'_{0}(\fn_-(\R),V^\vee)
&&\stackrel{\sim}{\To} \Pol(\fn_+)\otimes V^\vee\\
\rotatebox{90}{$\in$}\hspace{20pt}
&\hspace{50pt}\rotatebox{90}{$\in$}
&&\hspace{50pt}\rotatebox{90}{$\in$}
&&\hspace{55pt}\rotatebox{90}{$\in$}& \nonumber\\[-2pt]
u\otimes v^\vee \hspace{8pt}
&\mapsto dL(u)(\delta_{[o]} \otimes v^\vee) 
&&\mapsto d\pi_{(\xi,\lambda)^*}(u)(\delta_0\otimes v^\vee) 
&&\mapsto \widehat{d\pi_{(\xi,\lambda)^*}}(u)(1\otimes v^\vee), \nonumber
\end{alignat}
where $\delta_{[o]}$ and $\delta_0$ denote the Dirac delta functions supported at
$[o]$ and $0$, respectively  (cf.\ \cite{KP1, KuOr25a}).

Let $F_c$ denote the compositions of the three $(\mathfrak{g}, P)$-module isomorphisms. We call the resulting isomorphism
%\begin{defn}[{\cite[Sect.\ 3.4]{KP1}}]\label{def:AFT2}
\begin{equation}\label{eqn:Fc}
F_c\colon M_\fp(V^\vee) 
\stackrel{\sim}{\To}
\Pol(\fn_+) \otimes V^\vee,
\quad u\otimes v^\vee \longmapsto 
\widehat{d\pi_{(\xi,\lambda)^*}}(u)(1\otimes v^\vee)\\
\end{equation}
the \emph{algebraic Fourier transform of the generalized Verma module  $M_\fp(V^\vee)$} (\cite[Sect.\ 3.4]{KP1}).
%\end{defn}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{The F-method}
\label{sec:Fmethod2}
Observe that
the algebraic Fourier transform
$F_c$  in \eqref{eqn:Fc} 
gives an $M'A'$-isomorphism
\begin{equation}\label{eqn:VP2}
\Mp(V^\vee)^{\fn_+'}
\stackrel{\sim}{\To}
(\Pol(\fn_+) 
\otimes V^\vee)^{\widehat{d\pi_{(\xi,\lambda)^*}}(\fn_+')},
\end{equation}
which induces a linear isomorphism
\begin{equation}\label{eqn:VP31}
\operatorname{Hom}_{M'A'}(W^\vee,
\Mp(V^\vee)^{\fn_+'})
\stackrel{\sim}{\To}
\operatorname{Hom}_{M'A'}
\left(W^\vee,
(\mathrm{Pol}(\mathfrak{n}_+) 
\otimes V^\vee)^{\widehat{d\pi_{(\xi,\lambda)^*}}(\fn_+')}\right).
\end{equation}
Here $M'A'$ acts on $\Pol(\fn_+)$ via the action
\begin{equation}\label{eqn:sharp}
\Ad_{\#}(l) \colon p(X) \mapsto p(\Ad(l^{-1})X)
\;\; \text{for $l \in M'A'$}.
\end{equation}

Now we set
\begin{equation}\label{eqn:Sol2a}
\mathrm{Sol}(\mathfrak n_+;V,W):=
\operatorname{Hom}_{M'A'}(W^\vee,
(\mathrm{Pol}(\mathfrak{n}_+) 
\otimes V^\vee)^{\widehat{d\pi_{(\xi,\lambda)^*}}(\fn_+')}).
\end{equation}
Via the identification
$\textrm{Hom}_{M'A'}(W^\vee, \Pol(\fn_+)\otimes V^\vee)
\simeq
\big((\Pol(\fn_+)\otimes V^\vee) \otimes W\big)^{M'A'}$,
we have
\begin{align}\label{eqn:Sol}
&\Sol(\fn_+;V,W)\nonumber \\[3pt]
&=\{ \psi \in \Hom_{M'A'}(W^\vee, \Pol(\fn_+)\otimes V^\vee): 
\text{
$\psi$ satisfies the system \eqref{eqn:Fsys} of PDEs below.}\}
\end{align}
\begin{equation}\label{eqn:Fsys}
(\widehat{d\pi_{(\xi,\lambda)^*}}(C) \otimes \id_W)\psi=0
\,\,
\text{for all $C \in \fn_+'$}.
\end{equation}
We refer to the system \eqref{eqn:Fsys} of PDEs 
as the \emph{F-system} (\cite[Fact 3.3 (3)]{KKP16}).
Since
\begin{equation*}%\label{eqn:20221030}
\operatorname{Hom}_{P'}(W^\vee,\Mp(V^\vee))
=
\operatorname{Hom}_{M'A'}(W^\vee,\Mp(V^\vee)^{\fn_+'}),
\end{equation*}
the isomorphism \eqref{eqn:VP31} together with \eqref{eqn:Sol2a} shows the following.

\begin{thm}
[F-method, {\cite[Thm.\ 4.1]{KP1}}]
\label{thm:Fmethod}
There exists a linear isomorphism
\begin{equation*}
F_c \otimes \mathrm{id}_{W}\colon 
\operatorname{Hom}_{P'}(W^\vee,
\Mp(V^\vee))
\stackrel{\sim}{\To}
\mathrm{Sol}(\mathfrak n_+;V,W).
\end{equation*}
Equivalently, we have
\begin{equation*}
F_c \otimes \mathrm{id}_{W}\colon 
\mathrm{Hom}_{\mathfrak g',P'}(\Mpp(W^\vee),\Mp(V^\vee))\stackrel{\sim}{\To}
\mathrm{Sol}(\mathfrak n_+;V,W).
\end{equation*}
\end{thm}

The following diagram summarizes the duality theorem and F-method.
\begin{equation}\label{eqn:isom}
\begin{tikzcd}[row sep=1.3cm, column sep=1cm]
& 
\mathrm{Sol}(\mathfrak n_+;V,W)
\arrow[dr, dashed, "\sim"' sloped] \\
\operatorname{Hom}_{\mathfrak{g}',P'}(\Mpp(W^\vee),\Mp(V^\vee)) 
  \arrow[rr, "\sim", "\EuScript{D}"']
  \ar[ur, "\sim"' sloped, "F_c\otimes\mathrm{id}_W"] 
 &
 & 
 \operatorname{Diff}_{G'}(\mathcal V, \mathcal W).
%}
\end{tikzcd}
\end{equation}

\vskip 0.1in

To end this subsection we show a small lemma on
the infinitesimal representation $d\pi_{(\xi,\lambda)^*}(X)$
for $X \in \fn_-$, which will be useful for later arguments.

\begin{lem}\label{lem:dpiL}
We have
\begin{equation}\label{eqn:dpiL}
d\pi_{(\xi,\lambda)^*}\vert_{\Cal{U}(\fn_-)} =
dL \vert_{\Cal{U}(\fn_-)}\otimes \id_{V^\vee}.
\end{equation}
\end{lem}

\begin{proof}
The identity readily follows from the derivation of the infinitesimal action $d\pi_{(\xi,\lambda)^*}$. 
Or, one can also show \eqref{eqn:dpiL} from the formula 
\eqref{eqn:dpi3} directly. Indeed, for $Z \in \fg$, the action 
$d\pi_{(\xi,\lambda)^*}(Z)$ on $C^\infty(N_-)\otimes V^\vee$ is given by
\begin{equation}\label{eqn:dpi2}
d\pi_{(\xi,\lambda)^*}(Z)f(\bar{n})
=d\xi_\lambda^*((\Ad(\bar{n}^{-1})Z)_\fl)f(\bar{n})
-\left(dR((\Ad(\cdot^{-1})Z)_{\fn_-})f\right)(\bar{n}).
\end{equation}
For $X\in \fn_-$, we have
$(\Ad(\bar{n})X)_\fl = 0$
and $(\Ad(\bar{n})X)_{\fn_-} = \Ad(\bar{n})X$.
Therefore, for $Z=X \in \fn_-$, the formula \eqref{eqn:dpi2} reads
\begin{equation}\label{eqn:dpiL2}
d\pi_{(\xi,\lambda)^*}(X)f(\bar{n})
=-\left(dR(\Ad(\cdot^{-1})X)f\right)(\bar{n}).
\end{equation}
On the other hand, the infinitesimal left translation $dL(X)$ is given by
\begin{align}\label{eqn:LR}
dL(X)f(\bar{n}) 
&=\frac{d}{dt}\bigg\vert_{t=0} f(\exp(-tX)\bar{n}) \nonumber \\[3pt]
&=\frac{d}{dt}\bigg\vert_{t=0} f(\bar{n}\exp(-\Ad(\bar{n}^{-1})X))  \nonumber \\[3pt]
&=-dR(\Ad(\cdot^{-1})X)f(\bar{n}).
\end{align}
Now \eqref{eqn:dpiL2} and \eqref{eqn:LR} conclude the proposed identity.
\end{proof}

\begin{rem}
It follows from Lemma \ref{lem:dpiL} that,
for $u\otimes v^\vee \in \Cal{U}(\fn_-)\otimes V^\vee 
\simeq \Mp(V^\vee)$, the diagram \eqref{eqn:VP} is reduced to the following.
\begin{alignat}{4}\label{eqn:VP1}
\Cal{U}(\fn_-)\otimes V^\vee
&\stackrel{\sim}{\To}  \Cal{D}'_{[o]}(G/P,\Cal{V}^*) 
&&\stackrel{\sim}{\To}  \Cal{D}'_{0}(\fn_-(\R),V^\vee)
&&\stackrel{\sim}{\To}  \Pol(\fn_+)\otimes V^\vee\\
\rotatebox{90}{$\in$}\hspace{20pt}
&\hspace{50pt}\rotatebox{90}{$\in$}
&&\hspace{50pt}\rotatebox{90}{$\in$}
&&\hspace{55pt}\rotatebox{90}{$\in$}& \nonumber\\[-2pt]
u\otimes v^\vee \hspace{8pt}
&\mapsto dL(u)(\delta_{[o]} \otimes v^\vee) 
&&\longmapsto\hspace{5pt} dL(u)(\delta_0 \otimes v^\vee) 
&&\longmapsto \hspace{5pt} \widehat{dL}(u)(1\otimes v^\vee) \nonumber
\end{alignat}

\end{rem}

