\section{The truncated symbol map $\symb_0$ and its inverse $\symb_0^{-1}$}
\label{sec:symb}

The aim of this section is to define the truncated symbol map
\begin{equation}\label{eqn:symb0}
\symb_0\colon
\operatorname{Diff}_{G'}(\mathcal V, \mathcal W)
\stackrel{\sim}{\To}
\mathrm{Sol}(\mathfrak n_+;V,W)
\end{equation}
with its inverse $\symb_0^{-1}$
in such a way that the diagram in \eqref{eqn:isom} commutes.
This is achieved in Theorem \ref{thm:symb2}.
We continue with the notation from Section \ref{sec:Fmethod}, unless
otherwise specified.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Notation on the action of the Weyl algebra}
\label{sec:Weyl2}

Before starting the main arguments, let us fix a notation 
about the Weyl algebra
$
\C[\zeta, \tfrac{\partial}{\partial \zeta}]
=\C[\zeta_1, \ldots, \zeta_n, 
\tfrac{\partial}{\partial \zeta_1}, \ldots, \tfrac{\partial}{\partial \zeta_n}]$.
We denote by $\acts$ the action of the elements in
$\C[\zeta, \tfrac{\partial}{\partial \zeta}]$
on $\C[\zeta]$, unless it is clear from the context.
For instance, the notation $\tfrac{\partial}{\partial  \zeta_j}\zeta_i$ stands for
the product of the differential operator $\tfrac{\partial}{\partial \zeta_j}$ and 
the multiplication operator by $\zeta_i$
as a Weyl algebra element, while $\tfrac{\partial}{\partial \zeta_j}\acts \zeta_i$ means
the action of $\tfrac{\partial}{\partial \zeta_j}$ on the monomial
$\zeta_i$. For instance, we have
\begin{alignat*}{4}
&\frac{\partial}{\partial \zeta_j} 1 
&&= \frac{\partial}{\partial \zeta_j},
\qquad
&&\frac{\partial}{\partial \zeta_j}\zeta_i 
&&= \zeta_i \frac{\partial}{\partial \zeta_j} + \delta_{i,j},\\[5pt]
&\frac{\partial}{\partial \zeta_j}\acts 1 
&&= 0,
\qquad
&&\frac{\partial}{\partial \zeta_j}\acts \zeta_i  &&= \delta_{i,j}.
\end{alignat*}

Remark that
the polynomial $(D_1D_2) \acts \psi(\zeta)$ 
for $D_1, D_2 \in \C[\zeta, \tfrac{\partial}{\partial \zeta}]$ and 
$\psi(\zeta) \in \C[\zeta]$
is computed as
\begin{equation}\label{eqn:acts}
(D_1D_2) \acts \psi(\zeta) = D_1 \acts (D_2\acts \psi(\zeta)).
\end{equation}
For instance, we have 
\begin{equation*}
(\frac{\partial}{\partial \zeta_j}\zeta_i) \acts \psi(\zeta)
= \frac{\partial}{\partial \zeta_j}\acts (\zeta_i\acts \psi(\zeta))
=\frac{\partial}{\partial \zeta_j} \acts \zeta_i\psi(\zeta)
=\delta_{i,j}\psi(\zeta) + \zeta_i \frac{\partial}{\partial \zeta_j} \acts \psi(\zeta).
\end{equation*}
In particular,
\begin{equation*}
(\frac{\partial}{\partial \zeta_j}\zeta_i) \acts 1
= \frac{\partial}{\partial \zeta_j}\acts (\zeta_i\acts 1)
=\frac{\partial}{\partial \zeta_j} \acts \zeta_i
=\delta_{i,j}.
\end{equation*}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{The inverse $F_c^{-1}$ of the algebraic Fourier transform $F_c$}
\label{sec:FcSymb}

Let $P=LN_+$ be the Levi decomposition of the parabolic subgroup $P$ with $L = MA$.
Recall from Section \ref{sec:dpi2} that
$\kappa(\cdot, \cdot)$  is a non-degenerate 
$\Ad$-invariant symmetric bilinear form of $\fg$.
Fix bases $\{Y_1, \ldots, Y_n\}$ and $\{X_1, \ldots, X_n\}$  
for $\fn_+(\R)$ and $\fn_-(\R)$, respectively, such that $\kappa(Y_i, X_j) =\delta_{i,j}$. 
We also regard them as bases of $\fn_+$ and $\fn_-$.

For $a_1, a_2, \ldots, a_k$ in an algebra $\Cal{A}$ over $\C$, 
we define the symmetrization $\sigma_k(a_1a_2\cdots a_k)$ 
of the product $a_1a_2\cdots a_k$ as
\begin{equation*}
\sigma_k(a_1a_2\cdots a_k):=
\frac{1}{k!}\sum_{\tau \in \frak{S}_k}
a_{\tau(1)} \cdots a_{\tau(k)},
\end{equation*}
where $\frak{S}_k$ denotes the symmetric group on $k$ elements.

We first observe several $L$-isomorphisms.
To begin with, as in Section \ref{sec:dpi2}, we put 
$\zeta_j(\cdot):=\kappa(\cdot, X_j) \in \fn_+^\vee$.
Then, as $L$-modules, we have 
\begin{equation}\label{eqn:Lisom}
\omega\colon \fn_+^\vee \stackrel{\sim}{\To} \fn_-, \; \zeta_j \longmapsto X_j.
\end{equation}

Let $S^k(V)$ denote the subspace  
of the symmetric tensor algebra $S(V)$ of a vector space $V$
spanned by monomials of homogeneous degree $k$.
Then, as $\Pol^k(\fn_+)=S^k(\fn_+^\vee)$, 
the isomorphism $\omega$ gives rise to 
an $L$-isomorphism
\begin{equation*}
\omega_k\colon \Pol^k(\fn_+) \stackrel{\sim}{\To} S^k(\fn_-),
\;
\zeta_1^{k_1} \cdots \zeta_n^{k_n} \longmapsto
X_1^{k_1} \cdots X_n^{k_n}
\end{equation*}
for $k_1 + \cdots + k_n = k$.

Meanwhile, the symmetrization map 
$\widetilde{\sigma}_k \colon S^k(\fn_-) \to \Cal{U}(\fn_-)$ gives an $L$-isomorphism
\begin{equation*}
\widetilde{\sigma}_k \colon S^k(\fn_-) \stackrel{\sim}{\To} 
\widetilde{\sigma}_k(S^k(\fn_-)) \subset \Cal{U}(\fn_-),
%\quad
%X_{j_1}\cdots X_{j_k}\mapsto 
%\sigma_k(X_{j_1}\cdots X_{j_k}).
%\frac{1}{k!} \sum_{\tau \in \frak{S}_k}
%X_{j_{\tau(1)}} \cdots X_{j_{\tau(k)}},
\end{equation*}
where, for  $X_{j_1}\cdots X_{j_k}:=X_1^{k_1}\cdots X_n^{k_n} \in S^k(\fn_-)$,
we have
\begin{equation*}
\widetilde{\sigma}_k\colon
X_{j_1}\cdots X_{j_k}\mapsto 
\sigma_k(X_{j_1}\cdots X_{j_k}).
\end{equation*}
Here, the product $X_{j_1}\cdots X_{j_k}$ in $\sigma_k(X_{j_1}\cdots X_{j_k})$
is taken as an element of the universal enveloping algebra $\Cal{U}(\fn_-)$.

Recall from \eqref{eqn:Fc} that,
for a finite-dimensional irreducible $L$-module $V$, the algebraic Fourier
transform $F_c$ gives a $(\fg, P)$-isomorphism
\begin{equation*}
F_c\colon \Cal{U}(\fg)\otimes_{\Cal{U}(\fp)}V^\vee \stackrel{\sim}{\To} 
\Pol(\fn_+)\otimes V^\vee,
\;
u\otimes v^\vee \longmapsto \widehat{d\pi_{(\xi,\lambda)^*}}(u)(1\otimes v^\vee),
\end{equation*}
which leads to an $L$-isomorphism
\begin{equation}\label{eqn:Fc2}
F_c \colon \Cal{U}(\fn_-)\otimes V^\vee \stackrel{\sim}{\To} \Pol(\fn_+)\otimes V^\vee.
\end{equation}
By \eqref{eqn:dpiL}, the $L$-isomorphism \eqref{eqn:Fc2} reads
\begin{equation*}
F_c\colon \Cal{U}(\fn_-) \otimes V^\vee \stackrel{\sim}{\To} \Pol(\fn_+)\otimes V^\vee,
\; 
u\otimes v^\vee
\longmapsto
(\widehat{dL}(u)\otimes \id_{V^{\vee}})(1\otimes v^\vee),
\end{equation*}
where $(\widehat{dL}(u)\otimes \id_{V^{\vee}})(1\otimes v^\vee)$ is given by
\begin{align*}
(\widehat{dL}(u)\otimes \id_{V^{\vee}})(1\otimes v^\vee)
=(\widehat{dL}(u) \acts 1)\otimes v^\vee
\end{align*}
in the notation introduced in Section \ref{sec:Weyl2}.

For the sake of simplicity, we write
\begin{equation*}
\hdL(u)_1:= \hdL(u)\acts 1
\end{equation*}
so that
\begin{equation}\label{eqn:FcL}
F_c\vert_{\widetilde{\sigma}_k(S^k(\fn_-))} = \hdL(\cdot)_1 \otimes \id_{V^\vee}.
\end{equation}
The algebraic Fourier transform $F_c$ in  
\eqref{eqn:Fc2} combined with $\widetilde{\sigma}_k$  then yields an $L$-isomorphism
\begin{alignat}{2}\label{eqn:hdL}
F_c\colon \widetilde{\sigma}_k(S^k(\fn_-))&\otimes V^\vee 
&&\stackrel{\sim}{\To} 
\hdL(\widetilde{\sigma}_k(S^k(\fn_-)))_1\otimes V^\vee  \\[-2pt]
&\hspace{3pt}\cap && \hspace{63pt} \cap \nonumber \\[-5pt]
\Cal{U}(\fn_-)&\otimes V^\vee 
&&\To 
\Pol(\fn_+)\otimes V^\vee.\nonumber
\end{alignat}
In summary, the following compositions of $L$-isomorphisms hold.
\begin{alignat}{2}
\Pol^k(\fn_+)\otimes V^\vee
\stackrel[\sim]{\omega_k}{\To} 
S^k(\fn_-)\otimes V^\vee
\stackrel[\sim]{\widetilde{\sigma}_k}{\To} 
\widetilde{\sigma}_k(S^k(\fn_-))&\otimes V^\vee
\stackrel[\sim]{F_c}{\To} 
\hdL(\widetilde{\sigma}_k(S^k(\fn_-)))_1&&\otimes V^\vee \label{eqn:PdL}\\[-2pt]
&\;\cap &&\;\cap \nonumber \\[-5pt]
\Cal{U}(\fn_-)&\otimes V^\vee
\hspace{70pt} \Pol(\fn_+) &&\otimes V^\vee \nonumber
\end{alignat}
In particular, we have
\begin{equation}\label{eqn:Pol1}
(\hdL(\cdot)_1 \circ \widetilde{\sigma}_k \circ \omega_k)(\Pol^k(\fn_+)) \simeq \Pol^k(\fn_+).
\end{equation}

We claim that the left hand side of \eqref{eqn:Pol1} is indeed equal to the right. 
In order to show it,
let $\gD(W)$ denote the set of weights for 
an $L$-submodule $W \subset \Pol(\fn_+)$. 
Also, let  $\ga_1, \ldots, \ga_n$ be the roots for $\fn_+$.
Then the set $\gD(\Pol^1(\fn_+))$ is given by
\begin{equation*}
\gD(\Pol^1(\fn_+))=\gD(\fn_-) = \{-\ga_1, \ldots, -\ga_n\}.
\end{equation*}
Further, we have
\begin{equation*}
\gD(\Pol^k(\fn_+)) = \gD(S^k(\fn_-))=F_k,
\end{equation*}
where
\begin{align*}
F_k&:=\{-\sum_{j=1}^nk_j\ga_j : (k_1,\ldots, k_n) \in E_k\},\\
E_k&:=\{(k_1,\ldots, k_n) \in \Z_{\geq 0}^n : k_1+\cdots +k_n=k\}.
\end{align*}

\begin{lem}\label{lem:VFk}
The following two conditions on 
an $L$-submodule $W \subset \Pol(\fn_+)$ are equivalent.
\begin{enumerate}
\item[\emph{(i)}] $\gD(W) = F_k$.
\item[\emph{(ii)}] $W = \Pol^k(\fn_+)$.
\end{enumerate}
\end{lem}

\begin{proof}
Since the implication ``(ii) $\Rightarrow$ (i)'' is trivial, it suffices to show the other direction.
Let $\upsilon_j$ be a root vector in $\Pol^1(\fn_+)$
for $-\ga_j$ for $j=1,\ldots, n$. Then any root vector
for $-\sum_{j=1}^nk_j \ga_j \in F_k$ is a scalar multiple of $\upsilon_1^{k_1}\cdots \upsilon_n^{k_n}$.
Thus if $\gD(W)=F_k$, then 
$W=\spn_\C\{\upsilon_1^{k_1}\cdots \upsilon_n^{k_n}: (k_1,\ldots, k_n) \in E_k\}=\Pol^k(\fn_+)$.
\end{proof}

\begin{prop}\label{prop:Pol2}
We have
\begin{equation}\label{eqn:Pol2}
(\hdL(\cdot)_1 \circ \widetilde{\sigma}_k \circ \omega_k)(\Pol^k(\fn_+)) = \Pol^k(\fn_+).
\end{equation}
\end{prop}

\begin{proof}
By \eqref{eqn:Pol1}, we have 
$\gD((\hdL(\cdot)_1 \circ \widetilde{\sigma}_k \circ \omega_k)(\Pol^k(\fn_+)))=\gD(\Pol^k(\fn_+))$.
As $(\hdL(\cdot)_1 \circ \widetilde{\sigma}_k \circ \omega_k)(\Pol^k(\fn_+))$
is an $L$-submodule of $\Pol(\fn_+)$,
the equality \eqref{eqn:Pol2} follows from Lemma \ref{lem:VFk}.
\end{proof}

In the rest of this section we aim to show 
\begin{equation*}
\hdL(\cdot)_1 \circ \widetilde{\sigma}_k \circ \omega_k = \id_{\Pol^k(\fn_+)}.
\end{equation*}
In order to prove it, we first show one technical lemma.
For $\zeta_{j_1},\ldots, \zeta_{j_k} \in \fn_+^\vee$, put
\begin{equation}\label{eqn:Dell}
D_\ell:=\zeta_{j_\ell} + \sum_{r\neq j_\ell} p_r^{j_\ell} (\tfrac{\partial}{\partial \zeta}) \zeta_r
\end{equation}
with $p_r^{j_\ell} (\tfrac{\partial}{\partial \zeta}) 
\in \C^{\geq 1}[\tfrac{\partial}{\partial \zeta_1}, \ldots, \tfrac{\partial}{\partial \zeta_n}]$,
that is, $p_r^{j_\ell} (\tfrac{\partial}{\partial \zeta})$ are constant-coefficient
differential operators with no constant term.

\begin{lem}\label{lem:Dk}
The polynomial $(D_1\cdots D_k) \acts 1 \in \Pol(\fn_+)$ is of the form
\begin{equation}\label{eqn:Dk1}
(D_1\cdots D_k) \acts 1
=\zeta_{j_1}\cdots \zeta_{j_k} + 
\text{(lower order terms)}.
\end{equation}
\end{lem}

\begin{proof}
We prove it by induction. First, observe that 
\begin{equation*}
D_k \acts 1 
=(\zeta_{j_k} + \sum_{r\neq j_k} p_r^{j_k}(\tfrac{\partial}{\partial \zeta}) \zeta_r)
\acts 1
= \zeta_{j_k} + \sum_{r\neq j_k} p_r^{j_k}(\tfrac{\partial}{\partial \zeta}) \acts \zeta_r.
\end{equation*}
Since the differential operator $p_r^{j_k}(\tfrac{\partial}{\partial \zeta})$ 
does not have
a constant term, 
we have $p_r^{j_k}(\tfrac{\partial}{\partial \zeta})\acts \zeta_r \in \C$.
Therefore,
\begin{equation*}
D_k \acts 1 = \zeta_{j_k} + \text{(constant)},
\end{equation*}
which is of the form of \eqref{eqn:Dk1}.

Now assume that $(D_{\ell+1}\cdots D_k) \acts 1$ is given by
\begin{equation*}
(D_{\ell+1}\cdots D_n) \acts 1 = \zeta_{j_{\ell+1}} \cdots \zeta_{j_k} + q(\zeta)
\end{equation*}
for some $q(\zeta)\in \Pol(\fn_+)$ with $\deg q(\zeta) < k-\ell$.
Then,
\begin{align}\label{eqn:Dk2}
(D_\ell \cdots D_k)\acts 1
&=
D_\ell\acts (\zeta_{j_{\ell+1}} \cdots \zeta_{j_k}+ q(\zeta)) \nonumber \\
&=
(\zeta_{j_\ell}\zeta_{j_{\ell+1}}\cdots \zeta_{j_k}) + \zeta_{j_\ell}q(\zeta)
+\sum_{r\neq j_{\ell}}p_r^{j_\ell}(\tfrac{\partial}{\partial \zeta})\acts 
(\zeta_r\zeta_{j_{\ell+1}}\cdots\zeta_{j_k})
+\sum_{r\neq j_{\ell}}p_r^{j_\ell}(\tfrac{\partial}{\partial \zeta})\acts \zeta_{j_\ell}q(\zeta).
\end{align}
As $p_r^{j_\ell}(\tfrac{\partial}{\partial \zeta})$ has no constant term, we have 
\begin{equation*}
\deg(p_r^{j_\ell}(\tfrac{\partial}{\partial \zeta}) \acts u(\zeta)) < \deg u(\zeta)
\end{equation*}
for any $u(\zeta) \in \Pol(\fn_+)$. Thus, by \eqref{eqn:Dk2}, 
the polynomial $(D_\ell\cdots D_k)\acts 1$ has the form \eqref{eqn:Dk1}. Now, by induction,
the proposed assertion holds.
\end{proof}

In the following,
we identify $N_- \simeq \R^n$ via the diffeomorphism
\begin{equation}\label{eqn:diffeo}
\R^n \stackrel{\sim}{\To} N_-,
\quad
(x_1, \ldots, x_n) \longmapsto \exp(x_1X_1+ \cdots + x_n X_n).
\end{equation}

\begin{lem}
With respect to the local coordinates \eqref{eqn:diffeo},
the differential operator
$dL(X_j)$ is of the form
\begin{equation}\label{eqn:dLj}
dL(X_j) = - ( \tfrac{\partial}{\partial x_j} 
+ \sum_{r\neq j}p_r(x)\tfrac{\partial}{\partial x_r})
\end{equation}
for some $p_r(x) \in \Pol^{\geq 1}(\fn_-)$.
\end{lem}

\begin{proof}
Take $f(\bar{n}) \in C^\infty(N_-)\simeq C^\infty(\R^n)$.
For $\bar{n}=\exp(x_1X_1+\cdots+x_nX_n)$, we have 
\begin{equation}\label{eqn:exp1}
dL(X_j)f(\bar{n})
=\frac{d}{dt}\bigg\vert_{t=0}f(\exp(-tX_j)\exp(x_1X_1+\cdots+x_nX_n)).
\end{equation}
For simplicity, write $Y:=x_1X_1+\cdots+x_nX_n$.
Then, by the Baker--Campbell--Hausdorff formula,
the product $\exp(-tX_j)\exp(Y)$ amounts to
\begin{equation}\label{eqn:exp2}
\exp(-tX_j)\exp(Y)
=\exp((x_j-t)X_j + \sum_{r\neq j}x_r X_r + \sum_{\ell=2}^\infty H_\ell)
\quad \text{(finite sum)},
\end{equation}
where $H_2 := \frac{1}{2}[-tX_j, Y]$ and $H_\ell$ is a finite linear 
combination of $\ad(Z_1)\cdots \ad(Z_{\ell-1})Z_\ell$, with 
$Z_i \in \{-tX_j, Y\}$ (cf.\ \cite[Thm.\ B.22]{Knapp02}). 
For each $\ad(Z_1)\cdots \ad(Z_{\ell-1})Z_\ell$, there exist 
$i_0$ and $i_0'$ such that 
$Z_{i_0} = -tX_j$ and $Z_{i_0'} = Y$; 
otherwise, $\ad(Z_1)\cdots \ad(Z_{\ell-1})Z_\ell=0$.
Since $\ad(X_r)X_j \neq X_j$ for any $r$, there is no term
of $X_j$ in $\ad(Z_1)\cdots \ad(Z_{\ell-1})Z_\ell$
when it is written in terms of the basis $\{X_1,\ldots, X_n\}$.
Therefore, the sum of the second and third terms of \eqref{eqn:exp2} is of the form
\begin{equation*}
\sum_{r\neq j}x_r X_r + \sum_{\ell=2}^\infty H_\ell
=\sum_{r\neq j} \sum_{m=0}^{\infty} p_{r,m}(x)t^m X_r 
\quad \text{(finite sum)}
\end{equation*}
for some $p_{r,m}(x) \in \Pol^{\geq 1}(\fn_-)$. Thus, \eqref{eqn:exp1} is given by
\begin{equation*}
dL(X_j) f(\bar{n})
=\frac{d}{dt}\bigg\vert_{t=0}f(\exp((x_j-t)X_j +  \sum_{r\neq j} \sum_{m=0}^{\infty} p_{r,m}(x)t^m X_r).
\end{equation*}
Now \eqref{eqn:dLj} is obtained by differentiating the function with respect to the local coordinates \eqref{eqn:diffeo}
and evaluating it at $t=0$.
\end{proof}

\begin{thm}\label{thm:dL1}
We have 
\begin{equation*}
\hdL(\cdot)_1 \circ \widetilde{\sigma}_k \circ \omega_k = \id_{\Pol^k(\fn_+)}.
\end{equation*}
In other words,
\begin{equation}\label{eqn:Finv}
F_c^{-1}((\zeta_{j_1}\cdots \zeta_{j_k})\otimes v^\vee)
=\sigma_k(X_{j_1}\cdots X_{j_k})\otimes v^\vee.
\end{equation}
\end{thm}

\begin{proof}
By definition, we have 
\begin{equation*}
(\hdL(\cdot)_1 \circ \widetilde{\sigma}_k \circ \omega_k )(\zeta_{j_1}\cdots \zeta_{j_k})
=
\sigma_k(\hdL(X_{j_1})\cdots \hdL(X_{j_k}))\acts 1.
\end{equation*}
So, we wish to show that 
\begin{equation*}
\sigma_k(\hdL(X_{j_1})\cdots \hdL(X_{j_k})) \acts 1= \zeta_{j_1}\cdots \zeta_{j_k}.
\end{equation*}
It follows from \eqref{eqn:dLj} that $dL(X_{j_\ell})$ is of the form
\begin{equation*}
dL(X_{j_\ell}) = - ( \tfrac{\partial}{\partial x_{j_\ell}} 
+ \sum_{r\neq j_\ell}p^{j_\ell}_r(x)\tfrac{\partial}{\partial x_r})
\end{equation*}
for some $p^{j_\ell}_r(x) \in \Pol^{\geq 1}(\fn_-)$.
By the algebraic Fourier transform $\widehat{\, \cdot\,}$ of the Weyl algebra \eqref{eqn:Weyl}, we have
$\hdL(X_{j_\ell}) = D_\ell$ with $D_\ell$ defined in \eqref{eqn:Dell}. 
Thus, by Lemma \ref{lem:Dk}, the polynomial
$(\hdL(X_{j_1})\cdots \hdL(X_{j_k}))\acts 1$ is of the form 
 \begin{equation*}
(\hdL(X_{j_1})\cdots \hdL(X_{j_k}))\acts 1
=
\zeta_{j_1}\cdots \zeta_{j_k} + 
\text{(lower degree terms)},
\end{equation*}
which implies that 
\begin{align*}
\sigma_k(\hdL(X_{j_1})\cdots \hdL(X_{j_k}))\acts 1
&=\frac{1}{k!} \cdot k! \cdot (\zeta_{j_1}\cdots \zeta_{j_k}) + \text{(lower degree terms)}\\
&=\zeta_{j_1}\cdots \zeta_{j_k} + \text{(lower degree terms)}.
\end{align*}
However, it follows from Proposition \ref{prop:Pol2} that 
\begin{equation*}
\sigma_k(\hdL(X_{j_1})\cdots \hdL(X_{j_k}))\acts 1 \in \Pol^k(\fn_+).
\end{equation*}
Thus, the lower degree terms are all 0. This establishes the first identity.

It follows from \eqref{eqn:FcL} that
\begin{equation}\label{eqn:zLF}
(\zeta_{j_1}\cdots \zeta_{j_k})\otimes v^\vee
=
\hdL(\sigma_k(X_{j_1}\cdots X_{j_k}))_1\otimes v^\vee
=F_c(\sigma_k(X_{j_1}\cdots X_{j_k})\otimes v^\vee).
\end{equation}
Now apply $F_c^{-1}$ to both sides to obtain \eqref{eqn:Finv}.
\end{proof}

In summary, the following diagram commutes.
\begin{equation}\label{eqn:dL1}
\begin{tikzcd}[row sep=1cm, column sep=1cm]
& 
\mathrm{Pol}^k(\mathfrak n_+)
\arrow[rd, "\omega_k", "\sim"' sloped]
& \\
\sigma_k(S^k(\fn_-)) 
  \arrow[ru,   "\sim"' sloped, "\hdL(\cdot)_1"]
&
\arrow[u,  pos=0.5, phantom, "\circlearrowleft"]
   & 
S^k(\fn_-)  
\arrow[ll,  "\widetilde{\sigma}_k", "\sim"']
\end{tikzcd}
\end{equation}

