\subsection{The inverse map $\symb_0^{-1}$}
\label{sec:symb2a}

Take $\psi(\zeta) \in  \Pol(\fn_+)\otimes V^\vee\otimes W$.
Then $\psi(\zeta)$ is of the form
\begin{equation*}
\psi(\zeta)=\sum_{i,j}\psi_{i,j}(\zeta) \otimes v_i^\vee \otimes w_j
\end{equation*}
where $\{v_1^\vee,\ldots, v_\ell^\vee\}$ and $\{w_1, \ldots, w_m\}$
are given bases for $V^\vee$ and $W$, respectively. 
Write
\begin{equation*}
\psi_{i,j}(\zeta)=\sum_{\mathbf{r} \in \Z_{\geq 0}^n}a_\mathbf{r} \, 
\zeta_1^{r_1}\cdots \zeta_n^{r_n}
\quad
\text{(finite sum)}
\end{equation*}
for $\mathbf{r} = (r_1, \ldots, r_n)$. 
We put
\begin{equation*}
\psi^\sigma(X):=\sum_{i,j}\psi^\sigma_{i,j}(X) \otimes v_i^\vee \otimes w_j
\in S(\fn_-)\otimes V^\vee \otimes W,
\end{equation*}
where
\begin{equation*}
\psi^\sigma_{i,j}(X)
:=\sum_{\mathbf{r} \in \Z_{\geq 0}^n}a_\mathbf{r}\, \sigma_{|\mathbf{r}|}
(X_1^{r_1}\cdots X_n^{r_n})
\end{equation*}
with $|\mathbf{r}| = r_1 + \cdots + r_n$. 
It then follows from \eqref{eqn:zLF} that  we have
\begin{equation}\label{eqn:Finv3}
\psi(\zeta) = (F_c \otimes \id_W)(\psi^\sigma(X)) =
\sum_{i,j}\widehat{dL}(\psi^\sigma_{i,j}(X))_1\otimes v_i^\vee \otimes w_j.
\end{equation}


\begin{prop}\label{prop:Fc}
The inverse map
\begin{equation*}
(F^{-1}_c \otimes \id_W)\colon 
 \Pol(\fn_+)\otimes V^\vee\otimes W
 \stackrel{\sim}{\To}
 M_\fp^\fg(V^\vee) \otimes W
\end{equation*}
is given by
\begin{equation}\label{eqn:Finv2}
(F^{-1}_c \otimes \id_W)(\psi(\zeta)) =\psi^\sigma(X).
\end{equation}
\end{prop}

\begin{proof}
This is a direct consequence of Theorem \ref{thm:dL1}.
\end{proof}

Now we define $\symb_0^{-1}(\psi(\zeta))$ by
\begin{equation}\label{eqn:symb}
\symb_0^{-1}(\psi(\zeta))
:=\sum_{i,j}\psi^\sigma_{i,j}(dR(X)) \otimes v_i^\vee \otimes w_j.
\end{equation}
Let $\Rest$ denotes the restriction map 
from $C^\infty(G/P',\Cal{W})$ to $C^\infty(G'/P',\Cal{W})$ with respect to 
the morphism $G'/P' \to G/P$.

\begin{thm}\label{thm:symb}
The map $\Rest \circ \symb_0^{-1}$ provides a linear isomorphism
\begin{equation*}
\Rest \circ \symb_0^{-1} \colon 
\Sol(\fn_+;V,W) \stackrel{\sim}{\To} 
\operatorname{Diff}_{G'}(\mathcal V, \mathcal W)
\end{equation*}
such that the following diagram commutes.
\begin{equation}\label{eqn:isom3}
\begin{tikzcd}[row sep=1.2cm, column sep=0.7cm]
& 
\mathrm{Sol}(\mathfrak n_+;V,W)
\arrow[dr,  "\sim"' sloped, "\Rest\, \circ \, \mathrm{symb}_0^{-1}"] \\
\operatorname{Hom}_{\mathfrak{g}',P'}(\Mpp(W^\vee),\Mp(V^\vee)) 
  \arrow[rr, "\sim", "\EuScript{D}"']
  \ar[ur, "\sim"' sloped, "F_c\otimes\mathrm{id}_W"] 
 &
 \arrow[u,  pos=0.5, phantom, "\circlearrowleft"]
 & 
 \operatorname{Diff}_{G'}(\mathcal V, \mathcal W).
%}
\end{tikzcd}
\end{equation}
\end{thm}

\begin{proof}
For $\psi(\zeta) \in  \Sol(\fn_+;V,W) \subset \Pol(\fn_+)\otimes V^\vee\otimes W$,
by \eqref{eqn:HD} and \eqref{eqn:Finv2}, we have 
\begin{align*}
(\EuD \circ (F^{-1}_c \otimes \id_W))(\psi(\zeta))
&=\Rest \circ \sum_{i,j}\psi^\sigma_{i,j}(dR(X)) \otimes v_i^\vee \otimes w_j\\
&=(\Rest\circ \symb_0^{-1})(\psi(\zeta)),
\end{align*}
which concludes the theorem.
\end{proof}

\begin{rem}\label{rem:symb}
In the case that $\fn_{\pm}$ are abelian, we have 
$dR(X_j) = \frac{\partial}{\partial x_j}$ for $j=1,\ldots, n$ 
and 
\begin{equation*}
\sigma_{|\mathbf{r}|}(dR(X_1)^{r_1}\cdots dR(X_n)^{r_n}) 
= \frac{\partial^{|\mathbf{r}|}}{\partial x_1^{r_1} \cdots \partial x_n^{r_n}}
\end{equation*}
via the diffeomorphism \eqref{eqn:diffeo}. Therefore, in the case,
the map $\symb_0^{-1}$ defined in \eqref{eqn:symb} is the inverse $\symb^{-1}$
of the symbol map $\symb$ defined in \cite[Sect.\ 4]{KP1}.
\end{rem}

