\subsection{Truncated symbol map $\symb_0$}
\label{sec:symb2b}

For $D=\sum_{\mathbf{r} \in \Z_{\geq 0}^n} 
p_{\mathbf{r}}(x)\tfrac{\partial^{|\mathbf{r}|}}{\partial x^{\mathbf{r}}} 
\in \C[x, \tfrac{\partial}{\partial x}]$, we write
$D_0 := \sum_{\mathbf{r} \in \Z_{\geq 0}^n} p_{\mathbf{r}}(0)\frac{\partial^{|\mathbf{r}|}}{\partial x^{\mathbf{r}}}
\in \C[\tfrac{\partial}{\partial x}]$,
the constant-coefficient terms of $D$. 
We then define the 
\emph{truncated symbol} $\symb_0(D)$ of $D \in  \C[x, \tfrac{\partial}{\partial x}]$
by
\begin{equation*}
\symb_0(D) :=\symb(D_0),
\end{equation*}
where $\symb$ is the symbol map from
$\C[\tfrac{\partial}{\partial x}]$ to $\C[\zeta]$, namely,
\begin{equation*}
\symb\colon \C[\tfrac{\partial}{\partial x}] \To \C[\zeta],
\quad
\tfrac{\partial}{\partial x_j} \longmapsto \zeta_j.
\end{equation*}
We call the linear map
\begin{equation*}
\symb_0 \colon \C[x, \tfrac{\partial}{\partial x}]\to \C[\zeta],
\quad
D \longmapsto \symb(D_0)
\end{equation*}
the \emph{truncated symbol map}.

The following simple observation on $D_0$ will play a role in later arguments.

\begin{lem}\label{lem:trun}
If $E=\sum_{\mathbf{r} \in \Z^n_{\geq 0}}
a_{\mathbf{r}} \frac{\partial^{|\mathbf{r}|}}{\partial x^{\mathbf{r}}} \in 
\C[\frac{\partial}{\partial x}]$ is a constant-coefficient differential operator
such that
\begin{equation}\label{eqn:trun}
\IP{\delta_0}{D f} = \IP{\delta_0}{E f} 
\quad \text{for all $f \in C^\infty(\R^n)$},
\end{equation}
then $E = D_0$, where $\IP{\cdot}{\cdot}$ denotes the natural paring of 
$\D'_0(\R^n) \times C^\infty(\R^n)$. 
%(We omit the notation $\acts$ for the action of 
%differential operators as it is clear from the context.)
\end{lem}

\begin{proof}
It is clear that $D_0$ satisfies \eqref{eqn:trun}. To show the uniqueness,
given $\mathbf{r} = (r_1, \ldots, r_n) \in \Z_{\geq 0}^n$, 
for $f(x):=(r_1!\cdots r_n!)^{-1}x_1^{r_1}\cdots x_n^{r_n}$,
we have 
\begin{align*}
p_{\mathbf{r}}(0)
=\IP{\delta_0}{D_0  f(x)}
=\IP{\delta_0}{D  f(x)}
=\IP{\delta_0}{E   f(x)}
=a_{\mathbf{r}}.
\end{align*}
Now the lemma follows.
\end{proof}

%\vskip 0.1in

Observe that as $\Pol(\fn_+) = \C[\zeta]$,  we have
\begin{align}\label{eqn:const2}
\symb_0\colon
\C[x, \tfrac{\partial}{\partial x}]
 \otimes \operatorname{Hom}_{\C}(V,W)
 \To &\;
\Pol(\fn_+)
\otimes \operatorname{Hom}_{\C}(V,W) \nonumber \\
\text{{\footnotesize{$\bigcup$}} \hspace{2.8cm}}& 
\hspace{1.48cm} 
\text{{\footnotesize{$\bigcup$}}} \\
\textnormal{Diff}_{G'}(\mathcal{V}, \mathcal{W}) \hspace{2cm} 
&
\hspace{-0.7cm}\To
\hspace{0.5cm} 
\symb_0(\textnormal{Diff}_{G'}(\mathcal{V}, \mathcal{W})).
 \hspace{0.5cm}\nonumber
\end{align}
On the other hand, by \eqref{eqn:Sol2a}, we also have
\begin{equation*}
\mathrm{Sol}(\mathfrak n_+;V,W)
\subset 
\Pol(\fn_+)
\otimes \operatorname{Hom}_{\C}(V,W).
\end{equation*}
Hence, 
\begin{equation*}
\xymatrix@R=-1pt@C=-35pt{
& 
\hspace{-15pt}
\mathrm{Pol}(\mathfrak{n}_+) \otimes \operatorname{Hom}_{\C}(V,W)
&\\
\rotatebox[origin=c]{-45}{$\bigcup$}
%\hspace{5pt}
&
&
\rotatebox[origin=c]{45}{$\bigcup$}
%\hspace{20pt}
\\
\symb_0(\textnormal{Diff}_{G}(\mathcal{V}, \mathcal{W}))
 \hspace{10pt}
&
&
\mathrm{Sol}(\mathfrak n_+;V,W)
}
\end{equation*}
Then we claim that
\begin{equation*}
\symb_0(\textnormal{Diff}_{G}(\mathcal{V}, \mathcal{W}))
= 
\mathrm{Sol}(\mathfrak n_+;V,W).
\end{equation*}

To prove our claim, 
it is shown that  the truncated symbol map $\symb_0$ is the inverse of 
$\symb_0^{-1}$ defined in \eqref{eqn:symb}.
To the end, we first prove one technical lemma that relates
$dL$ with $dR$.
For $u = Z_1\cdots Z_\ell$ with $Z_j \in \fn_-$, write
\begin{equation*}
u^\circ:=(-1)^\ell Z_\ell \cdots Z_1.
\end{equation*}
Then $dL(u)\delta_0$ is defined by
\begin{equation*}
\IP{dL(u)\delta_0}{f} := \IP{\delta_0}{dL(u^\circ) f}
\quad 
\text{for $f \in C^\infty(N_-)$}.
\end{equation*}

\begin{lem}\label{lem:dLR}
For $u\in \Cal{U}(\fn_-)$, we have 
\begin{equation*}
\IP{dL(u)\delta_0}{f} = \IP{\delta_0}{dR(u) f}
\quad 
\text{for $f \in C^\infty(N_-)$}.
\end{equation*}
\end{lem}

\begin{proof}
Observe that $dL(Z)f(e) = -dR(Z)f(e)$ for 
$Z \in \fn_-$ and $f \in C^\infty(N_-)$. Thus,
for 
$f \in C^\infty(N_-)$ and 
$u = Z_1\cdots Z_\ell$ with $Z_j \in \fn_-$, we have
\begin{align*}
\IP{dL(u)\delta_0}{f}
&=\IP{\delta_0}{dL(u^\circ)f}\\[3pt]
&=(-1)^\ell\IP{\delta_0}{dL(Z_n)\cdots dL(Z_1) f}\\[3pt]
&=(-1)^\ell dL(Z_n)\cdots dL(Z_1)f(e)\\[3pt]
&=dR(Z_1)\cdots dR(Z_\ell)f(e)\\[3pt]
&=\IP{\delta_0}{dR(u)f}.
\end{align*}
\end{proof}

By slight abuse of notation, we denote by $(\, \cdot \,)^\vee$ the inverse of the 
algebraic Fourier transform $\widehat{\cdot}$ of the Weyl algebra:
\begin{align*}
(\,\cdot\,)^\vee \colon \C[\zeta, \tfrac{\partial}{\partial \zeta}]
\To \C[x, \tfrac{\partial}{\partial x}],
\quad
\zeta_j \mapsto -\frac{\partial}{\partial x_j},
\quad
\frac{\partial}{\partial \zeta_j} \mapsto x_j.
\end{align*}
Here, we regard the algebraic Fourier transform 
$(\, \cdot \,)^\vee$ as a map 
$(\, \cdot \,)^\vee 
\colon \C[x, \tfrac{\partial}{\partial x}] \to \C[\zeta, \tfrac{\partial}{\partial \zeta}]$.
Recall from \eqref{eqn:VP1} that
\begin{alignat}{4}\label{eqn:VP06}
\Cal{U}(\fn_-)\otimes V^\vee
&\stackrel{\sim}{\To}  \Cal{D}'_{0}(\fn_-(\R),V^\vee)
&&\stackrel{\sim}{\To}  \Pol(\fn_+)\otimes V^\vee\\
\rotatebox{90}{$\in$}\hspace{20pt}
&\hspace{60pt}\rotatebox{90}{$\in$}
&&\hspace{60pt}\rotatebox{90}{$\in$}& \nonumber\\[-2pt]
u\otimes v^\vee \hspace{8pt}
&\longmapsto\hspace{5pt} dL(u)\delta_0 \otimes v^\vee 
&&\longmapsto \hspace{5pt} (\hdL(u) \acts 1)\otimes v^\vee \nonumber
\end{alignat}
with $\hdL(u) \acts 1 = \widehat{dL(u)\delta_0}$. Thus,
\begin{equation*}%\label{eqn:invF}
dL(u)\delta_0 = (\widehat{dL(u)\delta_0})^\vee = 
(\hdL(u) \acts 1)^\vee.
\end{equation*}
It then follows from 
\eqref{eqn:zLF} that
$\sigma_{k}(dL(X_{j_1})\cdots dL(X_{j_k}))\delta_0$ 
is given by
\begin{align}\label{eqn:dLD}
\sigma_{k}(dL(X_{j_1})\cdots dL(X_{j_k}))\delta_0\nonumber
&=(\hdL(\sigma_k(X_{j_1}\cdots X_{j_k}))\acts 1)^\vee \nonumber \\[3pt]
&=(\zeta_{j_1}\cdots \zeta_{j_k}\acts 1)^\vee \nonumber \\[3pt]
&= (-1)^k\partial_{j_1} \cdots \partial_{j_k} \delta_0.
\end{align}


Now we are ready to prove our claim.

\begin{thm}\label{thm:symb2}
The truncated symbol map $\symb_0$ 
is the inverse of $\Rest \circ \symb_0^{-1}$. 
Consequently, it gives rise to a linear isomorphism
\begin{equation*}
\symb_0 \colon \Diff_{G'}(\Cal{V}, \Cal{W}) \stackrel{\sim}{\To}
\Sol(\fn_+;V,W).
\end{equation*}
\end{thm}

\begin{proof}
Take $\mathbb{D} =\Rest \circ \sum_{i,j}dR(u_{i,j}) \otimes v_i^\vee\otimes w_j
\in \Diff_{G'}(\Cal{V}, \Cal{W})$ with $u_{i,j} \in \Cal{U}(\fn_-)$.
It follows from Theorem \ref{thm:symb} that $\mathbb{D}$ 
can be rewritten as
\begin{equation*}
\mathbb{D}=\Rest \circ \sum_{i,j}\psi^\sigma_{i,j}(dR(X))\otimes v_i^\vee\otimes w_j,
\end{equation*}
where 
\begin{equation*}
\psi^\sigma_{i,j}(dR(X))=\sum_{\mathbf{r} \in \Z_{\geq 0}^n}a_\mathbf{r}  
\sigma_{|\mathbf{r}|}(dR(X_1)^{r_1}\cdots dR(X_n)^{r_n}).
\end{equation*}
It follows from \eqref{eqn:symb} that the polynomial
\begin{equation*}
\psi(\zeta)=\sum_{i,j}\psi_{i,j}(\zeta) \otimes v_i^\vee\otimes w_j 
\end{equation*}
with
\begin{equation*}
\psi_{i,j}(\zeta)=\sum_{\mathbf{r} \in\Z_{\geq 0}^n}a_\mathbf{r}  
\zeta_1^{r_1}\cdots \zeta_n^{r_n}
\end{equation*}
satisfies $\psi(\zeta) \in \Sol(\fn_+;V,W)$ and 
$\Rest\circ \symb_0^{-1}(\psi(\zeta))=\mathbb{D}$. 
Thus, to prove the assertion,
it suffices to show that  
\begin{equation*}
\symb_0(\sigma_{|\mathbf{r}|}(dR(X_1)^{r_1}\cdots dR(X_n)^{r_n}))
=\zeta_1^{r_1}\cdots \zeta_n^{r_n},
\end{equation*}
that is,
\begin{equation*}
\symb(\sigma_{|\mathbf{r}|}(dR(X_1)^{r_1}\cdots dR(X_n)^{r_n})_0)
=\zeta_1^{r_1}\cdots \zeta_n^{r_n},
\end{equation*}
where $\sigma_{|\mathbf{r}|}(dR(X_1)^{r_1}\cdots dR(X_n)^{r_n})_0$ is the 
constant-coefficient part of 
$\sigma_{|\mathbf{r}|}(dR(X_1)^{r_1}\cdots dR(X_n)^{r_n})$.

By Lemma \ref{lem:dLR} and \eqref{eqn:dLD}, 
for $f \in C^\infty(N_-)\simeq C^\infty(\R^n)$, we have 
\begin{align*}
\IP{\delta_0}{\sigma_{|\mathbf{r}|}(dR(X_1)^{r_1}\cdots dR(X_n)^{r_n})_0
f}
&=\IP{\delta_0}{\sigma_{|\mathbf{r}|}(dR(X_1)^{r_1}\cdots dR(X_n)^{r_n})f}\\[3pt]
&=\IP{\sigma_{|\mathbf{r}|}(dL(X_1)^{r_1}\cdots dL(X_n)^{r_n})\delta_0}{f}\\[3pt]
&=
(-1)^{|\mathbf{r}|}\IP{\partial_1^{r_1}\cdots \partial_n^{r_n} \delta_0}{f} \\[3pt]
&=\IP{\delta_0}{\partial_1^{r_1}\cdots \partial_n^{r_n}f},
\end{align*}
which, by Lemma \ref{lem:trun}, yields
\begin{equation*}
\sigma_{|\mathbf{r}|}(dR(X_1)^{r_1}\cdots dR(X_n)^{r_n})_0 
= \partial_1^{r_1}\cdots \partial_n^{r_n}.
\end{equation*}
Therefore, we obtain
\begin{equation*}
\symb(\sigma_{|\mathbf{r}|}(dR(X_1)^{r_1}\cdots dR(X_n)^{r_n})_0)
=\symb(\partial_1^{r_1}\cdots \partial_n^{r_n}) 
= \zeta_1^{r_1}\cdots \zeta_n^{r_n}.
\end{equation*}
This concludes the theorem.
\end{proof}

\begin{rem}
If $\fn_+$ is abelian, then $\mathbb{D}=\mathbb{D}_0$  
(cf.\ \cite[Sect.\ 2.8]{KuOr25a}). Thus, in this case, we have
$\symb_0(\mathbb{D}) = \symb(\mathbb{D})$.
\end{rem}

\begin{rem}
To compute the truncated symbol $\symb_0(\mathbb{D})$ of $\mathbb{D}$,
it is not necessary to rewrite it in the symmetrized form. 
For $\mathbb{D} =\Rest \circ 
\sum_{i,j}dR(u_{i,j}) \otimes v_i^\vee\otimes w_j
\in \Diff_{G'}(\Cal{V}, \Cal{W})$ with $u_{i,j} \in \Cal{U}(\fn_-)$,
the truncated symbol $\symb_0(\mathbb{D})$ is given by
\begin{equation*}
\symb_0(\mathbb{D})
=\sum_{i,j} \symb(dR(u_{i,j})_0) \otimes v_i^\vee\otimes w_j.
\end{equation*}
Moreover, it follows from  
the diagrams \eqref{eqn:isom3} and \eqref{eqn:VP06}
that $\symb_0(\mathbb{D})$ is also given by
\begin{equation*}
\symb_0(\mathbb{D}) = 
\sum_{i,j}\hdL(u_{i,j})_1 \otimes v_i^\vee\otimes w_j
\end{equation*}
with $\hdL(u_{i,j})_1 = \hdL(u_{i,j}) \acts 1$.
We shall discuss a concrete example in  Example \ref{example:symb3}.
\end{rem}



%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{A recipe of the F-method}
\label{sec:recipe}

By \eqref{eqn:Sol} and Theorem \ref{thm:symb},
one can classify and construct DSBOs
$\bD \in  \operatorname{Diff}_{G'}(\mathcal V, \mathcal W)$ and
$(\fg', P')$-homomorphisms $\Phi \in 
\Hom_{\mathfrak{g}',P'}(\Mpp(W^\vee),\Mp(V^\vee))$
by computing $\psi \in \mathrm{Sol}(\mathfrak n_+;V,W)$ as follows.
\vskip 0.1in

\begin{enumerate}

\item[Step 1]
Compute $d\pi_{(\xi,\lambda)^*}(C)$ and 
$\widehat{d\pi_{(\xi,\lambda)^*}}(C)$
for $C \in \fn_+'$.
\vskip 0.1in

\item[Step 2]
Classify and construct
$\psi \in \Hom_{M'A'}(W^\vee, \Pol(\fn_+)\otimes V^\vee)$.
\vskip 0.1in

\item[Step 3]
Solve the F-system \eqref{eqn:Fsys}
for $\psi \in \Hom_{M'A'}(W^\vee, \Pol(\fn_+)\otimes V^\vee)$.
\vskip 0.1in

\item[Step 4]
For $\psi \in \mathrm{Sol}(\mathfrak n_+;V,W)$ obtained in Step 3,
do the following.
\vskip 0.1in

\begin{enumerate}
\item[Step 4a]
Apply $\Rest \circ \symb_0^{-1}$ 
to $\psi \in \mathrm{Sol}(\mathfrak n_+;V,W)$
to obtain $\bD \in  \operatorname{Diff}_{G'}(\mathcal V, \mathcal W)$.
\vskip 0.1in
\item[Step 4b]
Apply $F_c^{-1} \otimes \id_W$ 
to $\psi \in \mathrm{Sol}(\mathfrak n_+;V,W)$
to obtain $\Phi \in \operatorname{Hom}_{\mathfrak{g}',P'}
(\Mpp(W^\vee), \Mp(V^\vee))$.
\end{enumerate}

\vskip 0.2in

\end{enumerate}

In Sections \ref{sec:proof1} and \ref{sec:proof2},
we shall apply the recipe to classify and construct  
differential intertwining operators $\D$ and homomorphisms $\varphi$
between Verma modules
for $G=G'=SL(3,\R)$ with $P=P'=B$, where $B$ is
a minimal parabolic subgroup of $G$.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{DIOs $\D$ and $(\fg, B)$-homomorphisms $\varphi$ 
between Verma modules for $SL(3,\R)$}\label{sec:SL3}

The aim of this section is to 
classify and construct  DIOs $\D$ and $(\fg, B)$-homomorphisms 
$\varphi$ between Verma modules for 
 $G=SL(3,\R)$ and $P=B$, a minimal parabolic subgroup of $G$.
The classification is done in Theorems \ref{thm:DIO1} and 
\ref{thm:Hom1}, while 
the explicit formulas are given in Theorems \ref{thm:DIO2} and \ref{thm:Hom2}.
At the end of this section we also give the classification of 
$(\fg, B)$-homomorphisms $\varphi$ in terms of infinitesimal characters.
The proof of these results will be discussed in detail in 
Sections \ref{sec:proof1} and \ref{sec:proof2}.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Notation and normalizations}
\label{subsec:SL3}

We start with some notation.
Let $G = SL(3,\R)$ with Lie algebra $\fg(\R)=\f{sl}(3,\R)$.
We put
\begin{alignat*}{3}
N_1^+:&=E_{1,2},
\quad
N_2^+&:=E_{2,3},
\quad
N_3^+&:=E_{1,3},\\[3pt]
N_1^-&:=E_{2,1},
\quad
N_2^-&:=E_{3,2},
\quad
N_3^-&:=E_{3,1},
\end{alignat*}
where $E_{i,j}$ denote matrix units.
We also set $\fa(\R):=\text{span}_\R\{E_{i,i}-E_{i+1, i+1}: i=1, 2\}$ 
and $\fn_\pm(\R):=\spn_\R\{N_1^\pm, N_2^\pm, N_3^\pm\}$.
Then $\fg(\R) = \fn_-(\R) \oplus \fa(\R) \oplus \fn_+(\R)$ is a Gelfand--Naimark 
decomposition of $\fg(\R)$ and
$\fb(\R):=\fa(\R) \oplus \fn_+(\R)$ is a minimal parabolic subalgebra of $\fg(\R)$.

Let $K=SO(3)$ with Lie algebra $\fk(\R)=\f{so}(3)$ . 
Also, let $A$ and $N_+$ 
be the analytic subgroups of $G$ with Lie algebras 
$\fa(\R)$ and $\fn_+(\R)$, respectively.
Then $G=K AN_+$ is an Iwasawa decomposition of $G$.
We write $M = Z_{K}(\fa(\R))$, so that
$B:=MAN_+$ is a minimal parabolic subgroup of $G$ 
with Lie algebra $\fb(\R)$.

We denote by $\fg$ the complexification of the Lie algebra $\fg(\R)$ of $G$.
A similar convention is employed also for subgroups of $G$;
for instance, $\mathfrak{b}= \mathfrak{a} \oplus \mathfrak{n}_+$ 
is a Borel subalgebra of $\fg= \f{sl}(3,\C)$.

Let $\Delta\equiv \Delta(\mathfrak{g},\mathfrak{a})$ denote
the set of roots of $\mathfrak{g}$ with respect to $\mathfrak{a}$. 
We denote by $\Delta^+$ and $\Pi$ 
the positive system corresponding to $\fb$ and 
the set of simple roots of $\gD^+$, respectively.
Then we have 
\begin{equation*}
\gD^+=\{\gamma_1-\gamma_2, \gamma_2-\gamma_3, \gamma_1-\gamma_3\}
\quad \text{and} \quad
\Pi=\{\gamma_1-\gamma_2, \gamma_2-\gamma_3\},
\end{equation*}
where $\gamma_j$ are the dual basis of $E_{j,j}$ for $j=1, 2, 3$.
The root spaces $\fg_{\pm(\gamma_i-\gamma_j)}$ for 
$1\leq i < j \leq 3$ are then given as 
\begin{equation*}
\fg_{\pm(\gamma_1-\gamma_2)} = \C N_1^{\pm},
\quad
\fg_{\pm(\gamma_2-\gamma_3)} = \C N_2^{\pm}, 
\quad
\fg_{\pm(\gamma_1-\gamma_3)} = \C N_3^{\pm}.
\end{equation*}
We write $\rho$ for half the sum of the positive roots, namely,
$\rho=\gamma_1 - \gamma_3$.

For a closed subgroup $J$ of $G$, we denote by $\Irr(J)$ and $\Irr(J)_{\fin}$
the sets of equivalence classes of irreducible representations of $J$  and 
irreducible finite-dimensional representations of $J$, respectively.

\vskip 0.1in

Write 
\begin{equation}\label{eqn:H}
H_1 := 
\begin{small}\begin{pmatrix}1 & 0 & 0 \\ 0 & -1 & 0 \\ 0 & 0 & 0\end{pmatrix}\end{small}
\quad
\text{and}
\quad
H_2 := 
\begin{small}\begin{pmatrix}0 & 0 & 0 \\ 0 & 1 & 0 \\ 0 & 0 & -1\end{pmatrix}\end{small}.
\end{equation}
Then $\fa(\R) = \spn_{\R}\{ H_1, H_2\}$. For $\lambda_1, \lambda_2 \in \C$, 
we define a one-dimensional representation 
$\C_{(\lambda_1, \lambda_2)}:=(\chi^{(\lambda_1,\lambda_2)}_A, \C)$ 
of $A = \exp(\fa(\R))$ by
\begin{equation}\label{eqn:chi}
\chi_A^{(\lambda_1,\lambda_2)} \colon \exp(t_1 H_1 + t_2 H_2) 
\longmapsto \exp(\lambda_1t_1 + \lambda_2 t_2).
\end{equation}
Then $\Irr(A)$ is given by
\begin{equation*}
\Irr(A)=\{\C_{(\lambda_1, \lambda_2)} : \lambda_1, \lambda_2 \in \C\} \simeq \C^2.
\end{equation*}

Let
\begin{equation*}
m_0:=
\begin{small}
\begin{pmatrix}
1& 0 & 0\\
0 & 1 & 0\\
0 & 0 & 1
\end{pmatrix}
\end{small}
,\;
m_1:=
\begin{small}
\begin{pmatrix}
-1& 0 & 0\\
0 & 1 & 0\\
0 & 0 & -1
\end{pmatrix}
\end{small}
,\;
m_2:=
\begin{small}
\begin{pmatrix}
1& 0 & 0\\
0 & -1 & 0\\
0 & 0 & -1
\end{pmatrix}
\end{small}
,\;
m_3:=
\begin{small}
\begin{pmatrix}
-1& 0 & 0\\
0 & -1 & 0\\
0 & 0 & 1
\end{pmatrix}.
\end{small}
\end{equation*}
Then 
\begin{equation*}
M=\{m_0, m_1, m_2, m_3\}.
\end{equation*}
For $\eps, \eps' \in \{\pm\}$,
a one-dimensional $M$-representation 
$\C_{(\eps,\eps')}:=(\chi_M^{(\eps, \eps')}, \C)$ is defined by
a character $\chi^{(\eps,\eps')}_M\colon M \to \{\pm 1\}$ given as
\begin{equation*}
\chi_M^{(\eps, \eps')}
(\mathrm{diag}(b_1, b_2, b_3))
:=|b_1|_{\eps}\;|b_3|_{\eps'},
\end{equation*}
where
$|b|_+:=|b|$ and $|b|_-:=b$.
Table \ref{table:char} summarizes the values of the character 
$(\eps,\eps') =\chi_M^{(\eps,\eps')}$ at each $m_j \in M$.
The set $\Irr(M)$ of 
equivalence classes of irreducible representations of $M$ is given as
\begin{equation}\label{eqn:char}
\Irr(M)= \{ \pp, \pmi, \mip, \mm\} \simeq (\Z/2\Z)^2.
\end{equation}

\begin{table}
\caption{Character table for $(\eps,\eps')$}
\begin{center}
\begin{normalsize}
