Since $\Irr(B)_{\fin}\simeq \Irr(M) \times \Irr(A)$, the set $\Irr(B)_\fin$ can be 
parametrized by
\begin{equation*}
\Irr(B)_{\fin}\simeq (\Z/2\Z)^2 \times \C^2.
\end{equation*}
For $(\eps_1, \eps_2;\lambda_1,\lambda_2) \in \Irr(B)_{\fin}$,
we write
\begin{equation}\label{eqn:Ind}
I(\lambda_1,\lambda_2)^{(\eps_1,\eps_2)} 
:= 
\Ind_{B}^G\left(\C_{(\eps_1,\eps_2)} \boxtimes \C_{(\lambda_1,\lambda_2)}\right)
\end{equation}
for an unnormalized parabolically induced representation 
(a principal series representation) of $G$.
Also, we denote by 
\begin{equation}\label{eqn:Verma}
M(\lambda_1,\lambda_2)^{(\eps_1,\eps_2)} 
:=\Cal{U}(\fg) \otimes_{\Cal{U}(\fb)}
(\C_{(\eps_1, \eps_2)}\boxtimes \C_{(\lambda_1,\lambda_2)})
\end{equation}
the Verma module induced from 
$\C_{(\eps_1, \eps_2)}\boxtimes \C_{(\lambda_1,\lambda_2)}$
as a $(\fg, B)$-module. When we regard it merely as a $\fg$-module,
we simply write $M(\lambda_1,\lambda_2)$. 

We shall classify and construct  differential intertwining  operators 
\begin{equation*}
\D \in 
\Diff_G(I(\lambda_1, \lambda_2)^{(\eps_1, \eps_2)}, I(\nu_1,\nu_2)^{(\delta_1,\delta_2)})
\end{equation*}
and $(\fg, B)$-homomorphisms
\begin{equation*}
\varphi \in 
\Hom_{\fg, B}(
M(-\nu_1,-\nu_2)^{(\delta_1, \delta_2)},
M(-\lambda_1, -\lambda_2)^{(\eps_1, \eps_2)})
\end{equation*}
in the next subsections.
%in Sections \ref{sec:DIO}.


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Classification of DIOs $\D$ and $(\fg, B)$-homomorphisms $\varphi$}
\label{sec:DIO}

We put
\begin{align*}
\Lambda_a&:=(-\Z_{\geq 0})\times \C, \\[3pt]
\swap{\Lambda}_a&:=\C \times (-\Z_{\geq 0}), \\[3pt]
\Lambda_b&:=\{(1-k, 1-\ell+k) : k, \ell \in 1+\Z_{\geq 0}\}, \\[3pt]
\swap{\Lambda}_b&:=\{(1-k+\ell, 1-\ell) : k, \ell \in 1+\Z_{\geq 0}\}, \\[3pt]
\Lambda_c&:=\{(\tfrac{1}{2}(2-k-s), \tfrac{1}{2}(2-k+s)) : k \in 1+\Z_{\geq 0} \; 
\text{and} \;  s \in \C\}.
\end{align*}
Remark that, for instance, the set $\Lambda_b$ can also be defined as 
$\Lambda_b=\{(-k, 1-\ell+k) : k, \ell \in \Z_{\geq 0}\}$. 
We defined $\Lambda_b$, $\swap{\Lambda}_b$,
and $\Lambda_c$ as above for convenience to later arguments
(see, for instance, Sections \ref{sec:Fsys1} and \ref{subsec:Verma2}).


Write
$\eps:= (\eps_1, \eps_2),\,
\delta:= (\delta_1, \delta_2)
\in (\Z/2\Z)^2$
with 
$\Z/2\Z = \{ \pm 1\} \equiv \{\pm\}$
and 
$\lambda:=(\lambda_1, \lambda_2),\,
\nu:=(\nu_1,\nu_2)
\in \C^2$.
We then define 
\begin{equation*}
\Xi_a, \;
\swap{\Xi}_a, \;
\Xi_b, \;
\swap{\Xi}_b,\;
\Xi_c
\subset (\Z/2\Z)^4 \times \C^4
\end{equation*}
as follows. 
\begin{alignat*}{2}
&\Xi_a&&:=\{(\eps, \delta; \lambda, \nu) \in (\Z/2\Z)^4\times \C^4: 
\text{\eqref{eqn:L1} holds.}\} \\[3pt]
&\swap{\Xi}_a&&:=\{(\eps, \delta; \lambda, \nu) \in (\Z/2\Z)^4\times \C^4: 
\text{\eqref{eqn:L2} holds.}\} \\[3pt]
&\Xi_b&&:=\{(\eps, \delta; \lambda, \nu) \in (\Z/2\Z)^4\times \C^4: 
\text{\eqref{eqn:L3+} holds.}\}  \\[3pt]
&\swap{\Xi}_b&&:=\{(\eps, \delta; \lambda, \nu) \in (\Z/2\Z)^4\times \C^4: 
\text{\eqref{eqn:L3-} holds.}\} \\[3pt]
&\Xi_c&&:=\{(\eps, \delta; \lambda, \nu) \in (\Z/2\Z)^4\times \C^4: 
\text{\eqref{eqn:L4} holds.}\} 
\end{alignat*}
\begin{alignat}{3}
&(\lambda_1, \lambda_2) \in \Lambda_a \quad
&&(\nu_1, \nu_2) = (2-\lambda_1, \lambda_1 + \lambda_2 -1 ), \quad
&&(\delta_1, \delta_2) = (\eps_1, \eps_2\cdot (-)^{1-\lambda_1}) \label{eqn:L1}\\[3pt]
&(\lambda_1, \lambda_2) \in \swap{\Lambda}_a, \quad
&&(\nu_1, \nu_2) = (\lambda_1 + \lambda_2 -1, 2-\lambda_2), \quad
&&(\delta_1, \delta_2) = (\eps_1\cdot (-)^{1-\lambda_2}, \eps_2) \label{eqn:L2} \\[3pt]
&(\lambda_1, \lambda_2) \in \Lambda_b, \quad
&&(\nu_1, \nu_2) = (\lambda_2, 3-\lambda_1-\lambda_2), \quad
&&(\delta_1, \delta_2) 
= (\eps_1\cdot (-)^{2-\lambda_1-\lambda_2}, \eps_2\cdot (-)^{1-\lambda_1})\label{eqn:L3+} \\[3pt]
&(\lambda_1, \lambda_2) \in \swap{\Lambda}_b, \quad
&&(\nu_1, \nu_2) = (3-\lambda_1-\lambda_2, \lambda_1), \quad
&&(\delta_1, \delta_2) 
= (\eps_1\cdot (-)^{1-\lambda_2}, \eps_2\cdot (-)^{2-\lambda_1-\lambda_2})\label{eqn:L3-} \\[3pt]
&(\lambda_1, \lambda_2) \in \Lambda_c, \quad
&&(\nu_1, \nu_2) = (2-\lambda_2, 2-\lambda_1), \quad
&&(\delta_1, \delta_2) 
= (\eps_1\cdot (-)^{2-\lambda_1-\lambda_2}, \eps_2\cdot (-)^{2-\lambda_1-\lambda_2}).
\label{eqn:L4}
\end{alignat}

We put
\begin{equation*}
\Xi: = \Xi_a \cup \swap{\Xi}_a \cup \Xi_b \cup \swap{\Xi}_b \cup \Xi_c.
\end{equation*}

\begin{thm}\label{thm:DIO1}
The following conditions on $(\eps, \delta; \lambda, \nu) \in (\Z/2\Z)^4\times \C^4$ 
are equivalent:

\begin{enumerate}

\item[\emph{(i)}] 
$\Diff_G(I(\lambda_1, \lambda_2)^{(\eps_1, \eps_2)}, I(\nu_1,\nu_2)^{(\delta_1, \delta_2)})
\neq \{0\}$.

\vskip 0.1in

\item[\emph{(ii)}] 
$\dim_\C \Diff_G(I(\lambda_1, \lambda_2)^{(\eps_1, \eps_2)}, 
I(\nu_1,\nu_2)^{(\delta_1, \delta_2)})=1$.

\vskip 0.1in

\item[\emph{(iii)}] 
One of the following conditions holds.
\vskip 0.1in

\begin{enumerate}
\item[\emph{(iii-a)}] $(\delta;\nu) = (\eps; \lambda)$.
\vskip 0.1in

\item[\emph{(iii-b)}] $(\eps, \delta; \lambda, \nu) \in \Xi$.

\end{enumerate}

\end{enumerate}

\end{thm}

\begin{thm}\label{thm:Hom1}
The following conditions on $(\eps, \delta; \lambda, \nu) \in (\Z/2\Z)^4\times \C^4$ 
are equivalent:

\begin{enumerate}

\item[\emph{(i)}] 
$
\Hom_{\fg, B}(
M(-\nu_1,-\nu_2)^{(\delta_1, \delta_2)},
M(-\lambda_1, -\lambda_2)^{(\eps_1, \eps_2)})
\neq \{0\}
$.

\vskip 0.1in

\item[\emph{(ii)}] 
$\dim_\C 
\Hom_{\fg, B}(
M(-\nu_1,-\nu_2)^{(\delta_1, \delta_2)},
M(-\lambda_1, -\lambda_2)^{(\eps_1, \eps_2)})
=1
$.

\vskip 0.1in

\item[\emph{(iii)}] 
One of the following conditions holds.
\vskip 0.1in

\begin{enumerate}
\item[\emph{(iii-a)}] $(\delta;\nu) = (\eps; \lambda)$.
\vskip 0.1in

\item[\emph{(iii-b)}] $(\eps, \delta; \lambda, \nu) \in \Xi$.

\end{enumerate}

\end{enumerate}

\end{thm}


