\subsection{Construction of DIOs $\D$ and $(\fg, B)$-homomorphisms $\varphi$}
\label{sec:construction}

Next we shall give the explicit formulas for DIOs $\D$ 
and $(\fg,B)$-homomorphisms $\varphi$. Toward the end, let 
$\{\Cay_m(x;y)\}_{m=0}^\infty$ denote the Cayley continuants, that is,

\begin{itemize}

\item[$\diamond$] $m =0:$ $\Cay_0(x;y)=1$,
\vskip 0.1in

\item[$\diamond$] $m=1:$ $\Cay_1(x;y) = x$,
\vskip 0.1in

\item[$\diamond$] $m \geq 2:$ $\Cay_m(x;y) = 
\begin{small}
\begin{vmatrix}
x& 1    &              &            &             &       \\
y& x    &     2       &            &             &       \\
  & y-1 &     x       &  3        &             &       \\
  &       &  \dots  &  \dots & \dots  &       \\
  &       &              &y-m+3   &x            & m-1 \\
  &       &              &            &y-m+2     & x    
\end{vmatrix}
\end{small}
$.
%\vskip 0.1in
\end{itemize}
The polynomial $\Cay_m(x;y)$ is also given as 
\begin{equation*}
\Cay_m(x;y)=\sum_{j=0}^m\binom{m}{j}
\left(\frac{x+y}{2}\right)^{\underline{j}}
\left(\frac{x-y}{2}\right)^{\overline{j}},
\end{equation*}
where $r^{\underline{j}}$ and $r^{\overline{j}}$ denote the 
falling factorial and rising factorial, respectively, namely,
\begin{align*}
r^{\underline{j}}&:=r(r-1)(r-2)\cdots (r-j+1)
=\frac{\Gamma(r+1)}{\Gamma(r-j+1)},\\[3pt]
r^{\overline{j}}&:=r(r+1)(r+2)\cdots (r+j-1)
=\frac{\Gamma(r+j)}{\Gamma(r)}.
\end{align*}
(See, for instance, \cite[(5)]{MT05}.)

Let $\Cal{A}$ be an algebra over $\C$.
Then, for $k, \ell \in \Z_{\geq 0}$ and $s \in \C$, we define polynomials
$\eta_+^{(k,\ell)}(a_1,a_2,a_3)$, 
$\eta_-^{(k,\ell)}(a_1,a_2,a_3)$,  
and $\eta_c^{(s;k)}(a_1,a_2,a_3)$ on $\Cal{A}$ as follows.
\begin{align}
\eta_+^{(k,\ell)}(a_1,a_2,a_3) &:= \sum_{m=0}^{\min(k,\ell)} \frac{1}{2^m}m!\binom{k}{m}\binom{\ell}{m}
\sigma_{k+\ell-m}(a_1^{k-m} a_2^{\ell-m} a_3^m) \label{eqn:eta1} \\[3pt]
\eta_-^{(k,\ell)}(a_1,a_2,a_3) &:= \sum_{m=0}^{\min(k,\ell)} \frac{(-1)^m}{2^m}m!\binom{k}{m}\binom{\ell}{m}
\sigma_{k+\ell-m}(a_1^{k-m} a_2^{\ell-m} a_3^m) \label{eqn:eta2}\\[3pt]
\eta_c^{(s;k)}(a_1,a_2,a_3)&:= \sum_{m=0}^{k} \frac{1}{2^m}\binom{k}{m}\Cay_m(s;k)
\sigma_{2k-m}(a_1^{k-m} a_2^{k-m} a_3^m) \label{eqn:eta3}
\end{align}

As in \eqref{eqn:DN}, we understand 
$\D \in 
\Diff_G(I(\lambda_1, \lambda_2)^{(\eps_1, \eps_2)}, 
I(\nu_1,\nu_2)^{(\delta_1,\delta_2)})$
for $(\eps, \delta; \lambda, \nu) \in \Xi$ as a linear map
$\D\colon C^\infty(\R^3) \to C^\infty(\R^3)$
via the diffeomorphism
\begin{equation}\label{eqn:n-}
\R^3 \stackrel{\sim}{\To} N_-, \quad (x_1, x_2, x_3) 
\mapsto \exp(x_1 N_1^- + x_2 N_2^- +  x_3 N_3^-).
\end{equation}


We set
\begin{align*}
\D_1
:=dR(N_1^-)
=\frac{\partial}{\partial x_1} + \frac{x_2}{2}\frac{\partial}{\partial x_3},%\\[3pt]
\quad
\D_2
:=dR(N_2^-)
=\frac{\partial}{\partial x_2} - \frac{x_1}{2}\frac{\partial}{\partial x_3},%\\[3pt]
\quad
\D_3
:=dR(N_3^-)=\frac{\partial}{\partial x_3}.
\end{align*}
(We shall  discuss the formulas for $dR(N_j^-)$ in Lemma \ref{lem:dR}.) Then, 
for $k, \ell \in \Z_{\geq 0}$ and $s \in \C$, we define three differential operators
$\D_+^{(k,\ell)}$, $\D_-^{(k,\ell)}$, and $\D_c^{(s;k)}$ as follows.
\begin{equation*}
\D_+^{(k,\ell)}:=\eta_+^{(k,\ell)}(\D_1,\D_2,\D_3), \quad
\D_-^{(k,\ell)}:=\eta_-^{(k,\ell)}(\D_1,\D_2,\D_3), \quad
\D_c^{(s;k)} := \eta_c^{(s;k)}(\D_1,\D_2,\D_3).
\end{equation*}

\vskip 0.1in

\begin{thm}\label{thm:DIO2} 
The following holds.
\begin{equation*}
\Diff_G(I(\lambda_1, \lambda_2)^{(\eps_1, \eps_2)}, 
I(\nu_1,\nu_2)^{(\delta_1,\delta_2)})
=
\begin{cases}
\C \id & \emph{if $(\delta;\nu) = (\eps; \lambda)$},\\[3pt]
\C \D_1^{1-\lambda_1} & \emph{if $(\eps, \delta; \lambda,\nu) \in \Xi_a$}, \\[3pt]
\C \D_2^{1-\lambda_2} & \emph{if $(\eps, \delta; \lambda,\nu) \in \swap{\Xi}_a$}, \\[3pt]
\C \D_+^{(1-\lambda_1, 2-\lambda_1-\lambda_2)} & \emph{if $(\eps, \delta; \lambda,\nu) \in \Xi_b$}, \\[3pt]
\C \D_-^{(2-\lambda_1-\lambda_2, 1-\lambda_2)} & \emph{if $(\eps, \delta; \lambda,\nu) \in \swap{\Xi}_b$}, \\[3pt]
\C \D_c^{(\lambda_1-\lambda_2; 2-\lambda_1-\lambda_2)} & \emph{if $(\eps, \delta; \lambda,\nu) \in \Xi_c$}, \\[3pt]
\{0\} & \emph{otherwise}.
\end{cases}
\end{equation*}
\end{thm}

The order of the DIO $\D$ for $(\eps, \delta; \lambda,\nu) \in \Xi$ is 
given by $(\nu_1+\nu_2)-(\lambda_1+\lambda_2)$.

\vskip 0.1in

Next, we give explicit formulas of $(\fg,B)$-homomorphisms $\varphi$.
For $k,\ell \in \Z_{\geq 0}$ and $s \in \C$, 
we define maps 
\begin{equation*}
\varphi_1^{(k)},
\varphi_2^{(k)},
\varphi_+^{(k,\ell)},
\varphi_-^{(k,\ell)},
\varphi_c^{(s;k)} 
\in \Hom_{\C}(\C , \Cal{U}(\fn_-) \otimes \C)
\end{equation*}
as follows.
\begin{align*}
\varphi_1^{(k)} &\colon \mathbb{1} 
\longmapsto (N_1^-)^{k} \otimes \mathbb{1}, \\[3pt]
\varphi_2^{(k)} & \colon \mathbb{1}
\longmapsto (N_2^-)^{k} \otimes \mathbb{1}, \\[3pt]
\varphi_+^{(k,\ell)}& \colon \mathbb{1} 
\longmapsto \eta_+^{(k,\ell)}(N_1^-,N_2^-,N_3^-) \otimes \mathbb{1}, \\[3pt]
\varphi_-^{(k,\ell)}& \colon \mathbb{1}
\longmapsto \eta_-^{(k,\ell)}(N_1^-,N_2^-,N_3^-) \otimes \mathbb{1}, \\[3pt]
\varphi_c^{(s;k)} & \colon \mathbb{1}
\longmapsto \eta_c^{(s;k)}(N_1^-,N_2^-,N_3^-)\otimes \mathbb{1}.
\end{align*}

Via the identification
\begin{align*}
&\Hom_{\fg, B}(
M(-\nu_1,-\nu_2)^{(\delta_1, \delta_2)},
M(-\lambda_1, -\lambda_2)^{(\eps_1, \eps_2)})\\
&\simeq
\Hom_B(\C_{(\delta_1,\delta_2)} \boxtimes \C_{(-\nu_1,-\nu_2)},
M(-\lambda_1, -\lambda_2)^{(\eps_1, \eps_2)}),
\end{align*}
the $(\fg,B)$-homomorphisms $\varphi$ are given as follows.

\begin{thm}\label{thm:Hom2} 
The following holds.
\begin{equation*}
\Hom_{\fg, B}(
M(-\nu_1,-\nu_2)^{(\delta_1, \delta_2)},
M(-\lambda_1, -\lambda_2)^{(\eps_1, \eps_2)})
=
\begin{cases}
\C \id & \emph{if $(\delta;\nu) = (\eps; \lambda)$},\\[3pt]
\C \varphi_1^{(1-\lambda_1)} & \emph{if $(\eps, \delta; \lambda,\nu) \in \Xi_a$}, \\[3pt]
\C \varphi_2^{(1-\lambda_2)} & \emph{if $(\eps, \delta; \lambda,\nu) \in \swap{\Xi}_a$}, \\[3pt]
\C \varphi_+^{(1-\lambda_1, 2-\lambda_1-\lambda_2)} & \emph{if $(\eps, \delta; \lambda,\nu) \in \Xi_b$}, \\[3pt]
\C \varphi_-^{(2-\lambda_1-\lambda_2,1-\lambda_2)} & \emph{if $(\eps, \delta; \lambda,\nu) \in \swap{\Xi}_b$}, \\[3pt]
\C \varphi_c^{(\lambda_1-\lambda_2; 2-\lambda_1-\lambda_2)} & \emph{if $(\eps, \delta; \lambda,\nu) \in \Xi_c$}, \\[3pt]
\{0\} & \emph{otherwise}.
\end{cases}
\end{equation*}
\end{thm}

