\subsection{Classification in terms of infinitesimal characters}
\label{sec:InfChar}

For later convenience we also give the classification of $(\fg, B)$-homomorphisms
$\varphi$ in terms of infinitesimal characters of Verma modules.

Let $\varpi_1$ and $\varpi_2$ be the first and second fundamental weights,
respectively, so that $\varpi_i(H_j) = \delta_{i,j}$ for $H_j$ in \eqref{eqn:H}.
Then the differential
$d\chi_A^{(\mu_1,\mu_2)}$ of the character 
$\chi_A^{(\mu_1,\mu_2)}$ defined in \eqref{eqn:chi} is given by
\begin{equation}\label{eqn:dchi}
d\chi_A^{(\mu_1,\mu_2)} = \mu_1\varpi_1+\mu_2\varpi_2.
\end{equation}
Therefore the Verma module $M(\mu_1,\mu_2)$ defined in 
\eqref{eqn:Verma}
can be be understood as
\begin{equation*}
M(\mu_1,\mu_2)
=\Cal{U}(\fg)\otimes_{\Cal{U}(\fb)} \C_{\mu_1\varpi_1+\mu_2\varpi_2}.
\end{equation*}

Now, for $\mu \in \fa^*$, we denote by
\begin{equation*}
N(\mu):=\Cal{U}(\fg)\otimes_{\Cal{U}(\fb)} \C_{\mu-\rho},
\end{equation*}
the Verma module with infinitesimal character $\chi_\mu$.
As $\rho=\varpi_1 + \varpi_2$, 
for $\mu=(\mu_1,\mu_2)$, we have
\begin{equation*}
M(\mu_1,\mu_2) = N(\mu_1+1,\mu_2+1).
\end{equation*}

We wish to state Theorem \ref{thm:Hom2} in terms of $N(\mu)$.
To do so,
it is convenient to identify $\fa^*$ with
$\fa^*=\{(v_1, v_2 , v_3) \in \C^3: v_1+v_2+v_3=0\}$. 
In the realization we have
\begin{equation*}
\varpi_1=\tfrac{1}{3}(2,-1,-1)
\quad
\text{and}
\quad
\varpi_2=\tfrac{1}{3}(1,1,-2);
\end{equation*}
in particular, $\rho = \varpi_1+\varpi_2 = (1,0,-1)$.

In this notation, the weight $\mu_1\varpi_1+\mu_2\varpi_2+\rho$ is given by
\begin{equation*}
\mu_1\varpi_1+\mu_2\varpi_2+\rho
=
\tfrac{1}{3}(2\mu_1+\mu_2+3, -\mu_1+\mu_2, -\mu_1-2\mu_2-3).
\end{equation*}
Then we put
\begin{align}
\mu_\lambda
&:=-(\lambda_1\varpi_1+\lambda_2\varpi_2)+\rho \nonumber\\[3pt]
&=\tfrac{1}{3}(-(2\lambda_1+\lambda_2-3), \lambda_1-\lambda_2, \lambda_1+2\lambda_2-3) \label{eqn:muL},
\end{align}
which gives
\begin{align*}
M(-\lambda_1, -\lambda_2)^{(\eps_1,\eps_2)}
&=
N(-\lambda_1+1,-\lambda_2+1)^{(\eps_1,\eps_2)}\\
&\equiv
N(\mu_\lambda)^{(\eps_1,\eps_2)},
\end{align*}
where the identification $\fa^* \subset \C^3$ is applied from the first 
line to the second.

For Theorem \ref{thm:Hom3} below, we put
\begin{equation*}
\ga:=\gamma_1-\gamma_2=(1,-1,0),\quad
\beta:=\gamma_2-\gamma_3=(0,1,-1), \quad
\gamma:=\gamma_1-\gamma_3=(1,0,-1).
\end{equation*}
For $\eta \in \gD$, we denote by $s_\eta$ the root reflection with respect to $\eta$.

In the following,
we only consider the case $(\eps_1,\eps_2) = (+, +)$;
the other cases can be obtained easily by
the conditions for $(\delta_1,\delta_2)$ in \eqref{eqn:L1}--\eqref{eqn:L4}.

\begin{thm}\label{thm:Hom3}
For $(\eps_1, \eps_2) = (+, +)$,  the $(\fg, B)$-homomorphisms $\varphi$
are classified as follows.
\begin{alignat*}{4}
&\varphi_1^{(1-\lambda_1)} 
&&\colon 
N(s_{\ga}\mu_\lambda)^{(+,\, (-)^{1-\lambda_1})}
&&\To 
N(\mu_\lambda)^{(+,+)}
\quad  
&&\emph{for $(\lambda_1,\lambda_2) \in \gL_a$}, \\[3pt]
&\varphi_2^{(1-\lambda_2)} 
&&\colon 
N(s_{\gb}\mu_\lambda)^{((-)^{1-\lambda_2},\, +)}
&&\To
N(\mu_\lambda)^{(+,+)} 
\quad  
&&\emph{for $(\lambda_1,\lambda_2) \in \swap{\gL}_a$}, \\[3pt]
&\varphi_+^{(1-\lambda_1,2-\lambda_1-\lambda_2)}
&& \colon 
N(s_{\gb}s_{\ga}\mu_\lambda)^{((-)^{2-\lambda_1-\lambda_2},\, (-1)^{1-\lambda_1})}
&& \To 
N(\mu_\lambda)^{(+,+)}
\quad  
&&\emph{for $(\lambda_1,\lambda_2) \in \gL_b$}, \\[3pt]
&\varphi_-^{(2-\lambda_1-\lambda_2,1-\lambda_2)}
&& \colon 
N(s_{\ga}s_{\gb}\mu_\lambda)^{((-1)^{1-\lambda_2},\, (-)^{2-\lambda_1-\lambda_2})} 
&&\To 
N(\mu_\lambda)^{(+,+)} 
\quad  
&&\emph{for $(\lambda_1,\lambda_2) \in \swap{\gL}_b$}, \\[3pt]
&\varphi_c^{(\lambda_1-\lambda_2;2-\lambda_1-\lambda_2)} 
&& \colon 
N(s_{\gamma}\mu_\lambda)^{((-1)^{2-\lambda_1-\lambda_2},\, (-)^{2-\lambda_1-\lambda_2})}
&&\To 
N(\mu_\lambda)^{(+,+)}
\quad  
&&\emph{for $(\lambda_1,\lambda_2) \in \gL_c$}.
\end{alignat*}
\end{thm}

\begin{proof}
We show only $\varphi_1^{(1-\lambda_1)}$;
the other cases can be handled similarly.
It follows from Theorem \ref{thm:Hom2} that,
for $(\lambda_1, \lambda_2) \in \Lambda_a$, we have 
\begin{equation}\label{eqn:T421}
\varphi_1^{(1-\lambda_1)} \colon
M(-(2-\lambda_1),-(\lambda_1+\lambda_2-1))^{(+,(-)^{1-\lambda_1})}
\To 
M(-\lambda_1,-\lambda_2)^{(+,+)}.
\end{equation}
As in \eqref{eqn:muL}, for $(\nu_1,\nu_2)=(2-\lambda_1,\lambda_1+\lambda_2-1)$,
one computes that
\begin{equation*}
-(\nu_1\varpi_1+\nu_2\varpi_2)+\rho 
=\tfrac{1}{3}(\lambda_1-\lambda_2,
-(2\lambda_1+\lambda_2-3), 
\lambda_1+2\lambda_2-3)
=s_{\ga}\mu_\lambda,
\end{equation*}
which shows
\begin{equation*}
M(-(2-\lambda_1),-(\lambda_1+\lambda_2-1))^{(+,(-)^{1-\lambda_1})}
=N(s_\ga\mu_\lambda)^{(+,(-)^{1-\lambda_1})}.
\end{equation*}
Now the equality
$M(-\lambda_1,-\lambda_2)^{(+,+)}=N(\mu_\lambda)^{(+,+)}$ and
\eqref{eqn:T421} conclude the case for $\varphi_1^{(1-\lambda_1)}$.
\end{proof}

\begin{example}
The diagrams \eqref{eqn:homs1} and \eqref{eqn:homs2} below
illustrate all $\fg$-homomorphisms $\varphi$ in Theorem \ref{thm:Hom3} 
for the case $(\lambda_1, \lambda_2) = (0,0)$.
\begin{equation}\label{eqn:homs1}
\begin{tikzcd}[row sep=1cm, column sep=1cm]
&N(s_{\beta}s_{\ga}\rho) 
\arrow[r, "\varphi_2^{(2)}"]  
\arrow[ddr, pos=0.8,"\varphi_c^{(3; 1)}"]
& N(s_\ga\rho)  
\arrow[dr, "\varphi_1^{(1)}"]&\\
N(s_\gamma \rho) 
\arrow[ur, "\varphi_1^{(1)}"]
\arrow[dr, "\varphi_2^{(1)}"']
\arrow[rrr, pos=0.2, "\varphi_c^{(0;2)}"]
& & & N(\rho)\\
&N(s_\ga s_\gb \rho)  
\arrow[r, "\varphi_1^{(2)}"']  
\arrow[uur, pos=0.85, "\varphi_c^{(-3;1)}"']
&N(s_\gb \rho) 
\arrow[ur, "\varphi_2^{(1)}"']&
\end{tikzcd}
\end{equation}
\begin{equation}\label{eqn:homs2}
\begin{tikzcd}[row sep=1cm, column sep=1cm]
&N(s_{\beta}s_{\ga}\rho) 
\arrow[rrd, "\varphi_+^{(1,2)}"']  
& N(s_\ga\rho)  &\\
N(s_\gamma \rho) 
\arrow[urr, "\varphi_-^{(1,2)}"']
\arrow[drr, "\varphi_+^{(2,1)}"]
& & & N(\rho)\\
&N(s_\ga s_\gb \rho)    
\arrow[urr, "\varphi_-^{(2,1)}"]
&N(s_\gb \rho) &
\end{tikzcd}
\end{equation}

Here we have
$s_\gamma \rho = s_{\ga}s_{\gb}s_{\ga}\rho = s_{\gb}s_{\ga}s_{\gb}\rho = -\rho$.
Further, these homomorphisms admit factorization identities such as
\begin{alignat}{3}
\varphi_c^{(0;2)} 
&= \varphi_1^{(1)} \circ  && \,\, \varphi_2^{(2)} \circ  \varphi_1^{(1)}
&&=  \varphi_2^{(1)} \circ \varphi_1^{(2)} \circ  \varphi_2^{(1)},\label{eqn:ExF1}\\[3pt]
\varphi_c^{(3;1)} \circ \varphi_1^{(1)}
&=&&\varphi_+^{(2,1)}
&&=\varphi_1^{(2)}\circ \varphi_2^{(1)}.\label{eqn:ExF2}
\end{alignat}
In terms of singular vectors,
the identities \eqref{eqn:ExF1} and \eqref{eqn:ExF2} read
\begin{equation*}%\label{eqn:ExF3}
\left(
\sigma_{4}((N_1^-)^2(N_2^-)^2)-\tfrac{1}{2}(N_3^-)^2
\right)
\otimes \mathbb{1}_0
=(N_1^-)(N_2^-)^2(N_1^-)\otimes \mathbb{1}_0
=(N_2^-)(N_1^-)^2(N_2^-)\otimes \mathbb{1}_0
\end{equation*}
and
\begin{equation}\label{eqn:ExF4}
\begin{aligned}
\left(
(N_1^-)\sigma_2((N_1^-)(N_2^-))+\tfrac{3}{2}(N_3^-)
\right)\otimes \mathbb{1}_{s_\beta \rho-\rho}
&=
\left(
\sigma_3((N_1^-)^2(N_2^-))+\sigma_2((N_1^-)(N_3^-))
\right)
\otimes \mathbb{1}_{s_\beta \rho-\rho}\\[3pt]
&=
(N_2^-)(N_1^-)^2\otimes \mathbb{1}_{s_\beta \rho-\rho},
\end{aligned}
\end{equation}
respectively.
Remark that we have
$(\varphi_1^{(2)}\circ \varphi_2^{(1)})(1\otimes \mathbb{1}_{s_\gamma\rho-\rho})=(N_2^-)(N_1^-)^2\otimes \mathbb{1}_{s_\beta \rho-\rho}$, not 
$(N_1^-)^2(N_2^-)\otimes \mathbb{1}_{s_\beta \rho-\rho}$
(see Lemma \ref{lem:hom-comp}).
We shall discuss the factorization identities 
in detail in Section \ref{sec:factorization}.
\end{example}

\begin{rem}
Via the algebraic Fourier transform $F_c$,
the symmetrized form of a singular vector can be found
from the non-symmetrized one.
Indeed, for instance,
it follows from a direct computation that
$\hdL(N_2^-)\hdL(N_1^-)^2\acts 1 = \zeta_1^2\zeta_2+\zeta_1\zeta_3$.
Then we have 
\begin{align*}
(N_2^-)(N_1^-)^2\otimes \mathbb{1}_{s_\beta\rho-\rho}
&=(F_c^{-1}\circ F_c)((N_2^-)(N_1^-)^2\otimes \mathbb{1}_{s_\beta\rho-\rho})\\[3pt]
&=F_c^{-1}\big((\hdL(N_2^-)\hdL(N_1^-)^2\acts 1)
\otimes \mathbb{1}_{s_\beta\rho-\rho}\big)\\[3pt]
&=F_c^{-1}\big((\zeta_1^2\zeta_2+\zeta_1\zeta_3)\otimes \mathbb{1}_{s_\beta\rho-\rho})\\[3pt]
&=\big(\sigma_3((N_1^-)^2(N_2^-))+\sigma_2((N_1^-)(N_3^-))\big)
\otimes \mathbb{1}_{s_\beta\rho-\rho}.
\end{align*}
\end{rem}

\begin{example}\label{example:symb3}
It follows from \eqref{eqn:ExF4} that the truncated symbol 
$\symb_0(\D_2\D_1^2)$ of $\D_2\D_1^2$ is 
\begin{equation}\label{eqn:symbEx}
\symb_0(\D_2\D_1^2) 
= \symb_0(\sigma_3(\D_1^2\D_2)+\sigma_2(\D_1\D_3))
=\zeta_1^2\zeta_2+\zeta_1\zeta_3. 
\end{equation}
The equality \eqref{eqn:symbEx} can be obtained 
directly from the definition of $\symb_0$.
Indeed, a direct computation shows that the differential operator
$\D_2\D_1^2$ is given in the local coordinates \eqref{eqn:n-} as 
\begin{align*}
\D_2\D_1^2
=\frac{\partial^3}{\partial x_1^2 \partial x_2}
+\frac{\partial^2}{\partial x_ 1\partial x_3}
&+\frac{1}{2}x_2\frac{\partial^3}{\partial x_3^3}
+x_2\frac{\partial^3}{\partial x_1\partial x_2 \partial x_3}\\[3pt]
&+\frac{1}{4}x_2^2\frac{\partial^3}{\partial x_2 \partial x_3^2}
-\frac{1}{2}x_1\frac{\partial^3}{\partial x_1^2 \partial x_3}
-\frac{1}{2}x_1x_2\frac{\partial^3}{\partial x_1 \partial x_3^2}
-\frac{1}{8}x_1x_2^2\frac{\partial^3}{\partial x_3^3}.
\end{align*}
Thus the truncated operator $(\D_2\D_1^2)_0$ is
%\begin{equation*}
$(\D_2\D_1^2)_0 =\frac{\partial^3}{\partial x_1^2 \partial x_2}
+\frac{\partial^2}{\partial x_ 1\partial x_3}$.
%\end{equation*}
Therefore, the truncated symbol $\symb_0(\D_2\D_1^2)$ is given by
\begin{equation*}
\symb_0(\D_2\D_1^2)=\symb((\D_2\D_1^2)_0)=\zeta_1^2\zeta_2+\zeta_1\zeta_3,
\end{equation*}
which agrees with \eqref{eqn:symbEx}.
\end{example}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Proof of the classification and construction of $\D$ and $\varphi$: Part I}
\label{sec:proof1}

The aim of the next two sections is to prove 
Theorems 
\ref{thm:DIO1},
\ref{thm:Hom1}, 
\ref{thm:DIO2},
and
\ref{thm:Hom2}.
Our primary goal is to classify
the space $\Sol(\eps,\delta;\lambda,\nu)$
of solutions  to the F-system:
\begin{align*}
&
\Sol(\eps,\delta;\lambda,\nu)\\
&=
\{ \psi \in 
\Hom_{MA}(\C_{\delta}\boxtimes \C_{-\nu}, 
\Pol(\fn_+)\otimes (\C_\eps\boxtimes \C_{-\lambda})): 
\text{
$\psi$ solves \eqref{eqn:Fsys3} below.}\}.
\end{align*}
\begin{equation}\label{eqn:Fsys3}
\widehat{\dpi_{(\eps, \lambda)^*}}(N_j^+)\psi =0
\quad
\text{for $j=1,2$}.
\end{equation}
Remark that since $N_3^+ = [N_1^+, N_2^+]$, 
it suffices to consider 
$\widehat{\dpi_{(\eps, \lambda)^*}}(N_j^+)\psi=0$ for $j=1,2$ in \eqref{eqn:Fsys3}.

We proceed with the following recipe to compute 
$\Sol(\eps,\delta;\lambda,\nu)$,
where 
Steps 1 and 2 are switched from the one in 
Section \ref{sec:recipe}.

\vskip 0.1in

\begin{enumerate}

\item[Step 1]
Classify and construct
$\psi \in
\Hom_{MA}(\C_{\delta}\boxtimes \C_{-\nu}, 
\Pol(\fn_+)\otimes (\C_\eps\boxtimes \C_{-\lambda}))$.

\vskip 0.1in

\item[Step 2]
Compute $d\pi_{(\eps,\lambda)^*}(N_j^+)$ and 
$\widehat{d\pi_{(\eps,\lambda)^*}}(N_j^+)$
for $j=1,2$.

\vskip 0.1in

\item[Step 3]
Solve the F-system \eqref{eqn:Fsys3}.
\vskip 0.1in

\item[Step 4]
Apply $\symb_0^{-1}$ and $F_c^{-1}$ 
to the solutions $\psi \in \Sol(\eps,\delta;\lambda,\nu)$.

\end{enumerate}

\vskip 0.1in

In this section we focus on Steps 1 and 2. 
Further,
the F-system \eqref{eqn:Fsys3}, a system of PDEs,  
will be reduced to that of ODEs via the so-called T-saturation.
The remaining steps will be 
handled in Section \ref{sec:proof2} by solving the resulting system of ODEs. 

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Step 1: 
Classify and construct
$\psi \in
\Hom_{MA}(\C_{\delta}\boxtimes \C_{-\nu}, 
\Pol(\fn_+)\otimes (\C_\eps\boxtimes \C_{-\lambda}))$}
For $X, Y \in \fg$, let $\Tr(X,Y)=\text{Trace}(XY)$ denote the trace form of $\fg$. 
Then $N_i^+$ and $N_j^-$ satisfy $\Tr(N_i^+,N_j^-)=\delta_{i,j}$.
We identify  the dual $\fn_+^\vee$
with $\fn_+^\vee \simeq \fn_-$ via the trace form $\Tr(\cdot, \cdot)$,
which gives rise to an $MA$-isomorphism
$\Pol(\fn_+)=S(\fn_+^\vee) \simeq S(\fn_-)$.
In particular, we have
$\zeta_j(\cdot)=\Tr(\cdot, N_j^-)$
for $\Pol(\fn_+)=\C[\zeta_1, \zeta_2, \zeta_3]$.

As $N_j^-$ are root vectors, the spaces 
$\C\zeta_j^n\simeq \C(N_j^-)^n$
are $MA$-representations for any $n \in \Z_{\geq 0}$.
Observe that, given character $(\eps_1,\eps_2)$ of $M$, we have
$(\eps_1, \eps_2)^n=(\eps_1^n, \eps_2^n)$.

\begin{lem}\label{lem:zetaChar}
Let $n \in \Z_{\geq 0}$.
Then, as $MA$-representations, we have
\begin{equation}\label{eqn:zetaChar1}
\C \zeta_1^n\simeq \C_{(+,(-)^n)} \boxtimes \C_{(-2n,n)},
\quad
\C \zeta_2^n\simeq \C_{((-)^n,+)} \boxtimes \C_{(n,-2n)},
\quad
\C \zeta_3^n\simeq \C_{((-)^n,(-)^n)} \boxtimes \C_{(-n,-n)}.
\end{equation}
In particular, for $k, \ell \in \Z_{\geq 0}$ and $j \in \{0, 1,2,\ldots, \min(k,\ell)\}$,
we have 
\begin{equation}\label{eqn:zetaChar2}
\C\zeta_1^{k-j}\zeta_2^{\ell-j}\zeta_3^j \simeq 
\C_{((-)^\ell,(-)^k)}\boxtimes \C_{(\ell-2k, k-2\ell)}.
\end{equation}
\end{lem}

\begin{proof}
The isomorphisms in \eqref{eqn:zetaChar1}
can be checked directly via the action $\Ad_{\#}$ in \eqref{eqn:sharp}.
Or,  as $\zeta_j(\cdot)=\Tr(\cdot, N_j^-)$, they can also be shown by computing
the characters on $\C (N_j^-)^n$. 
The second identity \eqref{eqn:zetaChar2} is an immediate consequence 
of \eqref{eqn:zetaChar1}. 
\end{proof}

For $k,\ell \in \Z_{\geq 0}$, we put
\begin{equation*}%\label{eqn:Pol1}
\Pol(k,\ell):=\spn_{\C}\{\zeta_1^{k-j}\zeta_2^{\ell-j}\zeta_3^j:
j=0,1,\ldots, \min(k,\ell)\}.
\end{equation*}
By Lemma \ref{lem:zetaChar}, we have
\begin{equation*}
\Pol(k,\ell) \simeq  
\bigoplus_{j=0}^{\min(k,\ell)}
\C_{((-)^\ell,(-)^k)}\boxtimes \C_{(\ell-2k, k-2\ell)}.
\end{equation*}

\begin{prop}\label{prop:MA}
The following conditions on 
$(\eps, \delta; \lambda,\nu) \in (\Z/2\Z)^4 \times \C^4$ are equivalent.
\begin{enumerate}
\item[\emph{(i)}] 
$\Hom_{MA}(\C_{\delta}\boxtimes \C_{-\nu}, 
\Pol(\fn_+)\otimes (\C_\eps\boxtimes \C_{-\lambda}))\neq \{0\}$.
\item[\emph{(ii)}] There exist $k, \ell \in \Z_{\geq 0}$ such that
\begin{equation}\label{eqn:MAcond}
(\eps_1\delta_1, \eps_2\delta_2)=((-)^\ell, (-)^k)
\quad
\text{and}
\quad
(\nu_1-\lambda_1,\nu_2-\lambda_2)
= (2k-\ell,2\ell-k).
\end{equation}
\end{enumerate}
\end{prop}

\begin{proof}
Observe that we have
\begin{equation*}
\Pol(\fn_+)=\bigoplus_{k,\ell \in \Z_{\geq 0}} \Pol(k,\ell).
\end{equation*}
Thus, the $MA$-representation $\Pol(\fn_+)$ can be decomposed as
\begin{equation}\label{eqn:PolDecomp}
\Pol(\fn_+)\simeq \bigoplus_{k,\ell \in \Z_{\geq 0}} 
\bigoplus_{j=0}^{\min(k,\ell)}
\C_{((-)^\ell,(-)^k)}\boxtimes \C_{(\ell-2k, k-2\ell)},
\end{equation}
which yields the proposition.
\end{proof}

\begin{cor}\label{cor:Sol}
If $\Sol(\eps, \delta; \lambda,\nu) \neq \{0\}$, then
$(\eps, \delta;\lambda, \nu)$ satisfies \eqref{eqn:MAcond} 
for some $k,\ell \in \Z_{\geq0}$.
\end{cor}

\begin{proof}
As $\Sol(\eps, \delta; \lambda,\nu) \subset 
\Hom_{MA}(\C_{\delta}\boxtimes \C_{-\nu}, 
\Pol(\fn_+)\otimes (\C_\eps\boxtimes \C_{-\lambda}))$,
this is an immediate consequence of Proposition \ref{prop:MA}.
\end{proof}

Given $k, \ell \in \Z_{\geq 0}$,
for $(\eps,\delta;\lambda,\nu)$ satisfying \eqref{eqn:MAcond}
with $\lambda = (\lambda_1, \lambda_2)$, 
we put
\begin{equation*}
\Sol_{(k,\ell)}(-\lambda_1,-\lambda_2):=
\{ \psi \in 
\Hom_{MA}(\C_{\delta}\boxtimes \C_{-\nu}, 
\Pol(k,\ell)\otimes (\C_\eps\boxtimes \C_{-\lambda})): 
\text{$\psi$ solves \eqref{eqn:Fsys3}.}\}.
\end{equation*}
By Proposition \ref{prop:MA} and \eqref{eqn:MAcond}, to determine 
$\Sol(\eps,\delta;\lambda,\nu)$,
it suffices to compute 
$\Sol_{(k,\ell)}(-\lambda_1,-\lambda_2)$ for 
all $k, \ell \in \Z_{\geq 0}$. We shall carry it out in Section \ref{sec:proof2}.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Step 2: Compute 
$d\pi_{(\eps,\lambda)^*}(N_j^+)$ and 
$\widehat{d\pi_{(\eps,\lambda)^*}}(N_j^+)$ for $j=1,2$}

For the rest of this section, we make preparations for computing
$\Sol_{(k,\ell)}(-\lambda_1,-\lambda_2)$.
The first objects to look at are
$d\pi_{(\eps,\lambda)^*}(N_j^+)$ and 
$\widehat{d\pi_{(\eps,\lambda)^*}}(N_j^+)$ for $j=1,2$.
To the end, we first compute $dR(N_j^-)$ for $j=1,2,3$.

\begin{lem}\label{lem:dR}
The differential operators $dR(N_j^-)$ for $j=1,2,3$ are given as follows.
\begin{equation*}
dR(N_1^-) = \frac{\partial}{\partial x_1} + \frac{x_2}{2}\frac{\partial}{\partial x_3},
\quad
dR(N_2^-) = \frac{\partial}{\partial x_2} - \frac{x_1}{2}\frac{\partial}{\partial x_3},
\quad
dR(N_3^-) = \frac{\partial}{\partial x_3}
\end{equation*}
\end{lem}

\begin{proof}
We only demonstrate the identity for $dR(N_1^-)$; the other cases can be shown 
similarly. Via the local coordinates \eqref{eqn:n-}, for 
$f(\bar{n})\in C^\infty(N_-)\simeq C^\infty(\R^3)$,
we have
\begin{align*}
dR(N_1^-)f(\bar{n})
&=\frac{d}{dt}\bigg\vert_{t=0} f\left(\bar{n}\exp(tN_1^-)\right)\\[3pt]
&=\frac{d}{dt}\bigg\vert_{t=0} 
f\left(\exp(x_1 N_1^- + x_2 N_2^- + x_3 N_3^-)
\exp(tN_1^-)\right)\\[3pt]
&=\frac{d}{dt}\bigg\vert_{t=0} 
f\left(\exp((x_1+t)N_1^- + x_2 N_2^- + (x_3 +\tfrac{x_2}{2}t)N_3^-)\right)\\[3pt]
&=\frac{d}{dt}\bigg\vert_{t=0} f(x_1+t, x_2, x_3 +\tfrac{x_2}{2}t).
%&=\left(\frac{\partial}{\partial x_1} + \frac{x_2}{2}\frac{\partial}{\partial x_3}\right)
%f(x_1, x_2 ,x_3),
\end{align*}
Evaluate the derivative at $t=0$ to obtain the desired identity.
\end{proof}

As the character $\eps=(\eps_1,\eps_2)$ 
of $M$ does not contribute to solving the F-system  \eqref{eqn:Fsys3},
in the following, we simply write $\dpi_{\lambda^*}=d\pi_{(\eps,\lambda)^*}$
with
\begin{equation*}
\lambda^* :=2\rho - d\chi_A^{(\lambda_1,\lambda_2)}
=(2-\lambda_1)\varpi_1 + (2-\lambda_2)\varpi_2,
\end{equation*}
where $d\chi_A^{(\lambda_1,\lambda_2)}$ is the differential of the character of
$\chi_A^{(\lambda_1,\lambda_2)}$ given in  \eqref{eqn:dchi}.


\begin{prop}\label{prop:dpi}
We have 
\begin{align*}
\dpil(N_1^+)&=
(2-\lambda_1)x_1+x_1^2\frac{\partial}{\partial x_1} 
-\frac{1}{2}(x_1x_2-2x_3)\frac{\partial}{\partial x_2} 
+\frac{1}{4}(x_1^2x_2+2x_1x_3)\frac{\partial}{\partial x_3},\\[3pt]
\dpil(N_2^+)&=
(2-\lambda_2)x_2-\frac{1}{2}(x_1x_2+2x_3)\frac{\partial}{\partial x_1}
+x_2^2\frac{\partial}{\partial x_2} 
-\frac{1}{4}(x_1x_2^2-2x_2x_3)\frac{\partial}{\partial x_3}.
\end{align*}
\end{prop}

\begin{proof}
We only show the formula for $\dpil(N_1^+)$; 
the other case can be shown analogously.
By \eqref{eqn:dpi3} with $\fl =\fa$, 
one needs to compute
\begin{equation*}
d\pi_{\lambda^*}(N_1^+)f(\bar{n})
=\lambda^*((\Ad(\bar{n}^{-1})N_1^+)_\fa)f(\bar{n})
-\left(dR((\Ad(\cdot^{-1})N_1^+)_{\fn_-})f\right)(\bar{n}).
\end{equation*}

Write $X: =x_1 N_1^- + x_2 N_2^- + x_3 N_3^-$ and set $\bar{n}:=\exp(X)$.
Then it follows from a direct computation that 
$\Ad(\bar{n}^{-1})N_1^-$ is evaluated as
\begin{align*}
\Ad(\bar{n}^{-1})N_1^+
&=\exp(\ad(-X))N_1^+\\[3pt]
&=N_1^+
+x_1H_1
-x_1^2N_1^-
+\tfrac{1}{2}(x_1x_2-2x_3)N_2^-
+\tfrac{1}{2}(x_1^2x_2-2x_1x_3)N_3^-.
\end{align*}
Therefore,
$(\Ad(\bar{n}^{-1})N_1^+)_{\fa}$ and $(\Ad(\bar{n}^{-1})N_1^+)_{\fn_-}$
are given by
\begin{align*}
(\Ad(\bar{n}^{-1})N_1^+)_{\fa}&=x_1 H_1\\
(\Ad(\bar{n}^{-1})N_1^+)_{\fn_-}&=-x_1^2N_1^-
+\tfrac{1}{2}(x_1x_2-2x_3)N_2^-
+\tfrac{1}{2}(x_1^2x_2-2x_1x_3)N_3^-.
\end{align*}
Therefore, $\dpil(N_1^+)$ is given by
\begin{align*}
\dpil(N_1^+)
&=\lambda^*((\Ad(\bar{n}^{-1})N_1^+)_\fa)f(\bar{n})
-\left(dR((\Ad(\cdot^{-1})N_1^+)_{\fn_-})f\right)(\bar{n})\\[3pt]
&=x_1 \lambda^*(H_1)
+x_1^2dR(N_1^-)
+\tfrac{1}{2}(x_1x_2-2x_3)dR(N_2^-)
+\tfrac{1}{2}(x_1^2x_2-2x_1x_3)dR(N_3^-).
\end{align*}
As $\lambda^*(H_1)=2-\lambda_1$,
Lemma \ref{lem:dR} and some simple manipulations conclude the formula.
\end{proof}

The next step is to compute $\hdpil(N_j^+)$ for $j=1,2$.
For later convenience, we instead consider $-\zeta_j\hdpil(N_j^+)$.
Remark that the system of equations $\hdpil(N_j^+)\psi(\zeta)=0$ 
for $\psi(\zeta) \in \Pol(\fn_+)$ is 
equivalent to $-\zeta_j\hdpil(N_j^+)\psi(\zeta)=0$.
For $i=1,2,3$, we write $\vartheta_i := \zeta_i \tfrac{\partial}{\partial \zeta_i}$
for the Euler operator for $\zeta_i$.

\begin{prop}\label{prop:dpih}
We have 
\begin{align*}
-\zeta_1\hdpil(N_1^+)
&=\lambda_1\vartheta_1 + (\vartheta_1^2-\vartheta_1)-\frac{1}{2}\vartheta_1\vartheta_2+
\frac{1}{2}\vartheta_1\vartheta_3+\frac{\zeta_1\zeta_2}{\zeta_3}\vartheta_3
+\frac{1}{4}\frac{\zeta_3}{\zeta_1\zeta_2}(\vartheta_1^2-\vartheta_1)\vartheta_2,\\[3pt]
-\zeta_2\hdpil(N_2^+)
&=\lambda_2\vartheta_2+(\vartheta_2^2-\vartheta_2)-\frac{1}{2}\vartheta_1\vartheta_2
+\frac{1}{2}\vartheta_2\vartheta_3-\frac{\zeta_1\zeta_2}{\zeta_3}\vartheta_3
-\frac{1}{4}\frac{\zeta_3}{\zeta_1\zeta_2}\vartheta_1(\vartheta_2^2-\vartheta_2).
\end{align*}
\end{prop}

\begin{proof}
Direct applications of 
the algebraic Fourier transform
\eqref{eqn:Weyl2} to $\dpil(N_j^+)$ in Proposition \ref{prop:dpi}.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsubsection{T-saturation}
\label{sec:T}

Now we reduce the system of PDEs  $-\zeta_j\hdpil(N_j^+)\psi(\zeta)=0$
to that of ODEs. To do so, identify $\Pol(k,\ell)$ with the space
$\Pol_{\min(k,\ell)}[t]$ of polynomials $p(t)$ of one variable $t$ with
$\deg p(t) \leq \min(k,\ell)$ via the linear map
\begin{equation*}
T_{k,\ell} \colon 
\Pol_{\min(k,\ell)}[t] \stackrel{\sim}{\To}\Pol(k,\ell),
\quad
p(t) \longmapsto 
\zeta_1^k\zeta_2^\ell p(\tfrac{\zeta_3}{\zeta_1\zeta_2}).
\end{equation*}
Given $D \colon \Pol(k,\ell) \to \Pol(k,\ell)$, 
we define
$T^\sharp_{k,\ell}D \colon \Pol_{\min(k,\ell)}[t] \to \Pol_{\min(k,\ell)}[t]$ by
\begin{equation*}
T_{k, \ell} \circ T^\sharp_{k,\ell}(D) = D \circ T_{k,\ell},
\end{equation*}
so that the following diagram commutes.
\begin{equation*}
\begin{tikzcd}[row sep=1cm, column sep=1cm]
\Pol_{\min(k,\ell)}[t] 
\arrow[d, "T^\sharp_{k,\ell}(D)"']  
\arrow[r, "T_{k, \ell}", "\sim"']  
%\ar@{}[rd]|{\circlearrowleft}
&\Pol(k,\ell)
\arrow[d, "D"]  \\
\Pol_{\min(k,\ell)}[t] 
\arrow[r, "T_{k, \ell}", "\sim"']  
\arrow[ur,  pos=0.5, phantom, "\circlearrowleft"]
&\Pol(k,\ell)
\end{tikzcd}
\end{equation*}

The linear map $T_{k,\ell} \colon 
\Pol_{\min(k,\ell)}[t] \stackrel{\sim}{\To}\Pol(k,\ell)$
is called the \emph{T-saturation} (\cite[Sect.\ 3.2]{KP2}).
Via the linear isomorphism $T_{k,\ell}$, the equation 
$T^\sharp_{k,\ell}(D)p(t)=0$ is equivalent to 
$DT_{k,\ell}(p)(\zeta)=0$ for a differential operator $D$ on $\Pol(k,\ell)$.
Proposition \ref{prop:dpih} shows that $-\zeta_1\hdpil(N_j^+)$ for $j=1,2$
preserve $\Pol(k,\ell)$. We then aim to compute the T-saturated operators
$T^\sharp_{k,\ell}(-\zeta_1\hdpil(N_j^+))$. 

The next lemma collects several useful formulas 
for some basic operators on $\Pol(k,\ell)$.
We write $\vartheta_t:=t\frac{d}{dt}$, the Euler operator for $t$.

\begin{lem}\label{lem:T}
The following hold for any $k, \ell \in \Z_{\geq 0}$.

\begin{enumerate}

\item[\emph{(1)}]
$T^\sharp_{k,\ell}(\vartheta_1)=k-\vartheta_t$

%\vskip 0.1in

\item[\emph{(2)}]
$T^\sharp_{k,\ell}(\vartheta_2)=\ell-\vartheta_t$

%\vskip 0.1in

\item[\emph{(3)}]
$T^\sharp_{k,\ell}(\vartheta_3)=\vartheta_t$

%\vskip 0.1in

\item[\emph{(4)}]
$T^\sharp_{k,\ell}(\frac{\zeta_3}{\zeta_1\zeta_2})=t$

%\vskip 0.1in

\item[\emph{(5)}]
$T^\sharp_{k,\ell}(\frac{\zeta_1\zeta_2}{\zeta_3})=t^{-1}$

%\vskip 0.1in

\end{enumerate}
\end{lem}

\begin{proof}
We only prove (1) and (4); other formulas can be shown in a similar way.

For (1), it suffices to show
$T_{k,\ell} \circ T^\sharp_{k,\ell}(\vartheta_1)p(t)=T_{k,\ell}(kp(t)-\vartheta_tp(t))$.
Indeed, we have
\begin{align*}
T_{k,\ell} \circ T^\sharp_{k,\ell}(\vartheta_1)p(t)
&=\vartheta_1 \circ T_{k,\ell}(p(t))\\[3pt]
&=\vartheta_1 \left(\zeta_1^k\zeta_2^\ell\,  
p\left(\frac{\zeta_3}{\zeta_1\zeta_2}\right)\right)\\[3pt]
&=\zeta_1^k\zeta_2^\ell\left(
kp\left(\frac{\zeta_3}{\zeta_1\zeta_2}\right) - \frac{\zeta_3}{\zeta_1\zeta_2}
\frac{dp}{dt}\left(\frac{\zeta_3}{\zeta_1\zeta_2}\right)\right)\\[3pt]
&=T_{k,\ell}(kp(t)-\vartheta_tp(t)).
\end{align*}

For (4), we show 
$T_{k,\ell}\circ T^\sharp_{k,\ell}(\frac{\zeta_3}{\zeta_1\zeta_2})p(t)
=T_{k,\ell}(tp(t))$. We have
\begin{align*}
T_{k,\ell}\circ T^\sharp_{k,\ell}\left(\frac{\zeta_3}{\zeta_1\zeta_2}\right)p(t)
&=\frac{\zeta_3}{\zeta_1\zeta_2}T_{k,\ell}(p(t))\\[3pt]
&=\frac{\zeta_3}{\zeta_1\zeta_2} \cdot \zeta_1^k\zeta_2^\ell\,
p\left(\frac{\zeta_3}{\zeta_1\zeta_2}\right)\\[3pt]
&=T_{k,\ell}(tp(t)).
\end{align*}
\end{proof}

\begin{prop}\label{prop:tdpih}
We have 
\begin{align}
T^\sharp_{k,\ell}(-\zeta_1\hdpil(N_1^+))
&=
\frac{d}{dt} + (\lambda_1+k-\tfrac{1}{2}\ell-1)(k-\vartheta_t)
+\frac{1}{4}t(k-1-\vartheta_t)(k-\vartheta_t)(\ell-\vartheta_t), \label{prop:thdpi1}\\[3pt]
T^\sharp_{k,\ell}(-\zeta_2\hdpil(N_2^+))
&=
-\frac{d}{dt}+(\lambda_2-\tfrac{1}{2}k+\ell-1)(\ell-\vartheta_t)
-\frac{1}{4}t(k-\vartheta_t)(\ell-1-\vartheta_t)(\ell-\vartheta_t).\label{prop:thdpi2}
\end{align}
\end{prop}

\begin{proof}
Observe that, for differential operators $D_1, D_2$ on $\Pol(k,\ell)$,
we have $T^\sharp_{k,\ell}(D_1 \cdot D_2) 
= T^\sharp_{k,\ell}(D_1)\cdot T^\sharp_{k,\ell}(D_2)$.
The proposed formulas are then obtained by 
straightforward computations with the aid of Lemma \ref{lem:T}.
\end{proof}

For $a, b, \mu \in \C$, we write
\begin{equation*}
D^{(a,b)}(\mu;t):=
\frac{d}{dt}+(\mu+a-\tfrac{1}{2}b-1)(a-\vartheta_t)
+\frac{1}{4}t(a-1-\vartheta_t)(a-\vartheta_t)(b-\vartheta_t).
\end{equation*}
It follows from \eqref{prop:thdpi1} and \eqref{prop:thdpi2} that 
\begin{equation*}
D^{(k,\ell)}(\lambda_1;t)=
T^\sharp_{k,\ell}(-\zeta_1\hdpil(N_1^+))
\quad
\text{and}
\quad
D^{(\ell,k)}(\lambda_2;-t)=
T^\sharp_{k,\ell}(-\zeta_2\hdpil(N_2^+)).
\end{equation*}

For $\lambda_j \in \C$ for $j=1,2$ and $k,\ell \in \Z_{\geq 0}$, we put 
\begin{equation*}
\wSol_{(k,\ell)}(-\lambda_1,-\lambda_2)
:=\{p(t) \in \Pol_{\min(k,\ell)}[t] :
D^{(k,\ell)}(\lambda_1;t)p(t)=D^{(\ell,k)}(\lambda_2;-t)p(t)=0\}.
\end{equation*}
Then the T-saturation
$T_{k,\ell} \colon 
\Pol_{\min(k,\ell)}[t] \stackrel{\sim}{\To}\Pol(k,\ell)$
induces a linear isomorphism
\begin{equation}\label{eqn:SolSol}
\wSol_{(k,\ell)}(-\lambda_1,-\lambda_2) 
\stackrel{\sim}{\To}
\Sol_{(k,\ell)}(-\lambda_1,-\lambda_2).
\end{equation}
Thus, to solve the F-system \eqref{eqn:Fsys3},
it suffices to consider 
\begin{equation}\label{eqn:Deq}
D^{(k,\ell)}(\lambda_1;t)p(t)=0
\quad
\text{and}
\quad
D^{(\ell,k)}(\lambda_2;-t)p(t)=0
\end{equation}
for each $k,\ell \in \Z_{\geq 0}$.
The next proposition reduces the range of $k,\ell$ to consider.

\begin{prop}\label{prop:duality}
There exists a linear isomorphism
\begin{equation*}
\wSol_{(k,\ell)}(-\lambda_1,-\lambda_2)
\stackrel{\sim}{\To}
\wSol_{(\ell, k)}(-\lambda_2,-\lambda_1),
\quad
p(t) \longmapsto p(-t).
\end{equation*}
\end{prop}

\begin{proof}
By definition,  polynomials 
$p(t) \in \wSol_{(k,\ell)}(-\lambda_1,-\lambda_2)$ satisfy
\begin{equation*}
D^{(k,\ell)}(\lambda_1;t)p(t)=D^{(\ell,k)}(\lambda_2;-t)p(t)=0.
\end{equation*}
Thus, for $s :=-t$, we have
\begin{align*}
D^{(\ell,k)}(\lambda_2;t)p(-t)&=
D^{(\ell,k)}(\lambda_2;-s)p(s)=0,\\[3pt]
D^{(k,\ell)}(\lambda_1;-t)p(-t)&=
D^{(k,\ell)}(\lambda_1;s)p(s)=0,
\end{align*}
which show $p(-t) \in \wSol_{(\ell,k)}(-\lambda_2,-\lambda_1)$.
\end{proof}

In the next section, we explicitly compute 
$\wSol_{(k,\ell)}(-\lambda_1,-\lambda_2)$.

