We consider the following five cases separately.

\begin{enumerate}

\item $(k,\ell) = (0,0)$: the origin (\textbullet)
\vskip 0.1in

\item $(k, \ell) \in (1+\Z_{\geq 0}) \times \{0\}$: the $k$-axis $\setminus \{(0,0)\}$
($\blacktriangle$)
\vskip 0.1in

\item $(k, \ell) \in \{0\}  \times  (1+\Z_{\geq 0})$: the $\ell$-axis $\setminus \{(0,0)\}$
($\blacksquare$)
\vskip 0.1in

\item $(k,\ell) \in (1+\Z_{\geq 0})^2$ with $k \neq \ell$:
any lattice neither on the $k$-axis, $\ell$-axis, nor diagonal line
($\circ$)
\vskip 0.1in

\item $(k,\ell) \in (1+\Z_{\geq 0})^2$ with $k=\ell$:
the diagonal line $\setminus \{(0,0)\}$
($\blacklozenge$)
\vskip 0.1in

\end{enumerate}

We write
\begin{align}
p_+^{(k,\ell)}(t) &:= \sum_{m=0}^{\min(k,\ell)} \frac{1}{2^m}m!\binom{k}{m}\binom{\ell}{m}
t^m, \label{eqn:p+0}\\[3pt]
p_-^{(k,\ell)}(t) &:= \sum_{m=0}^{\min(k,\ell)} \frac{(-1)^m}{2^m}m!\binom{k}{m}\binom{\ell}{m}
t^m, \label{eqn:p-0}\\[3pt]
p_{c}^{(s;k)}(t)&:= \sum_{m=0}^{k} \frac{1}{2^m}\binom{k}{m}\Cay_m(s;k)t^m.\label{eqn:pc0}
\end{align}

In the following.
we deal with Case (1) in Proposition \ref{prop:1},
Cases (2) and (3) in Proposition \ref{prop:2},
Case (4) in Proposition \ref{prop:3},
and Case (5) in Proposition \ref{prop:4},
in order.

\begin{prop}\label{prop:1}
Let $(k,\ell) = (0,0)$. Then we have
\begin{equation*}
\wSol_{(0, 0)}(-\lambda_1, -\lambda_2) = \C
\quad 
\text{for all $\lambda_1 ,\lambda_2 \in \C$}.
\end{equation*}
\end{prop}

\begin{proof}
As $\Pol_{\min(0,0)}[t] = \C$, the set  
$\wSol_{(0,0)}(-\lambda_1,-\lambda_2)$
is given by
\begin{equation*}
\wSol_{(0,0)}(-\lambda_1,-\lambda_2)
=\{a \in \C : 
D^{(0,0)}(\lambda_1;t)a=
D^{(0,0)}(\lambda_2;-t)a=0\}.
\end{equation*}
Since
\begin{align*}
D^{(0,0)}(\lambda_1;t)&=
\frac{d}{dt} - (\lambda_1-1)\vartheta_t - \frac{1}{4}t(\vartheta_t+1)\vartheta_t^2,\\[3pt]
D^{(0,0)}(\lambda_2;-t)&=
-\frac{d}{dt} - (\lambda_2-1)\vartheta_t + \frac{1}{4}t(\vartheta_t+1)\vartheta_t^2,
\end{align*}
it is clear that
\begin{equation*}
D^{(0,0)}(\lambda_1;t)a=
D^{(0,0)}(\lambda_2;-t)a=0
\quad
\text{for all $\lambda_1, \lambda_2 \in \C$.}
\end{equation*}
\end{proof}

\begin{prop}\label{prop:2}
The following hold.
\begin{enumerate}
\item[\emph{(a)}]
Let $(k,\ell) \in (1+\Z_{\geq 0}) \times \{0\}$. Then the following conditions on
$(\lambda_1,\lambda_2) \in \C^2$ are equivalent.
\begin{enumerate}
\item[\emph{(i)}]
$\wSol_{(k,0)}(-\lambda_1,-\lambda_2) \neq \{0\}$.
\item[\emph{(ii)}]
$(\lambda_1,\lambda_2) \in \{1-k\} \times \C $.
\end{enumerate}
\vskip 0.1in

\item[\emph{(b)}]
Let $(k,\ell) \in \{0\} \times (1+\Z_{\geq 0})$. Then the following conditions on
$(\lambda_1,\lambda_2) \in \C^2$ are equivalent.
\begin{enumerate}
\item[\emph{(i)}]
$\wSol_{(0,\ell)}(-\lambda_1,-\lambda_2) \neq \{0\}$.

\item[\emph{(ii)}]
$(\lambda_1,\lambda_2) \in \C \times \{1-\ell\}$.

\end{enumerate}
\end{enumerate}
Moreover, we have
\begin{align*}
\wSol_{(k,0)}( -(1-k), -\lambda_2) &= \C,\\[3pt]
\wSol_{(0,\ell)}(-\lambda_1, -(1-\ell)) &= \C.
\end{align*}
\end{prop}

\begin{proof}
Case (b) simply follows from Proposition \ref{prop:duality} and Case (a).
Thus, it suffices to consider $(k,\ell) \in (1+\Z_{\geq 0}) \times  \{0\}$.
As $\Pol_{\min(k,0)}[t] = \C$, 
the set 
$\wSol_{(k,0)}(-\lambda_1,-\lambda_2)$
is given by
\begin{equation*}
\wSol_{(k,0)}(-\lambda_1,-\lambda_2)
=\{a \in \C : 
D^{(k,0)}(\lambda_1;t)a=
D^{(0,k)}(\lambda_2;-t)a=0\},
\end{equation*}
where
\begin{align*}
D^{(k,0)}(\lambda_1;t)&=
\tfrac{d}{dt} + (\lambda_1+k-1)(k-\vartheta_t) 
- \tfrac{1}{4}t(k-1-\vartheta_t)(k-\vartheta_t)\vartheta_t,\\[3pt]
D^{(0,k)}(\lambda_2;-t)&=
-\tfrac{d}{dt} - (\lambda_2-\tfrac{1}{2}k-1)\vartheta_t 
- \tfrac{1}{4}t(\vartheta_t+1)(k-\vartheta_t)\vartheta_t.
\end{align*}
Therefore, 
$D^{(k,0)}(\lambda_1;t)a=D^{(0,k)}(\lambda_2;-t)a=0$
if and only if $k(\lambda_1+k-1)=0$, which is equivalent to 
$(\lambda_1, \lambda_2) \in \{1-k\} \times \C$ as $k \neq 0$.
\end{proof}

\begin{prop}\label{prop:3}
Let $k, \ell \in 1+\Z_{\geq 0}$ with $ k\neq \ell$. Then the following 
two conditions on $(\lambda_1,\lambda_2) \in \C^2$  are equivalent.
\begin{enumerate}
\item[\emph{(i)}] 
$\wSol_{(k,\ell)}(-\lambda_1,-\lambda_2) \neq \{0\}$.

\item[\emph{(ii)}] 
$(\lambda_1,\lambda_2) \in \{(1-k, 1-\ell+k), (1-k+\ell ,1-\ell )\}$.
\end{enumerate}
Moreover, we have 
\begin{align*}
\wSol_{(k,\ell)}(-(1-k), -(1-\ell+k)) &= \C  p_+^{(k,\ell)}(t),\\[3pt]
\wSol_{(k,\ell)}(-(1-k+\ell), -(1-\ell)) &= \C  p_-^{(k,\ell)}(t).
\end{align*}
\end{prop}

\begin{proof}
It follows from Proposition \ref{prop:duality} that it suffices to consider $k > \ell$.
As $\Pol_{\min(k,\ell)}[t] = \Pol_\ell[t]$, 
the set 
$\wSol_{(k,\ell)}(-\lambda_1,-\lambda_2)$
is given by
\begin{equation*}
\wSol_{(k,\ell)}(-\lambda_1,-\lambda_2)
=\{p(t) \in  \Pol_\ell[t] : 
D^{(k,\ell)}(\lambda_1;t)p(t)=
D^{(\ell,k)}(\lambda_2;-t)p(t)=0\}.
\end{equation*}

Take $p(t)=  \sum_{j=0}^\ell a_jt^j\in \Pol_\ell[t]$.
For simplicity, we put
\begin{align*}
\gamma_\lambda(k,\ell)&:=\lambda_1+k-\tfrac{1}{2}\ell-1,\\[3pt]
\delta_\lambda(k,\ell)&:=\lambda_2-\tfrac{1}{2}k+\ell-1,
\end{align*}
so that 
\begin{align*}
D^{(k,\ell)}(\lambda_1;t)
&=
\tfrac{d}{dt} + \gamma_\lambda(k,\ell)(k-\vartheta_t)
+\tfrac{1}{4}t(k-1-\vartheta_t)(k-\vartheta_t)(\ell-\vartheta_t), \\[3pt]
D^{(\ell,k)}(\lambda_2;-t)
&=
-\tfrac{d}{dt}+\delta_\lambda(k,\ell)(\ell-\vartheta_t)
-\tfrac{1}{4}t(\ell-1-\vartheta_t)(k-\vartheta_t)(\ell-\vartheta_t).
\end{align*}

A direct computation reduces
the equation $D^{(k,\ell)}(\lambda_1;t)p(t)=0$ to the condition
$A_m=0$ for $m=0,1,\ldots, \ell$, where 
\begin{align*}
A_0&=\gamma_\lambda(k,\ell)ka_0+a_1,\\[3pt]
A_1&=\tfrac{1}{4}(k-1)k\ell a_0 + \gamma_\lambda(k,\ell)(k-1)a_1+2a_2,\\[3pt]
A_m&=\tfrac{1}{4}(k-m)(k-m+1)(\ell-m+1)a_{m-1}+\gamma_\lambda(k,\ell)(k-m)a_m
+(m+1)a_{m+1} \quad
\text{for $m=2,\ldots, \ell-1$},\\[3pt]
A_\ell&=\tfrac{1}{4}(k-\ell)(k-\ell+1) a_{\ell-1} +\gamma_\lambda(k,\ell)(k-\ell)a_\ell.
\end{align*}
Similarly, the equation $D^{(\ell,k)}(\lambda_2;-t)p(t)=0$ 
is equivalent to the condition
$B_m=0$ for $m=0,1,\ldots, \ell-1$, where 
\begin{align*}
B_0&=\delta_\lambda(k,\ell)k a_0-a_1,\\[3pt]
B_1&=-\tfrac{1}{4}(\ell-1)k\ell a_0 + \delta_\lambda(k,\ell)(\ell-1)a_1-2a_2,\\[3pt]
B_m&=-\tfrac{1}{4}(\ell-m)(k-m+1)(\ell-m+1)a_{m-1}+\delta_\lambda(k,\ell)(\ell-m)a_m
-(m+1)a_{m+1} \quad
\text{for $m=2,\ldots, \ell-1$}.
\end{align*}

If $a_0=0$, then the recurrence relations force $p(t)\equiv 0$. 
Then, without loss of generality, we assume that $a_0=1$.
Since $k,\ell, k-\ell \neq 0$, by the system of linear equations
\begin{align*}
A_0 + B_0 &= 0,\\
A_1 + B_1 &= 0,
\end{align*}
one obtains
\begin{equation*}
\lambda_1 \in \{1-k,1-k+\ell\}
\quad
\text{and}
\quad 
-\ell \delta_\lambda(k,\ell) = k\gamma_\lambda(k,\ell).
\end{equation*}

First, suppose that $\lambda_1=1-k$. In this case, we have
\begin{equation*}
\lambda_2=1-\ell+k,
\quad
\gamma_\lambda(k,\ell)=-\frac{\ell}{2},
\quad
\delta_\lambda(k,\ell)=\frac{k}{2}.
\end{equation*}
Then, by solving the system of equations $A_m=0$ and $B_m=0$, one obtains
\begin{equation*}
a_m=\frac{1}{2^m}m! \binom{k}{m}\binom{\ell}{m}
\quad
\text{for $1\leq m \leq \ell$},
\end{equation*}
which amounts to $p(t)= p_+^{(k,\ell)}(t)$.

Next, observe that if $\lambda_1 = 1-k+\ell$, 
then $\lambda_2=1-\ell$. It thus follows from 
Proposition \ref{prop:duality} and the former case that, in the case, 
we have $p(t)= p_-^{(k,\ell)}(t)$.
This completes the proof.
\end{proof}

\begin{prop}\label{prop:4}
Let $k, \ell \in 1+\Z_{\geq 0}$ with $ k=\ell$. Then the following 
two conditions on $(\lambda_1,\lambda_2) \in \C^2$  are equivalent.
\begin{enumerate}
\item[\emph{(i)}] 
$\wSol_{(k,k)}(-\lambda_1,-\lambda_2) \neq \{0\}$.

\item[\emph{(ii)}] 
$(\lambda_1,\lambda_2) \in 
\{(\tfrac{1}{2}(2-k-s), \tfrac{1}{2}(2-k+s)) : s\in \C\}$.
\end{enumerate}
Moreover, we have 
\begin{equation*}
\wSol_{(k,k)}(-\tfrac{1}{2}(2-k-s), -\tfrac{1}{2}(2-k+s))= \C p_c^{(k,\ell)}(t).
\end{equation*}
\end{prop}

\begin{proof}
In this case we have
\begin{equation*}
\wSol_{(k,k)}(-\lambda_1,-\lambda_2)
=\{p(t) \in  \Pol_k[t] : 
D^{(k,k)}(\lambda_1;t)p(t)=
D^{(k,k)}(\lambda_2;-t)p(t)=0\},
\end{equation*}
where
\begin{align*}
D^{(k,k)}(\lambda_1;t)
&=
\tfrac{d}{dt} + (\lambda_1+\tfrac{1}{2}k-1)(k-\vartheta_t)
+\tfrac{1}{4}t(k-1-\vartheta_t)(k-\vartheta_t)^2, \\[3pt]
D^{(k,k)}(\lambda_2;-t)
&=
-\tfrac{d}{dt}+(\lambda_2+\tfrac{1}{2}k-1)(k-\vartheta_t)
-\tfrac{1}{4}t(k-1-\vartheta_t)(k-\vartheta_t)^2.
\end{align*}

Now we put
\begin{align*}
D^{(k)}_+&:=D^{(k,k)}(\lambda_1;t)+D^{(k,k)}(\lambda_2;-t)
=(\lambda_1+\lambda_2+k-2)(k-\vartheta_t),\\[3pt]
D^{(k)}_-&:=D^{(k,k)}(\lambda_1;t)-D^{(k,k)}(\lambda_2;-t)
=2\tfrac{d}{dt}+(\lambda_1-\lambda_2)(k-\vartheta_t)
+\tfrac{1}{2}t(k-1-\vartheta_t)(k-\vartheta_t)^2.
\end{align*}
It suffices to consider $D^{(k)}_+p(t)=D^{(k)}_-p(t)=0$.

For $p(t)=\sum_{m=0}^k a_m t^m \in \Pol_k[t]$,
the system $D^{(k)}_+p(t)=D^{(k)}_-p(t)=0$ of equations forces
\begin{equation}\label{eqn:cond1}
\lambda_1+\lambda_2+k-2=0
\end{equation}
and
\begin{equation}\label{eqn:cond2}
a_m=\frac{-1}{4m}(k-m+1)
\{(k-m+2)^2a_{m-2} + 2(\lambda_1-\lambda_2)a_{m-1}\}
\end{equation}
for $m=1,\ldots, k$ with $a_{-1}=0$. It follows from \eqref{eqn:cond2} that
if $a_0=0$, then $p(t)\equiv 0$. Then, without loss of generality, we assume that 
$a_0=1$.

Now, we put
\begin{equation*}
\gL_c(k):=
\{(\tfrac{1}{2}(2-k-s), \tfrac{1}{2}(2-k+s)): s\in \C\}.
\end{equation*}
Then \eqref{eqn:cond1} is equivalent to 
$(\lambda_1,\lambda_2) \in \gL_c(k)$.
For $(\lambda_1,\lambda_2) \in \gL_c(k)$, the coefficients
$a_m$ are given by
\begin{equation*}
a_m=\frac{-1}{4m}(k-m+1)
\{(k-m+2)^2a_{m-2} - 2sa_{m-1}\}.
\end{equation*}

\begin{claim}\label{claim:am}
We have 
\begin{equation*}
a_m=\frac{1}{2^m}\binom{k}{m}\Cay_m(s;k),
\end{equation*}
where $\Cay_m(s;k)$ is a Cayley continuant defined 
at the beginning of Section \ref{sec:construction}.
\end{claim}

If Claim \ref{claim:am} holds, then $p(t)=p_c^{(s;k)}(t)$.
It thus suffices to show the claim. Put 
\begin{equation*}
b_m:=\frac{1}{2^m}\binom{k}{m}\Cay_m(s;k).
\end{equation*}
We wish to show $a_m = b_m$ for $m=0,1,2\ldots, k$.
We prove it by induction.

As $\Cay_0(s;k) =1$ and $\Cay_1(s;k)=s$, we have 
$b_0 = 1$ and 
\begin{equation*}
b_1 = \frac{1}{2}\binom{k}{1}\Cay_1(s;k)=\frac{1}{2}ks,
\end{equation*}
while $a_0=1$ by assumption and
\begin{equation*}
a_1 = \frac{-1}{4}(k-1+1)\{(k-1+2)^2a_{-1} - 2sa_0\}=\frac{1}{2}ks.
\end{equation*}
Now assume that $a_m=b_m$ for $m=0, 1, \ldots, j-1$. Then, for $m=j$, we have
\begin{align}
&(k-j+2)^2 a_{j-2}-2sa_{j-1} \nonumber \\[3pt]
&=(k-j+2)^2 \frac{1}{2^{j-2}} \binom{k}{j-2} \Cay_{j-2}(s;k)
-2s\frac{1}{2^{j-1}}\binom{k}{j-1}\Cay_{j-1}(s;k) \nonumber \\[3pt]
&=\frac{-1}{2^{j-2}}\binom{k}{j-1}
\{s\Cay_{j-1}(s;k) - (j-1)(k-j+2)\Cay_{j-2}(s;k)\}.\label{eqn:acay}
\end{align}
It is known that Cayley continuants $\Cay_{j}(s;k)$ satisfy
the recurrence relation
\begin{equation*}
\Cay_j(s;k)=s\Cay_{j-1}(s;k) - (j-1)(k-j+2)\Cay_{j-2}(s;k)
\end{equation*}
(cf.\ \cite[(3)]{MT05}). Therefore it follows from \eqref{eqn:acay} that
\begin{equation*}
(k-j+2)^2 a_{j-2}-2sa_{j-1}
=\frac{-1}{2^{j-2}}\binom{k}{j-1}\Cay_j(s;k).
\end{equation*}
Hence,
\begin{align*}
a_j 
&= \frac{-1}{4j}(k-j+1)\{(k-j+2)^2 a_{j-2}-2sa_{j-1}\}\\[3pt]
&= \frac{-1}{4j}(k-j+1)\cdot \frac{-1}{2^{j-2}}\binom{k}{j-1}\Cay_j(s;k)\\[3pt]
&=\frac{1}{2^{j}}\binom{k}{j}\Cay_j(s;k).
\end{align*}
By induction, the claim holds.
\end{proof}

Recall from \eqref{eqn:SolSol} that 
the T-saturation $T_{k,\ell}$ provides the linear isomorphism
\begin{align*}
\wSol_{(k,\ell)}(-\lambda_1,-\lambda_2) 
&\stackrel{\sim}{\To}
\Sol_{(k,\ell)}(-\lambda_1,-\lambda_2),\\
p(t) &\longmapsto T_{k,\ell}p(t):=
\zeta_1^k\zeta_2^\ell  p(\tfrac{\zeta_3}{\zeta_1\zeta_2}).
\end{align*}
For simplicity, we write
\begin{equation*}
T_{k,\ell}( p_\pm) := T_{k,\ell}\, p_\pm^{(k,\ell)}(t)
\quad
\text{and}
\quad
T_{k}(p_c^{(s)}) := T_{k,k}\, p_c^{(s;k)}(t).
\end{equation*}
Now we classify 
$\Sol(\eps,\delta;\lambda,\nu)$.

\begin{thm}\label{thm:Sol}
The space 
$\Sol(\eps,\delta;\lambda,\nu)$
of polynomial solutions to the F-system \eqref{eqn:Fsys3}
is classified as follows.
\begin{equation*}
\Sol(\eps,\delta;\lambda,\nu)
=
\begin{cases}
\C \id & \emph{if $(\delta;\nu) = (\eps; \lambda)$},\\[3pt]
\C \zeta_1^{1-\lambda_1} & \emph{if $(\eps, \delta; \lambda,\nu) \in \Xi_a$}, \\[3pt]
\C \zeta_
2^{1-\lambda_2} & \emph{if $(\eps, \delta; \lambda,\nu) \in \swap{\Xi}_a$}, \\[3pt]
\C T_{1-\lambda_1, 2-\lambda_1-\lambda_2}(p_+) & \emph{if $(\eps, \delta; \lambda,\nu) \in \Xi_b$}, \\[3pt]
\C T_{2-\lambda_1-\lambda_2, 1-\lambda_2}(p_-) & \emph{if $(\eps, \delta; \lambda,\nu) \in \swap{\Xi}_b$}, \\[3pt]
\C T_{2-\lambda_1-\lambda_2}(p_c^{(\lambda_1-\lambda_2)}) & \emph{if $(\eps, \delta; \lambda,\nu) \in \Xi_c$}, \\[3pt]
\{0\} & \emph{otherwise},
\end{cases}
\end{equation*}
where $\Xi_a,\swap{\Xi}_a, \ldots, \Xi_c$ are the sets defined in Section \ref{sec:DIO}.
\end{thm}

\begin{proof}
It follows from Corollary \ref{cor:Sol} that 
$\Sol(\eps,\delta;\lambda,\nu)\neq \{0\}$ if and only 
if $\Sol_{(k,\ell)}(-\lambda_1,-\lambda_2)\neq \{0\}$ for some
$k,\ell \in \Z_{\geq 0}$, which is further equivalent to
$\wSol_{(k,\ell)}(-\lambda_1,-\lambda_2)\neq \{0\}$.
One then rewrites $k,\ell \in \Z_{\geq 0}$ and $s \in \C$ 
in terms of $\lambda_1, \lambda_2$ 
given in Propositions \ref{prop:1}, \ref{prop:2}, \ref{prop:3}, and \ref{prop:4}
to obtain the proposed parameters in $\Xi_a,\swap{\Xi}_a, \ldots, \Xi_c$.
The generators simply follow from the application of 
the T-saturation $T_{k,\ell}$ to $1$, $p_{\pm}^{(k,\ell)}$, and $p_c^{(s;k)}$.
Now the theorem holds.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Step 4:
Apply $\symb_0^{-1}$ and $F_c^{-1}$ 
to the solution $\psi \in \Sol(\eps,\delta;\lambda,\nu)$}
\label{sec:Step4}

Recall from \eqref{eqn:Finv2} and \eqref{eqn:symb} that, 
given $\psi(\zeta) \in \Sol(\eps,\delta;\lambda,\nu)$ with
\begin{equation*}
\psi(\zeta) 
= \sum_{\mathbf{r} \in \Z_{\geq 0}^3}a_\mathbf{r}  \zeta_1^{r_1}\zeta_2^{r_2}\zeta_3^{r_3},
\end{equation*}
we have 
\begin{align*}
\symb_0^{-1}(\psi(\zeta))
&=\sum_{\mathbf{r} \in \Z_{\geq 0}^3}a_\mathbf{r}  
\sigma_{|\mathbf{r}|}(\D_1^{r_1}\D_2^{r_2}\D_3^{r_3}),\\[3pt]
F_c^{-1}(\psi(\zeta))
&=\sum_{\mathbf{r} \in \Z_{\geq 0}^3}a_\mathbf{r}  
\sigma_{|\mathbf{r}|}((N_1^-)^{r_1}(N_2^-)^{r_2}(N_3^-)^{r_3}),
\end{align*}
where $\D_j = dR(N_j^-)$ for $j=1,2,3$ and
$\sigma_{|\mathbf{r}|}$ is symmetrization on $|\mathbf{r}|$ letters. 

Now we are ready to prove 
Theorems 
\ref{thm:DIO1},
\ref{thm:Hom1}, 
\ref{thm:DIO2},
and
\ref{thm:Hom2}.

\begin{proof}[Proof of Theorems 
\ref{thm:DIO1},
\ref{thm:Hom1}, 
\ref{thm:DIO2},
and
\ref{thm:Hom2}]

It is clear that $\D_j^k=\symb_0^{-1}(\zeta_j^k)$ for $j=1,2$,
$\D_\pm^{(k,\ell)} = \symb_0^{-1}(T_{k,\ell}(p_{\pm}))$, and 
$\D_c^{(s;k)}=\symb_0^{-1}(T_{k}(p_c^{s}))$. Therefore,
Theorems \ref{thm:DIO1} and \ref{thm:DIO2} follow 
from Theorems \ref{thm:symb} and \ref{thm:Sol}.
Likewise, let 
$\eta_{\pm}^{(k,\ell)}(N_1^-,N_2^-,N_3^-)$ and 
$\eta_c^{(s;k)}(N_1^-,N_2^-,N_3^-)$ be the polynomials
defined in \eqref{eqn:eta1}, \eqref{eqn:eta2}, and \eqref{eqn:eta3}.
By Theorem \ref{thm:dL1}, we have
$(N_j^-)^k=F_c^{-1}(\zeta_j^k)$,
$\eta_{\pm}^{(k,\ell)}(N_1^-,N_2^-,N_3^-) =F_c^{-1}(T_{k,\ell}(p_{\pm}))$,
and
$\eta_c^{(s;k)}(N_1^-,N_2^-,N_3^-) = F_c^{-1}(T_{k}(p_c^{s}))$.
Hence, Theorems \ref{thm:Fmethod} and \ref{thm:Sol} yield
the desired theorems. This ends  the proof.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Uniform expressions of $p_{\pm}^{(k,\ell)}(t)$ and $p_c^{(s;k)}(t)$
by Jacobi polynomials $P_m^{(\ga,\beta)}(z)$ at $z=0$}
\label{sec:Uniform}

In this short section we aim to show that
the key polynomials $p_{\pm}^{(k,\ell)}(t)$ and $p_c^{(s;k)}(t)$ obtained in 
Section \ref{sec:proof2} can be uniformly expressed by Jacobi polynomials
$P_m^{(\ga,\beta)}(z)$ for certain parameters $\ga, \beta$ at $z=0$.
This is accomplished in Theorem \ref{thm:unif}.
We also discuss that $p_c(s;k)$ can be 
given also by binary Krawtchouk polynomials $K_m(x;y)$,
which play a role in the factorization identities in Section \ref{sec:factorization}.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Jacobi polynomials $P^{(\ga,\gb)}_m(z)$} 
\label{sec:Jacobi}

First, we briefly recall some basic properties of 
Jacobi polynomials $P^{(\ga,\gb)}_m(z)$.
For $\ga, \gb \in \C$ and $m \in \Z_{\geq 0}$, we write
\begin{equation*}
P^{(\ga,\gb)}_m(z) := \sum_{j=0}^m\binom{m+\ga}{m-j}\binom{m+\beta}{j}
\left(\frac{z-1}{2}\right)^j\left(\frac{z+1}{2}\right)^{m-j}.
\end{equation*}
The polynomials $P^{(\ga,\gb)}_m(z)$ are called \emph{Jacobi polynomials} 
(cf.\ \cite[p.\ 68]{Szego75}).

The Jacobi polynomials $P_m^{(\ga,\beta)}(z)$ satisfy the following 
generating function: %(cf.\ \cite{Carlitz63, Milch68}]\label{fact:Jacobi1}):
\begin{equation}\label{eqn:Jacobi1}
(1+\frac{z+1}{2}w)^\ga(1+\frac{z-1}{2}w)^\beta
=\sum_{m=0}^\infty P_m^{(\ga-m,\beta-m)}(z) w^m.
\end{equation}
In particular, if $z=0$ and $w=2t$, then
\begin{equation}\label{eqn:Jacobi2}
(1+t)^\ga(1-t)^\beta = \sum_{m=0}^\infty 2^m P_m^{(\ga-m,\beta-m)}(0) t^m.
\end{equation}


It follows from the generating function \eqref{eqn:Jacobi1} that
\begin{equation}\label{eqn:Jacobi3}
P^{(\ga,\beta)}_m(-z) = (-1)^mP_m^{(\beta,\ga)}(z).
\end{equation}
In particular,
\begin{equation}\label{eqn:Jacobi4}
P^{(\ga,\beta)}_m(0) = (-1)^mP_m^{(\beta,\ga)}(0).
\end{equation}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Uniform expressions by $P_m^{(\ga,\beta)}(z)$} 

Now we show that the polynomials 
$p_\pm^{(k,\ell)}(t)$ and $p_c^{(s;k)}(t)$ are given in terms of 
Jacobi polynomials $P_m^{(\ga,\beta)}(z)$.

\begin{thm}\label{thm:unif}
Let $k, \ell \in \Z_{\geq 0}$ and $s\in \C$.
Then $p_{\pm}^{(k,\ell)}(t)$ and $p_c^{(s;k)}(t)$ can be expressed as follows:
\begin{align}
p_+^{(k,\ell)}(t)
&=
\begin{cases}
\sum_{m=0}^\ell k^{\underline{m}} \, 
P_m^{(\ell-m,\, -m)}(0)t^m & \text{if $k \geq \ell$},\\[5pt]
\sum_{m=0}^k \ell^{\underline{m}} \, 
P_m^{(k-m,\, -m)}(0)t^m & \text{if $k < \ell$},
\end{cases}\label{eqn:p+J}\\[5pt]
p_-^{(k,\ell)}(t)
&=
\begin{cases}
\sum_{m=0}^\ell k^{\underline{m}}\, P_m^{(-m,\, \ell-m)}(0)t^m 
& \text{if $k \geq \ell$},\\[5pt]
\sum_{m=0}^k \ell^{\underline{m}} \, P_m^{(-m,\, k-m)}(0)t^m 
& \text{if $k < \ell$},
\end{cases}\label{eqn:p-J}\\[3pt]
p_c^{(s;k)}(t)
&=\sum_{m=0}^k k^{\underline{m}}\, 
P_m^{(\frac{k+s-2m}{2}, \, \frac{k-s-2m}{2})}(0)t^m, \label{eqn:pcJ}
\end{align}
where $r^{\underline{m}}:=r(r-1)(r-2)\cdots (r-m+1) = \frac{\Gamma(r+1)}{\Gamma(r-m+1)}$. In particular, we have 
\begin{equation}\label{eqn:pcJpm}
p_c^{(\pm k;k)}(t) = p_{\pm}^{(k,k)}(t).
\end{equation}
\end{thm}


\begin{proof}
The identity \eqref{eqn:pcJpm} readily follows from
\eqref{eqn:p+J}, \eqref{eqn:p-J}, and \eqref{eqn:pcJ}.
Thus, we only focus on showing the latter three identities.

We start with the proof for \eqref{eqn:p+J}. 
Without loss of generality, we assume $k \geq \ell$. Thus,
\begin{equation}\label{eqn:p+}
p_+^{(k,\ell)}(t) 
= \sum_{m=0}^{\ell} \frac{1}{2^m}m!\binom{k}{m}\binom{\ell}{m}t^m
= \sum_{m=0}^{\ell} \frac{k^{\underline{m}}}{2^m}\binom{\ell}{m}t^m.
\end{equation}
Observe that the polynomial $(1+t)^\ell$ is expanded as
\begin{equation}\label{eqn:BinomGen}
(1+t)^\ell = \sum_{m=0}^\ell \binom{\ell}{m}t^m,
\end{equation}
which is the case for $(\ga, \beta) = (\ell, 0)$ in \eqref{eqn:Jacobi2}. Therefore,
\begin{equation}\label{eqn:binom1}
\binom{\ell}{m} = 2^m \cdot P_m^{(\ell-m, -m)}(0).
\end{equation}
Now \eqref{eqn:binom1} and \eqref{eqn:p+} conclude the proposed identity \eqref{eqn:p+J}.
The identity \eqref{eqn:p-J} for $p_-^{(k,\ell)}(t)$ is obtained by applying 
\eqref{eqn:Jacobi4} to \eqref{eqn:p+J}.

To show \eqref{eqn:pcJ}, recall from \eqref{eqn:pc0} that
\begin{equation}\label{eqn:pc}
p_c^{(s;k)}(t)
=\sum_{m=0}^k \frac{1}{2^m}\binom{k}{m}\Cay_m(s;k) t^m
=\sum_{m=0}^k \frac{1}{2^m} \frac{k^{\underline{m}} }{m!}\Cay_m(s;k) t^m.
\end{equation}
It is known that 
the generating function of Cayley continuants $\{\Cay_m(x;y)\}$
is given by 
\begin{equation*}
(1+t)^{(\frac{y+x}{2}, \frac{y-x}{2})} = 
\sum_{m=0}^\infty \frac{1}{m!}\Cay_m(x;y) t^m,
\end{equation*}
which is the case for $(\ga, \beta) = (\frac{y+x}{2}, \frac{y-x}{2})$ in \eqref{eqn:Jacobi2}
(cf.\ \cite[(4)]{MT05}). Thus,
\begin{align}\label{eqn:CayP}
\Cay_m(s;k) 
&= m! \cdot 2^m \cdot P_m^{(\frac{k+s-2m}{2}, \frac{k-s-2m}{2})}(0).
\end{align}
The formula \eqref{eqn:pcJ} is then given by substituting \eqref{eqn:CayP} into \eqref{eqn:pc}. 
\end{proof}

\begin{rem}\label{rem:pJ}
The identity \eqref{eqn:pcJpm} 
plays a role in the degenerate cases of
the factorization identities of IDO $\D$ 
and $(\fg, B)$-homomorphisms $\varphi$.
(See Cases (5) and (6) of 
Theorems \ref{thm:factor1}  and \ref{thm:factor2}.)
\end{rem}

For $x, y \in \C$ and $m\in \Z_{\geq 0}$, we write
\begin{equation}\label{eqn:BKraw}
K_m(x;y):=\sum_{j=0}^m(-1)^j\binom{x}{j}\binom{y-x}{m-j}.
\end{equation}
The polynomials $K_m(x;y)$ are called (binary) Krawtchouk polynomials 
(cf.\ \cite[p.\ 151]{MS77} and \cite{Podesta16+}).

\begin{cor}\label{cor:pcK}
For $k, \ell \in \Z_{\geq 0}$, the following hold.
\begin{align}
p_c^{(k-2\ell;k)}(t) &= \sum_{m=0}^k \frac{1}{2^m} 
 k^{\underline{m}} K_m(\ell;k) t^m, \label{eqn:Kraw1}\\[3pt]
p_c^{(2k-\ell;\ell)}(t) &= \sum_{m=0}^\ell \frac{(-1)^m}{2^m}  \ell^{\underline{m}} 
K_m(k;\ell) t^m. \label{eqn:Kraw2}
\end{align}
\end{cor}

\begin{proof}
To show \eqref{eqn:Kraw1},
observe that if $s=k-2\ell$, then
\begin{equation*}
\tfrac{1}{2}(k+s-2m)=k-\ell-m
\quad \text{and} \quad
\tfrac{1}{2}(k-s-2m) = \ell-m.
\end{equation*}
Then, by Theorem \ref{thm:unif}, we have 
\begin{equation}\label{eqn:pcP}
p_c^{(k-2\ell;k)}(t) = \sum_{m=0}^k k^{\underline{m}}
P_m^{(k-\ell-m, \ell-m)}(0)t^m.
\end{equation}
On the other hand, it follows from \eqref{eqn:BKraw} that
$K_m(x;y)$ satisfies the following generating function:
\begin{equation}\label{eqn:KroGen}
(1+t)^{y-x}(1-t)^x = \sum_{m=0}^\infty K_m(x;y) t^m,
\end{equation}
which is the case for $(\ga, \beta)= (y-x, x)$ in \eqref{eqn:Jacobi2}. Thus,
\begin{equation}\label{eqn:KJ}
K_m(\ell;k) = 
2^m \cdot P_m^{(k-\ell-m, \ell-m)}(0).
\end{equation}
Now \eqref{eqn:pcP} and \eqref{eqn:KJ} yield the desired formula.

Likewise, if $s=2k-\ell$, then the same argument shows that
\begin{align*}%\label{eqn:pcP2}
p_c^{(2k-\ell;\ell)}(t) 
&= \sum_{m=0}^\ell \ell^{\underline{m}}
P_m^{(k-m, \ell-k-m)}(0)t^m \\[3pt]
&= \sum_{m=0}^\ell \ell^{\underline{m}}(-1)^m
P_m^{(\ell-k-m,k-m)}(0)t^m,
\end{align*}
where \eqref{eqn:Jacobi4} is applied from line one to line two.
The identity $K_m(k;\ell)=2^m \cdot P_m^{(\ell-k-m,k-m)}(0)$ 
then concludes the other formula \eqref{eqn:Kraw2}.
\end{proof}

We end this section by showing an identity on the binary
Krawtchouk polynomials $K_m(x;y)$, which will 
be used in the proof of  the factorization identities in the next section.

\begin{lem}
For $x,y \in \C$ and $m \in \Z_{\geq 0}$, we have 
\begin{equation}\label{eqn:BinKro}
\binom{x}{m} = (-1)^m\sum^m_{r=0}\binom{x-y}{m-r}K_r(x;y).
\end{equation}

\end{lem}

\begin{proof}
Observe that 
\begin{equation*}
(1-t)^{x} = (1+t)^{x-y}(1+t)^{y-x}(1-t)^x,
\end{equation*}
which implies that 
\begin{equation*}
\sum_{m=0}^\infty(-1)^m\binom{x}{m}t^m = 
\big(\sum_{u=0}^\infty \binom{x-y}{u}t^u \big) \big(\sum_{r=0}^\infty K_r(x;y)t^r\big)
\end{equation*}
by \eqref{eqn:BinomGen} and \eqref{eqn:KroGen}.
Now take the coefficients of $t^m$ on the both sides to conclude \eqref{eqn:BinKro}.
\end{proof}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Factorization identities}
\label{sec:factorization}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

The aim of this section is to show the factorization identities 
of the differential intertwining operators $\D$ and 
$(\fg, B)$-homomorphisms $\varphi$.
Such identities are accomplished  
in Theorems \ref{thm:factor1} and \ref{thm:factor2}
for $\varphi$ and $\D$, respectively. 

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{General theory of homomorphisms between Verma modules}
\label{subsec:Verma1}
We begin with a quick overview of a general theory of homomorphisms 
between Verma modules.
Let $\fg$ be a complex simple Lie algebra and fix a Cartan subalgebra $\fh$ of $\fg$.
We also fix an inner product $\IP{\cdot}{\cdot}$ on $\fh^*$.
Let $\Delta$ denote the set of roots of $\fg$ with respect to $\fh$.
Choose a positive system $\gD^+$ for $\gD$ and write $\Pi$ for the 
set of simple roots for $\gD^+$. We write $\fb = \fh \oplus \fn_+$ for
the Borel subalgebra corresponding to $\gD^+$.
For $\ga \in \gD$ and $\mu \in \fh^*$, 
we write $s_\ga\mu = \mu - \IP{\mu}{\ga^\ssv}\ga$
with $\ga^\ssv =\frac{2}{\IP{\ga}{\ga}}\ga$.

As in Section \ref{sec:InfChar}, for $\mu \in \fh^*$, we write
\begin{equation*}
N(\mu):=\Cal{U}(\fg)\otimes_{\Cal{U}(\fb)} \C_{\mu-\rho},
\end{equation*}
where $\rho$ is half the sum of the positive roots.

It is well known that we have
$\dim_\C\Hom_{\fg}(N(\nu),N(\lambda)) \leq 1$
for any $\nu, \lambda \in \fh^*$.
To describe the condition when $\dim_\C\Hom_{\fg}(N(\nu),N(\lambda)) = 1$,
we next recall the notion of a \emph{link} between weights.

\begin{defn}
[Bernstein--Gelfand--Gelfand]
\label{def:Link}
Let $\gl, \lambda \in \fh^*$ and $\gb_1, \ldots, \gb_t \in \gD^+$. Set $\lambda_0 = \lambda$
and $\lambda_i = s_{\gb_i} \cdots s_{\gb_1}(\lambda)$ for $1 \leq i \leq t$.
We say that the sequence $(\gb_1, \ldots, \gb_t)$ \emph{links} $\lambda$ to $\gl$ if 
the following two conditions are satisfied:
\begin{enumerate}
\item[(1)] $\lambda_t = \gl$;
\item[(2)] $\IP{\lambda_{i-1}}{\gb_i^{\ssv}} \in \Z_{\geq 0}$ for $1\leq i \leq t$.
\end{enumerate}
\end{defn}

Let $L(\gl)$ denote the unique irreducible quotient of 
the Verma module $N(\gl)$.
The following celebrated result of BGG--Verma shows when 
$\dim_\C\Hom_{\fg}(N(\nu),N(\lambda)) = 1$.

\begin{thm}
[BGG--Verma]
\label{thm:BGGV}
The following three conditions on $\gl, \lambda \in \fh^*$ are equivalent.
\begin{enumerate}
\item[\emph{(i)}] $\dim_\C\Hom_{\fg}(N(\nu),N(\lambda)) =1$.
\item[\emph{(ii)}] $L(\gl)$ is a composition factor of $N(\lambda)$.
\item[\emph{(iii)}] There exists a sequence $(\gb_1, \ldots, \gb_t)$ with $\gb_i \in \gD^+$
that links $\lambda$ to $\gl$.
\end{enumerate}
\end{thm}


To show factorization identities,
singular vectors of the composition of 
two homomorphisms between Verma modules have to be computed.
The next two lemmas will be useful for this matter.

\begin{lem}\label{lem:hom-comp}
For $\lambda, \nu, \mu \in \fh^*$,
let 
$\varphi_1\colon N(\nu)\to N(\mu)$ and $\varphi_2\colon N(\mu)\to N(\lambda)$
be
homomorphisms 
between Verma modules such that 
$\varphi_1(1\otimes \mathbb{1}_{\nu-\rho})=u_1\otimes \mathbb{1}_{\mu-\rho}$
and $\varphi_2(1\otimes \mathbb{1}_{\mu-\rho})=u_2\otimes \mathbb{1}_{\lambda-\rho}$.
Then $(\varphi_2 \circ \varphi_1)(1\otimes \mathbb{1}_{\nu-\rho})$ 
is given by 
\begin{equation*}
(\varphi_2 \circ \varphi_1)(1\otimes \mathbb{1}_{\nu-\rho}) 
= u_1u_2\otimes \mathbb{1}_{\lambda-\rho}.
\end{equation*}
\end{lem}

One ensures the order of $u_1$ and $u_2$ in Lemma \ref{lem:hom-comp},
namely, $(\varphi_2 \circ \varphi_1)(1\otimes \mathbb{1}_{\nu-\rho}) 
\neq u_2u_1\otimes \mathbb{1}_{\lambda-\rho}$.
For the proof, see, for instance, \cite[Lem.\ 3.7]{KuOr19}.


\begin{lem}
Retain the hypothesis of Lemma \ref{lem:hom-comp}. 
Let $\widehat{\dpi}\equiv\widehat{d\pi_{(\xi,\lambda)^*}}$ denote the 
transformed representation of $\fg$ defined as in \eqref{eqn:hdpi}.
Then the algebraic Fourier transform
$F_c(\varphi_2\circ \varphi_1)$ of $\varphi_2\circ \varphi_1  \in \Hom_{\fg}(N(\nu),N(\lambda))$ 
is given by
\begin{equation}\label{eqn:Fc-comp0}
F_c(\varphi_2\circ \varphi_1) 
= (\widehat{\dpi}(u_1)\widehat{\dpi}(u_2))\acts 1
= \widehat{\dpi}(u_1) \acts (\widehat{\dpi}(u_2)\acts 1).
\end{equation}
In particular, if $u_j \in \Cal{U}(\fn_-)$ for $j=1,2$, then
\begin{equation}\label{eqn:Fc-comp}
F_c(\varphi_2\circ \varphi_1) 
= (\widehat{dL}(u_1)\widehat{dL}(u_2))\acts 1
= \widehat{dL}(u_1) \acts (\widehat{dL}(u_2)\acts 1).
\end{equation} 
\end{lem}

\begin{proof}
The identities \eqref{eqn:Fc-comp0} and \eqref{eqn:Fc-comp} 
are immediate consequences of Lemma \ref{lem:hom-comp} and \eqref{eqn:dpiL}.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Factorization identities}
\label{subsec:Verma2}
Now we consider the factorization identities of 
$(\fg, B)$-homomorphisms $\varphi$ and IDOs $\D$ in order.
Recall from Section \ref{sec:DIO} that
\begin{align*}
\Lambda_a&=(-\Z_{\geq 0})\times \C, \\[3pt]
\swap{\Lambda}_a&=\C \times (-\Z_{\geq 0}), \\[3pt]
\Lambda_b&=\{(1-k, 1-\ell+k) : k, \ell \in 1+\Z_{\geq 0}\}, \\[3pt]
\swap{\Lambda}_b&=\{(1-k+\ell, 1-\ell) : k, \ell \in 1+\Z_{\geq 0}\}, \\[3pt]
\Lambda_c&=\{(\tfrac{1}{2}(2-k-s), \tfrac{1}{2}(2-k+s)) : k \in 1+\Z_{\geq 0} \; 
\text{and} \;  s \in \C\}.
\end{align*}
Further, for $\square \in \{> , <, =\}$,
we put
\begin{align*}
\Lambda_b^{(k\,\square\, \ell)}
&:=\{(1-k, 1-\ell+k) \in \Lambda_b:  k\, \square\, \ell \}, \\[3pt]
\swap{\Lambda}{}_b^{(k\, \square\, \ell)}
&:=\{(1-k+\ell, 1-\ell)  \in \swap{\Lambda}_b:
k\, \square\, \ell\}.
\end{align*}
One can easily check that
\begin{equation*}
\Lambda_b \subset \Lambda_a \cap \Lambda_c,
\quad
\swap{\Lambda}_b \subset \swap{\Lambda}_a \cap \Lambda_c,
\quad
\text{and}
\quad
\Lambda_b^{(k < \ell)} = \swap{\Lambda}{}_b^{(k>\ell)}.
\end{equation*}

Also, recall from Section \ref{sec:InfChar} that 
in the identification 
$\fa^*=\{(v_1, v_2 , v_3) \in \C^3: v_1+v_2+v_3=0\}$,
we have 
\begin{align*}
\mu_\lambda
&:=-(\lambda_1\varpi_1+\lambda_2\varpi_2)+\rho\\[3pt]
&=\tfrac{1}{3}(-(2\lambda_1+\lambda_2-3), \lambda_1-\lambda_2, \lambda_1+2\lambda_2-3).
\end{align*}
We put 
\begin{equation*}
\theta_{(k,\ell)}:=\frac{1}{3}(k+\ell, \ell-2k, k-2\ell)
\quad
\text{and}
\quad
\swap{\theta}_{(k,\ell)}:=\frac{1}{3}(2k-\ell, 2\ell-k, -(k+\ell)).
\end{equation*}
Then,
\begin{equation*}
\mu_\lambda 
=
\begin{cases}
\theta_{(k,\ell)} &
\text{if $(\lambda_1,\lambda_2)=(1-k,1-\ell+k) \in \Lambda_b$},\\[3pt]
\swap{\theta}_{(k,\ell)} &
\text{if $(\lambda_1,\lambda_2)=(1-k+\ell,1-\ell) \in \swap{\Lambda}_b$}
\end{cases}
\end{equation*}
and
\begin{equation*}
\theta_{(k,\ell)} = \swap{\theta}_{(\ell, \ell-k)}
\quad
\text{for $k \leq \ell$}
\quad
\text{and}
\quad
\swap{\theta}_{(k, \ell)}= \theta_{(k-\ell,k)}
\quad
\text{for $k\geq \ell$}.
\end{equation*}
Moreover, we have
\begin{equation*}
s_\beta s_\ga\theta_{(k,k)} = s_\gamma \theta_{(k,k)}
\quad
\text{and}
\quad
s_\ga s_\beta\swap{\theta}_{(k,k)} = s_\gamma \swap{\theta}_{(k,k)}.
\end{equation*}

\medskip

First we show that, to study factorization identities, 
it suffices to consider $(\lambda_1,\lambda_2) \in \gL_b\cup \swap{\gL}_b$.
As in Theorem \ref{thm:Hom3},
we write
\begin{equation*}
\ga=(1,-1,0),\quad
\beta=(0,1,-1), \quad
\gamma=(1,0,-1).
\end{equation*}

\begin{prop}
Suppose that 
$\varphi\colon N(\mu'_\lambda)^{(\delta_1,\delta_2)} \to N(\mu_\lambda)^{(+,+)}$
is a non-zero $(\fg, B)$-homomorphism in Theorem \ref{thm:Hom3}.
If $\varphi$ admits a factorization identity, then 
$(\lambda_1,\lambda_2)\in \gL_b\cup \swap{\gL}_b$.
\end{prop}

\begin{proof}
Since $\varphi$ admits a factorization identity, 
it follows from Theorem \ref{thm:BGGV} that
$\mu_\lambda'$ must be
$\mu'_\lambda \in 
\{s_\ga s_\beta \mu_\lambda, \, 
s_\beta s_\ga \mu_\lambda,\, s_\gamma \mu_\lambda\}$.
Theorem \ref{thm:Hom3} shows that
if $\mu_\lambda' \in \{ s_\ga s_\beta \mu_\lambda,\, s_\beta s_\ga \mu_\lambda\}$, then
$\varphi = \varphi^{(k.\ell)}_{\pm}$ for some $k,\ell \in 1+\Z_{\geq 0}$.
Thus, in this case, $(\lambda_1,\lambda_2) \in \gL_b\cup \swap{\gL}_b$.

We now show that even if $\mu_\lambda' = s_\gamma \mu_\lambda$,
the parameters $(\lambda_1,\lambda_2)$ satisfy the proposed condition.
Indeed, in this case, we have $\varphi = \varphi^{(s; k)}_c$ and 
$(\lambda_1,\lambda_2) = (\tfrac{1}{2}(2-k-s), \tfrac{1}{2}(2-k+s))$
for some $k \in 1+\Z_{\geq 0}$ and $s \in \C$. 
Let $\varphi^{(s;k)} = \varphi'' \circ \varphi'$ denote a factorization
of $\varphi^{(s;k)}$. Then 
$\varphi' \in \{\varphi^{(\ell)}_1,  \varphi^{(\ell)}_2, 
\varphi^{(\ell_1, \ell_2)}_{\pm}\}$ for some $\ell, \ell_1, \ell_2 \in 1+\Z_{\geq 0}$.
If $\varphi' = \varphi^{(\ell_1, \ell_2)}_{\pm}$, then 
$(\lambda_1,\lambda_2) \in \gL_b\cup \swap{\gL}_b$.
Next, suppose that $\varphi' \in \{\varphi^{(\ell)}_1,  \varphi^{(\ell)}_2\}$.
If $\varphi' = \varphi^{(\ell)}_1$, then
Theorem \ref{thm:Hom3} shows that
$\varphi'$ is a map
$\varphi \colon N(s_\ga\mu_\lambda)^{(+,(-)^\ell)} \to N(\mu_\lambda)^{(+,+)}$
with
$\IP{\mu_\lambda}{\ga} =\ell$. A direct computation shows that 
$\IP{\mu_\lambda}{\ga}=\tfrac{1}{2}(k+s)$.
The equality $\tfrac{1}{2}(k+s)=\ell$
leads to the condition $(\lambda_1,\lambda_2) \in \gL_b$.
Likewise, if $\varphi' = \varphi^{(\ell)}_2$, then
$(\lambda_1,\lambda_2) \in \swap{\gL}_b$.
Now the proposition follows.
\end{proof}

We next exhibit the factorization identities for 
$(\lambda_1,\lambda_2) \in \gL_b\cup \swap{\gL}_b$.


\begin{thm}\label{thm:factor1}
Let $(\lambda_1,\lambda_2) \in \Lambda_b \cup \swap{\Lambda}_b$.
Then the following factorization identities hold.

\begin{enumerate}

\item[\emph{(1)}] 
For $(\lambda_1,\lambda_2) = (1-k, 1-\ell+k) 
\in \Lambda_b^{(k < \ell)}(=\swap{\Lambda}{}_b^{(k>\ell)})$,
the homomorphisms $\varphi_+^{(k,\ell)}$ and $\varphi_c^{(2k-\ell;\ell)}$
can be factored as 
\begin{equation*}
\varphi_+^{(k,\ell)}=\varphi_1^{(k)}\circ \varphi_2^{(\ell)}
\quad
\text{and}
\quad
\varphi_c^{(2k-\ell;\ell)}
=\varphi_+^{(k,\ell)}\circ \varphi_1^{(\ell-k)}.
\end{equation*}
Equivalently, the following diagram commutes.
\begin{equation*}
\begin{tikzcd}[row sep=1cm, column sep=1cm]
&
N(s_\beta s_\alpha\theta_{(k,\ell)})^{((-)^\ell,(-)^k)} 
\arrow[rrd, "\varphi_+^{(k,\ell)}"']
\arrow[r,"\varphi_2^{(\ell)}"]  
& N(s_\alpha\theta_{(k,\ell)})^{(+,(-)^k)}
 \arrow[dr, "\varphi_1^{(k)}"]&\\
 N(s_\gamma\theta_{(k,\ell)})^{((-)^\ell,(-)^\ell)}
\arrow[urr, "\varphi_-^{(\ell-k,\ell)}"']
\arrow[ur, "\varphi_1^{(\ell-k)}"]
\arrow[rrr, "\varphi_c^{(2k-\ell;\ell)}"']
& 
\arrow[u,  pos=0.89, phantom, "\circlearrowleft"]
\arrow[ru,  pos=0.55, phantom, "\circlearrowleft"]
& \arrow[u,  pos=0.89, phantom, "\circlearrowleft"]
& N(\theta_{(k,\ell)})^{(+,+)}\\
\end{tikzcd}
\end{equation*}

\item[\emph{(2)}]
For $(\lambda_1,\lambda_2) =(1-k, 1-\ell+k) \in \Lambda_b^{(k>\ell)}$,
the homomorphism $\varphi_+^{(k,\ell)}$ can be factored as 
\begin{equation*}
\varphi_c^{(2k-\ell;\ell)} \circ \varphi^{(k-\ell)}_1
= \varphi_+^{(k,\ell)}
=\varphi^{(k)}_1 \circ \varphi^{(\ell)}_2.
\end{equation*}
Equivalently, 
the following diagram commutes.
\begin{equation*}
\begin{tikzcd}[row sep=1cm, column sep=1cm]
& N(s_\gamma \theta_{(k,\ell)})^{((-)^\ell,(-)^\ell)} 
\arrow[ddr, "\varphi_c^{(2k-\ell;\ell)}"] 
&\\
N(s_\beta s_\ga\theta_{(k,\ell)})^{((-)^\ell,(-)^k)} 
\arrow[drr,"\varphi_+^{(k,\ell)}"]
\arrow[ur, "\varphi_1^{(k-\ell)}"]
\arrow[dr, "\varphi_2^{(\ell)}"']
 & & \\
&N(s_\ga\theta_{(k,\ell)})^{(+,(-)^k)}
\arrow[uu,  pos=0.5, phantom, "\circlearrowleft"] 
\arrow[uu,  pos=0.03, phantom, "\circlearrowleft"] 
\arrow[r, "\varphi_1^{(k)}"']  
&N(\theta_{(k,\ell)})^{(+,+)}  
\\
\end{tikzcd}
\end{equation*}


\item[\emph{(3)}] 
For $(\lambda_1,\lambda_2) =(1-k+\ell, 1-\ell) \in
\swap{\Lambda}{}_b^{(k>\ell)}(=\Lambda_b^{(k < \ell)})$,
the homomorphisms 
$\varphi_-^{(k,\ell)}$ and $\varphi_c^{(k-2\ell;k)}$ can be 
factored as 
\begin{equation*}
\varphi_-^{(k,\ell)} = \varphi^{(\ell)}_2 \circ \varphi^{(k)}_1
\quad
\text{and}
\quad
\varphi_c^{(k-2\ell;k)} 
=\varphi_-^{(k,\ell)} \circ \varphi^{(k-\ell)}_2.
\end{equation*}
Equivalently, 
the following diagram commutes.
\begin{equation*}
\begin{tikzcd}[row sep=1cm, column sep=1cm]
N(s_\gamma \swap{\theta}_{(k,\ell)})^{((-)^k,(-)^k)}
\arrow[dr, "\varphi_2^{(k-\ell)}"']
\arrow[rrr, "\varphi_c^{(k-2\ell;k)}"]
\arrow[drr, "\varphi_+^{(k,k-\ell)}"]
& 
\arrow[d,  pos=0.89, phantom, "\circlearrowleft"]
\arrow[rd,  pos=0.55, phantom, "\circlearrowleft"]
& 
\arrow[d,  pos=0.89, phantom, "\circlearrowleft"]
&  N(\swap{\theta}_{(k,\ell)})^{(+,+)}\\
&N(s_\ga s_\beta\swap{\theta}_{(k,\ell)})^{((-)^\ell,(-)^k)}   
\arrow[r, "\varphi_1^{(k)}"']  
\arrow[urr, "\varphi_-^{(k,\ell)}"]
&N(s_\beta\swap{\theta}_{(k,\ell)})^{((-)^\ell,+)}  
\arrow[ur, "\varphi_2^{(\ell)}"']&\\
\end{tikzcd}
\end{equation*}


\item[\emph{(4)}]
For $(\lambda_1,\lambda_2)=(1-k+\ell, 1-\ell)\in \swap{\Lambda}{}_b^{(k<\ell)}$, 
the homomorphism $\varphi_-^{(k,\ell)}$ 
can be factored as 
\begin{equation*}
\varphi_c^{(k-2\ell;k)} \circ \varphi_2^{(\ell-k)}
= \varphi_-^{(k,\ell)}=\varphi_2^{(\ell)}\circ \varphi_1^{(k)}.
\end{equation*}
Equivalently, the following diagram commutes.
\begin{equation*}
\begin{tikzcd}[row sep=1cm, column sep=1cm]
&
N(s_\beta\swap{\theta}_{(k,\ell)})^{((-)^\ell,+)}
\arrow[r, "\varphi_2^{(\ell)}"]  
\arrow[dd,  pos=0.05, phantom, "\circlearrowleft"] 
\arrow[dd,  pos=0.5, phantom, "\circlearrowleft"] 
&N(\swap{\theta}_{(k,\ell)})^{(+,+)} &\\
N(s_\alpha  s_\beta\swap{\theta}_{(k,\ell)})^{((-)^\ell,(-)^k)} 
\arrow[rru, "\varphi_-^{(k,\ell)}"']
\arrow[ur, "\varphi_1^{(k)}"]
\arrow[dr, "\varphi_2^{(\ell-k)}"']
& & & \\
& N(s_\gamma\swap{\theta}_{(k,\ell)})^{(-)^k,(-)^k)} 
\arrow[uur, "\varphi_c^{(k-2\ell;k)}"']
& &\\
\end{tikzcd}
\end{equation*}

\item[\emph{(5)}]  
For $(\lambda_1,\lambda_2) =(1-k, 1) \in \Lambda_b^{(k=\ell)}$,
we have
\begin{equation*}
\varphi_c^{(k;k)} 
= \varphi_+^{(k,k)}
=\varphi^{(k)}_1 \circ \varphi^{(k)}_2.
\end{equation*}
Equivalently, 
the following diagram commutes.
\begin{equation*}
\begin{tikzcd}[row sep=1cm, column sep=1cm]
&
N(s_\ga\theta_{(k,k)})^{(+,(-)^k)}
\arrow[rd, "\varphi_1^{(k)}"]
 & \\
N(s_\gamma \theta_{(k,k)})^{((-)^k,(-)^k)} 
\arrow[rr, "\varphi_c^{(k;k)}=\varphi_+^{(k,k)}"']
\arrow[ur, "\varphi_2^{(k)}"]
&
\arrow[u,  pos=0.5, phantom, "\circlearrowleft"]
 &  
 N(\theta_{(k,k)})^{(+,+)}\\
\end{tikzcd}
\end{equation*}

\item[\emph{(6)}]
For $(\lambda_1,\lambda_2)=(1, 1-k)\in \swap{\Lambda}{}_b^{(k=\ell)}$, 
we have
\begin{equation*}
\varphi_c^{(-k;k)} 
= \varphi_-^{(k,k)}
=\varphi_2^{(k)}\circ \varphi_1^{(k)}.
\end{equation*}
Equivalently, the following diagram commutes.
\begin{equation*}
\begin{tikzcd}[row sep=1cm, column sep=1cm]
N(s_\gamma\swap{\theta}_{(k,k)})^{(-)^k,(-)^k)} 
\arrow[rr, "\varphi_c^{(-k;k)}=\varphi_-^{(k,k)}"]
\arrow[dr,"\varphi_1^{(k)}"']
&
\arrow[d,  pos=0.5, phantom, "\circlearrowleft"]
 & N(\swap{\theta}_{(k,k)})^{(+,+)} \\
&
N(s_\beta\swap{\theta}_{(k,k)})^{((-)^k,+)}
\arrow[ur, "\varphi_2^{(k)}"']
&
\end{tikzcd}
\end{equation*}

\end{enumerate}

\end{thm}

\begin{proof}
We demonstrate the proof of the factorization identities in (1) and (2); 
the other cases can be handled similarly.
As the characters $(\pm,\pm)$ of $M$ 
in the diagrams directly follow from Theorem \ref{thm:Hom3},
we only focus on the factorizations of the homomorphisms $\varphi$.
Remark that the identities $\varphi_c^{(\pm k;k)} = \varphi_\pm^{(k,k)}$
in Cases (5) and (6) follow from \eqref{eqn:pcJpm}.

To get ready for the proof, observe that
similar arguments for Lemma \ref{lem:dR}
and the algebraic Fourier transform $\widehat{\;\cdot\;}$ \eqref{eqn:Weyl} 
show that $\widehat{dL}(N_j^-)$ for $j=1,2,3$
are given by
\begin{equation}\label{eqn:dL8}
\widehat{dL}(N_1^-)=
\zeta_1 -\frac{\zeta_3}{2}\frac{\partial}{\partial \zeta_2},
\quad
\widehat{dL}(N_2^-)=\zeta_2 +\frac{\zeta_3}{2}\frac{\partial}{\partial \zeta_1},
\quad
\widehat{dL}(N_3^-)=\zeta_3.
\end{equation}
Further, recall from \eqref{eqn:eta3} that 
$\eta_c^{(s;k)}(a_1,a_2,a_3)$ is a polynomial on an algebra $\Cal{A}$ defined by
\begin{equation*}
\eta_c^{(s;k)}(a_1,a_2,a_3)
= \sum_{m=0}^{k} \frac{1}{2^m}\binom{k}{m}\Cay_m(s;k)
\sigma_{2k-m}(a_1^{k-m} a_2^{k-m} a_3^m).
\end{equation*}
By \eqref{eqn:Kraw1} and \eqref{eqn:Kraw2}, we have 
\begin{align}
\eta_c^{(k-2\ell;k)}(a_1,a_2,a_3)&=\sum_{m=0}^k \frac{1}{2^m}k^{\underline{m}}K_m(\ell;k)
\sigma_{2k-m}(a_1^{k-m} a_2^{k-m} a_3^m), \label{eqn:nKraw1}\\[3pt]
\eta_c^{(2k-\ell;\ell)}(a_1,a_2,a_3)&=\sum_{m=0}^\ell \frac{(-1)^m}{2^m}\ell^{\underline{m}}K_m(k;\ell)
\sigma_{2\ell-m}(a_1^{\ell-m} a_2^{\ell-m} a_3^m).\label{eqn:nKraw2}
\end{align}

In the following, we omit writing the highest weights of Verma modules.
For instance, we simply write $1\otimes \mathbb{1}$
for a highest weight vector $1\otimes \mathbb{1}_{\theta_{(k,\ell)}-\rho}$
of $N(\theta_{(k,\ell)})$. 


We start with $\varphi_+^{(k,\ell)} = \varphi^{(k)}_1 \circ \varphi^{(\ell)}_2$.
To prove this, it suffices to show 
$F_c(\varphi_+^{(k,\ell)}) = F_c(\varphi^{(k)}_1 \circ \varphi^{(\ell)}_2)$.
Observe that the homomorphisms
$\varphi^{(k)}_1 \circ \varphi^{(\ell)}_2$
and 
$\varphi_+^{(k,\ell)}$
map
\begin{align*}
\varphi^{(k)}_1 \circ \varphi^{(\ell)}_2
&\colon
1\otimes \mathbb{1}
\longmapsto
(N_2^-)^\ell(N_1^-)^k \otimes \mathbb{1}\\[3pt]
\varphi_+^{(k,\ell)}
&\colon
1\otimes \mathbb{1}
\longmapsto
\eta_+^{(k,\ell)}(N_1^-,N_2^-,N_3^-)\otimes \mathbb{1},
\end{align*}
By \eqref{eqn:dL8}, we have 
$\widehat{dL}(N_1^-)^k\acts 1 = \zeta_1^k$
and, by \eqref{eqn:Finv3} and \eqref{eqn:eta1},
\begin{equation*}
F_c(\varphi_+^{(k,\ell)})
=\eta_+^{(k,\ell)}(\zeta_1,\zeta_2,\zeta_3)
=\sum_{m=0}^k\frac{1}{2^m}m!\binom{k}{m}\binom{\ell}{m} 
\zeta_1^{k-m}\zeta_2^{\ell-m}\zeta_3^m.
\end{equation*}
It then follows from \eqref{eqn:Fc-comp} that the Fourier transform 
$F_c(\varphi^{(k)}_1 \circ \varphi^{(\ell)}_2)$ is evaluated as

\begin{align*}
F_c(\varphi^{(k)}_1 \circ \varphi^{(\ell)}_2)
&=\widehat{dL}(N_2^-)^\ell\acts \left(\widehat{dL}(N_1^-)^k\acts 1 \right) \\[3pt]
&=\widehat{dL}(N_2^-)^\ell\acts \zeta_1^k \\[3pt]
&=\left(\zeta_2+\frac{\zeta_3}{2}\frac{\partial}{\partial \zeta_1} \right)^\ell 
\acts \zeta_1^k\\[3pt]
&=\left(
\sum_{m=0}^\ell\frac{1}{2^m}\binom{\ell}{m} \zeta_2^{\ell-m}\zeta_3^m
\frac{\partial^m}{\partial \zeta_1^m} \right) \acts \zeta_1^k\\[3pt]
&=
\sum_{m=0}^k\frac{1}{2^m}m!\binom{k}{m}\binom{\ell}{m} 
\zeta_1^{k-m}\zeta_2^{\ell-m}\zeta_3^m\\[3pt]
&=F_c(\varphi_+^{(k,\ell)}).
\end{align*}

Next, we show 
$\varphi_c^{(2k-\ell;\ell)}
=\varphi_+^{(k,\ell)}\circ \varphi_1^{(\ell-k)}$.
The homomorphisms $\varphi_+^{(k,\ell)}\circ \varphi_1^{(\ell-k)}$ 
and $\varphi_c^{(2k-\ell;\ell)}$ map
\begin{align*}
\varphi_+^{(k,\ell)}\circ \varphi_1^{(\ell-k)}
&\colon
1\otimes \mathbb{1} \longmapsto
(N_1^-)^{\ell-k}\eta_+^{(k,\ell)}(N_1^-,N_2^-,N_3^-) \otimes \mathbb{1}, \\[3pt]
\varphi_c^{(2k-\ell;\ell)} &\colon 1\otimes \mathbb{1} \longmapsto
\eta_c^{(2k-\ell;\ell)}(N_1^-,N_2^-,N_3^-) \otimes \mathbb{1}.
\end{align*}
It follows from \eqref{eqn:Finv3}, \eqref{eqn:eta1}, and \eqref{eqn:nKraw2} that
\begin{align*}
\widehat{dL}(\eta_+^{(k,\ell)}(N_1^-,N_2^-,N_3^-)) \acts 1
&=\eta_+^{(k,\ell)}(\zeta_1,\zeta_2,\zeta_3)\\
&=\sum_{j=0}^k\frac{1}{2^j}j!\binom{k}{j}\binom{\ell}{j} \zeta_1^{k-j}\zeta_2^{\ell-j}\zeta_3^j,\\[3pt]
F_c(\varphi_c^{(2k-\ell;\ell)})
&=\eta_c^{(2k-\ell;\ell)}(\zeta_1,\zeta_2,\zeta_3)\\
&=\sum_{m=0}^\ell \frac{(-1)^m}{2^m}\ell^{\underline{m}}K_m(k;\ell)
\zeta_1^{\ell-m} \zeta_2^{\ell-m} \zeta_3^m.
\end{align*} 
Thus we have 
\begin{align*}
F_c(\varphi_+^{(k,\ell)}\circ \varphi_1^{(\ell-k)})
&=
\widehat{dL}(N_1^-)^{\ell-k}\acts
(\widehat{dL}(\eta_+^{(k,\ell)}(N_1^-,N_2^-,N_3^-) \acts 1)\\[3pt]
&=
\left(\zeta_1-\frac{\zeta_3}{2}\frac{\partial}{\partial \zeta_2} \right)^{\ell-k}\acts
\left(
\sum_{j=0}^k\frac{1}{2^j}j!\binom{k}{j}\binom{\ell}{j} \zeta_1^{k-j}\zeta_2^{\ell-j}\zeta_3^j
\right)\\
&=\sum_{m=0}^\ell\frac{(-1)^m}{2^m}\ell^{\underline{m}}
\sum_{j=0}^m(-1)^j\binom{k}{j}\binom{\ell-k}{m-j}\zeta_1^{\ell-m}
\zeta_2^{\ell-m}\zeta_3^m\\[3pt]
&=\sum_{m=0}^\ell \frac{(-1)^m}{2^m}\ell^{\underline{m}}K_m(k;\ell)
\sigma_{2\ell-m}(\zeta_1^{\ell-m} \zeta_2^{\ell-m} \zeta_3^m)\\[3pt]
&=F_c(\varphi_c^{(2k-\ell;\ell)}).
\end{align*}

As the last identity, we prove 
$\varphi_c^{(k-2\ell;k)} \circ \varphi_2^{(\ell-k)}
= \varphi_-^{(k,\ell)}=\varphi_2^{(\ell)}\circ \varphi_1^{(k)}$.
Since the argument for the last half 
$\varphi_-^{(k,\ell)}=\varphi_2^{(\ell)}\circ \varphi_1^{(k)}$ 
is the same as 
$\varphi_+^{(k,\ell)} = \varphi^{(k)}_1 \circ \varphi^{(\ell)}_2$, 
we only demonstrate
$\varphi_-^{(k,\ell)}= 
\varphi_c^{(k-2\ell;k)} \circ \varphi_2^{(\ell-k)}$.
Observe that we have
\begin{align*}
\varphi_c^{(k-2\ell;k)} \circ \varphi_2^{(\ell-k)}
&\colon 1\otimes \mathbb{1} \longmapsto
(N_2^-)^{\ell-k}\eta_c^{(k-2\ell;k)}(N_1^-,N_2^-,N_3^-)\otimes \mathbb{1},\\
\varphi_-^{(k,\ell)}
&\colon
1\otimes \mathbb{1} \longmapsto \eta_-^{(k,\ell)}(N_1^-,N_2^-,N_3^-)\otimes \mathbb{1}.
\end{align*}
It follows from \eqref{eqn:Finv3}, \eqref{eqn:eta2}, and \eqref{eqn:nKraw1} that
\begin{align*}
\widehat{dL}(\eta_c^{(k-2\ell;k)}(N_1^-,N_2^-,N_3^-))\acts 1
&=\eta_c^{(k-2\ell;k)}(\zeta_1,\zeta_2,\zeta_3)\\[3pt]
&= \sum_{r=0}^k \frac{1}{2^r}k^{\underline{r}}K_r(\ell;k)
\zeta_1^{k-r} \zeta_2^{k-r} \zeta_3^r,\\
F_c(\varphi_-^{(k,\ell)})
&=
\sum_{m=0}^k \frac{(-1)^m}{2^m}m!
\binom{k}{m}\binom{\ell}{m}\zeta_1^{k-m}\zeta_2^{\ell-m}\zeta_3^m.
\end{align*}
Hence,
\begin{align*}
F_c(\varphi_c^{(k-2\ell;k)} \circ \varphi_2^{(\ell-k)})
&=
\widehat{dL}(N_2^-)^{\ell-k}\acts
(\widehat{dL}(\eta_c^{(k-2\ell;k)}(N_1^-,N_2^-,N_3^-))\acts 1)\\[3pt]
&=\left(\zeta_2+\frac{\zeta_3}{2}\frac{\partial}{\partial \zeta_1} \right)^{\ell-k} \acts
\left(\sum_{r=0}^k \frac{1}{2^r}k^{\underline{r}}K_r(\ell;k)
\zeta_1^{k-r} \zeta_2^{k-r} \zeta_3^r\right)\\[3pt]
&=\sum_{m=0}^k \frac{m!}{2^m}\binom{k}{m}
\sum_{r=0}^m\binom{\ell-k}{m-r}K_r(\ell;k)\zeta_1^{k-m}\zeta_2^{\ell-m}\zeta_3^m\\[3pt]
&=\sum_{m=0}^k \frac{(-1)^m}{2^m}m!
\binom{k}{m}\binom{\ell}{m}\zeta_1^{k-m}\zeta_2^{\ell-m}\zeta_3^m\\[3pt]
&=F_c(\varphi_-^{(k,\ell)}).
\end{align*}
Here, \eqref{eqn:BinKro} is applied from line three to line four.
\end{proof}

\begin{rem}
As $\Lambda_b^{(k < \ell)}=\swap{\Lambda}{}_b^{(k>\ell)}$,
one may merge the diagrams in Cases (1) and (3) in one.
For instance, 
for $(\lambda_1,\lambda_2) = (1-k, 1-\ell+k) \in \Lambda_b^{(k < \ell)}$,
we have
\begin{equation}\label{eqn:merge}
\begin{tikzcd}[row sep=1cm, column sep=1cm]
&
N(s_\beta s_\alpha\theta_{(k,\ell)})^{((-)^\ell,(-)^k)} 
\arrow[rrd, "\varphi_+^{(k,\ell)}"']
\arrow[r, "\varphi_2^{(\ell)}"]  
& N(s_\alpha\theta_{(k,\ell)})^{(+,(-)^k)}
\arrow[dr, "\varphi_1^{(k)}"]&\\
N(s_\gamma\theta_{(k,\ell)})^{((-)^\ell,(-)^\ell)}
\arrow[ur, "\varphi_1^{(\ell-k)}"]
\arrow[urr, "\varphi_-^{(\ell-k,\ell)}"']
\arrow[rrr, "\varphi_c^{(2k-\ell;\ell)}"]
\arrow[dr, "\varphi_2^{(k)}"']
\arrow[drr, "\varphi_+^{(\ell,k)}"]
& & & N(\theta_{(k,\ell)})^{(+,+)}\\
&N(s_\ga s_\beta\theta_{(k,\ell)})^{((-)^{\ell-k},(-)^\ell)}   
\arrow[r, "\varphi_1^{(\ell)}"']  
\arrow[urr, "\varphi_-^{(\ell,\ell-k)}"]
&N(s_\beta \theta_{(k,\ell)})^{((-)^{\ell-k},+)}  
\arrow[ur, "\varphi_2^{(\ell-k)}"']&
\end{tikzcd}
\end{equation}

\noindent
Further, since $s_\ga\theta_{(k,\ell)} = \swap{\theta}_{(\ell-k,\ell)}$ and 
$s_\beta\theta_{(k,\ell)} = \theta_{(\ell,k)}$, one may put 
the diagrams in Cases (2) and (4) as in \eqref{eqn:merge} as follows.

\begin{equation*}
\begin{tikzcd}[row sep=1cm, column sep=1cm]
&
N(s_\beta s_\alpha\theta_{(k,\ell)})^{((-)^\ell,(-)^k)} 
\arrow[ddr, pos=0.8, "\varphi_c^{(2\ell-k;k)}"] 
\arrow[r, "\varphi_2^{(\ell)}"]  
& N(s_\alpha\theta_{(k,\ell)})^{(+,(-)^k)}
 \arrow[dr, "\varphi_1^{(k)}"]
&\\
 N(s_\gamma\theta_{(k,\ell)})^{((-)^\ell,(-)^\ell)}
\arrow[ur, "\varphi_1^{(\ell-k)}"]
\arrow[urr, "\varphi_-^{(\ell-k,\ell)}"']
\arrow[dr, "\varphi_2^{(k)}"']
\arrow[drr, "\varphi_+^{(\ell,k)}"]
& & & N(\theta_{(k,\ell)})^{(+,+)}
\\
&N(s_\ga s_\beta\theta_{(k,\ell)})^{((-)^{\ell-k},(-)^\ell)}  
\arrow[uur, pos=0.8,"\varphi_c^{(-(k+\ell);\ell-k)}"'] 
\arrow[r, "\varphi_1^{(\ell)}"']  
&N(s_\beta \theta_{(k,\ell)})^{((-)^{\ell-k},+)}  
\arrow[ur, "\varphi_2^{(\ell-k)}"']&
\end{tikzcd}
\end{equation*}

\end{rem}





We end this section by the differential-operator counterpart of 
Theorem \ref{thm:factor1}. 
We write
\begin{equation*}
\w{I}(\lambda_1,\lambda_2)^{(\eps_1,\eps_2)}
:=\Ind_B^G(\C_{(\eps_1,\eps_2)}\boxtimes 
\C_{(\lambda_1+1,\lambda_2+1)})
\end{equation*}
for the normalized parabolically induced representation.
Under the identification $\fa^*=\{(v_1, v_2 , v_3) \in \C^3: v_1+v_2+v_3=0\}$,
the unnormalized induced representation 
$I(\lambda_1, \lambda_2)^{(\eps_1,\eps_2)}$ can be 
given as
\begin{equation*}
I(\lambda_1, \lambda_2)^{(\eps_1,\eps_2)}
=\w{I}(\lambda_1-1,\lambda_2-1)^{(\eps_1,\eps_2)}
\equiv\w{I}(-\mu_\lambda)^{(\eps_1,\eps_2)},
\end{equation*}
where $\mu_\lambda$ is the weight defined in \eqref{eqn:muL}.

\begin{thm}\label{thm:factor2}
Let $(\lambda_1,\lambda_2) \in \Lambda_b \cup \swap{\Lambda}_b$.
Then the following factorization identities hold.

\begin{enumerate}

\item[\emph{(1)}] 
For $(\lambda_1,\lambda_2) = (1-k, 1-\ell+k) 
\in \Lambda_b^{(k < \ell)}(=\swap{\Lambda}{}_b^{(k>\ell)})$,
the differential operators $\D_+^{(k,\ell)}$ and $\D_c^{(2k-\ell;\ell)}$
can be factored as 
\begin{equation*}
\D_+^{(k,\ell)}=
\D_2^{\ell}\circ \D_1^{k}
\quad
\text{and}
\quad
\D_c^{(2k-\ell;\ell)}
=\D_1^{\ell-k}\circ \D_+^{(k,\ell)}.
\end{equation*}
Equivalently, the following diagram commutes.
\begin{equation*}
\begin{tikzcd}[row sep=1cm, column sep=1cm]
&
\w{I}(-s_\alpha\theta_{(k,\ell)})^{(+,(-)^k)}
\arrow[r, "\D_2^{\ell}"]  
\arrow[rrd, "\D_-^{(\ell-k,\ell)}"']  
& 
\w{I}(-s_\beta s_\alpha\theta_{(k,\ell)})^{((-)^\ell,(-)^k)} 
\arrow[dr, "\D_1^{\ell-k}"]&\\
\w{I}(-\theta_{(k,\ell)})^{(+,+)} 
\arrow[rru, "\D_+^{(k,\ell)}"']
\arrow[ur, "\D_1^{k}"]
\arrow[rrr, "\D_c^{(2k-\ell;\ell)}"']
& 
\arrow[u,  pos=0.89, phantom, "\circlearrowleft"]
\arrow[ru,  pos=0.65, phantom, "\circlearrowleft"]
& 
\arrow[u,  pos=0.89, phantom, "\circlearrowleft"]
& 
\w{I}(-s_\gamma\theta_{(k,\ell)})^{((-)^\ell,(-)^\ell)}\\
\end{tikzcd}
\end{equation*}

\item[\emph{(2)}]  
For $(\lambda_1,\lambda_2) =(1-k, 1-\ell+k) \in \Lambda_b^{(k>\ell)}$,
the differential operator $\D_+^{(k,\ell)}$ can be factored as 
\begin{equation*}
\D^{k-\ell}_1
\circ \D_c^{(2k-\ell;\ell)} 
= \D_+^{(k,\ell)}
=
\D^{\ell}_2
\circ \D^{k}_1.
\end{equation*}
Equivalently, 
the following diagram commutes.
\begin{equation*}
\begin{tikzcd}[row sep=1cm, column sep=1cm]
&
\w{I}(-s_\gamma \theta_{(k,\ell)})^{((-)^\ell,(-)^\ell)} 
\arrow[dr, "\D_1^{k-\ell}"]
& &\\
& &
\w{I}(-s_\beta s_\ga\theta_{(k,\ell)})^{((-)^\ell,(-)^k)} 
&
 \\
\w{I}(-\theta_{(k,\ell)})^{(+,+)}  
\arrow[urr, "\D_+^{(k,\ell)}"]
\arrow[uur, "\D_c^{(2k-\ell;\ell)}"] 
\arrow[r, "\D_1^{k}"']  
&
\w{I}(-s_\ga\theta_{(k,\ell)})^{(+,(-)^k)}
\ar[ur, "\D_2^{\ell}"']
\arrow[uu,  pos=0.5, phantom, "\circlearrowleft"] 
\arrow[uu,  pos=0.01, phantom, "\circlearrowleft"] 
&
&\\
\end{tikzcd}
\end{equation*}

\item[\emph{(3)}] 
For $(\lambda_1,\lambda_2) =(1-k+\ell, 1-\ell) \in
\swap{\Lambda}{}_b^{(k>\ell)}(=\Lambda_b^{(k < \ell)})$,
the differential operators
$\D_-^{(k,\ell)}$ and $\D_c^{(k-2\ell;k)}$ can be 
factored as 
\begin{equation*}
\D_-^{(k,\ell)} = \D^{k}_1 \circ \D^{\ell}_2
\quad
\text{and}
\quad
\D_c^{(k-2\ell;k)} 
=\D^{k-\ell}_2 \circ \D_-^{(k,\ell)}.
\end{equation*}
Equivalently, 
the following diagram commutes.
\begin{equation*}
\begin{tikzcd}[row sep=1cm, column sep=1cm]
\w{I}(-\swap{\theta}_{(k,\ell)})^{(+,+)}
\arrow[drr, "\D_-^{(k,\ell)}"]
\arrow[dr, "\D_2^{\ell}"']
\arrow[rrr, "\D_c^{(k-2\ell;k)}"]
& 
\arrow[d,  pos=0.89, phantom, "\circlearrowleft"]
\arrow[rd,  pos=0.65, phantom, "\circlearrowleft"]
& 
\arrow[d,  pos=0.89, phantom, "\circlearrowleft"]
&  
\w{I}(-s_\gamma \swap{\theta}_{(k,\ell)})^{((-)^k,(-)^k)}\\
&
\w{I}(-s_\beta\swap{\theta}_{(k,\ell)})^{((-)^\ell,+)} 
\arrow[r, "\D_1^{k}"'] 
\arrow[rru,"\D_+^{(k,k-\ell)}"]  
&
\w{I}(-s_\ga s_\beta\swap{\theta}_{(k,\ell)})^{((-)^\ell,(-)^k)}   
\arrow[ur, "\D_2^{k-\ell}"']
&\\
\end{tikzcd}
\end{equation*}


\item[\emph{(4)}]
For $(\lambda_1,\lambda_2)=(1-k+\ell, 1-\ell)\in \swap{\Lambda}{}_b^{(k<\ell)}$, 
the differential operator $\D_-^{(k,\ell)}$ 
can be factored as 
\begin{equation*}
\D_2^{\ell-k}\circ
\D_c^{(k-2\ell;k)}
= \D_-^{(k,\ell)}
=\D_1^{k} \circ \D_2^{\ell}.
\end{equation*}
Equivalently, the following diagram commutes.
\begin{equation*}
\begin{tikzcd}[row sep=1cm, column sep=1cm]
\w{I}(-\swap{\theta}_{(k,\ell)})^{(+,+)} 
\arrow[r, "\D_2^{\ell}"]  
\arrow[ddr,"\D_c^{(k-2\ell;k)}"']
\arrow[rrd,"\D_-^{(k,\ell)}"']
&
\w{I}(-s_\beta\swap{\theta}_{(k,\ell)})^{((-)^\ell,+)}
\arrow[dr,"\D_1^{k}"]
\arrow[dd,  pos=0.5, phantom, "\circlearrowleft"] 
\arrow[dd,  pos=0.05, phantom, "\circlearrowleft"] 
&
&\\
& & 
\w{I}(-s_\alpha  s_\beta\swap{\theta}_{(k,\ell)})^{((-)^\ell,(-)^k)} 
& 
\\
& 
\w{I}(-s_\gamma\swap{\theta}_{(k,\ell)})^{(-)^k,(-)^k)} 
\arrow[ur, "\D_2^{\ell-k}"']
& &\\
\end{tikzcd}
\end{equation*}


\item[\emph{(5)}]  
For $(\lambda_1,\lambda_2) =(1-k, 1) \in \Lambda_b^{(k=\ell)}$,
we have
\begin{equation*}
\D_c^{(k;k)} 
= \D_+^{(k,k)}
=\D^{(k)}_2 \circ \D^{(k)}_1.
\end{equation*}
Equivalently, 
the following diagram commutes.
\begin{equation*}
\begin{tikzcd}[row sep=1cm, column sep=1cm]
&
\w{I}(-s_\ga\theta_{(k,k)})^{(+,(-)^k)}
 \arrow[dr,"\D_2^{(k)}"]  
 & \\
\w{I}(-\theta_{(k,k)})^{(+,+)}
\arrow[rr,"\D_c^{(k;k)}=\D_+^{(k,k)}"']
\arrow[ur,"\D_1^{(k)}"]
&
 \arrow[u,  pos=0.5, phantom, "\circlearrowleft"]
 &  
\w{I}(-s_\gamma \theta_{(k,k)})^{((-)^k,(-)^k)} \\
\end{tikzcd}
\end{equation*}

\item[\emph{(6)}]
For $(\lambda_1,\lambda_2)=(1, 1-k)\in \swap{\Lambda}{}_b^{(k=\ell)}$, 
we have
\begin{equation*}
\D_c^{(-k;k)} 
= \D_-^{(k,k)}
=\D_1^{(k)}\circ \varphi_2^{(k)}.
\end{equation*}
Equivalently, the following diagram commutes.
\begin{equation*}
\begin{tikzcd}[row sep=1cm, column sep=1cm]
\w{I}(-\swap{\theta}_{(k,k)})^{(+,+)} 
\arrow[rr, "\D_c^{(-k;k)}=\D_-^{(k,k)}"]
\arrow[dr,"\D_2^{(k)}"']
&
\arrow[d,  pos=0.5, phantom, "\circlearrowleft"]
& 
\w{I}(-s_\gamma\swap{\theta}_{(k,k)})^{(-)^k,(-)^k)}\\
&
\w{I}(-s_\beta\swap{\theta}_{(k,k)})^{((-)^k,+)}
\arrow[ur,"D_1^{(k)}"']  
&\\
\end{tikzcd}
\end{equation*}


\end{enumerate}

\end{thm}

\begin{proof}
Apply the duality theorem (Theorem \ref{thm:duality}) to Theorem \ref{thm:factor1}.
\end{proof}


