\subsection{Notation for root systems.} \label{subsec:alggrp}
%
Let $G$ be a connected, simply-connected, simple (linear) algebraic group over $\BC$, 
$T$ a maximal torus of $G$. 
We set $\Fg := \Lie(G)$ and $\Ft := \Lie(T)$; 
$\Fg$ is a finite-dimensional simple Lie algebra over $\BC$, and 
$\Ft$ is a Cartan subalgebra of $\Fg$. 
We denote by $\pair{\cdot\,}{\cdot} : \Ft^{\ast} \times \Ft \rightarrow \BC$ 
the canonical pairing, where $\Ft^{\ast} := \Hom_{\BC}(\Ft, \BC)$. 
Let $\Delta \subset \Ft^{\ast}$ be the root system of $\Fg$, 
$\Delta^{+} \subset \Delta$ the set of positive roots, 
and $\{ \alpha_{j} \}_{j \in I} \subset \Delta^{+}$ the set of simple roots. 
We denote by $\alpha^{\vee} \in \Ft$ the coroot of $\alpha \in \Delta$. 
Also, we denote by $\theta \in \Delta^+$ the highest root of $\Delta$, 
and set $\rho := (1/2) \sum_{\alpha \in \Delta^{+}} \alpha$. 
The root lattice $Q$ and the coroot lattice $Q^{\vee}$ of $\Fg$ are defined by 
$Q := \sum_{j \in I} \BZ \alpha_{j}$ and $Q^{\vee} := \sum_{j \in I} \BZ \alpha_{j}^{\vee}$, respectively. 
We set $Q^{\vee,+}:=\sum_{j \in I} \BZ_{\ge 0} \alpha_{j}^{\vee}$; for 
$\xi,\zeta \in Q^{\vee}$, we write $\xi \ge \zeta$ if $\xi-\zeta \in Q^{\vee,+}$. 
For $i \in I$, the weight $\vpi_{i} \in \Ft^{\ast}$ 
given by $\pair{\vpi_{i}}{\alpha_{j}^{\vee}} = \delta_{i,j}$ for all $j \in I$, 
with $\delta_{i,j}$ the Kronecker delta, 
is called the $i$-th fundamental weight. 
The (integral) weight lattice $\Lambda$ of $\Fg$ is defined by 
$\Lambda := \sum_{j \in I} \BZ \vpi_{j}$. 
We denote by $\BZ[\Lambda]$ the group algebra of $\Lambda$, that is, 
the associative algebra generated by formal elements $\be^{\nu}$, $\nu \in \Lambda$, 
where the product is defined by $\be^{\mu} \be^{\nu} := \be^{\mu + \nu}$ for $\mu, \nu \in \Lambda$. 

A reflection $s_{\alpha} \in GL(\Ft^{\ast})$, $\alpha \in \Delta$, 
is defined by $s_{\alpha} \mu := \mu - \pair{\mu}{\alpha^{\vee}} \alpha$ 
for $\mu \in \Ft^{\ast}$. We write $s_{j} := s_{\alpha_{j}}$ for $j \in I$. 
Then the (finite) Weyl group $W$ of $\Fg$ is defined to be the subgroup of $GL(\Ft^{\ast})$ 
generated by $\{ s_{j} \}_{j \in I}$, that is, $W := \langle s_{j} \mid j \in I \rangle$. 
For $w \in W$, there exist $j_{1}, \ldots, j_{r} \in I$ such that $w = s_{j_{1}} \cdots s_{j_{r}}$. 
If $r$ is minimal, then the product $s_{j_{1}} \cdots s_{j_{r}}$ is called a reduced expression for $w$, 
and $r$ is called the length of $w$; we denote by $\ell(w)$ the length of $w$. 
% Note that a reduced expression for $w$ is not unique. However, the length is defined uniquely. 
% Also, the affine Weyl group $W_{\af}$ of $\Fg$ is, by definition, the semi-direct product group 
% $W \ltimes \{ t_{\xi} \mid \xi \in Q^{\vee} \}$ of $W$ and the abelian group 
% $\{ t_{\xi} \mid \xi \in Q^{\vee} \} \cong Q^{\vee}$, 
% where $t_{\xi}$ denotes the translation in $\Fh^{\ast}$ corresponding to $\xi \in Q^{\vee}$.

Let $\J$ be a subset of $I$. We set
%
\begin{align*}
& \QJ := \sum_{j \in \J} \BZ \alpha_j, \qquad 
  \DJs := \Delta^{+} \cap \QJ, \qquad
  \rho_{\J}:=(1/2) \sum_{\alpha \in \DJs} \alpha, \\
& \QJv := \sum_{j \in \J} \BZ \alpha_j^{\vee}, \qquad
  \QJvp := \sum_{j \in \J} \BZ_{\ge 0} \alpha_i^{\vee}, \qquad 
% & \DeJ := \Delta \cap \QJ, \qquad
  \WJs := \langle s_{j} \mid j \in \J \rangle. 
\end{align*}
%
For $w \in W$, let $\mcr{w}=\mcr{w}^{\J}$ and 
$\mxcr{w}=\mxcr{w}^{\J}$ denote the minimal(-length) coset representative
and maximal(-length) coset representative for the coset $w\WJs$, respectively. 
We set $\WJ:=\bigl\{ \mcr{w} \mid w \in W \bigr\} \subset W$. 
Also, we denote by $[\,\cdot\,]=[\,\cdot\,]_{\J}:
Q^{\vee} \twoheadrightarrow \QJv$ the projection 
that maps $\sum_{j \in I} c_{j}\alpha_{j}^{\vee} \in Q^{\vee}$ to 
$\sum_{j \in \J} c_{j}\alpha_{j}^{\vee} \in \QJv$. 

