\subsection{The quantum Bruhat graph.}
\label{subsec:QBG}

\begin{dfn} \label{dfn:QBG} % [{\cite[Definition~6.1]{BFP}}]
Let $\J$ be a subset of $I$. 
The (parabolic) \emph{quantum Bruhat graph} of $\WJ$, 
denoted by $\QBG(\WJ)$, is the ($\DJp$)-labeled
directed graph whose vertices are the elements of $\WJ$ and 
whose edges are of the following form: 
$x \edge{\alpha} y$, with $x, y \in \WJ$ and $\alpha \in \DJp$, 
such that $y = \mcr{x s_{\alpha}}^{\J}$ and either of the following holds: 
(B) $\ell(y) = \ell (x) + 1$; 
(Q) $\ell(y) = \ell (x) + 1 - 2 \pair{\rho-\rho_{\J}}{\alpha^{\vee}}$.
An edge satisfying (B) (resp., (Q)) is called a \emph{Bruhat edge} (resp., \emph{quantum edge}). 
When $\J=\emptyset$ (note that $W^{\emptyset}=W$, $\rho_{\emptyset}=0$, and $\mcr{x}^{\emptyset}=x$ for all $x \in W$), 
we write $\QBG(W)$ for $\QBG(W^{\emptyset})$.
\end{dfn}

For an edge $x \edge{\alpha} y$ in $\QBG(W)$, 
we sometimes write $x \Be{\alpha} y$ (resp., $x \Qe{\alpha} y$) 
to indicate that the edge is a Bruhat (resp., quantum) edge. 

Let 
%
\begin{equation} \label{eq:dp}
\bp: y_{0} \edge{\beta_{1}} y_{1} \edge{\beta_{2}} \cdots \edge{\beta_{r}} y_{r}
\end{equation}
%
be a directed path in the quantum Bruhat graph $\QBG(W)$. 
We set $\ed(\bp):=y_{r}$ and $\ell(\bp)=r$. 
A directed path $\bp$ is called the trivial (resp., non-trivial) one 
if $\ell(\bp)=0$ (resp., $\ell(\bp) > 0$). 
When $\bp$ is non-trivial, 
we call $\IL{\bp}:=\beta_{1}$ and $\FL{\bp}=\beta_{r}$ 
the initial label and the final label of $\bp$, respectively. 
For $\bp$ of the form \eqref{eq:dp}, we set
%
\begin{equation*}
\qwt(\bp):=\sum_{ \begin{subarray}{c} 1 \le k \le r \\ 
\text{$y_{k-1} \edge{\beta_k} y_{k}$ is} \\
\text{a quantum edge} \end{subarray} } \beta_{k}^{\vee} \in Q^{\vee,+}. 
\end{equation*}
%
Let $v,w \in W$, and let $\bp$ be a shortest directed path from $v$ to $w$ in $\QBG(W)$. 
We set $\qwt(v \Rightarrow w):=\qwt(\bp)$; we know from \cite[Proposition~8.1]{LNSSS1} that 
$\qwt(v \Rightarrow w)$ does not depend on the choice of a shortest directed path $\bp$. 
%
%%%%%%%%%%%%%%%%
%%% prop:qwt %%%
%%%%%%%%%%%%%%%%
%
\begin{prop}[{\cite[Proposition~8.1]{LNSSS1}}] \label{prop:qwt}
Let $v,w \in W$, and let $\bq$ be a directed path (not necessarily, shortest) 
from $v$ to $w$ in $\QBG(W)$. Then, we have $\qwt(v \Rightarrow w) \le \qwt(\bq)$.
\end{prop}

Let $\lhd$ be a reflection (convex) order on $\Delta^{+}$; 
see, e.g., \cite[Section 2.2]{KNS}.
A directed path $\bp$ of the form \eqref{eq:dp} is said to be label-increasing 
(resp., label-decreasing) with respect to $\lhd$ 
if $\beta_{1} \lhd \cdots \lhd \beta_{r}$ (resp., $\beta_{1} \rhd \cdots \rhd \beta_{r}$). 

\begin{thm}[{see, for example, \cite[Theorem~7.4]{LNSSS1}}]
Let $v,w \in W$.
%
\begin{enu}
\item There exists a unique label-increasing directed path from $v$ to $w$ 
in the quantum Bruhat graph $\QBG(W)$. Moreover, it is a shortest directed path 
from $v$ to $w$. 

\item There exists a unique label-decreasing directed path from $v$ to $w$ 
in the quantum Bruhat graph $\QBG(W)$. Moreover, it is a shortest directed path 
from $v$ to $w$. 
\end{enu}
%
\end{thm}

For $v,w \in W$, we denote by $\dec(v \Rightarrow w)$ the (unique) label-decreasing 
directed path from $v$ to $w$; note that $\qwt(v \Rightarrow w) = \qwt(\dec(v \Rightarrow w))$. 
%
%%%%%%%%%%%%%%%%%%%
%%% dfn:dtilted %%%
%%%%%%%%%%%%%%%%%%%
%
\begin{dfn}[dual tilted Bruhat order] \label{dfn:dtilted}
For each $v \in W$, we define the dual $v$-tilted Bruhat order 
$\dtb{v}$ on $W$ as follows:
for $w_{1},w_{2} \in W$, 
%
%%%%%%%%%%%%%%%%%%
%%% eq:dtilted %%%
%%%%%%%%%%%%%%%%%%
%
\begin{equation} \label{eq:dtilted}
w_{1} \dtb{v} w_{2} \iff \ell(w_{1} \Rightarrow v) = 
 \ell(w_{1} \Rightarrow w_{2}) + \ell(w_{2} \Rightarrow v).
\end{equation}
%
Namely, $w_{1} \dtb{v} w_{2}$ if and only if 
there exists a shortest directed path in $\QBG(W)$ 
from $w_{1}$ to $v$ passing through $w_{2}$; 
or equivalently, if and only if the concatenation of a shortest directed path 
from $w_{1}$ to $w_{2}$ and one from $w_{2}$ to $v$ 
is one from $w_{1}$ to $v$. 
\end{dfn}
%
%%%%%%%%%%%%%%%%%%
%%% prop:tbmax %%%
%%%%%%%%%%%%%%%%%%
%
\begin{prop}[{\cite[Proposition~2.25]{NOS}}] \label{prop:tbmax}
Let $v \in W$, and let $\J$ be a subset of $I$. 
Then each coset $u\WJ$ for $u \in W$ has a unique maximal element
with respect to $\dtb{v}$\,{\rm;} 
we denote it by $\tbmax{u}{\J}{v}$.
\end{prop}

Let $\J$ be a subset of $I$. 
As \cite[(2.4)]{KNS}, let $\lhd$ be an arbitrary reflection 
order on $\Delta^{+}$ satisfying the condition that 
%
%%%%%%%%%%%%%
%%% eq:ro %%%
%%%%%%%%%%%%%
%
\begin{equation} \label{eq:ro}
\beta \lhd \gamma \quad 
\text{for all $\beta \in \DJs$ and $\gamma \in \DJp$}. 
\end{equation}
%
%
%%%%%%%%%%%%%%%%%
%%% lem:tbmax %%%
%%%%%%%%%%%%%%%%%
%
\begin{lem}[{\cite[Lemma~2.15]{KNS}}] \label{lem:tbmax}
Let $\J$ be a subset of $I$, and let $\lhd$ be a reflection order on $\Delta^{+}$ 
satisfying condition \eqref{eq:ro}. 
Let $v,w \in W$, and $w' \in w\WJs$. Then, 
$w' = \tbmax{w}{\J}{v}$ if and only if 
all the labels in the label-increasing (shortest) directed path 
from $w'$ to $v$ in $\QBG(W)$ are contained in $\DJp$. 
\end{lem}

For $w \in W$, let $\bQBG{w}$ denote 
the set of all label-increasing directed paths $\bp$ 
in $\QBG(W)$ starting at $w$, and 
satisfying the condition that 
all the labels of the edges in $\bp$ are contained in $\DJp$: 
%
%%%%%%%%%%%%%%%
%%% eq:bQBG %%%
%%%%%%%%%%%%%%%
%
\begin{equation} \label{eq:bQBG}
\bp: 
\underbrace{w = z_{0} \edge{\beta_{1}} z_{1} \edge{\beta_{2}} \cdots \edge{\beta_{s}} z_{s},}_{
\text{directed path in $\QBG(W)$}} \quad \text{where} \quad 
%
\begin{cases}
s \ge 0, \\[1mm]
\text{$\beta_{k} \in \DJp$, $1 \le k \le s$}, \\[1mm]
\beta_{1} \lhd \beta_{2} \lhd \cdots \lhd \beta_{s}. 
\end{cases}
%
\end{equation}
%
Let $\bt_{w}$ denote the trivial directed path of length $0$ 
starting at $w$ and ending at $w$; 
note that $\bt_{w} \in \bQBG{w}$. 

