\subsection{Quantum Lakshmibai-Seshadri paths.}
\label{subsec:QLS}

Let $\lambda \in \Lambda^{+}:=\sum_{j \in I} \BZ_{\ge 0}\vpi_{j}$ 
be a dominant (integral) weight, and take 
%
%%%%%%%%%%%%
%%% eq:J %%%
%%%%%%%%%%%%
%
\begin{equation} \label{eq:J}
\J=\J_{\lambda}:= 
\bigl\{ j \in I \mid \pair{\lambda}{\alpha_{j}^{\vee}}=0 \bigr\}.
\end{equation}
%
%%%%%%%%%%%%%%%
%%% dfn:QBa %%%
%%%%%%%%%%%%%%%
%
\begin{dfn} \label{dfn:QBa}
For a rational number $0 \le a < 1$, 
we define $\QBG_{a\lambda}(\WJ)$ to be the subgraph of $\QBG(\WJ)$ 
with the same vertex set but having only those directed edges of 
the form $x \edge{\alpha} y$ for which 
$a\pair{\lambda}{\alpha^{\vee}} \in \BZ$ holds. 
Note that if $a = 0$, then $\QBG_{a\vpi_{i}}(\WJ) = \QBG(\WJ)$. 
\end{dfn}
%
%%%%%%%%%%%%%%%
%%% dfn:QLS %%%
%%%%%%%%%%%%%%%
%
\begin{dfn}[{\cite[Section~3.2]{LNSSS2}}] \label{dfn:QLS}
A \emph{quantum Lakshmibai-Seshadri path} (QLS path for short) 
of shape $\lambda$ is a pair 
%
%%%%%%%%%%%%%%
%%% eq:QLS %%%
%%%%%%%%%%%%%%
%
\begin{equation} \label{eq:QLS}
\eta = (\bv \,;\, \ba) = 
(v_{1},\,\dots,\,v_{s} \,;\, a_{0},\,a_{1},\,\dots,\,a_{s}), \quad s \ge 1, 
\end{equation}
%
of a sequence $v_{1},\,\dots,\,v_{s}$ 
of elements in $\WJ$, with $v_{k} \ne v_{k+1}$ 
for any $1 \le k \le s-1$, and an increasing sequence 
$0 = a_0 < a_1 < \cdots  < a_s =1$ of rational numbers 
satisfying the condition that there exists a directed path 
in $\QBG_{a_{k}\lambda}(\WJ)$ from $v_{k+1}$ to  $v_{k}$ 
for each $k = 1,\,2,\,\dots,\,s-1$. 
\end{dfn}

Let $\QLS(\lambda)$ denote 
the set of all QLS paths of shape $\lambda$. 
For $\eta \in \QLS(\lambda)$ of the form \eqref{eq:QLS}, 
we set $\iota(\eta):=v_{1} \in \WJ$, $\kappa(\eta):=v_{s} \in \WJ$, and 
%
\begin{equation} \label{eq:wt}
\wt (\eta) := \sum_{k=1}^{s} (a_{k}-a_{k-1}) v_{k}\lambda \in P. 
\end{equation}
%
Also, following \cite[(3.26) and (3.27)]{NOS}, 
for $\eta \in \QLS(\lambda)$ of the form \eqref{eq:QLS} and $v \in W$, 
we define $\kap{\eta}{v} \in W$ by the following recursive formula: 
%
%%%%%%%%%%%%%%
%%% eq:haw %%%
%%%%%%%%%%%%%%
%
\begin{equation} \label{eq:haw}
%
\begin{cases}
\ha{v}_{0}:=v, & \\[2mm]
\ha{v}_{k}:=\tbmax{v_{k}}{\J}{\ha{v}_{k-1}} & \text{for $1 \le k \le s$}, \\[2mm]
\kap{\eta}{v}:=\ha{v}_{s}, 
\end{cases}
%
\end{equation}
%
and then we set
%
%%%%%%%%%%%%%%%%
%%% eq:zetav %%%
%%%%%%%%%%%%%%%%
%
\begin{equation} \label{eq:zetav}
\zeta(\eta,v):= 
\sum_{k=0}^{s-1} \wt (\ha{v}_{k+1} \Rightarrow \ha{v}_{k}). 
\end{equation}

Now, let $i \in I$, and consider the case $\lambda=\vpi_{i}$. 
We fix $N = N_{i} \in \BZ_{\ge 1}$ satisfying the following condition: 
%
\begin{equation} \label{eq:cN}
N/\pair{\vpi_{i}}{\alpha^{\vee}} \in \BZ \quad 
\text{for all $\alpha \in \Delta^{+}$ such that $\pair{\vpi_{i}}{\alpha^{\vee}} \ne 0$}.
\end{equation}
%
By the definition of QLS paths of shape $\vpi_{i}$, 
we see that if 
%
\begin{equation} \label{eq:QLS1}
\eta = (v_{1},\,\dots,\,v_{s} \,;\, 
a_{0},\,a_{1},\,\dots,\,a_{s}) \in \QLS(\vpi_{i}),
\end{equation}
%
then $Na_{k} \in \BZ$ for all $0 \le k \le s$; 
we write $\eta$ as:
%
\begin{equation} \label{eq:QLS2}
\eta = ( \underbrace{ v_{1},\dots,v_{1} }_{N(a_{1}-a_{0}) \text{ times}}, 
\underbrace{ v_{2},\dots,v_{2} }_{N(a_{2}-a_{1}) \text{ times}},\,\dots,\,
\underbrace{ v_{s},\dots,v_{s} }_{N(a_{s}-a_{s-1}) \text{ times}}). 
\end{equation}
%
Let $\eta = (w_{1}, w_{2}, \dots, w_{N}) \in \QLS(\vpi_{i})$ 
(allowing that $w_{k-1}=w_{k}$ for some $2 \le k \le N$), and $v \in W$. 
We define $\ha{w}_{0}:=v,\,\ha{w}_{1},\,\ha{w}_{2},\,\dots,\ha{w}_{N}$ by the 
same recursive formula as \eqref{eq:haw}; we see that 
$\ha{w}_{N}=\kappa(\eta,v)$. 
%
Let $w \in W$. If $\ha{w}_{N} = \kappa(\eta,v) = w$, 
then we deduce from Lemma~\ref{lem:tbmax} that
for each $1 \le k \le N$, there exists a (unique) $\bp_{k} \in \bQBG{\ha{w}_{k}}$ 
such that $\ed(\bp_{k}) = \ha{w}_{k-1}$; note that if $w_{k-1}=w_{k}$, 
then $\ha{w}_{k-1}=\ha{w}_{k}$, and $\bp_{k}$ is 
the trivial directed path $\bt_{\ha{w}_{k}}$. 
%
%%%%%%%%%%%%%%%
%%% lem:1/2 %%%
%%%%%%%%%%%%%%%
%
\begin{lem} \label{lem:1/2}
Keep the notation and setting above. 
For $1 \le k \le N$, the directed path $\bp_{k}$ is 
a directed path in $\QBG_{((k-1)/N)\vpi_{i}}(W)$. 
\end{lem}

\begin{proof}
Let $1 \le k \le N$. 
By the definition of QLS paths of shape $\vpi_{i}$, 
there exists a directed path (possibly trivial) from $w_{k}$ to $w_{k-1}$ in 
$\QBG_{((k-1)/N)\vpi_{i}}(\WJ)$. By the same argument as that for \cite[Lemma~6.6\,(2)]{LNSSS2}, 
we deduce that there exists a directed path from $\ha{w}_{k}$ to $\ha{w}_{k-1}$ 
in $\QBG_{((k-1)/N)\vpi_{i}}(W)$. Then, by \cite[Lemma~6.7]{LNSSS2}, 
all shortest directed paths from $\ha{w}_{k}$ to $\ha{w}_{k-1}$ 
in $\QBG(W)$ are directed paths in $\QBG_{((k-1)/N)\vpi_{i}}(W)$. 
In particular, $\bp_{k}$ is a directed path in $\QBG_{((k-1)/N)\vpi_{i}}(W)$.
This proves the lemma. 
\end{proof}

Now, we set 
%
\begin{equation}
\bQLS{w}: = 
\left\{ \bp=(\bp_{N},\dots,\bp_{2},\bp_{1}) \ \Biggm| \ 
\begin{array}{l}
\text{for all $1 \le k \le N$, $\bp_{k} \in \bQBG{\ed(\bp_{k+1})}$, and}  \\[2mm]
\text{$\bp_{k}$ is a directed path in $\QBG_{((k-1)/N)\vpi_{i}}(W)$}
\end{array} \right\}, 
\end{equation}
%
where $\bp_{N+1}$ is considered to be the trivial directed path $\bt_{w}$, 
and hence $\ed(\bp_{N+1})=w$. 
Let $\bp=(\bp_{N},\dots,\bp_{2},\bp_{1}) \in \bQLS{w}$, and set 
%
%%%%%%%%%%%%%%%
%%% eq:etap %%%
%%%%%%%%%%%%%%%
%
\begin{equation} \label{eq:etap}
\eta_{\bp}:=(\mcr{\ed(\bp_{2})}^{\J},\dots,\mcr{\ed(\bp_{N})}^{\J},\mcr{\ed(\bp_{N+1})}^{\J}=\mcr{w}^{\J}), 
\end{equation}
%
where $\J= J_{\varpi_i} = I \setminus \{i\}$. 
By the argument above, we see that 
$\eta_{\bp} \in \QLS(\vpi_{i})$, $\kappa(\eta_{\bp},v) = w$, and $\zeta(\eta_{\bp},v) = 
\sum_{k = 1}^{N} \qwt(\bp_{k})$, with $v = \ed(\bp_{1})$. 
Moreover, we deduce that the map $\bp \mapsto \bigl( \eta_{\bp}, \ed(\bp_{1}) \bigr)$
is a bijection from $\bQLS{w}$ onto 
the set $\bigl\{(\eta,v) \in \QLS(\vpi_{i}) \times W \mid \kappa(\eta,v) =w \bigr\}$.
For $\bp=(\bp_{N},\dots,\bp_{2},\bp_{1}) \in \bQLS{w}$, we set
%
\begin{equation}
%
\begin{split}
& \ell(\bp):=\sum_{k = 1}^{N} \ell(\bp_{k}), \qquad
  \ed(\bp):=\ed(\bp_{1}), \\
& \qwt(\bp):=\sum_{k = 1}^{N} \qwt(\bp_{k}), \qquad
  \qwt_{2}(\bp):=\sum_{k = 2}^{N} \qwt(\bp_{k}) = \qwt(\bp)-\qwt(\bp_{1}). 
\end{split}
%
\end{equation}
%
%%%%%%%%%%%%%%%
%%% ex:G2-1 %%%
%%%%%%%%%%%%%%%
%
