%     START SUBSECTION 0302    %
%==============================%
%
\subsection{Statements of the main results.}
\label{subsec:main}

The (small) $T$-equivariant quantum $K$-theory ring $QK_T(X)$ of $X = G/B$, 
defined by Givental \cite{Giv} and Lee \cite{Lee}, 
is (as a module over $R(T)\bra{\sQ}$) $K_T(X) \otimes_{R(T)} R(T)\bra{\sQ}$, 
where $R(T)\bra{\sQ}$ is the ring of formal power series 
with coefficients in $R(T)$ in the (Novikov) variables 
$\sQ_j := \sQ^{\alpha_j^{\vee}}$, $j \in I$. 
The quantum $K$-metric $\Kmet{\cdot}{\cdot}$ on $QK_T(X)$ is 
the $R(T)\bra{\sQ}$-bilinear (perfect) pairing 
$QK_T(X) \times QK_T(X) \to R(T)\bra{\sQ}$ defined as: 
%
\begin{equation*}
\Kmet{\gamma_1}{\gamma_2} = 
\sum_{d \in Q^{\vee,+}} \sQ^d \langle \gamma_1, \gamma_2 \rangle_d
\end{equation*}
%
for $\gamma_1, \gamma_2 \in K_T(X)$, 
where $\sQ^d := \prod_{j \in I} \sQ_j^{d_j}$ 
for $d = \sum_{j \in I} d_j \alpha_j^{\vee} \in Q^{\vee,+}$. 
The quantum product $\star$ in $QK_T(X)$ is determined by:
%
\begin{equation}\label{eq:qmulti}
\Kmet{\gamma_1 \star \gamma_2}{\gamma_3} = 
\sum_{d \in Q^{\vee,+}} \sQ^d \langle \gamma_1, \gamma_2, \gamma_3 \rangle_d
\end{equation}
%
for $\gamma_1, \gamma_2, \gamma_3 \in K_T(X)$; 
note that the quantum product is $R(T)\bra{\sQ}$-bilinear, 
commutative, and associative, with $1 \in K_T(X)$ the multiplicative identity; 
also, it is known that $\Kmet{\gamma_1 \star \gamma_2}{\gamma_3} = 
\Kmet{\gamma_1}{\gamma_2 \star \gamma_3}$ 
for classes $\gamma_1, \gamma_2, \gamma_3 \in K_T(X)$. 

Now, the structure constants with respect to 
the (opposite) Schubert classes $\CO^w$, $w \in W$, 
for the quantum multiplication in $QK_T(X)$ are defined by: 
%
\begin{equation}\label{eq:qmulticoeff}
\CO^{v} \star \CO^w = 
\sum_{\substack{z \in W \\ d \in Q^{\vee,+}}} N_{v,w}^{z,d} \sQ^d \CO^z,
\end{equation}
%
with $N_{v,w}^{z,d} \in R(T)$ for $v, w, z \in W$ and $d \in Q^{\vee,+}$. 
Hence, from the definition \eqref{eq:qmulti} of the quantum product $\star$, 
we deduce the following equation:
%
\begin{equation}\label{eq:KGWinv}
\sum_{d \in Q^{\vee,+}} \sQ^d \thp{s_i}{w}{x}_d = 
\Kmet{\CO^{s_i} \star \CO^w}{\CO_x}
\end{equation}
%
for $i \in I$, $u, v \in W$. 

Let us take and fix  $i \in I$, $w \in W$ arbitrarily; 
in the following, we take 
$\J= J_{\varpi_i} = I \setminus \{i\}$ (see \eqref{eq:J}). 
For $z \in W$, we set 
\begin{equation}
a_z(\sQ) := \sum_{d \in Q^{\vee,+}} N_{s_i,w}^{z,d} \sQ^d, 
\end{equation}
which turns out to be an element of $R(T)[\sQ] \subset R(T)\bra{\sQ}$ 
by the Chevalley formula (see Theorem~\ref{thm:NOS} below). 
Then, we have in $QK_T(X)$, 
%
\begin{equation}
\CO^{s_i} \star \CO^{w} = 
\sum_{z \in W} a_{z}(\sQ) \CO^{z}; 
\end{equation}
%
if we set $c_{z}:=a_{z}(0) \in R(T)$, then we have in $K_T(X)$, 
\begin{equation}
\CO^{s_i} \cdot \CO^w = 
\sum_{z \in W} c_z \CO^z.
\end{equation}
Fix $x \in W$. It follows from equation~\eqref{eq:KGWinv} that 
%
\begin{equation} \label{eq:main1}
\sum_{d \in Q^{\vee,+}}
\sQ^{d} \thp{s_{i}}{w}{x}_{d} = 
\sum_{z \in W} a_{z}(\sQ) \sum_{\xi \in Q^{\vee,+}} \sQ^{\xi} \twp{z}{x}_{\xi}.  
\end{equation}
%
Here, the 2-point KGW invariants $\langle \CO^z, \CO_x \rangle_{\xi}$ 
for $z \in W$, $\xi \in Q^{\vee,+}$ can be explicitly described in terms of 
the quantum Bruhat graph $\QBG(W)$ on the Weyl group $W$. 
To be more precise, for $z, x \in W$, let $\qwt(z \Rightarrow x)$ 
denote the quantum weight, given as the quantum weight $\qwt(\bp)$ 
of a shortest directed path $\bp$ from $z$ to $x$ in $\QBG(W)$ 
(not depending on the choice of $\bp$)
Indeed, we know from \cite[Lemma~4 and Proposition~6]{BCLM} 
that for $z \in W$ and $\xi \in Q^{\vee,+}$, 
%
%%%%%%%%%%%%%%%%%%
%%% eq:2pt-qwt %%%
%%%%%%%%%%%%%%%%%%
%
\begin{equation} \label{eq:2pt-qwt}
\twp{z}{x}_{\xi} = 
\begin{cases}
1 & \text{if $\xi \ge \qwt(z \Rightarrow x)$}, \\
0 & \text{otherwise}.
\end{cases}
\end{equation}
%
The following is the first main result in this paper. 
%
%%%%%%%%%%%%%%%
%%% thm:qk1 %%%
%%%%%%%%%%%%%%%
%
\begin{thm} \label{thm:qk1}
Let $i \in I$ and $w,x \in W$. 
Let $d=\sum_{j \in I} d_{j} \alpha_{j}^{\vee} \in Q^{\vee,+}$ 
be such that $d_{i}=0$. Then, the following holds: 
%
\begin{equation} \label{eq:qk1a}
\thp{s_{i}}{w}{x}_{d} = 
\sum_{z \in W} c_{z} \twp{z}{x}_{d} =
\langle \CO^{s_i} \cdot \CO^w, \CO_x \rangle_{d}. 
\end{equation}
%
\end{thm}

Now, for $d=\sum_{j \in I} d_{j} \alpha_{j}^{\vee} \in Q^{\vee,+}$, we set 
%
\begin{equation} \label{eq:bQLSwxd}
\bQLS{w,x,d}:=
\bigl\{ \bp=(\bp_{N},\dots,\bp_{2},\bp_{1}) \in \bQLS{w} \mid 
\qwt (\ed(\bp) \Rightarrow x) \le d - \qwt(\bp) \bigr\}; 
\end{equation}
%
remark that $\qwt (\ed(\bp) \Rightarrow x) \le d - \qwt(\bp)$ implies 
$\qwt(\bp) \le d$ since $\qwt (\ed(\bp) \Rightarrow x) \ge 0$. 
Also, we define
%
%%%%%%%%%%%%%
%%% eq:bR %%%
%%%%%%%%%%%%%
%
\begin{equation} \label{eq:bR}
\bR{w,x,d}:=
\left\{ \bp=(\bp_{N},\dots,\bp_{2},\bp_{1}) \in \bQLS{w,x,d} \ \Biggm| \ 
\begin{array}{c}
\pair{\vpi_{i}}{d - \qwt_{2}(\bp)} = 0 \\[1.5mm]
\ell(\bp_{1})=0, \, \ed(\bp) \in x\WJs
\end{array}
\right\}. 
\end{equation}
%
The following is the second main result in this paper. 
%
%%%%%%%%%%%%%%%
%%% thm:qk2 %%%
%%%%%%%%%%%%%%%
%
\begin{thm} \label{thm:qk2}
Let $i \in I$, $w,x \in W$, and 
$d=\sum_{j \in I} d_{j} \alpha_{j}^{\vee} \in Q^{\vee,+}$. 
Then, the following holds: 
%
\begin{equation} \label{eq:qk2a}
\thp{s_{i}}{w}{x}_{d} =  
 \twp{w}{x}_{d} - 
 \sum_{ \bp \in \bR{w,x,d} }
(-1)^{\ell(\bp)}\be^{-\vpi_{i}+\wt(\eta_{\bp})}.
\end{equation}
%
\end{thm}
%
%%%%%%%%%%%%%%%
%%% ex:G2-2 %%%
%%%%%%%%%%%%%%%
%
\begin{ex} \label{ex:G2-2}
As in Example~\ref{ex:G2-1}, 
we assume that $\Fg$ is of type $G_{2}$, and $i = 2$; 
recall that $\alpha_{2}$ is the long simple root, and that $N=N_{2}=6$. 
Let $w:=s_{2}s_{1}s_{2}s_{1}s_{2}$, and  
$d := d_{1}\alpha_{1}^{\vee}+2\alpha_{2}^{\vee} \in Q^{\vee,+}$ 
with $d_{1} \in \BZ_{> 0}$. 
By using \eqref{eq:qk2a}, we compute $\thp{w}{s_2}{x}_{d}$ for $x \in W$ as follows. 
By Figure~\ref{fig:G2}, we see that 
for all $x \in W$, $\qwt(s_{2}s_{1}s_{2}s_{1}s_{2} \Rightarrow x) \le d$, and hence 
$\twp{s_{2}s_{1}s_{2}s_{1}s_{2}}{x}_{d} = 1$. 
Let $\bp=(\bp_{6},\bp_{5},\dots,\bp_{2},\bp_{1}) \in \bQLS{s_{2}s_{1}s_{2}s_{1}s_{2}}$. 
Then, we deduce that $(\bp_{6},\bp_{5},\dots,\bp_{2})$ is 
%
\begin{equation*}
\text{either} \quad (\bt_{w},\dots,\bt_{w}) \quad \text{or} \quad 
(\bt_{w},\bt_{w},\bq,\bt_{e},\bt_{e}),
\end{equation*}
%
where $\bq:w \Qe{3\alpha_{1}+2\alpha_{2}} e$. 
% note that $(3/6) \pair{\vpi_{2}}{(3\alpha_{1}+2\alpha_{2})^{\vee}} = 1 \in \BZ$. 
If $\bp \in \bR{w,x,d}$, then 
$(\bp_{6},\bp_{5},\dots,\bp_{2}) = 
(\bt_{w},\bt_{w},\bq,\bt_{e},\bt_{e})$ and $\bp_{1} = \bt_{e}$. 
Note that $\WJs=W_{I \setminus \{2\}} = \{ e,\,s_{1} \}$. Thus, 
we find that 
%
\begin{equation*}
\bR{w,x,d} = 
 \begin{cases}
 \{ \underbrace{ (\bt_{w},\bt_{w},\bq,\bt_{e},\bt_{e},\bt_{e}) }_{
    \text{$= \bp'$ in Example~\ref{ex:G2-1}} } \} & \text{if $x = e$ or $s_{1}$}, \\[2mm]
 \emptyset & \text{otherwise}. 
 \end{cases}
\end{equation*}
%
Since $\wt(\eta_{\bp'}) = \vpi_{2}-(3\alpha_{1}+2\alpha_{2}) = 0$, 
we conclude that 
%
\begin{equation} \label{eq:G2a}
\thp{s_{2}}{w}{x}_{d} =  
 \begin{cases}
 1+\be^{-\vpi_{2}} & \text{if $x = e$ or $s_{1}$}, \\
 1 & \text{otherwise}.
 \end{cases}
\end{equation}
%
\end{ex}

We can rewrite the second sum on the right-hand side of equation~\eqref{eq:qk2a} 
in terms of QLS paths of shape $\vpi_i$ as follows; 
recall that $J = J_{\varpi_i} = I \setminus \{ i \}$. 
%
%%%%%%%%%%%%%%%%%%%
%%% prop:qk2-QLS %%%
%%%%%%%%%%%%%%%%%%%
%
\begin{prop} \label{prop:qk2-QLS}
Keep the notation and setting of Theorem~\ref{thm:qk2}. 
We have 
%
%%%%%%%%%%%%%%%
%%% eq:RQLS %%%
%%%%%%%%%%%%%%%
%
\begin{equation} \label{eq:RQLS}
 \sum_{ \bp \in \bR{w,x,d} }
(-1)^{\ell(\bp)}\be^{-\vpi_{i}+\wt(\eta_{\bp})} = 
\sum_{v \in x\WJs} \sum_{
 \begin{subarray}{c}
 \eta \in \QLS(\vpi_{i}) \\[1mm]
 \iota(\eta) \in x\WJs,\,\kappa(\eta,v)=w \\[1mm]
 \pair{\vpi_{i}}{d-\zeta(\eta,v)} = 0 \\[1mm]
 \qwt(v \Rightarrow x) \le d-\zeta(\eta,v)
 \end{subarray} } (-1)^{\ell(v)-\ell(w)} \be^{-\vpi_{i}+\wt(\eta)}. 
\end{equation}
%
\end{prop}

\begin{proof}
Recall from Section~\ref{subsec:QLS} 
the bijection $\bp \mapsto \bigl( \eta_{\bp}, \ed(\bp) \bigr)$ 
from $\bQLS{w}$ onto 
$\bigl\{(\eta,v) \in \QLS(\vpi_{i}) \times W \mid \kappa(\eta,v) =w \bigr\}$; 
notice that $(-1)^{\ell(\bp)} = (-1)^{\ell(\ed(\bp))-\ell(w)}$. 
Hence it suffices to show that under the bijection above, 
the set $\bR{w,x,d}$ is mapped to the set
%
\begin{equation} \label{eq:RQLSa}
\left\{ 
(\eta,v) \in \QLS(\vpi_{i}) \times W \ \Biggm| \ 
\begin{array}{l}
v \in x\WJs,\, \iota(\eta) \in x\WJs,\,\kappa(\eta,v)=w \\[1mm]
\pair{\vpi_{i}}{d-\zeta(\eta,v)} = 0 \\[1mm]
\qwt(v \Rightarrow x) \le d-\zeta(\eta,v)
\end{array}
\right\}. 
\end{equation}
%
Let $\bp=(\bp_{N},\dots,\bp_{2},\bp_{1}) \in \bR{w,x,d}$. 
We know that $\kappa(\eta_{\bp},v) = w$ and $\zeta(\eta_{\bp},v) = \qwt(\bp)$ 
with $v = \ed(\bp) \in x\WJs$. Since $\ell(\bp_{1})=0$, it follows that 
$\qwt(\bp) = \qwt_{2}(\bp)$ and $\ed(\bp) = \ed(\bp_{2})$. 
Hence, $\pair{\vpi_{i}}{d - \qwt_{2}(\bp)} = 0$ and 
$\qwt (\ed(\bp) \Rightarrow x) \le d - \qwt(\bp)$ imply that 
$\pair{\vpi_{i}}{d-\zeta(\eta_{\bp},v)} = 0$ and 
$\qwt(v \Rightarrow x) \le d-\zeta(\eta_{\bp},v)$, respectively. 
Also, we deduce that modulo $\WJs$, $\iota(\eta_{\bp}) \equiv \ed(\bp_{2}) = 
\ed(\bp) = v \equiv x$. 
% the second equality follows from 
% the assumption that $\ell(\bp_{1})=0$. 
Thus, $\bigl( \eta_{\bp}, \ed(\bp) \bigr) \in \QLS(\vpi_{i}) \times W$ 
is contained in the set \eqref{eq:RQLSa}. 

Let $(\eta,v) \in \QLS(\vpi_{i}) \times W$ be an element 
in the set \eqref{eq:RQLSa}, and 
$\bp = (\bp_{N},\dots,\bp_{2},\bp_{1})$ a unique element of 
$\bQBG{w}$ such that $\bigl( \eta_{\bp}, \ed(\bp) \bigr) = (\eta,v)$; 
we will show that $\bp \in \bR{w,x,d}$. Notice that 
$\ed(\bp) = v \in x\WJs$. Also, since $\ed(\bp_{2}) \equiv 
\iota(\eta_{\bp}) = \iota(\eta) \equiv x$ modulo $\WJs$, it follows that 
$\ed(\bp_{2}) \in x\WJs$. Hence there exists a shortest directed path 
from $\ed(\bp_{2}) \in x\WJs$ to $\ed(\bp_{1}) \in x\WJs$ in $\QBG(W)$
whose labels are all contained in $\DJs$. Since $\bp_{1}$ is a label-increasing 
(shortest) directed path from $\ed(\bp_{2})$ to $\ed(\bp_{1})$, 
it is lexicographically minimal among all shortest paths from
$\ed(\bp_{2})$ to $\ed(\bp_{1})$; see \cite[Theorem~7.3]{LNSSS1}. 
By \eqref{eq:ro}, we deduce that $\ell(\bp_{1})= 0$. Therefore, we see that 
$\qwt(\bp) = \qwt_{2}(\bp) = \zeta(\eta_{\bp},v) = \zeta(\eta,v)$, 
and hence $\qwt(\ed(\bp) \Rightarrow x) = \qwt(v \Rightarrow x) \le d-\zeta(\eta,v)
=d-\qwt(\bp)$. Also, we see that $\pair{\vpi_{i}}{d - \qwt_{2}(\bp)} = 
\pair{\vpi_{i}}{d - \zeta(\eta,v)} = 0$. Thus, we obtain $\bp \in \bR{w,x,d}$, as desired. 
This proves the proposition. 
\end{proof}

