\section{Proofs of Theorems~\ref{thm:qk1} and \ref{thm:qk2}.}
\label{sec:prf-main}
%
%==============================%
%     START SUBSECTION 0401    %
%==============================%
%
\subsection{The Chevalley formula.}
\label{subsec:Monk}

Fix $i \in I$ arbitrarily; recall that 
$\J = \J_{\vpi_i} = I \setminus \{i\}$. 
Let $\lhd$ be a reflection order satisfying \eqref{eq:ro}, with $\J=I \setminus \{i\}$. 
%
%%%%%%%%%%%%%%%
%%% thm:NOS %%%
%%%%%%%%%%%%%%%
%
\begin{thm}[{\cite[(1.6)]{NOS}; see also \cite[Theorem 49]{LNS}}] \label{thm:NOS}
Let $w \in W$. In $QK_{T}(G/B)$, we have
%
\begin{equation} \label{eq:NOS}
\CO^{s_{i}} \star \CO^{w} = 
\CO^{w} + 
\sum_{v \in W}
\sum_{
  \begin{subarray}{c}
   \eta \in \QLS(\vpi_{i}) \\
   \kappa(\eta,v) = w
  \end{subarray}}
  (-1)^{\ell(v) - \ell(w) + 1} \be^{-\vpi_{i}+\wt(\eta)}
  \sQ^{\zeta(\eta, v)} \CO^{v}. 
\end{equation}
%
\end{thm}

By using the bijection $\bQLS{w} \rightarrow 
\bigl\{(\eta,v) \in \QLS(\vpi_{i}) \times W \mid \kappa(\eta,v) =w \bigr\}$, 
$\bp \mapsto \bigl( \eta_{\bp}, \ed(\bp_{1}) \bigr)$, 
given in Section~\ref{subsec:QLS}, we can rewrite equation~\eqref{eq:NOS} 
as follows. 
%
%%%%%%%%%%%%%%%%
%%% cor:NOS2 %%%
%%%%%%%%%%%%%%%%
%
\begin{cor} \label{cor:NOS2}
Let $i \in I$ and $w \in W$. In $QK_{T}(G/B)$, we have
%
\begin{equation} \label{eq:NOS2}
\CO^{s_{i}} \star \CO^{w} = 
\CO^{w} -
\sum_{\bp \in \bQLS{w}} 
  (-1)^{\ell(\bp)}  \be^{-\vpi_{i}+\wt(\eta_{\bp})}
  \sQ^{\qwt(\bp)} \CO^{\ed(\bp)}. 
\end{equation}
%
\end{cor}

%==============================%
%     START SUBSECTION 0402    %
%==============================%
%
\subsection{Proof of Theorem~\ref{thm:qk1}.}
\label{subsec:prf-qk1}

Keep the notation and setting of Theorem~\ref{thm:qk1}. 
We see from Corollary~\ref{cor:NOS2} that for $z \in W$, 
%
\begin{equation} \label{eq:N}
a_{z}(\sQ) = \delta_{z,w} 
 - (-1)^{\ell(z)-\ell(w)}
  \sum_{ \begin{subarray}{c} \bp \in \bQLS{w} \\ \ed(\bp)=z \end{subarray} }
   \be^{-\vpi_{i}+\wt(\eta_{\bp})}  \sQ^{ \qwt(\bp) }; 
\end{equation}
%
since the labels of the edges in $\bp$ are all contained in $\DJp$, we see that
%
\begin{equation} \label{eq:Qi}
\qwt(\bp) > 0 \iff 
\pair{\vpi_{i}}{\qwt(\bp)} > 0 \iff 
\sQ^{\qwt(\bp)} \in \sQ_{i}R(T)[\sQ]. 
\end{equation}

We set 
%
\begin{equation*}
U:=\bigl\{ z \in W \mid 
\text{$\ed(\bp) = z$ and $\qwt(\bp) = 0$ for some $\bp \in \bQLS{w}$} \bigr\}; 
\end{equation*}
%
notice that $w \in U$ since $(\bt_{w},\dots,\bt_{w},\bt_{w}) \in \bQLS{w}$. 
From \eqref{eq:N} and \eqref{eq:Qi}, we deduce that 
%
\begin{enu}
\item[\rm (a)] if $z \in U$, then $a_{z}(\sQ) \ne 0$ and $a_{z}(\sQ) \in c_{z} + \sQ_{i}R(T)[\sQ]$; 
\item[\rm (b)] if $z \in W \setminus U$, then $a_{z}(\sQ) \in \sQ_{i}R(T)[\sQ]$, and hence $c_{z} = 0$. 
\end{enu}
%
Now, let $d \in Q^{\vee,+}$ be as in Theorem~\ref{thm:qk1}.
Then, the coefficient of $\sQ^{d}$ on the left-hand side of \eqref{eq:main1} 
is equal to $\thp{s_{i}}{w}{x}_{d}$. 
Also, the right-hand side of \eqref{eq:main1} can be written as: 
%
\begin{equation*}
\sum_{z \in U} \underbrace{a_{z}(\sQ)}_{\in c_{z}+\sQ_{i}R(T)[\sQ]}
\sum_{\xi \in Q^{\vee,+}} \sQ^{\xi} \twp{z}{x}_{\xi}
+ 
\sum_{z \in W \setminus U}
\underbrace{ a_{z}(\sQ) }_{\in \sQ_{i}R(T)[\sQ] } 
\sum_{\xi \in Q^{\vee,+}} \sQ^{\xi} \twp{z}{x}_{\xi}. 
\end{equation*}
%
Since $d_{i}= 0$ (and hence $\sQ^{d} \notin \sQ_{i}R(T)[\sQ]$), 
we see that the coefficient of $\sQ^{d}$ 
on the right-hand side of \eqref{eq:main1} is equal to 
$\sum_{z \in U} c_{z} \twp{z}{x}_{d}$.
Therefore, we conclude that 
%
\begin{equation*}
\thp{s_{i}}{w}{x}_{d} = \sum_{z \in U} c_{z} \twp{z}{x}_{d} 
\stackrel{\text{(b)}}{=}
\sum_{z \in W} c_{z} \twp{z}{x}_{d}, 
\end{equation*}
%
as desired. 
This completes the proof of Theorem~\ref{thm:qk1}. 

%==============================%
%     START SUBSECTION 0403    %
%==============================%
%
\subsection{Proof of Theorem~\ref{thm:qk2}.}
\label{subsec:prf-qk2}

Keep the notation and setting of Theorem~\ref{thm:qk2}; 
recall that $J = J_{\varpi_i} = I \setminus \{ i \}$. 
By \eqref{eq:N}, we can rewrite \eqref{eq:main1} as follows:
%
\begin{align} 
& \sum_{d \in Q^{\vee,+}}
  \sQ^{d} \thp{s_{i}}{w}{x}_{d} \nonumber \\
%
& = \sum_{\xi \in Q^{\vee,+}} \sum_{z \in W}
\left( \delta_{z,w} \sQ^{\xi}\twp{z}{x}_{\xi} - (-1)^{\ell(w)-\ell(z)} 
  \sum_{ \begin{subarray}{c} \bp \in \bQLS{w} \\ \ed(\bp)=z \end{subarray} }
  \be^{-\vpi_{i}+\wt(\eta_{\bp})} \sQ^{ \qwt(\bp) + \xi }\twp{z}{x}_{\xi}\right) \nonumber \\
%
& = \sum_{\xi \in Q^{\vee,+}} \sum_{z \in W} \delta_{z,w} \sQ^{\xi}\twp{z}{x}_{\xi} - 
\sum_{\xi \in Q^{\vee,+}} 
\sum_{ \bp \in \bQLS{w} } (-1)^{\ell(\bp)} 
\be^{-\vpi_{i}+\wt(\eta_{\bp})}
\sQ^{ \qwt(\bp) + \xi }\twp{\ed(\bp)}{x}_{\xi}. \label{eq:main2}
\end{align}
%
By comparing the coefficients of $\sQ^{d}$ on the leftmost-hand side and the rightmost-hand side, we deduce that 
%
%%%%%%%%%%%%%%%%%
%%% eq:conj2a %%%
%%%%%%%%%%%%%%%%%
%
\begin{align}
\thp{s_{i}}{w}{x}_{d}
& = \twp{w}{x}_{d} - 
\sum_{ \begin{subarray}{c} \bp \in \bQLS{w} \\ \qwt(\bp) \le d \end{subarray} } 
(-1)^{\ell(\bp)}
\be^{-\vpi_{i}+\wt(\eta_{\bp})}
\twp{\ed(\bp)}{x}_{d-\qwt(\bp)} \nonumber \\
%
& = \twp{w}{x}_{d} - 
\sum_{ \begin{subarray}{c} \bp \in \bQLS{w} \\ 
\qwt(\ed(\bp) \Rightarrow x) \le d-\qwt(\bp) \end{subarray} }
(-1)^{\ell(\bp)}\be^{-\vpi_{i}+\wt(\eta_{\bp})} \nonumber \\
%
& = \twp{w}{x}_{d} - 
\sum_{ \bp \in \bQLS{w,x,d} }
(-1)^{\ell(\bp)}\be^{-\vpi_{i}+\wt(\eta_{\bp})}. \label{eq:conj2a}
\end{align}
%
Here, we set
%
\begin{align}
\bQLS{w,x,d,+} & = \bigl\{ \bp \in \bQLS{w,x,d} \mid \pair{\vpi_{i}}{d-\qwt_{2}(\bp)} > 0 \bigr\}, \\
\bQLS{w,x,d,0} & = \bigl\{ \bp \in \bQLS{w,x,d} \mid \pair{\vpi_{i}}{d-\qwt_{2}(\bp)} = 0 \bigr\};
\end{align}
%
note that $\bQLS{w,x,d} = \bQLS{w,x,d,+} \sqcup \bQLS{w,x,d,0}$, and that 
$\bR{w,x,d} \subset \bQLS{w,x,d,0}$. In order to prove Theorem~\ref{thm:qk2}, 
we need to prove the following proposition. 

%%%%%%%%%%%%%%%%
%%% prop:qk2 %%%
%%%%%%%%%%%%%%%%
%
\begin{prop} \label{prop:qk2}
Keep the notation and setting above. We have 
%
\begin{equation} \label{eq:qk2-1}
 \sum_{ \bp \in \bQLS{w,x,d,+} }
(-1)^{\ell(\bp)}\be^{-\vpi_{i}+\wt(\eta_{\bp})} = 0, 
\end{equation}
%
\begin{equation} \label{eq:qk2-2}
 \sum_{ \bp \in \bQLS{w,x,d,0} \setminus \bR{w,x,d} }
(-1)^{\ell(\bp)}\be^{-\vpi_{i}+\wt(\eta_{\bp})} = 0. 
\end{equation}
%
\end{prop}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsubsection{Proof of \eqref{eq:qk2-1}.}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

In the proof below, we give two ``sijections'' (i.e., bijections 
between signed sets) $\Theta$ and $\Theta'$.

First, for $\bp=(\bp_{N},\dots,\bp_{2},\bp_{1}) \in \bQLS{w}$, 
we define $\Theta(\bp)$ as follows. Here we recall that 
$\FL{\bp_{1}}$ denotes the final label of $\bp_{1}$ 
(if $\bp_{1}$ is not the trivial directed path); 
if $\bp_{1}$ is the trivial directed path, then we set $\FL{\bp_{1}}:=-\infty$, 
which is a formal element such that 
$- \infty \lhd \alpha$ for all $\alpha \in \Delta^{+}$. 
Remark that $\alpha_{i}$ is the maximum element in $\Delta^{+}$ with respect to $\lhd$. 
%
\begin{enu}
\item If $\FL{\bp_{1}}=\alpha_{i}$, then 
we define $\Theta(\bp_{1})$ to be the directed path obtained from $\bp_{1}$ by removing the final edge $\ed(\bp_{1})s_{i} \edge{\alpha_{i}} \ed(\bp_{1})$; 
we set $\Theta(\bp):=(\bp_{N},\dots,\bp_{2},\Theta(\bp_{1}))$. 
%
\item If $\FL{\bp_{1}} \ne \alpha_{i}$, then 
we define $\Theta(\bp_{1})$ to be the directed path obtained from $\bp_{1}$ 
by adding the edge $\ed(\bp_{1}) \edge{\alpha_{i}} \ed(\bp_{1})s_{i}$ at the end of $\bp_{1}$; 
we set $\Theta(\bp):=(\bp_{N},\dots,\bp_{2},\Theta(\bp_{1}))$. 
\end{enu}
%
It is easily verified that 
$\Theta(\bp) \in \bQLS{w}$, with $\ell(\Theta(\bp))=\ell(\bp) \pm 1$, and that 
$\eta_{\Theta(\bp)} = \eta_{\bp}$. Hence, $\Theta$ is a sijection on $\bQLS{w}$; 
however, the set $\bQLS{w,x,d}$ is not stable under $\Theta$ in general. 

%%%%%%%%
\medskip
%%%%%%%%

Now, we set 
%
\begin{align*}
\bA & := \bigl\{ (\bp_{N},\dots,\bp_{2},\bp_{1}) \in \bQLS{w,x,d,+} \mid 
  \FL{\bp_{1}} = \alpha_{i} \bigr\}, \\
\bB & := \bigl\{ (\bp_{N},\dots,\bp_{2},\bp_{1}) \in \bQLS{w,x,d,+} \mid 
  \FL{\bp_{1}} \ne \alpha_{i} \bigr\}. 
\end{align*}
%
%%%%%%%%%%%%%%%%%%
%%% lem:Theta1 %%%
%%%%%%%%%%%%%%%%%%
%
\begin{lem} \label{lem:Theta1}
We have $\Theta(\bp) \in \bB$ for all $\bp \in \bA$.
\end{lem}

\begin{proof}
Let $\bp = (\bp_{N},\dots,\bp_{2},\bp_{1}) \in \bA$, and set $z:=\ed(\bp)$; 
recall that $\qwt(z \Rightarrow x) \le d - \qwt(\bp)$ and 
$\pair{\vpi_{i}}{d-\qwt_{2}(\bp)} > 0$. 
We see that $\qwt_{2}(\Theta(\bp)) = \qwt_{2}(\bp)$, which implies that 
$\pair{\vpi_{i}}{d-\qwt_{2}(\Theta(\bp))} = \pair{\vpi_{i}}{d-\qwt_{2}(\bp)} > 0$. 
Note that 
$\ed(\Theta(\bp)) = zs_{i} \edge{\alpha_{i}} z=\ed(\bp)$ is the final edge of $\bp_{1}$. 
Let $zs_{i} \edge{\alpha_{i}} z \Rightarrow x$ be 
the concatenation of the edge $zs_{i} \edge{\alpha_{i}} z$ 
with a shortest directed path from $z$ to $w$. 
%
Assume that $zs_{i} \edge{\alpha_{i}} z$ is a Bruhat edge. 
We see that $\qwt(\Theta(\bp))=\qwt(\bp)$, and that 
%
\begin{align*}
\qwt(\ed(\Theta(\bp)) \Rightarrow x) & = 
\qwt(zs_{i} \Rightarrow x) \le 
\qwt(zs_{i} \Be{\alpha_{i}} z \Rightarrow x) = \qwt(z \Rightarrow x) \\ 
& \le d-\qwt(\bp) = d-\qwt(\Theta(\bp)); 
\end{align*}
%
for the first inequality, see Proposition~\ref{prop:qwt}. 
Thus, we deduce that 
$\qwt(\ed(\Theta(\bp)) \Rightarrow x) \le d-\qwt(\Theta(\bp))$, 
and hence $\Theta(\bp) \in \bB$. 
Assume that $zs_{i} \edge{\alpha_{i}} z$ is a quantum edge. 
We see that $\qwt(\Theta(\bp))=\qwt(\bp)-\alpha_{i}^{\vee}$, and that 
%
\begin{align*}
\qwt(\ed(\Theta(\bp)) \Rightarrow x) & = 
\qwt(zs_{i} \Rightarrow x) \le 
\qwt(zs_{i} \Qe{\alpha_{i}} z \Rightarrow x) = \alpha_{i}^{\vee}+ \qwt(z \Rightarrow x) \\ 
& \le \alpha_{i}^{\vee} + d-\qwt(\bp) = d-\qwt(\Theta(\bp)). 
\end{align*}
%
Thus, we deduce that 
$\qwt(\ed(\Theta(\bp)) \Rightarrow x) \le d-\qwt(\Theta(\bp))$, 
and hence $\Theta(\bp) \in \bB$. This proves the lemma. 
\end{proof}

%%%%%%%%%
We divide the subset $\bB$ into two subsets: 
%
\begin{align*}
\bB_{1} & := \bigl\{ \bp \in \bB \mid \Theta(\bp) \in \bQLS{w,x,d,+} \bigr\}, \\
\bB_{2} & := \bigl\{ \bp \in \bB \mid \Theta(\bp) \not\in \bQLS{w,x,d,+} \bigr\}.
\end{align*}
%
By Lemma~\ref{lem:Theta1}, we find that $\bp \mapsto \Theta(\bp)$ 
is a sijection on the set $\bA \sqcup \bB_{1}$. 
We need to define another sijection $\Theta'$ on $\bB_{2}$. 
Let $\bp = (\bp_{N},\dots,\bp_{2},\bp_{1}) \in \bB_{2}$, and set $z := \ed(\bp)$. 
Since $\qwt_{2}(\Theta(\bp)) = \qwt_{2}(\bp)$, it follows that 
$\pair{\vpi_{i}}{d-\qwt_{2}(\Theta(\bp))} = \pair{\vpi_{i}}{d-\qwt_{2}(\bp)} > 0$. 
Hence we have
%
\begin{equation} \label{eq:notle}
\qwt ( \ed(\Theta(\bp)) \Rightarrow x) \not\le d - \qwt(\Theta(\bp)).
\end{equation}
%
Let $\sT_{1} \in \{\sB, \sq\}$ be the type of the edge 
$\ed(\bp)=z \edge{\alpha_{i}} zs_{i}$ (the final edge of $\Theta(\bp_{1})$), and set 
%
\begin{equation} \label{eq:osT}
\ol{\sT}_{1}:=\begin{cases} 
 \sB & \text{if $\sT_{1}=\sq$}, \\
 \sq & \text{if $\sT_{1}=\sB$}.
 \end{cases}
\end{equation}
%
Note that $\qwt(\Theta(\bp)) = \qwt(\bp) + \delta_{\sT_{1},\bq}\alpha_{i}^{\vee}$. 
Since $zs_{i} \te{\alpha_{i}}{\ol{\sT}_{1}} z \Rightarrow x$ 
(the concatenation of the edge $zs_{i} \edge{\alpha_{i}} z$ 
 with a shortest directed path from $z$ to $w$) 
is a directed path from $zs_{i}$ to $x$, we have 
%
\begin{align*}
& \qwt(\ed(\Theta(\bp)) \Rightarrow x) = 
\qwt(zs_{i} \Rightarrow x) \\
%
& = 
\begin{cases}
-\delta_{\sT_1,\sq} \alpha_{i}^{\vee} + 
\qwt(z \Rightarrow x) & \text{if condition (D) is satisfied}, \\
%
\delta_{\sT_1,\sB} \alpha_{i}^{\vee} + \qwt(z \Rightarrow x) 
& \text{if condition (D) is not satisfied},
\end{cases}
%
\end{align*}
%
where condition (D) is: 
%
\begin{enu}
\item[(D)] the initial label $\IL{\dec(z \Rightarrow x)}$ of 
the label-decreasing directed path $\dec(z \Rightarrow x)$ 
from $z$ to $x$ is  $\alpha_{i}$; 
recall that $\alpha_{i}$ is the maximum element with respect to $\lhd$. 
\end{enu}
%
Recall that $\qwt(\ed(\bp) \Rightarrow x) \le d - \qwt(\bp)$. 
If condition (D) were satisfied, then we would have 
$\qwt(\ed(\Theta(\bp)) \Rightarrow x) \le d - \qwt(\Theta(\bp))$, 
which contradicts \eqref{eq:notle}. 
Therefore, condition (D) is not satisfied in this case.
Now, we set 
%
\begin{equation} \label{eq:beta}
\beta:= \begin{cases}
 \FL{\bp_{1}} & \text{if $\bp_{1}$ is not the trivial one}, \\[1.5mm]
 -\infty & \text{if $\bp_{1}$ is the trivial one}; 
 \end{cases}
\end{equation}
%
note that 
$\beta \ne \alpha_{i}$ since $\bp \in \bB_{2} \subset \bB$. 
Also, we set 
%
\begin{equation} \label{eq:gamma}
\gamma:= \begin{cases}
 \IL{\dec(z \Rightarrow x)} & \text{if $z \ne x$}, \\[1.5mm]
 -\infty & \text{if $z = x$}; 
 \end{cases}
\end{equation}
%
note that $\gamma \ne \alpha_{i}$ since condition (D) is not satisfied. 
%
%%%%%%%%%%%%%%
%%% lem:s1 %%%
%%%%%%%%%%%%%%
%
\begin{lem} \label{lem:s1}
Keep the notation and setting above. 
If $\gamma \in \DJs \cup \{ -\infty \}$, then $\qwt(\bp_{1}) > 0$, 
and hence $\bp_{1}$ is not the trivial directed path. 
\end{lem}
%
%%%%%%%%%%%%%%
%%% rem:bg %%%
%%%%%%%%%%%%%%
%
\begin{rem} \label{rem:bg}
By Lemma~\ref{lem:s1}, we see that $(\beta,\gamma) \ne (-\infty,-\infty)$. 
Recall that if there exists a directed path of the form 
$z's_{\beta'} \edge{\beta'} z' \edge{\beta'} z's_{\beta'}$ in $\QBG(W)$ 
for some $z' \in W$ and $\beta' \in \Delta^{+}$, then 
$\beta'$ is a simple root. 
Since $\alpha_{i}$ is the unique simple root contained in 
$\DJp$, and since $\beta,\,\gamma \ne \alpha_{i}$ as seen above, 
we conclude that $\beta \ne \gamma$. 
\end{rem}

\begin{proof}[Proof of Lemma~\ref{lem:s1}]
Suppose, for a contradiction, that 
$\gamma \in \DJs \cup \{-\infty\}$ and $\qwt(\bp_{1}) = 0$; 
note that $\qwt(\bp)=\qwt_{2}(\bp)$ in this case. 
%
Recall that $\qwt(\Theta(\bp)) = \qwt(\bp) + \delta_{\sT_{1},\sq}\alpha_{i}^{\vee}$. 
Also, we deduce by \eqref{eq:ro} that 
$\qwt(z \Rightarrow x) \in \sum_{j \in \J} \BZ_{\ge 0}\alpha_{j}^{\vee}$. 
Since $\pair{\vpi_{i}}{d-\qwt_{2}(\bp)} > 0$, and 
$\qwt(z \Rightarrow x) \le d - \qwt(\bp) = d - \qwt_{2}(\bp)$, we see that 
%
\begin{align*}
\qwt(\ed(\Theta(\bp)) \Rightarrow x) & = 
\delta_{\sT_{1},\sB} \alpha_{i}^{\vee} + \qwt(z \Rightarrow x) \\
& \le d - \qwt(\bp) - \delta_{\sT_{1},\sq}\alpha_{i}^{\vee} = d-\qwt(\Theta(\bp)), 
\end{align*}
%
which contradicts \eqref{eq:notle}. 
This proves the lemma. 
\end{proof}

We define $\Theta'(\bp_{1})$ as follows (recall that $\beta \ne \gamma$, and 
$\beta,\,\gamma \ne \alpha_{i}$). 
%
\begin{enu}
\item[(i)] If $\beta \rhd \gamma$, then 
$\Theta'(\bp_{1})$ is defined to be the directed path obtained from $\bp_{1}$ by 
removing the final edge (labeled by $\beta$). 

\item[(ii)] If $\beta \lhd \gamma$, then 
$\Theta'(\bp_{1})$ is defined to be the directed path obtained from $\bp_{1}$ by 
adding the edge labeled by $\gamma$ at the end of $\bp_{1}$ 
(note that if $\beta=-\infty$, then $\gamma \in \DJp$; see Lemma~\ref{lem:s1}). 
\end{enu}
%
We set $\bq_{1}:=\Theta'(\bp_{1})$. We see that 
$\Theta'(\bp):= (\bp_{N},\dots,\bp_{2},\Theta'(\bp_{1})) \in \bQLS{w}$; notice that 
%
\begin{equation} \label{eq:sij}
\ell(\Theta'(\bp)) = \ell(\bp) \pm 1 \quad \text{and} \quad 
\eta_{\Theta'(\bp)}=\eta_{\bp}.
\end{equation}
%
We claim that $\bq := \Theta'(\bp) \in \bB_{2}$. 
We remark that the final label $\FL{\bq_{1}}$ of 
$\bq_{1}=\Theta'(\bp_{1})$ is not equal to $\alpha_{i}$ (recall the definition of $\bB$). 
Since $\qwt_{2}(\Theta'(\bp)) = \qwt_{2}(\bp)$, it follows that 
$\pair{\vpi_{i}}{d-\qwt_{2}(\Theta'(\bp))} = \pair{\vpi_{i}}{d-\qwt_{2}(\bp)} > 0$. 
Hence, it remains to show that
%
\begin{equation} \label{eq:B1}
 \underbrace{ \qwt(\ed(\bq) \Rightarrow x) }_{= \, \qwt(\ed(\bq_{1}) \Rightarrow x)} 
 \le d-\qwt(\bq), 
\end{equation}
%
\begin{equation} \label{eq:B2}
 \underbrace{ \qwt( \ed(\Theta(\bq) ) \Rightarrow x) }_{= \, \qwt(\ed(\Theta(\bq_{1})) \Rightarrow x)} 
 \not \le d-\qwt(\Theta(\bq)). 
\end{equation}

%%%%%%%%
\medskip
%%%%%%%%

%%%%%%%%%%%%%%%%%%%%%%%
\paragraph{\bf Case 1.}
%%%%%%%%%%%%%%%%%%%%%%%
%
Assume that $\beta \rhd \gamma$ (see (i));
note that $\ed(\bq) = \ed(\bq_{1}) = zs_{\beta} \edge{\beta} z=\ed(\bp_{1}) = \ed(\bp)$ 
is the final edge of $\bp_{1}$. Let $\sT_{\beta} \in \{\sB, \sq\}$ 
be the type of the edge $zs_{\beta} \edge{\beta} z$. We have 
%
\begin{equation*}
\underbrace{
\overbrace{\ed(\bp_{2}) \edge{\bullet} \cdots \edge{\bullet}
\ed(\bq_{1})}^{= \, \bq_{1} \, = \, \Theta'(\bp_{1})} = zs_{\beta} \te{\beta}{\sT_{\beta}} 
\ed(\bp_{1})}_{= \, \bp_{1}} = 
\underbrace{z \edge{\gamma} \cdots \edge{\bullet} x}_{= \, \dec(z \Rightarrow x)}, 
\end{equation*}
%
\begin{equation*}
\qwt(\Theta'(\bp)) = \qwt(\bp) - \delta_{\sT_{\beta},\sq} \beta^{\vee}, \qquad 
\qwt(z \Rightarrow x) = \qwt(zs_{\beta} \Rightarrow x) - \delta_{\sT_{\beta},\sq} \beta^{\vee}. 
\end{equation*}
%
Therefore, it follows that 
%
\begin{align*}
\qwt(\ed(\Theta'(\bp)) \Rightarrow x) & = 
  \qwt(\ed(\bp) \Rightarrow x) + \delta_{\sT_{\beta},\sq} \beta^{\vee} \\
& \le d-\qwt(\bp) + \delta_{\sT_{\beta},\sq} \beta^{\vee} = d - \qwt(\Theta'(\bp)), 
\end{align*}
%
which implies \eqref{eq:B1}. Let us show \eqref{eq:B2}. 
Let $\sT_{2} \in \{\sB, \sq\}$ be the type of the edge 
$zs_{\beta} \edge{\alpha_{i}} zs_{\beta}s_{i}$, and set
%
\begin{equation} \label{eq:osT2}
\ol{\sT}_{2}:=\begin{cases} 
 \sB & \text{if $\sT_{2} = \sq$}, \\
 \sq & \text{if $\sT_{2} = \sB$}.
 \end{cases}
\end{equation}
%
Notice that
%
\begin{equation*}
zs_{\beta}s_{i} \te{\alpha_{i}}{\ol{\sT}_{2}} zs_{\beta} \te{\beta}{\sT_{\beta}} 
\underbrace{z \edge{\gamma} \cdots \edge{\bullet} x}_{ = \, \dec(z \Rightarrow x) }, \qquad
zs_{i} \te{\alpha_{i}}{\ol{\sT}_{1}}
\underbrace{z \edge{\gamma} \cdots \edge{\bullet} x}_{ = \, \dec(z \Rightarrow x) }
\end{equation*}
%
are both label-decreasing directed paths (recall that $\alpha_{i} \rhd \beta \rhd \gamma$). 
Hence, we see that
%
\begin{equation*}
%
\begin{split}
\qwt(\Theta(\bq)) 
 & = \qwt(\Theta(\bp)) -\delta_{\sT_{1},\sq} \alpha_{i}^{\vee} 
     -\delta_{\sT_{\beta},\sq} \beta^{\vee} + \delta_{\sT_{2},\sq}\alpha_{i}^{\vee}, \\
\qwt(zs_{\beta}s_{i} \Rightarrow x) & = \qwt(zs_{i} \Rightarrow x) 
  - \delta_{\ol{\sT}_{1},\bq} \alpha_{i}^{\vee} 
  + \delta_{\sT_{\beta},\sq} \beta^{\vee} 
  + \delta_{\ol{\sT}_{2},\sq} \alpha_{i}^{\vee} \\
  & = \qwt(zs_{i} \Rightarrow x) 
  - (-\alpha_{i}^{\vee}+\delta_{\ol{\sT}_{1},\bq} \alpha_{i}^{\vee})
  + \delta_{\sT_{\beta},\sq} \beta^{\vee} 
  + (-\alpha_{i}^{\vee}+\delta_{\ol{\sT}_{2},\sq} \alpha_{i}^{\vee}) \\
  & = \qwt(zs_{i} \Rightarrow x) 
  + \delta_{\sT_{1},\bq} \alpha_{i}^{\vee}
  + \delta_{\sT_{\beta},\sq} \beta^{\vee} 
  - \delta_{\sT_{2},\sq} \alpha_{i}^{\vee}.
\end{split}
%
\end{equation*}
%
Since $\qwt(zs_{i} \Rightarrow x) \not\le d - \qwt(\Theta(\bp))$ by the assumption, 
it follows that $\qwt(zs_{\beta}s_{i} \Rightarrow x) \not\le d - \qwt(\Theta(\bq))$. 
Thus, we have shown \eqref{eq:B2}, as desired. 

\medskip

%%%%%%%%%%%%%%%%%%%%%%%
\paragraph{\bf Case 2.}
%%%%%%%%%%%%%%%%%%%%%%%
%
Assume that $\beta \lhd \gamma$ (see (ii));
note that $\ed(\bp) = \ed(\bp_{1}) = z \edge{\gamma} zs_{\gamma} = \ed(\bq_{1}) = \ed(\bq)$ 
is the initial edge of $\dec(z \Rightarrow x)$. Let $\sT_{\gamma} \in \{\sB, \sq\}$ 
be the type of the edge $z \edge{\gamma} zs_{\gamma}$. We have 
%
\begin{equation*}
\underbrace{
\ed(\bp_{2}) \edge{\bullet} \cdots \edge{\bullet} zs_{\beta} \edge{\beta} 
\ed(\bp_{1})}_{= \, \bp_{1}} = 
\underbrace{
z \te{\gamma}{\sT_{\gamma}} \ed(\bq_{1}) = zs_{\gamma} \edge{\bullet} \cdots \edge{\bullet} x}_{%
= \, \dec(z \Rightarrow x)}, 
\end{equation*}
%
\begin{equation*}
\qwt(\Theta'(\bp)) = \qwt(\bp) + \delta_{\sT_{\gamma},\sq}\gamma^{\vee}, \qquad 
\qwt(z \Rightarrow x) = \qwt(zs_{\gamma} \Rightarrow x) + \delta_{\sT_{\gamma},\sq}\gamma^{\vee}. 
\end{equation*}
%
Therefore, it follows that 
%
\begin{align*}
\qwt(\ed(\Theta'(\bp)) \Rightarrow x) 
& = \qwt(\ed(\bp) \Rightarrow x) -  \delta_{\sT_{\gamma},\sq}\gamma^{\vee} \\
& \le d-\qwt(\bp) - \delta_{\sT_{\gamma},\sq}\gamma^{\vee} = d-\qwt(\Theta'(\bp)), 
\end{align*}
%
which implies \eqref{eq:B1}. Let us show \eqref{eq:B2}.
Let $\sT_{3} \in \{\sB, \sq\}$ be the type of the edge 
$zs_{\gamma} \edge{\alpha_{i}} zs_{\gamma}s_{i}$, and 
set
%
\begin{equation} \label{eq:osT3}
\ol{\sT}_{3}:=\begin{cases} 
 \sB & \text{if $\sT_{3} = \sq$}, \\
 \sq & \text{if $\sT_{3} = \sB$}.
 \end{cases}
\end{equation}
%
Notice that 
%
\begin{equation*}
zs_{i} \te{\alpha_{i}}{\ol{\sT}_{1}}
\underbrace{z \te{\gamma}{\sT_{\gamma}} zs_{\gamma} \edge{\bullet} 
\cdots \edge{\bullet} x}_{ = \, \dec(z \Rightarrow x) }, \qquad
%
zs_{\gamma}s_{i} \te{\alpha_{i}}{\ol{\sT}_{3}}
\underbrace{zs_{\gamma} \edge{\bullet} \cdots \edge{\bullet} x}_{ \text{label-decreasing} }
\end{equation*}
%
are both label-decreasing directed paths. Hence, we see that
%
\begin{align*}
\qwt(\Theta(\bq)) & = \qwt(\Theta(\bp)) 
 - \delta_{\sT_{1},\sq}\alpha_{i}^{\vee}
 + \delta_{\sT_{\gamma},\sq}\gamma^{\vee} 
 + \delta_{\sT_{3},\sq}\alpha_{i}^{\vee}, \\
\qwt(zs_{\gamma}s_{i} \Rightarrow x) 
& = \qwt(zs_{i} \Rightarrow x) 
    - \delta_{\ol{\sT}_{1},\sq} \alpha_{i}^{\vee} 
    - \delta_{\sT_{\gamma},\sq}\gamma^{\vee} 
    + \delta_{\ol{\sT}_{3},\sq}\alpha_{i}^{\vee} \\
& = \qwt(zs_{i} \Rightarrow x) 
    - (-\alpha_{i}^{\vee} + \delta_{\ol{\sT}_{1},\sq} \alpha_{i}^{\vee})
    - \delta_{\sT_{\gamma},\sq}\gamma^{\vee} 
    + (-\alpha_{i}^{\vee} + \delta_{\ol{\sT}_{3},\sq}\alpha_{i}^{\vee}) \\
& = \qwt(zs_{i} \Rightarrow x) 
    + \delta_{\sT_{1},\sq}\alpha_{i}^{\vee}
    - \delta_{\sT_{\gamma},\sq}\gamma^{\vee} 
    - \delta_{\sT_{3},\sq}\alpha_{i}^{\vee}. 
\end{align*}
%
Since $\qwt(zs_{i} \Rightarrow x) \not\le d - \qwt(\Theta(\bp))$ by the assumption, 
it follows that $\qwt(zs_{\gamma}s_{i} \Rightarrow x) \not\le d - \qwt(\Theta(\bq))$. 
Thus, we have shown \eqref{eq:B2}, as desired. 

\bigskip

We can easily deduce that $\Theta'(\Theta'(\bp)) = \bp$ for all $\bp \in \bB_{2}$. 
By this fact, together with \eqref{eq:sij}, $\Theta'$ is a sijection on $\bB_{2}$. 
Therefore, we conclude that 
%
\begin{align*}
& \sum_{\bp \in \bQLS{w,x,d,+}} (-1)^{\ell(\bp)} \be^{-\vpi_{i}+\wt(\eta_{\bp})} \\[2mm]
& = 
\underbrace{ \sum_{\bp \in \bA \sqcup \bB_{1}} (-1)^{\ell(\bp)} \be^{-\vpi_{i}+\wt(\eta_{\bp})} }_{= \, 0 \ 
\text{by sijection $\Theta$}}  + 
\underbrace{ \sum_{\bp \in \bB_{2}} (-1)^{\ell(\bp)} \be^{-\vpi_{i}+\wt(\eta_{\bp})} }_{= \, 0 \
\text{by sijection $\Theta'$}} = 0,
\end{align*}
%
as desired.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsubsection{Proof of \eqref{eq:qk2-2}.}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

For simplicity of notation, we set
%
\begin{equation}
\bS{w,x,d}:=\bQLS{w,x,d,0} \setminus \bR{w,x,d}. 
\end{equation}
%
Let $\bp = (\bp_{N},\dots,\bp_{2},\bp_{1}) \in \bS{w,x,d}$, and set $z:=\ed(\bp)$. 
We define $\beta$ and $\gamma$ as in \eqref{eq:beta} and \eqref{eq:gamma}, respectively. 
Since $\bp \in \bS{w,x,d}$, we see that
%
\begin{equation} \label{eq:bg2}
\text{if $\gamma \in \DJs \cup \{-\infty\}$, then $\beta \in \DJp$}. 
\end{equation}
%
Suppose, for a contradiction, that $(\beta,\gamma) = (\alpha_{i},\alpha_{i})$. 
Then we have $zs_{i} \edge{\beta=\alpha_{i}} z \edge{\gamma=\alpha_{i}} zs_{i}$; 
note that either of these two edges is a quantum edge. 
Recall that $\qwt_{2}(\bp)+\qwt(\bp_{1}) = \qwt(\bp) \le d$. 
Since $\pair{\vpi_{i}}{d-\qwt_{2}(\bp)} = 0$, and 
since the labels of the edges in $\bp_{1}$ are all contained in $\DJp$, 
we deduce that $\qwt(\bp_{1})=0$, or equivalently, all the edges in $\bp_{1}$ 
are Bruhat edges; in particular, $zs_{i} \edge{\beta=\alpha_{i}} z$ is a Bruhat edge. 
Also, we have $\qwt(\bp) = \qwt_{2}(\bp)$. 
Since $\qwt(z \Rightarrow x) \le d - \qwt(\bp) = d-\qwt(\bp_{2})$, 
it follows that an edge in $\dec(z \Rightarrow x)$ whose label 
is contained in $\DJp$ is a Bruhat edge; in particular, 
$z \edge{\gamma=\alpha_{i}} zs_{i}$ is also a Bruhat edge. However, 
this is a contradiction. Thus, we have shown that $(\beta,\gamma) \ne (\alpha_{i},\alpha_{i})$. 
By the same argument as that in Remark~\ref{rem:bg}, we deduce that $\beta \ne \gamma$. 
%
Now, we define $\Psi(\bp_{1})$ as follows. 
%
\begin{enu}
\item[(iii)] If $\beta \rhd \gamma$, then 
$\Psi(\bp_{1})$ is defined to be the directed path obtained from $\bp_{1}$ by 
removing the final edge (labeled by $\beta$). 

\item[(iv)] If $\beta \lhd \gamma$, then 
$\Psi(\bp_{1})$ is defined to be the directed path obtained from $\bp_{1}$ by 
adding the edge labeled by $\gamma$ at the end of $\bp_{1}$ 
(note that if $\beta=-\infty$, then $\gamma \in \DJp$; see \eqref{eq:bg2}). 
\end{enu}
%
Then we set $\Psi(\bp):=(\bp_{N},\dots,\bp_{2},\Psi(\bp_{1}))$; 
notice that $\Psi(\bp) \in \bQLS{w}$, and that 
%
\begin{equation}
\ell(\Psi(\bp)) = \ell(\bp) \pm 1 \quad \text{and} \quad 
\eta_{\Psi(\bp)} = \eta_{\bp}.
\end{equation}
%
We claim that $\Psi(\bp) \in \bS{w,x,d}$. 
Since $\qwt_{2}(\Psi(\bp)) = \qwt_{2}(\bp)$, 
it follows that $\pair{\vpi_{i}}{d-\qwt_{2}(\Psi(\bp))}=
\pair{\vpi_{i}}{d-\qwt_{2}(\bp)}=0$. We see that 
$\ell(\Psi(\bp_1)) > 0$ or $\ed(\Psi(\bp)) \notin x\WJs$. 
Hence, it remains to show that 
%
\begin{equation} \label{eq:Psi}
\qwt(\ed(\Psi(\bp)) \Rightarrow x) \le d - \qwt(\Psi(\bp)).
\end{equation}
%
By the argument in the previous paragraph, we deduce that 
in both cases (iii) and (iv), 
$\qwt(\ed(\Psi(\bp)) \Rightarrow x) = \qwt(\ed(\bp) \Rightarrow x)$ and 
$\qwt(\Psi(\bp)) = \qwt(\bp)$. Since 
$\qwt(\ed(\bp) \Rightarrow x) \le d - \qwt(\bp)$ by the assumption, 
we obtain \eqref{eq:Psi}, as desired. 

Notice that $\ell(\Psi(\bp)) = \ell(\bp) \pm 1$ and 
$\eta_{\Psi(\bp)}=\eta_{\bp}$. Hence, $\Psi$ is a sijection on $\bS{w,x,d}$. 
Thus, we have proved \eqref{eq:qk2-2}, as desired. 

