\section{Parabolic Analogs.}
\label{sec:para}

%==============================%
%     START SUBSECTION 0501    %
%==============================%
%
\subsection{$K$-theoretic Gromov-Witten invariants (parabolic case).}
\label{subsec:pKGW}

Let $\K$ be an arbitrarily fixed (nonempty) subset of $I$. 
Let $P = P_{\Kc}$ be the (standard) parabolic subgroup of $G$ containing $B$
corresponding to the subset $\Kc$ of $I$, and let $Y := G/P$ be 
the corresponding flag manifold; 
let $W_{\Kc} := \langle s_j \mid j \in \Kc \rangle \subset W$ 
be the Weyl group for $P = P_{\Kc}$. 
The $T$-equivariant $K$-theory ring $K_T(Y)$ of $Y$ 
has an $R(T)$-basis consisting of the (opposite) Schubert classes $\CO^w_Y := [\CO_{Y^w}]$, 
$w \in W^{\Kc}$, where $W^{\Kc}$ is the set of minimal-length coset representatives 
for the cosets in $W/W_{\Kc}$; note that $Y^w := \ol{B^{-}wP/P} \subset Y$. 
We also use an $R(T)$-basis of $K_T(Y)$ consisting of 
the Schubert classes $\CO^Y_w := [\CO_{Y_w}]$, $w \in W^{\Kc}_{\max}$, 
where $W^{\Kc}_{\max}$ is the set of maximal-length coset representatives 
for the cosets in $W/W_{\Kc}$; note that $Y_w := \ol{B wP/P} \subset Y$. 

The 2nd homology group $H_2(Y, \BZ)$ is identified with 
$Q^{\vee}/Q^{\vee}_{\Kc} \cong Q^{\vee}_{K}$, 
where $Q^{\vee}_{\Kc} := \sum_{j \in \Kc} \BZ \alpha_j^{\vee}$ and 
$Q^{\vee}_{\K} := \sum_{j \in \K} \BZ \alpha_j^{\vee}$, 
with $\alpha_j^{\vee} \in Q^{\vee}_{\K}$ identified with 
the homology class $[Y_{s_j}] \in H_2(Y, \BZ)$ associated to 
the simple reflection $s_j$ for $j \in \K$. 
%
For an effective degree $d \in Q^{\vee,+}_{K} := 
\sum_{j \in K} \BZ_{\geq 0} \alpha_j^{\vee}$, and $m \geq 1$, 
let $\ol{\CM}_{0,m}(Y, d)$ denote the Kontsevich moduli space 
parametrizing all $m$-point, genus 0, degree $d$ stable maps to $Y$, 
which is equipped with ($T$-equivariant) evaluation maps 
$\ev_k : \ol{\CM}_{0,m}(Y, d) \to Y$ for $1 \leq k \leq m$. 
Then, for classes $\gamma_k \in K_T(Y)$, $1 \leq k \leq m$, 
the $m$-point ($T$-equivariant) $K$-theoretic Gromov-Witten (KGW) invariant is defined to be 
%
\begin{equation*}
\langle \gamma_1, \gamma_2, \ldots , \gamma_m \rangle_d^Y := 
\chi^{T}_{\ol{\CM}_{0,m}(Y,d)}(\ev_1^*(\gamma_1) \cdot \cdots \cdot \ev_m^*(\gamma_m)) 
\in K_{T}(\mathrm{pt}) = R(T),
\end{equation*}
%
where $\chi^{T}_{\ol{\CM}_{0,m}(Y,d)}$ is the ($T$-equivariant) pushforward 
along the structure morphism $\ol{\CM}_{0,m}(Y, d) \rightarrow \{ \mathrm{pt} \}$; 
the KGW invariant $\langle \gamma_1, \gamma_2, \ldots , \gamma_m \rangle_d^Y$ is 
$R(T)$-linear in each argument $\gamma_j$. 

Let $\pi = \pi_{\Kc} : X = G/B \to Y = G/P$ be the natural projection, 
which induces the pullback $\pi^* : K_T(Y) \to K_T(X)$. 
It is known that $\pi^*(\CO_{Y}^{w}) = \CO^w$ for $w \in W^{\Kc}$, 
and that $\pi^*(\CO^{Y}_{w}) = \CO_w$ for $w \in W^{\Kc}_{\max}$. 
Also, we know from \cite[Lemma~1]{Woo} 
(see also \cite[Remark~10.17]{LS} and \cite[Lemma~3.8]{LNSSS1}) 
that for each $d \in Q^{\vee}_K \cong H_2(Y, \BZ)$, 
there exists a unique $\dl{d} \in Q^{\vee} \cong H_2(X, \BZ)$ 
which is sent to $d$ under the induced map $H_2(X, \BZ) \to H_2(Y, \BZ)$ 
(which is just the projection $[\,\cdot\,] = [\,\cdot\,]_\K : 
Q^{\vee} \twoheadrightarrow Q^{\vee}/Q^{\vee}_{\Kc} \cong Q^{\vee}_{K}$, 
given by $[\sum_{j \in I} d_j \alpha_j^{\vee}] = \sum_{j \in K} d_j \alpha_j^{\vee}$) and 
such that $\pair{\alpha}{\dl{d}} \in \{ 0, -1 \}$ holds 
for all positive roots in $\Delta^+ \cap Q_{\Kc}$, 
with $Q_{\Kc} := \sum_{j \in \Kc} \BZ \alpha_j$; 
the element $\dl{d}$ is called the \emph{Peterson lift} of $d$.
Moreover, we know from Appendix~\ref{sec:MX} that 
the natural projection $\pi : X \rightarrow Y$ induces 
the (cohomologically trivial) map 
$\Phi : \ol{\CM}_{0,3}(X, \dl{d}) \rightarrow \ol{\CM}_{0,3}(Y, d)$, 
and hence the following equation for 3-point KGW invariants holds: 
for an effective degree $d \in Q^{\vee,+}_{\K} = 
\sum_{j \in \K} \BZ_{\geq 0} \alpha_j^{\vee}$ 
and its Peterson lift $\dl{d} \in Q^{\vee,+}$. 
%
\begin{equation}
\langle \gamma_1, \gamma_2, \gamma_3 \rangle_{d}^{Y} = 
\langle \pi^*(\gamma_1), \pi^*(\gamma_2), \pi^*(\gamma_3) \rangle_{\dl{d}}, 
\end{equation}
%
with $\gamma_1,\,\gamma_2,,\gamma_3 \in K_T(Y)$. 

The (small) $T$-equivariant quantum $K$-theory ring $QK_T(Y)$ of $Y$, 
defined by Givental \cite{Giv} and Lee \cite{Lee}, is 
(as a module over $R(T)\bra{\sQ}$) $K_T(Y) \otimes_{R(T)} R(T)\bra{\sQ_\K}$, 
where $R(T)\bra{\sQ_\K}$ is the ring of formal power series 
with coefficients in $R(T)$ in the (Novikov) variables 
$\sQ_j := \sQ^{\alpha_j^{\vee}}$, $j \in K$. 
The quantum $K$-metric $\Kmet{\,\cdot\,}{\cdot\,}^{Y}$ 
on $QK_T(Y)$ is the $R(T)\bra{\sQ_\K}$-bilinear (perfect) pairing 
$QK_T(Y) \times QK_T(Y) \rightarrow R(T)\bra{\sQ_\K}$ defined as: 
%
\begin{equation*}
\Kmet{\gamma_1}{\gamma_2}^Y = 
\sum_{d \in Q^{\vee,+}_K} \sQ^d \langle \gamma_1, \gamma_2 \rangle_d^Y
\end{equation*}
%
for $\gamma_1, \gamma_2 \in K_T(Y)$, 
where $\sQ^d := \prod_{j \in K} \sQ_j^{d_j}$ 
for $d = \sum_{j \in K} d_j \alpha_j^{\vee} \in Q^{\vee,+}_\K$. 
The quantum product $\star$ in $QK_T(Y)$ is determined by:
%
\begin{equation}\label{eq:parabqmulti}
\Kmet{\gamma_1 \star \gamma_2}{\gamma_3}^{Y} = 
\sum_{d \in Q^{\vee,+}_K} \sQ^d \langle \gamma_1, \gamma_2, \gamma_3 \rangle_d^Y
\end{equation}
%
for $\gamma_1, \gamma_2, \gamma_3 \in K_T(Y)$; 
note that the quantum product is $R(T)\bra{\sQ_\K}$-bilinear, 
commutative, and associative, with $1 \in K_T(Y)$ the multiplicative identity; 
also, it is known that $\Kmet{\gamma_1 \star \gamma_2}{\gamma_3}^Y = 
\Kmet{\gamma_1}{\gamma_2 \star \gamma_3}^Y$ 
for classes $\gamma_1, \gamma_2, \gamma_3 \in K_T(Y)$. 
The structure constants with respect to 
the (opposite) Schubert classes $\CO^w_Y$, $w \in W^{\Kc}$, 
for the quantum multiplication $\star$ in $QK_T(Y)$ are defined by: 
%
\begin{equation}\label{eq:parabqmulticoeff}
\CO^{v}_Y \star \CO^w_Y = 
\sum_{\substack{z \in W^{\Kc} \\ d \in Q^{\vee,+}_K}} M_{v,w}^{z,d} \sQ^d \CO^z_Y,
\end{equation}
%
with $M_{v,w}^{z,d} \in R(T)$ for $v, w, z \in W^{\Kc}$ and $d \in Q^{\vee,+}_K$. 

Now, let $QK_T^{\mathrm{poly}}(X) := 
K_T(X) \otimes_{R(T)} R(T)[\sQ] \subset QK_T(X)$ be 
the polynomial version of $QK_T(X)$, where $R(T)[\sQ]$ is 
the polynomial ring with coefficients in $R(T)$ 
in the variables $\sQ_j$, $j \in I$. 
Also, let $QK_T^{\mathrm{poly}}(Y) := K_T(Y) \otimes_{R(T)} R(T)[\sQ_\K]$ be 
the polynomial version of $QK_T(Y) = K_T(Y) \otimes_{R(T)} R(T)\bra{\sQ_\K}$, 
where $R(T)[\sQ_{\K}]$ is the polynomial ring 
with coefficients in $R(T)$ in the variables $\sQ_j$, $j \in \K$. 
Then, we know from \cite{Kat} (see also \cite[Section~2.3]{KLNS}) that 
the natural projection $\pi : X \rightarrow Y$ induces 
a surjective $R(T)$-module homomorphism $\pi_* : QK_T(X) \rightarrow QK_T(Y)$ 
such that $\pi_*(\CO^w \sQ^d) = \CO_{Y}^{\mcr{w}} \sQ^{[d]}$ 
for $w \in W$ and $d \in Q^{\vee,+}$, 
where $\mcr{w} \in W^{\Kc}$ is the minimal-length coset representative 
for the coset $w W_{\Kc}$, and such that 
%
\begin{equation}
\pi_*(\CO^{s_j} \star \CO^w) = \CO_{Y}^{s_j} \star \CO_{Y}^{\mcr{w}}
\end{equation}
%
for all $j \in K$, $w \in W$; 
note that $s_j \in W^{\Kc}$ for all $j \in K$. 
Let $i \in I$ be such that $i \in \K$; 
note that $\Kc \subset I \setminus \{i\}=\J$. 
Based on the result above, we deduce from the Chevalley formula 
(see Corollary~\ref{cor:NOS2}) in $QK_T(X)$ that in $QK_T(Y)$, 
%
\begin{equation} \label{eq:chev-p}
\CO^{s_i}_Y \star \CO^{w}_Y = 
\CO^{w}_Y -
\sum_{\bp \in \bQLS{w}} 
  (-1)^{\ell(\bp)}  \be^{-\vpi_{i}+\wt(\eta_{\bp})}
  \sQ^{[\qwt(\bp)]} \CO^{\mcr{\ed(\bp)}}_Y. 
\end{equation}
%
For $z \in \WK$, we set 
%
\begin{equation}
a_z^{\Kc}(\sQ_{\K}) := \sum_{d \in Q^{\vee,+}} M_{s_i,w}^{z,d} \sQ^d,
\end{equation}
%
which is an element of $R(T)[\sQ_{\K}] \subset R(T)\bra{\sQ_{\K}}$. 
Namely, we have in $QK_T(Y)$, 
%
\begin{equation*}
\CO^{s_i}_Y \star \CO^{w}_Y = 
\sum_{z \in \WK} a_{z}^{\Kc}(\sQ_{\K}) \CO^{z}_Y; 
\end{equation*}
%
if we set $c_{z}^{\Kc}:=a_{z}^{\Kc}(0) \in R(T)[\Lambda]$, 
then we have in $K_T(Y)$, 
%
\begin{equation}
\CO^{s_i}_Y \cdot \CO^{w}_Y = 
\sum_{z \in \WK} c_{z}^{\Kc} \CO^{z}_Y.
\end{equation}
%
Then, from the definition \eqref{eq:parabqmulti} of 
$\star$ in $QK_T(Y)$, we deduce that 
%
\begin{equation} \label{eq:3pt-p}
\sum_{ d \in \QKvp }
\sQ^{d} \langle \CO^{s_i}_Y, \CO^w_Y, \CO_x^Y \rangle_{d}^{Y} = 
\sum_{z \in \WK} a_{z}^{\Kc}(\sQ)
\sum_{ \xi \in \QKvp } \sQ^{\xi} \langle \CO^z_Y, \CO_x^Y \rangle_{\xi}^{Y}. 
\end{equation}
%
Here, the 2-point KGW invariants can be explicitly described in terms of the quantum Bruhat graph $\QBG(W)$ on $W$ as follows; 
recall the projection $[\,\cdot\,]=[\,\cdot\,]_{\K} : Q^{\vee} \twoheadrightarrow \QKv$, 
$\sum_{j \in I} c_{j}\alpha_{j}^{\vee} \mapsto 
 \sum_{j \in \K} c_{j}\alpha_{j}^{\vee}$, and that 
for $x \in W$, $\mxcr{x}=\mxcr{x}^{\Kc}$ 
denotes the maximal-length coset representative for the coset $xW_{\Kc}$. 

\begin{lem} \label{lem:ptwp}
Let $\xi \in Q^{\vee}_{\K}$. 
Let $z \in \WK$, and let $x \in W$ be such that $x = \mxcr{x}^{\Kc}$. 
Then, we have 
%
\begin{equation} \label{eq:2ptp-qwt}
\langle \CO^z_Y, \CO_x^Y \rangle_{\xi}^{Y} = 
%
\begin{cases}
1 & \text{\rm if $\xi \ge [\qwt(z \Rightarrow x)]$}, \\
0 & \text{\rm otherwise}.
\end{cases}
%
\end{equation}
%
\end{lem}

\begin{proof}
It follows from the definition of $\mathrm{dist}_{Y}(z, x)$ that $\mathrm{dist}_{Y}(z, x) = [\mathrm{dist}_X(z, x)]$. 
Also, by \cite[Lemma~4]{BCLM}, we know that $\mathrm{dist}_{X}(z, x) = \qwt(z \Rightarrow x)$ (in our notation). Therefore, we deduce that $\mathrm{dist}_{Y}(z, x) = [\qwt(z \Rightarrow x)]$. 
Hence, the assertion of the lemma immediately follows from \cite[Proposition~6]{BCLM}. 
This proves the lemma. 
\end{proof}
