\subsection{Proof of Theorem~\ref{thm:qk1p}.}
\label{subsec:prf-qk1p}

We can prove Theorem~\ref{thm:qk1p} by the same arguments as those for Theorem~\ref{thm:qk1}. 
We set 
%
\begin{equation*}
U^{\Kc}:=\bigl\{ z \in \WK \mid 
\text{$\mcr{\ed(\bp)} = z$ and $\qwt(\bp) = 0$ for some $\bp \in \bQLS{w}$} \bigr\}. 
\end{equation*}
%
We deduce that 
%
\begin{enu}
\item[\rm (a)'] if $z \in U^{\Kc}$, then 
$a_{z}^{\Kc}(\sQ_{\K}) \in c_{z}^{\Kc} + \sQ_{i}R(T)[\sQ_{\K}]$; 
%
\item[\rm (b)'] if $z \in \WK \setminus U^{\Kc}$, then $a_{z}^{\Kc}(\sQ_{\K}) \in 
\sQ_{i}R(T)[\sQ_{\K}]$, and hence $c_{z}^{\Kc} = 0$. 
\end{enu}
%
Now, let $d \in \QKvp$ be as in Theorem~\ref{thm:qk1p}. 
By exactly the same argument as that in the proof of Theorem~\ref{thm:qk1}, 
we deduce by (a)' and (b)', together with the condition $d_{i}=0$, that 
%
\begin{equation*}
\langle \CO^{s_i}_Y, \CO^w_Y, \CO_x^Y \rangle_{d}^{Y} = \sum_{z \in U^{\Kc}} c_{z}^{\Kc} \langle \CO^z_Y, \CO_x^Y \rangle_{d}^{Y} = 
\sum_{z \in \WK} c_{z}^{\Kc} \langle \CO^z_Y, \CO^Y_x \rangle_{d}^{Y}, 
\end{equation*}
%
as desired. This completes the proof of Theorem~\ref{thm:qk1p}. 
