\subsection{Proof of Theorem~\ref{thm:qk2p}.}
\label{subsec:prf-qk2p}

We can prove Theorem~\ref{thm:qk2p} 
by the same arguments as those for Theorem~\ref{thm:qk2}. 
By using \eqref{eq:chev-p} and \eqref{eq:3pt-p}, we deduce that
%
\begin{align} 
& \sum_{d \in \QKvp}
  \sQ^{d} \langle \CO^{s_i}_Y, \CO^w_Y, \CO_x^Y \rangle_{d}^{Y} 
  = \sum_{\xi \in \QKvp} \sum_{z \in \WK} \delta_{w,z} \sQ^{\xi} \langle \CO^z_Y, \CO_x^Y \rangle_{\xi}^{Y}
  \nonumber \\
& - 
\sum_{\xi \in \QKvp} 
\sum_{ \bp \in \bQLS{w} } (-1)^{\ell(\bp)} 
\be^{-\vpi_{i}+\wt(\eta_{\bp})}
\sQ^{ [\qwt(\bp)] + \xi } \langle \CO^{\mcr{\ed(\bp)}}_Y, \CO_x^Y \rangle_{\xi}^{Y}. \label{eq:qk2p-1}
\end{align}
%
Let $d \in \QKvp$ be as in Theorem~\ref{thm:qk2p}. 
By Lemma~\ref{lem:ptwp}, we obtain 
%
\begin{equation*}
\langle \CO^{s_i}_Y, \CO^{w}_Y, \CO_x^Y \rangle_{d}^{Y}
= \langle \CO^w_Y, \CO_x^Y \rangle_{d}^{Y} - 
\sum_{ \begin{subarray}{c} \bp \in \bQLS{w} \\ 
  [ \qwt(\mcr{\ed(\bp)} \Rightarrow x) ] \le d-[\qwt(\bp)] \end{subarray} }
(-1)^{\ell(\bp)}\be^{-\vpi_{i}+\wt(\eta_{\bp})}.
\end{equation*}
%
It follows from \cite[Lemma~7.2]{LNSSS2} that 
$[ \qwt(\mcr{\ed(\bp)} \Rightarrow x) ] = [ \qwt(\ed(\bp) \Rightarrow x) ]$. 
Therefore, 
%
%%%%%%%%%%%%%%%%%
%%% eq:qk2p-2 %%%
%%%%%%%%%%%%%%%%%
%
\begin{equation} \label{eq:qk2p-2}
\langle \CO^{s_i}_Y, \CO^w_Y, \CO_x^Y \rangle_{d}^{Y}
= \langle \CO^w_Y, \CO_x^Y \rangle_{d}^{Y} - 
\sum_{ \bp \in \pbQLS{w,x,d} }
(-1)^{\ell(\bp)}\be^{-\vpi_{i}+\wt(\eta_{\bp})}.
\end{equation}
%
We set 
%
\begin{align}
\pbQLS{w,x,d,+} & = \bigl\{ \bp \in \pbQLS{w,x,d} \mid \pair{\vpi_{i}}{d-\qwt_{2}(\bp)} > 0 \bigr\}, \\
\pbQLS{w,x,d,0} & = \bigl\{ \bp \in \pbQLS{w,x,d} \mid \pair{\vpi_{i}}{d-\qwt_{2}(\bp)} = 0 \bigr\}; 
\end{align}
%
note that $\pbQLS{w,x,d} = \pbQLS{w,x,d,+} \sqcup \pbQLS{w,x,d,0}$, and 
$\pbR{w,x,d} \subset \pbQLS{w,x,d,0}$. In order to prove Theorem~\ref{thm:qk2p}, 
we need to show the following (cf. Proposition~\ref{prop:qk2}): 
%
\begin{equation} \label{eq:qk2p-a}
 \sum_{ \bp \in \pbQLS{w,x,d,+} }
(-1)^{\ell(\bp)}\be^{-\vpi_{i}+\wt(\eta_{\bp})} = 0, 
\end{equation}
%
\begin{equation} \label{eq:qk2p-b}
 \sum_{ \bp \in \pbQLS{w,x,d,0} \setminus \pbR{w,x,d} }
(-1)^{\ell(\bp)}\be^{-\vpi_{i}+\wt(\eta_{\bp})} = 0. 
\end{equation}
%
The proof of equation \eqref{eq:qk2p-a} is similar to that of equation \eqref{eq:qk2-1}. 
Recall the sijection $\Theta$ on $\bQLS{w}$. We set 
%
\begin{align*}
\bA^{\K} & := \bigl\{ (\bp_{N},\dots,\bp_{2},\bp_{1}) \in \pbQLS{w,x,d,+} \mid 
  \FL{\bp_{1}} = \alpha_{i} \bigr\}, \\
\bB^{\K} & := \bigl\{ (\bp_{N},\dots,\bp_{2},\bp_{1}) \in \pbQLS{w,x,d,+} \mid 
  \FL{\bp_{1}} \ne \alpha_{i} \bigr\}, \\
\bB^{\K}_{1} & := \bigl\{ \bp \in \bB^{\K} \mid \Theta(\bp) \in \pbQLS{w,x,d,+} \bigr\}, \\
\bB^{\K}_{2} & := \bigl\{ \bp \in \bB^{\K} \mid \Theta(\bp) \not\in \pbQLS{w,x,d,+} \bigr\}. 
\end{align*}
%
By the same arguments as that for Lemma~\ref{lem:Theta1} (and that after its proof), 
we can verify that $\Theta(\bp) \in \bB^{\K}_{1}$ for all $\bp \in \bA^{\K}$, 
and hence that $\Theta$ is a sijection on the set $\bA^{\K} \sqcup \bB^{\K}_{1}$. 
Also, a sijection $\Theta'$ on $\bB^{\K}_{2}$ can be defined in exactly the same way as the one 
on $\bB_{2}$ as follows. Let $\bp = (\bp_{N},\dots,\bp_{2},\bp_{1}) \in \bB^{\K}_{2}$, 
and set $z := \ed(\bp)$. We define $\beta$ and $\gamma$ in the same manner as 
in \eqref{eq:beta} and \eqref{eq:gamma}, respectively.
As in Lemma~\ref{lem:s1} and Remark~\ref{rem:bg}, we deduce that 
$\beta \ne \alpha_{i}$, $\gamma \ne \alpha_{i}$, and $\beta \ne \gamma$. 
Then, we define $\Theta'(\bp_{1})$ in exactly the same way as in (i) and (ii), 
and set $\Theta'(\bp):= (\bp_{N},\dots,\bp_{2},\Theta'(\bp_{1}))$. 
By replacing $\qwt(\bullet)$, $\beta^{\vee}$, $\gamma^{\vee}$ in Cases 1 and 2 
in the proof of equation \eqref{eq:qk2-1} by $[\qwt(\bullet)]$, $[\beta^{\vee}]$, $[\gamma^{\vee}]$, 
respectively, we can show that $\Theta'(\bp) \in \bB^{\K}_{2}$. 
Thus, we have defined a sijection $\Theta'$ on $\bB^{\K}_{2}$. 
By using the sijections $\Theta$ (on $\bA^{\K} \sqcup \bB^{\K}_{1}$) and 
$\Theta'$ (on $\bB^{\K}_{2}$), we can prove equation \eqref{eq:qk2p-a}, as desired. 

The proof of equation \eqref{eq:qk2p-b} is also similar to that of equation \eqref{eq:qk2-2}. 
For simplicity of notation, we set
%
\begin{equation}
\pbS{w,x,d}:=\pbQLS{w,x,d,0} \setminus \pbR{w,x,d}. 
\end{equation}
%
Let $\bp = (\bp_{N},\dots,\bp_{2},\bp_{1}) \in \pbS{w,x,d}$, and set $z:=\ed(\bp)$. 
Let $\beta$ and $\gamma$ be as above. Then, we see that \eqref{eq:bg2} in this case, too. 
Also, by the same argument as that after \eqref{eq:bg2}, 
we deduce that $(\beta,\gamma) \ne (\alpha_{i},\alpha_{i})$, and hence $\beta \ne \gamma$. 
We now define $\Psi(\bp_{1})$ in exactly the same way as in (iii) and (iv), 
and set $\Psi(\bp):= (\bp_{N},\dots,\bp_{2},\Psi(\bp_{1}))$. 
By replacing $\qwt(\bullet)$ in the proof of \eqref{eq:qk2-2} 
by $[\qwt(\bullet)]$, we can show that $\Psi(\bp) \in \pbS{w,x,d}$. 
Thus, we have defined a sijection $\Psi$ on $\pbS{w,x,d}$. 
By using the sijection $\Psi$, we can prove \eqref{eq:qk2p-b}, as desired. 
This completes the proof of Theorem~\ref{thm:qk2p}. 

