\section{The case that $\QLS(\vpi_{i})=\LS(\vpi_{i})$ and $d_{i} > 0$.}
\label{sec:QLS=LS}
%
%%%%%%%%%%%%%%%
%%% dfn:LS %%%
%%%%%%%%%%%%%%%
%
\begin{dfn}[{\cite{Lit94} and \cite{Lit95}}] \label{dfn:LS}
Let $\lambda \in \Lambda^{+}$ be a dominant (integral) weight, and set $\J=\J_{\lambda} = 
\bigl\{ j \in I \mid \pair{\lambda}{\alpha_{j}^{\vee}} = 0 \bigr\}$. 
A Lakshmibai-Seshadri path (LS path for short) 
of shape $\lambda$ is an element $\eta \in \QLS(\lambda)$ 
of the form \eqref{eq:QLS} satisfying the condition that 
all the edges in a directed path in $\QBG_{a_{k}\nu}(\WJ)$ 
from $w_{k+1}$ to $w_{k}$ are Bruhat edges for all $k = 1,\,2,\,\dots,\,s-1$.
\end{dfn}

Let $\LS(\lambda)$ denote 
the set of all LS paths of shape $\lambda$; 
note that $\LS(\lambda) \subset \QLS(\lambda)$. 
In this appendix, we fix $i \in I$ such that
%
\begin{equation} \label{eq:QLS=LS}
\QLS(\vpi_{i}) = \LS(\vpi_{i}).
\end{equation}
%
We know from \cite[Lemma~2.14]{MNS} that 
condition \eqref{eq:QLS=LS} is equivalent to the equality 
$\pair{\vpi_{i}}{\theta^{\vee}}=1$, 
where $\theta \in \Delta^{+}$ is the highest root. 
The following is the list of such $i$'s, 
where our numbering of the nodes of a Dynkin diagram is the same as that in \cite[Section 11.4]{H}: 
%
\begin{center}
%
\begin{tabular}{l|l}
$A_{n}$ & all $i \in I$ (minuscule) \\ \hline
$B_{n}$ & $i = 1$ (cominuscule), $i = n$ (minuscule), \\
 & with $\alpha_{n}$ the unique short simple root \\ \hline
$C_{n}$ & all $i \in I$ ($\vpi_{1}$ is the unique minuscule weight), \\ 
 & with $\alpha_{n}$ the unique long simple root \\ \hline
$D_{n}$ & $i = 1,\,n-1,\,n$ (minuscule) \\ \hline
$E_{6}$ & $i = 1,\,5$ (minuscule) \\ \hline
$E_{7}$ & $i = 6$ (minuscule)\\ \hline
$E_{8}$ & none \\ \hline
$F_{4}$ & $i = 4$ (not minuscule), with $\alpha_{4}$ a short simple root  \\ \hline
$G_{2}$ & $i = 1$ (not minuscule), with $\alpha_{1}$ the short simple root
\end{tabular}
%
\end{center}
%
In all the cases above, we have
%
\begin{equation}
\pair{\vpi_{i}}{\beta^{\vee}} \in \{0,1,2\} \quad 
\text{for all $\beta \in \Delta^{+}$}, 
\end{equation}
%
and hence we can take $N=N_{i}=2$. Note that 
if $\eta = (w_{1},w_{2}) \in \QLS(\vpi_{i})=\LS(\vpi_{i})$ 
(with the notation as in \eqref{eq:QLS2}), then 
$w_{1} \ge w_{2}$ in the Bruhat order $\ge$. 
Recall that $\J=\J_{\vpi_{i}}=I \setminus \{i\}$. 
%
%%%%%%%%%%%%%%%%%%%
%%% lem:tbmax-B %%%
%%%%%%%%%%%%%%%%%%%
%
\begin{lem} \label{lem:tbmax-B}
Let $v,w \in W$, and assume that $\mcr{w}^{\J} \le \mcr{v}^{\J}$ in the Bruhat order. 
If $w=\tbmax{w}{\J}{v}$, then $w \le v$ in the Bruhat order. 
\end{lem}

\begin{proof}
% By Lemma~\ref{lem:tbmax}, 
%there exists a label-increasing directed path $\bp$
% from $w$ to $v$ in $\QBG(W)$ whose labels of edges are all contained in 
%$\DJp$. It suffices to show that all the edges in $\bp$ are Bruhat edges, 
%or equivalently, $\wt(\bp) = 0$. 
%
We write $v$ as $v=\mcr{v}^{\J}z$ with $z \in \WJs$, and set $w':=\mcr{w}^{\J}z$. 
Since $w' \in w\WJs$, and since $w=\tbmax{w}{\J}{v}$, 
we deduce by the definition of $\dtb{v}$ that 
$\ell(w' \Rightarrow v) = 
 \ell(w' \Rightarrow w) + \ell(w \Rightarrow v)$. 
%
Hence, it follows that 
%
\begin{equation*}
\qwt(w' \Rightarrow v) = 
\qwt(w' \Rightarrow w) + \qwt(w \Rightarrow v). 
\end{equation*}
%
Also, since $\mcr{w}^{\J} \le \mcr{v}^{\J}$, 
it follows that $w'=\mcr{w}^{\J}z \le \mcr{v}^{\J}z=v$, 
which implies that $\qwt(w' \Rightarrow v) = 0$. 
Since $\qwt(w' \Rightarrow w) \ge 0$ and 
$\qwt(w \Rightarrow v) \ge 0$, we obtain 
$\qwt(w \Rightarrow v) = 0$. 
Therefore, we deduce that $w \le v$, as desired. 
This proves the lemma. 
\end{proof}
%
%%%%%%%%%%%%%%%
%%% cor:qk2 %%%
%%%%%%%%%%%%%%%
%
\begin{cor} \label{cor:qk2}
Let $i \in I$ be such that $\QLS(\vpi_{i})=\LS(\vpi_{i})$. 
Let $w,x \in W$, and let $d=\sum_{j \in I} d_{j} \alpha_{j}^{\vee} \in Q^{\vee,+}$ with $d_{i} > 0$. 
Then, we have $\bR{w,x,d} = \emptyset$, and hence
%
\begin{equation} \label{eq:qk2c}
\thp{s_i}{w}{x}_{d} =  
\twp{w}{x}_{d}.
\end{equation}
%
\end{cor}

\begin{proof}
We will show that $\pair{\vpi_{i}}{d-\qwt_{2}(\bp)} > 0$
for all $\bp=(\bp_{2},\bp_{1}) \in \bQLS{w,x,d}$. 
%
Recall that $\eta_{\bp}=(\mcr{\ed(\bp_{2})}^{\J}, \mcr{w}^{\J}) \in \QLS(\vpi_{i})$. 
Since $\QLS(\vpi_{i}) = \LS(\vpi_{i})$, we have $\mcr{\ed(\bp_{2})}^{\J} \ge \mcr{w}^{\J}$ 
in the Bruhat order $\ge$ on $\WJ$. 
%
By Lemma~\ref{lem:tbmax}, we have $w = \tbmax{w}{\J}{\ed(\bp_{2})}$. 
By Lemma~\ref{lem:tbmax-B}, together with the fact that 
$\mcr{\ed(\bp_{2})}^{\J} \ge \mcr{w}^{\J}$, 
we have $\ed(\bp_{2}) \ge w$ in the Bruhat order, 
which implies that $\qwt_{2}(\bp) = \qwt(\bp_{2}) = 0$. 
Therefore, we deduce that $\pair{\vpi_{i}}{d-\qwt_{2}(\bp)} = 
\pair{\vpi_{i}}{d} = d_{i} > 0$, as desired. 
This proves the corollary. 
\end{proof}
%
We also have the following parabolic analogue of Corollary~\ref{cor:qk2}. 
%
%%%%%%%%%%%%%%%%
%%% cor:qk2p %%%
%%%%%%%%%%%%%%%%
%
\begin{cor} \label{cor:qk2p}
Let $i \in I$ be such that $\QLS(\vpi_{i})=\LS(\vpi_{i})$, 
with $i \in K \subset I$. 
Let $w \in \WK$, and assume that $x \in W$ satisfies $\mxcr{x}^{\Kc}=x$. 
Let $d=\sum_{j \in \K} d_{j} \alpha_{j}^{\vee} \in Q^{\vee,+}_{\K}$ 
with $d_{i} > 0$. Then, we have $\pbR{w,x,d} = \emptyset$, and hence
%
\begin{equation} \label{eq:qk2pc}
\langle \CO^{s_i}_Y, \CO^w_Y, \CO_x^Y \rangle_{d}^{Y} =  
 \langle \CO^w_Y, \CO_x^Y \rangle_{d}^{Y}.
\end{equation}
%
\end{cor}

\begin{proof}
We will show that $\pair{\vpi_{i}}{d-[\qwt_{2}(\bp)]} > 0$
for all $\bp=(\bp_{2},\bp_{1}) \in \pbQLS{w,x,d}$. 
%
By exactly the same argument as that in the proof of Corollary~\ref{cor:qk2}, 
we can show that $\qwt_{2}(\bp) = \qwt(\bp_{2}) = 0$. 
Hence, we deduce that $\pair{\vpi_{i}}{d-[\qwt_{2}(\bp)]} = 
\pair{\vpi_{i}}{d} = d_{i} > 0$, as desired. 
This proves the corollary. 
\end{proof}

