\section{Relationship between bases.}
\label{sec:basis}

Let $(\CO^x)^{\vee} \in K_T(X)$, $x \in W$, 
denote the basis of $K_T(X)$ dual to $\CO^x$, $x \in W$, 
in the sense that $\chi^T_X((\CO^{x})^{\vee} \cdot \CO^{y}) = 
\delta_{x, y}$ for $x, y \in W$, 
where $\chi^T_X$ is the ($T$-equivariant) pushforward 
along the structure morphism of $X$.
In fact, for $x \in W$, $(\CO^x)^{\vee}$ is the class of 
the ideal sheaf $\CI_{\partial X_x}$ of 
the boundary $\partial X_x$ of $X_x$, and we have 
%
\begin{equation} \label{eq:basis1}
(\CO^x)^{\vee} = 
 \sum_{\substack{y \in W \\ y \leq x}} (-1)^{\ell(x) - \ell(y)} \CO_y, \qquad 
\CO_x = \sum_{\substack{y \in W \\ y \leq x}} (\CO^{y})^{\vee}. 
\end{equation}
%
Also, for $x \in W$, $(\CO_{x})^{\vee}$ is 
the class of the ideal sheaf $\CI_{\partial X^x}$ of 
the boundary $\partial X^x$ of $X^x$, and we have
%
\begin{equation} \label{eq:basis2}
(\CO_x)^{\vee} = \sum_{\substack{y \in W \\ y \geq x}} 
(-1)^{\ell(x) - \ell(y)} \CO^y, \qquad 
\CO^x = \sum_{\substack{y \in W \\ y \geq x}} (\CO_y)^{\vee}.
\end{equation}
%
Here, $\leq$ denotes the Bruhat order on $W$. 
%
%%%%%%%%%%%%%%%
%%% ex:G2-B %%%
%%%%%%%%%%%%%%%
%
\begin{ex}[{cf. \cite[Section~4.2]{LM}}] \label{ex:G2-B}
As in Examples~\ref{ex:G2-1} and \ref{ex:G2-2}, 
we assume that $\Fg$ is of type $G_{2}$, and $i = 2$. 
Let $w=s_{2}s_{1}s_{2}s_{1}s_{2}$, and  
$d = d_{1}\alpha_{1}^{\vee}+2\alpha_{2}^{\vee} \in Q^{\vee,+}$ 
with $d_{1} \in \BZ_{> 0}$. Since 
%
\begin{equation*}
\langle \CO^{s_2},\CO^{w},(\CO^{x})^{\vee} \rangle_{d} =  
\sum_{y \le x} (-1)^{\ell(x) - \ell(y)} 
\thp{s_2}{w}{y}_{d}, 
\end{equation*}
%
we have
%
\begin{align*}
& \langle \CO^{s_2},\CO^{w},(\CO^{e})^{\vee} \rangle_{d} = 
\thp{s_2}{w}{e}_{d} = 1+\be^{-\vpi_{2}}, \\
%
& \langle \CO^{s_2},\CO^{w},(\CO^{s_{2}})^{\vee} \rangle_{d} = 
\thp{s_2}{w}{s_{2}}_{d} - \thp{s_2}{w}{e}_{d} = 1-(1+\be^{-\vpi_{2}}) = -\be^{-\vpi_{2}}. 
\end{align*}
%
Also, since 
%
\begin{equation*}
\thp{s_2}{w}{s_{1}}_{d} - \thp{s_2}{w}{e}_{d} = 
\twp{w}{s_{1}}_{d} - \twp{w}{e}_{d}, 
\end{equation*}
%
\begin{equation*}
\thp{s_2}{w}{y}_{d} = 
\twp{w}{y}_{d} \quad \text{for all $y \in W \setminus \{e,s_2\}$}, 
\end{equation*}
%
it follows that for $x \in W \setminus \{s_{2},e\}$ (note that $x \ge s_{1} > e$),
%
\begin{align*}
\langle \CO^{s_2},\CO^{w},(\CO^{x})^{\vee} \rangle_{d} & =  
%
\sum_{y \le x} (-1)^{\ell(x) - \ell(y)} 
\thp{s_2}{w}{y}_{d} \\
%
& =
%
\sum_{y \le x} (-1)^{\ell(x) - \ell(y)} 
\twp{w}{y}_{d} =
\sum_{y \le x} (-1)^{\ell(x) - \ell(y)} = 0.
\end{align*}
%
\end{ex}

