\section{A Peterson comparison formula in quantum K theory (Notes by Mihalcea and Xu).}
\label{sec:MX}

In this Appendix, we state a comparison formula for the $K$-theoretic GW invariants on \(G/P\)'s, generalizing the similar formula 
in cohomology, conjectured by Peterson \cite{Pet97} and proved by Woodward \cite{Woo}. 
Most of our arguments can be found, implicitly or explicitly, in Woodward's proof, but we indicate here the 
modifications needed to work in $K$-theory. In particular, the key fact that the natural map 
$\Mb_{0,3}(G/B, \dl{d}) \to \Mb_{0,3}(G/P, d)$ induced by the natural projection of flag manifolds $G/B \to G/P$ is cohomologically trivial, may be deduced directly from arguments in Woodward's proof. We use the comparison formula to give an alternative proof of Theorem~\ref{thm:parabolic} in the Introduction. 

Let \(K\subseteq J\) be subsets of \(I\). Let \(P\) and \(Q\) be parabolic subgroups of \(G\) containing \(B\) corresponding to the subsets \(I\setminus K\) and \(I\setminus J\), respectively. Let $\pi_{J\setminus K} : G/Q \to G/P$ be the natural projection. 
For \(d\in H_2(G/P; \mathbb{Z})\), let $\Hom_{d}(G/P)$ denote the set of morphisms $\mathbb{P}^1 \to G/P$ of degree $d$. 
It is known that when non-empty, it is a smooth, connected, reduced quasiprojective 
scheme and a dense open subset 
of the moduli space \(\Mb_{0,3}(G/P, d)\) of \(3\)-point, degree \(d\) maps to \(G/P\); 
see \cite{Tho,FP}. It is also known to be a rational 
variety \cite{KP}. 
Locally, the moduli space may be realized as a smooth space modulo 
a finite group (see, e.g., \cite{FP}), therefore it has rational singularities \cite{Bou}.


Recall from Section~\ref{sec:para} the definition of the Peterson lift \(\dl{d}\) of \(d\). It was stated by Peterson and proved by Woodward in \cite[Lemma 1]{Woo} that if \(\Hom_{d}(G/P)\) is non-empty, so is \(\Hom_{\dl{d}}(G/B)\). 
This $\dl{d}$ determines a parabolic subgroup $P^{\prime} \subseteq P$ containing \(B\) corresponding to the subset
\[
I\setminus K^{\prime} \coloneqq \{j\in I\setminus K \mid \angles{\alpha_j,\dl{d}}=0\}.
\] 
Let \[d^{\prime} \coloneqq \left(\pi_{I\setminus K^{\prime}}\right)_*\dl{d}\quad \in H_2(G/P^{\prime}; \mathbb{Z}).\]

The main result proved by Woodward \cite[Theorem 3]{Woo} is the following.

\begin{thm}[{\cite{Woo}}] \label{thm:woodward}
The following hold. 
\begin{enumerate}
\item The morphism $\mathrm{Hom}_{\dl{d}}(G/B) \to \mathrm{Hom}_{d^{\prime}}(G/P^{\prime}) \times_{G/P^{\prime}} G/B$ given by $f \mapsto (\pi_{I\setminus K^{\prime}} \circ f, f(0))$ is an open, dense immersion; 
\item The morphism $\mathrm{Hom}_{d^{\prime}}(G/P^{\prime}) \to \mathrm{Hom}_{d}(G/P)$ given by $f\mapsto\pi_{K^{\prime} \setminus K} \circ f$ is birational. 
\end{enumerate}
\end{thm} 

A morphism $f: X \to Y$ of irreducible varieties is said to be \emph{cohomologically trivial} if $f_* \cO_X = \cO_Y$ and $R^i f_* \cO_X = 0$ for $i>0$. A result of Koll\'ar \cite{Kol} shows that if $f$ is surjective, $X$ and \(Y\) are projective with rational singularities, and the general fibers of $f$ are rationally connected, then $f$ is cohomologically trivial; we refer to \cite[Theorem 3.1]{BM1} and \cite[Proposition 5.2]{BCMP1} for details.  This, together with the previous theorem, implies the following. 

\begin{cor}\label{cor:cohtriv} The natural morphisms \[ \Mb_{0,3}(G/B,\dl{d}) \to \Mb_{0,3}(G/P^{\prime}, d^{\prime}) \times_{G/P^{\prime}} G/B, \quad \Mb_{0,3}(G/P^{\prime},d^{\prime}) \to \Mb_{0,3}(G/P, d)\] are birational, surjective, and cohomologically trivial.\end{cor}

\begin{rem} This corollary also appears on \cite[page 8]{Woo}, and it leads to the main calculation of the Peterson comparison formula.\end{rem}
\begin{cor}\label{cor:cohtriv-final} 
The natural map $\Mb_{0,3}(G/B, \dl{d}) \to \Mb_{0,3}(G/P, d)$ is cohomologically trivial.\end{cor}
\begin{proof} This follows from Corollary~\ref{cor:cohtriv} and either \cite[Lemma~2.4]{BCMP2} or \cite[Proposition~1.7]{BPX}. 
\end{proof}

Recall that $\pi:X=G/B \to Y=G/P$ denotes the natural projection and 
$\Phi: \Mb_{0,3}(X, \dl{d}) \to \Mb_{0,3}(Y, d)$ denotes the induced map. 
\begin{prop}\label{prop:Kcomparison} Let $a,b,c \in K_T(Y)$, and $d \in H_2(Y; \mathbb{Z})$ an effective degree. Then, there is an equality of KGW invariants: 
\[ \langle a , b, c \rangle^{Y}_{d} = \langle \pi^*(a) ,\pi^*(b), \pi^*(c) \rangle_{\dl{d}} \/. \]
\end{prop}
\begin{proof} We have a commutative diagram: 
%
\begin{equation*}
%
\begin{CD}
\Mb_{0,3}(X,\dl{d}) @>{EV}>> X \times X \times X \\
@V{\Phi}VV @ VV{\pi \times \pi \times \pi}V \\
\Mb_{0,3}(Y,d) @>{EV_{Y}}>> Y \times Y \times Y, 
\end{CD}
%
\end{equation*}
%
% \[ \xymatrix{\Mb_{0,3}(X,\dl{d}) \ar[rr]^{EV} \ar[d]^{\Phi}&&
% X \times X \times X \ar[d]^{\pi \times \pi \times \pi} \\
% \Mb_{0,3}(Y,d) \ar[rr]^{EV_Y} &&  Y \times Y \times Y}\]
%
where $EV$ and $EV_Y$ are the triple products of evaluation maps at the three marked points in $X$ and $Y$, respectively. 
Starting from the definition of KGW invariants, we see that 
\[ \begin{split} \langle a , b, c \rangle^{Y}_{d} & = \chi^T_{\Mb_{0,3}(Y,d)}(EV_Y^*(a \times b \times c) \cdot [\cO_{\Mb_{0,3}(Y,d)}]) \\ 
& = \chi^T_{\Mb_{0,3}(Y,d)}(EV_Y^*(a \times b \times c) \cdot \Phi_*[\cO_{\Mb_{0,3}(X,\dl{d})}]) \\
& = \chi^T_{\Mb_{0,3}(X,\dl{d})}(\Phi^* EV_Y^*(a \times b \times c) \cdot [\cO_{\Mb_{0,3}(X,\dl{d})}]) \\
& = \chi^T_{\Mb_{0,3}(X,\dl{d})}(EV^*(\pi^*(a) \times \pi^*(b) \times \pi^*(c)) \cdot [\cO_{\Mb_{0,3}(X,\dl{d})}]) \\
& = \langle \pi^*(a) ,\pi^*(b), \pi^*(c) \rangle_{\dl{d}} \/. 
\end{split}
\]
Here, the second equality follows from the cohomological triviality in Corollary~\ref{cor:cohtriv-final}, {the third equality follows from the projection formula \cite[Chap.~5, Sect.~5.3.12]{CG}, and the fourth equality is just using that the diagram commutes.} This proves the proposition. \end{proof} 

We also give an alternative proof of Theorem~\ref{thm:parabolic}. 

\vspace{0.5pc}

\noindent
{\it Alternative proof of Theorem~\ref{thm:parabolic}}. 
  Note that for $i \in K$, \(d_i=0\) if and only if \(\dl{d}_i=0\). 

  Using Proposition~\ref{prop:Kcomparison}, Theorem~\ref{thm:qk1}, and Corollary~\ref{cor:qk2p}, we see that 
  \begin{align*}
    &\langle \CO^{s_i}_Y, \CO^u_Y, \CO_v^Y \rangle_{d}^{Y}=\gw{\pi^*(\CO^{s_i}_Y),\pi^*(\CO^u_Y),\pi^*(\CO_v^Y)}{\dl{d}}=\gw{\CO^{s_i},\pi^*(\CO^u_Y),\pi^*(\CO_v^Y)}{\dl{d}},
  \end{align*}
  and when \(d_i>0\) and $\pair{\vpi_i}{\theta^{\vee}} = 1$,
  \begin{align*}
    \gw{\CO^{s_i},\pi^*(\CO^u_Y),\pi^*(\CO_v^Y)}{\dl{d}}=\gw{\pi^*(\CO^u_Y),\pi^*(\CO_v^Y)}{\dl{d}}=\langle \CO_{Y}^{u}, \CO^{Y}_{v} \rangle_{d}^Y; 
  \end{align*}
  when \(d_i=0\), we see that 
  \begin{align*}
    &\gw{\CO^{s_i},\pi^*(\CO^u_Y),\pi^*(\CO_v^Y)}{\dl{d}} = \gw{\pi^*(\CO^{s_i}_Y)\cdot\pi^*(\CO^u_Y),\pi^*(\CO_v^Y)}{\dl{d}} = \gw{\pi^*(\CO^{s_i}_Y)\cdot\pi^*(\CO^u_Y),\pi^*(\CO_v^Y),\cO_X}{\dl{d}} \\ &= \gw{\pi^*(\CO^{s_i}_Y\cdot\CO^u_Y),\pi^*(\CO_v^Y),\pi^*(\cO_Y)}{\dl{d}} = \angles{\CO^{s_i}_Y\cdot\CO^u_Y,\CO_v^Y,\cO_Y}_{d}^Y = \angles{\CO^{s_i}_Y\cdot\CO^u_Y,\CO_v^Y}_{d}^Y,
  \end{align*}
  where we have used the (simplest case of the) string equation and the fact that \(\pi^*(\cO_Y)=\cO_X\) for the natural projection \(\pi:X\to Y\). This proves Theorem~\ref{thm:parabolic}. 

\vspace{0.5pc}

Also, using similar arguments, we can deduce the following from Theorems~\ref{thm:qk2} and \ref{thm:qk2p}. 
\begin{prop}
  \[
    \sum_{ \bp \in \bR{w,x,\dl{d}} }
    (-1)^{\ell(\bp)}\be^{-\vpi_{i}+\wt(\eta_{\bp})}=\sum_{ \bp \in \pbR{w,x,d} }
    (-1)^{\ell(\bp)}\be^{-\vpi_{i}+\wt(\eta_{\bp})}. 
  \]
\end{prop}

It would be interesting to find a purely combinatorial proof of this proposition. 

