\caption{Pipelines for Augmenters and Annotators}
\begin{tabular}{c}
\toprule
\textbf{Algorithm 1: Pipeline for Each Augmenter} \\

\begin{minipage}{0.95\linewidth}
\begin{algorithm}[H]
\begin{algorithmic}[1]
\Require Definition of SDoH category $D$, Raw note $N$
\Ensure Optimized prompt, Verified augmented notes
\State \textbf{Model:} LLM
\State $input\_prompt \gets D$ \Comment{Initialize with category definition}
\While{True}
    \State $augmented\_notes \gets \{\}$
    \State $output \gets$ LLM($input\_prompt$) \Comment{Generate notes based on $D$ and $N$}
    \For{each note $n$ in $output$}
        \State $verification, feedback \gets$ HumanVerify($n$)
        \If{$verification == \text{True}$}
            \State $augmented\_notes \gets augmented\_notes \cup \{n\}$
        \Else
            \State Save $feedback$
        \EndIf
    \EndFor
    \State $accuracy \gets \frac{\text{Number of True verifications}}{\text{Total number of notes}}$
    \If{$accuracy \geq 0.90$}
        \State \textbf{break}
    \Else
        \State $input\_prompt \gets$ OptimizePrompt($input\_prompt$, $feedback$)
    \EndIf
\EndWhile
\State \Return $input\_prompt$, $augmented\_notes$
\end{algorithmic}
\end{algorithm}
\label{alg:augmenter_pipeline}
\end{minipage}
\\

