    \toprule
    \textbf{Model} & \textbf{Peak memory (GiB)} & \textbf{Adaptation time (ms)} \\
    \midrule
    Masked Transformer & $1.39$ & $18.38 \pm 4.03$ \\
    Baseline GRU         & $2.91$ & $28.44 \pm 8.33$ \\
    \bottomrule
