    \State $\ddot{\bm{\theta}}_{ref}[k] = \bm{M}(\bm{\theta}[k-1])^{-1} \left ( \bm{\tau}_{u}[k] + \hat{\bm{\tau}}_{ext}[k-1] \right)$
    \State $\dot{\bm{\theta}}_{int-HPF}[k] \gets \frac{2 - 2\omega_c T}{2 + 2\omega_c T} \bm{\theta}_{int-HPF}[k-1] + \frac{T}{2 + 2\omega_c T} \left(\ddot{\bm{\theta}}_{ref}[k] + \ddot{\bm{\theta}}_{ref}[k-1]\right)$ 
    \Statex \Comment{Integral and 1st-order HPF}
    % \State $\bm{\theta}_{lpf} \gets \frac{2\omega_c}{s+2\omega_c} \bm{\theta}_k$
    \State $\bm{\theta}_{LPF-VOB}[k] \gets \frac{2 - 2\omega_c T}{2 + 2\omega_c T} \bm{\theta}_{LPF-VOB}[k-1] + \frac{2\omega_c T}{2 + 2\omega_c T} \left(\bm{\theta}[k] + \bm{\theta}[k-1]\right)$ \Comment{1st-order LPF}
    % \State $\dot{\bm{\theta}}_{pseudo-diff} \gets 2\omega_c(1-\frac{2\omega_c}{s+2\omega_c}) \bm{\theta}_k$
    \State $\dot{\bm{\theta}}_{pdiff-VOB}[k] \gets 2\omega_c( \bm{\theta}[k] - \bm{\theta}_{LPF-VOB}[k])$ \Comment{Pseudo differential}
    \State $\hat{\dot{\bm{\theta}}}[k] \gets \dot{\bm{\theta}}_{int-HPF}[k] + \dot{\bm{\theta}}_{pdiff-VOB}[k]$

    \Statex
    \Statex \text{// --- External Force Estimation ---}
    % \State $\bm{\tau}_{u, lpf} \gets \frac{\omega_c}{s+\omega_c} \bm{\tau}_{u}$ \Comment{1st-order LPF}
    \State $\bm{\tau}_{u, LPF}[k] \gets \frac{2 - \omega_c T}{2 + \omega_c T} \bm{\tau}_{u, LPF}[k-1] + \frac{\omega_c T}{2 + \omega_c T} \left(\bm{M}(\bm{\theta}[k])^{-1}\bm{\tau}_{u}[k] + \bm{M}(\bm{\theta}[k])^{-1}\bm{\tau}_{u}[k-1]\right)$
    % \Comment{1st-order LPF}
    \State $\bm{\theta}_{LPF-FOB}[k] \gets \frac{2 - \omega_c T}{2 + \omega_c T} \bm{\theta}_{LPF-FOB}[k-1] + \frac{\omega_c T}{2 + \omega_c T} \left(\bm{\theta}[k] + \bm{\theta}[k-1]\right)$ \Comment{1st-order LPF}
    % \State $\dot{\bm{\theta}}_{pdiff-FOB} \gets \omega_c(1-\frac{\omega_c}{s+\omega_c})\bm{\theta}_k$ \Comment{Pseudo differential}
    \State $\dot{\bm{\theta}}_{pdiff-FOB}[k] \gets \omega_c( \bm{\theta}[k] - \bm{\theta}_{LPF-FOB}[k])$ \Comment{Pseudo differential}
    \State $ \bm{temp}[k] \gets \bm{\tau}_{u, LPF} + \omega_c\dot{\bm{\theta}}_{pdiff-FOB}$
    % \State $\bm{tmp}_{lpf} \gets \frac{\omega_c}{s+\omega_c}\bm{tmp}$ \Comment{1st-order LPF}
    \State $\bm{temp}_{LPF}[k] \gets \frac{2 - \omega_c T}{2 + \omega_c T} \bm{temp}_{LPF}[k-1] + \frac{\omega_c T}{2 + \omega_c T} \left(\bm{temp}[k] + \bm{temp}[k-1]\right)$ \Comment{1st-order LPF}
    \State $\hat{\bm{\tau}}_{ext}[k] = \bm{M}(\bm{\theta}[k])\left(-\bm{temp}_{LPF} + \omega_c \dot{\bm{\theta}}_{pdiff-FOB}\right)$
    % \State $\hat{\bm{\tau}}_{ext}[k]=\bm{M}(\bm{\theta}[k])\left\{\bm{M}(\bm{\theta}[k])^{-1}\hat{\bm{\tau}}_{ext}[k]\right\}$

    \Statex
    % \Statex
    % \Comment{Controller}
    \Statex \text{// --- Controller ---}
    \State $\ddot{\bm{\theta}}_{ref}[k+1] \gets \bm{K}_p(\bm{\theta}_{des}[k] - \bm{\theta}[k]) + \bm{K}_d(\dot{\bm{\theta}}_{des}[k] - \hat{\dot{\bm{\theta}}}[k]) + \bm{K}_f(\bm{\tau}_{des}[k] + \hat{\bm{\tau}}_{ext}[k])$

    \State $\bm{\tau}_{u}[k+1] \gets \tilde{\bm{M}}(\bm{\theta}[k])\ddot{\bm{\theta}}_{ref}[k+1] - \hat{\bm{\tau}}_{ext}[k]$

    \Statex
    \For{$i = 0$ to JOINT-NUM} \Comment{Torque limit}
    \If{$\bm{\tau}_{u}[k+1][i] + \tilde{\bm{h}}(\bm{\theta}[k], \hat{\dot{\bm{\theta}}}[k])[i] > \bm{\tau}_{limit}[i] $} 
    \State $\bm{\tau}_{u}[k+1][i] \gets \bm{\tau}_{limit}[i] - \tilde{\bm{h}}(\bm{\theta}[k], \hat{\dot{\bm{\theta}}}[k])[i]$
    \ElsIf{$\bm{\tau}_{u}[k+1][i] + \tilde{\bm{h}}(\bm{\theta}[k], \hat{\dot{\bm{\theta}}}[k])[i] < -\bm{\tau}_{limit}$[i]}
        \State $\bm{\tau}_{u}[k+1][i] \gets -\bm{\tau}_{limit}[i] - \tilde{\bm{h}}(\bm{\theta}[k], \hat{\dot{\bm{\theta}}}[k])[i]$
    \EndIf
    \EndFor

    \Statex
    \State $\bm{\tau}_{ref}[k+1] \gets \bm{\tau}_{u}[k+1] + \tilde{\bm{h}}(\bm{\theta}[k], \hat{\dot{\bm{\theta}}}[k])$ 
    \State \Comment{Centrifugal, Coriolis, friction, and gravity force compensation}

    \Statex
    \State $\text{writeTorque}(\bm{\tau}_{ref}[k+1]) $ \Comment{Send reference torque to motor}
    % \Statex
    \State k++
    \State $\text{sleep}()$ \Comment{Periodic execution}
\EndWhile
\end{algorithmic}
\end{algorithm}

\subsection{Teleoperation Comparison Settings}
We implemented unilateral control, symmetric position type, and force feedback type bilateral control besed on proposed 4-channel bilateral control system.
For unilateral control, $\bm{K}_p$, $\bm{K}_d$, $\bm{K}_f$ of the leader and $\bm{K}_f$ of the follower was set to $\bm{0}$, and disable external force compensation.
For symmetric position type bilateral control, $\bm{K}_f$ of both the leader and the follower was set to $\bm{0}$, and disable external force compensation.
For force feedback type bilateral control, $\bm{K}_p$, $\bm{K}_d$, of the leader and $\bm{K}_f$ of the follower was set to $\bm{0}$, and disable external force compensation of the follower.
For the fixed ineatia case, we used the ineatia matrix $diag[0.012258, 0.112990, 0.012028, 0.040000, 0.005676, 0.006600, 0.006281, 0.006891]$.

\subsection{Imitation Learning Settings}
The camera capture and ACT policies were executed at a rate of 30 Hz.
Since the joint angles, velocities and external forces were measured at 1 kHz, they were downsampled to 30 Hz for learning purposes.
Ten time-series datasets were created for each episode using the ten frames of joint information surrounding the 30 Hz timestamp of the image.
% AdamW was used for optimisation with a learning rate of 1e-5.
The temporal ensemble coefficient was set to 0.01.

\subsection{Imitation Learning Tasks}

\textbf{Task1: Dual-arm Pick-and-Place.}
We performed a task of grasping blocks of different widths between two arms.
Task snapshots are shown in Fig.~\ref{fig:snapshot_dual_arm_pick_and_place}.
% This task was simple, but it was challenging because the position and force of the left and right arms had to be adjusted with high precision, or the blocks would be dropped.
We prepared five types of blocks, ranging in width from 10 mm to 50 mm, and collected a total of 10 demonstration data sets, two for each type.
All blocks have a 50 mm x 50 mm base and are designed to look almost identical when viewed from directly above.
In this experimental environment, the camera captured images from a bird's-eye view, making it difficult to determine the width of blocks based solely on the images.
Regarding success or failure, if the block was entirely off the table, the pick was considered successful, and if the block was placed without being dropped or knocked over, the placement was considered successful.

\textbf{Task2: Nut Turning.}
We attempted the nut-turning task as a task that requires more force and speed.
Task snapshots are shown in Fig.~\ref{fig:snapshot_nut_turning}.
We collected 10 demonstration data sets.
This task involved quickly rubbing a nut that was loosely attached to a screw with robot's finger and turning it with momentum.
If the robot does not apply enough force and move the finger at a considerable speed, the nut will not turn properly.
The movement is repeated until the nut reaches the screw head.
Success or failure was determined by whether the nut reached the head of the screw.

\textbf{Task3: Cucumber peeling.}
As a task that involves handling irregularly shaped objects, we attempted to peel cucumbers with a peeler.
The task snapshots are shown in Fig.~\ref{fig:snapshot_cucumber_peeling}.
We collected 10 demonstration data sets.
First, the left arm grasps the cucumber placed in the center of the cutting board, then the right arm grabs the peeler located in the designated spot. Next, the peeler is pressed against the cucumber, and the right arm is quickly moved from left to right while applying downward pressure to peel the cucumber.
Success or failure was determined by whether the peeler blade touched the cucumber and whether the cucumber skin was peeled off.

