For a row vector $\vu\in \Z^{2d}$, $\vu\not \equiv \0_{2d}\pmod N$, where $\0_{2d}$ is the $2d$-dimensional zero-vector, we denote by $Q_{s}(N;\vu)$ the number of solutions of the congruence 
 \begin{equation}\label{eq: Cong with-u}
\vu \left(A^{x_1}+\ldots +A^{x_{s}} -A^{y_1} -\ldots -A^{y_{s}}\right)   \equiv  \0_{2d}\pmod N,  
\end{equation}
with integers $1\leq x_i, y_i \leq  \ord(A,N) $, $i =1, \ldots, s$. 

The key inequality below connects the $2s$-th moment associated to
the basic observables $\TN(\vu)$ 
with the number of
solutions $Q_{s}(N;\vu)$ to the system~\eqref{eq: Cong with-u}. 
For even $s$, this is given (in broader generality) by~\cite[Lemma~4.1]{KORS}. 
However this parity condition is too restrictive for us, hence we show how to prove 
a result for any $s$.

\begin{lem}\label{lem: T and Q}
Let $\vu\in \Z^{2d} \setminus\{ \0_{2d}\}$. Then
\[
   \max_{\psi \in \Psi_N(A)} 
  \left| \langle \TN(\vu)\psi ,\psi  \rangle \right|^{2s}
  \leq N^d \frac{Q_{s}(N;\vu)}{\ord(A,N)^{2s} },
\]
where the maximum is taken over all normalised eigenfunctions of $U_{N}(A)$.
\end{lem}

\begin{proof}
We argue exactly as in the proof of \cite[Lemma~4.1]{KORS}. Denote $\tau=\ord(A,N)$, and consider
\[
  D(\vu) =
  \frac 1{\tau}\sum_{i=1}^\tau  \TN(\vu  A^i),\quad \mathrm{and}\quad  H(\vu)=D(\vu)^{*}D(\vu).
\]



We have
\[
| \langle \TN(\vu)\psi,\psi \rangle|^{2s} \le \| D(\vu) \|^{2s}=\| H(\vu) \|^s=\| H(\vu)^s\|,
\]
where $\| \cdot \|$ denotes the operator norm. 

At this point, our argument differs from the proof of \cite[Lemma~4.1]{KORS}. We note that  
$H(\vu)$ is not only Hermitian, but also a positive semidefinite matrix; this is because
\[
\vz^{*}H(\vu)\vz=\vz^{*}D(\vu)^{*}D(\vu)\vz=\| D(\vu)\vz\|^2.
\]

Moreover, the operator $H(\vu)$ is also unitarily diagonalisable (see \cite[Theorem~2.5.6]{HJmatrix}), with non-negative eigenvalues. This shows that $H(\vu)^s$ is also a positive semidefinite matrix. Now, it is not hard to see that $\| H(\vu)^s\|=\rho(H(\vu)^s)$,
where $\rho(H(\vu)^s)$ is the spectral radius of $H(\vu)^s$, that is, the maximum of all the eigenvalues of $H(\vu)^s$. Clearly, we then have
\[
\| H(\vu)^s\|\leq \tr(H(\vu)^s).
\]

Now the proof concludes, by the same treatment as in the proof of \cite[Lemma~4.1]{KORS}.
\end{proof} 

Next we reduce  $Q_{s}(N;\vu)$ to the number of solutions to a 
similar system of equations but without the vector $\vu$. 


 \subsection{Linear independence of matrix powers} 
 \label{sec:lin indep}

For a vector $\vz = (z_1, \ldots, z_{n}) \in \R^{n}$, as usual, we  denote
\[
\| \vz \|_2 = (z_1^2 + \ldots + z_n^2)^{1/2}.
\]

We need the following result which is given by~ \cite[Lemma 4.3,~(i)]{KORS}
(in broader generality). 

Throughout this section we always assume that $A\in \Sp(2d,\Z)$ has an irreducible characteristic polynomial. 

\begin{lem}\label{lin indep lemma}
For any non-zero row vector $\vu\in \Z^{2d}$, which is not
%%a zero-divisor  
the vectors $\vu, \vu A,  \ldots,\vu A^{2d-1}$ are linearly independent.
\end{lem}

We are now ready to establish the desired result which allows to remove $\vu$ in our 
considerations of  $Q_{s}(N;\vu)$.


\begin{lem}
\label{lem: no u}  
  There is a constant $C(A)$ depending only on $A$, such that if we have $p^{m+1} > C(A)\|\vu\|_2^{2d}$ for some integer $1\leq m<k$, then for any solution $\(x_1,\ldots,x_{2s},y_1,\ldots, y_{2s}\) \in \Z^{4s} $ to~\eqref{eq: Cong with-u} with $N =p^k$, we have
\[
    A^{x_1}+\ldots A^{x_{2s}}\equiv A^{y_1}+\ldots+ A^{y_{2s}}\pmod {p^{k-m}}.
\]
\end{lem}

\begin{proof}
Let us set 
$$B=A^{x_1}+\ldots A^{x_{2s}}-A^{y_1}-\ldots -A^{y_{2s}}.$$
Since $\vu B\equiv 0\pmod {p^k}$, considering the matrix $X$ whose rows are $\vu,\vu A,\ldots,\vu A^{2d-1}$ and observing that $A$ and $B$ commute,  we have $XB\equiv 0\pmod{p^k}$. In particular, multiplying both sides by  the adjoint of $X$, we get 
\begin{equation}\label{eqn:detx}
\det X\cdot B\equiv 0 \pmod {p^k}.
\end{equation}

On the other hand,  Lemma~\ref{lin indep lemma}  shows that $\det X$ is a non-zero integer. In particular, if $p^{m+1}\nmid \det X$, then the congruence~\eqref{eqn:detx} implies that $B\equiv 0 \pmod {p^{k-m}}$. The proof now follows, as we obviously have $\det X \ll \|\vu\|_2^{2d}$.
\end{proof}


Let $p$ be a split prime which does not divide the discriminant and the constant coefficient of the characteristic polynomial of $A$ (that is, exactly as  we assume in Section~\ref{sec:constr}). 

We see that we have $2d$ distinct the eigenvalues of $A$   modulo $p$, that is, in the finite field  $\F_p$ 
of $p$ elements, which using Hensel lifting give us  the roots 
 \[ 
 \lambda_{1},\ldots,\lambda_{2d}\in \Z/p^{k}\Z,
 \]
 of the characteristic polynomial of $A$  modulo $p^{k}$.

