We have the following variant of~\cite[Lemma~4.4]{KORS}. 

\begin{lem}
\label{lem: no A}
    Let $p$ be any prime as in Section~\ref{sec:constr}, and let $m$ be the smallest integer 
    with $p^{m+1} > C(A)\|\vu\|_2^{2d}$ where $C(A)$ is as in Lemma~\ref {lem: no u}. 
    For any  solution $(x_1,\ldots x_{2s}, y_1,\ldots, y_{2s})$ to \eqref{eq: Cong with-u}
    with $N = p^k$ and $k > m$, we have
    $$\lambda_{i}^{x_1}+\ldots \lambda_{i}^{x_{2s}}\equiv \lambda_{i}^{y_1}+\ldots \lambda_{i}^{y_{2s}} \pmod {p^{k-m}}, \qquad i=1,\ldots,2d.$$
\end{lem}

\begin{proof}
 By the assumption on $p$, clearly the characteristic polynomial of $A$ has $2d$ distinct roots in $\Q_p$.  In particular, $A$ is diagonalisable over $\Q_p$. Denote $\blambda_1,\ldots,\blambda_{2d} \in \Z_p$ be its eigenvalues, where $\Z_p$ is the ring of $p$-adic integers in $\Q_p$. We have
 \begin{equation}\label{eqn:bltol}
\nu_p\(\lambda_i  -  \blambda_i\) \ge k, \qquad i=1,\ldots,2d.
 \end{equation}


For each $1\leq i\leq 2d$, there exists a non-zero vector $ \vv_i\in (\Q_p)^{2d}$, for which $\vv_i A=\blambda_i \vv_i$. We scale $\vv_i = \(v_{i,1},\ldots, v_{i,2d}\)$ so that all its coordinates lie in $\Z_p$, 
with some coordinate $v_{i,j_i}$ satisfying
 \begin{equation}\label{eq:unit}
 \nu_p\(v_{i,j_i}\) = 0.
  \end{equation}
 Lemma~\ref{lem: no u} then implies that
\[
\vv_i(\blambda_{i}^{x_1}+\ldots \blambda_{i}^{x_{2s}}-\blambda_{i}^{y_1}-\ldots -\blambda_{i}^{y_{2s}})
 \in  \(p^{k-m}\Z_p\)^{2d}, \qquad i=1,\ldots,2d, 
\]
and thus
\[
\nu_p\(v_{i,j_i}(\blambda_{i}^{x_1}+\ldots \blambda_{i}^{x_{2s}}-\blambda_{i}^{y_1}-\ldots -\blambda_{i}^{y_{2s}}\) \ge k-m , \qquad i=1,\ldots,2d.
\]
The result now follows from~\eqref{eqn:bltol} and~\eqref{eq:unit}. 
\end{proof}



\section{Multiplicative orders and exponential sums} \label{sec:ord}
  \subsection{Multiplicative orders}  

 We need to collect the  simple and well-known properties of multiplicative orders 
 modulo prime powers. More general results have been given by Korobov~\cite{Kor1,Kor2}, 
 we need the following  direct consequence of~\cite[Lemma~1]{Kor1}.



 \begin{lem}\label{eq:ord growth} 
Assume that a prime  $p\ge 3$ and an integer  $\lambda\ne \pm 1$ are relatively prime. 
Let 
\[
\gamma = \nu_p\(\lambda^{\ord(\lambda, p)} -1\).
\]
Then for $k \ge \gamma$ we have 
\[
\ord(\lambda, p^k) = \ord(\lambda, p) p^{k-\gamma}.
\]
\end{lem}

Define integers $\rho_{i,j} $, $1 \le i,j \le 2d$, by 
$\rho_{i,j} \equiv  \lambda_i/\lambda_j \pmod {p^k}$. 

We also define $\gamma_i$ and $\gamma_{i,j}$ as in Lemma~\ref{eq:ord growth} 
for $\lambda_i$ and  $\rho_{i,j} $, respectively, $1 \le i,j \le 2d$

 \begin{lem}
 \label{eq:ord growth max} 
 There is a constant $c(A,p)$ depending only on $A$ and $p$, such that  
 \[
 \max_{\substack{1 \le i,j \le 2d\\ i\ne j}}\{\gamma_i, \gamma_{i,j}\} \le c(A,p). 
 \]
\end{lem}

\begin{proof} Let $\mu_1, \ldots, \mu_{2d}$ be the eigenvalues $A$ and 
$\fp$ be a prime ideal of $\Q\(\mu_1, \ldots, \mu_{2d}\)$. 
Note that $p^{\gamma_i}\mid \lambda_i^t-1$, with integer $t \ge 1$
 implies $\fp^{\gamma_i} \mid \mu_i^t-1$.  Note that by our assumption
 on $A$ we have  $ \mu_i^t-1 \ne 0$ and hence $\gamma_i$ is bounded 
 only in terms of $A$ and $p$. 

 Similarly, $p^{\gamma_{i,j}}\mid \rho_{i,j}^t-1$ implies 
 $\fp^{\gamma_{i,j}}\mid  \mu_i^t -  \mu_j^t$ and for $i \ne j$ the same argument applies. 
\end{proof}

 \subsection{Exponential sums}


Let $p$ be any prime as in Section~\ref{sec:constr} and let $\lambda_1, \ldots \lambda_{2d}$ be as in Section~\ref{sec:lin indep}. 

 For a vector of integers $\va = \(a_1, \ldots, a_{2d}\)$ and a positive integer $r$, we define the exponential sums 
 \[
S_r(\va) = \sum_{x=1}^{t_r}  \e_{p^r}\(a_1\lambda_1^x + \ldots + a_{2d}\lambda_{2d}^x \),
\]
where $t_r$   is the period of the sequence $a_1\lambda_1^x + \ldots + a_{2d}\lambda_{2d}^x$, $x =0,1, \ldots$, 
 modulo $p^r$. 


We note that the following bound on these exponential sums is essentially established in~\cite{Shp} and in fact for 
essentially arbitrary linear recurrence sequences. Note that a similar argument has also been used in~\cite{MeShp}.


\begin{lem}\label{eq:exp sum} 
Let $p$ be any prime as in Section~\ref{sec:constr} and let $\lambda_1, \ldots \lambda_{2d}$ be as in Section~\ref{sec:lin indep}.   Then for any integer $r \ge 1$, 
uniformly over integers $a_1, \ldots, a_{2d}$  with 
\[
\gcd(a_1, \ldots, a_{2d}, p) =  1, 
 \]
we have
\[
\left| S_r(\va) \right| \le t_r^{1-1/(2d)+o(1)}, \qquad \text{as} \ r \to \infty. 
 \]
\end{lem}

\begin{proof}   The result in~\cite[Theorem~2]{Shp} is formulated  for fixed integers  
$\lambda_1, \ldots \lambda_{2d}$ (and fixed $d$ and $p$).  
Since the work~\cite{Shp} is difficult to access, we now summarise some ideas used in the proof, 
which references to much easier accessible work~\cite{MeShp}. 
In full generality,~\cite[Theorem~2]{Shp} gives the following bound 
\[
\left| \sum_{x=1}^{\tau_r} \e_{p^r} \(u(x)\) \right| \le \tau_r^{1-1/e + o(1)}
\]
on exponential sums over the full period $\tau_r$ modulo $p^r$ of an integer linear recurrence sequence $u(x)$ of order $e$, with a square-fee 
characteristic polynomial $f(X) \in \Z[X]$, such that there are no roots of unity amongst the roots of $f$ and their nontrivial ratios. This bound is based on:
\begin{itemize}
\item a polynomial representation (as polynomials in $y$) of the sequences $u(a+ \tau_s y)$ for each $a =0, \ldots, \tau_s-1$, with $s$ slowly growing with $r$, and an upper bound on $p$-adic order of at least one coefficient among every $e$ consecutive coefficients of this polynomial, 
see~\cite[Lemma~2.5]{MeShp}; 

\item  a bound on exponential sums 
 \begin{equation}\label{eq:poly exp sum}
\sum_{y=1}^{p^r} \e_{p^r} \(F(y)\)  \ll p^{r(1-1/e)}
  \end{equation}
provided $p > e$, 
with any polynomial $F(Y) \in \Z[Y]$ of the form
$F(Y) =p G(Y) + A_eY^e + \ldots + A_1Y$ for an arbitrary $G(Y) \in \Z[Y]$, 
and $\gcd(A_1, \ldots, A_e, p) = 1$, which follows, for example, from a much more general result of Cochrane  and  Zheng~\cite[Theorem~3.1]{CoZh} (with the implied constant depending only on $e$ and $p$). 
\end{itemize}

It is important to recall that the implied constant in~\eqref{eq:poly exp sum} depends only on $e$ and $p$, in particular, it does not depend on $\deg F$. 

Note that we have $e = 2d$ in out setting. 


As we have mentioned a similar strategy has also been used in~\cite{MeShp}, where instead of the above complete sums, very short exponential sums are used. 

Examining the dependencies in implied constants throughout the argument of the 
proof of~\cite[Theorem~2]{Shp} one can easily verify that in fact all constants depend only on $d$, $p$ and  parameters 
$\gamma_i$ and $\gamma_{i,j}$ 
from Lemma~\ref{eq:ord growth max}, which depend  only on the matrix $A$ and the prime $p$. 
\end{proof}

\begin{rem} Certainly the parity of the number of terms in the sums $ S_r(\va)$, plays no role in argument and 
the similar statement holds for any number $e$ of terms instead of $2d$ (with the saving $1/e$). 
\end{rem}
 \section{Proof of Theorem~\ref{thm:integers}}

\subsection{Bounding  $Q_{s}(N;\vu)$}   
Let $p$ be any prime as in Section~\ref{sec:constr} and let $N = p^k$. 
Assume that $k> m$  where $m$ is the smallest integer with $p^{m+1} > C(A)\|\vu\|_2^{2d}$ where $C(A)$ is as in Lemma~\ref {lem: no u}. 
Denote $T=\ord(A,N) =\ord(A,p^k)$.

Using the  orthogonality of exponential functions, it follows from Lemmas~\ref{lem: no u} and~\ref{lem: no A} that
 \begin{equation}
 \begin{split}
 \label{eq:Q < exp sums}
Q_{s}&(N;\vu)\\
& \le \frac{1}{p^{2d(k-m)}}\sum_{\va \in (\Z/p^{k-m}\Z)^{2d}}\left|\sum_{x=1}^{T}\e_{p^{k-m}}\(a_1\lambda_{1}^x+\ldots+a_{2d}\lambda_{2d}^x\)\right|^{2s}.
\end{split}
\end{equation}



For each $r =0, \ldots, k-m$ we separate the contribution 
\begin{align*}
W_r & = \sum_{\substack{\va \in (\Z/p^{k-m}\Z)^{2d}\\\gcd\(a_1, \ldots, a_{2d}, p^{k-m} \)  = p^{k-m-r}}}\left|\sum_{x=1}^{T}\e_{p^{k-m}}\(a_1\lambda_{1}^x+\ldots+a_{2d}\lambda_{2d}^x\)\right|^{2s}\\
 & = \sum_{\substack{\vb \in (\Z/p^{r}\Z)^{2d}\\\gcd\(b_1, \ldots, b_{2d}, p \)  = 1}}\left|\sum_{x=1}^{T}\e_{p^{r}}\(b_1\lambda_{1}^x+\ldots+b_{2d}\lambda_{2d}^x\)\right|^{2s}\
\end{align*}
to the sum on the right hand side 
of~\eqref{eq:Q < exp sums} from vectors $\va$  for which 
$\gcd\(a_1, \ldots, a_{2d}, p^{k-m} \)  = p^{k-m-r}$.

For each $\vb \in (\Z/p^{r}\Z)^{2d}$ with $\gcd\(b_1, \ldots, b_{2d}, p \)  = 1$ we see that the period $t_r (\vb)$ of the sequence  $b_1\lambda_1^x + \ldots + b_{2d}\lambda_{2d}^x$ 
modulo $p^r$ satisfies 
\[
t_r (\vb)  %% \gg  t_{k-m} p^{k-m-r} \gg  T p^{-(k-m-r)} 
\gg p^r \mand t_r (\vb)  \mid  t_{k-m} (\vb) \mid T,
\]
and hence by Lemma~\ref{eq:exp sum}  we have 
\[
\left|\sum_{x=1}^{T}\e_{p^r}\(b_1\lambda_{1}^x+\ldots+b_{2d}\lambda_{2d}^x\)\right|
\ll T^{1+o(1)} p^{-r/(2d)}. 
\]

Therefore, 
\begin{align*}
W_r & \le \(T^{1+o(1)} p^{-r/(2d)}\)^{2s-2} \\
& \qquad \qquad \sum_{\substack{\vb \in (\Z/p^{r}\Z)^{2d}\\\gcd\(b_1, \ldots, b_{2d}, p \)  = 1}}\left|\sum_{x=1}^{T}\e_{p^{r}}\(b_1\lambda_{1}^x+\ldots+b_{2d}\lambda_{2d}^x\)\right|^2\\
& \le T^{2s-2+o(1)} p^{-r(s-1)/d}
 \sum_{\vb \in (\Z/p^{r}\Z)^{2d}}\left|\sum_{x=1}^{T}\e_{p^{r}}\(b_1\lambda_{1}^x+\ldots+b_{2d}\lambda_{2d}^x\)\right|^2.
\end{align*}

It is easy to see that by  the  orthogonality of exponential functions we have 
\[
 \sum_{\vb \in (\Z/p^{r}\Z)^{2d}}\ \left|\sum_{x=1}^{T}\e_{p^{r}}\(b_1\lambda_{1}^x+\ldots+b_{2d}\lambda_{2d}^x\)\right|^2
\le p^{2dr} T (T/t_r) \ll T^2 p^{r(2d-1)}.
\]
Hence, 
\[
W_r \le T^{2s+o(1)} p^{r\(2d -1  - (s-1)/d\)}.
\]
%%Assuming that $s \le d^2$, since $p^m \ll 1$, we derive from~\eqref{eq:Q < exp sums}  that 
%%\begin{align*}
%%Q_{2s}(N;\vu) &\le \frac{1}{p^{2d(k-m)}}\sum_{r=0 }^{k-m}  W_r\\
%%&  \le   \frac{1}{p^{2d(k-m)}} T^{4s+o(1)} p^{(k-m)(2d - 2s/d)} \le  T^{4s+o(1)} p^{-2ks/d}.
%%\end{align*}

Assuming that 
 \begin{equation}
 \label{eq:cond s small}
s-1 \le d(2d-1),
\end{equation}
 and noting that $p^m \ll \|\vu\|_2^{2d}$, we derive 
from~\eqref{eq:Q < exp sums} that 
\begin{align*}
Q_{s}(N;\vu) &\le \frac{1}{p^{2d(k-m)}}\sum_{r=0 }^{k-m}  W_r\\
&  \le   \frac{k}{p^{2d(k-m)}} T^{2s+o(1)} p^{(k-m)\(2d -1  - (s-1)/d\)}\\ 
&\le \|\vu\|_2^{2s+2d-2} T^{2s+o(1)}  p^{-k\(1+ (s-1)/d\)} \log N.
\end{align*}

Then, since $T \ll N$  and thus $\log N$ can be absorbed in $T^{o(1)}$,   it follows from Lemma~\ref{lem: T and Q} that,
\begin{equation}\label{eq:small s}
\begin{split}
\max_{\psi \in \Psi_N(A)}& \left| \langle \TN(\vu)\psi ,\psi  \rangle \right|\\
& \le  \|\vu\|_2^{(2s-2+2d)/(2s)}   p^{k\(d - 1 - (s-1)/d\)/(4s)}T^{o(1)} \\
& =  \|\vu\|_2^{(s-1+d)/s} N^{-\( (s-1)/d+1 - d\)/(2s)+o(1)} .
\end{split}
\end{equation}



\subsection{Concluding the proof}   
Our goal is choose $s$ with~\eqref{eq:cond s small} which maximises  
the saving in~\eqref{eq:small s}
\[
\eta_d(s) = \frac{ (s-1)/d+1 - d}{2s} = \frac{1}{2d}  - \frac{d(d-1) +1 }{2ds} 
\]
which is clearly a monotonically increasing function of $s$.

We choose 
\[
s_0 = d(2d-1) + 1,
\]
for which we obtain 
\[
\eta_d(s_0 ) = \frac{1}{2d} - \frac{d^2 - d + 1}{2d(2d^2 - d + 1)}
=  \frac{d }{2(2d^2 - d + 1)}. 
\]

%%If $d$ is even, we choose 
%%\[
%%s_0 = d(2d-1)/2,
%%\]
%%for which we obtain 
%%\[
%%\eta_d(s_0 ) = \frac{1}{2d} - \frac{d^2 - d + 1}{2d^2(2d - 1)}
%%=  \frac{d^2 -1  }{2d^2(2d - 1)}. 
%%\]
Hence  we obtain 
\[
\max_{\psi \in \Psi_N(A)} \left| \langle \TN(\vu)\psi ,\psi  \rangle \right
| \ll  \|\vu\|_2^{(s_0-1+d)/s_0} N^{-\kappa_d+o(1)} , 
\]
where $\kappa_d$ is given by~\eqref{eq:kappa}.

The proof of Theorem~\ref{thm:integers} concludes since the Fourier coefficients of the functions in $C^\infty(\TT^{2d})$ has a rapid decay (faster than any power of $\|\vu\|$). For more details, see~\cite{KORS,KRDuke}.

\begin{rem}
We only consider that case~\eqref{eq:cond s small} since  the case $s-1> d(2d-1)$ 
produces weaker results. Indeed,  for  $s-1> d(2d-1)$ we obtain 
\[
Q_{s}(N;\vu) \ll  \frac{1}{p^{2kd}} \|\vu\|_2^{4d^2} T^{2s+o(1)}, 
\]
which  by Lemma~\ref{lem: T and Q} implies that
\[
\max_{\psi \in \Psi_N(A)} \left| \langle \TN(\vu)\psi ,\psi  \rangle \right|
 \ll \|\vu\|_2^{2d^2/s}  N^{-d/(2s)+o(1)}.
 \]
One easily verifies that for  $s-1>d(2d-1)$ we have 
$ d/(2s)  \le \kappa_d$. 
\end{rem}

















