  \title{Long-range dispersal promotes spatial synchrony but reduces the length and time scales of synchronous fluctuations.}
  \author[1]{Davi Arrais Nobre\corref{cor1}}
  \ead{dv.nobr@gmail.com}
  \author[2]{Karen C. Abbott}
  \author[3,4]{Jonathan Machta}
  \author[5,4]{Alan Hastings}
  \cortext[cor1]{Corresponding author.}
  \address[1]{Department of Physics and Astronomy, University of California, Davis, One Shields Avenue, Davis, CA, 95616 USA.}
  \address[2]{Department of Biology, Case Western Reserve University, 10900 Euclid Ave, Cleveland, OH, 44106 USA.}
  \address[3]{Department of Physics, University of Massachusetts, Amherst, MA, 01003 USA.}
  \address[4]{Santa Fe Institute, 1399 Hyde Park Road, Santa Fe, NM, 87501 USA.}
