\title{A practical identifiability criterion leveraging weak-form parameter estimation}%to characterize the relationship between measurement error and parameter uncertainty
%\title{A weak-form practical identifiability framework}
\author*[1]{\fnm{Nora} \sur{Heitzman-Breen}}\email{nora.heitzman-breen@colorado.edu}
