\section{Weak form Estimation of Nonlinear Dynamics (WENDy)}\label{app:WENDy}

Recently, we have developed the Weak form Estimation of Nonlinear Dynamics (WENDy) method for parameter estimation method \cite{BortzMessengerDukic2023BullMathBiol}, which we will briefly describe here. We begin by considering the $i$th variable $u_i$ in a $d$-dimensional ordinary differential
equation (ODE)
\begin{equation}
\dot{u}_i=\Theta(u)\wbf_i\label{eq:general model}
\end{equation}
with row vector of $d$ solution states \[u(t;\wbf):=(u_{1}(t;\wbf), \dots, u_{d}(t;\wbf))\] and row vector of $J$ features $\Theta(u):=(
f_{1}(u),\dots,f_{J}(u))$. Each feature $f_j:\Rbb^d\to \Rbb$ is assumed to be $C^2$. We seek to identify the vector of unknown parameters $\wbf=[\wbf_1^T|\cdots|\wbf_d^T]^T\in\mathbb{R}^{Jd}$ from observations of $u$. 

We let the superscript $\star$ notation denote quantities based on the true (noise-free and unknown) parameter values ($\wbf^{\star}$) and let $u^{\star}:=u(t;\wbf^{\star})$
and $\Theta^{\star}:=\Theta(u^{\star})$. We
assume that at each timepoint $t\in\tbf=(t_0,\dots,t_M)$ measurements of the system are observed with additive noise
\begin{equation}
U(t)=u^{\star}(t)+\varepsilon(t)\label{eq:additive noise-1}
\end{equation}
where each element of $\varepsilon(t)$ is i.i.d.~$\mathcal{N}(0,\sigma^{2})$. Using bold-face variables to represent evaluation at the timegrid $\tbf$, our observations then consist of samples $\Ubf:=\ubf^\star+\pmb{\varepsilon}\in\mathbb{R}^{(M+1)\times d}$.

To arrive at a weak-form framework to estimate $\wstar$ from $\Ubf$, we consider a $C^{\infty}$ bump function $\phi$ for which the function and all derivatives are compactly supported in the time interval $[0,T]$ (e.g.\ $\phi \in C_{c}^{\infty}([0,T])$). Multiplying both sides of (\ref{eq:general model}) by $\phi$, and integrating by parts over $0$ to $T$, we obtain
\begin{equation}
-\int_{0}^{T}\dot{\phi}u\textsf{d}t
=\int_{0}^{T}\phi\Theta(u)\textsf{mat}(\wbf)\textsf{d}t,\label{eq:WENDyContinuum}
\end{equation}
where ``$\mathsf{mat}$'' is the matricization operation.
Using a set of these test function $\{\phi_k\}_{i=1}^{K}$, \eqref{eq:WENDyContinuum} can be discretized at observed data $\Ubf$, yielding approximated integrals $-\dot{\Phi}_k\Ubf = \Phi_k\Theta(\Ubf)W$ and corresponding linear system $\Gbf\wstar\approx \bbf$, where
\begin{align*}
\Gbf & :=[\mathbb{I}_{d}\otimes(\Phi\Theta(\Ubf))],\\
\bbf & :=-\mathsf{vec}(\dot{\Phi}\Ubf).
\end{align*}
A simple ordinary least-squares framework for identifying $\wstar$ does not address the Errors-In-Variables nature of the problem (given the dependence of both $\Gbf$ and $\bbf$ on the noisy data). To address this, the WENDy algorithm uses iterative reweighting to approximate the correct underlying covariance structure. For this purpose, consider the residual
\begin{equation}
\rbf(\mathbf{U},\wbf):=\Gbf\wbf-\bbf,\label{eq:WENDyDataResid}
\end{equation}
which can be decomposed into several components
\begin{align}
\rbf(\Ubf,\wbf)=\underbrace{(\Gbf-\Gbf^\star)\wbf}_{\begin{array}{c}\ebf_\Theta\end{array}}+\underbrace{\Gbf^\star(\Wbf-\wstar)}_{\begin{array}{c}\rbf_{0}\end{array}}+\underbrace{(\Gbf^\star\wstar-\bbf^\star)}_{\begin{array}{c}\ebf_{\text{int}}\end{array}}-\bbf^{\pmb{\varepsilon}}.\label{eq:ResidualDecomposition}
\end{align}
Here, $\rbf_0$ is the residual without measurement noise or integration errors, and $\ebf_{\text{int}}$ is the numerical integration error induced by the quadrature. The leftover terms $\ebf_\Theta-\bbf^{\pmb{\varepsilon}}$ can be Taylor expanded around the data $\Ubf$,
\begin{equation}
\ebf_\Theta-\bbf^{\pmb{\varepsilon}} = \Lbf_{\wbf}\mathsf{vec}(\pmb{\varepsilon})+\hbf(\Ubf,\wbf,\pmb{\varepsilon})
\label{eqn:eThetabeps}
\end{equation}
where $\hbf(\Ubf,\wbf,\pmb{\varepsilon})$ denotes higher-order terms in the measurement errors $\pmb{\varepsilon}$. The first order matrix in the expansion \eqref{eqn:eThetabeps} is
\[
\mathbf{L}_{\wbf} :=[\mathsf{mat}(\wbf)^{T}\otimes\Phi]\nabla\Theta\Kbf+[\mathbb{I}_{d}\otimes\dot{\Phi}],
\]
where $\Kbf$ is the commutation matrix such that $\Kbf\textsf{vec}(\boldsymbol{\varepsilon})=\textsf{vec}(\boldsymbol{\varepsilon}^{T})$. The matrix $\nabla \Theta$ contains derivatives of the features (for details see \cite{BortzMessengerDukic2023BullMathBiol}). Under the Gaussian noise assumption, when $\wbf=\wstar$ and the integration error is negligible, to first order 
 we have 
 \begin{equation}
\Gbf \wstar-\bbf\sim\mathcal{N}(\mathbf{0},\sigma ^2\mathbf{L}_{\wstar}(\mathbf{L}_{\wstar})^{T})\label{eqn:ResidDistwstar}.
\end{equation}
This leads to an iterative alrogithm, where the covariance matrix $\Cbf^{(n)}$ is updated using the weights $\wbf^{(n)}$ step $n$, for regularization parameter $\alpha$,
\begin{align*}
\Lbf^{(n)} &\leftarrow [\textsf{mat}(\wbf^{(n)})^{T}\otimes\Phi]\nabla\Theta(\Ubf)\Kbf+[\mathbb{I}_{d}\otimes\dot{\Phi}]\\
\Cbf^{(n)} &= (1-\alpha)\Lbf^{(n)}(\Lbf^{(n)})^T + \alpha \Ibf\\
\intertext{and the weights are subsequently updated as}
\wbf^{(n+1)} &\leftarrow (\Gbf^T(\Cbf^{(n)})^{-1}\Gbf)^{-1}\Gbf^{T}(\Cbf^{(n)})^{-1}\bbf.
\end{align*}

\section{Derivations of weak-form input-ouput equations for SIR model}\label{app:derv_wkIO}

Consider model equation, which is presented again below,
\begin{equation}\begin{split}
    \dot{S}&=-\beta SI,\\
    \dot{I}&=\beta SI-\alpha I,\\
    \dot{R}&=\alpha I.
\end{split}\label{eq-app:SIR}
\end{equation}
By solving for $S$ from the $\dot{S}$ equation, we obtain equation the following,
\begin{equation}
    S=\frac{\dot{S}}{-\beta I}.\label{eq-app:Ssub}
\end{equation}
From the $\dot{S}$ equation we can also obtain equation the following by taking the derivative, 
\begin{equation}
    \ddot{S}=-\beta \dot{S}I-\beta S\dot{I}.\label{eq-app:Sdotsub}
\end{equation}
From the $\dot{S}$ and $\dot{I}$ equations we can obtain,
\begin{equation}
    \dot{S}=-\beta SI +\alpha I -\alpha I = -(\beta SI -\alpha I) -\alpha I= -\dot{I}-\alpha I.\label{eq-app:Sdotsub2}
\end{equation}
From the $\dot{S}$ and $\dot{I}$ equations we can obtain  the following equation by taking the derivative, 
\begin{equation}
    \ddot{I}=\frac{d}{\textsf{d}t}(\beta SI-\alpha I)=\frac{d}{\textsf{d}t}(-\dot{S}-\alpha I)=-\ddot{S}-\alpha \dot{I}.\label{eq-app:Idotdotsub}
\end{equation}
Substituting equations \eqref{eq-app:Ssub} and \eqref{eq-app:Sdotsub2} in equation \eqref{eq-app:Sdotsub} we obtain equation below,
\begin{equation}\begin{split}
    \ddot{S}&=-\beta \dot{S}I-\beta S\dot{I}=-\beta(-\alpha I-\dot{I})I-\beta \frac{\dot{S}}{-\beta I}\dot{I}\\&=\beta\alpha I^2+\beta I\dot{I}+(-\alpha I-\dot{I})\frac{\dot{I}}{I}=\beta\alpha I^2+\beta I\dot{I}-\alpha \dot{I}-\frac{\dot{I}^2}{I}. \end{split}\label{eq-app:Sdotdot}
\end{equation}
Next we substitute equation \eqref{eq-app:Sdotdot} in equation \eqref{eq-app:Idotdotsub} to obtain equation \eqref{eq:io_sir}, an input-output equation for the SIR model for observed state variable $I,$ which we present again below,
\begin{equation*}
    \begin{split}
        \ddot{I}&=-\ddot{S}-\alpha I\\
        \ddot{I}&=-\beta\alpha I^2-\beta I\dot{I}+\alpha \dot{I}+\frac{\dot{I}^2}{I}-\alpha \dot{I}\\
        0&=-\frac{\dot{I}^2}{I}+\beta I\dot{I}+\beta\alpha I^2.
    \end{split}
\end{equation*}
Notice that three of the terms on the right hand side of \eqref{eq:io_sir} can be written in the form \eqref{eq:diff_form1}, or in other words can be written a derivative of a function of only $I$. However, the term $\frac{\dot{I}^2}{I}$ cannot be put in this form. We re-write equation \eqref{eq:io_sir} in the form \eqref{eq:diff_form2} by converting as many terms as possible to form \eqref{eq:diff_form1} to obtain equation the following,
\begin{equation}
    0=-\frac{\dot{I}^2}{I}+\beta\alpha I^2+\frac{d}{\textsf{d}t}\frac{\beta}{2}I^2+\frac{d^2}{\textsf{d}t^2}I.\label{eq-app:io-form2}
\end{equation}
Next, we multiply by test function $\phi$ and integrate over domain 0 to $T$ to obtain equation \eqref{eq:wf_sir}, the weak-form SIR input-output equation for observed state $I$, which is presented again below,
\begin{equation*}
\int_0^T\ddot{\phi}I\textsf{d}t-\int_0^T\phi\frac{\dot{I}^2}{I}\textsf{d}t=\beta\int_0^T\dot{\phi}\frac{I^2}{2}\textsf{d}t-\beta\alpha\int_0^T\phi I^2\textsf{d}t.
\end{equation*}
From equation \eqref{eq:SIR} we know,
\begin{equation*}
    \dot{I}^2=(\beta SI)^2-2\beta\alpha SI^2+\alpha^2I^2.
\end{equation*}
So, using equation \eqref{eq-app:Sdotsub2} we can then re-write the term which is not integrable by parts as follows,
\begin{equation}
    \frac{\dot{I}^2}{I}=\beta^2 S^2I-2\beta\alpha SI+\alpha^2=\beta S\dot{S} -2\beta\alpha SI+\alpha^2I.\label{eq:sqdotI}
\end{equation}
Substituting equation \eqref{eq:sqdotI} into equation \eqref{eq:wf_sir} we obtain the following
\begin{equation}
\begin{split}
    \int_0^T\phi\frac{\dot{I}^2}{I}\textsf{d}t&=\beta\int_0^T\phi S\dot{S}\textsf{d}t-\beta\alpha\int_0^T\phi 2SI\textsf{d}t+\alpha^2\int_0^T\phi \textsf{d}t,\\
&=-\beta\int_0^T\dot{\phi}\frac{S^2}{2}\textsf{d}t-\beta\alpha\int_0^T\phi 2SI\textsf{d}t+\alpha^2\int_0^T\phi I\textsf{d}t.
\end{split}\label{eq:wf_sqdot_int}
\end{equation}
Let the total population $N=S(t)+I(t)+R(t)$ be constant. Then, $S(t)=N-I(t)-R(t)$. From the equation \eqref{eq:SIR} we know,
\begin{equation*}
    R(t)=\int_0^t\alpha I(s)\textsf{d}s.
\end{equation*}
Then from our assumption of constant population we are able to generate the following equation from equation \eqref{eq:wf_sqdot_int}, which is given again below,
\begin{equation*}
\begin{split}
    \int_0^T\phi\frac{\dot{I}^2}{I}\textsf{d}t
&=\beta\int_0^T\dot{\phi}\frac{(N-R(t)-I)^2}{2}\textsf{d}t-\beta\alpha\int_0^T\phi2(N-R(t)-I)I\textsf{d}t+\alpha^2\int_0^T\phi I\textsf{d}t.
\end{split}
\end{equation*}
Finally, we can write equation \eqref{eq:wf_sir_conpop}, a weak-form SIR model that reveals parameter $\beta$ using only observations of state $I$, which is given again below,
\begin{equation*}
\begin{split}
    \int_0^T\ddot{\phi}I\textsf{d}t-\alpha^2\int_0^T\phi I \textsf{d}t&=\beta\int_0^T\dot{\phi}(\frac{I^2-(N-R(t)-I)^2}{2}\textsf{d}t\\&-\beta\alpha\int_0^T\phi(I^2+2(N-R(t)-I)I)\textsf{d}t,\\
    R(t)&=\int_0^t\alpha I(s)\textsf{d}s.
\end{split}
\end{equation*}


