The succeeding lemma expounds the expected and probabilistic error bounds of \texttt{randQB} \cite{halko2011finding}, which are exactly the same as those of \texttt{farPCA} without shifted technique, owing to their mathematical equivalence.

\begin{lemma}[Expected and probabilistic error bounds for \texttt{randQB} {\cite{halko2011finding}}]\label{lemma4.7}
    Generate an $n\times l$ standard Gaussian matrix $\mathbf{G}$, where $l=k+h\leq n$, $k\geq 2$, and $h\geq 2$. Construct $\mathbf{Y}=\mathbf{A}\mathbf{G}$. Consequently, if $\mathbf{Q}$ is an orthonormal basis for the range of $\mathbf{Y}$ and $\mathbf{Q}_P$ serves as an orthonormal basis for the range of $(\mathbf{A}\mathbf{A}^\top)^P\mathbf{Y}$ with $P$ being a natural number, then
    \begin{footnotesize}
    \begin{align}
        &\mathbb{E}\|(\mathbf{I}-\mathbf{Q}\mathbf{Q}^\top)\mathbf{A}\|_\mathrm{F}\leq\left(1+\frac{k}{h-1}\right)^{\frac{1}{2}}\left(\sum_{j=k+1}^{n}\sigma_j^2\right)^{\frac{1}{2}},\label{eq4.9}\\
        &\mathbb{E}\|(\mathbf{I}-\mathbf{Q}_P\mathbf{Q}_P^\top)\mathbf{A}\|\leq\left(\left(1+\sqrt{\frac{k}{h-1}}\right)\sigma_{k+1}^{2P+1}+\frac{e\sqrt{k+h}}{h}\left(\sum_{j=k+1}^{n}\sigma_j^{2(2P+1)}\right)^{\frac{1}{2}}\right)^{\frac{1}{2P+1}}.\label{eq4.10}
    \end{align}
    \end{footnotesize}
    Further assume that $h\geq 4$, then for all $u,t\geq 1$,
    \begin{small}
    \begin{align}
        \|(\mathbf{I}-\mathbf{Q}\mathbf{Q}^\top)\mathbf{A}\|_\mathrm{F}\leq\left(1+t\sqrt{\frac{3k}{h+1}}\right)\left(\sum_{j=k+1}^{n}\sigma_j^2\right)^{\frac{1}{2}}+ut\frac{e\sqrt{k+h}}{h+1}\sigma_{k+1}\label{eq4.11}
    \end{align}
    \end{small}
    with failure probability not exceeding $2t^{-h}+e^{-u^2/2}$, and 
    \begin{footnotesize}
    \begin{multline}\label{eq4.12}
    \|(\mathbf{I}-\mathbf{Q}_P\mathbf{Q}_P^\top)\mathbf{A}\|\leq\\
    \left(\left(1+t\sqrt{\frac{3k}{h+1}}\right)\sigma_{k+1}^{2P+1}+t\frac{e\sqrt{k+h}}{h+1}\left(\sum_{j=k+1}^{n}\sigma_j^{2(2P+1)}\right)^{\frac{1}{2}}+ut\frac{e\sqrt{k+h}}{h+1}\sigma_{k+1}^{2P+1}\right)^{\frac{1}{2P+1}}
    \end{multline}
    \end{footnotesize}
     with failure probability not exceeding $2t^{-h}+e^{-u^2/2}$.
\end{lemma}

To enable effective error control for large matrices, we leverage innovations from RMT to establish tighter asymptotic bounds. Instead of employing the norm bounds of the pseudo-inverse of the Gaussian matrix presented by \cite[Proposition 10.2, Proposition 10.4]{halko2011finding}, Lemma \ref{lemma4.6} is used to give a more exact norm bound when $k$ and $h$ tend to infinity. The results are as follows. 

\begin{theorem}[Asymptotic expected and probabilistic error bounds for \texttt{randQB} (\texttt{farPCA} without shifted power iteration)]\label{thm4.8}
    Generate an $n\times l$ standard Gaussian matrix $\mathbf{G}$, where $l=k+h\leq n$, $k\geq 2$, and $h\geq 2$. Let $\mathbf{Y}=\mathbf{A}\mathbf{G}$, then if $\mathbf{Q}$ is an orthonormal basis for the range of $\mathbf{Y}$ and $\mathbf{Q}_P$ serves as an orthonormal basis for the range of $(\mathbf{A}\mathbf{A}^\top)^P\mathbf{Y}$ with $P$ being a natural number, as $k\to\infty,k/(k+h)\to\gamma\in(0,1)$, the subsequent equations hold with probability $1$:
    \begin{footnotesize}
    \begin{align}
        &\mathbb{E}\|(\mathbf{I}-\mathbf{Q}\mathbf{Q}^\top)\mathbf{A}\|_\mathrm{F}\leq\left(1+\frac{k}{h}\right)^{\frac{1}{2}}\left(\sum_{j=k+1}^{n}\sigma_j^2\right)^{\frac{1}{2}},\label{eq4.13}\\
        &\mathbb{E}\|(\mathbf{I}-\mathbf{Q}_P\mathbf{Q}_P^\top)\mathbf{A}\|\leq\left(\left(1+\sqrt{\frac{k}{h}}\right)\sigma_{k+1}^{2P+1}+\frac{\sqrt{k+h}+\sqrt{k}}{h}\left(\sum_{j=k+1}^{n}\sigma_j^{2(2P+1)}\right)^{\frac{1}{2}}\right)^{\frac{1}{2P+1}}.\label{eq4.14}
    \end{align}
    \end{footnotesize}
    Furthermore, for all $u>0$,
    \begin{small}
    \begin{align}
        \|(\mathbf{I}-\mathbf{Q}\mathbf{Q}^\top)\mathbf{A}\|_\mathrm{F}\leq\left(1+\sqrt{\frac{k}{h}}\right)\left(\sum_{j=k+1}^{n}\sigma_j^2\right)^{\frac{1}{2}}+u\frac{\sqrt{k+h}+\sqrt{k}}{h}\sigma_{k+1},\label{eq4.15}
    \end{align}
    \end{small}
    with failure probability not exceeding $e^{-u^2/2}$, and 
    \begin{footnotesize}
    \begin{multline}\label{eq4.16}
    \|(\mathbf{I}-\mathbf{Q}_P\mathbf{Q}_P^\top)\mathbf{A}\|\leq\\
    \left(\left(1+\sqrt{\frac{k}{h}}\right)\sigma_{k+1}^{2P+1}+\frac{\sqrt{k+h}+\sqrt{k}}{h}\left(\sum_{j=k+1}^{n}\sigma_j^{2(2P+1)}\right)^{\frac{1}{2}}+u\frac{\sqrt{k+h}+\sqrt{k}}{h}\sigma_{k+1}^{2P+1}\right)^{\frac{1}{2P+1}}
    \end{multline}
    \end{footnotesize}
     with failure probability not exceeding $e^{-u^2/2}$.
\end{theorem}

\begin{proof}[Proof of Theorem \ref{thm4.8}]
    We restrict our proof to the non-power iteration case, with the bounds for the power iteration version being straightforwardly inferred from \cite[Proposition 8.6]{halko2011finding}. According to Lemma \ref{lemma4.1}, when the random matrix $\mathbf{\Phi}$ is chosen as a standard Gaussian matrix $\mathbf{G}$, denote $\mathbf{\Phi}_1=\mathbf{V}_1^\top\mathbf{G},\mathbf{\Phi}_2=\mathbf{V}_2^\top\mathbf{G}$, then
    $$\interleave(\mathbf{I}-\mathbf{Q}\mathbf{Q}^\top)\mathbf{A}\interleave^2\leq\interleave\mathbf{\Sigma}_2\interleave^2+\interleave\mathbf{\Sigma}_2\mathbf{\Phi}_2\mathbf{\Phi}_1^\dagger\interleave^2.$$
    Therefore, according to the H{\"o}lder's inequality, $$\mathbb{E}\|(\mathbf{I}-\mathbf{Q}\mathbf{Q}^\top)\mathbf{A}\|_\mathrm{F}\leq\left(\mathbb{E}\|(\mathbf{I}-\mathbf{Q}\mathbf{Q}^\top)\mathbf{A}\|_\mathrm{F}^2\right)^{\frac{1}{2}}\leq\left(\|\mathbf{\Sigma}_2\|_\mathrm{F}^2+\mathbb{E}\|\mathbf{\Sigma}_2\mathbf{\Phi}_2\mathbf{\Phi}_1^\dagger\|_\mathrm{F}^2\right)^{\frac{1}{2}},$$
    then by applying \eqref{eq4.4}, \eqref{eq4.7}, and the law of total expectation, we have $$\mathbb{E}\|\mathbf{\Sigma}_2\mathbf{\Phi}_2\mathbf{\Phi}_1^\dagger\|_\mathrm{F}^2=\mathbb{E}\left(\mathbb{E}\left(\left\|\mathbf{\Sigma}_2\mathbf{\Phi}_2\mathbf{\Phi}_1^\dagger\right\|_\mathrm{F}^2\mid\mathbf{\Phi}_1\right)\right)=\mathbb{E}\left(\left\|\mathbf{\Sigma}_2\right\|_\mathrm{F}^2\left\|\mathbf{\Phi}_1^\dagger\right\|_\mathrm{F}^2\right)=\frac{k}{h}\|\mathbf{\Sigma}_2\|_\mathrm{F}^2.$$
    The last equality above holds since $\|\mathbf{G}^\dagger\|_\mathrm{F}\to\sqrt{{k}/{h}}$, implying $\mathbb{E}\|\mathbf{G}^\dagger\|_\mathrm{F}^2\to k/h$. Consequently, $\mathbb{E}\|(\mathbf{I}-\mathbf{Q}\mathbf{Q}^\top)\mathbf{A}\|_\mathrm{F}\leq\left(1+k/h\right)^{1/2}\left(\sum_{j=k+1}^{n}\sigma_j^2\right)^{1/2}$, thereby \eqref{eq4.13} holds.

    For the expected spectral error bound, by H{\"o}lder's inequality and \eqref{eq4.5}, then
    \begin{equation}\begin{aligned}
\mathbb{E}\|\mathbf{\Sigma}_{2}\mathbf{\Phi}_2\mathbf{\Phi}_1^{\dagger}\|\leq\mathbb{E}(\|\mathbf{\Sigma}_{2}\|\|\mathbf{\Phi}_1^{\dagger}\|_{\mathrm{F}}+\|\mathbf{\Sigma}_{2}\|_{\mathrm{F}}\|\mathbf{\Phi}_1^{\dagger}\|).\notag
\end{aligned}\end{equation}
According to Lemma \ref{lemma4.6}, $\lim\limits_{k\to\infty}\|\mathbf{G}^\dagger\|\leq(\sqrt{k+h}-\sqrt{k})^{-1}$ . Therefore,
\begin{small}
\begin{align*}
        \mathbb{E}\|(\mathbf{I}-\mathbf{Q}\mathbf{Q}^\top)\mathbf{A}\|&\leq\left(\mathbb{E}\|(\mathbf{I}-\mathbf{Q}\mathbf{Q}^\top)\mathbf{A}\|^2\right)^{\frac{1}{2}}\leq\left(\|\mathbf{\Sigma}_2\|^2+\mathbb{E}\|\mathbf{\Sigma}_2\mathbf{\Phi}_2\mathbf{\Phi}_1^\dagger\|^2\right)^{\frac{1}{2}}\\
        &\leq\|\mathbf{\Sigma}_2\|+\mathbb{E}\|\mathbf{\Sigma}_2\mathbf{\Phi}_2\mathbf{\Phi}_1^\dagger\|\leq\|\mathbf{\Sigma}_2\|+\left\|\mathbf{\Sigma}_2\right\|\mathbb{E}\|\mathbf{\Phi}_1^\dagger\|_\mathrm{F}+\left\|\mathbf{\Sigma}_2\right\|_\mathrm{F}\cdot\mathbb{E}\|\mathbf{\Phi}_1^\dagger\|\\
        &\leq\left(1+\sqrt{\frac{k}{h}}\right)\sigma_{k+1}+\frac{\sqrt{k+h}+\sqrt{k}}{h}\left(\sum_{j=k+1}^{n}\sigma_j^2\right)^{\frac{1}{2}}.
\end{align*}
\end{small}

For the probabilistic error bounds, consider the function $f_1(\mathbf{X})=\|\mathbf{\Sigma}_2\mathbf{X}\mathbf{\Phi}_1^\dagger\|,\\f_2(\mathbf{X})=\|\mathbf{\Sigma}_2\mathbf{X}\mathbf{\Phi}_1^\dagger\|_\mathrm{F}$, then $|f_1(\mathbf{X})-f_1(\mathbf{Y})|\leq\|\mathbf{\Sigma}_2\|\|\mathbf{X}-\mathbf{Y}\|\|\mathbf{\Phi}_1^\dagger\|\leq\|\mathbf{\Sigma}_2\|\|\mathbf{X}-\mathbf{Y}\|_\mathrm{F}\|\mathbf{\Phi}_1^\dagger\|$, which implies that $f_1$ is $L$-Lipschitz, where $L\leq\|\mathbf{\Sigma}_2\|\|\mathbf{\Phi}_1^\dagger\|.$ Moreover, \eqref{eq4.5} ascertains that $\mathbb{E}\left(f_1(\mathbf{\Phi}_2)|\mathbf{\Phi}_1\right)\leq\|\mathbf{\Sigma}_2\|\|\mathbf{\Phi}_1^\dagger\|_\mathrm{F}+\|\mathbf{\Sigma}_2\|_\mathrm{F}\|\mathbf{\Phi}_1^\dagger\|$. Relying on Lemma \ref{lemma4.3} intimates that $$\mathbb{P}\left(\|\mathbf{\Sigma}_2\mathbf{\Phi}_2\mathbf{\Phi}_1^\dagger\|\geq\|\mathbf{\Sigma}_2\|\|\mathbf{\Phi}_1^\dagger\|_{\mathrm{F}}+\|\mathbf{\Sigma}_2\|_{\mathrm{F}}\|\mathbf{\Phi}_1^\dagger\|+\|\mathbf{\Sigma}_2\|\|\mathbf{\Phi}_1^\dagger\|\cdot u\right)\leq\mathrm{e}^{-u^2/2}.$$

According to Lemma \ref{lemma4.6}, we have
{\small$$\mathbb{P}\left(\|\mathbf{\Sigma}_2\mathbf{\Phi}_2\mathbf{\Phi}_1^\dagger\|\geq\|\mathbf{\Sigma}_2\|\sqrt{\frac{k}{h}}+\|\mathbf{\Sigma}_2\|_{\mathrm{F}}\frac{\sqrt{k+h}+\sqrt{k}}{h}+\|\mathbf{\Sigma}_2\|\frac{\sqrt{k+h}+\sqrt{k}}{h}\cdot u\right)\leq\mathrm{e}^{-u^2/2}.$$}
Then \eqref{eq4.16} holds since {\small$\|(\mathbf{I}-\mathbf{Q}\mathbf{Q}^\top)\mathbf{A}\|\leq\left(\|\mathbf{\Sigma}_2\|^2+\|\mathbf{\Sigma}_2\mathbf{\Phi}_2\mathbf{\Phi}_1^\dagger\|^2\right)^{1/2}\leq\|\mathbf{\Sigma}_2\|+\|\mathbf{\Sigma}_2\mathbf{\Phi}_2\mathbf{\Phi}_1^\dagger\|$.}

For the Frobenius case, note that $|f_2(\mathbf{X})-f_2(\mathbf{Y})|\leq\|\mathbf{\Sigma}_2\|\|\mathbf{X}-\mathbf{Y}\|_\mathrm{F}\|\mathbf{\Phi}_1^\dagger\|$, which intimates that $f_2$ is also $L$-Lipschitz, where $L\leq\|\mathbf{\Sigma}_2\|\|\mathbf{\Phi}_1^\dagger\|.$ Then by H{\"o}lder's inequality and \eqref{eq4.4}, $\mathbb{E}\left(f_2(\mathbf{\Phi}_2)|\mathbf{\Phi}_1\right)\leq\left(\mathbb{E}\Big(\|\mathbf{\Sigma}_2\mathbf{\Phi}_2\mathbf{\Phi}_1^\dagger\|_\mathrm{F}^2|\mathbf{\Phi}_1\Big)\right)^{\frac{1}{2}}=\|\mathbf{\Sigma}_2\|_\mathrm{F}\|\mathbf{\Phi}_1^\dagger\|_\mathrm{F}.$ Therefore, Lemma \ref{lemma4.3} extrapolates that $$\mathbb{P}(\|\mathbf{\Sigma}_2\mathbf{\Phi}_2\mathbf{\Phi}_1^\dagger\|_\mathrm{F}\geq\|\mathbf{\Sigma}_2\|_\mathrm{F}\|\mathbf{\Phi}_1^\dagger\|_\mathrm{F}+\|\mathbf{\Sigma}_2\|\|\mathbf{\Phi}_1^\dagger\| u)\leq\mathrm{e}^{-u^2/2}.$$
By Lemma \ref{lemma4.6}, \eqref{eq4.15} holds since $\|(\mathbf{I}-\mathbf{Q}\mathbf{Q}^\top)\mathbf{A}\|_\mathrm{F}\leq\left(\|\mathbf{\Sigma}_2\|_\mathrm{F}^2+\|\mathbf{\Sigma}_2\mathbf{\Phi}_2\mathbf{\Phi}_1^\dagger\|_\mathrm{F}^2\right)^{1/2}\leq\|\mathbf{\Sigma}_2\|_\mathrm{F}+\|\mathbf{\Sigma}_2\mathbf{\Phi}_2\mathbf{\Phi}_1^\dagger\|_\mathrm{F}$.
\end{proof}

Moreover, relying on Theorem \ref{thm3.2} and Propositions \ref{proposition3.5} and \ref{proposition3.6}, we further expand these error bounds for \texttt{farPCASB}, \texttt{farPCASS} and \texttt{farPCASG} by exploiting Lemma \ref{lemma4.7} and Theorem \ref{thm4.8}. We emphasize the error analysis of algorithms that do not utilize shifted power iteration, as the power parameters $P=0,1,2$ generally suffice for most applications. The shifted power iteration only works when $P>2$ and yields nearly optimal approximation results for larger values of $P$ (e.g. $P=5$ \cite{feng2023fast}).

\begin{theorem}[Error bounds for \texttt{farPCASB}, \texttt{farPCASS} and \texttt{farPCASG} without shifted power iteration]\label{thm4.9}
    Assume that $\mathbf{V}_A^\top=(u_{ij})$ satisfy condition \eqref{eq3.1}. Generate a standardized Bernoulli matrix or a sparse sign matrix or a sparse Gaussian matrix $\mathbf{\Upsilon}\in\mathbb{R}^{n\times l}$ with parameter $p\in(0,1)$, where $l=k+h\leq n$, $k\geq 2$ and $h\geq 2$. Consequently, if $\mathbf{Q}$ is an orthonormal basis for the range of $\mathbf{Y}=\mathbf{A}\mathbf{\Upsilon}$ and $\mathbf{Q}_P$ serves as an orthonormal basis for the range of $(\mathbf{A}\mathbf{A}^\top)^P\mathbf{Y}$ with $P$ being a natural number, then with probability $1$, \eqref{eq4.9} and \eqref{eq4.10} hold. Further suppose that $h\geq 4$, for all $u,t\geq 1$, \eqref{eq4.11} and \eqref{eq4.12} hold with failure probability not exceeding $2t^{-h}+e^{-u^2/2}$.

    Additionally, as $k\to\infty,k/(k+h)\to\gamma\in(0,1)$, \eqref{eq4.13} and \eqref{eq4.14} hold with probability $1$, and \eqref{eq4.15} and \eqref{eq4.16} hold with failure probability not exceeding $e^{-u^2/2}$ for all $u>0$.
\end{theorem}

\begin{proof}
    For \eqref{eq4.9}-\eqref{eq4.12}, the proof straightforwardly derives from Lemma \ref{lemma4.7} since $\mathbf{V}_A^\top\mathbf{\Upsilon}$ is asymptotically equivalent to $\mathbf{V}_A^\top\mathbf{G}$ by exploiting Theorem \ref{thm3.2} and Propositions \ref{proposition3.5} and \ref{proposition3.6}. For the asymptotic error bounds \eqref{eq4.13}-\eqref{eq4.16}, the proof follows directly from Theorem \ref{thm4.8}, with the same argument that $\mathbf{V}_A^\top\mathbf{\Upsilon}$ is asymptotically equivalent to $\mathbf{V}_A^\top\mathbf{G}$.
\end{proof}

\section{Numerical experiments}\label{sec5}
In this section, we present some numerical experiments to elucidate the effectiveness of \texttt{farPCASB}, \texttt{farPCASS}, and \texttt{farPCASG} relative to \texttt{farPCA} and \texttt{farPCA} based on the Bernoulli matrix (\texttt{farPCAB}). For the real data, MATLAB's \texttt{svds} function is exploited to produce precise results, after which \texttt{farPCASB}, \texttt{farPCASS}, and \texttt{farPCASG} are compared with \texttt{farPCA}, \texttt{farPCAB}, \texttt{randUBV}, and \texttt{svds} to assess its computational performance. Results for addressing the fixed-rank approximation and fixed-precision approximation problems are delineated in subsections \ref{sec5.1} and \ref{sec5.2}. Furthermore, the analysis of how variations in the parameter 
$p$ affect the performance of the four acceleration algorithms is presented in subsection \ref{sec5.3}. We also examine these algorithms on real data in subsection \ref{sec5.4} and finally discuss their stability in subsection \ref{sec5.5}.

For simulations, we generate two kinds of $n\times n$ matrices:
\begin{itemize}
    \item Matrix $1$ (slow decay): Let $\mathbf{A}$ be the form $\mathbf{A}=\mathbf{U}_A\mathbf{\Sigma}_A\mathbf{V}_A^\top$, where $\mathbf{U}_A,\mathbf{V}_A\in\mathbb{R}^{n\times n}$ are attained by orthonormalizing the standard Gaussian matrices. The diagonal values of the diagonal matrix $\mathbf{\Sigma}_A$ are: $\sigma_j=1/j^2$ for $1\leq j\leq n$. This matrix is Matrix $1$ in \cite[Section 5.1]{hallman2022block}.
    \item Matrix $2$ (fast decay): $\mathbf{A}$ is built in the same manner as Matrix $2$, except that the singular values become: $\sigma_j=e^{-j/20}$ for $1\leq j\leq n$. This matrix is Matrix 3 in \cite[Section 5.1]{hallman2022block}.
\end{itemize}

Execution time, rank, and error metrics for the algorithms in subsections \ref{sec5.1} to \ref{sec5.3} are averaged over multiple trials with identical input matrices and $i.i.d.$ random test matrices. Denoting the approximation of $\mathbf{A}$ by $\hat{\mathbf{A}}$, the relative Frobenius-norm error is $\|\mathbf{A}-\hat{\mathbf{A}}\|_\mathrm{F}/\|\mathbf{A}\|_\mathrm{F}.$ All experiments were conducted in MATLAB 2024b on an Intel Core i9-12900KF CPU with 64 GB of DDR5 RAM.

\subsection{Efficiency validation for solving the fixed-rank problems}\label{sec5.1}

In practical applications of fixed-rank problems, rank $l$ is selected directly as the number of columns of $\mathbf{U}$ output in these algorithms. Notably, an exceedingly small $p$ could result in rank deficiency, requiring more iterations. Specifically, when $p$ is slightly larger, the algorithm stabilizes and becomes less sensitive to the choice of 
$p$, as will be elaborated in subsection \ref{sec5.3}. Nevertheless, $p$ must be minimal enough to capitalize on the sparsity (e.g., $p\leq0.1$). Practically, for an $m\times n$ target matrix with $m\geq n$, we recommend setting $p=10^{-3}$ when $n$ is large, which can leverage Theorem \ref{thm3.2} to attain the asymptotic behavior of $\mathbf{V}_A^\top\mathbf{B}$. Conversely, for smaller $n$, as the asymptotic results do not apply, a relatively larger value of $p$ is recommended to refrain from the risk of rank deficiency. Therefore, we empirically set $p_1=\max\{10^{-3},\ln(n)/n\}$ for \texttt{farPCASB} and $p_2=\max\{10^{-3},10/n\}$ for \texttt{farPCASS}, \texttt{farPCASG}, and \texttt{farPCAB}. To evaluate the performance, two types of input matrices of size $n\times n$ were generated, with $n$ set to $5000$, $10000$, and $30000$. The block size $b$ fixed at $20$, while $l$ ranges from $b$ to $10b$. The average results of $20$ experiments for power parameter $P=1$ and $P=0$ are summarized in Figure \ref{fig1} and Figure \ref{fig2}, respectively.

