\title{The Hamiltonian surface of $\Aut(F_2)$}
\author{Sylvain Barr\'e}
\author{Mika\"el Pichot}
\address{Sylvain Barr\'e, UMR 6205, LMBA, Université de Bretagne-Sud,BP 573, 56017, Vannes, France}\email{Sylvain.Barre@univ-ubs.fr}
