\section{Proof of Theorem~\ref{thm:semicircle}} \label{sec:proof_semicircle}
\subsection{Trace expansion}
Denote \[\bQ=\bA-\E\bA.\]
We will show Theorem~\ref{thm:semicircle} by applying the moment method to $\bQ$. 
We start with the trace expansion,
\begin{align}
    \frac{1}{n}\E\tr\left(\frac{\bQ}{\sqrt{np(1-p)}} \right)^k=\frac{1}{n^{k/2+1}(p(1-p))^{k/2}}\sum_{i_1,\dots,i_k\in [n]} \E[\bQ_{i_1i_2}\bQ_{i_2i_3}\cdots \bQ_{i_{k-1}i_k} \bQ_{i_ki_1}], \label{eq:trace_expand}
\end{align}
where the sum is over all sequences $(i_1,\dots,i_k)$ with $i_{j}\not=j_{j-1}, 2\leq j\leq k$ and $i_k\not=i_1$. The sequence $(i_1,\dots,i_k,i_1)$ corresponds to a closed walk of length $k+1$ on a complete graph with $n$ vertices. For each closed walk $I=(i_1,\dots,i_k,i_1)$, we can associate a graph $G_I=(V,E)$. 
We classify closed walks into two categories:
\begin{itemize}
    \item $\mathcal{C}_1$: Closed walks in which each edge is traversed exactly twice, and the underlying graph is a tree.
    \item $\mathcal{C}_2$: All other closed walks not included in $\mathcal{C}_1$.
\end{itemize}

We write \eqref{eq:trace_expand} as 
\begin{align}
    \frac{1}{n}\E\tr\left(\frac{\bQ}{\sqrt{np(1-p)}} \right)^k=S_1+S_2, 
\end{align}
where $S_i$ is the contribution from all $G_I$ in $\mathcal{C}_i$. 
We estimate each $S_i$  in the following subsections. 



\subsection{Estimating $S_1$}\label{sec:S_1}

By our definition, $S_1=0$ if $k$ is odd since closed walks on the tree must be of even length. Now we assume $k=2m$, then for each closed walk $I\in \mathcal C_1$, $G_I=(V,E)$ is a tree and we must have  $|V|=m+1$ and $|E|=m$.  With \eqref{eq:trace_expand},
\begin{align}
     S_1&=\frac{1}{n^{m+1} (p(1-p))^m} \sum_{(i_1,i_2,...i_{2m})\in \mathcal C_1} \mathbb{E} [\bQ_{i_1,i_2} \bQ_{i_2,i_3} ...\bQ_{i_{2m},i_1}] 
\end{align}
Let $\mathcal T_m$ be the set of all rooted planar trees with $m+1$ vertices, then 
\begin{align}\label{eq:Catalan}
|\mathcal  T_m|=\frac{\binom{2m}{m}}{m+1},
\end{align}
which is the $m$-th Catalan number \cite{stanley2011enumerative}. For each unlabeled rooted planar tree $T\in \mathcal T_m$, there are $n(n-1)\cdots (n-m)=(1+o(1))n^{m+1}$ many ways to label $T$ with distinct vertex labels from $[n]$. Each rooted planar tree $T$ with $m+1$  distinct vertex labels in $[n]$ corresponds to a closed walk $(i_1,\dots, i_{2m})$, with the vertex sequence in the depth-first search on $T$.
We apply a canonical labeling with $\{1,\dots, m+1\}$ to vertices in $T$ such that whenever the $k$-th distinct vertex $v$ is visited by the depth-first search on $T$ for the first time, $v$ is assigned with a label $k\in [m+1]$. \\
Since each edge in $T$ is visited exactly twice, we can rewrite $S_1$ as 
\begin{align}\label{eq:S_1}
    S_1=\frac{n(n-1)\cdots (n-m)}{n^{m+1} (p(1-p))^m}\sum_{T\in \mathcal T_m} \E \prod_{e\in E(T)}\bQ_{e}^2,
\end{align}
where $\bQ_{e}=\bQ_{ij}$ if $e=\{i,j\}$, which represents the entry of $\bQ$ index by an edge $e\in T$. 
Let $T$ be a tree with $m$ edges $e_1, \dots, e_m$ and $m+1$ vertices $v_1, \dots, v_{m+1}$. Since each $v \in V(T)$ corresponds to a latent vector $\bv \in \mathbb{R}^d$, 
we define
\begin{align} \label{eq:expectation_tree}
    \E \prod_{e \in E(T)} \bQ_{e}^2
\end{align}
as the expectation taken over all vectors corresponding to the vertices $v \in V(T)$. We denote the collection of such vectors by $\mathcal{V}$.


We aim to compute \eqref{eq:expectation_tree}
by recursively peeling off the leaves of the tree. At each step, we choose one of the leaf edges $e^* = (v_1^*, v_2^*)$, where $v_1^*$ is a leaf node and $v_2^*$ is an internal node. We condition on the random vector $\bv_2^*$ associated with node $v_2^*$ to make the leaf edge independent from the rest of the tree.
 By independence, we can write:
\begin{align}
\E_{ \bv \in \mathcal{V} } \prod_{e \in E(T)} \bQ_e^2 
= \E_{\bv_2^*}  \E_{\bv \in \mathcal{V} \setminus \{\bv_2^*\}} \prod_{e \in E(T)} \bQ_e^2 
= \E_{\bv_2^*}\left[  \E_{\bv \in \mathcal{V} \setminus \{\bv_1^*, \bv_2^*\}} \prod_{e \in E(T) \setminus \{e^*\}} \bQ_e^2  \cdot \E_{\bv_1^*}  \bQ_{e^*}^2 \right].
\end{align}
Since for each edge, $\bQ_e$ satisfies
\begin{align}
\E \bQ_e^2 = p(1 - p)^2 + (1 - p)(-p)^2 = p(1 - p),
\end{align}
we can iteratively peel off one leaf at a time, multiplying the expectation by $p(1 - p)$ at each step. Repeating this for all $m$ edges in the tree, we obtain:
\begin{align} \label{eq:q^2}
\E \prod_{e \in E(T)} \bQ_e^2 = [p(1 - p)]^m.
\end{align}
From equations \eqref{eq:S_1} and \eqref{eq:Catalan}, this gives:
\begin{align}\label{eq:S_1_catalan}
S_1 =
\begin{cases}
(1 + o(1)) \dfrac{\binom{2m}{m}}{m + 1} & \text{if } k = 2m, \\
0 & \text{if } k \text{ is odd}.
\end{cases}
\end{align}


\subsection{Estimating $S_2$}


Note that in the analysis of $S_1$, no assumption on $d$ is used. However, estimating $S_2$ involves closed walks where certain edges are traversed only once, and their contributions depend on the vector dimension $d$. To establish that closed walks in $\mathcal{C}_2$ have vanishing contributions to the moment, we combine \textit{block-cut tree decomposition} and the \textit{ear decomposition} and algorithmically evaluate the moment.  

\subsubsection{A graph decomposition algorithm}\label{sec:graph_decomposition}
Recall that we want to evaluate 
\begin{align}
S_2 &= \frac{1}{n^{k/2+1} (p(1-p))^{k/2}} \sum_{(i_1,i_2,\dots,i_k) \in \mathcal{C}_2} \mathbb{E} [\bQ_{i_1,i_2} \bQ_{i_2,i_3} \cdots \bQ_{i_k,i_1}].
\end{align}
For a closed walk of length $k$, $I = (i_1, \dots, i_k) \in \mathcal{C}_2$, we denote by $G_I = (V, E)$ the simple graph spanned by $I$, with $v = |V|$ and $e = |E|$. Let $\mathcal{G}_2$ denote the collection of distinct unlabeled graphs obtained from all possible closed walks in $\mathcal{C}_2$. For each $G \in \mathcal{G}_2$, there are \[n(n - 1) \cdots (n - v + 1) = O(n^v)\] ways to label it. It suffices to evaluate the contribution of a fixed $G \in \mathcal{G}_2$, given by
\begin{align} \label{eq:S_2_goal}
 \mathbb{E}_{v \in V(G)} \prod_{e \in E(G)}\bQ_{e}^{m(e)} ,
\end{align}
where $m(e)$ denotes the multiplicity of each edge $e \in E(G)$, and the expectation is taken over the random vectors $\bv$ corresponding to each vertex $v\in V(G)$ as we did in Section~\ref{sec:S_1}.  We proceed with the following steps.


\medskip
\noindent \textbf{Step 1: A block-cut tree of $G$}



Recall the definition of a block-cut tree from Definition~\ref{def:block_cut}.
We decompose the graph $G$ into its 2-edge-connected components, which are connected by bridges. Since $G$ is spanned by a closed walk $I$, every bridge must be traversed at least twice. We express $G$ as
\begin{align}
    G = \bigcup_{i=1}^{r} G_{C_i} \cup \bigcup_{j=1}^{q} F_j,
\end{align}
where each $G_{C_i}$ denotes a \textit{2-edge-connected component}, and each $F_j$ is a \textit{bridge component}. This gives a \textit{block-cut tree} of $G$.  Note that when $r=0$, $G$ is a tree.



Denote by $v_{F_j}$ and $e_{F_j}$ the number of vertices and edges in  $F_j$, respectively, and by $v_{C_i}$ and $e_{C_i}$ the number of vertices and edges in the 2-edge-connected component $G_{C_i}$, respectively. 




Let $J(G)$ be the set of all junction vertices in $G$ defined in Definition~\ref{def:junction}.
We condition on all junction vertices to make the contribution from each 2-edge-connected component and each bridge independent. We can bound \eqref{eq:S_2_goal} by
\begin{align}
    &\left| \mathbb{E}_{v \in V(G)} \prod_{e \in E(G)}\bQ_{e}^{m(e)}\right|\\
    \leq &\E_{v\in J(G)}\prod_{i=1}^r  \left|\E_{v\in V(G_{C_i})\setminus J(G)} \!\! \prod_{e \in E(G_{C_i})} \!\!\bQ_e^{m(e)} \right|   \prod_{j=1}^q \left|\E_{v\in V(F_j)\setminus J(G)} \prod_{e \in E(F_j)} \bQ_e^{m(e)} \right|. \label{eq:total_bound_G}
\end{align}




\medskip

\noindent\textbf{Step 2: Evaluating  the expectation of a leaf component} 

Denote $T(G)$ the block-cut tree of $G$. A leaf of $T(G)$ has two possibilities: 
\begin{enumerate}
    \item It corresponds to a leaf in $G$, belonging to certain $F_j$.
    \item It corresponds to 2-edge-connected component $G_{C_i}$ that only contains one junction vertex.
\end{enumerate}
We call this $F_j$ or $G_{C_i}$ an leaf component of $G$. We treat the two cases separately. 

\medskip

\noindent \textbf{Case 1: $F_j$ is a leaf component}

Since each edge in the bridge path $F_j$ is traversed at least twice and $F_j$ contains a leaf vertex in $G$, by \eqref{eq:q^2}, and the fact $|Q_e|\leq 1$, we have 

\begin{align}
    \left|\E_{v\in V(F_j)\setminus J(G)} \prod_{e \in E(F_j)} \bQ_e^{m(e)} \right|\leq  \E_{v\in V(F_j)\setminus J(G)} \prod_{e \in E(F_j)} \bQ_e^2=[p(1-p)]^{v_{F_j}-1},  \label{eq:leaf_F}
\end{align}
where the last identity holds by taking the conditional expectation sequentially as in \eqref{eq:q^2}.

\medskip

\noindent \textbf{Case 2: $G_{C_i}$ is a leaf component}




We now deal with the conditional expectation from a 2-edge-connected component $G_{C_i}$, where $G_{C_i}$ contains only one junction vertex. 

Our analysis relies on the \textit{ear decomposition} defined in Definition~\ref{def:ear_decompose}. By Lemma~\ref{eq:ear}, we can find an ear decomposition whose initial cycle $R_1$ contains the junction vertex in $G_{C_i}$.
Let $(R_1, R_2, \dots, R_s)$ be the ear decomposition of $G_{C_i}$, where $s=s(C_i)$ is the number of ears.  Let $e_{R_j} = |E(R_j)|$.   By the properties of the ear decomposition, we have
\begin{align}\label{eq:ear_number}
    e_{C_i} &= \sum_{j=1}^{s(C_i)} e_{R_j}.
\end{align}
We have the following inequality from the ear decomposition:
\begin{align}
\left|\E_{v\in V(G_{C_i})\setminus J(G)} \!\! \prod_{e \in E(G_{C_i})} \!\!\bQ_e^{m(e)} \right|\leq \E_{v\in V(G_{C_i})\setminus J(G)}  \prod_{j=1}^s \left| \E_{v\in V(R_j)\setminus J(G)}\prod_{e \in E(R_j)} \!\!\bQ_e^{m(e)}  \right|.
\end{align}

Next, we handle the contribution from each ear recursively. There are two subcases:

\medskip

\noindent \textbf{Case (1): $s=1$}. In this case, $G_{C_i}$ is a cycle of length $e_{C_i}$. Note that $G_{C_i}$ contains only one junction vertex, with Lemma~\ref{lemma:decomposition}, we have 
\begin{align}
    \left|\E_{v\in V(G_{C_i})\setminus J(G)} \!\! \prod_{e \in E(G_{C_i})} \!\!\bQ_e^{m(e)} \right|&=\left|\E \!\! \prod_{e \in E(G_{C_i})} \!\!\bQ_e^{m(e)} \right|\\
    &=\left|\E \!\! \prod_{e \in E(G_{C_i})} (\alpha_{m(e)} \bQ_e+\beta_{m(e)})\right|, \label{eq:decom_exp}
\end{align}
where $\alpha_{m(e)},\beta_{m(e)}$ are constants
with $\alpha_{m(e)}\in [0,1]$. We can expand the expectation in \eqref{eq:decom_exp} to obtain 
\begin{align}
  \E \prod_{ e \in E(G_{C_i})} [\bQ_e\alpha_{m(e)}+\beta_{m(e)}] &=\E\prod_{e \in E(G_{C_i})}\bQ_e\alpha_{m(e)} + \sum_{S \subsetneq E(G_{C_i})} \E\prod_{e \in S} \bQ_e\alpha_{m(e)} \prod_{e \notin S} \beta_{m(e)} \\
  &=\E\prod_{e \in E(G_{C_i})}\bQ_e\alpha_{m(e)}, \label{eq:decom_exp1}
\end{align}
where the second term on the right-hand side vanishes because each subset $S\subsetneq E(G_{C_i})$ forms a forest and the expectation is zero due to the conditional independence of edges. 

On the other hand, by a binomial expansion and the conditional independence of edges,
\begin{align}
    \left|\E\prod_{e \in E(G_{C_i})}\bQ_e\right|&= \left|\E \prod_{e \in E(G_{C_i})}(\bA_e-p)\right|\\
    &=\left|\E\prod_{e \in E(G_{C_i})}\bA_e- p^{e_{C_i}}\right|\leq  C p^{e_{C_i}-1} (C\tau)^{e_{C_i}-2} \sqrt{\log(1/p)}\label{eq:decom_exp2}
\end{align}
for an absolute constant $C>0$,  where the last inequality is due to the cycle probability estimate from \eqref{eq:cycle_probability}. 


Combining all \eqref{eq:decom_exp}, \eqref{eq:decom_exp1}, and \eqref{eq:decom_exp2}, we obtain 
\begin{align}
 \left|\E_{v\in V(G_{C_i})\setminus J(G)} \!\! \prod_{e \in E(G_{C_i})} \!\!\bQ_e^{m(e)} \right| \leq   C p^{e_{C_i}-1} (C\tau)^{e_{C_i}-2} \sqrt{\log(1/p)}. 
\end{align}



\medskip

\noindent \textbf{Case (2): $s\geq 2$}. In this case,   $R_2,\dots, R_s$ are paths. Note that the last ear $R_s$ only intersects with the previously constructed subgraph $\bigcup_{j=1}^{s-1} R_j$  through its two endpoints. Let $J(R_j)$ be the set of the two endpoints in $R_j$. There are two cases depending on $e_{R_j}$: 
\begin{itemize}
    \item If $e_{R_j}\geq 3$, using the the expansion as in \eqref{eq:decom_exp}  \eqref{eq:decom_exp1}, and \eqref{eq:decom_exp2}, the contribution of $R_j$ is bounded by  
\begin{align}
     \left|\E_{v\in V(R_j)\setminus J(R_j)} \!\! \prod_{e \in E(R_j)} \!\!\bQ_e^{m(e)} \right|&\leq \left|\E_{v\in V(R_j)\setminus J(R_j)}\prod_{e \in E(R_j)}\bA_e- p^{e_{R_j}}\right|\\
     &\leq C p^{e_{R_j}-1} (C\tau)^{e_{R_j}-2} \sqrt{\log(1/p)} \label{eq:last_ear},
\end{align}
where in the last inequality, we use the path probability estimate from Lemma~\ref{eq:path_probability}.
\item If $e_{R_j}=2$, let $(v_1,v_2,v_3)$ be the path formed by $R_j$ with $e_1=(v_1,v_2), e_{2}=(v_2,v_3)$, we have 
\end{itemize}



\begin{align}
     \left|\E_{v\in V(R_j)\setminus J(R_j)} \!\! \prod_{e \in E(R_j)} \!\!\bQ_e^{m(e)} \right|&=\left|\E_{v_2} [\bQ_{v_1v_2}^{m(e_1)} \bQ_{v_2v_3}^{m(e_2)}]\right|\leq |\E_{v_2} \bQ_{v_1v_2}\bQ_{v_2v_3}|\leq \E_{v_2}|\bQ_{v_1v_2}|\leq 2p, \label{eq:ear_length_2}
\end{align}
where in the first inequality we use \eqref{eq:decom_exp}. Let $t_{C_i}$ be the number of length-2 ears in $G_{C_i}$.
We can apply the estimate \eqref{eq:last_ear} and \eqref{eq:ear_length_2} sequentially by peeling off $R_s,\dots, R_{2}$, and finally $R_1$  to obtain

\begin{align}
      &\left|\E_{v\in V(G_{C_i})\setminus J(G)} \!\! \prod_{e \in E(G_{C_i})} \!\!\bQ_e^{m(e)} \right|\\
      \leq & \prod_{j=2}^{s_{C_i}} \left( p^{e_{R_j}-1} (C\tau)^{e_{R_j}-2} C\sqrt{\log(1/p)} \1_{e_{R_j>2}} + 2p \1 _{e_{R_j}=2}\right) p^{e_{R_1}-1} (C\tau)^{e_{R_1}-2} C\sqrt{\log(1/p)}\\
      =& 2^{t_{C_i}}  p^{e_{C_i}-s_{C_i}} (C\tau)^{e_{C_i}-2s_{C_i}} C^{s_{C_i}-t_{C_i}}\log^{(s_{C_i}-t_{C_i})/2}(1/p), \label{eq:case12}
\end{align}
where $s_{C_i}$ is the number of ears in $G_{C_i}$.
Compared to \eqref{eq:decom_exp2}, we can see \eqref{eq:case12} holds for both Cases (1) and (2).


\medskip

\noindent \textbf{Step 3: Peeling off the block-cut tree}





In Step 2, we have shown how to evaluate the contribution from the first leaf component in the block-cut tree of $G$.
Now, we decompose each graph $G$ by starting with any leaf component in its block-cut tree. 
After evaluating its conditional expectation, we sequentially remove leaf components one by one until the block-cut tree is empty. 

Using the conditional independence, combining \eqref{eq:leaf_F} and \eqref{eq:case12}, we can bound \eqref{eq:total_bound_G} by
\begin{align}
  & \left| \mathbb{E}_{v \in V(G)} \prod_{e \in E(G)}\bQ_{e}^{m(e)}\right|\\
   &\leq \prod_{i=1}^r \left(2^{t_{C_i}}  p^{e_{C_i}-s_{C_i}} (C\tau)^{e_{C_i}-2s_{C_i}}C^{s_{C_i}-t_{C_i}}\log^{(s_{C_i}-t_{C_i})/2}(1/p)\right) \prod_{j=1}^q  p^{v_{F_j}-1}\\
   % &=\prod_{i=1}^r \left(2^{t_{C_i}}  p^{e_{C_i}-s_{C_i}} (C\tau)^{e_{C_i}-2s_{C_i}}C^{s_{C_i}-t_{C_i}}\log^{(s_{C_i}-t_{C_i})/2}(1/p)\right) \prod_{j=1}^q  p^{e_{F_j}}.
   &= 2^{\sum_{i=1}^r t_{C_i}}p^{e(G)-\sum_{i=1}^r s_{C_i}} (C\tau)^{\sum_{i=1}^r (e_{C_i}-2 s_{C_i})} C^{\sum_{i=1}^r(s_{C_i}-t_{C_i})}\log^{\frac{1}{2} \sum_{i=1}^r(s_{C_i}-t_{C_i}) }(1/p). 
   \label{eq:G_bound}
\end{align} 
Denote $t(G)=\sum_{i=1}^r t_{C_i}$  the total number of length-2 ears in $G$.
Since the number of all ears in the block-cut tree is the excess of $G$ denoted by \[g(G):=e(G)-v(G)+1,\] we have 
 $\sum_{i=1}^r s_{C_i}=g(G)=e(G)-v(G)+1$.
We also denote $c(G)=\sum_{i=1}^r e_{C_i}$ to be the number of total edges in all 2-edge-connected components of $G$. Then we can simplify  \eqref{eq:G_bound} as
\begin{align}
  \left| \mathbb{E} \prod_{e \in E(G)}\bQ_{e}^{m(e)}\right|&\leq   2^{t(G)} p^{v(G)-1}(C\tau)^{c(G)-2g(G)}\left(C\sqrt{\log (1/p)}\right)^{g(G)-t(G)},\label{eq:G_bound2}
\end{align}
which holds for any $G\in \mathcal G_2$.

\subsubsection{Bounding $S_2$}
Recall 
\begin{align}
S_2 &= \frac{1}{n^{k/2+1} (p(1-p))^{k/2}} \sum_{(i_1,i_2,\dots,i_k) \in \mathcal{C}_2} \mathbb{E} [\bQ_{i_1,i_2} \bQ_{i_2,i_3} \cdots \bQ_{i_k,i_1}] \\ &= \sum_{G \in \mathcal{G}_2} \Bigl[ \frac{n^{v(G)}}{n^{k/2+1} (p(1-p))^{k/2}} \mathbb{E} \prod_{e \in E(G)}\bQ_{e}^{m(e)} \Bigl].
\end{align}

For each $G \in \mathcal{G}_2$, from \eqref{eq:G_bound2}, since $p\in [0,p_0]$,
\begin{align}
    \frac{n^{v(G)}}{n^{k/2+1} (p(1-p))^{k/2}} \left|\mathbb{E} \prod_{e \in E(G)}\bQ_{e}^{m(e)}\right|\leq 2^{k/2+t}  (np)^{v-1-k/2} (C\tau)^{c-2g}(C\sqrt{\log(1/p)})^{g-t}.
       \label{eq:each_G}
\end{align}
Here, $t$, $v$, $c$, and $g$ stand for $t(G)$, $v(G)$, $c(G)$, and $g(G)$, respectively.


We now consider two cases:

\medskip

\noindent\textbf{Case 1:  $G$ is a tree.}

In this case, since $G\in \mathcal G_2$ does not contribute to $S_1$, $G$ contains only bridges, and at least one bridge is visited more than twice. This implies 
\[v<1+\frac{k}{2}, \quad \text{ and } t=c=g=0. \]
Therefore, since $np\to\infty$, \eqref{eq:each_G} is bounded by 
\[2^{k/2} (np)^{-1} =o(1).\]


\medskip

\noindent\textbf{Case 2:  $G$ is not a tree.}

In this case,  we have $g\geq 1$.
Since  $\tau\leq C'\sqrt{\frac{\log(1/p)}d}$ for some absolute constant $C'>0$ from Lemma~\ref{lemma:tau}, we can find a constant $C>0$ and  bound \eqref{eq:each_G} by 
\begin{align}
   & 2^{k/2+t}  (np)^{v-1-k/2} (C \sqrt{\frac{\log(1/p)}{d}})^{c-2g}(C\sqrt{\log(1/p)})^{g-t} \\ = &2^{k/2+t} C^{c-g-t} \frac{(np)^{v-1-k/2}\log(1/p)^{c/2-g/2-t/2}}{d^{c/2-g}}.
\end{align}
%= &2^{k/2+t+c/2-g} C^{c-2g} \frac{(np)^{v-1-k/2}\log(1/p)^{c/2-g}}{d^{c/2-g}}(C\sqrt{\log(1/p)})^{g-t}.
Since the number of edges in $G$ equals the sum of the number of edges in all bridges and the number of edges in all \textit{2-edge-connected components}, and since each edge in a bridge must be visited at least twice, we have
\[
e \leq c + \frac{k - c}{2} = \frac{k}{2} + \frac{c}{2}.
\]
Thus 
\[
v-1-\frac{k}{2} \leq  \frac{c}{2} -e+v-1 = \frac{c}{2}-g
\]
Thus we can bound \eqref{eq:each_G} by 
\begin{align}
    2^{k/2+t} C^{c-g-t}  \Bigl(\frac{np\log^2(1/p)}{d}\Bigl)^{c/2-g} (\log(1/p))^{3g/2-t/2-c/2}. \label{eq:final_bound1}
\end{align}
Since the total number of edges in all \textit{2-edge-connected components} equals twice the number of length-2 ears plus the number of edges in all other ears of length $\geq 3$, we have 
\begin{align}\label{eq:c3g}
c \geq 2t+ 3(g-t)=3g-t.
\end{align}
Moreover, by our construction of the ear decomposition, each 2-edge-connected component $G_{C_i}$ has at least a cycle ear $R_1$ of length at least $3$, so we have $g\geq t+1$, hence $c\geq 2g+1$.
 Under the assumption $d=\omega( np\log^2(1/p))$, we obtain \eqref{eq:final_bound1} is $o(1)$ for any fixed $k$. 


Combining Cases 1 and 2, since $|\mathcal{G}_2|$ is finite when $k$ is fixed, we conclude $S_2 = o(1)$. 

\subsection{Proof of Theorem~\ref{thm:semicircle}}
\begin{proof}[Proof of Theorem~\ref{thm:semicircle}]
Combining all the estimates above, we obtain
\begin{align}
  \lim_{n\to\infty} \frac{1}{n}\E\tr\left(\frac{\bQ}{\sqrt{np(1-p)}} \right)^k  & = S_1+S_2 = \begin{cases}
\frac{1}{m + 1} \binom{2m}{m} & \text{if } k = 2m, \\
0& \text{if } k \text{ is odd}.
\end{cases}
\end{align}
This implies the empirical spectral distribution of $\frac{\bQ}{\sqrt{np(1-p)}}$ converges weakly to the semicircle law.



 Define $\bB$ to be the $n \times n$ matrix obtained by subtracting $p$ from each entry of $\bA$, including the diagonal entries. Then $\operatorname{rank}(\bA-\bB) = 1$. By Lemma~\ref{lemma:rank_inequality},
\begin{align}\label{eq:rank_1}
    \| F^{\frac{\bA}{\sqrt{np(1-p)}}} - F^{\frac{\bB}{np(1-p)}} \| \leq \frac{1}{n},
\end{align}
and thus $\frac{\bA}{\sqrt{np(1-p)}}$ and $\frac{\bB}{np(1-p)}$ have the same limiting spectral distribution. Note that the matrix $\bQ$ differs from $\bB$ only in the diagonal entries. Moreover, adding $p\mathbb{I}$, where $\mathbb{I}$ is the identity matrix, shifts the eigenvalues by at most $p/\sqrt{np(1-p)} = o(1)$. Therefore $\frac{\bA}{\sqrt {np(1-p)}}$ and $\frac{\bQ}{\sqrt {np(1-p)}}$ have the same limiting spectral distribution. This finishes the proof of Theorem~\ref{thm:semicircle}.
\end{proof}

\section{Proof of Theorem~\ref{thm:constantp}}\label{sec:proof_constant}

Now we aim to show that for $\mathcal{G}(n, p, d)$, when $np = \alpha$ for some fixed constant $\alpha > 0$, the normalized adjacency matrix attains the same limiting spectral distribution as $G(n,\frac{\alpha}{n})$.  Again, we start with the trace expansion.
\begin{align}
    \frac{1}{n}\E\tr\left(\frac{\bQ}{\sqrt{\alpha}} \right)^k=\frac{1}{n \alpha^{k/2}}\sum_{i_1,\dots,i_k\in [n]} \E[\bQ_{i_1i_2}\bQ_{i_2i_3}\cdots \bQ_{i_{k-1}i_k} \bQ_{i_ki_1}], \label{eq:trace_c}
\end{align}
We classify closed walks into two  categories:
\begin{itemize}
    \item $\mathcal{C}_1$: Closed walks in which the resulting simple graph is a tree.
    \item $\mathcal{C}_2$: All other closed walks not included in $\mathcal{C}_1$.
\end{itemize}
Our goal is to demonstrate that when $n \to \infty$, walks belonging to $\mathcal{C}_1$ contribute to \eqref{eq:trace_c}, whereas those in $\mathcal{C}_2$ have vanishing contributions.


\subsection{Estimating $S_1$}
By our definition, $S_1 = 0$ when $k$ is odd, since closed walks on a tree must be of even length. Note that $\mathcal{C}_1$ here differs from the definition in Section~\ref{sec:proof_semicircle}; here we also consider walks that may traverse some edges more than twice. 



Now assume $k = 2m$. For each closed walk $I \in \mathcal{C}_1$, the graph $G_I = (V, E)$ is a tree, and we must have $|V| = |E| + 1 \leq m + 1$ and $|E| \leq m$. Using \eqref{eq:trace_c}, we can write:
\begin{align}
    S_1 = \frac{1}{n \alpha^{k/2}} \sum_{(i_1, i_2, \dots, i_{2m}) \in \mathcal{C}_1} 
    \mathbb{E} [\bQ_{i_1 i_2} \bQ_{i_2 i_3} \cdots \bQ_{i_{2m} i_1}].
\end{align}


Let $\mathcal{T}_{\ell}$ denote the set of all rooted planar trees with $\ell + 1$ vertices. Then
\begin{align}\label{eq:Catalan_chap3}
    |\mathcal{T}_\ell| = \frac{1}{\ell+1} \binom{2\ell}{\ell},
\end{align}
which is the $\ell$-th Catalan number. For each unlabeled rooted planar tree $T \in \mathcal{T}_{\ell}$, there are $n(n - 1) \cdots (n - \ell) = (1 + o(1)) n^{\ell + 1}$ ways to assign distinct vertex labels from $[n]$. Each such labeled tree corresponds to a closed walk $(i_1, \dots, i_k)$, where the vertex sequence follows a depth-first search traversal of $T$.
We apply a canonical labeling using $\{1, \dots, \ell + 1\}$ such that whenever the $k$-th distinct vertex $v$ is first visited in the depth-first search of $T$, it is assigned label $k \in [\ell + 1]$.

We can now rewrite $S_1$ as
\begin{align} \label{eq:S_1_Chap3}
    S_1 = \sum_{\ell=1}^{m} \frac{n(n - 1) \cdots (n - \ell)}{n \alpha^{k/2}} \sum_{T \in \mathcal{T}_\ell} \mathbb{E} \left[ \prod_{e \in E(T)} \bQ_{e}^{m(e)} \right]   
\end{align}
where $\bQ_e = \bQ_{ij}$ if $e = \{i, j\}$.
By Lemma~\ref{lemma:decomposition}, we have that for $m(e) \geq 2$, 
\begin{align}
    \mathbb{E} [\bQ_e^{m(e)}]= (1+o(1))p.
\end{align}

Therefore, for a tree $T$ with $\ell$ edges, for any fixed $\ell$, 
\begin{align}\label{eq:sparse_tree}
    \mathbb{E} \prod_{e \in E(T)} \bQ_e^{m(e)}  = [(1+o(1))p]^\ell = (1+o(1))p^\ell.
\end{align}

With \eqref{eq:sparse_tree} and \eqref{eq:Catalan_chap3}, we can rewrite \eqref{eq:S_1_Chap3} into
\begin{align} 
    S_1 &= \sum_{\ell=1}^{m} \frac{n^{\ell + 1}}{n \alpha^{k/2}} \cdot \frac{1}{\ell + 1} \binom{2\ell}{\ell} \cdot (1+o(1))p^\ell\\
    &=(1+o(1)) \cdot  \sum_{\ell=1}^{m} \frac{(np)^\ell}{\alpha^m} \cdot \frac{1}{\ell + 1} \binom{2\ell}{\ell} \\&=  \sum_{\ell=1}^{m} \frac{1}{\alpha^{m-\ell}} \cdot \frac{1}{\ell + 1} \binom{2\ell}{\ell} +o(1).
\end{align}
This matches the moments of the limiting spectral distribution of $\mathcal{G}(n, \frac{\alpha}{n})$, as shown in \eqref{eq:sparse_limit}.

\subsection{Bounding $S_2$}
We apply the graph decomposition algorithm in Section~\ref{sec:graph_decomposition} and replace $np$ with $\alpha$ to bound $S_2$.
\begin{align}
|S_2| &\leq  \frac{1}{n\alpha^{k/2}} \sum_{(i_1,i_2,\dots,i_k) \in \mathcal{C}_2} |\mathbb{E} [\bQ_{i_1,i_2} \bQ_{i_2,i_3} \cdots \bQ_{i_k,i_1}] |\\ &\leq  \sum_{G \in \mathcal{G}_2}  \frac{n^{v(G)}}{n\alpha^{k/2}} \left|\mathbb{E} \prod_{e \in E(G)}\bQ_{e}^{m(e)} \right|.
\end{align}
For each $G \in \mathcal{G}_2$, from \eqref{eq:G_bound2}, 
\begin{align}
     \frac{n^{v(G)}}{n\alpha^{k/2}} \Bigl|\mathbb{E} \prod_{e \in E(G)}\bQ_{e}^{m(e)} \Bigl| & \leq \alpha^{-k/2}2^{t(G)} (np)^{v(G)-1}(C\tau)^{c(G)-2g(G)}\left(C\sqrt{\log (1/p)}\right)^{g(G)-t(G)} \\&= \alpha^{v-1-k/2} 2^{t} \left(C' \sqrt{\frac{\log(1/p)}{d}}\right)^{c-2g}\left(C'\sqrt{\log(1/p)}\right)^{g-t} 
    \label{eq:S_2_each_G}
\end{align}
for some constant $C'>0$, where we use the upper bound on $\tau$ in Lemma \ref{lemma:tau}.
Since we have $c-2g \geq g-t$, when $d =\omega(\log^2(n))$, we obtain \eqref{eq:S_2_each_G} is $o(1)$ for any fixed $k$. Since $|\mathcal{G}_2|$ is finite when $k$ is fixed, we conclude $S_2=o(1)$.
Therefore 
\begin{align}
 \lim_{n\to\infty}   \frac{1}{n}\E\tr\left(\frac{\bQ}{\sqrt{\alpha}} \right)^k=\begin{cases}
    \sum_{l=1}^{m} \alpha^{l-m} \cdot \frac{1}{l + 1} \binom{2l}{l}      &  k=2m\\
      0  &   k=2m+1
    \end{cases}
\end{align}
Since $\frac{\bQ}{\sqrt \alpha}$ and $\frac{\bA}{\sqrt \alpha}$ have the same limiting spectral distribution due to \eqref{eq:rank_1},  this finishes the proof of Theorem~\ref{thm:constantp}.


\section{Proof of Theorem~\ref{thm:spectral_gap}}\label{sec:proof_spectra_gap}
In this section, we apply our graph decomposition method to bound the second eigenvalue of $\bA$. Recall from \eqref{eq:G_bound2}, for each fixed graph $G$ spanned by a closed walk of length $k$, we have
\begin{align}\label{eq:G_path}
  \left| \mathbb{E} \prod_{e \in E(G)}\bQ_{e}^{m(e)}\right|&\leq   2^{t(G)} p^{v(G)-1}(C\tau)^{c(G)-2g(G)}\left(C\sqrt{\log (1/p)}\right)^{g(G)-t(G)}
\end{align}
for some constant $C>0$, 
where 
\begin{itemize}
    \item $v(G)$ is the number of vertices in $G$;
    \item $t(G)$ is the number of length-2 ears in $G$;
        \item $g(G)=e(G)-v(G)+1$ is the excess number of $G$, which is also equal to the total number of ears in the ear decomposition of $G$;
    \item $c(G)$ is the number of total edges in all 2-edge connected components. 
\end{itemize}
Let $b(G)$ be the number of single edges in $G$. We will use the following counting lemma from \cite{liu2023local}.
\begin{lemma}[Claim 3.10 in \cite{liu2023local}]\label{lemma:counting}
    The number of closed walks in the trace expansion whose associated graph $G$ satisfies $e(G)=e, b(G)=b, g(G)=g$ is at most  \[n^{e+1-g} k^{2(k-b+g)}.\]
\end{lemma}

Now we are ready to prove Theorem~\ref{thm:spectral_gap}.
\begin{proof}[Proof of Theorem~\ref{thm:spectral_gap}]
Let $k$ be even. From \eqref{eq:G_path} and Lemma~\ref{lemma:counting}, we have 
\begin{align}
    \E\tr \bQ^k &\leq \sum_{c=0}^k\sum_{b=0}^c \sum_{g=0}^{\frac{c}{2}} \sum_{e=c}^{\frac{k+b}{2}}\sum_{t=0}^g n^{e+1-g}k^{2(k-b+g)} 2^t p^{e-g}(C\tau)^{c-2g}\left(C\sqrt{\log(1/p)}\right)^{g-t}\\
    &\leq k \sum_{c=0}^k\sum_{b=0}^c \sum_{g=0}^{\frac{c}{2}}\sum_{e=c}^{\frac{k+b}{2}} n^{e+1-g}k^{2(k-b+g)}  p^{e-g}(C\tau)^{c-2g}\left(C\sqrt{\log(1/p)}\right)^{g},
\end{align}
where we use the assumption $p\leq e^{-4}$ so that $\frac{2}{\sqrt{\log(1/p)}}\leq 1$.  Since $np\geq 1$,  summing over $e$, we obtain
\begin{align}
     \E\tr \bQ^k &\leq nk^2 \sum_{c=0}^k\sum_{b=0}^c \sum_{g=0}^{\frac{c}{2}} (np)^{\frac{k+b}{2}-g} k^{2(k-b+g)} (C\tau)^{c-2g}\left(C\sqrt{\log(1/p)}\right)^{g}\\
     &\leq nk^2\sum_{c=0}^k\sum_{b=0}^c \max \{ (C\tau)^c k^{2(k-b)}(np)^{\frac{k+b}{2}}, (np)^{\frac{k+b-c}{2}}k^{2(k-b)+c} (C\sqrt{\log (1/p)})^{c/2} \}.
\end{align}
Assuming $np\geq k^4$ and $k\geq \log n$, we further have 
\begin{align}
     \E\tr \bQ^k &\leq nk^3 \sum_{c=0}^k \max\left\{ (C\tau)^c k^{2(k-c)} (np)^{\frac{k+c}{2}}, (np)^{\frac{k}{2}} k^{2k-c} \left(C\sqrt{\log(1/p)}\right)^c \right\}\\
     &\leq  nk^4 \max \left\{ k^{2k} (np)^{\frac{k}{2}},  (C\tau np)^k,  (np)^{\frac{k}{2}} k^k (C\sqrt{\log(1/p)} )^k\right\}\\
     &=nk^4 \max \left\{ k^{2k} (C^2np)^{\frac{k}{2}},  (C\tau np)^k\right\}.
\end{align}

Take $k=4 \lfloor \gamma \log n \rfloor $ for any $\gamma\geq 1$.
Then by Markov's inequality, 
\begin{align}
    \mathbb P \left( \|\bQ\| \geq 3 \max \{ (4\gamma \log n)^{4} \sqrt{np} , C\tau np\}\right) \leq n k^4 3^{-k} \leq  n^{-\gamma}.
\end{align}
Therefore  when $p\geq C_0 \gamma^4 \log^4(n)$ and $p\leq e^{-4}$, with probability $1-n^{-\gamma}$,
\begin{align}
    \|\bQ\|\leq C_1\left( (\gamma \log n)^4 \sqrt{np} + \tau np \right)
    \end{align}
for an absolute constant $C_1$. 

Moreover,  by the Courant min-max theorem, 
\begin{align}
\lambda(\bA)&\leq \|\bA-p\mathbf{1}\mathbf{1}^\top \|\\
&\leq \|\bA-\E\bA \| + \|p\mathbf{1}\mathbf{1}^\top-\bA\|\\
&\leq \|\bA-\E\bA \| + p\\
&\leq C_1\left( (\gamma \log n)^4 \sqrt{np} + \tau np \right).
\end{align}
This finishes the proof.
\end{proof}

