\section{Additional proofs and auxiliary lemmas}\label{sec:appendix}
\subsection{Proof of Lemma~\ref{eq:ear}}
\begin{proof}[Proof of Lemma~\ref{eq:ear}]
The if and only if statement is due to  \cite{robbins1939theorem}.   
Algorithm~\ref{alg:DFS} describes the process of finding an ear decomposition based on the Depth-First Search (DFS), which guarantees $R_1$ is a cycle containing a given vertex in $G$.

\begin{algorithm}[H]
\caption{Ear Decomposition via DFS}
\begin{algorithmic}[1]
\REQUIRE A 2-edge-connected graph $G = (V, E)$
\ENSURE A sequence of ears $(R_1, R_2, \dots, R_s)$

\STATE Perform a DFS traversal on $G$ to classify each edge as a \textit{tree edge} or a \textit{back edge}.
\STATE Root the DFS tree and orient:
    \begin{itemize}
        \item All tree edges \textit{toward} the root
        \item All back edges \textit{away from} the root
    \end{itemize}
\FOR{each back edge}
    \STATE Traverse the unique directed cycle formed by the back edge and DFS tree edges
    \STATE Stop traversal when a previously visited vertex is reached
    \STATE Add the path to the ear sequence as a new ear $R_i$
\ENDFOR
\RETURN $(R_1, R_2, \dots, R_s)$
\end{algorithmic}\label{alg:DFS}
\end{algorithm}
\end{proof}





\subsection{Auxiliary lemmas} 

\begin{lemma}[Rank inequality, Theorem A.43 in \cite{bai2010spectral}]
    Let $ A_n, B_n $ be two $ n \times n $ Hermitian matrices. Let $ F^{A_n}, F^{B_n} $ be the cumulative distribution function of the empirical spectral distributions of $ A_n $ and $ B_n $. Then
\begin{align}\label{lemma:rank_inequality}
  \| F^{A_n} - F^{B_n} \| \leq \frac{\operatorname{rank}(A_n - B_n)}{n},
\end{align}
where $\|\cdot\| $ is the $L^\infty $-norm.
\end{lemma}

\begin{lemma}[Multiplicity reduction] \label{lemma:decomposition} For all integer $k\geq 1$, there exists $\alpha_k$ and $\beta_k$, s.t.
    \begin{align}
        (\bA_e-p)^k =(\bA_e-p)\alpha_k +\beta_k,
    \end{align}
where $\alpha_k\in [0,1], |\beta_k|\leq 2p(1-p)$.
\end{lemma}
\begin{proof} A simple calculation yields:
    \begin{align}
        (\bA_e-p)^k &=\bA_e((1-p)^k-(-p)^k)+(-p)^k\\
        &=(\bA_e-p)((1-p)^k-(-p)^k) +p(1-p)^k+(-p)^{k+1}+(-p)^k\\
        &=(\bA_e-p)\alpha_k +\beta_k,
    \end{align}
    where 
    \begin{align}
        \alpha_k=(1-p)^k-(-p)^k, \quad \beta_k= p(1-p)^k+(1-p)(-p)^k.
    \end{align}
    We can check $\alpha_k\in [0,1]$ and $|\beta_k|\leq 2p(1-p)$.
\end{proof}



\begin{lemma}[Two sided bounds on $\tau$, Lemma 2 in \cite{bubeck2016testing}]\label{lemma:tau}
There is a universal constant $C>0$ such that for any $p\in (0,1/2]$, 
    \begin{align}
         \left(C^{-1} \left(\frac{1}{2}-p\right)\sqrt{\frac{\log(1/p)}{d}}\right) \wedge \frac{1}{2}\leq \tau \leq C\sqrt{\frac{\log(1/p)}{d}}.
    \end{align}
\end{lemma}


\subsection{Subgraph probability estimates}\label{sec:subgraph}

We will use the following theorem from \cite{liu2023local} to estimate the probability of a certain subgraph appearing in the random geometric graph.
We relate subgraph probabilities to the mixing rate of a random walk on $\mathbb S^{d-1}$. Let $P_p$ denote the transition kernel of a random walk, where at each step, we walk from a point $x \in \mathbb S^{d-1}$ to a uniformly random point in the measure-$p$ cap around it. Let $\rho$ denote the uniform distribution on $\mathbb S^{d-1}$.


Our subgraph probability estimates will depend on the following result from \cite{liu2023local}:
\begin{lemma} \label{thm:tv_bound}
Assume $p\in (0,p_0]$ with any constant $p_0<1/2$. For any probability distribution $\mu$ over $\mathbb S^{d-1}$ and any integer $k\geq 1$, the total variation distance between $P_{p}^k\mu$ and $\rho$ satisfies
\begin{align}
     d_{TV}(P^{k}_{p}\mu, \rho)\leq \left((1+o_{d\tau^2}(1))\tau\right)^{k-1}  (1+o_{d\tau^2}(1)) \sqrt{ \log(1/p)},
\end{align}
where $o_{d\tau^2}(1)$ denotes a function that goes to $0$ as $d\tau^2\to \infty$. In particular, there is a constant $C>0$ depending on $p_0$ such that 
\begin{align}\label{eq:non-asym_tv}
     d_{TV}(P^{k}_{p}\mu, \rho)\leq C^k \tau^{k-1} \sqrt{ \log(1/p)}.
\end{align}
\end{lemma}
\begin{proof}
    The first claim follows from \cite[Corollary 4.7]{liu2023local} based on \cite[Theorem 4.19]{liu2023local}. For the second statement, note that $d\tau^2\geq C_0$ for a constant depending only on $p_0$ due to the lower bound on $\tau$ in Lemma~\ref{lemma:tau}, we can find a constant $C$ depending on $p_0$ such that \eqref{eq:non-asym_tv} holds.
\end{proof}



With Lemma~\ref{thm:tv_bound}, we can obtain the following useful lemma on subgraph probabilities. These bounds have been derived in \cite{liu2023local} and are included here for completeness.
\begin{lemma}[Subgraph probability] Assume $p\in (0,p_0]$ with any constant $p_0<1/2$.
Let $C_{\ell}$ be a cycle of length $\ell$ with vertices $v_0,...v_{\ell-1}$. Then  there is a constant $C>0$ depending only on  $p_0$ such that 
    \begin{align}
    |\E \prod_{e\in C_{\ell}} \bA_e-p^{\ell}|\leq C p^{\ell-1}(C\tau )^{\ell-2}\sqrt{\log(1/p)}. \label{eq:cycle_probability} 
    \end{align}
    Similarly, let $P_{\ell}$ be a path of length $\ell\geq 2$ with distinct vertices $v_0,\dots, v_{\ell}$. Then 
\begin{align}
  \left|\E_{v_1,\dots, v_{\ell-1}} \prod_{e\in P_{\ell}} \bA_e-p^{\ell}\right|\leq Cp^{\ell-1}(C\tau )^{\ell-2}\sqrt{\log(1/p)},   \label{eq:path_probability}
\end{align}
where the expectation is conditioned on the random vectors corresponding to $v_0, v_{\ell}$ and is taken over random vectors corresponding to $v_1,\dots, v_{\ell-1}$.
\end{lemma}
\begin{proof}
We first consider the cycle probability.  Let $\bv_0,\dots, \bv_{\ell-1}$ be the random vectors associated with $v_0,\dots, v_{\ell-1}$. Then
     \begin{align}
    |\E \prod_{e\in C_{\ell}} \bA_e-p^{\ell}| &= | \mathbb{P}(C_{\ell} \in G) - p^{\ell}| \\ 
    &= \left| p^{\ell-1} \mathbb P\left( \langle \bv_{\ell-1},\bv_0\rangle \geq \tau |\langle \bv_i,\bv_{i+1}\rangle \geq \tau, 0\leq i\leq \ell-2\right)-p^{\ell}\right|\\ 
    &\leq p^{\ell-1} \Bigl(p+d_{TV} \bigl(P_p^{\ell-1} \delta_{\bv_0}, \rho\bigl)\Bigl) -p^{\ell} \\&=p^{\ell-1} d_{TV} \bigl(P_p^{\ell-1} \delta_{\bv_0}, \rho\bigl).
\end{align}


Applying \eqref{eq:non-asym_tv}, we get 
\begin{align}
    |\E \prod_{e\in C_{\ell}} \bA_e-p^{\ell}|\leq Cp^{\ell-1}(C\tau )^{\ell-2}\sqrt{\log(1/p)}.
    \end{align}


    Similarly, 
    \begin{align}
        \left|\E_{v_1,\dots, v_{\ell-1}} \prod_{e\in P_{\ell}} \bA_e-p^{\ell}\right|&=\left| \mathbb P(\langle \bv_{\ell},\bv_{\ell-1}\geq \tau, \cdots ,\langle \bv_{1}, \bv_0\rangle \geq \tau ) -p^{\ell}\right|\\
        &=\left| p^{\ell-1} \mathbb P(\langle \bv_{\ell},\bv_{\ell-1}\geq \tau |  \langle \bv_{i}, \bv_{i+1}\rangle \geq \tau , 0\leq i\leq \ell-2)  -p^{\ell}\right|\\
         &\leq p^{\ell-1} \Bigl(p+d_{TV} \bigl(P_p^{\ell-1} \delta_{\bv_0}, \rho\bigl)\Bigl) -p^{\ell} \\&=p^{\ell-1} d_{TV} \bigl(P_p^{\ell-1} \delta_{\bv_0}, \rho\bigl) .
    \end{align}
    Applying \eqref{eq:non-asym_tv} again finishes the proof.
\end{proof}






