\section{Introduction}

Let $\PC$ be a polyhedron defined by the system $A x \leq b$, where $A \in \RR^{m \times n}$ and $b \in \RR^m$. \GribanovAdd{Throughout our work, we consider only \emph{full-dimensional} and \emph{pointed polyhedra}, meaning $\dim(\PC) = n$ and $\PC$ contains no lines. The latter condition is equivalent to $\rank(A) = n$.}
Additionally, we assume all inequalities in the system $A x \leq b$ are facet-defining, meaning the system contains no redundant inequalities. \GribanovAdd{In these assumptions, $(n,m)$ denotes the dimension and number of facets in $\PC$ respectively.}

The seminal Upper Bound Theorem by McMullen \cite{MaxFacesTh} states that the vertex count reaches its maximum for the class of polytopes dual to cyclic polytopes. Combining this with the formula from \cite[Section~4.7]{Grunbaum} for the facet count of cyclic polytopes yields:
% \begin{equation*}
%     \abs{\vertex(\PC)} \leq \xi(n,m) = \begin{cases}
%         \frac{m}{m-s} \binom{m-s}{s}, & \text{for } n = 2s,\\
%         2\binom{m-s-1}{s}, & \text{for } n = 2s+1,
%     \end{cases} 
%     = O\left(\frac{m}{n}\right)^{n/2}.
% \end{equation*}
\GribanovAdd{
\begin{equation}\label{eq:McMullenUB}
    \abs{\vertex(\PC)} = O\left(\frac{m}{n}\right)^{n/2}.
\end{equation}
}

\GribanovAdd{But, in many scenarios and especially in the context of ILP, the resulting polyhedra are very far from cyclic. In many cases, it is useful to look at the parameterization by $\Delta/\Delta_{\average}$ or $\Delta/\Delta_{\min}$, where the parameters $\Delta$, $\Delta_{\min}$ and $\Delta_{\average}$ are defined by the following way:
% In this work, we shift from parameterization by $m$ to parameterization by $\Delta/\Delta_{\average}$ or $\Delta/\Delta_{\min}$, where
\begin{gather*}
    \Delta(A) = \max\left\{ \abs{\det A_{\BC}} \colon \BC \in \binom{\intint m}{n} \right\}, \\
    \Delta_{\average}(\PC,A) = \max \left\{ \frac{1}{\abs{\TS}} \cdot \sum_{\BC \in \TS} \abs{\det A_{\BC}} \colon \text{$\TS$ -- is a triangulation of the $\PC$'s normal fan} \right\}, \\
    \Delta_{\min}(\PC,A) = \max\left\{ \min\limits_{\BC \in \TS} \abs{\det A_{\BC}} \colon \text{$\TS$ -- is a triangulation of the $\PC$'s normal fan} \right\}.
\end{gather*}
Here we identify the simplicial cones which form a triangulation $\TS$ with the corresponding feasible bases of the system $A x \leq b$ (see Section \nameref{sec:prelim} for the formal definitions of the normal fan of $\PC$ and its triangulation).

\begin{remark}\label{rm:delta_avg_def}
    Assuming that $\PC$ is simple, the normal fan of $\PC$ is simplicial and coincides with the set of feasible bases of the system $A x \leq b$ denoted by $\BS$. In this case, the definitions of $\Delta_{\min}$ and $\Delta_{\average}$ can be simplified by the following way:
    \begin{gather*}
        \Delta_{\average}(\PC,A) = \frac{1}{\abs{\BS}} \sum_{\BC \in \BS} \abs{\det A_{\BC}},\\
        \Delta_{\min}(\PC,A) = \min\limits_{\BC \in \BS} \abs{\det A_{\BC}}.
    \end{gather*}
\end{remark}
}

\GribanovAdd{
As our first contribution, we establish the following bound for the vertex count of $\PC$ (the proof is given in \Vref{proof:th:vertexUB}).
\begin{restatable}{theorem}{vertexUB}
\label{th:vertexUB}
    Let $\PC \subseteq \RR^n$ be a pointed $n$-dimensional polyhedron defined by a system $A x \leq b$. Denote $\Delta = \Delta(A)$ and $\Delta_{\average} = \Delta_{\average}(\PC,A)$, then  
    \begin{multline*}
        \abs{\vertex(\PC)} \leq n! \cdot \frac{\Delta}{\Delta_{\average}} \cdot \vol(\BB_2^n) \sim \\
        \sim \frac{1}{\sqrt{\pi n}} \cdot \left(\frac{2 \pi}{e}\right)^{n/2} \cdot n^{n/2} \cdot \frac{\Delta}{\Delta_{\average}} = O(n)^{n/2} \cdot \frac{\Delta}{\Delta_{\average}}.
    \end{multline*}
\end{restatable}
Here $\BB_2^n$ denotes the standard Euclidean ball.
This inequality is tight in the following sense (the proof is given in \Vref{proof:th:vertexUB}). 
\begin{restatable}{proposition}{vertexLB}
\label{prop:vertexLB}
    There exists a sequence of pointed $n$-dimensional polytopes $\PC_k \subseteq \RR^n$ defined by systems $A_k x \leq b_k$ such that:
    \begin{gather*}
        \lim\limits_{k \to \infty} \left(\vertex(\PC_k) - n! \cdot \frac{\Delta_k}{\Delta_{\average,k}} \cdot \vol \BB_2^n \right) = 0, \quad\text{and}\\
        \lim\limits_{k \to \infty} \frac{\Delta_k}{\Delta_{\average,k}} = \infty,
    \end{gather*}
    where $\Delta_k = \Delta(A_k)$ and $\Delta_{\average,k} = \Delta_{\average}(\PC_k,A_k)$. 
\end{restatable}
In fact, motivated by ILP applications described in \Cref{sec:algo_implications}, we establish a more general result concerning the count of $n$-dimensional faces in polyhedral fans (see \Cref{cor:vol_Delta_fan} and \Cref{prop:tightness_fans}). The result follows by utilizing properties of "totally unimodular" convex bodies described in \Cref{prop:totally_unimodular_set}, followed by an application of a symmetric version of Macbeath's theorem \cite{Macbeath}. In original form, Macbeath's theorem states that the Euclidean ball is the hardest to approximate by polytopes. The symmetric version formulated and proved as \Cref{th:Macbeath} states that the Euclidean ball is the hardest to approximate even by centrally symmetric polytopes.
}

\GribanovAdd{
We can compare \Cref{th:vertexUB} with the McMullen upper bound \eqref{eq:McMullenUB} by the following way. Assuming that $A$ is an integer matrix, it is known that $m$ can be bounded by a function depending on $n$ and $\Delta$. For instance:
\begin{itemize}
    \item $m = O(n^2 \cdot \Delta^2)$ (Lee~et~al.~\cite{ModularDiffColumns})
    \item $m = O(n^4 \cdot \Delta)$ (Averkov \& Schymura~\cite{DiffColumnsOther})
    \item $m = O(n^2 + n \cdot \Delta^7)$ (Paat~et~al.~\cite{DifferingSeparated})
\end{itemize}
Furthermore, \cite{ModularDiffColumns} provides examples of polyhedra with $m = \Theta(n^2 + n \cdot \Delta)$. Substitution of one of these expressions into McMullen's upper bound \eqref{eq:McMullenUB} provides upper bounds for $\abs{\vertex(\PC)}$ depending only on $n$ and $\Delta$. However, even in the case $m = \Theta(n^2 + n \cdot \Delta)$, \Cref{th:vertexUB} works better.
}

\GribanovAdd{
Another problem related to the use of parameter $\Delta$ and employing similar analysis methods is the problem of estimating the diameter of a polyhedral graph $\GC(\PC)$. Recall that graph $\GC(\PC)$ is the $1$-skeleton of polyhedron $P$, i.e., the graph formed by its vertices and edges. With respect to our result about the number of vertices, the results concerning the diameter of $\GC(\PC)$ use the same properties of "totally unimodular" convex bodies described in \Cref{prop:totally_unimodular_set} and the same construction for building the lower bound.

As the main in this direction, we present the following theorem, which is built on results from \cite{SubdeterminantsDiameter,ShadowSimplexForCurved} (the proof is given in \Vref{sec:diam_UB}).
\begin{restatable}{theorem}{diamUB}
\label{th:diamUB}
    Let $\PC \subseteq \RR^n$ be a pointed $n$-dimensional polyhedron defined by a system $A x \leq b$. Denote $\Delta = \Delta(A)$ and $\Delta_{\min} = \Delta_{\min}(\PC,A)$, then
    \begin{equation*}
        \diam\bigl(\GC(\PC)\bigr) = O\left(n^3 \cdot \frac{\Delta}{\Delta_{\min}} \cdot \ln \bigl(n \frac{\Delta}{\Delta_{\min}}\bigr) \right).
    \end{equation*}
\end{restatable}
While the dependence on $\frac{\Delta}{\Delta_{\min}}$ is provably optimal for $2$-dimensional polyhedra, for general $n$ we only construct examples with sublinear dependence on $\frac{\Delta}{\Delta_{\min}}$ (the proof is given in \Vref{proof:prop:diamLB}).
\begin{restatable}{proposition}{diamLB}
\label{prop:diamLB}
    There exists a sequence of pointed $n$-dimensional polytopes $\PC_k \subseteq \RR^n$ defined by systems $A_k x \leq b_k$ such that:
    \begin{equation*}
        \diam\bigl(\GC(\PC_k)\bigr) = 2^{k+1} - 1 = 2 \left(\frac{\Delta_k}{\Delta_{\min,k}}\right)^{1/\log_2 n} - 1,
    \end{equation*}
    where $\Delta_k = \Delta(A_k)$ and $\Delta_{\min,k} = \Delta_{\min}(\PC_k,A_k)$.
\end{restatable}
} 
Unfortunately, compared to the upper bound $O\left(n^3 \cdot \Delta^2 \cdot \ln (n \Delta) \right)$ for integer matrices\footnote{\GribanovAdd{In precise form, the upper bound by \cite{ShadowSimplexForCurved} is $O\left(n^3 \cdot \Delta_{n-1} \cdot \Delta_1 \cdot \ln (n \Delta_{n-1} \Delta_1) \right)$, where $\Delta_k$ (for $k \in \intint n$) denotes the maximum absolute value of $k \times k$ subdeterminants of $A$. In our work we replace $\Delta_{n-1} \cdot \Delta_1$ by $\Delta_n$.}} by Dadush \& H\"ahnle \cite{ShadowSimplexForCurved}, our upper bound is non-constructive\footnote{When discussing diameter computation, we additionally assume $A$ and $b$ are rational.}, as it requires knowledge of a submatrix $B \in \RR^{n \times n}$ of $A$ with $\abs{\det B}$ close to $\Delta$ - a computationally difficult task (see, e.g., Nikolov \cite{LargestSimplex_Nikolov}). We give a small survey about the diameter problem in \Cref{sec:related_work}.

\subsection{Algorithmic Implications}\label{sec:algo_implications}

\GribanovAdd{
One of our motivations comes from the problem of efficient counting of integer points inside polyhedra. Many known algorithms for this problem are based on the construction of a normal fan triangulation corresponding to $\PC$. In our work we provide a variant of such an algorithm, whose computational complexity is linear with respect to size of an output triangulation. On this way, our upper bound on size of polyhedral fans (see \Cref{cor:vol_Delta_fan}) yields the following result that can be interesting in its own. 
\begin{restatable}{theorem}{vertexEnumeration}
\label{th:vertex_enumeration}
    Let $\PC$ be a pointed polyhedron defined by the system $A x \leq b$, where $A \in \QQ^{m \times n}$ and $b \in \QQ^m$. Then, there exists an algorithm that enumerates the vertices of $\PC$ in
    \begin{equation*}
        O(n)^{n/2} \cdot m^2 \cdot \frac{\Delta}{\Delta_{\average}} + T_{\text{LP}} \quad\text{operations},
    \end{equation*}
    where $T_{\text{LP}}$ denotes the number of operations required to compute a rational feasible solution of $A x \leq b$. If $\PC$ is simple, the complexity bound improves to
    \begin{equation*}
        O(n)^{n/2} \cdot m \cdot \frac{\Delta}{\Delta_{\average}} + T_{\text{LP}} \quad\text{operations}.
    \end{equation*}
\end{restatable}
Assuming that $A$ is integer, we can replace $\frac{\Delta}{\Delta_{\average}}$ with $\Delta$, which consequently allows to eliminate the $T_{\text{LP}}$ term.
}
It follows from the complexity bound that
\begin{equation*}
    T_{\text{LP}} = n^{O(1)} \cdot m \cdot \log\left(1 + \Delta\right),
\end{equation*}
established by Dadush, Natura \& V\'egh \cite{TardosRevisiting_Dadush}. 

\GribanovAdd{
Our main algorithmic result, which also serves as one of the primary motivations for this paper, is the following.
\begin{restatable}{theorem}{integerCounting}
\label{th:integer_counting}
    Let $\PC$ be a pointed polyhedron defined by the system $A x \leq b$, where $A \in \ZZ^{m \times n}$ and $b \in \QQ^m$. Then, there exists an algorithm that computes $\abs{\PC \cap \ZZ^n}$ in
    \begin{equation*}
        O(n)^n \cdot \frac{\Delta^4}{\Delta_{\average}} \quad \text{operations.}
    \end{equation*}
\end{restatable}
When compared to Barvinok's algorithm \cite{BarvPom,BarvBook}, whose complexity bound can be estimated in
}
\begin{equation*}
    O(m/n)^{n/2} \cdot \bigl(\ln \Delta\bigr)^{n \ln n} \quad \text{operations},
\end{equation*}
our bound demonstrates superiority in scenarios where:
\begin{itemize}
    \item \GribanovAdd{$\Delta = n^{O(n \ln^{1 - \varepsilon} n)}$ for $\varepsilon > 0$ and $m \geq n$, or}
    \item $m = \Omega(n \Delta)$ with $\Delta \geq n^{2 + \varepsilon}$.
\end{itemize}

\subsection{Complexity Model Assumptions}\label{sec:assumptions}
All algorithms in this work adhere to the \emph{Word-RAM} computational model. Specifically, we assume that basic arithmetic operations (addition, subtraction, multiplication, and division) on rational numbers of bounded size can be performed in constant $O(1)$ time, where the bound is given by the \emph{word size}.

For polyhedra defined by systems $A x \leq b$ with $A \in \QQ^{m \times n}$ and $b \in \QQ^m$, we set the word size to be a fixed polynomial in 
\[
\lceil \log_2(1+n) \rceil + \lceil \log_2(1+ m) \rceil + \lceil \log_2( 1 + \alpha) \rceil,
\]
where $\alpha$ denotes the maximum absolute value of numerators and denominators in the rational representations of entries of $A$ and $b$.

