%     \begin{equation*}
%         \KC = \conv\bigl(\extreme(\KC)\bigr).
%     \end{equation*}
% \end{theorem}

\begin{remark}\label{rm:Delta_extreme_rm}
    Since the determinant is multilinear in its columns and by Minkowski's theorem,
    % ~\ref{th:KreinMilman}, 
    for any convex body $\KC \subseteq \RR^n$, the value $\Delta(\KC)$ is attained at extreme points:
    \begin{equation*}
        \Delta(\KC) = \Delta\bigl(\extreme(\KC)\bigr).
    \end{equation*}
\end{remark}

% We recall the definition of a \emph{polyhedral fan} and introduce its weaker version, termed a \emph{polyhedral cone packing}:
\GribanovAdd{
\begin{definition}\label{def:cone_packing}
    A family $\FS$ of polyhedral cones in $\RR^n$ 
    is said to form a \emph{packing} if, for every pair $\FC_1, \FC_2 \in \FS$,
    \[
    \dim(\FC_1 \cap \FC_2) < n.
    \]

    % A family $\FS$ of polyhedral cones in $\RR^n$ constitutes a \emph{$d$-dimensional polyhedral cone packing} ($d \leq n$) if:
    % \begin{enumerate}
    %     \item Each $\FC \in \FS$ is a $d$-dimensional polyhedral cone in $\RR^n$;
    %     \item For any distinct $\FC_1, \FC_2 \in \FS$, $\dim\bigl(\FC_1 \cap \FC_2\bigr) < d$.
    % \end{enumerate}
    % The packing $\FS$ is \emph{simplicial} if every $\FC \in \FS$ is the conic hull of exactly $d$ linearly independent vectors.
\end{definition}
}

\begin{definition}\label{def:fan}
    A family $\FS$ of polyhedral cones in $\RR^n$ is called a \emph{polyhedral fan} if:
    \begin{enumerate}
        \item Every face of any $\FC \in \FS$ also belongs to $\FS$;
        \item For any $\FC_1,\FC_2 \in \FS$, their intersection $\FC_1 \cap \FC_2$ is a common face of both cones;
        \item \GribanovAdd{The family $\FS$ has no inclusion-maximal elements of dimension less than $n$.}
    \end{enumerate}
    The $k$-dimensional faces and $f$-vector of $\FS$ are defined respectively by
    \begin{gather*}
        \Gamma_k(\FS) = \left\{ \FC \in \FS \colon \dim(\FC) = k \right\}, \\
        f_k(\FS) = \abs{\Gamma_k(\FS)}.
    \end{gather*}
    \GribanovAdd{Observe that $\Gamma_n(\FS)$ forms a packing. The fan $\FS$ is called simplicial if each element of $\Gamma_n(\FS)$ is a simplex.}
\end{definition}

In our work, we establish connections between polyhedral fan properties and matrix properties, \GribanovAdd{where matrix columns represent rays of a polyhedral fan}. This motivates our definitions of matrix-based polyhedral fans and cone packings:
\begin{definition}\label{def:matrix_based}
    \GribanovAdd{Let $\FS$ be a polyhedral fan or a packing of polyhedral cones.} We say that $\FS$ is \emph{based on the columns of a matrix $A \in \RR^{n \times m}$} if each $\FC \in \FS$ is the conic hull of some column subset of $A$. 
    % We identify each $\FC$ with the subset of indices in $\intint m$.  equivalently expressed as:
    \GribanovAdd{
    Abusing notation we also write $\FC$ for the corresponding subset of column indices $\FC \subseteq \intint m$. This way, we have
    }
    \begin{equation*}
        \FC = \cone(A_{* \FC}).
    \end{equation*}

    The \emph{underlying non-convex polytope\footnote{We define a non-convex polytope as a finite union of convex polytopes.} of $\FS$} is defined as:
    \begin{equation*}
        \norm{\FS}_A = \bigcup_{\FC \in \FS} \conv(\BZero, A_{* \FC}).
    \end{equation*}
    \GribanovAdd{
    For a packing $\FS$ of $n$-dimensional simplicial polyhedral cones, we define:
    }
    \begin{gather*}
        \Delta_{\min}(\FS,A) = \min_{\FC \in \FS} \abs{\det A_{* \FC}}, \\
        \Delta_{\average}(\FS,A) = \frac{1}{\abs{\FS}} \sum_{\FC \in \FS} \abs{\det A_{* \FC}}.
    \end{gather*}
    For simplicial fans $\FS$, these extend naturally via $\Gamma_d(\FS)$:
    \begin{gather*}
        \Delta_{\min}(\FS,A) = \Delta_{\min}\bigl(\Gamma_d(\FS),A\bigr), \\
        \Delta_{\average}(\FS,A) = \Delta_{\average}\bigl(\Gamma_d(\FS),A\bigr).
    \end{gather*}
\end{definition}

Finally, recall the definitions of the \emph{normal fan of a polyhedron}, the \emph{triangulation of a polyhedral fan} and the \emph{graph of a polyhedral fan}:
\begin{definition}\label{def:normal_fan}
    For a polyhedron $\PC \subseteq \RR^n$ defined by $A x \leq b$ ($A \in \RR^{m \times n}$, $b \in \RR^m$), the \emph{normal cone} at vertex $v \in \vertex(\PC)$ is:
    \[
    \FC_v = \cone\left((A_{i *})^\top \colon A_{i *} v = b_i\right).
    \]
    \GribanovAdd{
    Again we abuse our notation and write $\FC_v$ for the corresponding subset of row indices $\FC_v \subseteq \intint m$. This way, we have
    \[
        \FC_v = \conv\bigl((A_{\FC_v *})^\top\bigr).
    \]
    }

    The \emph{normal fan} $\NS(\PC)$ consists of all such $\FC_v$ and their faces. By \Cref{def:matrix_based}, $\NS(\PC)$ is based on columns of $A^\top$.
\end{definition}

\GribanovAdd{
\begin{definition}
    Let $\FS$ be a polyhedral fan in $\RR^n$. We say that a polyhedral fan $\TS$ forms a \emph{triangulation of $\FS$} if $\TS$ is induced by a partition of each $\FC \in \Gamma_n(\FS)$ into simplicial cones. 
\end{definition}
}

\begin{definition}\label{def:graph_of_fan}
    For a polyhedral fan $\FS$ in $\RR^n$, its \emph{graph} $\GC(\FS)$ is a simple graph with:
    \begin{itemize}
        \item Vertex set $\Gamma_n(\FS)$,
        \item Edge set $\left\{\{\FC_1,\FC_2\} \colon \dim(\FC_1 \cap \FC_2) = n - 1\right\}$.
    \end{itemize}
\end{definition}

\section{New Upper Bound for the Number of Vertices}\label{sec:vertex_UB}

\subsection{Relation Between the Volume of a Convex Body $\KC$ and $\Delta(\KC)$}

\GribanovAdd{
We are motivated by the following proposition, which is a version of the well known relation between $\Delta$-modularity and total $\Delta$-modularity of matrices.
}
\begin{proposition}\label{prop:totally_unimodular_set}
    Let $\KC \subseteq \RR^n$ be compact, and let $V = (v_1 \dots v_n) \in \RR^{n \times n}$ consist of vectors $v_1, \dots, v_n \in \KC$ satisfying $\Delta(\KC) = \abs{\det V}$. Then the transformed set $\UC = V^{-1} \KC$ is \emph{totally unimodular} in the following sense: for any $k \geq 1$ and any matrix $U = (u_1 \dots u_k)$ with columns $u_1, \dots, u_k \in \UC$, we have $\Delta(U) \leq 1$. In particular:
    \begin{gather*}
        \UC \subseteq \BB_{\infty}^n, \quad \text{and consequently} \quad \vol \KC \leq 2^n \cdot \Delta(\KC).
    \end{gather*}
\end{proposition}
% \begin{proof}
%     Since $\KC$ contains the points $\{v_1, \dots, v_n\}$, the set $\UC$ contains the points $\{e_1, \dots, e_n\}$. Let $B$ be some $k \times k$ submatrix of $U$. Appending s

%     We need to show that, for any $k \geq 1$ and any matrix $U = (u_1 \dots u_k)$ with columns $u_1, \dots, u_k \in \UC$, we have $\Delta(U) \leq 1$. Assume first that $U$ is an $n \times n$ matrix. Then, $\Delta(U) = \abs{\det U} \leq \Delta(\KC) / \abs{\det V} \leq 1$. Assume now that $U$ is an $k \times n$ matrix for $k < n$. 
% \end{proof}

The volume inequality for $\vol \KC$ is non-tight, and a sharper bound follows from the symmetric version of Macbeath's theorem. \GribanovAdd{Recall that the set $\KC$ is called \emph{$o$-symmetric} ($o \in \RR^n$), if for each $x \in \KC$ we have $2o - x \in \KC$.}
Let $\PS_m$ denote the class of convex polytopes with at most $m$ vertices.
For a convex body $\KC \subseteq \RR^n$, we define:
\begin{gather*}
    \eta_m(\KC) = \sup\left\{\frac{\vol \PC}{\vol \KC} \colon \PC \subset \KC,\, \PC \in \PS_m\right\}, \\
    \psi_m(\KC) = \sup\left\{\frac{\vol \PC}{\vol \KC} \colon \PC \subset \KC,\, \PC \in \PS_m,\, \text{$\PC$ -- is $o$-symmetric} \right\}.
\end{gather*}

\begin{theorem}[Macbeath \cite{Macbeath}]
    For any convex body $\KC \subseteq \RR^n$ and integer $m \geq 0$,
    % and integer $m \geq n+1$\footnote{\GribanovAdd{In fact, the inequality $m \geq n + 1$ is redundant, because $\eta_k(\KC) = 0$ for any convex body $\KC \in \RR^n$ and $k \leq n$. However, the theorem is not interesting in these cases.}},
    \begin{equation*}
        \eta_m(\KC) \geq \eta_m(\BB^n_2).
    \end{equation*}
\end{theorem}
We require the following symmetric version for our analysis, which we will prove below.
\begin{theorem}[A symmetric version of Macbeath’s theorem]\label{th:Macbeath}
    For any $o$-symmetric convex body $\KC \subseteq \RR^n$ and integer $m \geq 0$,
    \begin{equation*}
        \psi_m(\KC) \geq \psi_m(\BB^n_2).
    \end{equation*}
\end{theorem}
To prove \Cref{th:Macbeath}, we follow the original proof of Macbeath in \cite{Macbeath}, and use the following concept. Let $\HC$ be a hyperplane through the origin $o$ and let $\KC$ be an $o$-symmetric convex body, i.e. a compact, convex set with nonempty interior. Any point in $\RR^n$ can be uniquely determined by its signed distance $t$ from $\HC$ and its orthogonal projection $x$ onto $\HC$; in this case we denote the point by $(x,t)$. Let $\proj(\KC)$ denote the orthogonal projection of $\KC$ onto $\HC$, and for any $x \in \proj(\KC)$, define $\KC^+(x) = \max \left\{ t\colon (x,t) \in \KC \right\}$ and $\KC^-(x) = \min \left\{ t\colon (x,t) \in \KC \right\}$. Since $\KC$ is convex, we have that $\KC^- : \proj(\KC) \to \RR$ is a convex function and $\KC^+ : \proj(\KC) \to \RR$ is a concave function.
Define the set
\begin{equation*}
    \SC_{\HC}(\KC) = \left\{ (x,t) \colon x \in \proj(\KC),\, \abs{t} \leq \frac{1}{2} \bigl(\KC^+(x) - \KC^-(x)\bigr) \right\}.
\end{equation*}
This set, which is known to be a convex body \cite[Section 10]{BookSchneider}, is called the \emph{Steiner symmetral} of $\KC$.
Clearly, as $\KC$ is $o$-symmetric, so is $\SC_{\HC}(\KC)$. Our main lemma is the following.
\begin{lemma}\label{lm:Macbeath}
For any $o$-symmetric convex body $\KC$, $m \geq 0$, and hyperplane $\HC$ through $o$, we have
\[
\psi_m(\KC) \geq \psi_m\bigl(\SC_{\HC}(\KC)\bigr).
\]
\end{lemma}

\begin{proof}
% \GribanovAdd{Since $\psi_m(\KC) = 0$ for any $o$-symmetric convex body $\KC \in \RR^n$ and $m < 2 n$, we assume that $m \geq 2n$.} 
Let $\PC \in \PS_m$ be an $o$-symmetric convex polytope inside $\SC_{\HC}(\KC)$ of the largest volume; by compactness, such a polytope exists. Then every vertex $(x_i,t_i)$ of $\PC$, where $i \in \intint m$, lies in the boundary of $\SC_{\HC}(\KC)$, and hence, $t_i = \abs{\KC^+(x_i) - \KC^-(x_i)}/2$. Since $\SC_{\HC}(\KC)$ is symmetric to the hyperplane $\HC$, the convex hull of the points $(x_i,-t_i)$, which is the reflection of $\PC$ w.r.t. $\HC$, is also a largest volume $o$-symmetric convex polytope in $\SC_{\HC}(\KC)$. Now, let $\QC$ be the convex hull of the points 
\begin{equation*}
q_i =\left( x_i, t_i + \frac{1}{2} \bigl(\KC^+(x_i)+\KC^-(x_i)\bigr) \right),    
\end{equation*}
and $\RC$ be the convex hull of the points  
\begin{equation*}
    r_i =\left( x_i, - t_i + \frac{1}{2} \bigl(\KC^+(x_i)+\KC^-(x_i)\bigr) \right),
\end{equation*}
respectively, where $i \in \intint m$.
Observe that both $\{q_i\}$ and $\{r_i\}$ belong to $\KC$, and thus, both $\QC,\RC \in \PS_m$ are $o$-symmetric convex polytopes inside $\KC$.

The boundary of $\QC$ can be written as the union of the graphs of two functions $\QC^+ : \proj(\PC) \to \RR$ and $\QC^- : \proj(\PC) \to \RR$, where $\QC^-(x) \leq \QC^+(x)$ for all $x \in \proj(\PC)$, $\QC^-$ is convex and $\QC^+$ is concave. Similarly, the boundary of $\RC$ can be written as the union of the graphs of two functions $\RC^+ : \proj(\PC) \to \RR$ and $\RC^- : \proj(\PC) \to \RR$, where $\RC^-(x) \leq \RC^+(x)$ for all $x \in \proj(\PC)$, $\RC^-$ is convex and $\RC^+$ is concave. On the other hand, by their definitions, we have
\begin{gather*}
    \QC^+(x_i) \geq t_i + \frac{1}{2} \bigl(\KC^+(x_i)+\KC^-(x_i)\bigr) \geq \QC^-(x_i), \quad\text{and}\\
    \RC^+(x_i) \geq -t_i + \frac{1}{2} \bigr(\KC^+(x_i)+\KC^-(x_i)\bigr) \geq \RC^-(x_i).
\end{gather*} 
From this, we obtain that for $i \in \intint m$, 
\begin{equation}\label{eq:QRt_inequality}
    \frac{1}{2} \left( \QC^-(x_i) - \RC^+(x_i) \right) \leq t_i \leq \frac{1}{2} \left( \QC^+(x_i) - \RC^-(x_i) \right).
\end{equation}
Note that, since the function $\QC^- - \RC^+$ is convex and the function $\QC^+ - \RC^-$ is concave, the region $\TC$ defined as
\begin{equation*}
    \TC = \left\{ (x,t) \in \RR^n \colon x \in \proj(\PC),\, \frac{1}{2} \bigl( \QC^-(x) - \RC^+(x) \bigr) \leq t \leq \frac{1}{2} \bigl( \QC^+(x) - \RC^-(x) \bigr) \right\}
\end{equation*}
is convex. By \eqref{eq:QRt_inequality}, the polytope $\PC$ belongs to the region $\TC$. From this, Fubini's theorem yields that
\begin{multline*}
    \vol(\PC) \leq \vol(\TC) = \int_{\PC'} \frac{1}{2} \left( \QC^+(x) - \RC^-(x) \right) - \frac{1}{2} \left( \QC^-(x) - \RC^+(x) \right) \, dx = \\
    = \frac{1}{2} \int_{\PC'} \QC^+(x) - \QC^-(x) \, dx + \frac{1}{2} \int_{\PC'} \RC^+(x) - \RC^-(x) \, dx =\\ 
    = \frac{1}{2} \left( \vol(\QC) +  \vol(\RC) \right),
\end{multline*}
and consequently $\vol(\PC) \leq \vol(\QC)$ or $\vol(\PC) \leq \vol(\RC)$.

\end{proof}

\begin{proof}[Proof of \Cref{th:Macbeath}]
Note that the functional $\psi_m(\cdot)$ is continuous with respect to Hausdorff distance. On the other hand, for any $o$-symmetric convex body $\KC$ and $\varepsilon > 0$ there is a sequence of $o$-symmetric convex bodies $\KC_s$ such that each element can be obtained from $\KC$ by finitely many subsequent Steiner symmetrizations, and $\KC_s$ tends to a Euclidean ball, as $s \to \infty$, with respect to Hausdorff distance \cite[Section 10]{BookSchneider}. Thus, \Cref{lm:Macbeath} implies $\psi_m(\KC) \geq \psi_m(\BB^n_2)$.
\end{proof}
\begin{corollary}\label{cor:vol_Delta_body}
    Let $\KC \subseteq \RR^n$ be a compact $n$-dimensional set containing $\BZero$, then
    \begin{equation*}
        \frac{\vol \KC}{\vol \BB^n_2} \leq \Delta(\KC)
    \end{equation*}
\end{corollary}
\begin{proof}
    % If $\KC$ is centrally symmetric, then the statement directly follows from Theorem \ref{th:MakBeath}.
    \GribanovAdd{
    We are going to use \Cref{th:Macbeath} setting $m = 2n$ and $o = \BZero$. It is straightforward to see that each $o$-symmetric polytope $\PC$ of positive volume with at most $2n$ vertices has the form $\PC = A \cdot \BB_1^n$ for some non-singular $n \times n$ matrix $A$. Denote $\KC' = \conv\bigl(\KC \cup (-\KC)\bigr)$ and let $A \cdot \BB_1^n$ be an $o$-symmetric polytope inside $\KC'$ of the maximum volume. Note that the corresponding polytope of the maximum volume with respect to $\BB_2^n$ is $\BB_1^n$. Thus, by \Cref{th:Macbeath}, we have
    \begin{equation*}
        \frac{\vol \KC'}{\abs{\det A} \cdot \vol \BB_1^n} \geq \frac{\vol \BB_2^n}{\vol \BB_1^n}.
    \end{equation*}
    Consequently, since $\abs{\det A} = \Delta(\KC')$,
    \begin{equation*}
        \frac{\vol \KC'}{\vol \BB^n_2} \leq \Delta(\KC').
    \end{equation*}
    }
    From \Cref{rm:Delta_extreme_rm}, we know that $\Delta(\KC') = \Delta\bigl(\extreme(\KC')\bigr) = \Delta(\KC)$. Thus, we obtain
    \begin{equation*}
        \frac{\vol \KC}{\vol \BB^n_2} \leq \frac{\vol \KC'}{\vol \BB^n_2} \leq \Delta(\KC') = \Delta(\KC),
    \end{equation*}
    which completes the proof.
    % We refine $\KC$ by including $-x$ to $\KC$ for any $x \in \KC$. Clearly, $\vol \KC$ will not decrease and $\Delta(\KC)$ will stay the same. 
\end{proof}
The inequality becomes an equality for $\KC = r \cdot \BB^n_2$, $r > 0$. 

\subsection{From an Upper Bound on Polyhedral Fans to an Upper Bound on Vertices}

The following corollary is a discrete variation \Cref{cor:vol_Delta_body}.
\begin{corollary}\label{cor:vol_Delta_fan}
    Let $\FS$ be a packing of $n$-dimensional simplicial polyhedral cones based on the columns of a matrix $A \in \RR^{n \times m}$. Denote $\Delta = \Delta(A)$ and $\Delta_{\average} = \Delta_{\average}(\FS,A)$, then
    \begin{gather}
        \frac{\vol \norm{\FS}_A}{\vol \BB^n_2} \leq \Delta, \quad\text{and} \label{eq:fan_vol_Delta_ineq}\\
        \abs{\FS} \leq n! \cdot \frac{\Delta}{\Delta_{\average}} \cdot \vol \BB^n_2 \sim \frac{1}{\sqrt{n \pi}} \cdot \left(\frac{2 \pi}{e}\right)^{n/2} \cdot n^{n/2} \cdot \frac{\Delta}{\Delta_{\average}}.\label{eq:fan_NVertex_Delta_ineq}
    \end{gather}
    % Both inequalities are tight.
\end{corollary}
