    Denote $\KC = \norm{\FS}_A$. By \Cref{cor:vol_Delta_body} and \Cref{rm:Delta_extreme_rm},
    \begin{equation*}
        \frac{\vol \KC}{\vol \BB_2^n} \leq \Delta(\KC) = \Delta\bigl(\extreme(\KC)\bigr) \leq \Delta.
    \end{equation*}
    % Let $\KC = \norm{\FS}_A$ and $\KC' = \conv\bigl(\KC \cup (-\KC)\bigr)$. Following the proof of Corollary \ref{cor:vol_Delta_body},  
