\section{Note about the Diameter of a Polyhedron}\label{sec:diam_UB}

In this subsection, we prove \Cref{th:diamUB} by combining results from Dadush and H\"ahnle \cite{ShadowSimplexForCurved} with the trick described in \Cref{prop:totally_unimodular_set}. First, we recall several definitions from \cite{SubdeterminantsDiameter} and \cite{ShadowSimplexForCurved}.
\begin{definition}[$\delta$-distance Property]
    A set of linearly independent vectors $v_1, \dots, v_k \in \RR^n$ satisfies the \emph{$\delta$-distance property} if for every $i \in \intint k$, the vector $v_i$ is at Euclidean distance at least $\delta \norm{v_i}_2$ from $\linh\left(v_j \colon j \in \intint k \setminus i\right)$.

    For a polyhedron $\PC = \bigl\{ x \in \RR^n \colon A x \leq b \bigr\}$, we define $\PC$ to satisfy the \emph{local $\delta$-distance} property if every feasible basis of $A$, i.e. the rows of $A$ defining a vertex of $\PC$, satisfies the $\delta$-distance property.
\end{definition}

\begin{definition}[$\tau$-wide Polyhedra]
    We say that a cone $\CCal$ is \emph{$\tau$-wide} if it contains a Euclidean ball of radius $\tau$ centered on the unit sphere. We define a polyhedron $\PC$ to have a \emph{$\tau$-wide} normal fan (or simply $\PC$ to be $\tau$-wide) if every vertex normal cone is $\tau$-wide.
\end{definition}

According to \cite{ShadowSimplexForCurved}, the diameter of $\tau$-wide polyhedra is bounded by a polynomial function of $n$ and $\tau$.
\begin{theorem}[{\cite[Theorem 3]{ShadowSimplexForCurved}}]\label{th:tau_wide_diam}
    Let $\PC \subseteq \RR^n$ be an $n$-dimensional $\tau$-wide pointed polyhedron. Then the graph of $\PC$ has diameter bounded by $8n/\tau \cdot (1 + \ln 1/\tau)$. Furthermore, a path of this expected length can be constructed via the shadow simplex method.
\end{theorem}
According to \cite{ShadowSimplexForCurved}, the parameter $\tau$ can be expressed as a function of $\delta$.
\begin{lemma}[{\cite[Lemma 5]{ShadowSimplexForCurved}}]\label{lm:diam_prop_transition}
    Let $v_1, \dots, v_n \in \sphere^{n-1}$ be a basis satisfying the $\delta$-distance property. Then $\cone(v_1, \dots, v_n)$ is $(\delta/n)$-wide.
\end{lemma}

We are now ready to prove our observation.
\begin{lemma}\label{lm:transfomed_poly_delta_distance}
    Let $\PC \subseteq \RR^n$ be a pointed $n$-dimensional polyhedron defined by the system $A x \leq b$. Denote $\Delta = \Delta(A)$ and $\Delta_{\min} = \Delta_{\min}(\PC,A)$. Additionally, let $B$ be an $n \times n$ submatrix of $A$ such that $\abs{\det B} = \Delta$. Then, the polyhedron $\PC'$ defined by the system $A B^{-1} x \leq b$ satisfies the local $\delta$-distance property with 
    \begin{equation*}
        \delta \geq \frac{\Delta_{\min}}{n \Delta}.
    \end{equation*}
\end{lemma}

\begin{proof}
    \GribanovAdd{
    Let $\TS$ be a triangulation of $\NS(\PC)$, for which the value of $\Delta_{\min}(\PC,A)$ is attained. 
    Denote $A' = A B^{-1}$, and observe that for each $\BC \in \TS$,
    \begin{equation}\label{eq:Delta_poly_transform_prop_1}
        \abs{\det A'_{\BC *}} \geq \frac{\Delta_{\min}}{\Delta}.
    \end{equation}
    Additionally, for any $k \in \intint n$ and each square submatrix $C \in \RR^{k \times k}$ of $A'$, we have
    \begin{equation}\label{eq:Delta_poly_transform_prop_2}
        \abs{\det(C)} \leq 1.
    \end{equation}
    }

    % Denote $A' = A B^{-1}$, and observe that for any $k \in \intint n$ and any square submatrix $C \in \RR^{k \times k}$ of $A'$, we have
    % \begin{equation}\label{eq:Delta_poly_transform_prop}
    %     \frac{\Delta_{\min}}{\Delta} \leq \abs{\det(C)} \leq 1.
    % \end{equation}

    Fix some $\BC \in \TS$ and denote $M = A'_{\BC *}$. Additionally, fix some $i \in \intint n$, and let $v = (M_{i *})^\top$. The angle $0 \leq \varphi \leq \pi/2$ between $v$ and the subspace spanned by the remaining columns of $M$, i.e. $\linh(M_{\intint n \setminus i})$, can be expressed by the formula
    \begin{equation}\label{eq:cone_angle}
        \sin \varphi = \cos (\pi/2-\varphi) = \frac{\abs{\langle v, u \rangle}}{\norm{v}_2 \norm{u}_2},
    \end{equation}
    where $u$ is a normal vector to $\linh(M_{\intint n \setminus i})$. We can choose $u$ as the $i$-th column of the adjugate of $M$.  From \eqref{eq:Delta_poly_transform_prop_1} and \eqref{eq:Delta_poly_transform_prop_2}, we know that $\norm{u}_{\infty} \leq 1$, $\norm{v}_\infty \leq 1$, and $\abs{\langle v, u \rangle} = \abs{\det M} \geq \frac{\Delta_{\min}}{\Delta}$. Now the proof follows by applying these inequalities to the formula \eqref{eq:cone_angle}.
\end{proof}

As a consequence of \Cref{lm:transfomed_poly_delta_distance}, \Cref{lm:diam_prop_transition} and \Cref{th:tau_wide_diam}, we get our diameter bound.

