\section{Construction for Lower Bounds}\label{sec:LB}

In this subsection, we construct a sequence of examples demonstrating the tightness of inequalities in \Cref{cor:vol_Delta_fan} and \Cref{th:vertexUB}. This sequence simultaneously establishes the lower bound for polyhedral diameters by \Cref{prop:diamLB}. The construction leverages the approximation of the unit sphere by simplicial polytopes.

\subsection{Lower Bounds for Fan Size and Number of Vertices}

Our construction involves three interrelated objects: $\left\{ (\FS_k, R_k, \PC_k) \right\}_{k \geq 0}$, where:
\begin{itemize}
    \item $\FS_k$ is a simplicial polyhedral fan generated by columns of $R_k$,
    \item $\PC_k$ is a convex polytope such that the cones induced by $\PC_k$'s faces form $\FS_k$, i.e.,
    \begin{equation*}
        \FS_k = \left\{ \cone(\TC) \colon \TC \text{ is a face of } \PC_k \right\}.
    \end{equation*}
\end{itemize}
The construction begins with $\FS_k$, employing iterative subdivision of the facets of a regular simplex.  
\begin{definition}
    For $d \leq n$, let $\SC \subseteq \RR^n$ be a $d$-dimensional simplex with the vertices $v_1, v_2, \dots, v_{d+1}$. Then, the point
    \begin{equation*}
        b = \frac{1}{d+1} \cdot (v_1 + \ldots + v_{d+1})
    \end{equation*}
    is called the \emph{barycenter} of $\SC$.

    We define the \emph{simplicial subdivision operation on $\SC$} as an operation replacing $\SC$ with the set of the following $d+1$ subsimplices:
    \begin{equation*}
        \conv(v_1, \dots, v_{i-1}, b, v_{i+1}, \dots, v_{d+1}), \quad \text{for } i \in \intint{d+1}.
    \end{equation*}
    Denote this operation by $\subdiv(\SC)$. For $k \geq 1$, recursively define the $k$-th subdivision:
    \begin{gather*}
        \subdiv^k(\SC) = \bigcup_{\TC \in \subdiv^{k-1}(\SC)} \subdiv(\TC), \\
        \subdiv^0(\SC) = \{\SC\}.
    \end{gather*}
    \GribanovAdd{For the sake of clarity, we note that the $k$-the subdivision operation $\subdiv^k(\SC)$, started from a $n$-dimensional simplex $\SC$, will replace $\SC$ by a set of $(n+1)^k$ simplices of dimension $n$.}
\end{definition}

The following lemma establishes a key property of the subdivision operation: the vertices of subdivided simplices form a dense subset of the original simplex $\SC$. This should be well-known, but we could not find the proof in the literature. Thus, we provide a proof of the lemma in \Vref{proof:lm:subdiv}.
\begin{restatable}{lemma}{subdivisionDensity}
\label{lm:subdiv}
    Let $\SC \subseteq \RR^n$ be a $d$-dimensional simplex. For $k \geq 0$, let $\VC_k$ be the set of vertices of $\subdiv^k(\SC)$, and $\VC_{\infty} = \bigcup_{k \geq 0} \VC_k$. Then, the set $\VC_{\infty}$ forms a dense subset of $\SC$.
\end{restatable}
% \begin{lemma}\label{lm:subdiv}
%     Let $\SC \subseteq \RR^n$ be a $d$-dimensional simplex. For $k \geq 0$, let $\VC_k$ be the set of vertices of $\subdiv^k(\SC)$, and $\VC_{\infty} = \bigcup_{k \geq 0} \VC_k$. Then, the set $\VC_{\infty}$ forms a dense subset of $\SC$.
% \end{lemma}

We now present our explicit construction. Let $\PC_0 \subseteq \RR^n$ be a regular $n$-dimensional simplex with the vertices lying in the unit sphere $\sphere^{n-1}$, and let $\TC_1, \dots, \TC_{n+1}$ denote its facets. For each facet $\TC_i$ and iteration $k \geq 0$, we define:
\begin{itemize}
    \item $\BS_{i}^k = \subdiv^k(\TC_i)$ (the $k$-th simplicial subdivision of $\TC_i$),
    \item $\VC_i^k$ = the set of vertices of all simplices in $\BS_{i}^k$,
\end{itemize}
Let $\BS^k = \bigcup_{i=1}^{n+1} \BS_i^k$ and $\VC^k = \bigcup_{i=1}^{n+1} \VC_i^k$. For each $k \geq 0$, we construct:
\begin{itemize}
    \item The polyhedral fan $\FS_k$ with $\Gamma_n(\FS_k) = \left\{ \cone(\SC) \colon \SC \in \BS^k \right\}$,
    \item The matrix $R_k$, whose columns are central projections of $\VC^k$ onto $\sphere^{n-1}$.
\end{itemize} 

Given the construction of $\PC_{k-1}$, we build $\PC_k$ via the following procedure.
\begin{algorithmic}[1]
\State Initialize $\PC_k \gets \PC_{k-1}$;
\For{each facet $\TC$ of $\PC_{k-1}$}
    \State Identify the unique $v \in \VC^k$ satisfying $\cone(v) \cap \inter(\TC) \neq \emptyset$;
    \State Select $\alpha > 0$ such that:
    \begin{itemize}
        \item $\alpha v \notin \PC_{k-1}$,
        \item $\TC$ is the sole visible facet from $\alpha v$;
    \end{itemize}
    \State Update $\PC_k \gets \conv(\PC_k, \alpha v)$;
\EndFor
\end{algorithmic}
The construction yields $\PC_k$ with these inductively verifiable properties (algorithm correctness follows from Property 3):
\begin{proposition}\label{prop:PC_properties}
    For all $k \geq 0$:
    \begin{enumerate}
        \item $\PC_k$ remains convex;
        \item $\exists$ diagonal matrix $D_k \succ \BZero$ such that the columns of $R_k D_k$ are the vertices of $\PC_k$;
        \item $\FS_k$ coincides with face cones of $\PC_k$:
            \begin{equation*}
                \FS_k = \left\{ \cone(\TC) \colon \TC \text{ is a face of } \PC_k \right\}.
            \end{equation*}
    \end{enumerate}
\end{proposition}

\GribanovAdd{
Recall the following definition.
\begin{definition}
    A subset $\YC$ of $\XC \subseteq \RR^n$ is an \emph{$\varepsilon$-dense subset of $\XC$} if 
    \begin{equation*}
        \forall x \in \XC,\, \exists y \in \YC\colon \quad \norm{x-y}_2 \leq \varepsilon.
    \end{equation*}
    In other words, $\YC$ forms an \emph{$\varepsilon$-cover of $\XC$.}
\end{definition}
}

\begin{lemma}\label{lm:FS_properties}
    % Let \begin{equation*}
    %    \FC_{\infty} = \bigcup_{k = 0}^{\infty} \norm{\FC_k}_{A_k} 
    % \end{equation*}.
    The following properties hold:
    \begin{enumerate}
        \item \GribanovAdd{For any $\varepsilon > 0$ there exists $k' = k(\varepsilon)$ such that the set $\norm{\FS_{k'}}_{R_{k'}}$ is an $\varepsilon$-dense subset of $\BB_2^n$};
        \item $\lim_{k \to \infty} \Delta(R_k) = 1$;
        \item $\lim_{k \to \infty} \vol\left(\norm{\FS_k}_{R_k}\right) = \vol(\BB_2^n)$.
