\end{lemma}

\begin{proof}
    \GribanovAdd{We first prove that there exists $k' = k(\varepsilon)$ such that the columns of $R_{k'}$ form an $\varepsilon$-dense subset of $\sphere^{n-1}$.} Fix $\hat v \in \sphere^{n-1}$ and $\varepsilon > 0$. We will find $k' = k(\varepsilon)$ and a column $\hat u$ of $R_{k'}$ satisfying $\norm{\hat u - \hat v}_2 \leq \varepsilon$.

    Let $v$ be the intersection of $\PC_0$ with the ray $\{t \hat v : t \geq 0\}$, and let $\TC_1$ be the facet of $\PC_0$ containing $v$. For $x \in \TC_1$, denote by $\hat x$ its central projection to $\sphere^{n-1}$. By convexity, there exists $0 < c_n \leq 1$ (depending only on $n$) such that for all $x,y \in \TC_1$,
    \begin{equation*}
        \norm{\hat x - \hat y}_2 \leq c_n \cdot \norm{x - y}_2.
    \end{equation*}
    \Cref{lm:subdiv} guarantees $k'$ and $u \in \VC_1^{k'}$ with $\norm{v - u}_2 \leq \varepsilon/c_n$, implying $\norm{\hat v - \hat u}_2 \leq \varepsilon$. By construction, $\hat u$ is a column of $R_{k'}$, proving the claim.

    To prove (1), fix $v \in \BB_2^n \setminus \PC_0$ and $\varepsilon > 0$. Let $\hat v$ be a central projection of $v$. The claim yields $k'$ and a column $\hat u$ of $R_{k'}$ with $\norm{\hat v - \hat u}_2 \leq \varepsilon$. Since $[0, \hat u] \subset \norm{\FS_{k'}}_{R_{k'}}$,
    \begin{equation*}
        \dist_2\left(v, \norm{\FS_{k'}}_{R_{k'}}\right) \leq \dist_2\bigl(v, [0, \hat u]\bigr) \leq \varepsilon.
    \end{equation*}
    Properties (2) and (3) follow directly from (1).
\end{proof}

\GribanovAdd{Now we are ready to show that the inequalities \eqref{eq:fan_vol_Delta_ineq}, \eqref{eq:fan_NVertex_Delta_ineq} in \Cref{cor:vol_Delta_fan}, and \Cref{th:vertexUB} are asymptotically tight.
\begin{proposition}\label{prop:tightness_fans}
    For $k \to \infty$, we have
    \begin{gather*}
        \vol\left(\norm{\FS_k}_{R_k}\right) \sim \Delta(R_k) \cdot \vol(\BB_2^n), \quad\text{and}\\
        \abs{\FS_k} \sim n! \cdot \vol(\BB_2^n) \cdot \frac{\Delta(R_k)}{\Delta_{\average}(\FS_k,R_k)}.
