\end{proposition}

\begin{proof}
    The first asymptotic equality directly follows from \Cref{lm:FS_properties}. From the definition of $\Delta_{\average}(\FS_k,R_k)$ and by \Cref{lm:FS_properties}:
    \begin{equation*}
        \abs{\FS_k} = n! \cdot \vol\left(\norm{\FS_k}_{R_k}\right) \cdot \frac{1}{\Delta_{\average}(\FS_k,R_k)} \sim n! \cdot \vol(\BB_2^n) \cdot \frac{\Delta(R_k)}{\Delta_{\average}(\FS_k,R_k)},
    \end{equation*}
    which proves the second asymptotic equality.
\end{proof}
