\begin{proof}\label{proof:th:vertexLB}
    By polarity, the dual polytope to $\PC$ satisfies:
    \begin{multline*}
        \PC_k^{\circ} = \left\{ x \in \RR^n \colon (R_k D_k)^\top x \leq \BUnit \right\} \\
        = \left\{ x \in \RR^n \colon R_k^\top x \leq D_k^{-1} \BUnit \right\},
    \end{multline*}
    where vertices of $\PC_k^{\circ}$ correspond bijectively to facets of $\PC_k$. Since $\PC_k$ is simplicial, $\PC_k^{\circ}$ is simple. Consequently:
    \begin{itemize}
        \item $\FS_k$ coincides with the normal fan of $\PC_k^{\circ}$,
        \item $\abs{\vertex(\PC_k^\circ)} = \abs{\FS_k}$,
        \item Since $\PC_k^{\circ}$ is simple, $\Delta_{\average}(\FS_k,R_k) = \Delta_{\average}(\PC_k^{\circ}, R_k^\top )$.
    \end{itemize}
    Finally, \GribanovAdd{setting $A_k = R_k^\top$ and $b_k = D_k^{-1} \BUnit$, \Cref{th:vertexUB} follows immediately from \Cref{prop:tightness_fans}.}
\end{proof}

\subsection{Diameter Lower Bounds}

As previously noted, the diameter lower bound construction is nearly identical. Specifically, we reuse the polyhedral fan $\FS_k$ but modify its base matrix (denoted hereafter by $M_k$). Let $\GC_k$ denote the graph of $\FS_k$ according to \Cref{def:graph_of_fan}.
\begin{lemma}
    The number of vertices in $\GC_k$ is $(n+1)\cdot n^k$. The diameter of $\GC_k$ is $2^{k+1}-1$.
\end{lemma}

\begin{proof}
    The base case $\GC_0 = \KC_{n+1}$ is trivial. For $k \geq 1$, the graph $\GC_k$ can be constructed from $\GC_{k-1}$ by the following procedure.    
    \begin{itemize}
        \item \GribanovAdd{Consider the graph $\HC_k$ with $(n+1)\cdot n^k$ vertices consisting of $(n+1)\cdot n^{k-1}$ disjoint cliques isomorphic to $\KC_n$. Each clique $\CCal_v$ of $\HC_k$ bijectively corresponds to a vertex $v \in \GC_{k-1}$;}
        \item \GribanovAdd{ We define the graph $\GC_k$ to be equal to $\HC_k$ with the following additional edges. For any edge $(u,v)$ of $\GC_{k-1}$, consider the corresponding cliques $\CCal_u$ and $\CCal_v$ in $\GC_k$. Chose a pair of vertices $(\hat u, \hat v) \in \CCal_u \times \CCal_v$ such that $\hat u$ and $\hat v$ have no incident edges in $\GC_k$ except edges of the cliques $\CCal_u$ and $\CCal_v$. Draw an edge $(\hat u, \hat v)$ into $\GC_k$. }
    \end{itemize}
    \GribanovAdd{
        In other words, the set of edges of $\GC_k$, which was added during the second step, forms a perfect matching. Furthermore, each such an edge is drawn if and only if the corresponding edge exists in $\GC_{k-1}$.  
    }

    \GribanovAdd{
        It is straightforward to see that $\GC_k$ is a graph of $\FS_k$. Indeed, the fan $\FS_k$ is constructed from $\FS_{k-1}$ using the subdivision operation applied to each element of $\Gamma_n(\FS_{k-1})$. The subdivision operation replaces each simplicial cone of $\Gamma_n(\FS_{k-1})$ by $n$ simplicial cones which are pair-wise adjacent. Using the graph theoretical language, we just replace each vertex of $\GC_{k-1}$ by a clique. Next, for each pair of adjacent simplicial cones $\FC_1,\FC_2$ in $\Gamma_n(\FS_{k-1})$, there exists exactly one pair of adjacent simplicial cones $\FC_1'$ and $\FC_2'$ such that $\FC_1'$ and $\FC_2'$ are elements of the subdivisions of $\FC_1$ and $\FC_2$, respectively. This exactly corresponds to the described procedure which draws additional edges to $\GC_k$. 
    }

    \GribanovAdd{By the construction, the number of vertices in $\GC_k$ is $(n+1) \cdot n^k$.} For the diameter, we proceed by induction:
    \begin{itemize}
        \item {Base case ($k=0$)}: $\diam(\GC_0) = 1$ holds;
        \item {Inductive step}: For a \GribanovAdd{maximum} path $P = (v_1, \dots, v_s)$ composed of vertices of $\GC_{k-1}$ with $s = 2^k$, its $\GC_k$-realization consists of a sequence of cliques $(\CCal_{v_1}, \dots, \CCal_{v_s})$ where:
            \begin{itemize}
                \item Adjacent cliques share exactly one edge;
                \item \GribanovAdd{There are no edges connecting vertices of cliques that are not adjacent. In other words, there are no edges $(p,q)$ of $\GC_k$ of the form $p \in \CCal_{v_i}$ and $q \in \CCal_{v_j}$ with $\abs{i-j} > 1$. This fact follows from maximality of $P$.}
                \item \GribanovAdd{This yields a path of length $s + (s-1) = 2^{k+1} - 1$ in $\GC_k$. Clearly, it impossible to obtain a path of longer length, because all the paths in $\GC_k$ have the described structure, and the maximum path can be obtained only from the maximum path in $\GC_{k-1}$.}
            \end{itemize}
    \end{itemize}
\end{proof}

Let $M_k$ be the matrix with columns corresponding to $\VC_k$. Note that $\vol(\PC_0) = (n+1) \cdot \frac{\Delta(M_0)}{n!}$. By \Cref{rm:Delta_extreme_rm}, $\Delta(M_k) = \Delta(M_0)$ for all $k$. Since the subdivision operation splits each $n$-dimensional simplex into $(n+1)$ simplices of equal volume, we obtain:
\begin{equation*}
    (n+1)\cdot n^k = \frac{n! \cdot \vol \PC_0}{\Delta_{\min}(\FS_k,M_k)} = (n+1) \cdot \frac{\Delta(M_k)}{\Delta_{\min}(\FS_k,M_k)}.
\end{equation*}
Combining the identity $\diam(\GC_k) = 2^{k+1}-1$ with the derived relations yields:
\begin{gather*}
    \frac{\ln \left(\diam(\GC_k)+1\right)}{\ln 2} = 1 + \frac{\ln \left(\frac{\Delta(M_k)}{\Delta_{\min}(\FS_k,M_k)}\right)}{\ln n}, \\
    \diam(\GC_k)+1 = 2 \left(\frac{\Delta(M_k)}{\Delta_{\min}(\FS_k,M_k)}\right)^{\frac{\ln 2}{\ln n}}.
\end{gather*}

This proves the existence of a diameter lower bound of a polyhedral fan.
\begin{proposition}\label{prop:fan_diam_LB}
    There exists a sequence $\left\{(\FS_k, M_k)\right\}_{k \geq 0}$ where:
    \begin{itemize}
        \item $\FS_k$ is a polyhedral fan based on the columns of $M_k$,
        \item The diameter of $\GC(\FS_k)$ satisfies:
        \[
        \diam\bigl(\GC(\FS_k)\bigr) = 2^{k+1}-1 = 2 \left(\frac{\Delta(M_k)}{\Delta_{\min}(\FS_k,M_k)}\right)^{1/\log_2 n} - 1.
        \]
    \end{itemize}
\end{proposition}

Following the proof technique of \Cref{prop:vertexLB}, we obtain a diameter lower bound for polyhedra.

