\subsection{Counting Integer Points in Polytopes}

In this subsection, we establish a new complexity bound for counting integer points in $\Delta$-modular polyhedra. Our result builds upon two key ingredients: (1) the upper bound for the size of a polyhedral fan \Cref{cor:vol_Delta_fan}, and (2) the following theorem from \cite{SparseILP_Gribanov}.
\begin{theorem}[Gribanov~et~al. \cite{SparseILP_Gribanov}]\label{th:general_delta_counting}
    Let $\PC \subseteq \RR^n$ be an $n$-dimensional pointed polytope defined by the system $A x \leq b$, where $A \in \ZZ^{m \times n}$ and $b \in \QQ^m$. Denote $\Delta := \Delta(A)$. Assume additionally that a triangulation $\TS$ of the normal fan $\NC(\PC)$ is given. Then, the number $\abs{\PC \cap \ZZ^n}$ can be computed by an algorithm with the computational complexity bound
    \[
        O\left(n^4 \cdot \Delta \cdot \abs{\TS} \cdot \sum\limits_{\TC \in \TS} \abs{\det A_{\TC}}^2\right) \quad \text{operations}.
    \]
\end{theorem}

\begin{remark}
    We note that the complexity bound of \Cref{th:general_delta_counting} was recently improved in the preprint \cite{HyperAvoiding_NonHomo} to
    \begin{equation*}
        O\left(n^3 \cdot \Delta \cdot \abs{\TS} \cdot \sum_{\TC \in \TS} \abs{\det A_{\TC}}^2\right) \quad \text{operations}.
    \end{equation*}
    Moreover, the authors indicate that future work will establish a refined bound of the form
    \begin{equation*}
        n^2 \cdot \Delta \cdot \abs{\TS} \cdot \sum_{\TC \in \TS} \abs{\det A_{\TC}}^2 \cdot \poly(n, \log \Delta) \quad \text{operations}.
    \end{equation*}
\end{remark}

Additionally, we will use the following elementary technical lemma. The proof is given in \Vref{proof:lm:knapsack_ineq}.
\begin{restatable}{lemma}{knapsackInequality}
\label{lm:knapsack_ineq}
    Let $x \in [0,\alpha]^n$ with $\norm{x}_1 \leq \beta$. Then, for any nondecreasing convex function $f \colon \RR_{\geq 0} \to \RR$ satisfying $f(0) = 0$,
    \begin{equation*}
        \sum_{i=1}^n f(x_i) \leq \left\lfloor\frac{\beta}{\alpha}+1\right\rfloor \cdot f(\alpha). 
    \end{equation*}
\end{restatable}

% \begin{lemma}\label{lm:knapsack_ineq}
