Our main result for integer solutions counting is the following.

\integerCounting*

% \begin{theorem}\label{th:delta_counting_complexity}
%      Let $\PC \subseteq \RR^n$ be an $n$-dimensional pointed polytope defined by the system $A x \leq b$, where $A \in \ZZ^{m \times n}$ and $b \in \QQ^m$. Then the number $\abs{\PC \cap \ZZ^n}$ can be computed with
%     \begin{equation*}
%         O(n)^n \cdot \frac{\Delta^4}{\Delta_{\average}} \quad\text{operations}.
%     \end{equation*}
% \end{theorem}
\begin{proof}
    Let $\TS$ be a given triangulation of the normal fan $\NS(\PC)$. By \Cref{th:general_delta_counting}, the number $\abs{\PC \cap \ZZ^n}$ can be computed in
    \[
        O\left( n^4 \cdot \Delta \cdot \abs{\TS} \cdot \sum_{\TC \in \TS} \abs{\det A_{\TC}}^2 \right)
    \]
    arithmetic operations. \Cref{cor:vol_Delta_fan} yields the inequalities:
    \begin{gather*}
         \sum_{\TC \in \TS} \abs{\det A_{\TC}} \leq n! \cdot \Delta \cdot \vol \BB_2 = O(n)^{n/2} \cdot \Delta, \quad\text{and}\\
         \abs{\TS} \leq n! \cdot \frac{\Delta}{\Delta_{\average}} \cdot \vol \BB_2 = O(n)^{n/2} \cdot \frac{\Delta}{\Delta_{\average}}.
    \end{gather*}
    Applying \Cref{lm:knapsack_ineq}, we obtain
    \[
        \sum_{\TC \in \TS} \abs{\det A_{\TC}}^2 = O(n)^{n/2} \cdot \Delta^2,
    \]
    which establishes the claimed complexity of the counting algorithm. 

    \Cref{lm:convex_hull_complexity} guarantees that a triangulation of $\PC$'s normal fan can be constructed in 
    \[
        O(n)^{n/2} \cdot m^2 \cdot \frac{\Delta}{\Delta_{\average}} + T_{\text{LP}}
    \] 
    operations. By Averkov and Schymura \cite{DiffColumnsOther}, we may assume \( m = n^{O(1)} \cdot \Delta \), so the \( m^2 \) term is dominated by the asymptotic complexity. 
    % Let us show that the \( T_{\text{LP}} \) term can be omitted. 
    By Dadush et al. \cite{TardosRevisiting_Dadush}, \( T_{\text{LP}} = n^{O(1)} \cdot m \cdot \log (1+\Delta) \). Since \( \frac{\Delta}{\Delta_{\average}} \geq 1 \), the term \( T_{\text{LP}} \) is also asymptotically negligible.
\end{proof}

