    \section{Omitted Proofs}

    \subsection{Proof of \Cref{lm:subdiv}}\label{proof:lm:subdiv}

    We first establish a preliminary result. Let \(\{\SC_k\}_{k \geq 0}\) be a sequence of \(d\)-dimensional simplices in \(\RR^n\) with barycenters \(\{b_k\}\), where each subsequent simplex \(\SC_{k+1}\) is obtained from \(\SC_k\) by replacing one vertex with \(\SC_k\)'s barycenter \(b_k\).

    \begin{definition}
        A vertex set \(\UC\) is called a \emph{stable subset} of the sequence \(\{\SC_k\}_{k \geq 0}\) if every \(v \in \UC\) remains a vertex in all simplices \(\SC_k\) of the sequence.
    \end{definition}

    \begin{lemma}\label{lm:stable_vertices}
        Let $\UC$ be the maximum stable subset of vertices of $\{\SC_k\}_{k \geq 0}$ (i.e., there are no other stable vertices in the sequence). Denote $b^* = \frac{1}{\abs{\UC}} \sum_{v \in \UC} v$, then
        \begin{equation*}
            \lim\limits_{k \to \infty} b_k = b^*.
        \end{equation*}
    \end{lemma}
    \begin{proof}
        We proceed by induction on $d$. For the base case $d=1$, it suffices to consider $\UC = \{u\}$, where $u$ is the only stable vertex. In this scenario, all subsequent simplices satisfy $\SC_k = [b_{k-1}, u]$ for $k \geq 1$. Since each iteration halves the length of $[b_{k-1}, u]$, the barycenters $b_k$ converge to $u$.

        Assume the lemma holds for $(d-1)$-dimensional simplices. The barycenter $b_k$ of $\SC_k$ decomposes into a weighted average of facet barycenters:
        \begin{equation*}
            b_k = \frac{1}{d+1} \sum_{\FC} b_{k,\FC},
        \end{equation*}
        where $b_{k,\FC}$ denotes the barycenter of facet $\FC$ of $\SC_k$. For any subset $\MC \subseteq \UC$, define $b^*_{\MC} = \frac{1}{|\MC|} \sum_{v \in \MC} v$, and identify faces $\FC$ with their vertex sets. 

        By the induction hypothesis, barycenters of proper faces converge to their stable subsets' barycenters:
        \begin{equation*}
            \lim_{k \to \infty} b_{k,\FC} = b^*_{\FC \cap \UC}.
        \end{equation*}

        The facets of $\SC_k$ divide into two classes:
        \begin{itemize}
            \item $d+1-|\UC|$ facets containing all stable vertices $\UC$,
            \item $|\UC|$ facets omitting exactly one stable vertex.
        \end{itemize}
        Denote $\UC^{c} = \conv(\UC)$. The limit computation follows:
        \begin{multline*}
            \lim_{k \to \infty} b_k = \frac{1}{d+1} \sum_{\FC} b^*_{\FC \cap \UC} =\\
            = \frac{1}{d+1} \left( (d+1-|\UC|) \cdot b^*_{\UC} + \sum_{\substack{\GC \text{ - facet} \\ \text{of } \UC^{c}}} b^*_{\GC} \right) =\\
            = \frac{1}{d+1} \left( (d+1-|\UC|) + |\UC| \right) \cdot b^* = b^*,
        \end{multline*}
        where in the middle equality we have used that $b^* = b^*_{\UC} = \frac{1}{\abs{\UC}} \sum\limits_{\GC} b^*_{\GC}$, for $\GC$ running through the facets of $\UC^{c}$. 
    \end{proof}

    Now we ready to prove \Cref{lm:subdiv}.

    \subdivisionDensity*

    \begin{proof}[\Cref{lm:subdiv}]
        Suppose that there exists a point $x \in \SC$ whose $\varepsilon$-neighborhood contains no points from $\VC_{\infty}$. Then there exists $x'$ in the $\frac{\varepsilon}{2}$-neighborhood of $x$ that lies outside all lower-dimensional simplices at any finite step. This follows because a ball cannot be covered by countably many hyperplanes. 

        For each $k \geq 0$, let $\SC'_k$ be the unique simplex containing $x'$ at step $k$. We claim that, for every $k_0 \geq 0$ and every vertex $u$ of $\SC'_{k_0}$, there exists $k(u) > k_0$ such that $\SC'_{k(u)}$ no longer contains $u$ as a vertex. Otherwise, $\SC'_{k_0}$ would admit a stable vertex subset $\UC$ of maximum cardinality. Following \Cref{lm:stable_vertices}, denote $b^* = \frac{1}{|\UC|} \sum_{v \in \UC} v$. %Let $\UC^c = \conv \UC$. 
        Since $\norm{x'- b^*}_2 > 0$, \Cref{lm:stable_vertices} implies there exists $k$ such that for all $v \in S'_k \setminus \UC$, we have $\norm{v-b^*}_2 < \norm{x' - b^*}_2$. This contradicts $x' \in S'_k$ for any $k \geq 0$, and proves the claim.

        Consequently, after finitely many steps, the diameter of $\SC'_k$ halves, yielding:
        \[
        \lim_{k \to \infty} \diam \SC'_k = 0.
        \]
        Let $k_1$ be the first step where $\diam \SC'_{k_1} < \frac{\varepsilon}{2}$. Then, some point of $\VC^{k_1}$ lies in the $\varepsilon$-neighborhood of $x$, which contradicts our initial assumption.   
    \end{proof}

    \subsection{Proof of \Cref{lm:knapsack_ineq}}\label{proof:lm:knapsack_ineq}

    \knapsackInequality*

    \begin{proof}[\Cref{lm:knapsack_ineq}]
        Consider the polytope $\PC = \bigl\{x \in \RR^n \colon x \in [0,\alpha]^n,\, \norm{x}_1 \leq \beta\bigr\}$. Since $F(x) = \sum_{i=1}^n f(x_i)$ is convex, its maximum is attained at a vertex of $\PC$. The vertices of $\PC$ are of two types:

    \begin{enumerate}
        \item Vertices coinciding with vertices $v$ of $[0,\alpha]^n$: 
        Since $v \in \PC$, the number of nonzeroes in $v$ is bounded by $\lfloor \beta/\alpha \rfloor$, yielding $F(v) \leq \lfloor \beta/\alpha \rfloor \cdot f(\alpha)$.

        \item Intersection points of edges of $[0,\alpha]^n$ with the hyperplane $\sum_{i=1}^n x_i = \beta$:
        Without loss of generality, such vertices have the form
        \begin{equation*}
            v^\top = (\underbrace{\alpha,\dots,\alpha}_{s},\underbrace{0,\dots,0}_{t},x_n),
        \end{equation*}
        where $s+t = n-1$ and $x_n = \beta - s\alpha$. By the monotonicity of $f$,
        \begin{equation*}
            F(v) = s f(\alpha) + f(x_n) \leq \left\lfloor\frac{\beta}{\alpha}+1\right\rfloor \cdot f(\alpha).
        \end{equation*}
    \end{enumerate}
    \end{proof}
