 & $P(Y\!=\!0\mid D\!=\!0)$ & $P(Y\!=\!1\mid D\!=\!0)$\\[4pt]
 \hline
 &\\[-8pt]
 $P(Y\!=\!0\mid D\!=\!1)$ & $P($NR$)$ & $P($HU$)$ \\[4pt]
  $P(Y\!=\!1\mid D\!=\!1)$ & $P($HE$)$ &$P($AR$)$ \\[4pt]
\end{tabular}
