\section{Quasi-triangular Poisson bialgebras}\label{sec:qtpb}
We first recall the notion of coboundary Poisson bialgebras and then introduce the notion of quasi-triangular Poisson bialgebras as a special case of the coboundary Poisson bialgebras.

\begin{definition}(\cite{ni2013poisson})
	Let $(A, [\ ,\ ]_A, \cdot_A)$ be a Poisson algebra, $V$ be a vector space and $\rho, \mu: A \to \End (V)$ be two linear maps.
	Then the triple $(V, \rho, \mu)$ is called a \textbf{representation} of the Poisson algebra $(A, [\ ,\ ]_A, \cdot_A)$
	if the following conditions hold:
	\begin{enumerate}
		\item $(V, \rho)$ is a representation of the Lie algebra $(A, [\ ,\ ]_A)$, that is, 
		$\rho([a,b]_A) = \rho(a)\rho(b) - \rho(b)\rho(a)$ for all $a, b \in A$.
		\item $(V, \mu)$ is a representation of $(A, \cdot_A)$, that is, 
		$\mu(a\cdot_A b) = \mu(a)\mu(b)$ for all $a, b \in A$.
		\item 
		The following equations hold:
		\begin{align*}
			\rho(a \cdot_A b) &= \mu(b) \rho(a) + \mu(a) \rho(b),  \\
			\mu([a, b]_A) &= \rho(a) \mu(b) - \mu(b) \rho(a), \;\; \forall a,b\in A. 
		\end{align*}	
	\end{enumerate}
\end{definition}


\begin{proposition}
	{\rm (\cite{ni2013poisson}) }
	Let $(A, [\ ,\ ]_A, \cdot_A)$ be a Poisson algebra, $V$ be a vector space and $\rho, \mu: A \to \End (V)$ be two linear maps. 
	Then $(V,\rho, \mu)$ is a representation
	of $(A, [\ ,\ ]_A, \cdot_A)$ if and only if there is a Poisson algebra
	structure on $A\oplus V$ with the bilinear operations $[\ ,\ ]$ and $\cdot$ respectively defined by
	\begin{align*}
		\left[a_{1}+v_{1}, a_{2}+v_{2}\right] &=
		[a_{1},a_{2}]_A+\rho(a_1)v_2 - \rho(a_2)v_1, \\
		\left(a_{1}+v_{1}\right) \cdot \left(a_{2}+v_{2}\right) &= a_{1} \cdot_A a_{2}+\mu\left(a_{1}\right) v_{2}+\mu\left(a_{2}\right) v_{1},\; \forall a_{1},
		a_{2} \in A, v_{1}, v_{2} \in V.
	\end{align*}
	In this case, the resulting Poisson algebra
	structure on $A\oplus V$ is denoted by $(A \ltimes_{\rho,\mu}V, [\ ,\ ], \cdot)$ and called the \textbf{semi-direct product Poisson algebra} by $(A, [\ ,\ ]_A, \cdot_A)$ and $(V, \rho, \mu)$.
\end{proposition}

\begin{example}
	(\cite{ni2013poisson})
	Let $(A, [\ ,\ ]_A, \cdot_A)$ be a Poisson algebra. 
	Then $(A, \ad, L)$ is a representation of $(A, [\ ,\ ]_A, \cdot_A)$, 
	which is called the \textbf{adjoint representation}, 
	and $(A^*, -\ad^*, L^*)$ is also a representation of $(A, [\ ,\ ]_A, \cdot_A)$, which is called the \textbf{coadjoint representation}.  
\end{example}

A \textbf{Lie bialgebra} is a pair of Lie algebras $(A, [\ ,\ ]_A)$ and $(A^*, [\ ,\ ]_{A^*})$ such that 
\begin{equation*}
	\delta([a, b]_A) = (\ad(a) \otimes \id + \id \otimes \ad(a) )\delta(b) - (\ad (b) \otimes \id + \id \otimes \ad (b) )\delta(a), \;\;
	\forall a, b \in A,
\end{equation*}
where $\delta: A \to \mathrm{Alt}^2 A$ is defined by $\langle \delta(a), x^* \otimes y^*\rangle = \langle a, [x^*, y^*]_{A^*} \rangle$.
A Lie bialgebra is denoted by $((A, [\ ,\ ]_A), (A^*, [\ ,\ ]_{A^*}))$ or $(A, [\ ,\ ]_A, \delta)$.

An \textbf{infinitesimal bialgebra} is a pair of  associative algebras $(A, \cdot_A)$ and $(A^*, \cdot_{A^*})$ such that 
\begin{equation*}
	\Delta(a \cdot_A b) = (L(a) \otimes \id)\Delta(b) + (\id \otimes R(b) )\Delta(a), \;\;
	\forall a, b \in A,
\end{equation*}
where $\Delta: A \to A \otimes A$ is defined by $\langle \Delta(a), x^* \otimes y^*\rangle = \langle a, x^* \cdot_{A^*} y^* \rangle$.
An infinitesimal bialgebra is denoted by $((A, \cdot_A), (A^*, \cdot_{A^*}))$ or $(A, \cdot_A, \Delta)$.


\begin{definition}
	(\cite{ni2013poisson}) 
	A \textbf{Poisson bialgebra} is a pair of Poisson algebras $(A, [\ ,\ ]_A, \cdot_A)$ and $(A^*$, $[\ ,\ ]_{A^*}$, $\cdot_{A^*})$ such that 
	\begin{enumerate}
		\item 
		$((A, [\ ,\ ]_A), (A^*, [\ ,\ ]_{A^*}))$ is a Lie bialgebra;

		\item 
		$((A, \cdot_A), (A^*, \cdot_{A^*}))$ is an infinitesimal bialgebra;

		\item 
		$\delta$ and $\Delta$ are compatible in the following sense:
		\begin{align*}
			\delta(a \cdot_A b) &= (L(a) \otimes \id)\delta(b) + (L(b) \otimes \id)\delta(a) + (\id \otimes \ad(a))\Delta(b) +(\id \otimes \ad(b))\Delta(a),\\
			%%%%%%%%%%%%%%%%%%%%%%%%%
			\Delta([a, b]_A) &= (\ad(a) \otimes \id + \id \otimes \ad(a))\Delta(b) + (L(b) \otimes \id - \id \otimes L(b))\delta(a), \;\; \forall a, b \in A,
		\end{align*}
		where $\delta, \Delta$ are the linear duals of $[\ ,\ ]_{A^*}$ and $\cdot_{A^*}$ respectively.
	\end{enumerate}
	A Poisson bialgebra is denoted by $((A, [\ ,\ ]_A, \cdot_A), (A^*, [\ ,\ ]_{A^*}, \cdot_{A^*}))$ or $(A, [\ ,\ ]_A, \cdot_A, \delta, \Delta)$.
\end{definition}
Poisson bialgebras could be equivalently characterized by Manin triples of Poisson algebras (\cite{ni2013poisson}). 
Notably, given a Poisson bialgebra $((A, [\ ,\ ]_A, \cdot_A), (A^*, [\ ,\ ]_{A^*}, \cdot_{A^*}))$, the pair $( (A^*, [\ ,\ ]_{A^*}$, $\cdot_{A^*})$, $(A, [\ ,\ ]_A, \cdot_A))$ forms a Poisson bialgebra.


\begin{definition}
	Let $(A, [\ ,\ ]_A, \cdot_A, \delta_A, \Delta_A)$ and $(B, [\ ,\ ]_B, \cdot_B, \delta_B, \Delta_B)$ be two Poisson bialgebras.
	A \textbf{homomorphism} of Poisson bialgebras is a homomorphism of Poisson algebras $\varphi: A \to B$ such that 
	\begin{equation*}
		(\varphi \otimes \varphi)\delta_A = \delta_B \circ \varphi, \;\; 
		(\varphi \otimes \varphi)\Delta_A = \Delta_B \circ \varphi.
	\end{equation*}
	Furthermore, if $\varphi: A \to B$ is a linear isomorphism of vector spaces, then $\varphi: A \to B$ is called an \textbf{isomorphism} of Poisson bialgebras.
\end{definition}

\begin{proposition}\label{prop:tmpb}
	Let $((A, [\ ,\ ]_A, \cdot_A), (A^*, [\ ,\ ]_{A^*}, \cdot_{A^*}))$ be a Poisson bialgebra and $B$ be a vector space.
	Suppose that $\varphi: A \to B$ is a linear isomorphism of vector spaces.
	Define brackets $[\ ,\ ]_B: B \otimes B \to B, \; [\ , \ ]_{B^*}: B^* \otimes B^* \to B^*$ and multiplications $\cdot_B: B \otimes B \to B, \; \cdot_{B^*}: B^* \otimes B^* \to B^*$ respectively by 
	\begin{align*}
		&[a, b]_B = \varphi([\varphi^{-1}(a), \varphi^{-1}(b)]_A), \;\; && a \cdot_B b = \varphi(\varphi^{-1}(a) \cdot_A \varphi^{-1}(b)), \;\; \forall a, b \in B, \\
		&[x^*, y^*]_{B^*} = (\varphi^*)^{-1}([\varphi^{*}(x^*), \varphi^{*}(y^*)]_{A^*}), \;\; &&x^* \cdot_{B^*} y^* = (\varphi^*)^{-1}(\varphi^{*}(x^*) \cdot_{A^*} \varphi^{*}(y^*)), \;\;\forall x^*, y^* \in B^*. 
	\end{align*}
	Then $((B, [\ ,\ ]_B, \cdot_B), (B^*, [\ ,\ ]_{B^*}, \cdot_{B^*}))$ is a Poisson bialgebra.
	Furthermore, $\varphi$ is an isomorphism of Poisson bialgebras.
\end{proposition}
\begin{proof}
	It follows from a straightforward verification.
\end{proof}


\begin{definition}
	(\cite{ni2013poisson})
	A Poisson bialgebra $(A, [\ ,\ ]_A, \cdot_A, \delta, \Delta)$ is called \textbf{coboundary}
	if there exists $r \in A \otimes A$ such that:
	\begin{align}
		\delta(a) &= (\id \otimes \ad(a) + \ad(a) \otimes \id )(r), \label{eq:pcbd1}\\
		\Delta(a) &= (\id \otimes L(a) - L(a) \otimes \id)(r), \;\; \forall a \in A. \label{eq:pcbd2}
	\end{align}
	A coboundary Poisson bialgebra is denoted by $(A, [\ ,\ ]_A, \cdot_A, \delta_r, \Delta_r)$.
\end{definition}



\begin{theorem}\label{thm:cbd}
	{\rm (\cite[Theorem~2]{ni2013poisson})}
	Let $(A, [\ ,\ ]_A, \cdot_A)$ be a Poisson algebra and $r \in A \otimes A$.
	Writing $r$ as $r = S + \Lambda$ with $S \in \mathrm{Sym}^2(A)$ and $\Lambda \in \mathrm{Alt}^2(A)$.
	Let $\delta: A \to A \otimes A$ and $\Delta: A \to A \otimes A$ be two linear maps defined by Eqs.~\eqref{eq:pcbd1} and \eqref{eq:pcbd2} respectively.
	Then $(A^*, \delta^*, \Delta^*)$ is a Poisson algebra such that $(A, [\ ,\ ]_A, \cdot_A, \delta, \Delta)$ is a Poisson bialgebra if and only the following conditions are satisfied (for all $a \in A$):
	\begin{enumerate}[$(1)$]
		\item 
		$(\ad(a) \otimes \id + \id \otimes \ad(a))S = 0$;

		\item 
		$(L(a) \otimes \id - \id \otimes L(a))S = 0$;

		\item 
		$(\ad(a) \otimes \id \otimes \id + \id \otimes \ad(a) \otimes \id + \id \otimes \id \otimes \ad(a))\bm{C}(r) = 0$;

		\item 
		$(L(a) \otimes \id \otimes \id - \id \otimes \id \otimes L(a))\bm{A}(r) = 0$;

		\item 
		$(\ad(a) \otimes \id \otimes \id)\bm{A}(r) - (\id \otimes L(a) \otimes \id - \id \otimes \id \otimes L(a))\bm{C}(r) = 0$,
	\end{enumerate}
	where $\bm{C}(r) := [r_{12}, r_{13}]_A + [r_{13}, r_{23}]_A + [r_{12}, r_{23}]_A$ and $\bm{A}(r) := r_{12} \cdot_A r_{13} + r_{13} \cdot_A r_{23} - r_{23} \cdot_A r_{12}$.
\end{theorem}


\begin{definition}
	(\cite{ni2013poisson})
	Let $(A, [\ ,\ ]_A, \cdot_A)$ be a Poisson algebra and $r \in A \otimes A$.
	Then $r$ is called a solution of the \textbf{Poisson Yang-Baxter equation} in $(A, [\ ,\ ]_A, \cdot_A)$ if 
	$\bm{C}(r) = \bm{A}(r) = 0$.
\end{definition}
Note that $\bm{C}(r) = 0$ is called the \textbf{classical Yang-Baxter equation} in the Lie algebra $(A, [\ ,\ ]_A)$ and $\bm{A}(r) = 0$ is called the \textbf{associative Yang-Baxter equation} in the associative algebra $(A, \cdot_A)$.


Let $A$ be  a vector space. Any $r \in A \otimes A$ can be identified as maps from $A^*$ to $A$, which we denote by $r_{+}: A^* \to A$ and $r_{-}: A^* \to A$, respectively and explicitly,
\begin{equation*}
	\langle r_{+}(x^*), y^*\rangle = - \langle x^*, r_{-}(y^*)\rangle = \langle r, x^* \otimes y^*\rangle, \;\; \forall x^*, y^* \in A^*.
\end{equation*}
Note that $(\tau(r))_{+} = -r_{-}$ and $(\tau(r))_{-} = -r_{+}$. 
Moreover, the bracket and multiplication on $A^*$ defined by Eqs.~\eqref{eq:pcbd1}-\eqref{eq:pcbd2} (as the duals) are respectively given by
\begin{align}
	[x^*, y^*]_r &= -\ad^*(r_{+}(x^*)) y^* +\ad^*(r_{-}(y^*)) x^* , \label{eq:pcbdr1}\\
	x^* \cdot_r y^* &= L^*(r_{+}(x^*)) y^* + L^*(r_{-}(y^*)) x^*, \;\; \forall x^*,y^* \in A^*. \label{eq:pcbdr2}
\end{align}




\begin{proposition}\label{Dj:randtr}
	Let $(A, [\ ,\ ]_A, \cdot_A)$ be a Poisson algebra and $r \in A \otimes A$.  
	Then the following statements are equivalent:
 	\begin{enumerate}[$(1)$]
		\item\label{pbr:1} 
		$r$ is a solution of the Poisson Yang-Baxter equation in $(A, [\ ,\ ]_A, \cdot_A)$.

		\item\label{pbr:2} 
		$\tau (r)$ is a solution of the Poisson Yang-Baxter equation in $(A, [\ ,\ ]_A, \cdot_A)$.

		\item\label{pbr:3} 
		The following equations hold:
		\begin{align}
			[ r_{+}\left(x^{*}\right) , r_{+}\left(y^{*}\right)]_A &=r_{+}\left(-\operatorname{ad}^{*}\left(r_{+}\left(x^{*}\right)\right) y^{*}+\operatorname{ad}^{*}\left(r_{-}\left(y^{*}\right)\right) x^{*}\right), \label{bb1}\\
			%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
			r_{+}\left(x^{*}\right) \cdot_A r_{+}\left(y^{*}\right)&=r_{+}\left(L^{*}\left(r_{+}\left(x^{*}\right)\right) y^{*}+L^{*}\left(r_{-}\left(y^{*}\right)\right) x^{*}\right), \quad \forall x^{*}, y^{*} \in A^{*}. \label{bb2}
			\end{align} 

		\item\label{pbr:4} 
		The following equations hold:
		\begin{align}
			[ r_{-}\left(x^{*}\right) , r_{-}\left(y^{*}\right)]_A &= r_{-}\left(-\operatorname{ad}^{*}\left(r_{-}\left(x^{*}\right)\right) y^{*}+\operatorname{ad}^{*}\left(r_{+}\left(y^{*}\right)\right) x^{*}\right),\\
			%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
			r_{-}\left(x^{*}\right) \cdot_A r_{-}\left(y^{*}\right)&=r_{-}\left(L^{*}\left(r_{-}\left(x^{*}\right)\right) y^{*}+L^{*}\left(r_{+}\left(y^{*}\right)\right) x^{*}\right), \quad \forall x^{*}, y^{*} \in A^{*}. 
		\end{align}
	 \end{enumerate}
\end{proposition}
\begin{proof}
	(\ref{pbr:1}) $ \Longleftrightarrow $ (\ref{pbr:2}): Let $r = \sum\limits_i a_i \otimes b_i \in A \otimes A$. Then we have
	\begin{align*}
		\bm{C}(\tau(r)) &=  \sum_{i,j}  [b_{i}, b_{j}]_A  
		 \otimes   a_{i}   \otimes  a_{j}+ b_{i}  \otimes  [a_{i}, b_{j}]_A \otimes    a_{j}  + b_{i}  \otimes 
		b_{j} \otimes   [a_{i}, a_{j}]_A \\
		&=  \sigma_{13}\left(\sum_{i,j} a_{j}   
		 \otimes   a_{i}   \otimes  [b_{i}, b_{j}]_A +  a_{j}\otimes  [a_{i}, b_{j}]_A \otimes     b_{i}  +  [a_{i}, a_{j}]_A \otimes 
		b_{j} \otimes    b_{i}\right)\\
		&=  -\sigma_{13}(\bm{C}(r)),\\
		\bm{A}(\tau(r)) &=  \sum_{i,j}   b_{i} \cdot_A b_{j}  
		 \otimes   a_{i}   \otimes  a_{j}  + b_{i}  \otimes 
		b_{j} \otimes    a_{i} \cdot_A   a_{j} - b_{i}  \otimes     b_{j} \cdot_A a_{i}  \otimes    a_{j}\\
		&=  \sigma_{13}\left(\sum_{i,j}   
		 a_{j}\otimes   a_{i}   \otimes    b_{i} \cdot_A b_{j} +   a_{i} \cdot_A   a_{j}\otimes 
		b_{j} \otimes   b_{i}  -   a_{j}\otimes     b_{j} \cdot_A a_{i}  \otimes    b_{i}\right)\\
		&=  \sigma_{13}\left(\sum_{i,j}   
		 a_{j}\otimes   a_{i}   \otimes   b_{j} \cdot_A  b_{i} +   a_{j} \cdot_A   a_{i}\otimes 
		b_{j} \otimes   b_{i}  -   a_{j}\otimes     a_{i} \cdot_A  b_{j} \otimes    b_{i}\right)\\
		&=   \sigma_{13}(\bm{A}(r)),
	\end{align*}
	where $\sigma_{13} \in \operatorname{End}(A \otimes A \otimes A)$ is defined by  $\sigma_{13} (a \otimes b \otimes c) = c \otimes b \otimes a$ for all $a,b,c \in A$. 
	Thus, $r$ is a solution of the Poisson Yang-Baxter equation if and only if $\tau (r)$ is a solution of the Poisson Yang-Baxter equation.

	(\ref{pbr:1}) $ \Longleftrightarrow $ (\ref{pbr:3}): It follows from \cite[Proposition~3.8]{bai2010nonabelian} and  \cite[Theorem~3.5]{bai2012oass}. 

	(\ref{pbr:2}) $ \Longleftrightarrow $ (\ref{pbr:4}): It is similar to the proof of (\ref{pbr:1}) $ \Longleftrightarrow $ (\ref{pbr:3}).  
\end{proof}



We now turn to the definition of a quasi-triangular Poisson bialgebra as a special case of the coboundary Poisson bialgebras, and the notion of $(\ad, L)$-invariance of a 2-tensor in $A \otimes A$ is the main ingredient employed, which is motivated by Theorem~\ref{thm:cbd}.



\begin{definition}
	Let $(A, [\ ,\ ]_A, \cdot_A)$ be a Poisson algebra and $r \in A \otimes A$.
	Then $r$ is called \textbf{$(\ad, L)$-invariant} if
	\begin{align}
		(\ad(a) \otimes \id + \id \otimes \ad(a))(r) &= 0, \label{eq:adiv} \\
		(L(a) \otimes \id - \id \otimes L(a))(r) &= 0, \;\; \forall a \in A. \label{eq:liv}
	\end{align}
\end{definition}
Obviously, if $r$ is $(\ad, L)$-invariant, then $\tau(r)$ is also $(\ad, L)$-invariant. 
Denote by $I_r$ the operator
\begin{equation}
	I_r = r_{+} - r_{-}: A^* \to A. \label{eq:i}
\end{equation}
Note that $r_{-} = -r_{+}^*$ and hence $I_r^* = I_r$.
Moreover, let $S$ be the symmetric part of $r$, then $S_{+} = \frac{1}{2}I_r = \frac{1}{2}I_{\tau(r)}$.
In particular, if $r$ is antisymmetric, then $I_r=0$.


\begin{lemma}\label{lem:adi}
	Let $(A, [\ ,\ ]_A, \cdot_A)$ be a Poisson algebra and $r \in A \otimes A$.
	Let $S$ be the symmetric part of $r$. 
	Then the following conditions are equivalent:
	\begin{enumerate}[$(1)$]
		\item\label{pbinv:1} 
		$S$ is $(\ad, L)$-invariant. 

		\item\label{pbinv:2}  
		The following equations hold:
		\begin{align}
			S_{+}(\ad^*(a) x^*) + [a, S_{+}(x^*)]_A &= 0, \label{eq:adi1} \\ 
			%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
			S_{+}(L^*(a) x^*) - a \cdot_A S_{+}(x^*)&= 0, \;\; \forall a \in A, x^* \in A^*. \label{eq:adi2} 
		\end{align}

		\item\label{pbinv:3} 	
		The following equations hold:
		\begin{align}
			\ad^*(S_+(x^*))y^* + \ad^*(S_+(y^*))x^* &= 0, \label{eq:sadi1} \\
			%%%%%%%%%%%%%%%%%%%%%%
			L^*(S_+(x^*))y^* - L^*(S_+(y^*))x^* &= 0, \;\; \forall  x^*,y^* \in A^*. \label{eq:sadi2}
		\end{align}
	\end{enumerate}
\end{lemma}
\begin{proof}
(\ref{pbinv:1}) $\Longleftrightarrow$ (\ref{pbinv:2}): For all $a \in A$ and $x^*, y^* \in A^*$, we have 
	\begin{align*}
		\langle S_{+}(\ad^*(a) x^*) + [a, S_{+}(x^*)], y^*\rangle &= \langle S, \ad^*(a) x^* \otimes y^* + x^* \otimes \ad^*(a) y^* \rangle \\
		&= \langle (\ad(a) \otimes \id + \id \otimes \ad(a))S, x^* \otimes y^* \rangle, \\
		\langle S_{+}(L^*(a) x^*) - a \cdot S_{+}(x^*), y^*\rangle &= \langle S, L^*(a) x^* \otimes y^* - x^* \otimes L^*(a) y^* \rangle \\
		&= \langle (L(a) \otimes \id - \id \otimes L(a))S, x^* \otimes y^* \rangle,
	\end{align*}
	which show  that $S$ is $(\ad, L)$-invariant if and only if Eqs.~\eqref{eq:adi1}-\eqref{eq:adi2} hold.

	(\ref{pbinv:2}) $\Longleftrightarrow $ (\ref{pbinv:3}): For all $a \in A$ and $x^*, y^* \in A^*$, we have 
		\begin{align*}
		\langle \ad^*(S_{+}(x^*)) y^* + \ad^*(S_{+}(y^*)) x^* , a\rangle &= \langle y^*, [S_{+}(x^*), a]_A\rangle + \langle x^*, [S_{+}(y^*), a]_A\rangle  \\
	%	&= \langle y^*, [S_{+}(x^*), a]\rangle -\langle \ad^*(a)(x^*),  S_{+}(y^*)\rangle  \\
	%  &= \langle y^*, [S_{+}(x^*), a]\rangle -\langle y^*,  S_{+}(\ad^*(a)(x^*))\rangle  \\
	  	 &= -\langle y^*, ( S_{+}(\ad^*(a)(x^*))+ [ a,S_{+}(x^*)]_A)\rangle, \\
		\langle L^*(S_{+}(x^*)) y^* - L^*(S_{+}(y^*)) x^*, a \rangle &= \langle y^*, S_{+}(x^*) \cdot_A a\rangle - \langle x^*, S_{+}(y^*) \cdot_A a\rangle\\
&= -\langle y^*,  S_{+}(L^*(a)x^*)- a \cdot_A S_{+}(x^*)  \rangle,	
	\end{align*}
	which show  that Eqs.~\eqref{eq:adi1}-\eqref{eq:adi2} hold if and only if Eqs.~\eqref{eq:sadi1}-\eqref{eq:sadi2} hold.
\end{proof}


Recall that a bilinear form $\mathfrak{B} \in \otimes^2 A^*$ on a Poisson algebra $(A, [\ ,\ ]_A, \cdot_A)$ is called \textbf{invariant} if 
\begin{equation*}
	\mathfrak{B}([a, b]_A, c) = \mathfrak{B}(a, [b, c]_A), \;
	\mathfrak{B}(a \cdot_A b, c) = \mathfrak{B}(a, b \cdot_A c),  
	\;\; \forall a, b, c \in A.
\end{equation*}
A \textbf{quadratic Poisson algebra} is a quadruple $(A, [\ ,\ ]_A, \cdot_A, \mathfrak{B})$ where $(A, [\ ,\ ]_A, \cdot_A)$ is a Poisson algebra and $\mathfrak{B} \in \otimes^2 A^*$ is a nondegenerate symmetric invariant bilinear form on $(A, [\ ,\ ]_A, \cdot_A)$.

\begin{proposition}
	Let $\left(A,[\ ,\ ]_A, \cdot_{A}\right)$ be a Poisson algebra. 
	Then $\left(A \ltimes_{-\mathrm{ad}^{*},L^{*}} A^{*}, [\ ,\ ], \cdot, \mathfrak{B}_d \right)$ is a quadratic Poisson algebra, where $\mathfrak{B}_d$ is defined by
	\begin{align}
		\mathfrak{B}_d\left(a+x^{*}, b+y^{*}\right)=  \left\langle  a,y^{*}\right\rangle + \left\langle b, x^{*}\right\rangle, \quad  \forall a, b \in A,\quad x^{*}, y^{*} \in A^{*}. \label{abm}
	\end{align}
\end{proposition}
\begin{proof}
	It follows from a straightforward computation.
\end{proof}

Let $A$ be a vector space and $\mathfrak{B}$ be a nondegenerate  bilinear form. 
Denote by $I_\mathfrak{B}: A^* \to A$ the induced linear isomorphism defined by
\begin{align}
	\langle I_\mathfrak{B}^{-1}(a), b\rangle := \mathfrak{B}(a, b), \quad \forall a,b \in A. \label{eq:sxrbt1}
\end{align}
Moreover, denote by $r_\mathfrak{B}\in A \otimes A $ the 2-tensor form of $I_\mathfrak{B}$:
\begin{equation}
	\langle r_\mathfrak{B}, x^* \otimes y^*\rangle := \langle   I_\mathfrak{B}(x^*),y^*\rangle, \quad \forall  x^*,y^* \in A^*. \label{eq:sxrbt2}
\end{equation}


\begin{proposition}\label{qparinv}
	Let $(A, [\ ,\ ]_A, \cdot_A)$ be a Poisson algebra and $\mathfrak{B}$ be a nondegenerate  bilinear form.  
	Let $I_\mathfrak{B}: A^* \to A$ be the induced linear isomorphism  by $\mathfrak{B}$ and $r_\mathfrak{B} \in A \otimes A$ be the 2-tensor form of $I_\mathfrak{B}$ given by Eq.~\eqref{eq:sxrbt2}. 
	Then $(A, [\ ,\ ]_A, \cdot_A,\mathfrak{B})$ is a quadratic  Poisson algebra if and only if $r_\mathfrak{B}\in A \otimes A$ is symmetric and $(\ad, L)$-invariant.
\end{proposition}
\begin{proof}
	Suppose that $(A, [\ ,\ ]_A, \cdot_A,\mathfrak{B})$ is a quadratic  Poisson algebra. 
	For all $a, b, c \in A$, there exists $x^*,y^*,z^* \in A^*$ such that $I_\mathfrak{B}(x^*) = a, I_\mathfrak{B}(y^*) = b$ and $I_\mathfrak{B}(z^*) = c$. 
	Then we have
	\begin{equation*}
		\langle  r_\mathfrak{B}-\tau(r_\mathfrak{B}), x^* \otimes y^*\rangle  = \langle   I_{\mathfrak{B}}(x^*), I_\mathfrak{B}^{-1}(b)\rangle  - \langle   I_{\mathfrak{B}}(y^*), I_\mathfrak{B}^{-1}(a)\rangle  = \mathfrak{B}(b,a) -  \mathfrak{B}(a,b) = 0.
	\end{equation*}
	Thus, $r_\mathfrak{B}$ is  symmetric. 
	Moreover, we have
	\begin{align*}
		\langle(\ad(c) \otimes \id + \id \otimes \ad(c))(r_\mathfrak{B}), x^* \otimes y^*\rangle  &= \langle r_\mathfrak{B}, \ad^*(c)(x^*) \otimes y^*\rangle + \langle r_\mathfrak{B} , x^* \otimes \ad^*(c)(y^*)\rangle  \\
		&= \langle I_\mathfrak{B}(y^*), \ad^*(c)(x^*) \rangle + \langle I_\mathfrak{B}(x^*),  \ad^*(c)(y^*)\rangle  \\
		&= \mathfrak{B}( [c,b]_A,  a ) + \mathfrak{B}([c,a]_A,  b)=0, \\
		%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
		\langle	(L(c) \otimes \id - \id \otimes L(c))(r_\mathfrak{B}), x^* \otimes y^*\rangle &= \langle r_\mathfrak{B}, L^*(c)(x^*) \otimes y^*\rangle - \langle r_\mathfrak{B} , x^* \otimes L^*(c)(y^*)\rangle  \\
		&= \langle I_\mathfrak{B}(y^*), L^*(c)(x^*) \rangle - \langle I_\mathfrak{B}(x^*),  L^*(c)(y^*)\rangle  \\
		&= \mathfrak{B}( c \cdot_A b,  a ) - \mathfrak{B}( c \cdot_A  a ,  b)=0, 
	\end{align*}
	which show that $r_\mathfrak{B}\in A \otimes A$ is $(\ad, L)$-invariant.  
	The converse statement can be proved by reversing the argument.
\end{proof}

\begin{definition}\label{quasipb}
	Let $(A, [\ ,\ ]_A, \cdot_A)$ be a Poisson algebra. 
	If $r$ is a solution of the Poisson Yang-Baxter equation in $(A, [\ ,\ ]_A, \cdot_A)$ and the symmetric part of $r \in A \otimes  A$ is $(\ad, L)$-invariant, then the coboundary Poisson bialgebra $(A, [\ ,\ ]_A, \cdot_A, \delta_r,  \Delta_r)$ induced by $r$ is called a \textbf{quasi-triangular Poisson bialgebra}.
	In particular, if $r$ is antisymmetric, then $(A, [\ ,\ ]_A, \cdot_A, \delta_r, \Delta_r)$ is called a \textbf{triangular Poisson bialgebra}.
\end{definition}


\begin{proposition}\label{tquasipba}
	Let $(A, [\ ,\ ]_A, \cdot_A)$ be a Poisson algebra and $r \in A \otimes  A$. 
	Then $(A, [\ ,\ ]_A, \cdot_A, \delta_r, \Delta_r)$ is a  quasi-triangular Poisson bialgebra if and only if $(A, [\ ,\ ]_A, \cdot_A, \delta_{\tau(r)}, \Delta_{\tau(r)})$ is a quasi-triangular Poisson bialgebra.
\end{proposition}
\begin{proof}
	It follows from Proposition~\ref{Dj:randtr}.
\end{proof}


\begin{theorem}\label{thm:pybe2h}
	Let $(A, [\ ,\ ]_A, \cdot_A)$ be a Poisson algebra and $r \in A \otimes A$.
	Writing $r$ as $r = S+ \Lambda$ with $S \in \mathrm{Sym}^2(A)$ and $\Lambda \in \mathrm{Alt}^2(A)$.
	Suppose that $S$ is $(\ad, L)$-invariant.
	Then $r$ is a solution of the Poisson Yang-Baxter equation in $(A, [\ ,\ ]_A, \cdot_A)$ if and only if $(A, [\ ,\ ]_r, \cdot_r)$ is a Poisson algebra and the linear maps $r_{+}, r_{-}: (A^*, [\ ,\ ]_r, \cdot_r) \to (A, [\ ,\ ], \cdot)$ are both Poisson algebra homomorphisms, where $[\ ,\ ]_r, \cdot_r: A^* \otimes A^* \to A^*$ are respectively defined by Eqs.~\eqref{eq:pcbdr1} and \eqref{eq:pcbdr2}.
\end{theorem}
\begin{proof}
	($\Longrightarrow$) 
	By Definition~\ref{quasipb}, $(A, [\ ,\ ]_A, \cdot_A, \delta_r, \Delta_r)$ is a quasi-triangular Poisson bialgebra where $\delta_r,\Delta_r$ are respectively defined by Eqs.~\eqref{eq:pcbd1} and \eqref{eq:pcbd2}. 
	Thus, $(A, [\ ,\ ]_r, \cdot_r)$ is a Poisson algebra where $[\ ,\ ]_r, \cdot_r$ are respectively given by Eqs.~\eqref{eq:pcbdr1} and \eqref{eq:pcbdr2}. 
	Moreover, by Proposition~\ref{Dj:randtr} and Lemma~\ref{lem:adi}, for all $x^*, y^* \in A^*$, we have 
	\begin{align*}
		r_{+}\left([x^{*} ,y^{*}]_r \right)  &=r_{+}\left(-\operatorname{ad}^{*}\left(r_{+}\left(x^{*}\right)\right) y^{*}+\operatorname{ad}^{*}\left(r_{-}\left(y^{*}\right)\right) x^{*}\right) =[ r_{+}\left(x^{*}\right) , r_{+}\left(y^{*}\right)]_A ,\\
		%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
		r_{+}\left( x^{*} \cdot_r y^{*} \right) &=r_{+}\left(L^{*}\left(r_{+}\left(x^{*}\right)\right) y^{*}+L^{*}\left(r_{-}\left(y^{*}\right)\right) x^{*}\right)=  r_{+}\left(x^{*}\right) \cdot_A r_{+}\left(y^{*}\right),\\
		%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
		r_{-}\left([x^{*} ,y^{*}]_r \right)  &=r_{-}\left(-\operatorname{ad}^{*}\left(r_{+}\left(x^{*}\right)\right) y^{*}+\operatorname{ad}^{*}\left(r_{-}\left(y^{*}\right)\right) x^{*}\right) \\
		&=r_{-}\left(-2\operatorname{ad}^{*}\left(S_{+}\left(x^{*}\right)\right) y^{*}-\operatorname{ad}^{*}\left(r_{-}\left(x^{*}\right)\right) y^{*}+\operatorname{ad}^{*}\left(r_{+}\left(y^{*}\right)\right) x^{*}-2\operatorname{ad}^{*}\left(S_{+}\left(y^{*}\right)\right) x^{*}\right) \\
		&=r_{-}\left(  -\operatorname{ad}^{*}\left(r_{-}\left(x^{*}\right)\right) y^{*}  +\operatorname{ad}^{*}\left(r_{+}\left(y^{*}\right)\right) x^{*}  \right) \\
		&=[ r_{-}\left(x^{*}\right) , r_{-}\left(y^{*}\right)]_A, \\
		%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
		r_{-}\left( x^{*} \cdot_r y^{*} \right) &=r_{-}\left(L^{*}\left(r_{+}\left(x^{*}\right)\right) y^{*}+L^{*}\left(r_{-}\left(y^{*}\right)\right) x^{*}\right)\\
		&=r_{-}\left(2L^{*}\left(S_{+}\left(x^{*}\right)\right) y^{*} +  L^{*}\left(r_{-}\left(x^{*}\right)\right) y^{*}+L^{*}\left(r_{+}\left(y^{*}\right)\right) x^{*}-2L^{*}\left(S_{+}\left(y^{*}\right)\right) x^{*}\right)\\
		&=r_{-}\left(L^{*}\left(r_{-}\left(x^{*}\right)\right) y^{*}+L^{*}\left(r_{+}\left(y^{*}\right)\right) x^{*}\right)\\
		&=  r_{-}\left(x^{*}\right) \cdot_A r_{-}\left(y^{*}\right),
	\end{align*} 
	which shows that $r_{+}, r_{-}$ are both Poisson algebra homomorphisms.

	($\Longleftarrow$) 
	It follows from Proposition~\ref{Dj:randtr}. 
\end{proof}



\begin{proposition}\label{pro:pybe2h}
	Let $(A, [\ ,\ ]_A, \cdot_A,\mathfrak{B})$ be a quadratic Poisson algebra and $I_\mathfrak{B}: A^* \to A$ be the induced linear isomorphism by $\mathfrak{B}$. 
	Let $ r \in A \otimes A$.
	Then $r$ is a solution of the Poisson Yang-Baxter equation in $(A, [\ ,\ ]_A, \cdot_A)$ if and only if the linear map $P:= r_{+} \circ I_\mathfrak{B}^{-1}: A \to A$ satisfies the following equations:
	\begin{align}
		[P(a),P(b)]_A &= P\Big([P(a),b] + [a,P(b)] -  [a, (I_{r} \circ I_\mathfrak{B}^{-1})(b)]\Big),\\
		%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
		P(a) \cdot_A P(b) &= P\Big(P(a) \cdot_A b + a \cdot_A  P(b)  -  a \cdot_A (I_{r} \circ I_\mathfrak{B}^{-1})(b) \Big), \quad \forall a,b \in A.
	\end{align}
\end{proposition}
\begin{proof} 
	For all $a,b,c \in A$, there exists $x^*,y^* \in A^*$ such that $I_\mathfrak{B}(x^*) = a$ and $I_\mathfrak{B}(y^*) = b$. 
	Then we have
	\begin{align*}
		[P(a),P(b)]_A  &= [(r_{+} \circ I_\mathfrak{B}^{-1})(a),(r_{+} \circ I_\mathfrak{B}^{-1})(b)]_A = [ r_{+}  (x^*),  r_{+}  (y^*)]_A,\\
		%%%%%%%%%%%%%%%%%%%%%%%%%%
		P ([P(a),b]_A) &= (r_{+} \circ I_\mathfrak{B}^{-1})([(r_{+} \circ I_\mathfrak{B}^{-1})(a),b]_A) = (r_{+} \circ I_\mathfrak{B}^{-1})(\ad(r_{+} (x^*))I_\mathfrak{B}(y^*)) \\
		& =- r_{+} (\ad^*(r_{+} (x^*))  y^* ),\\
		%%%%%%%%%%%%%%%%%%%%%%%%%%
		P ([a,P(b)]_A) &= (r_{+} \circ I_\mathfrak{B}^{-1})([a,(r_{+} \circ I_\mathfrak{B}^{-1})(b)]_A) = -(r_{+} \circ I_\mathfrak{B}^{-1})(\ad( r_{+} (y^*))I_\mathfrak{B}(x^*)) \\
		& =  r_{+} (\ad^*(r_{+} (y^*))  x^* ),\\
		%%%%%%%%%%%%%%%%%%%%%%%%%%
		- P ([a, (I_{r} \circ I_\mathfrak{B}^{-1})(b)]) &= - (r_{+} \circ I_\mathfrak{B}^{-1})([a,(I_{r} \circ I_\mathfrak{B}^{-1})(b)]_A) =   (r_{+} \circ I_\mathfrak{B}^{-1})(\ad( I_{r} (y^*))I_\mathfrak{B}(x^*))  \\
		&= - r_{+} (\ad^*(I_{r} (y^*))  x^* ),\\
		%%%%%%%%%%%%%%%%%%%%%%%%%%%
		P(a) \cdot_A P(b) &= (r_{+} \circ I_\mathfrak{B}^{-1})(a) \cdot_A (r_{+} \circ I_\mathfrak{B}^{-1})(b) = r_{+}(x^*)\cdot_A r_{+}(y^*),\\
		%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
		P( P(a)\cdot_A b) &= (r_{+} \circ I_\mathfrak{B}^{-1})( (r_{+} \circ I_\mathfrak{B}^{-1})(a)\cdot_A  b)= (r_{+} \circ I_\mathfrak{B}^{-1})(L(r_{+}(x^*))I_\mathfrak{B}(y^*) ) \\
		&=  r_{+} (L^*(r_{+}(x^*)) y^* ),\\
		%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
		P(a \cdot_A P(b)) &= (r_{+} \circ I_\mathfrak{B}^{-1})(a \cdot_A (r_{+} \circ I_\mathfrak{B}^{-1})(b) )= (r_{+} \circ I_\mathfrak{B}^{-1})(L(r_{+}(y^*))I_\mathfrak{B}(x^*)) \\
		&=  r_{+} (L^*(r_{+}(y^*))x^* ),\\
		%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
		-  P ( a \cdot_A (I_{r} \circ I_\mathfrak{B}^{-1})(b) ) &= -(r_{+} \circ I_\mathfrak{B}^{-1})(a \cdot_A (I_{r} \circ I_\mathfrak{B}^{-1})(b) )=- (r_{+} \circ I_\mathfrak{B}^{-1})(L(I_{r}(y^*))I_\mathfrak{B}(x^*)) \\  
		&= - r_{+} (L^*(I_{r}(y^*))x^* ).
	\end{align*}
	By Eq.~\eqref{eq:i} and Proposition~\ref{Dj:randtr}, the conclusion follows.
\end{proof} 


We conclude this section by demonstrating that every quadratic Poisson algebra
naturally induces an isomorphism between the adjoint and coadjoint representations of the corresponding Poisson algebra.

\begin{definition}
	Let $(A,[\ ,\ ]_A, \cdot_A)$ be a Poisson algebra, and $(V_1, \rho_1, \mu_1)$ and $(V_2, \rho_2, \mu_2)$ be two representations of $(A,[\ ,\ ]_A,  \cdot_A)$. 
	A \textbf{homomorphism of representations} from $(V_1$, $\rho_1$, $\mu_1)$ to $(V_2$, $\rho_2$, $\mu_2)$ is a linear map $\varphi: V_1 \to V_2$ such that 
	\begin{equation*}
		\varphi \circ \rho_1(a) = \rho_2(a) \circ \varphi, \;
		\varphi \circ \mu_1(a) = \mu_2(a) \circ \varphi, \; \forall a \in A.
	\end{equation*}
	In particular, when $\varphi: V_1 \to V_2$ is a linear isomorphism of vector spaces, $\varphi$ is called an \textbf{isomorphism of representations} from $(V_1, \rho_1, \mu_1)$ to $(V_2, \rho_2, \mu_2)$.
\end{definition}

\begin{theorem}\label{pdualdengjia}
	Let $(A, [\ ,\ ]_A, \cdot_A)$ be a Poisson algebra.   
	If there is a bilinear form $\mathfrak{B}$ such that $(A, [\ ,\ ]_A, \cdot_A, \mathfrak{B})$ is a quadratic Poisson algebra, then the linear map $\mathfrak{B}^\sharp: A \to A^*$ defined by $\langle \mathfrak{B}^\sharp(a), b\rangle = \mathfrak{B}(a, b)$ is an isomorphism from the adjoint representation $(A, \ad, L)$ to the coadjoint representation $(A^*, -\ad^*, L^*)$.

	Conversely, if $I: A \to A^*$ is an isomorphism from the adjoint representation $(A, \ad, L)$ to the coadjoint representation $(A^*, -\ad^*, L^*)$, then the bilinear form $\mathfrak{B}$ defined by $\mathfrak{B}(a, b) = \langle I(a), b\rangle $ is nondegenerate invariant on $(A, [\ ,\ ]_A, \cdot_A)$.
\end{theorem}
\begin{proof}
	Suppose that $(A, [\ ,\ ]_A, \cdot_A, \mathfrak{B})$ is a quadratic Poisson algebra. 
	Then for all $a, b, c \in A$, we have
	\begin{align*}
		\langle \mathfrak{B}^\sharp \ad(b)a, c\rangle &= -\mathfrak{B}([a, b]_A, c) = -\mathfrak{B}(a, [b, c]_A) = \langle -\ad^*(b) \mathfrak{B}^\sharp(a), c\rangle, \\
		\langle \mathfrak{B}^\sharp L(a) b, c\rangle &= \mathfrak{B}(a \cdot_A b, c) = \mathfrak{B}(a, b \cdot_A c) = \langle L^*(b) \mathfrak{B}^\sharp a, c\rangle,
	\end{align*}
	that is,
	\begin{equation*}
		\mathfrak{B}^\sharp \ad(a) = -\ad^*(a) \mathfrak{B}^\sharp, \;\;
		\mathfrak{B}^\sharp L(a) = L^*(a) \mathfrak{B}^\sharp.
	\end{equation*}
	Note that $\mathfrak{B}^\sharp$ is a linear isomorphism.
	Therefore, $\mathfrak{B}^\sharp: A \to A^*$ is an isomorphism from the adjoint representation $(A, \ad, L)$ to the coadjoint representation $(A^*, -\ad^*, L^*)$. 
	The converse can be proved by a similar argument as above.
\end{proof}





