\section{Factorizable Poisson bialgebras}\label{sec:fpb}
In this section, we introduce the notion of a factorizable Poisson bialgebra, which is a special quasi-triangular Poisson bialgebra satisfying the map $I_r: A^* \to A$ is a linear isomorphism of vector spaces.
We show that the Drinfeld classical double of a Poisson bialgebra is naturally a factorizable Poisson bialgebra.


\begin{definition}
	A quasi-triangular Poisson bialgebra $(A, [\ ,\ ]_A, \cdot_A, \delta_r, \Delta_r)$ is called \textbf{factorizable} if the symmetric part $S$ of $r$ is nondegenerate, which means the linear map $I_r: A^* \to A$ defined by Eq.~\eqref{eq:i} is a linear isomorphism of vector spaces.
\end{definition}


\begin{proposition}\label{xtquasipba}
	Let $(A, [\ ,\ ]_A, \cdot_A)$ be a Poisson algebra and $r \in A \otimes A$. 
	Then $(A, [\ ,\ ]_A, \cdot_A, \delta_r, \Delta_r)$ is a factorizable Poisson bialgebra if and only if $(A, [\ ,\ ]_A, \cdot_A, \delta_{\tau(r)}, \Delta_{\tau(r)})$ is a factorizable Poisson bialgebra.
\end{proposition}
\begin{proof}
	It follows from Proposition~\ref{tquasipba}.
\end{proof}

Consider the map 
\begin{equation*}
	A^* \xrightarrow{\;\;\;\;r_{+} \oplus r_{-}\;\;\;\;} A \oplus A \xrightarrow{(a, b) \mapsto a - b} A.
\end{equation*}

The following result justifies the terminology of a factorizable Poisson bialgebra.
\begin{proposition}\label{prop:fpt}
	Let $(A, [\ ,\ ]_A, \cdot_A, \delta_r, \Delta_r)$ be a factorizable Poisson bialgebra.
	Then $\mathrm{Im}(r_{+} \oplus r_{-})$ is a Poisson subalgebra of the direct sum Poisson algebra $A \oplus A$, 
	which is isomorphic to the Poisson algebra $(A^*, [\ ,\ ]_r, \cdot_r)$, where $[\ ,\ ]_r, \cdot_r: A^* \otimes A^* \to A^*$ are respectively defined by Eqs.~\eqref{eq:pcbdr1} and \eqref{eq:pcbdr2}.
	Moreover, any $a \in A$ has a unique decomposition 
	$a = a_{+} - a_{-}$ with $(a_{+}, a_{-}) \in \mathrm{Im}(r_{+} \oplus r_{-})$.
\end{proposition}
\begin{proof}
	By Theorem~\ref{thm:pybe2h}, both $r_{+}$ and $r_{-}$ are Poisson algebra homomorphisms.
	Therefore, $\mathrm{Im}(r_{+} \oplus r_{-})$ is a Poisson subalgebra of the direct sum Poisson algebra $A \oplus A$.
	Since $I_r = r_{+} - r_{-}$ is a linear isomorphism of vector spaces, it follows that the Poisson algebra $\mathrm{Im}(r_{+} \oplus r_{-})$ is isomorphic to the Poisson algebra $(A^*, [\ ,\ ]_r, \cdot_r)$
	Moreover, we have
	\begin{equation*}
		r_{+}I_r^{-1}(a) - r_{-}I_r^{-1}(a) = (r_{+} - r_{-})I^{-1}(a) = a,
	\end{equation*} 
	which shows that $a = a_{+} - a_{-}$ with $a_{+} = r_{+}I_r^{-1}(a)$ and $a_{-} = r_{-}I_r^{-1}(a)$.
	The uniqueness also follows from the fact that $I_r: A^* \to A$ is a linear isomorphism of vector spaces.
\end{proof}



Let $((A, [\ ,\ ]_A, \cdot_A), (A^*, [\ ,\ ]_{A^*}, \cdot_{A^*}))$ be an arbitrary Poisson bialgebra.
Define a bracket and a multiplication on $\mathfrak{A} = A \oplus A^*$ by
\begin{align*}
	[(a, x^*), (b, y^*)]_\mathfrak{A} &= ([a, b]_A - \ad_{[,]_{A^*}}^*(x^*)b + \ad_{[,]_{A^*}}^*(y^*)a, [x^*, y^*]_{A^*} - \ad_{[,]_A}^*(a)y^* + \ad_{[,]_A}^*(b)x^*), \\
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	(a, x^*) \cdot_\mathfrak{A} (b, y^*) &= (a \cdot_A b + L_{\cdot_{A^*}}^*(x^*)b + L_{\cdot_{A^*}}^*(y^*)a, x^* \cdot_{A^*} y^* + L_{\cdot_{A}}^*(a)y^* + L_{\cdot_{A}}^*(b)x^*), 
\end{align*}
where $a, b \in A, x^*, y^* \in A^*$.
Then $(\mathfrak{A}, [\ ,\ ]_\mathfrak{A}, \cdot_\mathfrak{A})$ is a Poisson algebra, which is called the \textbf{Drinfeld classical double} of the Poisson bialgebra. 
Moreover, let $\{e_1, e_2, \cdots, e_n\}$ be a basis of $A$ and $\{e_1^*, e_2^*, \cdots, e_n^*\}$ be the dual basis of $A^*$.
Then 
\begin{equation*}
	r = \sum_{i}e_i \otimes e_i^* \in A \otimes A^* \subset \mathfrak{A} \otimes \mathfrak{A}
\end{equation*}
induces a coboundary Poisson bialgebra structure $(\mathfrak{A}, [\ ,\ ]_\mathfrak{A}, \cdot_\mathfrak{A}, \delta_r, \Delta_r)$ (see \cite[Theorem~3]{ni2013poisson} for more details).

\begin{theorem}\label{thm:spfb}
	The Poisson bialgebra $(\mathfrak{A}, [\ ,\ ]_\mathfrak{A}, \cdot_\mathfrak{A}, \delta_r, \Delta_r)$ is a quasi-triangular Poisson bialgebra. 
	Furthermore, it is factorizable.
\end{theorem}
\begin{proof}
	First, we need to verify that the symmetric part $S = \frac{1}{2}(e_i \otimes e_i^* + e_i^* \otimes e_i)$ of $r$ is $(\ad_{[,]_\mathfrak{A}}, L_{\cdot_\mathfrak{A}})$-invariant.
	For all $(x^*, a) \in \mathfrak{A}^*$, we have $S_{+}(x^*, a) = \frac{1}{2}(a, x^*) \in \mathfrak{A}$.
	Moreover, by a straightforward computation, we have 
	\begin{align*}
		[(a, x^*), S_{+}(y^*, b)]_\mathfrak{A} &= \frac{1}{2}([a, b]_A - \ad_{[,]_{A^*}}^*(x^*)b + \ad_{[,]_{A^*}}^*(y^*)a, [x^*, y^*]_{A^*} - \ad_{[,]_{A}}^*(a)y^* + \ad_{[,]_{A}}^*(b)x^*), \\
		%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
		\ad^*_{[,]_{\mathfrak{A}}}(a, x^*)(y^*, b) &= -([x^*, y^*]_{A^*} - \ad_{[,]_{A}}^*(a)y^* + \ad_{[,]_{A}}^*(b)x^*, [a, b]_A - \ad_{[,]_{A^*}}^*(x^*)b + \ad_{[,]_{A^*}}^*(y^*)a), \\
		%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
		(a, x^*) \cdot_\mathfrak{A} S_{+}(y^*, b) &= \frac{1}{2}(a \cdot_A b + L_{\cdot_{A^*}}^*(x^*)b + L_{\cdot_{A^*}}^*(y^*)a, x^* \cdot_{A^*} y^* + L_{\cdot_{A}}^*(a)y^* + L_{\cdot_{A}}^*(b)x^*), \\
		%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
		L^*_{\cdot_\mathfrak{A}}(a, x^*)(y^*, b) &= (x^* \cdot_{A^*} y^* + L_{\cdot_{A}}^*(a)y^* + L_{\cdot_{A}}^*(b)x^*, a \cdot_A b + L_{\cdot_{A^*}}^*(x^*)b + L_{\cdot_{A^*}}^*(y^*)a). 
	\end{align*}
	Thus, we have
	\begin{align*}
		S_{+}(\ad^*_{[,]_\mathfrak{A}}(a, x^*)(y^*, b))  + [(a, x^*), S_{+}(y^*, b)]_\mathfrak{A} &= 0, \\
		S_{+}(L^*_{\cdot_\mathfrak{A}}(a, x^*)(y^*, b)) - (a, x^*) \cdot_\mathfrak{A} S_{+}(y^*, b) &= 0.
	\end{align*}
	Therefore, by Lemma~\ref{lem:adi}, 
	the symmetric part $S$ of $r$ is $(\ad_{[,]_\mathfrak{A}}, L_{\cdot_\mathfrak{A}})$-invariant.
	By \cite[Theorem~3]{ni2013poisson}, $r$ is a solution of the Poisson Yang-Baxter equation in $(\mathfrak{A}, [\ ,\ ]_\mathfrak{A}, \cdot_\mathfrak{A})$.
	Hence, the Poisson bialgebra $(\mathfrak{A}, [\ ,\ ]_\mathfrak{A}, \cdot_\mathfrak{A}, \delta_r, \Delta_r)$ is a quasi-triangular Poisson bialgebra.

	Finally, we have to show $I_r$ is a linear isomorphism of vector spaces.
	Note that $r_{+}, r_{-}: \mathfrak{A}^* \to \mathfrak{A}$ are given by
	\begin{align*}
		r_{+}(x^*, a) = (0, x^*), \;
		r_{-}(x^*, a) = -(a, 0), \;\;
		\forall a \in A, x^* \in A^*.
	\end{align*}
	Thus, we have $I_r(x^*, a) = (a, x^*)$, which implies that the linear map $I_r: \mathfrak{A}^* \to \mathfrak{A}$ is a linear isomorphism of vector spaces.
	Therefore, the Poisson bialgebra $(\mathfrak{A}, [\ ,\ ]_\mathfrak{A}, \cdot_\mathfrak{A}, \delta_r, \Delta_r)$ is factorizable.
\end{proof}
