\section{Quadratic Rota-Baxter Poisson algebras}\label{sec:rbcfpb}
In this section, we introduce the notion of a quadratic Rota-Baxter Poisson algebra and show that a quadratic Rota-Baxter Poisson algebra of zero weight induces a triangular Poisson bialgebra. 
Moreover, we show that there is a one-to-one correspondence between factorizable Poisson bialgebras and quadratic Rota-Baxter Poisson algebras of nonzero weights.




Recall that a linear map $P: A \to A$ is called a \textbf{Rota-Baxter operator of weight $\lambda$} on a Poisson algebra $(A, [\ ,\ ]_A, \cdot_A)$ if 
\begin{align*}
	[P(a), P(b)]_A &= P([P(a), b]_A + [a, P(b)]_A + \lambda [a, b]_A), \\
	P(a) \cdot_A P(b) &= P(P(a) \cdot_A b + a \cdot_A P(b) + \lambda a \cdot_A b), 
	\;\; \forall a, b \in A.
\end{align*}
A \textbf{Rota-Baxter Poisson algebra $(A, [\ ,\ ]_A, \cdot_A, P)$ of weight $\lambda$} is a Poisson algebra $(A, [\ ,\ ]_A, \cdot_A)$ equipped with a Rota-Baxter operator $P$ of weight $\lambda$.

\begin{lemma}
	Let $(A, [\ ,\ ]_A, \cdot_A, P)$ be a Rota-Baxter Poisson algebra of weight $\lambda$. 
	Then $(A, [\ ,\ ]_P, \cdot_P)$ is a Poisson algebra, which is called the \textbf{descendent Poisson algebra} of $(A, [\ ,\ ]_A, \cdot_A, P)$, where $[\ ,\ ]_P, \cdot_P: A \otimes A \to A$ are respectively defined by 
	\begin{align}
		[a, b]_P &= [P(a), b]_A + [a, P(b)]_A + \lambda [a, b]_A, \label{eq:rdpal}\\
		%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
		a \cdot_P b &= P(a) \cdot_A b + a \cdot_A P(b) + \lambda a \cdot_A b, \;\; \forall a, b \in A. \label{eq:rdpac}
	\end{align}
	Furthermore, $P$ is a Poisson algebra homomorphism from $(A, [\ ,\ ]_P, \cdot_P)$ to $(A, [\ ,\ ]_A, \cdot_A)$.
\end{lemma}
\begin{proof}
	The proof is straightforward.
\end{proof}






Equipping quadratic Poisson algebras with Rota-Baxter operators satisfying compatibility conditions, we introduce the notion of quadratic Rota-Baxter Poisson algebras.
\begin{definition}
	The triple $((A, [\ ,\ ]_A, \cdot_A), \mathfrak{B}, P)$ is called a \textbf{quadratic Rota-Baxter Poisson algebra of weight $\lambda$} if $(A, [\ ,\ ]_A, \cdot_A, \mathfrak{B})$ is a quadratic Poisson algebra and $(A, [\ ,\ ]_A, \cdot_A, P)$ is a Rota-Baxter Poisson algebra of weight $\lambda$ satisfying the following compatibility condition:
	\begin{equation}
		\mathfrak{B}(a, P(b)) + \mathfrak{B}(P(a), b) + \lambda \mathfrak{B}(a, b) = 0, \;\; \forall a, b \in A. \label{eq:qrbp}
	\end{equation}
\end{definition}


\begin{proposition}\label{PandtauP}
	Let $\left(A,[\ ,\ ]_A, \cdot_{A}, \mathfrak{B}\right)$ be a quadratic Poisson algebra and $P: A \rightarrow A$ be a linear map, then $\left(A,[\ ,\ ]_A,\cdot_{A}, \mathfrak{B}, P\right)$ is a quadratic Rota-Baxter Poisson algebra of weight $\lambda$ if and only if $\left(A,[\ ,\ ]_A,\cdot_{A}, \mathfrak{B},\tilde{P}\right)$ is a quadratic Rota-Baxter Poisson algebra of weight $\lambda$, where $\tilde{P} := - \lambda \id - P$.
\end{proposition}
\begin{proof}
	It is easy to show that $P$ is a Rota-Baxter operator of weight $\lambda$ if and only if $\tilde{P}$ is a Rota-Baxter operator of weight $\lambda$. 
	Moreover, we have
	\begin{equation*}
		\mathfrak{B}(\tilde{P}(a), b)+\mathfrak{B}(a,\tilde{P}(b))+\lambda \mathfrak{B}(a, b)=-\mathfrak{B}(P(a), b)-\mathfrak{B}(a, P(b))-\lambda \mathfrak{B}(a, b), \quad \forall a,b \in A.
	\end{equation*}
	Thus, $P$ satisfies Eq.~\eqref{eq:qrbp} if and only if $\tilde{P}$ satisfies Eq.~\eqref{eq:qrbp}. 
	The proof is completed.
\end{proof}


\begin{proposition}\label{exrbfna}
	Let $\left(A,[\ ,\ ]_A, \cdot_{A}\right)$ be a Poisson algebra and $P: A \to A$ be a Rota-Baxter operator of weight $\lambda$ on $\left(A,[\ ,\ ]_A, \cdot_{A}\right)$. 
	Then $\left((A \ltimes_{-\mathrm{ad}^{*},L^{*}} A^{*}, [\ ,\ ], \cdot), \mathfrak{B}_d, P+\tilde{P}^{*}\right)$ is a quadratic Rota-Baxter Poisson algebra of weight $\lambda$, where $\mathfrak{B}_d$ is defined by Eq.~\eqref{abm} and $\tilde{P} := - \lambda \id - P$.
\end{proposition}
\begin{proof}
	The proof is straightforward.
\end{proof}



\begin{lemma}\label{rbfna0}
	Let $A$ be a vector space and $\mathfrak{B}$ be a nondegenerate symmetric bilinear form.
	Let $I_\mathfrak{B}: A^* \to A$ be the induced linear isomorphism by $\mathfrak{B}$ and $r_\mathfrak{B} \in A \otimes A$ be the 2-tensor form of $I_\mathfrak{B}$ given by Eq.~\eqref{eq:sxrbt2}. 
	Suppose that $ r \in A \otimes A$ and $S$ be the symmetric part of $r$. 
	Then $P_{r}:= r_+ \circ I_\mathfrak{B}^{-1}$ satisfies Eq.~\eqref{eq:qrbp} if and only if $S=-\lambda r_{\mathfrak{B}}$ where $\lambda \in \mathbb{K}$.
\end{lemma}
\begin{proof}
	For all $a, b \in A$, there exists $x^{*},y^{*} \in A^{*}$ such that $I_\mathfrak{B}\left(x^{*}\right)=a, I_\mathfrak{B}\left(y^{*}\right)=b$.
	Then
	\begin{align*}
		\mathfrak{B}\left(P_{r}(a), b\right)&=\mathfrak{B}\left(b, P_{r}(a)\right)= \left\langle I_\mathfrak{B}^{-1}(b), (r_+ \circ I_\mathfrak{B}^{-1})(a)\right\rangle=\left\langle r, x^{*} \otimes y^{*}\right\rangle,\\
		%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
		\mathfrak{B}(a, P_{r}(b))&=\left\langle I_\mathfrak{B}^{-1}(a),  (r_+ \circ I_\mathfrak{B}^{-1})(b)\right\rangle=\left\langle r, y^{*} \otimes x^{*}\right\rangle=\left\langle \tau(r), x^{*} \otimes y^{*}\right\rangle, \\
		%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
		\lambda \mathfrak{B}(a, b)&= \lambda \mathfrak{B}(b, a)= \lambda\left\langle I_\mathfrak{B}^{-1}(b), (I_\mathfrak{B} \circ I_\mathfrak{B}^{-1})(a)\right\rangle= \lambda\left\langle r_{\mathfrak{B}}, x^{*} \otimes y^{*}\right\rangle.
	\end{align*}
	Hence, $S= -\lambda r_{\mathfrak{B}}$ if and only if $P_{r}$ satisfies Eq.~\eqref{eq:qrbp}.
\end{proof}



As a direct consequence, a quadratic Rota-Baxter Poisson algebra of zero weight gives rise to a triangular Poisson bialgebra in the following sense.



\begin{proposition} \label{rbfna2}
	Let $\left((A,[\ ,\ ]_A,\cdot_{A}), \mathfrak{B}, P\right)$ be a quadratic Rota-Baxter Poisson algebra of weight $0$ and $I_\mathfrak{B}: A^* \to A$ be the induced linear isomorphism by $\mathfrak{B}$.
	Then $(A, [\ ,\ ]_A, \cdot_A, \delta_r, \Delta_r)$ is a triangular Poisson bialgebra where $r\in A \otimes A$ is the 2-tensor form of $P \circ I_\mathfrak{B}$ given by Eq.~\eqref{eq:sxrbt2}.
\end{proposition}
\begin{proof}
	It follows from Proposition~\ref{pro:pybe2h} and Lemma~\ref{rbfna0} with $r +\tau (r)=0$.
\end{proof}


The following theorem shows that a factorizable Poisson bialgebra naturally gives rise to a quadratic Rota-Baxter Poisson algebra of nonzero weight.


\begin{theorem}\label{thm:fpb2qrp}
	Let $(A, [\ ,\ ]_A, \cdot_A, \delta_r, \Delta_r)$ be a factorizable Poisson bialgebra with $I_r = r_{+}- r_{-}$.
	Then $((A, [\ ,\ ]_A, \cdot_A), \mathfrak{B}, P)$ is quadratic Rota-Baxter Poisson algebra of weight $\lambda$, where the linear map $P: A \to A$ and bilinear form $\mathfrak{B} \in \otimes^2 A^*$ are respectively defined by
	\begin{align*}
		P &= -\lambda r_{+} \circ I_r^{-1}, \quad \lambda \neq 0, \\
		\mathfrak{B}(a, b) &= -\lambda\langle I_r^{-1}(a), b \rangle, \;\; \forall a, b \in A.
	\end{align*}
\end{theorem}
\begin{proof}
	Since the symmetric part of $r$ is $(\ad, L)$-invariant, by Proposition~\ref{qparinv}, $(A, [\ ,\ ]_A, \cdot_A, \mathfrak{B})$ is quadratic Poisson algebra. 
	Moreover, by Proposition~\ref{pro:pybe2h} and Lemma~\ref{rbfna0}, $P$ is a Rota-Baxter operator of weight $\lambda$ on Poisson algebra $(A, [\ ,\ ]_A, \cdot_A)$ and satisfies Eq.~\eqref{eq:qrbp}. 
	Thus, $((A, [\ ,\ ]_A, \cdot_A), \mathfrak{B}, P)$ is quadratic Rota-Baxter Poisson algebra of weight $\lambda$.
\end{proof}





\begin{corollary}
	Let $(A, [\ ,\ ]_A, \cdot_A, \delta_r, \Delta_r)$ be a factorizable Poisson bialgebra with $I_r = r_{+}- r_{-}$, and $P =- \lambda r_{+} \circ I_r^{-1}$ be the induced Rota-Baxter operator of weight $\lambda \neq 0$.
	Let $(A, [\ ,\ ]_P, \cdot_P)$ be the descendent Poisson algebra of the Rota-Baxter algebra $(A, [\ ,\ ]_A, \cdot_A, P)$.
	Then $((A, [\ ,\ ]_P, \cdot_P)$, $(A^*, [\ ,\ ]_{I_r}, \cdot_{I_r}))$ is a Poisson bialgebra, where 
	\begin{align*}
		[x^*, y^*]_{I_r} &:= -\lambda I_r^{-1}([\frac{1}{\lambda}I_r(x^*), \frac{1}{\lambda}I_r(y^*)]_A), \\
		x^* \cdot_{I_r} y^* &:= -\lambda I_r^{-1}((\frac{1}{\lambda}I_r(x^*))\cdot_A (\frac{1}{\lambda}I_r(y^*))), \;\; \forall x^*, y^* \in A^*.
	\end{align*}
	Moreover, $-\frac{1}{\lambda}I_r: A^* \to A$ is a Poisson bialgebra isomorphism from $((A^*, [\ ,\ ]_r, \cdot_r), (A, [\ ,\ ]_A, \cdot_A))$ to $((A$, $[\ ,\ ]_P$, $\cdot_P)$, $(A^*, [\ ,\ ]_{I_r}, \cdot_{I_r}))$, where $[\ ,\ ]_r, \; \cdot_r: A^* \otimes A^* \to A^*$ are respectively defined by Eqs.~\eqref{eq:pcbdr1} and \eqref{eq:pcbdr2}.
\end{corollary}
\begin{proof}
	For all $x^*, y^* \in A^*$, setting $a = I_r(x^*)$ and $b = I_r(y^*)$, we have 
	\begin{align*}
		-\frac{1}{\lambda}I_r([x^*, y^*]_r)   
		&\overset{\eqref{eq:pcbdr1}}{=}-\frac{1}{\lambda}I_r(-\ad^*(r_{+}(x^*)) y^* +\ad^*(r_{-}(y^*)) x^*)\\
		&\overset{\eqref{eq:adi1}}{=}-\frac{1}{\lambda} ([ r_{+}(x^*), I_r(y^*)]_A - [r_{-}(y^*),  I_r(x^*)]_A )\\
		 & = \frac{1}{\lambda^2}([PI_r(x^*), I_r(y^*)]_A + [I_r(x^*), PI_r(y^*)]_A + \lambda [I_r(x^*), I_r(y^*)]_A)\\
		  & \overset{\eqref{eq:rdpal}}{=} [ -\frac{1}{\lambda}I_r(x^*), - \frac{1}{\lambda}I_r(y^*)]_P.
	\end{align*}
	Similarly, we have 
	\begin{equation*}
		-\frac{1}{\lambda}I_r(x^* \cdot_r y^*) = (-\frac{1}{\lambda}I_r(x^*)) \cdot_P  (-\frac{1}{\lambda}I_r(y^*)).
	\end{equation*}
	Hence, $-\frac{1}{\lambda}I_r: (A^*, [\ ,\ ]_r, \cdot_r) \to (A, [\ ,\ ]_A, \cdot_A)$ is a Poisson algebra homomorphism.

	Noting that $\frac{1}{\lambda}I^* = \frac{1}{\lambda}I$, we have 
	\begin{align*}
		-\frac{1}{\lambda}I^*_r([x^*, y^*]_{I_r}) = [-\frac{1}{\lambda}I_r(x^*), -\frac{1}{\lambda}I_r(y^*)]_A = [-\frac{1}{\lambda}I^*_r(x^*), -\frac{1}{\lambda}I^*_r(y^*)]_A, \\
		-\frac{1}{\lambda}I^*_r(x^*  \cdot_{I_r} y^*) = (-\frac{1}{\lambda}I_r(x^*)) \cdot_A (-\frac{1}{\lambda}I_r(y^*)) = (-\frac{1}{\lambda}I^*_r(x^*)) \cdot_A (-\frac{1}{\lambda}I^*_r(y^*)),
	\end{align*}
	which means that $-\frac{1}{\lambda}I_r^*: (A^*, [\ ,\ ]_I, \cdot_I) \to (A, [\ ,\ ]_A, \cdot_A)$ is also a Poisson algebra homomorphism.
	Note that $((A^*, [\ ,\ ]_r, \cdot_r), (A, [\ ,\ ]_A, \cdot_A))$ is a Poisson bialgebra.
	Therefore, by Proposition~\ref{prop:tmpb}, $((A, [\ ,\ ]_P, \cdot_P), (A^*, [\ ,\ ]_{I_r}, \cdot_{I_r}))$ is a Poisson bialgebra.
	Evidently, $-\frac{1}{\lambda}I_r$ is an isomorphism of Poisson bialgebras.
\end{proof}


As a counterpart to Theorem~\ref{thm:fpb2qrp}, the following theorem shows that a quadratic Rota-Baxter Poisson algebra of nonzero weight induces a factorizable Poisson bialgebra, thereby refining the one-to-one correspondence between factorizable Poisson bialgebras and quadratic Rota-Baxter Poisson algebras of nonzero weight.
\begin{theorem}\label{thm:fpb2qrpx}
	Let $((A, [\ ,\ ]_A, \cdot_A), \mathfrak{B}, P)$ be a quadratic Rota-Baxter Poisson algebra of weight $\lambda \neq 0$, and $I_\mathfrak{B}: A^* \to A$ be the induced linear isomorphism by $\mathfrak{B}$. 
	Let $r \in A \otimes A$ be the 2-tensor form of $P \circ I_\mathfrak{B}$ given by Eq.~\eqref{eq:sxrbt2}. 
	Then $r$ is a solution of the Poisson Yang-Baxter equation in $(A, [\ ,\ ]_A, \cdot_A)$ and gives rise to a factorizable Poisson bialgebra $(A, [\ ,\ ]_A, \cdot_A, \delta_r, \Delta_r)$. 
\end{theorem}
\begin{proof}
	Let $r_\mathfrak{B} \in A \otimes A$ be the 2-tensor form of $I_\mathfrak{B}$ given by Eq.~\eqref{eq:sxrbt2} and $S$ be the symmetric part of $r$. 
	By Proposition~\ref{qparinv} and Lemma~\ref{rbfna0}, $r_\mathfrak{B}$ is $(\ad, L)$-invariant and $S = -\lambda r_\mathfrak{B}$, which show that $S$ is also $(\ad, L)$-invariant and $I_r = -\lambda I_\mathfrak{B}$ is a linear isomorphism. 
	Moreover, by Proposition~\ref{pro:pybe2h}, $r$ satisfies the Poisson Yang-Baxter equation since $P$ is a Rota-Baxter operator of weight $\lambda$ on $(A, [\ ,\ ]_A, \cdot_A)$. 
	Thus, $(A, [\ ,\ ]_A, \cdot_A, \delta_r, \Delta_r)$ is a factorizable Poisson bialgebra.
\end{proof}


\begin{corollary}
	Let $(A, [\ ,\ ]_A, \cdot_{A})$ be a Poisson algebra, 
	$\{e_1, e_2, \cdots, e_n\}$ be a basis of $A$ and $\{e_1^*, e_2^*, \cdots, e_n^*\}$ be the dual basis of $A^*$.
	Then $r = \sum_{i} e_i^* \otimes e_i$ is a solution of the Poisson Yang-Baxter equation in $(A \ltimes_{-\mathrm{ad}^{*},L^{*}} A^{*}, [\ ,\ ], \cdot)$ and gives rise to a factorizable Poisson bialgebra $(A \ltimes_{-\mathrm{ad}^{*},L^{*}} A^{*}, [\ ,\ ], \cdot, \delta_r, \Delta_r)$. 
\end{corollary}
\begin{proof}
	Clearly, $\id: A \to A$ is a Rota-Baxter operator of weight $-1$ on $(A, [\ ,\ ]_A, \cdot_{A})$.
	Then by Proposition~\ref{exrbfna}, $\left((A \ltimes_{-\mathrm{ad}^{*},L^{*}} A^{*}, [\ ,\ ], \cdot), \mathfrak{B}_d, \id + 0^*\right)$ is a quadratic Rota-Baxter Poisson algebra of weight $-1$, where $\mathfrak{B}_d$ is defined by Eq.~\eqref{abm}.
	Now the conclusion follows from Theorem~\ref{thm:fpb2qrpx}. 
\end{proof}


\begin{proposition}
	Let $(A, [\ ,\ ]_A, \cdot_A, \delta_r, \Delta_r)$ be a factorizable Poisson bialgebra, which corresponds to a quadratic Rota-Baxter Poisson algebra $((A, [\ ,\ ]_A, \cdot_A), \mathfrak{B}, P)$ of weight $\lambda \neq 0$ via Theorems~\ref{thm:fpb2qrp} and \ref{thm:fpb2qrpx}. 
	Then the factorizable Poisson bialgebra $(A, [\ ,\ ]_A, \cdot_A, \delta_{\tau(r)}, \Delta_{\tau(r)})$ corresponds to the quadratic Rota-Baxter Poisson algebra $((A, [\ ,\ ]_A, \cdot_A), \mathfrak{B}, \tilde{P})$ of weight $\lambda \neq 0$ where $\tilde{P} := - \lambda \id - P$. 
	In conclusion, we have the following commutative diagram.
	\begin{displaymath}
		\xymatrix{ 
			(A, [\ ,\ ]_A, \cdot_A, \delta_r, \Delta_r) \ar@{<->}[rr]^{\mathrm{Prop.}~\ref{xtquasipba}}\ar@{->}[d]^{\mathrm{Thm.}~\ref{thm:fpb2qrp}}&  &  (A, [\ ,\ ]_A, \cdot_A,  \delta_{\tau(r)},\Delta_{\tau(r)}) \ar@{->}[d]^{\mathrm{Thm.}~\ref{thm:fpb2qrp}} \\
			((A, [\ ,\ ]_A, \cdot_A), \mathfrak{B}, P) \ar@<1.5ex>[u]^{\mathrm{Thm.}~\ref{thm:fpb2qrpx}} \ar@{<->}[rr]^{\mathrm{Prop}.~\ref{PandtauP} }& &   ((A, [\ ,\ ]_A, \cdot_A), \mathfrak{B}, \tilde{P}) \ar@<1.5ex>[u]^{\mathrm{Thm.}~\ref{thm:fpb2qrpx}}}
	\end{displaymath}
\end{proposition}
\begin{proof}
	By Theorem~\ref{thm:fpb2qrp}, the factorizable Poisson bialgebra $(A, [\ ,\ ]_A, \cdot_A, \delta_{\tau(r)}, \Delta_{\tau(r)})$ induces a quadratic Rota-Baxter Poisson algebra $(A, [\ ,\ ]_A, \cdot_A, \mathfrak{B}^{\prime}, P^{\prime})$ of weight $\lambda \ne 0$, where
	\begin{align*}
		\mathfrak{B}^{\prime}(a, b)&=-\lambda\langle I_{\tau(r)}^{-1}(a), b \rangle=-\lambda\left\langle I_r^{-1}(a), b\right\rangle=\mathfrak{B}(a, b), \quad \forall a, b \in A,\\
		P^{\prime} &= -\lambda (\tau(r))_{+} \circ I_{\tau(r)}^{-1}= \lambda r_{-} \circ I_{r}^{-1} = \lambda r_{+} \circ I_{r}^{-1} - \lambda I_{r} \circ I_{r}^{-1} = -\lambda \mathrm{id}_A-P = \tilde{P}.
	\end{align*}
	Thus, $(A, [\ ,\ ]_A, \cdot_A, \delta_{\tau(r)},\Delta_{\tau(r)})$ induces a quadratic Rota-Baxter Poisson algebra $((A, [\ ,\ ]_A, \cdot_A)$, $\mathfrak{B}, \tilde{P})$ of weight $\lambda$ by Theorem~\ref{thm:fpb2qrp}.
	Conversely, by a similar argument, we show that the quadratic Rota-Baxter Poisson algebra $((A, [\ ,\ ]_A, \cdot_A)$, $\mathfrak{B}, \tilde{P})$ of weight $\lambda$ induces the factorizable Poisson bialgebra $(A, [\ ,\ ]_A, \cdot_A, \delta_{\tau(r)},\Delta_{\tau(r)})$ via Theorem~\ref{thm:fpb2qrpx}.
\end{proof}

