\section{Quasi-triangular Poisson bialgebras via quasi-triangular differential ASI bialgebras}\label{sec:qpbfqdasi}
In this section, we generalize the construction of Poisson algebras from commutative algebras with a pair of commuting derivations to the context of quasi-triangular bialgebras.
We establish the quasi-triangular and factorizable theories for differential ASI bialgebras, and then construct quasi-triangular and factorizable Poisson bialgebras from quasi-triangular and factorizable (commutative and cocommutative) differential ASI bialgebras respectively.

%In this section, we always assume that $(A, \cdot_{A})$ is a commutative algebra.





Recall that a \textbf{coalgebra} $(A, \Delta)$ is a vector space $A$ with a linear map $\Delta: A \to A \otimes A$ satisfying the coassociative law:
\begin{equation*}
	(\Delta \otimes \id)\Delta = (\id \otimes \Delta) \Delta.
\end{equation*}
A coalgebra $(A, \Delta)$ is called \textbf{cocommutative}
if $\Delta = \tau \Delta$.



\begin{definition}\label{def:asi_bialgebra}
	(\cite{bai2010double})
	An \textbf{antisymmetric infinitesimal bialgebra} or simply an \textbf{ASI bialgebra} is a triple $(A, \cdot, \Delta)$ consisting of a vector space $A$ and linear maps $\cdot: A \otimes A \to A$ and $\Delta: A \to A \otimes A$ such that
	\begin{enumerate}
		\item $(A, \cdot_{A})$ is an associative algebra;
		\item $(A, \Delta)$ is a coalgebra;
		\item the following equations hold for all $a, b \in A$:
		\begin{align*}
			\Delta(a \cdot_{A} b) &= (R(b) \otimes \id )\Delta(a) + (\id \otimes L(a)) \Delta(b),  \\
			(L(a) \otimes \id - \id \otimes R(a))\Delta(b) &= \tau \left( (\id \otimes R(b) - L(b) \otimes \id )\Delta(a) \right).
		\end{align*}
	\end{enumerate}
\end{definition}


\begin{definition}
	Let $(A, \cdot_{A})$ be an associative algebra.
	A linear map $\partial: A \to A$ is called a \textbf{derivation} if the Leibniz rule is satisfied, i.e.,
	\begin{equation*}
		\partial(a \cdot_{A} b) = \partial(a) \cdot_{A} b + a \cdot_{A} \partial(b), \;\; \forall a, b \in A.
	\end{equation*}
	A \textbf{differential algebra} is a triple $(A, \cdot_{A}, \Phi)$, where $(A, \cdot_{A})$ is an associative algebra and $\Phi=\{\partial_{i}: A \to A\}_{i=1}^m$ is a finite set of commuting derivations.
	A differential algebra $(A, \cdot_{A}, \Phi)$ is called \textbf{commutative} if $(A, \cdot_{A})$ is commutative.
\end{definition}




\begin{definition}\label{def:coderivation}
	(\cite{doi1981homological})
	Let $(A, \Delta)$ be an associative coalgebra.
	A linear map $\eth: A \to A$ is called a \textbf{coderivation} on $(A, \Delta)$ if the following equation holds:
	\begin{equation}
		\Delta \eth = (\eth \otimes \id + \id \otimes \eth) \Delta. \label{eq:coderivation}
	\end{equation}
	A \textbf{differential coalgebra} is a triple $(A, \Delta, \Psi)$,
	consisting of an associative coalgebra $(A, \Delta)$ and a finite set of commuting coderivations $\Psi = \{\eth_k: A \to A\}_{k=1}^m$.
	A differential coalgebra $(A, \Delta, \Psi)$ is called \textbf{cocommutative} if $(A, \Delta)$ is cocommutative.
\end{definition}





\begin{definition}\label{def:dasi}
	A \textbf{differential antisymmetric infinitesimal bialgebra} or simply a \textbf{differential ASI bialgebra} is a quintuple
	$(A, \cdot_{A}, \Delta, \Phi, \Psi)$ satisfying
	\begin{enumerate}
		\item $(A, \cdot_{A}, \Delta)$ is an ASI bialgebra;
		\item $(A, \cdot_{A}, \Phi = \{\partial_k\}_{k=1}^m)$ is a differential algebra;
		\item $(A, \Delta, \Psi = \{\eth_k\}_{k=1}^m)$ is a differential coalgebra;
		\item $(A, \cdot_{A}, \Phi)$ is \textbf{$\Psi$-admissible}, that is, the following equations hold:
		\begin{align}
			\eth_k(a) \cdot b &= a \cdot \partial_k(b) + \eth_k(a \cdot b), \label{eq:qadm1} \\
			a \cdot \eth_k(b) &= \partial_k(a) \cdot b + \eth_k(a \cdot b), \;\;
			\forall a,b \in A, \;\; \forall  k=1, \cdots, m. \label{eq:qadm2}
		\end{align}
		\item $(A, \Delta^{*}, \Psi^{*})$ is \textbf{$\Phi^{*}$-admissible}, that is, the following equations hold:
		\begin{align}
			(\partial_k \otimes \id) \Delta &= (\id \otimes \eth_k) \Delta + \Delta \partial_k, \label{eq:psadm1} \\
			(\id \otimes \partial_k) \Delta &= (\eth_k \otimes \id) \Delta + \Delta \partial_k, \;\; \forall  k=1, \cdots, m. \label{eq:psadm2}
		\end{align}
	\end{enumerate}
	A differential ASI bialgebra $(A, \cdot_{A}$, $\Delta$, $\Phi, \Psi)$ is called \textbf{commutative and cocommutative} if $(A$, $\cdot_{A}$, $\Phi)$ is commutative and $(A, \Delta, \Psi)$ is cocommutative.
\end{definition}





\begin{definition}
	Let $(A, \cdot_{A}, \Phi = \{\partial_k\}_{k=1}^m)$ be a differential algebra.
	Suppose that $r \in A \otimes A$ and $\Psi = \{\eth_k: A \to A\}_{k=1}^m$ is a set of commuting linear maps.
	Then $\bm{A}(r) = 0$ with conditions given by the following equations
	\begin{align}
		(\partial_k \otimes \id - \id \otimes \eth_k)(r) &= 0, \label{eq:pqadm1} \\
		(\eth_k \otimes \id - \id \otimes \partial_k)(r) &= 0, \;\; \forall i=1,2, \cdots, m, \label{eq:pqadm2} 
	\end{align}
	is called the \textbf{$\Psi$-admissible associative Yang-Baxter equation} in $(A, \cdot_{A}, \Phi)$ or simply \textbf{$\Psi$-admissible AYBE} in $(A, \cdot_{A}, \Phi)$.
\end{definition}

\begin{lemma}\label{lem:aof}
	Let $(A, \cdot_{A}, \Phi = \{\partial_k\}_{k=1}^m)$ be a differential algebra.
	Suppose that $r \in A \otimes A$ and $\Psi = \{\eth_k: A \to A\}_{k=1}^m$ is a set of commuting linear maps.
	Then Eqs.~\eqref{eq:pqadm1}-\eqref{eq:pqadm2} hold if and only if
	\begin{equation*}
		\partial_{i}r_{+} = r_{+}\eth_{i}^{*}, \;\;
		\partial_{i}r_{-} = r_{-}\eth_{i}^{*}, \;\; \forall i = 1,2, \cdots, m.
	\end{equation*}
\end{lemma}
\begin{proof}
	For all $a \in A$ and $x^{*} \in A^{*}$, we have 
	\begin{align*}
		\langle \partial_{i}r_{+}(x^{*}), y^{*}\rangle &= \langle r, x^* \otimes \partial_{i}^{*}(y^{*})\rangle = \langle (\id \otimes \partial_{i})(r), x^{*} \otimes y^{*}\rangle, \\
		\langle r_{+}(\eth_{i}^{*}(x^{*})), y^{*}\rangle &= \langle r, \eth_{i}^{*}(x^*) \otimes y^{*} \rangle = \langle (\eth_{i} \otimes \id)(r), x^{*} \otimes y^{*}\rangle, \\
		\langle \partial_{i}r_{-}(x^{*}), y^{*}\rangle &= -\langle r, \partial_{i}^{*}(y^{*}) \otimes x^{*}  \rangle = -\langle (\partial_{i} \otimes \id)(r), y^{*} \otimes x^{*}\rangle, \\
		\langle r_{-}(\eth{i}^{*}(x^{*})), y^{*}\rangle &= -\langle r, y^{*} \otimes \eth{i}^{*}(x^{*}) \rangle = -\langle (\id \otimes \eth_{i})(r), y^{*} \otimes x^{*}\rangle,
	\end{align*}
	which completes the proof.
\end{proof}

\begin{lemma}
	Let $(A, \cdot_{A}, \Phi)$ be a $\Psi$-admissible differential algebra and $r \in A \otimes A$.
	If $r \in A \otimes A$ is a solution of the $\Psi$-admissible AYBE in $(A, \cdot_{A}, \Phi)$ and the symmetric part of $r$ satisfies Eq.~\eqref{eq:liv},
	then $(A, \cdot_{A}, \Delta, \Phi, \Psi)$ is a differential ASI bialgebra, 
	where $\Delta: A \to A \otimes A$ is defined by \eqref{eq:pcbd2}.
\end{lemma}
\begin{proof}
	It follows from \cite[Corollary~4.4]{lin2023differential}. 
\end{proof}



\begin{definition}
	Let $(A, \cdot_A, \Phi)$ be a differential algebra and $r \in A \otimes A$.
	Then $r$ is called \textbf{$L$-invariant} if the following equation hold:
	\begin{equation}
		(L(a) \otimes \id - \id \otimes R(a))(r) = 0, \;\; \forall a \in A. \label{eq:livnc}
	\end{equation}
\end{definition}

Recall that a differential ASI bialgebra $(A, \cdot_{A}, \Delta, \Phi, \Psi)$ is called \textbf{coboundary} if $\Delta$ is defined by Eq.~\eqref{eq:pcbd2} for some $r \in A \otimes A$.
A coboundary differential ASI bialgebra is denoted by $(A, \cdot_{A}, \Delta_{r}, \Phi, \Psi)$.

\begin{definition}\label{quasidab}
	Let $(A, \cdot_{A}, \Phi)$ be a $\Psi$-admissible differential algebra. 
	If $r$ is a solution of the $\Psi$-admissible AYBE in $(A, \cdot_{A}, \Phi)$ and the symmetric part of $r \in A \otimes  A$ is $L$-invariant, then the coboundary differential ASI bialgebra $(A, \cdot_{A}, \Delta_{r}, \Phi, \Psi)$ induced by $r$ is called a \textbf{quasi-triangular differential ASI bialgebra}.
	In particular, if $r$ is antisymmetric, then $(A, \cdot_{A}, \Delta_{r}, \Phi, \Psi)$ is called a \textbf{triangular differential ASI bialgebra}.
	A quasi-triangular differential ASI bialgebra $(A, \cdot_{A}$, $\Delta_{r}$, $\Phi$, $\Psi)$ is called \textbf{factorizable} if the symmetric part of $r$ is nondegenerate.
\end{definition}

The following proposition justifies the terminology of a factorizable differential ASI bialgebra.
\begin{definition}
	Let $(A, \cdot_{A}, \Phi_{A}=\{\partial_{A, i}\}_{i=1}^m)$ and $(B, \cdot_{B}, \Phi_{B}=\{\partial_{B, i}\}_{i=1}^m)$ be two differential algebras.
	A linear map $\varphi: (A, \cdot_{A}, \Phi_{A}) \to (B, \cdot_{B}, \Phi_{B})$ is called a \textbf{homomorphism} of differential algebras if $\varphi: (A, \cdot_{A}, \Phi_{A}) \to (B, \cdot_{B}, \Phi_{B})$ is a homomorphism of associative algebras satisfying 
	\begin{equation*}
		\varphi \circ \partial_{A, i} = \partial_{B, i} \circ \varphi, \;\; \forall i = 1, 2, \cdots, m.
	\end{equation*}
	If in addition $\varphi$ is a linear isomorphism, then $\varphi$ is called an \textbf{isomorphism} of differential algebras.
\end{definition}

\begin{proposition}\label{prop:fdt}
	Let $(A, \cdot_{A}, \Delta_{r}, \Phi, \Psi)$ be a factorizable differential ASI bialgebra.
	Then $\mathrm{Im}(r_{+} \oplus r_{-})$ is a differential subalgebra of the direct sum differential algebra $A \oplus A$, 
	which is isomorphic to the differential algebra $(A^*, \cdot_r, \Psi^{*})$, where $\cdot_r: A^* \otimes A^* \to A^*$ is defined by 
	\begin{equation}
		x^* \cdot_r y^* = R^*(r_{+}(x^*)) y^* + L^*(r_{-}(y^*)) x^*, \;\; \forall x^*,y^* \in A^*. \label{eq:dcbdr}
	\end{equation}
	Moreover, any $a \in A$ has a unique decomposition 
	$a = a_{+} - a_{-}$ with $(a_{+}, a_{-}) \in \mathrm{Im}(r_{+} \oplus r_{-})$.
\end{proposition}
\begin{proof}
	By \cite[Proposition~3.2]{sheng2023quasi}, we have that both $r_{+}, r_{-}: (A^{*}, \cdot_{r}) \to (A, \cdot_{A})$ are associative algebra homomorphisms, $\mathrm{Im}(r_{+} \oplus r_{-})$ is an associative subalgebra of the direct sum associative algebra $A \oplus A$, which is isomorphic to the associative algebra $(A^*, \cdot_r)$, and any $a \in A$ has a unique decomposition 
	$a = a_{+} - a_{-}$ with $(a_{+}, a_{-}) \in \mathrm{Im}(r_{+} \oplus r_{-})$.
	Furthermore, by Lemma~\ref{lem:aof}, we show that both $r_{+}, r_{-}: (A^{*}, \cdot_{r}, \Psi^{*}) \to (A, \cdot_{A}, \Phi)$ are differential algebra homomorphisms.
	Therefore, $\mathrm{Im}(r_{+} \oplus r_{-})$ is a differential subalgebra of the direct sum differential algebra $A \oplus A$, 
	which is isomorphic to the differential algebra $(A^*, \cdot_r, \Psi^{*})$.
\end{proof}

Let $(A, \cdot_{A}, \Delta_{r}, \Phi, \Psi)$ be an arbitrary differential ASI bialgebra and $(\mathfrak{A}, \cdot_{\mathfrak{A}})$ be the algebra structure on $A \oplus A^*$ obtained from the matched pair of algebras $(A, A^*, R^*_{\cdot_{A}}, L^*_{\cdot_{A}}, R^*_{\cdot_{A^*}}, L^*_{\cdot_{A^*}})$ (\cite{lin2023differential}).
Moreover, let $\{e_1, e_2, \cdots, e_n\}$ be a basis of $A$ and $\{e_1^*, e_2^*, \cdots, e_n^*\}$ be the dual basis of $A^*$.
Define 
\begin{equation*}
	r = \sum_{i}e_i \otimes e_i^* \in A \otimes A^* \subset \mathfrak{A} \otimes \mathfrak{A}
\end{equation*}
and 
\begin{equation*}
	\Delta_{r}(u) = (\id \otimes L_{\cdot_{\mathfrak{A}}}(u) - R_{\cdot_{\mathfrak{A}}}(u) \otimes \id)(r), \;\; \forall u \in \mathfrak{A},
\end{equation*}
then $(\mathfrak{A}, \cdot_{\mathfrak{A}}, \Delta_{r}, \Phi + \Psi^*, \Psi + \Phi^*)$ is a coboundary differential ASI bialgebra (see \cite[Theorem~4.5]{lin2023differential} for more details).
\begin{theorem}\label{thm:adfd}
	The differential ASI bialgebra $(\mathfrak{A}, \cdot_{\mathfrak{A}}, \Delta_{r}, \Phi + \Psi^*, \Psi + \Phi^*)$ is a quasi-triangular differential ASI bialgebra. 
	Furthermore, it is factorizable.
\end{theorem}
\begin{proof}
	The proof of \cite[Theorem~4.5]{lin2023differential} implies that $r$ is a solution of the $\Psi + \Phi^*$-admissible AYBE in $(\mathfrak{A}, \cdot_{\mathfrak{A}}, \Phi + \Psi^*)$.
	By suitable modification to the proof \cite[Theorem~4.5]{lin2023differential}, we show that the symmetric part of $r$ is $L$-invariant.
	Moreover, by the proof of Theorem~\ref{thm:spfb}, we have $I_{r}$ is an isomorphism of vector spaces.
	Hence, the differential ASI bialgebra $(\mathfrak{A}, \cdot_{\mathfrak{A}}, \Delta_{r}, \Phi + \Psi^*, \Psi + \Phi^*)$ is factorizable.
\end{proof}

\begin{definition}
	A bilinear form $\mathfrak{B}(\ ,\ )$ on an associative algebra $(A, \cdot_{A})$ is called \textbf{invariant} if
	\begin{equation*}
		\mathfrak{B}(a \cdot_{A} b, c) = \mathfrak{B}(a, b \cdot_{A} c), \;\;
		\forall a, b, c \in A.
	\end{equation*}
	A \textbf{Frobenius algebra} $(A, \cdot_{A}, \mathfrak{B})$ is an associative algebra $(A, \cdot_{A})$ with a nondegenerate invariant bilinear form $\mathfrak{B}(\ , \ )$.
	A Frobenius algebra $(A, \cdot_{A}, \mathfrak{B})$ is called \textbf{symmetric} if $\mathfrak{B}(\ , \ )$ is symmetric.
\end{definition}

\begin{definition}
	A \textbf{differential Frobenius algebra} is a quadruple $(A, \cdot_{A}, \Phi, \mathfrak{B})$, where $(A, \cdot_{A}$, $\Phi = \{\partial_k\}_{k=1}^m)$ is a differential algebra
	and $(A, \cdot_{A}, \mathfrak{B})$ is a Frobenius algebra. It is
	called {\bf symmetric} if $\mathfrak B$ is symmetric.
	For all $k=1,\cdots, m$, let $\hat{\partial_k}$ be the adjoint linear operator of $\partial_k$ under the nondegenerate bilinear form $\mathfrak{B}$:
	\begin{equation*}
		\mathfrak{B}(\partial_k(a), b) = \mathfrak{B}(a, \hat{\partial_k}(b)), \;\;
		\forall a, b \in A.
	\end{equation*}
	We call $\hat{\Phi} := \{\hat{\partial_k}\}_{k=1}^m$ the \textbf{adjoint of $\Phi = \{\partial_k\}_{k=1}^m$ with respect to $\mathfrak B$}.
\end{definition}
Note that $\hat{\Phi}$ is admissible to $(A, \cdot_{A}, \Phi)$ (\cite[Proposition~3.3]{lin2023differential}).

\begin{definition}
	The triple $((A, \cdot_A, \Phi = \{\partial_k\}_{k=1}^m), \mathfrak{B}, P)$ is called a \textbf{symmetric Rota-Baxter differential Frobenius algebra of weight $\lambda$} if $(A, \cdot_A, \Phi, \mathfrak{B})$ is a symmetric differential Frobenius algebra and $(A, \cdot_A, P)$ is a Rota-Baxter algebra of weight $\lambda$ satisfying the compatibility condition given by Eq.~\eqref{eq:qrbp} such that 
	\begin{equation*}
		\partial_{i} P = P \partial_{i}, \;\; \forall i=1, 2, \cdots, m.
	\end{equation*}
\end{definition}

\begin{lemma}\label{lem:dfof}
	Let $((A, \cdot_{A}, \Phi = \{\partial_k\}_{k=1}^m), \mathfrak{B}, P)$ be a symmetric Rota-Baxter differential Frobenius algebra of weight $\lambda$, and $I_\mathfrak{B}: A^* \to A$ be the induced linear isomorphism by $\mathfrak{B}$. 
	Let $r \in A \otimes A$ be the 2-tensor form of $P \circ I_\mathfrak{B}$ given by Eq.~\eqref{eq:sxrbt2}. 
	Then 
	\begin{equation*}
		\partial_{i}I_{\mathfrak{B}} = I_{\mathfrak{B}}\hat{\partial_{i}}^{*}, \;\;
		\partial_{i}r_{+} = r_{+}\hat{\partial_{i}}^{*}, \;\; \forall i = 1, 2, \cdots, m.
	\end{equation*}
\end{lemma}
\begin{proof}
	For all $a \in A$ and $x^{*} \in A^{*}$, we have 
	\begin{equation*}
		\mathfrak{B}(\partial_{i}I_{\mathfrak{B}}(x^{*}), a) = \mathfrak{B}(I_{\mathfrak{B}}(x^{*}), \hat{\partial_{i}}(a)) = \langle x^*, \hat{\partial_{i}}(a)\rangle = \langle \hat{\partial_{i}}^{*}(x^*), a\rangle = \mathfrak{B}(I_{\mathfrak{B}}\hat{\partial_{i}}^{*}(x^*), a),
	\end{equation*}
	that is, $\partial_{i}I_{\mathfrak{B}} = I_{\mathfrak{B}}\hat{\partial_{i}}^{*}$.
	Therefore,
	\begin{equation*}
		\partial_{i}r_{+} = \partial_{i}P I_{\mathfrak{B}} = P \partial_{i} I_{\mathfrak{B}} = PI_{\mathfrak{B}}\hat{\partial_{i}}^{*} = r_{+}\hat{\partial_{i}}^{*}.
	\end{equation*}
	The proof is completed.
\end{proof}

\begin{proposition}\label{rbfw0rd}
	Let $\left((A, \cdot_A, \Phi), \mathfrak{B}, P\right)$ be a symmetric Rota-Baxter differential Frobenius algebra of weight $0$ and $I_\mathfrak{B}: A^* \to A$ be the induced linear isomorphism by $\mathfrak{B}$.
	Then $(A, \cdot_A, \Delta_r, \Phi, \hat{\Phi})$ is a triangular differential ASI bialgebra where $r\in A \otimes A$ is the 2-tensor form of $P \circ I_\mathfrak{B}$ given by Eq.~\eqref{eq:sxrbt2} and $\hat{\Phi}$ is the adjoint of $\Phi$ with respect to $\mathfrak B$.
\end{proposition}
\begin{proof}
	It follows from Lemma~\ref{rbfna0} that $r +\tau (r)=0$.
	Similarly to Proposition~\ref{pro:pybe2h}, we show $\bm{A}(r) = 0$.
	On the other hand, setting $\Phi = \{\partial_k\}_{k=1}^m$, by Lemma~\ref{lem:dfof}, we have $\partial_{i}r_{+} = r_{+}\hat{\partial_{i}}$.
	Therefore, by Lemma~\ref{lem:aof}, we show that $r$ is a solution of the $\hat{\Phi}$-admissible AYBE in $(A, \cdot_{A}, \Phi)$.
	Noting that $\hat{\Phi}$ is admissible to $(A, \cdot_{A}, \Phi)$, we complete the proof. 
\end{proof}

\begin{theorem}\label{thm:fdb2qrp}
	Let $(A, \cdot_A, \Delta_r, \Phi = \{\partial_k\}_{k=1}^m, \Psi = \{\eth_k\}_{k=1}^m)$ be a factorizable differential ASI bialgebra with $I_r = r_{+}- r_{-}$.
	Then $((A, \cdot_A, \Phi), \mathfrak{B}, P)$ is symmetric Rota-Baxter differential Frobenius algebra of weight $\lambda$ such that the adjoint of $\Phi$ with respect to $\mathfrak{B}$ is $\Psi$, where the linear map $P: A \to A$ and bilinear form $\mathfrak{B} \in \otimes^2 A^*$ are respectively defined by
	\begin{align*}
		P &= -\lambda r_{+} \circ I_r^{-1}, \quad \lambda \neq 0, \\
		\mathfrak{B}(a, b) &= -\lambda\langle I_r^{-1}(a), b \rangle, \;\; \forall a, b \in A.
	\end{align*}
\end{theorem}
\begin{proof}
	It follows from \cite[Corollary~4.8]{sheng2023quasi} that $(A, \cdot_{A}, \mathfrak{B})$ is a symmetric Frobenius algebra and $(A, \cdot_A, P)$ is a Rota-Baxter algebra of weight $\lambda$ such that Eq.~\eqref{eq:qrbp} holds.
	For all $a \in A$ and $x^* \in A^*$, we have
	\begin{align*}
		\mathfrak{B}(\partial_{i}(a), b) = -\lambda \langle I_{r}^{-1}(\partial_{i}(a)), b\rangle = -\lambda \langle I_{r}^{-1}\partial_{i}I_{r}I_{r}^{-1}(a), b\rangle, \\
		\mathfrak{B}(a, \eth_{i}(b)) = -\lambda \langle I_{r}^{-1}(a), \eth_{i}(b)\rangle = -\lambda \langle I_{r}^{-1}I_{r}\eth_{i}^{*}I_{r}^{-1}(a), b\rangle,
	\end{align*}
	and by Lemma~\ref{lem:aof}, we have 
	\begin{equation*}
		\partial_{i}I_{r} = \partial_{i}(r_{+}-r_{-}) = (r_{+}-r_{-})\eth_{i}^{*} = I_{r}\eth_{i}^{*}.
	\end{equation*}
	Therefore, $\mathfrak{B}(\partial_{i}(a), b) = \mathfrak{B}(a, \eth_{i}(b))$.
	Furthermore, we have 
	\begin{equation*}
		\partial_{i} P = - \lambda \partial_{i} r_{+}  I_{r}^{-1} =  - \lambda r_{+} \eth_{i}^{*} I_{r}^{-1} = - \lambda r_{+} I_{r}^{-1} \partial_{i} = P \partial_{i}.
	\end{equation*}
	The proof is completed.
\end{proof}


\begin{theorem}\label{thm:fdb2qrpx}
	Let $((A, \cdot_{A}, \Phi = \{\partial_k\}_{k=1}^m), \mathfrak{B}, P)$ be a symmetric Rota-Baxter differential Frobenius algebra of weight $\lambda \neq 0$, and $I_\mathfrak{B}: A^* \to A$ be the induced linear isomorphism by $\mathfrak{B}$. 
	Let $r \in A \otimes A$ be the 2-tensor form of $P \circ I_\mathfrak{B}$ given by Eq.~\eqref{eq:sxrbt2} and $\hat{\Phi}$ be the adjoint of $\Phi$ with respect to $\mathfrak B$. 
	Then $r$ is a solution of the $\hat{\Phi}$-admissible AYBE in $(A, \cdot_A, \Phi)$ and gives rise to a factorizable differential ASI bialgebra $(A, \cdot_{A}, \Delta_r, \Phi, \hat{\Phi})$. 
\end{theorem}
\begin{proof}
	By Lemma~\ref{rbfna0}, the symmetric part $S$ of $r$ is equal to $-\lambda r_\mathfrak{B}$ and $I_{r} = -\lambda I_{\mathfrak{B}}$.
	Then by Lemma~\ref{lem:dfof}, we have 
	\begin{equation*}
		\partial_{i}r_{+} = r_{+}\hat{\partial_{i}}^{*} \text{\;\; and \;\;}
		\partial_{i}r_{-} = \partial_{i}(r_{+} - I_{r}) = r_{+}\hat{\partial_{i}}^{*} - I_{r} \hat{\partial_{i}}^{*} = r_{-}\hat{\partial_{i}}^{*}.
	\end{equation*}
	Moreover, similarly to Theorem~\ref{thm:fpb2qrpx}, we show that $\bm{A}(r) = 0$ and $S$ is $L$-invariant.
	Hence, by Lemma~\ref{lem:aof}, $r$ is a solution of the $\hat{\Phi}$-admissible AYBE in $(A, \cdot_{A}, \Phi)$, which completes the proof.
\end{proof}



\begin{proposition}\label{prop:ipfd}
	Let $(A, \cdot_{A}, \Phi = \{\partial_{1}, \partial_{2}\})$ be a commutative differential algebra.
	Then $(A$, $[\ ,\ ]_{A}$, $\cdot_{A})$ is a Poisson algebra, called the \textbf{induced Poisson algebra of $(A, \cdot_{A}, \Phi)$}, where $[\ , \ ]: A \otimes A \to A$ is defined by 
	\begin{equation}
		[a, b]_{A} := \partial_{1}(a)\cdot_{A} \partial_{2}(b) - \partial_{2}(a)\cdot_{A} \partial_{1}(b), \;\; \forall a, b \in A.
	\end{equation}
\end{proposition}

\begin{lemma}
	{\rm (\cite{lin2023differential})}
	Let $(A, \Delta, \Psi = \{\eth_1, \eth_2\})$ be a cocommutative differential coalgebra.
	Then $(A, \delta$, $\Delta)$ is Poisson coalgebra, called the \textbf{induced Poisson coalgebra} of $(A, \Delta, \Psi)$, where $\delta$ is defined by
	\begin{equation}
		\delta = (\eth_1 \otimes \eth_2 - \eth_2 \otimes \eth_1)
		\Delta. \label{eq:coP}
	\end{equation}
	Moreover, $(A^*, \delta^*, \Delta^*)$ is exactly the induced Poisson algebra of the commutative differential algebra $(A^*, \Delta^*, \Psi^*)$.
\end{lemma}

\begin{lemma}\label{lem:aybe2pybe}
	{\rm (\cite{lin2023differential})}
	Let $(A, \cdot_{A}, \Phi = \{\partial_1, \partial_2\})$ be a $\Psi = \{\eth_1, \eth_2\}$-admissible commutative differential algebra and $(A, [\ ,\ ]_{A}, \cdot_{A})$ be the induced Poisson algebra of $(A, \cdot_{A}, \Phi)$.
	Suppose that the following equation hold
	\begin{equation}
		\eth_2(\partial_1(a)) \cdot b = \eth_1(\partial_2(a)) \cdot b , \;\;
		\forall a, b \in A. \label{eq:vip}
	\end{equation}
	Then every solution of $\Psi$-admissible AYBE in $(A, \cdot_{A}, \Phi)$ is a solution of PYBE in the Poisson algebra $(A, [\ ,\ ]_{A}, \cdot_{A})$.
\end{lemma}

\begin{theorem}\label{thm:dasi2pb}
	If $(A, \cdot_{A}, \Delta_{r}, \Phi, \Psi)$ is a quasi-triangular (resp. triangular, factorizable) commutative and cocommutative differential ASI bialgebra, and Eq.~\eqref{eq:vip} holds,
	then $(A, [\ ,\ ]_{A}, \cdot_{A}, \delta, \Delta_{r})$ is a quasi-triangular (resp. triangular, factorizable) Poisson bialgebra through $r$, where $(A, [\ ,\ ]_{A}, \cdot_{A})$ is the induced Poisson algebra of $(A, \cdot_{A}, \Phi)$ and $(A, \delta$, $\Delta_{r})$ is the induced Poisson coalgebra of $(A, \Delta_{r}, \Psi)$. 
\end{theorem}
\begin{proof}
	For all $a \in A$, we have
	\begin{align*}
		&(\ad(a) \otimes \id + \id \otimes \ad(a))(r+\tau(r)) \\
		&\overset{\hphantom{\eqref{eq:qadm1}}}{=} \left((L(\partial_{1}(a))\partial_{2} - L(\partial_{2}(a))\partial_{1} ) \otimes \id + \id \otimes (L(\partial_{1}(a))\partial_{2} - L(\partial_{2}(a))\partial_{1})\right)(r+\tau(r)) \\
		&\overset{\eqref{eq:qadm1}}{=} \left( L(\partial_{1}(a)) \otimes \eth_{2} - L(\partial_{2}(a)) \otimes \eth_{1}  - \id \otimes \eth_{2} L(\partial_{1}(a))  + \id \otimes \eth_{1} L(\partial_{2}(a)) \right)(r+\tau(r)) \\
		&\quad + (\id \otimes L(\eth_{2}\partial_{1}(a)) - \id \otimes L(\eth_{1}\partial_{2}(a)))(r+\tau(r)) \\
		&\overset{\eqref{eq:vip}}{=} \left( (\id \otimes \eth_{2})(L(\partial_{1}(a)) \otimes \id - \id \otimes L(\partial_{1}(a))) + (\id \otimes \eth_{1})(L(\partial_{2}(a)) \otimes \id - \id \otimes L(\partial_{2}(a))) \right)(r + \tau(r))\\
		&= 0.
	\end{align*}
	Hence, the symmetric part of $r$ is $(\ad, L)$-invariant.
	By Lemma~\ref{lem:aybe2pybe}, $r$ is a solution of the Poisson Yang-Baxter equation in $(A, [\ ,\ ]_{A}, \cdot_{A})$.
	Furthermore, 
	\begin{align*}
		\delta(a)&\overset{\hphantom{\eqref{eq:pqadm1}}}{=} (\eth_1 \otimes \eth_2 - \eth_2 \otimes \eth_1) \Delta(a) =(\eth_1 \otimes \eth_2 - \eth_2 \otimes \eth_1) (\id \otimes L(a) - L(a) \otimes \id )(r) \\
		&\overset{\eqref{eq:pqadm1}}{=} (\id \otimes \eth_2 L(a) \partial_1 - \id \otimes \eth_1 L(a) \partial_2 )(r) - (\eth_1 L(a) \partial_2 \otimes \id - \eth_2 L(a) \partial_1 \otimes \id)(r) \\
		&\overset{\eqref{eq:qadm1}}{=} (\id \otimes \ad (a))(r) + (\ad(a) \otimes \id)(r).
	\end{align*}
	It is now obvious that the theorem holds.
\end{proof}

Let $(A, \cdot_{A}, \Delta_{r}, \Phi=\{\partial_{1}, \partial_{2}\}, \Psi=\{\eth_{1}, \eth_{2}\})$ be a communicative and cocommutative factorizable differential ASI bialgebra.
By Proposition~\ref{prop:fdt}, let $(\mathrm{Im}(r_{+} \oplus r_{-}), \cdot, \Phi + \Phi = \{\partial_{1} + \partial_{1}, \partial_{2} + \partial_{2}\})$ be the differential subalgebra of the direct sum differential algebra $A \oplus A$, which is isomorphic to the differential algebra $(A^*, \cdot_r, \Psi^{*})$, where $\cdot_r: A^* \otimes A^* \to A^*$ is defined by \eqref{eq:pcbdr2}.
On the other hand, suppose that Eq.~\eqref{eq:vip} holds. 
Let $(A, [\ ,\ ]_{A}, \cdot_{A}, \delta_{r}, \Delta_{r})$ be the induced factorizable Poisson bialgebra in Theorem~\ref{thm:dasi2pb}.
Then by Proposition~\ref{prop:fpt}, let $(\mathrm{Im}(r_{+} \oplus r_{-}), [\ ,\ ], \cdot)$ be the Poisson subalgebra of the direct sum Poisson algebra $A \oplus A$, 
which is isomorphic to the Poisson algebra $(A^*, [\ ,\ ]_r, \cdot_r)$, where $[\ ,\ ]_r, \cdot_r: A^* \otimes A^* \to A^*$ are respectively defined by Eqs.~\eqref{eq:pcbdr1} and \eqref{eq:pcbdr2}.
\begin{corollary}
	With the conditions as above. 
	The induced Poisson algebras of $(\mathrm{Im}(r_{+} \oplus r_{-}), \cdot, \Phi + \Phi)$ and $(A^*, \cdot_r, \Psi^{*})$ are exactly $(\mathrm{Im}(r_{+} \oplus r_{-}), [\ ,\ ], \cdot)$ and $(A^*, [\ ,\ ]_r, \cdot_r)$ respectively.  
	In conclusion, we have the following commutative diagram
	\begin{displaymath}
		\xymatrix@C=2cm{ 
			(A, \cdot_A, \Delta_r, \Phi, \Psi) \ar@{->}[d]^{\mathrm{Thm.}~\ref{thm:dasi2pb}} \ar@{->}[r]^{\mathrm{Prop.}~\ref{prop:fdt}} & (\mathrm{Im}(r_{+} \oplus r_{-}), \cdot, \Phi + \Phi) \ar@{->}[r]^-{\simeq} \ar@{->}[d]^{\mathrm{Prop.}~\ref{prop:ipfd}} & (A^*, \cdot_r, \Psi^{*}) \ar@{->}[d]^{\mathrm{Prop.}~\ref{prop:ipfd}} \\
			(A, [\ ,\ ]_A, \cdot_A,  \delta_{r},\Delta_{r}) \ar@{->}[r]^{\mathrm{Prop.}~\ref{prop:fpt}} & (\mathrm{Im}(r_{+} \oplus r_{-}), [\ ,\ ], \cdot) \ar@{->}[r]^-{\simeq} & (A^*, [\ ,\ ]_r, \cdot_r) 
		}
	\end{displaymath}
\end{corollary}
\begin{proof}
	By Theorem~\ref{thm:dasi2pb}, we have 
	\begin{equation*}
		(\eth_1 \otimes \eth_2 - \eth_2 \otimes \eth_1)
		\Delta_{r} = \delta_{r}.
	\end{equation*}
	Therefore, the induced Poisson algebra of $(A^*, \cdot_r, \Psi^{*})$ is exactly $(A^*, [\ ,\ ]_r, \cdot_r)$.
	Note that $(A, [\ ,\ ]_{A}, \cdot_{A})$ is the induced Poisson algebra of $(A, \cdot_{A}, \Phi)$, it is straightforward that the induced Poisson algebra of $(\mathrm{Im}(r_{+} \oplus r_{-}), \cdot, \Phi + \Phi)$ is exactly $(\mathrm{Im}(r_{+} \oplus r_{-}), [\ ,\ ], \cdot)$.
	The proof is completed.
\end{proof}



Let $(A, \cdot_{A}, \Delta, \Phi=\{\partial_{1}, \partial_{2}\}, \Psi=\{\eth_{1}, \eth_{2}\})$ be a differential ASI bialgebra.
Let $(A, [\ ,\ ]_{A}, \cdot_{A})$ be the induced Poisson algebra of $(A, \cdot_{A}, \Phi)$ and $(A, \delta$, $\Delta)$ be the induced Poisson coalgebra of $(A, \Delta, \Psi)$. 
Suppose that Eq.~\eqref{eq:vip} and the following equation hold:
\begin{equation}
	(\eth_2\partial_1 \otimes \id)\Delta = (\eth_1\partial_2 \otimes \id)\Delta. \label{eq:vip1}
\end{equation}
Then $(A, [\ ,\ ]_{A}, \cdot_{A}, \delta, \Delta)$ is a Poisson bialgebra (\cite[Theorem~5.24]{lin2023differential}).
Let $(\mathfrak{A}, \cdot_{\mathfrak{A}}, \Delta_{r}, \Phi + \Psi^*, \Psi + \Phi^*)$ be the factorizable differential ASI bialgebra obtained in Theorem~\ref{thm:adfd} arising from $(A$, $\cdot_{A}$, $\Delta$, $\Phi$, $\Psi)$ and $(\mathfrak{A}$, $[\ ,\ ]_\mathfrak{A}$, $\cdot_\mathfrak{A}$, $\delta_r$, $\Delta_r)$ be the factorizable Poisson bialgebra obtained in Theorem~\ref{thm:spfb} arising from $(A, [\ ,\ ]_{A}, \cdot_{A}, \delta, \Delta)$.
Noting that the Poisson algebra structure $(\mathfrak{A}, [\ ,\ ]_\mathfrak{A}, \cdot_\mathfrak{A})$ is exactly the induced Poisson algebra of $(\mathfrak{A}, \cdot_{\mathfrak{A}}, \Phi + \Psi^*)$ (\cite[Remark~5.25]{lin2023differential}) and Eq.~\eqref{eq:vip} holds in $(\mathfrak{A}, \cdot_{\mathfrak{A}}, \Phi+\Psi^{*})$, we have the following conclusion.
\begin{corollary}
	With the conditions as above.
	$(\mathfrak{A}$, $[\ ,\ ]_\mathfrak{A}$, $\cdot_\mathfrak{A}$, $\delta_r$, $\Delta_r)$ is the induced factorizable Poisson bialgebra of the factorizable differential ASI bialgebra $(\mathfrak{A}, \cdot_{\mathfrak{A}}, \Delta_{r}, \Phi + \Psi^*, \Psi + \Phi^*)$.
	In conclusion, we have the following commutative diagram
	\begin{displaymath}
		\xymatrix@C=3cm{ 
			(A, \cdot_A, \Delta, \Phi, \Psi)  \ar@{->}[r]^-{\mathrm{Thm.}~\ref{thm:adfd}} \ar@{->}[d]& (\mathfrak{A}, \cdot_{\mathfrak{A}}, \Delta_{r}, \Phi + \Psi^*, \Psi + \Phi^*) \ar@{->}[d]^-{\mathrm{Thm.}~\ref{thm:dasi2pb}} \\
			(A, [\ ,\ ]_A, \cdot_A,  \delta,\Delta) \ar@{->}[r]^-{\mathrm{Thm.}~\ref{thm:spfb}} & (\mathfrak{A}, [\ ,\ ]_\mathfrak{A}, \cdot_\mathfrak{A}, \delta_r, \Delta_r) 
		}
	\end{displaymath}
\end{corollary}



\begin{proposition}
	Let $(A, \cdot_{A}, \Delta_{r}, \Phi, \Psi)$ be a communicative and cocommutative factorizable differential ASI bialgebra, which corresponds to a symmetric Rota-Baxter differential Frobenius algebra $((A, \cdot_{A}, \Phi), \mathfrak{B}, P)$ of weight  $\lambda \neq 0$.
	Suppose that Eq.~\eqref{eq:vip} holds.
	Let $(A, [\ ,\ ]_{A}, \cdot_{A})$ be the induced Poisson algebra of $(A, \cdot_{A}, \Phi)$.
	Then $((A, [\ ,\ ]_{A}, \cdot_{A}), \mathfrak{B}, P)$ is a quadratic Rota-Baxter Poisson algebra of weight $\lambda$, to which the corresponding factorizable Poisson bialgebra $(A, [\ ,\ ]_{A}, \cdot_{A}, \delta_{r}, \Delta_{r})$ in Theorem~\ref{thm:dasi2pb} corresponds.
	In conclusion, we have the following commutative diagram
	\begin{displaymath}
		\xymatrix@C=2cm{ 
			(A, \cdot_A, \Delta_r, \Phi, \Psi) \ar@{->}[r]^{\mathrm{Thm.}~\ref{thm:dasi2pb}}\ar@{->}[d]^{\mathrm{Thm.}~\ref{thm:fdb2qrp}}&  (A, [\ ,\ ]_A, \cdot_A,  \delta_{r},\Delta_{r}) \ar@{->}[d]^{\mathrm{Thm.}~\ref{thm:fpb2qrp}} \\
			((A, \cdot_{A}, \Phi), \mathfrak{B}, P) \ar@<1.5ex>[u]^{\mathrm{Thm.}~\ref{thm:fdb2qrpx}} \ar@{->}[r] &((A, [\ ,\ ]_A, \cdot_A), \mathfrak{B}, P) \ar@<1.5ex>[u]^{\mathrm{Thm.}~\ref{thm:fpb2qrpx}}}
	\end{displaymath}
\end{proposition}
\begin{proof}
	For all $a, b, c \in A$, we have 
	\begin{align*}
		\mathfrak{B}([a, b]_{A}, c) &= \mathfrak{B}(\partial_{1}(a) \cdot_{A} \partial_{2}(b) - \partial_{2}(a) \cdot_{A} \partial_{1}(b), c) = \mathfrak{B}(a, \eth_{1}(\partial_{2}(b) \cdot_{A} c) - \eth_{2}(\partial_{1}(b) \cdot_{A} c)) \\
		&=\mathfrak{B}(a, \eth_{1}(\partial_{2}(a)) \cdot_{A} b - \partial_{2}(b) \cdot_{A} \partial_{1}(c) - \partial_{1}(a)) \cdot_{A} b + \partial_{1}(b) \cdot_{A} \partial_{2}(c) ) \\
		&= \mathfrak{B}(a, [b, c]_{A}).
	\end{align*} 
	Therefore, $((A, [\ ,\ ]_{A}, \cdot_{A}), \mathfrak{B}, P)$ is a quadratic Rota-Baxter Poisson algebra of weight $\lambda$.
	We have thus proved the proposition.
\end{proof}



