&-\sum_{u \in V(T)}\kappa_{\vec{G}_1}(u,x_{out})w'(u)\sum_{v \in \overline{V}}\kappa_{\vec{G}_1}(x_{out},v)w(v)-\sum_{u \in \overline{V}}\kappa_{\vec{G}_1}(u,x_{in})w(u)\sum_{v \in V(T)}\kappa_{\vec{G}_1}(x_{in},v)w'(v)\\
