       &R(\vec{G_0},w)-R(\vec{G}_1,w)\\
       =&\left(2\sum_{v \in V(G)}{w(v)\choose 2}+\sum_{(u,v) \in P(G)}\kappa_{\vec{G_0}}(u,v)w(u)w(v)\right)\\&-\left(2\sum_{v \in V(G)}{w(v)\choose 2}+\sum_{(u,v) \in P(G)}\kappa_{\vec{G}_1}(u,v)w(u)w(v)\right)\\
       \geq &\sum_{(u,v) \in P_2 \cup P_4}\kappa_{\vec{G_0}}(u,v)w(u)w(v)-\sum_{(u,v) \in P_2 \cup P_4}\kappa_{\vec{G}_1}(u,v)w(u)w(v)\\
