&+\sum_{(u,v) \in P_4}\max\{\kappa_{\vec{G_0}}(u,x_1)\kappa_{\vec{G_0}}(x_1,v),\kappa_{\vec{G_0}}(u,x_2)\kappa_{\vec{G_0}}(x_2,v)\}w(u)w(v)\\ &-\sum_{(u,v) \in P_4}\max\{\kappa_{\vec{G}_1}(u,x_1)\kappa_{\vec{G}_1}(x_1,v),\kappa_{\vec{G}_1}(u,x_2)\kappa_{\vec{G}_1}(x_2,v)\}w(u)w(v)\\
