&+\sum_{(u,v) \in P_4^1}\kappa_{\vec{G_0}}(x_1,v)w(u)w(v)+\sum_{(u,v) \in P_4^2}\kappa_{\vec{G_0}}(x_2,v)w(u)w(v)\\&+\sum_{(u,v) \in P_4^3}\max\{\kappa_{\vec{G_0}}(x_1,v),\kappa_{\vec{G_0}}(x_2,v)\}w(u)w(v)\\&-\sum_{(u,v) \in P_4^1}\kappa_{\vec{G}_1}(x_1,v)w(u)w(v)-\sum_{(u,v) \in P_4^2}\kappa_{\vec{G}_1}(x_2,v)w(u)w(v)\\&-\sum_{(u,v) \in P_4^3}\max\{\kappa_{\vec{G}_1}(x_1,v),\kappa_{\vec{G}_1}(x_2,v)\}w(u)w(v)\\
