\section{Dynamically optimal portfolio selection}\label{S:2}

%=================%
\subsection{Asset prices and admissibility}\label{SS:admissibility}
With \citet*{eberlein.jacod.97,kallsen.00,jakubenas.02,esche.schweizer.05,jeanblanc.al.07,bender.niethammer.08,nutz.12.mafi} we assume (after discounting) there is a risk-free asset with constant value 1 and $d\in\N$ risky assets with cumulative dollar yield $R$. For example, if $S$ denotes the value of the $d$ risky assets such that $S_->0$, the yield is given componentwise by  $R^{(i)} = \int_0^\cdot \frac{\d S^{(i)}_t}{S^{(i)}_{t-}}$. Whereas the cited works take the cumulative yield to be a L\'evy process satisfying $\Delta R>-1$, we shall consider $R$ from the wider class of semimartingales with independent increments and impose no lower bound on $\Delta R$. The assumption of independent increments will be invoked from Subsection~\ref{SS:2.4} onwards.

We sometimes write $L(R)$ for the set of predictable processes that integrate $R$. For $\vartheta\in L(R)$, we often use the shortcut notation $\vartheta\sint R = \int_0^\cdot \vartheta_t\d R_t$. For a  function $g:\R\to\R$ twice continuously differentiable at zero and $\vartheta\in L(R)$, we call 
$$g\circ (\vartheta\sint R) = g'(0)\vartheta\sint R +\frac{1}{2}g''(0)[\vartheta\sint R,\vartheta\sint R]^c + \sum_{t\leq\cdot}\bigs(g(\vartheta_t\Delta R_t)-g'(0)\vartheta_t\Delta R_t\bigs) $$
the $g$-variation of $\vartheta\sint R$. Occasionally, we use the operation ``$\circ$'' with predictable functions, relying on the results in \citet*{cerny.ruf.22.ejp}. We write $\id$ for the identity function, i.e., $\id(x)=x$. We also fix a truncation function $h:\R^d\to\R^d$ given by 
$$h(x) = (x_1\indicator{|x_1|\leq 1},\ldots,x_d\indicator{|x_d|\leq 1})$$
and write  $R[1]=h\circ R$ for the process $R$ with large jumps removed.

For a semimartingale $R$ with independent increments, by \citet*[Proposition~II.2.9 and Theorem~II.4.15]{js.03},
there is a deterministic, right-continuous, non-decreasing process $A$ with left limits such that the characteristics of $R$ are absolutely continuous with respect to $A$ and the resulting differential characteristics $(b^{R[1]},c^R,F^R)$ are deterministic. 
For a specific example of differential characteristics in a bivariate Merton jump-diffusion model, see, e.g., Example~4.3 in \cite{cerny.ruf.21.ejor}. In all It\^o semimartingale models one may choose the activity process $A_t=t$.
Specifying $b^{R[1]}$ rather than $b^R$ allows for the possibility that $R$ does not have a finite mean.

From Subsection~\ref{SS:2.4} onwards, we shall make the following standing assumption, which is weaker than the existence of an equivalent $\sigma$-martingale measure for $R$.%

\begin{assumption}\label{A:instNA_PII}
The yield process $R$  
is \emph{instantaneously arbitrage-free}, i.e., for all $t\in[0,T]$ and all  
$\lambda\in\R^d$ one has that 
\begin{equation}\label{eq:instNA_PII}
\left.
\begin{gathered}
 \left(\lambda c^R_t = 0 \text{ and } \int_{\R^d} \indicator{\lambda x< 0}F^R_t(\d x) = 0\right) \quad \implies \\
\left(\int_{\R^d} \indicator{0<\lambda x}F^R_t(\d x) > 0 \text{ and }
\lambda b^{R[1]}_t-\int_{\R^d}  \lambda h(x) F^R_t(\d x)<0\right)\\
\quad\text{or}\quad \\
\left(\int_{\R^d} \indicator{0<\lambda x}F^R_t(\d x) = 0 \text{ and } \lambda b^{R[1]}_t=0\right).
\end{gathered}
\qquad\right\}
\end{equation}
\end{assumption}
Intuitively, Assumption~\ref{A:instNA_PII} requires that process $\lambda R$ be free to move in both directions (up and down) or else be constant at any moment in time for any $\lambda\in\R^d$. At times $t$ when $R$ jumps with non-zero probability, the above condition is tantamount to the classical one-period no-arbitrage requirement
\begin{equation}\label{eq:NA_t}
\P[\lambda \Delta R_t \geq 0]=1 \Rightarrow \P[\lambda \Delta R_t=0]=1,\qquad \lambda\in\R^d,\ t\in[0,T]. 
\end{equation}
When $\P[\Delta R_t\neq 0]=0$, the definition requires that for each $\lambda\in\R^d$, the differential characteristic triplet of $\lambda R$ taken at $t$ is a triplet of a L\'evy process that is not a subordinator; see \citet*[Lemma~3.5]{kardaras.09}.   

\begin{definition} We say that a trading strategy $\vartheta\in L(R)$ is admissible, writing $\vartheta\in\AdmMMV$, if $\sup_{t\in[0,T]}(\vartheta\sint R_t)^-\in L^2$. We say that $\vartheta\in L(R)$ is mean--variance admissible, if the stricter requirement 
$\sup_{t\in[0,T]}|\vartheta\sint R_t|\in L^2$ holds. For such strategies we write $\vartheta\in\AdmMV$. 
\end{definition}
Observe that $\AdmMMV$ is a cone while $\AdmMV$ is a linear subspace inside $\AdmMMV$. Furthermore, $\AdmMMV$ contains, among others, all strategies whose wealth is bounded below by a constant. For later use we remark that for $\vartheta \in L(R)$ one can write more symmetrically
\begin{align}
\vartheta\in \AdmMMV \iff {}&{}\sup_{t\in[0,T]}|\utilMMV'(\vartheta\sint R_t)|\in L^2,\label{eq:250111.MMV}\\
\vartheta\in \AdmMV \iff {}&{} \sup_{t\in[0,T]}|\utilMV'(\vartheta\sint R_t)|\in L^2.\label{eq:250111.MV}
\end{align}

%=================%
\subsection{First steps}\label{SS:2.2}

For the utility function $\utilMMV$ in \eqref{eq:utilLRT}, consider the optimization problem
\begin{equation}\label{eq:ug}
\uLRT(x)=\sup_{\vartheta \in \AdmMMV}\{\E[\utilMMV(x+\vartheta \sint R_T)]\},\qquad x\in\R.
\end{equation}
Denote an optimal trading strategy in \eqref{eq:ug}, should it exist, by $\aLRT(x)$. Observe that maximization of expected utility is a time-consistent problem.

Recall next the monotone mean--variance utility in \eqref{eq:MMV1} and consider the corresponding optimal portfolio allocation problem 
\begin{equation} \label{eq:vg}
\vLRT(x) = \sup_{\vartheta \in \AdmMMV}\, \{V_{\MMV}(x+\vartheta \sint R_T)\},\qquad x\in\R. 
\end{equation}
The optimal strategy, should it exist, will be denoted $\bLRT(x)$, $x\in\R$. 

We will now recall results from \cite[Theorem~5.1]{cerny.20} that (a) allow $\vLRT(0)$ to be expressed directly in terms of $\uLRT(0)$; (b) identify an optimal trading strategy in \eqref{eq:vg} by means of a time-consistent zero-endowment optimal strategy in \eqref{eq:ug}. The proof is found in Appendix~\ref{appx:A}. The next proposition is model-free in the sense that it works for any semimartingale $R$ (i.e., also without independent increments) and any set of strategies that forms a cone. Furthermore, no assumptions on the absence of arbitrage are needed.  
\begin{proposition}\label{P1}
The following are equivalent.
\begin{enumerate}[(i)]
\item\label{T1.i} $\uLRT(0)<\frac{1}{2}$;
\item\label{T1.ii} $\vLRT(0)<\infty$.
\end{enumerate}
Furthermore, if either of the two conditions holds, then 
\begin{equation}\label{eq:vLRT0}
\vLRT(x) = x+\frac{\left(1-2\uLRT(0)\right)^{-1}-1}{2},\qquad x\in\R,
\end{equation}
and \eqref{eq:vg} admits an optimizer for $x=0$ if and only if \eqref{eq:ug} does so for $x=0$, in which case \eqref{eq:vg} admits an optimizer for each $x\in\R$ and
\begin{equation}\label{eq:bLRT}
\bLRT(x) = \left(1-2\uLRT(0)\right)^{-1}\aLRT(0),\qquad x\in\R.
\end{equation}
\end{proposition}
\begin{remark}
By \citet*[Eq. (17)]{cerny.20}, the quantity $2\vLRT(0)$ is the square of the maximal monotone Sharpe ratio available by trading in $\AdmMMV$ with zero endowment. 
If the optimal strategy exists, the Sharpe  ratio of the truncated wealth $(\aLRT(0)\sint R_T) \wedge 1$ attains the maximal value $\sqrt{2\vLRT(0)}$ and $(\aLRT(0)\sint R_T-1)\vee0$ is the free cash flow stream in the terminology of \citet{cui.al.12}. For more discussion in this direction, see Section~\ref{S:3}. 
\end{remark}

%=================% 
\subsection{Parametrization of trading strategies}\label{SS:2.3}
The economic theory of risk aversion suggests a useful parametrization of monotone mean--variance trading rules. Consider some trading strategy $\alpha\in L(R)$ with wealth process $W=\alpha\sint R$. Observe that in the expected utility problem \eqref{eq:ug}, it is optimal \emph{not to} invest in the risky assets whenever the associated wealth exceeds the bliss point $1$ of the monotonized quadratic utility function $\utilMMV$. To underscore this point, the local absolute risk tolerance, 
\[
-\frac{\utilMMV'(W_{t-})}{\utilMMV''(W_{t-})}\indicator{\{W_{t-}<1\}}=\left(1 - W_{t-}\right)^+=\utilMMV'(W_{t-}),
\] 
falls towards zero as the wealth $W_{t-}$ approaches the bliss point $1$ from below. It therefore makes sense to parametrize the trading strategy by $\lambda_t$, the dollar amount in the risky assets per unit of local risk tolerance. This then yields wealth dynamics of the form
\begin{equation}\label{eq:210401.1}
	\d W_t = \lambda_t \left(1 - W_{t-}\right)^+ \d R_t
\end{equation}
for the optimal net wealth process, for a suitably chosen predictable $\lambda\in L(R)$. For a fixed $\lambda\in\R^d$, this very much resembles a \emph{constant proportion portfolio insurance} (CPPI) strategy of \citet*{black.perold.92}, except instead of a floor on losses there is a ceiling on gains; the riskiness of the investment is reduced in proportion to the gap (known as \emph{cushion} in the CPPI literature) between the net gain $W$ and the ceiling $1$.

By Lemma~\ref{L:SDE}, the unique solution of the stochastic differential equation \eqref{eq:210401.1} has the property
\begin{equation}\label{eq:210401.2}
\left(1 - W\right)^+=\Exp\left( \left(-1\vee \id\right) \circ (-\lambda\sint R) \right) = \Exp\left( -(\id\wedge1) \circ (\lambda\sint R) \right).
\end{equation}
Here, $\Exp(X)$ denotes the stochastic exponential of a semimartingale $X$. Economically, $\Exp(X)$ describes the value of an investment with initial value $1$, continuously compounded using the stochastic cumulative yield $X$. Intuitively, the process $(\id\wedge1) \circ (\lambda\sint R)$ truncates the jumps of the yield $\lambda\sint R$ at $1$. Combining \eqref{eq:210401.1} and \eqref{eq:210401.2}, the net wealth has the form
$W = \alpha \sint R$, where to each $\lambda\in L(R)$ we have associated the trading strategy (dollar investment in stock)
$
 \alpha = \lambda\Exp\left( -\left(\id\wedge1\right) \circ (\lambda\sint R) \right)_{-}
$.
The next proposition explores these ideas and their converse in detail. The proof is found in Appendix~\ref{appx:B}. This proposition, too, works for $R$ without independent increments.

\begin{proposition}\label{P:lambda to alpha and back}
Suppose $\lambda$ integrates $R$. Then
\begin{equation}\label{eq:alpha}
\alpha = \lambda\Exp\left( -\left(\id\wedge1\right) \circ (\lambda\sint R) \right)_{-}
\end{equation}
integrates $R$ and for the (marginal) utility of the wealth $\alpha\sint R$ one has 
\begin{align}
\utilMMV'(\alpha\sint R) ={}& (1-\alpha\sint R)^+=\Exp\left( -\left(\id\wedge1\right) \circ (\lambda\sint R) \right),\label{eq:Granada241014}\\
\utilMMV(\alpha\sint R) ={}& \dfrac{1-\Exp\bigs(-2\utilMMV\circ (\lambda\sint R)\bigs)}{2}.\label{eq:terminal utility}
\end{align}
Furthermore,
\begin{enumerate}[(a)]
\item\label{20241230.a} the marginal utility $\utilMMV'(\alpha\sint R)=(1-\alpha\sint R)^+$ does not go to zero continuously;
\item\label{20241230.b} $\alpha$ is zero from the first time the marginal utility $\utilMMV'(\alpha\sint R)$ becomes zero.
\end{enumerate}
Conversely, assume that $\alpha$ integrates $R$ and that \ref{20241230.a} and \ref{20241230.b} hold. 
Denote by $\sigma$ the first time $(1-\alpha\sint R)^+$ becomes 0. Then 
\begin{equation}\label{eq:Cierne250101}
 \lambda = \frac{\alpha}{1-\alpha\sint R_-}\indicator{\lc0,\sigma\rc}
\end{equation}
is well defined, it integrates $R$, and \eqref{eq:alpha} holds.
\end{proposition}



%=================% 
\subsection{Optimal dollar investment per unit of local risk tolerance}\label{SS:2.4}
From now on to the end of the paper, we assume that $R$ has independent increments and we invoke the instantaneous no-arbitrage condition in Assumption~\ref{A:instNA_PII}. All proofs of this subsection are found in Appendix~\ref{appx:C}.

For deterministic $\lambda$, we shall now produce an explicit formula for the expected monotone quadratic utility of the strategy $\alpha$ in \eqref{eq:alpha}. 
\begin{proposition}\label{P:Cierne240807}
For a deterministic $\lambda$ that integrates $R$, the following are equivalent.
\begin{enumerate}[(i)]
\item\label{P:Cierne240807.i} The strategy $\alpha$ in \eqref{eq:alpha} has finite expected utility, i.e., $\utilMMV(\alpha\sint R_T)\in L^1$.
\item\label{P:Cierne240807.ii} The realized local utility $\utilMMV \circ (\lambda\sint R)$ is special.
\end{enumerate}
Furthermore, if one of these conditions holds then
\begin{equation}\label{eq:Cierne240808}
\E[\utilMMV(\alpha\sint R_T)] = \frac{1-\Exp\left( b^{-2\utilMMV \circ\mkern1mu (\lambda\sint R)} \sint A\right)_T}{2}<\frac{1}{2}.
\end{equation}
\end{proposition}

\begin{remark} The quantity $\utilMMV\circ (\lambda\sint R)$ appearing on the right-hand side of \eqref{eq:Cierne240808} is the $\utilMMV$-variation of the cumulative yield $\lambda\sint R$. Since the variation is a limit of partial sums with summands of the form $\utilMMV(\lambda\sint R_{t_{n+1}}-\lambda\sint R_{t_n})$ (e.g., \citet*[Th\'eor\`eme~2a]{emery.78}), in Proposition~\ref{P:Cierne240807} we have interpreted this quantity as the \emph{realized local utility} of the strategy $\lambda$.
\end{remark}

A conditional expectation analog of \eqref{eq:Cierne240808} shows that 
\[
\E_t[\utilMMV(\alpha\sint R_T)] = 
\frac{1-(\utilMMV'(\alpha\sint R_t))^2 \Exp\left( \indicator{\rc t,T\rc}b^{-2\utilMMV \circ\mkern1mu (\lambda\sint R)} \sint A\right)_T}{2},
\]
i.e., the conditional expected utility generated by deterministic processes $\lambda$ is a deterministic affine transformation of $\utilMMV(W_t)$, whose local risk tolerance with respect to $W_t$ is therefore yet again $\left(1 - W_t\right)^+$. This strongly indicates that the optimal strategy, should it exist, is generated by a deterministic $\lambda$ and that  
\begin{quote}
the optimal $\lambda$ is obtained by maximizing the predictable $\utilMMV$-variation (i.e., the local expected utility) of the cumulative yield $\lambda\sint R$.
\end{quote}

We shall now examine the calculation of the optimal $\lambda$ in more detail. 
Consider a deterministic $\lambda$ that integrates $R$ and such that the realised local utility $\utilMMV \circ\mkern1mu (\lambda\sint R)$ is special. By composition \cite[Remark~3.19]{cerny.ruf.22.ejp}, one has 
$\utilMMV \circ\mkern1mu (\lambda\sint R) = \utilMMV(\lambda\mkern1mu\id) \circ R$. 
From Lemma~\ref{L:240130} one  obtains an explicit expression for the local expected utility rate 
\begin{equation*}
b^{\utilMMV \circ\mkern1mu (\lambda\sint R)}=  b^{ R[1]}\lambda - \frac{1}{2}\lambda c^{ R}\lambda^\top
+\int \bigs(\utilMMV(\lambda x)-\lambda h(x)\bigs)F^{ R}(\d x),
\end{equation*}
which then enters the expression \eqref{eq:Cierne240808}. 

\begin{definition}
We say that the deterministic function $\locutilMMV:[0,T]\times\R^d\to [-\infty,\infty)$ given by 
\begin{equation}\label{eq:locutil}
 \locutilMMV_t(\lambda) = b_t^{ R[1]}\lambda - \frac{1}{2}\lambda c_t^{ R}\lambda^\top
+\int_{\R^d} \bigs(\utilMMV(\lambda x)-\lambda h(x)\bigs)F_t^{ R}(\d x)
\end{equation}
is the \emph{local expected utility}.
\end{definition} 
Under this assumption, the local expected utility admits a maximizer over $\lambda$ $t$-by-$t$ for all $t$. Observe that $\locutilMMV$ is well defined even if $\lambda$ does not integrate $R$ or if $\utilMMV \circ\mkern1mu (\lambda\sint R)$ fails to be special. 

\begin{proposition}\label{P:Cierne240808}
There is a deterministic predictable process $\lLRT$ such that everywhere on $[0,T]$ one has  
\begin{enumerate}[(1)]
\item\label{Cierne240808.1} $\locutilMMV(\lambda)\leq \locutilMMV(\lLRT)$  for all $\lambda\in\R^d$;
\item\label{Cierne240808.2} $ 0\leq \locutilMMV(\lLRT)<\infty$; 
\item\label{Cierne240808.3} $\int_{\R^d} (\lLRT x)^2\indicator{\lLRT x<0}F^R(\d x) <\infty$ and 
\begin{equation*}
 b^{ R[1]}\lLRT - \lLRT c^{ R}\lLRT^\top
+\int_{\R^d} \bigs(\utilMMV'(\lLRT x)\lLRT x-\lLRT h(x)\bigs)F^{ R}(\d x) = 0.
\end{equation*}
\end{enumerate}
\end{proposition}
\begin{remark}
Proposition~\ref{P:Cierne240808} is novel to the extent that it establishes the existence of a maximizer of a specific local expected utility for a yield process with general independent increments. A precursor to this type of result can be found in \citet*{nutz.12.mafi} for L\'evy processes and \citet*{cerny.al.12} for one-period models. An expression of the form \eqref{eq:locutil} first appeared in \citet*[Definition~3.2]{kallsen.99} under the name ``local utility.''
\end{remark}
\begin{remark}
If the model $R$ admits null strategies, i.e., strategies $\lambda\neq0$ such that $\lambda b^{R[1]}=0$, $\lambda c^R=0$, and $\int_{\R^d}\indicator{\lambda x\neq 0}F^R(\d x)=0$, then trivially $\lLRT$ can be picked in many different ways. But even in the absence of such strategies, $\lLRT$ may not be unique since $\utilMMV$ is not strictly concave. This can be seen already in a one-period model with four atoms (Example~\ref{E:1}). We fix one $\lLRT$ from now on and refer to it as \emph{the locally optimal strategy}. 
\end{remark}
%=================% 
\subsection{Optimal local utility strategy integrates \texorpdfstring{$R$}{R}}\label{SS:2.5}
The aim of this section is to show that if the cumulative local expected utility is finite, then the optimal strategy $\lLRT$ integrates $R$. To the best of our knowledge, this is the first time that a link of this kind has been established in the literature.

One of the key ideas of the proof is to describe the maximal local expected utility $\locutil(\lLRT)$ as the drift rate of the variation $\utilMMV\circ (\lLRT\sint R)$. However, for the variation to be well defined, we first need to know that $\lLRT$ integrates $R$, leaving us with a conundrum how to break out of the circular reasoning. The second difficulty is that, even when granted that $\lLRT$ integrates $R$, we do not know whether $\utilMMV\circ (\lLRT\sint R)$ has a drift rate in the classical sense of being special. 

Our way around the first obstacle is to consider a sequence of strategies $\lLRTn = \lLRT\indicator{|\lLRT|\leq n}$, $n\in\N$. Here 
$|\mkern1mu\cdot\mkern1mu|$ stands for the Euclidean norm. We overcome the second difficulty by assigning a drift rate to processes that are not necessarily special but only $\sigma$-special as described in Appendix~\ref{appx:D}. 
\begin{lemma}\label{L:armistice1}
The process $\utilMMV\circ (\lLRTn\sint R)$ is $\sigma$-special with 
\begin{equation*}
0\leq b^{\utilMMV\circ (\lLRTn\sint R)} =\locutilMMV(\lLRTn)\uparrow \locutilMMV(\lLRT),\qquad n\uparrow \infty.
\end{equation*}
\end{lemma}
\begin{proof}
Proposition~\ref{P:Cierne240808} yields $0\leq \locutilMMV(\lLRTn)\uparrow \locutilMMV(\lLRT)$. Lemma~\ref{L:240130} yields that $\utilMMV\circ (\lLRTn\sint R)$ is $\sigma$-special with $b^{\utilMMV\circ (\lLRTn\sint R)} =\locutilMMV(\lLRTn)$.
\end{proof}
Next, we shall recast integrability of $\lLRT$ in terms of predictable variations. The ability to do so is based on a new result developed for this purpose in Corollary~\ref{C:integrability}.
\begin{lemma}\label{L:armistice2}
The following are equivalent.
\begin{enumerate}[(i)]
\item The optimal local utility strategy $\lLRT$ integrates $R$.
\item One has that 
\begin{equation}\label{eq:London241109}
\lim_{n\uparrow \infty} \left(b^{(\id^2\wedge1)\circ (\lLRTn\sint R)} + \big|b^{\id\mkern1mu\indicator{|\id|\leq1}\circ (\lLRTn\sint R)} \big| \right)
\end{equation}
integrates $A$.
\end{enumerate}
\end{lemma}

With Lemmata~\ref{L:armistice1} and \ref{L:armistice2} in place, we continue by observing  that $\utilMMV$ in \eqref{eq:utilLRT}
is essentially linear--quadratic. Since the optimality of $\lLRT$ ties together the first and second moment of the truncated optimal yield, one obtains with a little bit of effort that both quantities in \eqref{eq:London241109} are controlled by the expected local utility $\locutilMMV(\lLRTn)$. The proofs of the next proposition and theorem are  found in Appendix~\ref{appx:E}.
\begin{proposition}\label{P:London241109}
For the optimal local utility strategy $\lLRT$ we have $b^{\id\mkern1mu\indicator{|\id|\leq1}\circ (\lLRTn\sint R)}\geq0$ and   
\begin{equation}\label{eq:key inequality}
2 b^{\utilMMV\circ (\lLRTn\sint R)}\leq b^{(\id^2\wedge1)\circ (\lLRTn\sint R)} + b^{\id\mkern1mu\indicator{|\id|\leq1}\circ (\lLRTn\sint R)} 
\leq 6 b^{\utilMMV\circ (\lLRTn\sint R)},\qquad n\in\N.
\end{equation}
\end{proposition}

The desired result is now immediate.
\begin{theorem}\label{T2}
The following are equivalent. 
\begin{enumerate}[(i)]
\item\label{T2.i} The cumulative maximal local expected utility is finite, i.e., 
\begin{equation*}
 \int_0^T \locutilMMV_t(\lLRT_t) \d A_t<\infty.
\end{equation*}
\item\label{T2.ii} The strategy $\lLRT$ integrates $R$.
\end{enumerate}
Furthermore, if one of these conditions holds, then the realized local utility $\utilMMV\circ (\lLRT\sint R)$ as well as the processes $(\id\wedge1)\circ (\lLRT\sint R)$ and  $(\id\wedge1)^2\circ (\lLRT\sint R)$ are special with
\begin{equation}\label{eq:Granada241018.2}
 2\locutilMMV(\lLRT)\sint A = B^{2\utilMMV\circ (\lLRT\sint R)}=B^{(\id\wedge1)\circ (\lLRT\sint R)}=B^{(\id\wedge1)^2\circ (\lLRT\sint R)} .
\end{equation}
\end{theorem}

