\subsection{Optimal monotone mean--variance portfolios}\label{SS:2.6}

The next theorem is remarkable in that one does not require an \emph{a priori} existence of an equivalent $\sigma$-martingale measure with square-integrable density or square integrability of the yield process $R$. 

\begin{theorem}\label{T3}
If the cumulative maximal local expected utility is finite, i.e., 
$$ \int_0^T \locutilMMV_t(\lLRT_t) \d A_t< \infty,$$ 
then the maximal monotone mean--variance utility is given by
\begin{equation*}
\vLRT(x) = \sup_{\vartheta \in \AdmMMV}\, \{V_{\MMV}(x+\vartheta \sint R_T)\} 
=x+\dfrac{\Exp\bigs(-2\locutilMMV(\lLRT)\sint A\bigs)_T^{-1}-1}{2}<\infty,\quad x\in\R.
\end{equation*}
Furthermore, the optimal zero-endowment expected monotone quadratic utility strategy reads
\[
\aLRT(0) = \argmax_{\vartheta \in \AdmMMV}\{\E[\utilMMV(\vartheta \sint R_T)]\}
=\lLRT\Exp\bigs( -\left(\id\wedge1\right) \circ (\lLRT\sint R) \bigs)_{-}
\]
and the optimal monotone mean--variance investment strategy equals
\begin{equation*}
\bLRT(x) =\argmax_{\vartheta \in \AdmMMV}\, \{V_{\MMV}(x+\vartheta \sint R_T)\}= (1+2\vLRT(0))\aLRT(0). 
\end{equation*}
\end{theorem}

The complementary case gives rise to near-arbitrage opportunities.
\begin{theorem}\label{T4}
If the cumulative maximal local expected utility is infinite, i.e., 
$$ \int_0^T \locutilMMV_t(\lLRT_t) \d A_t=\infty,$$ 
then there is a sequence of admissible strategies whose negative terminal wealth goes to $0$ in $L^{2}$ and whose positive terminal wealth is greater than or equal to $1$ with probability approaching $1$. Furthermore, there is a sequence of admissible strategies whose monotone mean--variance utility goes to $\infty$, i.e., $\vMMV(0)=\infty$.
\end{theorem}
The proofs of both theorems are found in Appendix~\ref{appx:F}. We also state analogous results for the classical mean--variance preferences. These will be used to illustrate the difference between the classical and monotone mean--variance portfolio allocation in Example~\ref{E:2} and are new to the extent that they do not assume existence of an equivalent martingale measure with square-integrable density or square-integrability of the yield process $R$. 

Recall the mean--variance utility in \eqref{eq:MV1}, the quadratic utility function $\utilMV$ in \eqref{eq:utilMV}, and consider the corresponding optimal portfolio allocation problems 
\begin{align} 
\vMV(x) ={}& \sup_{\vartheta \in \AdmMV}\, \{V_{\MV}(x+\vartheta \sint R_T)\},\qquad x\in\R, \label{eq:vMV}\\
\uMV(x) ={}& \sup_{\vartheta \in \AdmMV}\{\E[\utilMV(x+\vartheta \sint R_T)]\},\qquad x\in\R.    \label{eq:uMV}
\end{align}
Denote the corresponding optimizers, should they exist, by $\bMV(x)$ and $\aMV(x)$, respectively. Observe that the expected utility maximization problem \eqref{eq:uMV} is time consistent. 
\begin{theorem}\label{T:MV}
There is a deterministic process $\lMV$ that maximizes, for each $t\in[0,T]$, the local expected quadratic utility $\locutilMV:[0,T]\times\R^d\to [-\infty,\infty)$ given by 
\begin{equation*}\label{eq:locutilMV}
 \locutilMV_t(\lambda) = b_t^{ R[1]}\lambda - \frac{1}{2}\lambda c_t^{ R}\lambda^\top
+\int_{\R^d} \bigs(\utilMV(\lambda x)-\lambda h(x)\bigs)F_t^{ R}(\d x).
\end{equation*}
We have $\uMV(0)<\frac{1}{2}$ if and only if $\vMV(0)<\infty$ if and only if $\int_0^T \locutilMV_t(\lMV_t)\d A_t<\infty$, in which case $\lMV$ integrates $R$, 
\begin{equation}\label{eq:Metabief250114}
2\locutilMV(\lMV)\sint A = B^{2\utilMV\circ (\lMV\sint R)}=B^{\lMV\sint R}=B^{\id^2\circ (\lMV\sint R)},
\end{equation}
the maximal zero-endowment expected quadratic utility equals 
\[\uMV(0) = \dfrac{1-\Exp\bigs(-2\locutilMV(\lMV)\sint A\bigs)_T}{2}\]
and the corresponding optimal investment strategy reads
\[
\aMV(0) = \argmax_{\vartheta \in \AdmMV}\{\E[\utilMV(\vartheta \sint R_T)]\}
=\lMV\Exp\bigs( -\lMV\sint R \bigs)_{-}.
\] 
Furthermore, the maximal mean--variance utility is then given by
\begin{equation*}
\vMV(x) =x+\dfrac{\Exp\bigs(-2\locutilMV(\lMV)\sint A\bigs)_T^{-1}-1}{2}<\infty,\quad x\in\R,
\end{equation*}
and the optimal mean--variance utility investment strategy equals
\begin{equation*}
\bMV(x) =\argmax_{\vartheta \in \AdmMMV}\, \{V_{\MV}(x+\vartheta \sint R_T)\}= (1+2\vMV(0))\aMV(0). 
\end{equation*}
\end{theorem}
We omit the proof since it is entirely analogous to the proofs of Propositions~\ref{P1} and \ref{P:Cierne240808} and Theorems~\ref{T2}--\ref{T4}, with $\AdmMMV$ in \eqref{eq:250111.MMV} replaced by $\AdmMV$ in \eqref{eq:250111.MV}; Proposition~\ref{P:London241109} replaced by Proposition~\ref{P:Cierne250106}, $\utilMMV'-1=\id\wedge1$ replaced by $\utilMV'-1=\id$, etc.
