\subsection{Duality}\label{SS:2.7}
Since we do not assume square-integrability of the yield process $R$, the appropriate dual concept is that of a separating measure; cf.~\citet*{bellini.frittelli.02}. 
\begin{definition}\label{D:separating}
We say that $\Q\ll\P$ with $\frac{\d\Q}{\d\P}\in L^2(\P)$ is a separating measure if for all $\vartheta\in\AdmMMV$, one has $\vartheta\sint R_T\in L^1(\Q)$  and $\E^{\Q}[\vartheta\sint R_T]\leq0$.
\end{definition}

By standard duality arguments, a separating measure imposes an upper bound on the maximal monotone mean--variance utility. From the  proof of the next proposition, it follows directly that $ \frac{1}{2}\Var\left(\frac{\d\Q}{\d\P}\right)$ is the maximal MMV utility in a complete market with prices determined by $\Q$ for an agent with initial wealth $0$. The proofs of this and other statements of this subsection are found in Appendix~\ref{appx:G}.
\begin{proposition}\label{P:Granada241017}
Any separating measure $\Q$ for $R$ satifies 
$\vLRT(0)\leq \frac{1}{2}\Var\left(\frac{\d\Q}{\d\P}\right)$.
\end{proposition}

The marginal utility of the optimal portfolio now yields the separating measure whose density has the smallest variance. 
\begin{theorem}\label{T5}
Assume that $\vLRT(0)<\infty$. Then the following statements hold.
\begin{enumerate}[(1)]
\item\label{T5.1} The process $\frac{\Exp( -\left(\id\wedge1\right) \circ(\lLRT\sint R))}{\Exp(B^{-\left(\id\wedge1\right) \circ(\lLRT\sint R)})}$ is a well-defined square-integrable martingale.
\item\label{T5.2} The probability measure $\QLRT$ defined by 
\begin{equation*}
 \frac{\d \QLRT}{\d \P} = \frac{\Exp\bigs( -\left(\id\wedge1\right) \circ(\lLRT\sint R) \bigs)_T}{\Exp\bigs(B^{-\left(\id\wedge1\right) \circ(\lLRT\sint R)}\bigs)_T}= \frac{\utilMMV'(\aLRT(0)\sint R_T)}{\E[\utilMMV'(\aLRT(0)\sint R_T)]},
\end{equation*}
is a separating measure.

\item\label{T5.3} The maximal MMV utility in the complete market given by $\QLRT$ equals $\vLRT(0)$, i.e.,
\[\frac{1}{2}\Var\bigg(\frac{\d\QLRT}{\d\P}\bigg)=\vLRT(0).\]  
\item\label{T5.4} The density of $\QLRT$ with respect to $\P$ has the smallest variance among all separating measures and the measure $\QLRT$ is determined uniquely, unlike $\lLRT$.
\item\label{T5.5} $\QLRT$ preserves the independent increments property (resp., the L\'evy property) of the yield process $R$ and, provided $\Delta R>-1$, of the log return process $\log\Exp(R)$. 
\end{enumerate}
\end{theorem}

We next formulate necessary and sufficient conditions for $\QLRT$ to be a martingale measure for $R$. In fact, the correct concept for $R$ with unbounded jumps is a $\sigma$-martingale measure. If this seems too abstract, Proposition~\ref{P:Metabief250115} shows that in the most frequently encountered models the $\sigma$-martingale  property already yields that $\QLRT$ is a martingale measure for $R$. We also provide necessary and sufficient conditions for $\QLRT$ to be equivalent. Observe that $\QLRT$ being equivalent to $\P$ implies absence of arbitrage over trading strategies in $\AdmMMV$ even if $\QLRT$ fails to be a $\sigma$-martingale measure. 

\begin{theorem}\label{T6}
Assuming $\vLRT(0)<\infty$, the following are equivalent.
\begin{enumerate}[(i)]
\item\label{T6.i} $\QLRT$ is a $\sigma$-martingale measure for $R$.
\item\label{T6.ii} $\id\mkern1mu\utilMMV'(\lLRT\mkern1mu\id)\circ R$ is $\sigma$-special and $b^{\id\mkern1mu\utilMMV'(\lLRT\mkern1mu\id)\circ R}=0$, $A$-almost everywhere on $[0,T]$.
\end{enumerate}
Furthermore, $\QLRT$ is equivalent to $\P$ if and only if $\lLRT\Delta R< 1$ holds  $(\P\otimes A)$-almost everywhere. 
\end{theorem}
\noindent Example~\ref{E:4} shows that $\QLRT$ may be equivalent to $\P$ without being a $\sigma$-martingale measure.

\begin{proposition}\label{P:Metabief250115}
Suppose that $\QLRT$ is a $\sigma$-martingale measure for $R$. Then $\vartheta\sint R$ is a $\QLRT$-martingale for every deterministic $\vartheta\in\AdmMMV$. In particular, if the jumps of $R$ are bounded from below, then $R$ is a $\QLRT$-martingale and $\QLRT$ is a martingale measure for $R$.
\end{proposition}

 Recall the optimal local quadratic utility strategy $\lMV$ from Theorem~\ref{T:MV}. The next theorem summarizes results analogous to Theorems~\ref{T5} and \ref{T6} for the classical quadratic utility. For a signed measure $\Q$ and  $W\in L^1(\Q) = L^1(\Q^+)\cap L^1(\Q^-)$, we write $\E^{\Q}[W] = \int W\d\Q^+ -\int W\d\Q^- $. Here $\Q^+$ and $\Q^-$ denote the positive and negative variations of $\Q$, respectively; see \citet[VI.6.6]{rudin.87}.
\begin{theorem}\label{T8}
Suppose $\vMV(0)<\infty$. Then $\Exp\bigs(B^{-\lMV\sint R}\bigs)>0$ and the (signed) measure $\QMV$, given by 
\begin{equation}\label{eq:QMV}
 \frac{\d \QMV}{\d \P} = \frac{\Exp\bigs( -\lMV\sint R \bigs)_T}{\Exp\bigs(B^{-\lMV\sint R}\bigs)_T}
=\frac{\utilMV'(\aMV(0)\sint R_T)}{\E[\utilMV'(\aMV(0)\sint R_T)]},
\end{equation}
is a separating measure over $\AdmMV$ and satisfies $\vMV(0)=\frac{1}{2}\Var(\frac{\d\QMV}{\d\P})$. Furthermore, if $\QMV$ is a probability measure, the following are equivalent.
\begin{enumerate}[(i)]
\item\label{T8.i} $\QMV$ is a $\sigma$-martingale measure for $R$.
\item\label{T8.ii} $\id\mkern1mu\utilMV'(\lMV\mkern1mu\id)\circ R$ is $\sigma$-special and $b^{\id\mkern1mu\utilMV'(\lMV\mkern1mu\id)\circ R}=0$, $A$-almost everywhere on $[0,T]$.
\end{enumerate}
\end{theorem}
 We shall call $\QMV$ the \emph{variance-optimal separating measure} since for square-integrable $R$, the measure $\QMV$ coincides with the variance-optimal martingale measure of \citet{schweizer.96}. We next characterize the circumstances under which the simpler MV optimizer already yields the optimal MMV portfolio.
\begin{theorem}\label{T7}
Suppose $R$ is square integrable and $\vLRT(0)<\infty$. Then $\QLRT$ is a $\sigma$-martingale measure for $R$, $\QMV$ is well defined, and the following are equivalent. 
\begin{enumerate}[(i)]
\item\label{T7.i} $\lMV\Delta R\leq 1$ holds  $(\P\otimes A)$-almost everywhere.
\item\label{T7.ii} $\lLRT=\lMV$ up to a null strategy, i.e., $(\lMV-\lLRT)\sint R=0$.
\item\label{T7.iii} $\QLRT=\QMV$.
\end{enumerate}
\end{theorem}
Example~\ref{E:3} shows the theorem is false without the assumption of square integrability of $R$. 

