\section{First steps}\label{appx:A}
\begin{proof}[Proof of Proposition~\ref{P1}]
To begin with, observe that for $x<1$ the correspondence 
$$\vartheta\mapsto \left(1- x\right)\vartheta $$ 
maps $\AdmMMV$ onto itself by the cone property of $\AdmMMV$. Since we have $1-2\utilMMV = ((1-\id)\vee0)^2$, the expected utility of these two strategies satisfies
$$1-2\E[\utilMMV(x+\left(1- x\right)\vartheta\sint R_T)] 
= (1- x)^{2}\left(1-2\E[\utilMMV(\vartheta\sint R_T)]\right).$$
On taking infima over $\vartheta\in\AdmMMV$, one obtains 
\begin{equation}\label{eq:uLRTx}
1-2\uLRT(x) = (1-x)^{2}\left(1-2\uLRT(0)\right), \qquad x<1,
\end{equation}
and, should an optimal strategy $\aLRT(0)$ exist, also
$$ \aLRT(x) =\left(1-x\right)^+\aLRT(0),\qquad x\in\R.$$

The MMV utility formula \eqref{eq:MMV2} and \eqref{eq:uLRTx} now yield 
\begin{equation}\label{eq:vLRT}
 \vLRT(0) = \sup_{x\in\R}\, \{\uLRT(x)-x\} 
= \left\{\begin{array}{cl} \frac{\left(1-2\uLRT(0)\right)^{-1}-1}{2},&\qquad  \uLRT(0)<\frac{1}{2},\\[1ex]
\infty,&\qquad  \uLRT(0)=\frac{1}{2},
\end{array}\right.
\end{equation}
which shows the equivalence of \ref{T1.i} and \ref{T1.ii}.

For $\uLRT(0)<\frac{1}{2}$, the supremum in \eqref{eq:vLRT} is attained uniquely at  
$$\xLRT= 1-\left(1-2\uLRT(0)\right)^{-1}<1.$$
Thus if \ref{T1.i} or \ref{T1.ii} holds and $\aLRT(0)$ exists, then the optimal zero-endowment risky investment strategy for the divergence preferences is given by 
$$\bLRT(0) = \aLRT(\xLRT)=(1-\xLRT)\aLRT(0)=\left(1-2\uLRT(0)\right)^{-1}\aLRT(0).$$ 
The translation invariance of MMV utility now yields \eqref{eq:vLRT0} and \eqref{eq:bLRT}.

Conversely, suppose \ref{T1.i} or \ref{T1.ii} holds and a MMV optimizer $\bLRT(0)\in\AdmMMV$ exists. Then from \eqref{eq:MMV2}, there is $\hat \eta$ such that $\vLRT(0) = \E[\utilMMV(\bLRT(0)\sint R_T-\hat\eta)]+\hat\eta$, hence we may take $\aLRT(-\hat\eta)=\bLRT(0)$. Optimality (i.e., $\vLRT(0)\geq0$) and the upper bound $\utilMMV\leq \frac{1}{2}$ gives $\hat\eta\geq -\frac{1}{2}$. The first part of the proof now yields that we may take $\aLRT(0) = \frac{\aLRT(-\hat\eta)}{1+\hat\eta} = \frac{\bLRT(0)}{1+\hat\eta}$. 
\end{proof}

