\begin{proof}[Proof of Proposition~\ref{P:lambda to alpha and back}]
Observe that $\utilMMV$ and $\utilMMV'-1= -(\id\wedge1)$ are universal representing functions in the sense of \cite[Definition~3.4]{cerny.ruf.22.ejp}. 
We have that $\alpha$ integrates $R$ because $\lambda$ integrates $R$ and $\Exp\left( -\left(\id\wedge1\right) \circ (\lambda\sint R) \right)_{-}$ is locally bounded. Next, we have
\begin{equation*}
 \alpha  = \lambda\Exp\left( -\left(\id\wedge1\right) \circ (\lambda\sint R) \right)_{-} = \lambda\Exp\left( \left(-1\vee \id\right) \circ (-\lambda\sint R) \right) _{-},
\end{equation*}
by composition.  Observe that $\utilMMV' = (1-\id)^+ = 1-\id\wedge1$. Lemma~\ref{L:SDE} with $X=-\lambda\sint R$ now gives 
\begin{equation}\label{eq:Grana240513}
\begin{split}
\utilMMV'(\alpha\sint R) ={}& (1-\alpha\sint R)^+ 
= (1-\lambda\Exp\left( \left(-1\vee \id\right) \circ (-\lambda\sint R) \right) _{-}\sint R)^+
\\
={}& \Exp\left( \left(-1\vee \id\right) \circ (-\lambda\sint R) \right) 
=\Exp\left( -\left(\id\wedge1\right) \circ (\lambda\sint R) \right),
\end{split}
\end{equation}
which yields \eqref{eq:Granada241014}, \ref{20241230.a}, and \ref{20241230.b}. 
Since $2\utilMMV =1-(1-\id\wedge1)^2=1-(\utilMMV')^2$, the utility of wealth reads
\begin{equation}\label{eq:230714}
\begin{split}
\utilMMV(\alpha\sint R) 
={}& \frac{1- \Exp\left( -\left(\id\wedge1\right) \circ (\lambda\sint R) \right) ^2}{2}\\
={}&\frac{1-\Exp\big( \big(\left(1-\id\wedge1\right)^{2}-1\big) \circ (\lambda\sint R) \big)}{2},
\end{split}
\end{equation}
where the first equality follows from \eqref{eq:Grana240513} and the second  from \cite[Proposition~4.3 and Corollary~3.20]{cerny.ruf.22.ejp}. The explicit form of $\utilMMV$ now yields \eqref{eq:terminal utility}.

To show the converse statement, \ref{20241230.a} yields that $\lambda$ is well defined and integrates $R$. By associativity of stochastic integrals, on $\lc0,\sigma\rc$ one has 
$$1-\alpha\sint R = 1+\left(1-\alpha\sint R_-\right)\sint (-\lambda\sint R) = \Exp\left(-\lambda\sint R\right).$$
This and \eqref{eq:Cierne250101} gives 
\[ \alpha\indicator{\lc0,\sigma\rc} = \lambda (1-\alpha\sint R_-)\indicator{\lc0,\sigma\rc} = \Exp\left(-\lambda\sint R\right)_-\indicator{\lc0,\sigma\rc} = \lambda \Exp\left( -\left(\id\wedge1\right) \circ (\lambda\sint R) \right)_{-}\] 
and \ref{20241230.b} yields \eqref{eq:alpha}.
\end{proof}

