\section{Local utility maximization}\label{appx:C}
\begin{proof}[Proof of Proposition~\ref{P:Cierne240807}]
For deterministic $\lambda$, the realized local utility has independent increments by \citet*[Proposition~2.15]{cerny.ruf.23.spa}. Observe further that $2\utilMMV(\lambda\Delta R_t)\leq \max_{x\in\R}2\utilMMV(x)=1$ for all $t\in[0,T]$ and that $\P[2\utilMMV(\lambda\Delta R_t)= 1]=1$ only if there is instantaneous arbitrage at time $t$, i.e., $\P[\lambda\Delta R_t\geq 1] = 1$. 
In view of \eqref{eq:NA_t}, we therefore have $\P[2\utilMMV(\lambda\Delta R_t)= 1]<1$ and hence $\E\left[-2\utilMMV(\lambda\Delta R_t)\right]>-1$, for all $t\in [0,T]$. Identity \eqref{eq:terminal utility} and  \citet*[Theorem~4.1]{cerny.ruf.23.spa} with $Y=-2\utilMMV(\lambda\,\id) \circ R$ now yield the equivalence of \ref{P:Cierne240807.i} and \ref{P:Cierne240807.ii} as well as \eqref{eq:Cierne240808}.
\end{proof}

\begin{proof}[Proof of Proposition~\ref{P:Cierne240808}]
\noindent Step 1: We claim that the local expected utility  $\locutilMMV$ given by
\begin{equation*}
\locutil(\lambda)=  b^{ R[1]}\lambda - \frac{1}{2}\lambda c^{ R}\lambda^\top
+\int_{\R^d} \left(\utilMMV(\lambda x)-\lambda h(x)\right)F^{ R}(\d x),\qquad \lambda\in\R^d,
\end{equation*}
is a ``normal integrand'' on $[0,T]\times \R^d$ in the sense of \citet[Definition~14.27]{rockafellar.wets.98}. Indeed, 
\[
(t,\lambda)\mapsto \left(b_t^{ R[1]}+\int_{\R^d}(x\indicator{|x|\leq1}-h(x))F_t^X(\d x)\right)\lambda - \frac{1}{2}\lambda c_t^{ R}\lambda^\top
\] 
is a normal integrand by \cite[Example~14.29]{rockafellar.wets.98}. Furthermore, we have 
\[ \utilMMV(\lambda x)-\lambda x\indicator{|x|\leq1}\leq \frac{1}{2}\indicator{|x|>1}\leq |x|^2\wedge1,\qquad  (x,\lambda)\in\R^d\times\R^d,\]
$t\mapsto (|\id|^2\wedge1) F_t^R$ is a finite transition kernel from $([0,T],\mathcal{B}([0,T]))$ to $(\R^d,\mathcal{B}(\R^d))$, and   
\[(x,\lambda)\mapsto\frac{\utilMMV(\lambda x)-\lambda x\indicator{|x|\leq1}}{|x|^2\wedge1}\indicator{x\neq0},\] 
being measurable in $x$ and continuous in $\lambda$, is a normal integrand on $\R^d \times \R^d$ by \cite[Example~14.29]{rockafellar.wets.98}. By \citet[Lemma~2.55 and Theorem~1.20.4]{pennanen.perkkio.24}, 
\[
(t,\lambda)\mapsto \int_{\R^d} \left(\utilMMV(\lambda x)-\lambda h(x)\right)F_t^{ R}(\d x)
=\int_{\R^d} \frac{\utilMMV(\lambda x)-\lambda h(x)}{|x|^2\wedge1}\indicator{x\neq0}(|x|^2\wedge1)F_t^{ R}(\d x) 
\]
is a normal integrand on $[0,T]\times \R^d$, which establishes the claim.\medskip

\noindent Step 2: We claim that $\lambda\mapsto \locutilMMV_t(\lambda)$ has a maximizer for every $t\in[0,T]$.
Fix $\lambda\in\R^d$. To simplify the notation, observe that by \citet*[Corollary~5.8]{cerny.ruf.22.ejp} and Lemma~\ref{L:241001} one has
\begin{align*}
b^{(\lambda R)[1]}&{} =   b^{ R[1]}\lambda +\int_{\R^d} \left(\lambda x\indicator{|\lambda x|\leq 1}-\lambda h(x)\right)F^{ R}(\d x),\\
c^{\lambda R}   &{}   =  \lambda c^R\lambda^\top,\\
F^{\lambda R} &{} \text{ is the image measure of $F^R$ via the mapping $\lambda\mkern2mu \id$}.
\end{align*}
This yields
\[ \locutil(\lambda y) = b^{(\lambda R)[1]}y-\frac{1}{2}c^{\lambda R}y^2 + \int_{\R} (\utilMMV(xy)-xy\indicator{|x|\leq1})F^{\lambda R}(\d x), \quad y\in\R.\]

We shall now examine the behaviour of $\psi(y) = \locutil(\lambda y)$ for $y>0$ in a number of mutually exclusive subcases.
\begin{enumerate}[(a)]
\item\label{240930.a} For $c^{\lambda R}>0$ or $F^{\lambda R}(\R_-)>0$, Lemma~\ref{L:230717} yields $\lim_{y\to\infty}\frac{\psi(y)}{y}=-\infty$.
\item\label{240930.b} The case $c^{\lambda R}=0$ and $F^{\lambda R}(\R_-)=0$ admits two subcases as per condition \eqref{eq:instNA_PII}.  
\begin{enumerate}[(i)] 
\item\label{240930.bi} Either $F^{\lambda R}(\R_+)>0$ and $b^{(\lambda R)[1]} - \int_{\R} x\indicator{|x|\leq 1}F^{\lambda R}(\d x)<0$, yielding $\lim_{y\to\infty}\frac{\psi(y)}{y} <0$ by Lemma~\ref{L:230717}; or
\item\label{240930.bii} $F^{\lambda R}(\R_+)=0$ and $b^{(\lambda R)[1]}=0$, in which case $\psi(y)=0$ for all $y\in\R$. 
\end{enumerate}
\end{enumerate}
For each fixed $\lambda$ and all $t\in[0,T]$, we therefore have either $\lim_{y\to\infty} \frac{\locutil_t(\lambda y)}{y}<0$, which yields  $\lim_{y\to\infty} \locutil_t(\lambda y) = -\infty$, or $\locutil_t(\lambda y)=0$ for all $y\in\R$. By \citet*[Theorem~27.3]{rockafellar.70}, the function $\locutil_t$ attains its maximum in $\R^d$ for all $t\in[0,T]$.\medskip 

\noindent Step 3: By \citet[Theorem~14.37]{rockafellar.wets.98}, measurable selection applied to the normal integrand $\locutilMMV$ establishes \ref{Cierne240808.1}. 
By optimality, $0=\locutilMMV(0)\leq\locutilMMV(\lLRT)$. Since $\utilMMV$ is bounded from above, we have $\locutilMMV(\lLRT)<\infty$, yielding \ref{Cierne240808.2}.  
The first claim in \ref{Cierne240808.3} follows from $0\leq\locutilMMV(\lLRT)$ together with the inequality 
\[-\id^2\indicator{\id\leq-2}\leq \utilMMV\indicator{\id\leq-2}\leq-\frac{1}{2}\id^2\indicator{\id\leq-2}. \] 
Then $\psi$ given by $\psi(y) = \locutil(\lLRT y)$ for $y\geq 0$ is finite-valued and differentiable on $(0,\infty)$. By optimality of $\lLRT$, $\psi$ attains it maximum at $1$, hence $\psi'(1)=0$. Differentiation under the integral sign completes the proof.
\end{proof}



