\section{\texorpdfstring{$\sigma$}{Sigma}-special processes and semimartingale characteristics}\label{appx:D}
With \citet*{js.03}, we write $(b^{X[1]},c^X,F^X,A)$ for the characteristic triplet of some $\R^d$-valued semimartingale $X$ relative to some activity process $A$. Here $X[1] = \id\indicator{|\id|\leq 1}\circ X$ is the process $X$ with jumps larger than 1 in absolute value removed. The process $X[1]$ is special and its predictable compensator is precisely $B^{X[1]}= b^{X[1]}\sint A$. Furthermore, for special $X$ one clearly has 
\begin{equation}\label{eq:bX}
b^X = b^{X[1]} + \int_{\R^d} x\indicator{|x|>1}F^X(\d x).
\end{equation} 
\begin{definition}
We say that a semimartingale $X$ is $\sigma$-special if there is a sequence of predictable sets $\{D_n\}_{n\in\N}$ increasing to $\Omega\times [0,\infty)$ such that $\indicator{D_{n}}\sint X$ is special for all $n\in\N$. 
\end{definition}
By \citet*[Lemma~3.2]{kallsen.04}, $X$ is $\sigma$-special if and only if $\int_{\R^d} |x|\indicator{|x|>1}F^X(\d x)$ is finite $(\P\otimes A)$-almost everywhere and $X$ is special if and only if $\int_{\R^d} |x|\indicator{|x|>1}F^X(\d x)$ integrates $A$. This motivates the following proposition.


\begin{proposition}\label{P:sigma-special}
If a semimartingale $X$ is $\sigma$-special, then $b^X$ is well defined by \eqref{eq:bX}. Furthermore, for any predictable set $D$ such that $\indicator{D}\sint X$ is special, we have $b^X\indicator{D}\in L(A)$ and
$ B^{\indicator{D}\sint X} = (b^{X}\indicator{D})\sint A$.
\end{proposition}


\begin{proof}
The right-hand side of \eqref{eq:bX} is well defined by \citet*[Lemma~3.2]{kallsen.04}. Observe that
\begin{align*}
B^{\indicator{D}\sint X} ={}& b^{\indicator{D}\sint X}\sint A = \left( b^{(\indicator{D}\sint X)[1]} + \int_{\R^d} x\indicator{|x|>1}F^{\indicator{D}\sint X}(\d x)\right)\sint A\\
={}&\left( b^{X[1]}\indicator{D} + \int_{\R^d} x\indicator{|x|>1}\indicator{D}F^{X}(\d x)\right)\sint A,
\end{align*}
yielding the statement.
\end{proof}

Our aim is to provide a systematic way of computing compensators of $\sigma$-special semimartingales obtained from certain representations that one can loosely think of as variations. To this end we first introduce a (sub)class of predictable functions that is sufficiently general for our purposes.
\begin{definition}
Let $\tI^{n}(X)$ denote the set of all predictable functions $\xi: [0,\infty)\times\Omega\times\R^d \rightarrow \R^n$  such that the following properties hold.
	\begin{enumerate}[label={\rm(\arabic{*})}, ref={\rm(\arabic{*})}]
		\item\label{D_I(X):2}  $\xi(0) = 0$.
		\item\label{D_I(X):3} $x \mapsto \xi(x)$ is twice differentiable at zero.
		\item\label{D_I(X):4} $D \xi(0) \in L(X)$.
		\item\label{D_I(X):5} $D^2 \xi(0) \in L([X,X]^c)$.
		\item\label{D_I(X):6} $(\xi -   D  \xi(0) \, \id) \in L(\mu^{{X}})$.
	\end{enumerate}
We write $\tI(X)=\bigcup_{n\in\N}\tI^n(X)$ and for $\xi\in\tI(X)$ we define 
\begin{equation}\label{eq:circ tI}
\xi\circ X =  D\xi(0)\sint X + \frac{1}{2}D^2\xi(0)\sint [X,X]^c + (\xi - D\xi(0)\id)*\mu^X.
\end{equation}
\end{definition}

The following proposition provides sufficient conditions for a composition of functions in $\tI$ to remain in $\tI$. For a proof see \cite[Theorem~3.18]{cerny.ruf.22.ejp}.
\begin{proposition}\label{P:composition}
	Let $\xi \in \tI(X)$. Moreover, fix $\psi \in \tI(\xi\circ X)$ such that $D\psi(0)$ is locally bounded.
		Then $\psi(\xi) \in \tI(X)$ and we have $\psi \circ (\xi \circ X) = \psi(\xi) \circ X$.
\end{proposition}

\begin{remark}\label{L:241001}
In \cite{cerny.ruf.22.ejp}, the $\circ$ operation is defined for predictable functions from a wider class $\I(X)\supset \tI(X)$. Observe that the two definitions are consistent on $\tI(X)$. Indeed, by \cite[Definition~3.8]{cerny.ruf.22.ejp}, for $\R^d$-valued $X$ and $\R$-valued $\xi\in\I(X)$ one has
\begin{equation}\label{eq:FlightToBA241229}
\xi\circ X =  \indicator{\mathcal{H}_X}D\xi(0)\sint X + \frac{1}{2}D^2\xi(0)\sint [X,X]^c 
+ (\xi - \indicator{\mathcal{H}_X}D\xi(0)\id)\star \mu^X.
\end{equation}
where $\mathcal{H}_X=\{\nu^X(\{\cdot\})=0\}$ and $\star$ is the $\sigma$-localised form of the finite variation jump integral $*$. We further have $\indicator{\mathcal{H}_X^c}\id \in L_\sigma(\mu^X)$ by \cite[Proposition~3.8]{cerny.ruf.21.bej}. From this and $\indicator{\mathcal{H}_X^c}D\xi(0)\in L(X)$, we obtain $\indicator{\mathcal{H}_X^c}D\xi(0)\id\in L_\sigma(\mu^X)$ and $\indicator{\mathcal{H}_X^c}D\xi(0)\sint X = \indicator{\mathcal{H}_X^c}D\xi(0)\id\star\mu^X$ by \cite[Proposition~3.9]{cerny.ruf.21.bej}. The consistency of the two definitions now follows from \eqref{eq:FlightToBA241229}.
\end{remark}


\begin{lemma}\label{L:240130}
For an $\R^d$-valued semimartingale $X$ and a predictable $\R$-valued function $\xi\in\tI(X)$, the following are equivalent.
\begin{enumerate}[(i)]
\item\label{L:240130.i} $\xi\circ X$ is $\sigma$-special;
\item\label{L:240130.ii} $\int_{\R^d} |\xi(x)|\indicator{|\xi(x)|>1}F^X(\d x)$ is finite $(\P\otimes A)$-almost everywhere.
\end{enumerate}

Furthermore, if either of the two conditions holds, then  
\begin{equation*}
b^{\xi\circ X} = D\xi(0)b^{X[1]}+\frac{1}{2}\mathrm{trace} \big(D^2\xi(0)c^{X}\big) + \int_{\R^d} \left(\xi(x)-D\xi(0)h(x)\right)F^X(\d x)
\end{equation*}
and $\xi\circ X$ is special if and only if $\int_{\R^d} |\xi(x)|\indicator{|\xi(x)|>1}F^X(\d x)$ integrates $A$.
\end{lemma} 

\begin{proof}
Observe that $F^{\xi\circ X}$ is the push-forward measure of $F^X$ via the mapping $\xi$ (\cite[Corollary~5.8]{cerny.ruf.22.ejp}), hence $\int_{\R} |y|\indicator{|y|>1}F^{\xi\circ X}(\d y) = \int_{\R^d} |\xi(x)|\indicator{|\xi(x)|>1}F^X(\d x)$. The equivalence between \ref{L:240130.i} and \ref{L:240130.ii} as well as the  equivalence in the last claim now follow from \citet*[Lemma~3.2]{kallsen.04}. 
To argue the formula for $b^{\xi\circ X}$, assume that $\xi\circ X$ is $\sigma$-special. By definition, we have $b^{\xi\circ X} = b^{(\xi\circ X)[1]}+\int_{\R} y\indicator{|y|>1}F^{\xi\circ X}(\d y)$. Observe that $X-X[1]$ has finitely many jumps on compacts, hence $D\xi(0)\in L(X[1])$. The \'Emery formula \eqref{eq:circ tI} now yields
\[
(\xi\circ X)[1] =  D\xi(0)\sint X[1] + \frac{1}{2}D^2\xi(0)\sint [X,X]^c + (\xi\indicator{|\xi|\leq1} - D\xi(0)h) * \mu^X,
\] 
whereby one obtains by $\sigma$-localisation that
$$ b^{(\xi\circ X)[1]} = D\xi(0)b^{X[1]}+\frac{1}{2}\mathrm{trace} \big(D^2\xi(0)c^{X}\big) 
+ \int_{\R^d} \left(\xi(x)\indicator{|\xi(x)|\leq1}-D\xi(0)h(x)\right)F^X(\d x).$$
By image measure properties, $\int_{\R} y\indicator{|y|>1}F^{\xi\circ X}(\d y) = \int_{\R^d} \xi(x)\indicator{|\xi(x)|>1}F^X(\d x)$, which completes the proof of the drift formula. 
\end{proof}

We next formulate drift computation under an absolutely continuous change of measure, which will be used in the proof of Theorem~\ref{T6}.

\begin{lemma}\label{L:Metabief250115}
Let $Y$ be special such that $\Delta Y\geq -1$, $\Delta B^Y>-1$ and $M=\Exp(Y)/\Exp(B^Y)$ is a uniformly integrable martingale. Define $\Q$ by $\d\Q/\d\P=M_\infty$. For a $\P$--semimartingale $U$, the following are equivalent. 
\begin{enumerate}[(i)]
\item\label{T:Girsanov:i} $U$ is $\Q$-$\sigma$-special.
\item\label{T:Girsanov:ii} $U +  [U , Y]$ is $\P$-$\sigma$-special on the stochastic interval $M_->0$.
\end{enumerate}
If one of these conditions holds, then one has
\begin{equation} \label{eq:200610} 
b^{U,\Q} = \frac{b^{U +  [U , Y]}}{1+ \Delta B^{Y}}  \qquad \text{on the stochastic interval $M_->0$}.
\end{equation}
\end{lemma}
\begin{proof}
Fix a predictable set $D$ and apply \cite[Theorem~5.4]{cerny.ruf.23.spa} with $Z = \Exp(Y)$ and $V=\indicator{D}\sint U$, observing that $\Log(Z)=Y$ on the stochastic interval $M_->0$. The identity $\indicator{D}\sint(U+[U,Y])=V+[V,Y]$ yields the equivalence between \ref{T:Girsanov:i} and \ref{T:Girsanov:ii}. Suppose now \ref{T:Girsanov:i} or \ref{T:Girsanov:ii} holds and let $D$ belong to the corresponding $\sigma$-localising sequence. \cite[Theorem~5.4]{cerny.ruf.23.spa} then yields 
\[ 
\indicator{D}b^{U,\Q} = b^{V,\Q} = \frac{b^{V +  [V , Y]}}{1+ \Delta B^{Y}} = \frac{\indicator{D}b^{U +  [U , Y]}}{1+ \Delta B^{Y}}
\qquad \text{on the stochastic interval $M_->0$,}
\]
which completes the proof.
\end{proof}



