\section{Optimal local utility strategy integrates \texorpdfstring{$R$}{R}}\label{appx:E}

\begin{proof}[Proof of Proposition~\ref{P:London241109}]
Fix $n\in\N$. Item~\ref{Cierne240808.3} of Proposition~\ref{P:Cierne240808} and Lemma~\ref{L:240130} yield that 
$(\id\wedge1)\circ (\lLRTn\sint R)$ and $(\id\wedge1)^2\circ (\lLRTn\sint R)$ are $\sigma$-special with 
$b^{(\id\wedge1)\circ (\lLRTn\sint R)} = b^{(\id\wedge1)^2\circ (\lLRTn\sint R)}$, which in view of \eqref{eq:utilLRT} gives 
\begin{equation}\label{eq:241007.2}
2b^{\utilMMV\circ (\lLRTn\sint R)} = b^{(\id\wedge1)\circ (\lLRTn\sint R)} 
=  b^{(\id\wedge1)^2\circ (\lLRTn\sint R)}
\end{equation}
and also
\begin{equation}\label{eq:Cierne250104}
b^{\id\indicator{\id\leq1}\circ (\lLRTn\sint R)} = b^{(\id^2\indicator{\id\leq1})\circ (\lLRTn\sint R)}\geq0.
\end{equation}
The latter yields the first claim. 

The easy inequalities
$0\leq -\id \indicator{\id<-1}\leq \id^2 \indicator{\id<-1}\leq (\id\wedge1)^2$
give 
$
0\leq -b^{\id\indicator{\id< -1}\circ (\lLRTn\sint R)}  \leq  b^{(\id\wedge1)^2\circ (\lLRTn\sint R)},
$
while \eqref{eq:Cierne250104} can be rephrased as 
\[
0\leq b^{\id\indicator{|\id|\leq1}\circ (\lLRTn\sint R)}
= b^{\indicator{\id\leq 1}\id^2\circ (\lLRTn\sint R)}-b^{\id\indicator{\id< -1}\circ (\lLRTn\sint R)} .
\]
Combining the two, one has 
$ 
0\leq b^{\id\indicator{|\id|\leq1}\circ (\lLRTn\sint R)}\leq 2 b^{(\id\wedge1)^2\circ (\lLRTn\sint R)}.
$
In view of $b^{(\id^2\wedge1)\circ (\lLRTn\sint R)}\leq b^{(\id\wedge1)^2\circ (\lLRTn\sint R)}$ and \eqref{eq:241007.2}, the proof of the second inequality in \eqref{eq:key inequality} is complete.
On the other hand, we have
\[
2b^{\utilMMV\circ (\lLRTn\sint R)} ={} b^{(\id\wedge1)\circ (\lLRTn\sint R)}
\leq {} b^{\id\indicator{|\id|\leq1}\circ (\lLRTn\sint R)} + b^{\indicator{\id>1}\circ (\lLRTn\sint R)}
\]
and the first inequality in \eqref{eq:key inequality} follows easily.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{T2}]
Lemmata~\ref{L:armistice1} and \ref{L:armistice2} with Proposition~\ref{P:London241109} yield the equivalence of \ref{T2.i} and \ref{T2.ii}. 
Item~\ref{Cierne240808.3} of Proposition~\ref{P:Cierne240808} and Lemma~\ref{L:240130} yield that 
$(\id\wedge1)\circ (\lLRT\sint R)$ and $(\id\wedge1)^2\circ (\lLRT\sint R)$ are $\sigma$-special with 
$b^{(\id\wedge1)\circ (\lLRT\sint R)} = b^{(\id\wedge1)^2\circ (\lLRT\sint R)}$,
which in view of \eqref{eq:utilLRT} gives
\begin{equation}\label{eq:Cierne250104b}
 2\locutilMMV(\lLRT) = 2b^{\utilMMV\circ (\lLRT\sint R)} = b^{(\id\wedge1)\circ (\lLRT\sint R)} =  b^{(\id\wedge1)^2\circ (\lLRT\sint R)}.
\end{equation}
Since
$
|\utilMMV|\indicator{|\utilMMV|> 1} \leq 2\mkern2mu\id^2\indicator{\id\leq0}\leq 2 (\id\wedge1)^2,
$
and 
$b^{(\id\wedge1)^2\circ (\lLRT\sint R)}= 2b^{\utilMMV\circ (\lLRT\sint R)}$, 
 one has that 
\[
b^{|\utilMMV|\indicator{|\utilMMV|>1}\circ (\lLRT\sint R)}\leq 2 b^{(\id\wedge1)^2\circ (\lLRT\sint R)}
= 4b^{\utilMMV\circ (\lLRT\sint R)}=4\locutilMMV(\lLRT)
\] 
integrates $A$. Lemma~\ref{L:240130} now yields that $\utilMMV\circ (\lLRT\sint R)$ is special. The proof that $(\id\wedge1)\circ (\lLRT\sint R)$ and  $(\id\wedge1)^2\circ (\lLRT\sint R)$ are special is analogous. The last assertion of the theorem now follows from the identity \eqref{eq:Cierne250104b}.
\end{proof}

