\section{Optimal monotone mean--variance portfolios}\label{appx:F}
\begin{proof}[Proof of Theorem~\ref{T3}]
Let 
\begin{equation}\label{eq:a(0)}
\aLRT(0) = \lLRT\Exp\bigs( -\left(\id\wedge1\right) \circ (\lLRT\sint R) \bigs)_{-}.
\end{equation}
Then by Theorem~\ref{T2} and Proposition~\ref{P:lambda to alpha and back},  $\aLRT(0)$ integrates $R$. By Proposition~\ref{P:Cierne240807}, one has $\utilMMV(\aLRT(0)\sint R_T)\in L^1$, and  
\begin{equation}\label{eq:a(0) utility}
\E[\utilMMV(\aLRT(0)\sint R_T)] = \dfrac{1-\Exp\bigs(-2B^{\utilMMV \circ  (\lLRT\sint R)}\bigs)_T}{2}<\frac{1}{2}.
\end{equation}

We shall now show that $\aLRT(0)$ is admissible. Since $\utilMMV(\aLRT(0)\sint R_T)\in L^1$ and $(\utilMMV')^2=1-2\utilMMV$, Proposition~\ref{P:lambda to alpha and back} gives 
\[
\utilMMV'(\aLRT(0)\sint R_T)=\Exp(U)_T\in L^2
\]
with $U=-\left(\id\wedge1\right) \circ (\lLRT\sint R) = (\utilMMV'-1)\circ (\lLRT\sint R)$. We claim $\Delta B^U>-1$.
Indeed, the first-order conditions for $\lLRT$ in \eqref{eq:Granada241018.2} give
\[-\Delta B^U_t = \E[-\Delta U_t] = \E[(\Delta U_t)^2], \]
and $\Var(\Delta U_t)\geq0$ yields  $\Delta B^U_t\geq -1$, with $\Delta B^U_t = -1$ if and only if $\Delta U_t = -1$. The latter is ruled out by the absence of instantaneous arbitrage, which proves $\Delta B^U>-1$. \citet*[Theorem~4.1]{cerny.ruf.23.spa} now yields that $U$ is special, hence $\Exp(B^U)>0$. The multiplicatively compensated process $\frac{\Exp(U)}{\Exp(B^U)}$ is then a (square-integrable) martingale by \cite[Theorems~1.2~and~4.1]{cerny.ruf.23.spa}. In view of $\Exp(B^U)>0$, the Doob inequality yields 
\[
L^2\ni\sup_{t\in[0,T]}|\Exp(U)_t| = \sup_{t\in[0,T]}|\utilMMV'(\aLRT(0)\sint R)_t|,
\] 
hence $\aLRT(0)\in\AdmMMV$ by \eqref{eq:250111.MMV}.

As the next step, we shall show that $\aLRT(0)$ has the highest expected utility in $\AdmMMV$, i.e.,
\begin{equation}\label{eq:max utility}
\max_{\alpha\in\AdmMMV}\E[\utilMMV(\alpha\sint R_T)] = \E[\utilMMV(\aLRT(0)\sint R_T)].
\end{equation}
Fix an arbitrary $\alpha\in\AdmMMV$ and denote by  $\tau$  the first time $\utilMMV'(\alpha\sint R)=(1-\alpha\sint R)^+$ becomes zero. Observe that $\alpha\indicator{\lc 0, \tau\rc}\in\AdmMMV$ and that the terminal utility of $\alpha\indicator{\lc 0, \tau\rc}$ is at least as high as that of $\alpha$. Furthermore,
\[
Z= \left(\utilMMV'(\alpha\indicator{\lc 0, \tau\rc}\sint R)\right)^2 = 1-2\utilMMV(\alpha\indicator{\lc 0, \tau\rc}\sint R)
\]
is absorbed in zero if it ever hits zero. Admissibility of $\alpha\indicator{\lc 0, \tau\rc}$ means that $\sup_{t\in[0,T]}Z_t$ is integrable, hence $Z\geq0$ is special. 

We shall now apply the converse direction of Proposition~\ref{P:lambda to alpha and back} on a certain stochastic interval.
Denoting by $\tau^Z_c$ the first time $Z$ reaches zero continuously, we have that $\Log(Z)$ is well defined and special on $\lc 0,\tau^Z_c\lc$. Letting
\[
\lambda = \frac{\alpha\indicator{\lc 0, \tau\rc}}{1-\alpha\indicator{\lc 0, \tau\rc}\sint R_-}\indicator{\lc0,\tau^Z_c\lc},
\]
we obtain  
\[ 
B^{\Log(Z)}\indicator{\lc0,\tau^Z_c\lc} = -2B^{\utilMMV \circ (\lambda\sint R)}\indicator{\lc0,\tau^Z_c\lc}
\]
by Proposition~\ref{P:lambda to alpha and back}. By optimality of $\lLRT$ we have 
\begin{equation}\label{eq:Granada241012}
(2B^{\utilMMV \circ (\lLRT\sint R)}-2B^{\utilMMV \circ (\lambda\sint R)})\indicator{\lc0,\tau^Z_c\lc} \text{ is non-decreasing on $\lc0,\tau^Z_c\lc$,} 
\end{equation}
hence by Lemma~\ref{L:London241228} applied on $\lc0,\tau^Z_c\lc$ with $X=-2B^{\utilMMV \circ (\lambda\sint R)}$ and $X'=-2B^{\utilMMV \circ (\lLRT\sint R)}$ one obtains
\begin{align*}
\liminf_{t\uparrow\tau^Z_c}\Exp(B^{\Log(Z)})_t={}& \liminf_{t\uparrow\tau^Z_c}\Exp(-2B^{\utilMMV \circ (\lambda\sint R)})_t\\
\geq {}&\liminf_{t\uparrow\tau^Z_c}\Exp(-2B^{\utilMMV \circ (\lLRT\sint R)})_t
\geq \Exp(-2B^{\utilMMV \circ (\lLRT\sint R)})_T>0.
\end{align*} 

\citet*[Theorem~3.1]{cerny.ruf.23.spa} now yields that 
\[ M = \frac{Z}{\Exp(B^{\Log(Z)})}\indicator{\lc0,\tau^Z_c\lc}
\] is a local martingale on $[0,T]$. Furthermore, $M$ is uniformly integrable (hence a martingale) since $\sup_{t\in[0,T]}Z_t$ is integrable and $\frac{1}{\Exp(B^{\Log(Z)})}\indicator{\lc0,\tau^Z_c\lc}\leq \frac{1}{\Exp(-2B^{\utilMMV \circ (\lLRT\sint R)})_T}$ by \eqref{eq:Granada241012}.

Recalling \eqref{eq:a(0) utility}, we have
\begin{align*}
\frac{1-2\E\left[\utilMMV(\alpha\indicator{\lc 0, \tau\rc}\sint R_T)\right]}{1-2\E\left[\utilMMV(\aLRT(0)\sint R_T)\right]} = 
\frac{\E\left[Z_T\right]}{\Exp(-2B^{\utilMMV \circ (\lLRT\sint R)})_T} = 
\E\left[M_T\frac{\Exp(B^{\Log(Z)})_T\indicator{\{\tau^Z_c>T\}}}{\Exp(-2B^{\utilMMV \circ (\lLRT\sint R)})_T}\right]\geq \E\left[M_T\right] = 1, 
\end{align*}
where the inequality follows from \eqref{eq:Granada241012}. After rearranging, one has 
\begin{equation*}
\E\left[\utilMMV(\alpha\sint R_T)\right] \leq \E\left[\utilMMV(\alpha\indicator{\lc 0, \tau\rc}\sint R_T)\right] \leq \E\left[\utilMMV(\aLRT(0)\sint R_T)\right]
\end{equation*}
for all $\alpha\in\AdmMMV$, which proves \eqref{eq:max utility}.
\smallskip

In \eqref{eq:a(0) utility} and \eqref{eq:max utility} we have established the maximal expected monotone quadratic utility $\uLRT(0)=\frac{1-\Exp\bigs(-2B^{\utilMMV \circ  (\lLRT\sint R)}\bigs)_T}{2}<\frac{1}{2}$ over $\AdmMMV$ and shown $\aLRT(0)$ in \eqref{eq:a(0)} to be the maximizer. The rest of the statement now follows from Proposition~\ref{P1}.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{T4}]
For each $n\in\N$, let 
\begin{equation*}
\lLRTn_t = \lLRT_t\indicator{|\lLRT_t|\leq n}\indicator{\locutilMMV_t(\lLRT_t)\leq n}.
\end{equation*}
Then $\lLRTn$ is bounded, therefore it integrates $R$. By Proposition~\ref{P:Cierne240808}, we have 
$$ 0\leq \locutilMMV_t(\lLRTn_t)\uparrow  \locutilMMV_t(\lLRT_t)<\infty,\qquad t\in[0,T], \quad n\uparrow \infty.$$
An analog of Theorem~\ref{T2} with $\lLRT$ replaced by $\lLRTn$ yields that $\utilMMV(\lLRTn\,\id)\circ R$ is special. 

Letting $\alpha^n = \lLRTn\Exp\bigs( -\left(\id\wedge1\right) \circ (\lLRTn\sint R) \bigs) _{-}$, Proposition~\ref{P:Cierne240807} and monotonicity of $B^{\utilMMV(\lLRTn\,\id) \circ R}$ yield 
$$u^n=\E[\utilMMV(\alpha^n\sint R_T)] = \frac{1-\Exp\left( -2B^{\utilMMV(\lLRTn\,\id) \circ R} \right)_T}{2}\leq 
\frac{1-\exp\left( -2B^{\utilMMV(\lLRTn\,\id) \circ R}_T \right)}{2}.$$
Since 
\[
B^{\utilMMV(\lLRTn\,\id) \circ R}_T = \int_0^T \locutilMMV_t(\lLRTn_t)\d A_t\uparrow \int_0^T \locutilMMV_t(\lLRT_t) \d A_t= \infty,
\] 
we have $u^n\uparrow\frac{1}{2}$, which proves the first assertion in view of \eqref{eq:utilLRT}. 

To see the second assertion, observe that by an analog of Proposition~\ref{P1} with $\bigcup_{\lambda\geq 0}\lambda \alpha^n$ in place of $\AdmMMV$, $\alpha^n$ in place of $\aLRT(0)$, and $u^n$ in place of $\uMMV(0)$, the strategies $\beta^n = (1-2u^n)^{-1}\alpha^n$ satisfy $V_{\MMV}(\beta^n\sint R_T) =\frac{\left(1-2u^n\right)^{-1}-1}{2} \uparrow\infty$ as $n\uparrow \infty$ since $u^n\uparrow\frac{1}{2}$.
\end{proof}



