\section{Duality}\label{appx:G}

\begin{proof}[Proof of Proposition~\ref{P:Granada241017}]
Let $\Q$ be a separating measure. Observe that the function $h_\Q:\R\to[0,\infty]$, given by 
\[
h_\Q(y)= \E\left[\frac{1}{2}\left(y\frac{\d\Q}{\d\P}-1\right)^2\right] + \infty\indicator{y<0},
\]
is proper convex and lower semicontinuous. Consider now the function $\uLRT^\Q:\R\to\R_+$, given by  
$$\uLRT^\Q(x)=\sup_{{X\in L^1(\Q),\, \E^{\Q}[X]\leq0}}\{\E[\utilMMV(x + X)]\},\qquad x\in\R.$$
In economic terms,  $\uLRT^\Q(x)$ measures the maximal expected monotonized quadratic utility under $\P$ in a statically complete market with pricing measure $\Q$ for an agent with  initial wealth $x$. By \citet*[Lemma~4.3]{biagini.cerny.11} we have 
$\uLRT^\Q(x) = \min_{y\geq0} \left\{xy+h_\Q(y)\right\}$ for all $x\in\R$.
The Fenchel-Moreau theorem (e.g., \cite[Theorem~12.2]{rockafellar.70}) and the closedness of $h_\Q$ now yield 
\begin{equation}\label{eq:Granada241018}
\sup_{x\in\R}\,\{\uLRT^\Q(x)-xy\}=h_\Q(y),\qquad y\in\R.
\end{equation} 

Since $\Q$ is separating, we have 
\begin{align*}
\vLRT(0)  =   {}& \sup_{\vartheta\in\AdmMMV}\,\{V_{\MMV}(\vartheta\sint R_T)\}
\leq  {} \sup_{{X\in L^1(\Q),\, \E^{\Q}[X]\leq0}}\, \{V_{\MMV}(X)\}\\
					=   {}& \sup_{x\in\R}\,\{\uLRT^\Q(x)-x\} = h_{\Q}(1) = \frac{1}{2}\Var\left(\frac{\d\Q}{\d\P}\right),
\end{align*}
where the inequality follows by inclusion, the second equality follows from \eqref{eq:MMV2}, and the last two equalities follow from \eqref{eq:Granada241018} and the explicit form of $h_\Q$.
\end{proof} 

\begin{proof}[Proof of Theorem~\ref{T5}]
(1): By Theorems~\ref{T3} and \ref{T4}, one has $\vLRT(0)<\infty$ if and only if $\int_0^T \locutilMMV_t(\lLRT_t) \d A_t<\infty$. Letting 
$$U=-\left(\id\wedge1\right) \circ(\lLRT\sint R),$$ 
it is shown in the proof of Theorem~\ref{T3} that $U$  is special with $\Delta B^U>-1$ and that $\vfrac{\Exp(U)}{\Exp(B^U)}$ is a square-integrable martingale, which yields the claim.\smallskip

\noindent (2): By Theorem~\ref{T3}, $\aLRT(0) = \lLRT\Exp(U)_-$ maximizes the expected utility. Proposition~\ref{P:lambda to alpha and back} further gives $\utilMMV'(\aLRT(0)\sint R_T) = \Exp(U)_T=\Exp(B^U)_T\vfrac{\d\QLRT}{\d \P}$. Fix $\vartheta\in\AdmMMV$. By optimality of $\aLRT(0)$, the function $\psi:[0,\infty) \to \R$ given by $\psi(y) =\E[\utilMMV( \aLRT\sint R_T+y\vartheta\sint R_T)]$ attains its maximum at $0$. By dominated convergence and optimality, one obtains 
\[
0\geq \psi_+'(0) = \E[\utilMMV'( \aLRT(0)\sint R_T)\vartheta\sint R_T]>-\infty,
\] 
which shows that $\vartheta\sint R_T\in L^1(\QLRT)$ and $\E^{\QLRT}[\vartheta\sint R_T]<0$. Since $\vartheta\in\AdmMMV$ was arbitrary, this proves that $\QLRT$ is a separating measure. \smallskip

\noindent (3): Theorem~\ref{T3} together with \eqref{eq:Granada241018.2} yields 
\[
1+2\vLRT(0) = \Exp\bigs(-2B^{\utilMMV \circ  (\lLRT\sint R)}\bigs)_T^{-1} = \Exp\bigs(B^{U}\bigs)_T^{-1}.
\]
On the other hand, the Yor formula yields
\[ 
\Exp(U)^2 = \Exp\bigs( \left((1-(\id\wedge1))^2-1\right) \circ(\lLRT\sint R) \bigs) = \Exp\bigs( -2\utilMMV \circ(\lLRT\sint R) \bigs),
\]
which together with \cite[Theorem~4.1]{cerny.ruf.23.spa} and \eqref{eq:Granada241018.2} gives
\[
\E\bigg[\Big(\frac{\d \QLRT}{\d \P}\Big)^2\bigg] = \frac{\Exp\bigs(-2B^{\utilMMV \circ  (\lLRT\sint R)}\bigs)_T}{\Exp\bigs(B^{U}\bigs)_T^2} = \Exp\bigs(B^{U}\bigs)_T^{-1}=1+2\vLRT(0).
\]
This completes the proof of item (3).\smallskip

\noindent(4): In view of (3), Proposition~\ref{P:Granada241017} yields that the density of $\QLRT$ has the smallest variance among all separating measures. Arguing by contradiction, suppose there is another separating measure, say $\Q'$ whose density has the same variance. Strict convexity of $\id^2$ now yields that  $\QLRT/2 +\Q'/2$ is another separating measure with strictly smaller variance, which contradicts the already established optimality of $\QLRT$.\smallskip

\noindent(5): By \citet*[Proposition~4.2]{cerny.ruf.22.ejp}, for $\Delta R>-1$ one has $\log(\Exp(R)) = \log(1+\id)\circ  R$. The claim follows from the explicit form of $\QLRT$ and \cite[Proposition~2.15 and Corollary~5.10]{cerny.ruf.23.spa}.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{T6}]
Fix $i\in\{1,\ldots,d\}$.  Letting $V=R^{(i)}$ and $Y=-\left(\id\wedge1\right) \circ(\lLRT\sint R)$, we have $V+[V,Y] = \id_i\utilMMV'(\lLRT\mkern1mu\id)\circ R$.  Lemma~\ref{L:Metabief250115} now yields \ref{T6.ii} $\Rightarrow$ \ref{T6.i}. To argue the converse direction, Lemma~\ref{L:Metabief250115} yields that $b^{V+[V,Y]}$ is well-defined and equal to zero on all paths where $\d\QLRT/\d\P>0$, hence everywhere since $V+[V,Y]$ has independent increments under $\P$ and $\P[\d\QLRT/\d\P>0]>0$ by \cite[Lemma~4.2]{cerny.ruf.23.spa}. 
\end{proof}

\begin{proof}[Proof of Proposition~\ref{P:Metabief250115}]
Working under $\QLRT$, we have that $\vartheta\sint R$ has independent increments by Theorem~\ref{T5}\ref{T5.5} and $\vartheta\sint R_T$ is integrable by  Theorem~\ref{T5}\ref{T5.2}. By Theorem~\ref{T:200603}, the  $\sigma$-martingale $\vartheta\sint R$ is a martingale.
Next, fix $i\in\{1,\ldots,d\}$. If the jumps of $R^{(i)}$ are bounded from below, then  $R^{(i)}=1\sint R^{(i)}$ is the wealth of a deterministic admissible strategy by Lemma~\ref{L:Cierne250106}, and the claim follows. 
\end{proof}

\begin{proof}[Proof of Theorem~\ref{T7}]
The square integrability of $R$ yields that the local utility $\locutilMMV_t(\lambda)$ is finite for all $\lambda\in\R^d$ and $t\in[0,T]$, hence $\lLRT_t$ is an interior maximizer whose first-order condition reads $b_t^{\id\utilMMV'(\lLRT\mkern1mu\id)\circ R}=0$. Theorem~\ref{T6} now yields that $\QLRT$ is a $\sigma$-martingale measure for $R$. Furthermore,  the measure $\QMV$ is well defined thanks to Theorem~\ref{T8} and the inequality $\vMV(0)<\vMMV(0)$. 

To establish the equivalence between \ref{T7.i} and \ref{T7.ii}, observe that for square-integrable $R$, the local utilities $\locutilMV$ and $\locutilMMV$ are differentiable on the whole $\R^d$. \citet[Section~27, p.~264]{rockafellar.70} yields that $\partial\locutilMV(\lMV)=\partial\locutilMMV(\lLRT)=0$ characterizes all optimizers. Strict concavity of $\locutilMV$ on any complement of null strategies then yields uniqueness of $\lMV$ up to a null strategy. Observe also that $\utilMMV'-\utilMV'=(\id-1)\indicator{\id>1}$ is zero on $(-\infty,1]$ and positive on $(1,\infty)$.\smallskip

\noindent \ref{T7.i} $\Rightarrow$ \ref{T7.ii}   $\lMV\Delta R\leq1$  gives $0=\partial\locutilMV(\lMV)=\partial\locutilMMV(\lMV)$ hence $\lMV=\lLRT$, up to a null strategy. \smallskip

\noindent \ref{T7.ii} $\Rightarrow$ \ref{T7.i}   $\partial\locutilMV(\lMV)=\partial\locutilMMV(\lMV)=0$ implies $\lMV(\partial\locutilMMV(\lMV)-\partial\locutilMV(\lMV))=0$ which yields $b^{\id(\id-1)\indicator{\id>1}\circ(\lMV\sint R)}=0$. Since for $f=\id(\id-1)\indicator{\id>1}$ we have $f\circ (\lMV\sint R)=\sum_{s\leq\cdot}f(\lambda_s\Delta R_s)$ and $f$ is non-negative with $f>0$ on $(1,\infty)$, we conclude that $b^{f\circ(\lMV\sint R)}=0$  if and only if $\lMV\Delta R\leq1$. \smallskip

\noindent\ref{T7.i} $\Rightarrow$ \ref{T7.iii} The density of $\QMV$ has the smallest variance among all (signed) separating measures over $\AdmMV$. Since $\AdmMV\subset\AdmMMV$, we have $\Var(\frac{\d\QMV}{\d\P})\leq \Var(\frac{\d\QLRT}{\d\P})$.    
The square integrability of $R$ yields that the local utility $\locutilMV_t(\lambda)$ is finite for all $\lambda\in\R^d$ and $t\in[0,T]$, hence $\lMV_t$ is an interior maximizer whose first-order condition reads $b_t^{\id\utilMV'(\lMV\mkern1mu\id)\circ R}=0$. 
Condition \ref{T7.i} yields that $\QMV$ is a probability measure, hence a $\sigma$-martingale measure for $R$ by Theorem~\ref{T8}. By \citet[Proposition~5.2]{biagini.cerny.20}, $\QMV$ is then a separating measure over $\AdmMMV$. Minimality and uniqueness of $\QLRT$ obtained in Theorem~\ref{T5}\ref{T5.4} yield \ref{T7.iii}.\smallskip

\noindent \ref{T7.iii} $\Rightarrow$ \ref{T7.i} $\frac{\d\QMV}{\d\P}\geq0$ yields $\lMV\Delta R\leq1$ by the independence of increments.  
\end{proof}

