\section{Auxiliary statements}
%appx B
\begin{lemma}\label{L:SDE}
For any semimartingale $X$, the SDE
\begin{equation}\label{SDE}
 W = 1+ W^+_-\sint X 
\end{equation}
has a unique solution 
\begin{equation}\label{eq:240927Granada}
W =  1 + \Exp((-1\vee\id)\circ X)_-\sint X
\end{equation}
that furthermore satisfies 
$$ W^+ = \Exp((-1\vee\id)\circ X).$$
\end{lemma}
\begin{proof}
Since the function $x\mapsto x^+$ is Lipschitz, the SDE \eqref{SDE} has a unique (semimartingale) solution $W$ by \citet*[Theorem~V.6]{protter.05}. Denote by $\tau$ the first time $\Delta X\leq -1$. Then  $\Exp(X^\tau)^+=\Exp(X^\tau)\indicator{\lc0,\tau\lc}$ by \citet*{js.03} and $\Exp(X^\tau)^+_-=\Exp(X^\tau)_-\indicator{\lc0,\tau\rc}$. Since 
$$\Exp(X^\tau) =  1+\Exp(X^\tau)_- \sint X^\tau = 1+\Exp(X^\tau)_-\indicator{\lc0,\tau\rc}\sint X,$$ 
we have $W=\Exp(X^\tau)$. Observe that $-1\vee\id$ is a universal representing function in the sense of \citet*[Definition~3.4]{cerny.ruf.22.ejp}, hence 
$(-1\vee\id)\circ X$ is well defined. In view of \cite[Proposition~3.13(1)]{cerny.ruf.22.ejp}, $\tau$ is also the first time $(-1\vee\id)\circ X$ jumps by $-1$. By \citet*{js.03} again, $\Exp((-1\vee\id)\circ X)=\Exp(X)$ on $\lc0,\tau\lc$ and $\Exp((-1\vee\id)\circ X)_\tau=0$, hence 
\[ W^+ = \Exp(X^\tau)^+ =\Exp(X^\tau)\indicator{\lc0,\tau\lc} = \Exp((-1\vee\id)\circ X).\]
In combination with \eqref{SDE}, this yields \eqref{eq:240927Granada}. 
\end{proof}


%appx C
The next lemma studies the asymptotic slope of the local utility in a given direction. In this paper, it is used with $X=\lambda R$.

\begin{lemma}\label{L:230717}
Let $X$ be an $\R$-valued independent-increments semimartingale with characteristics $(b^{X[1]},c^X,F^X,A)$. Consider the function $\psi:\R\to [-\infty,\infty)$ given by 
\begin{equation*} 
\psi(y)= b^{X[1]}y - \frac{1}{2}  c^X y^2 +\int_{\R} \left(\utilMMV(xy)-xy\indicator{|x|\leq 1}\right)F^X(\d x).
\end{equation*}
Then 
\begin{equation}\label{eq:230718}
\begin{split}
 \infty>\lim_{y\to\infty}\frac{\psi(y)}{y} ={}& b^{X[1]}-\int_{\R} x\indicator{0<x\leq 1}F^X(\d x)
-\infty\left(\indicator{c^X>0}+\indicator{F^X(\R_-)>0}\right),
\end{split}
\end{equation}
with the convention $\infty\times0  = 0$.  
\end{lemma}
\begin{proof} 
Observe that $0\geq y^{-1}\left(\utilMMV(xy)-xy\right)\indicator{0<x\leq 1}\downarrow -x\indicator{0<x\leq 1}$ for $y\uparrow \infty$,
and, similarly, 
$$0\geq y^{-1}\left(\utilMMV(xy)-xy\right)\indicator{-1\leq x<0}\downarrow -\infty\indicator{-1\leq x<0},\qquad  y\uparrow \infty.$$
Monotone convergence now yields 
\begin{equation}\label{eq:mono1}
\begin{split}
\lim_{y\to\infty} y^{-1}\int_{\R} \left(\utilMMV(xy)-xy\right)\indicator{|x|\leq 1}F^X(\d x) ={}& -\int_{\R} x\indicator{0<x\leq 1}F^X(\d x)
-\infty \indicator{F^X([-1,0))>0}.
\end{split}
\end{equation}
The right-hand side is well defined with the convention $\infty\times0  = 0$ in the last term.

One also has 
$ 0\leq y^{-1}\utilMMV(xy)\indicator{1<x}\leq \frac{1}{2}\indicator{1<x}$ for $y\geq 1$.
Since $F^X([1,\infty))<\infty$, dominated convergence now yields
\begin{equation*}
\lim_{y\uparrow\infty} y^{-1}\int_{\R} \utilMMV(xy)\indicator{1<x}F^X(\d x) = 0.
\end{equation*}

As the final ingredient, monotone convergence yields
\begin{equation}\label{eq:mono2}
0\geq \lim_{y\to\infty} y^{-1}\int_{\R} \utilMMV(xy)\indicator{x<-1}F^X(\d x) = -\infty \indicator{F^X((\infty,-1))>0},
\end{equation}
with the convention $\infty\times0  = 0$.

Pulling \eqref{eq:mono1}--\eqref{eq:mono2} together yields \eqref{eq:230718}.
\end{proof}


%appx D
We next characterize integrability in terms of predictable characteristics. We first present a somewhat simplified version of \citet*[Theorem~III.6.30]{js.03}, where we additionally interpret the predictable criterion as a certain predictable variation. 
\begin{theorem}\label{T:int}
For an  $\R^d$-valued predictable process $\zeta$ and  an $\R^d$-valued semimartingale $X$, the following are equivalent.
\begin{enumerate}[(i)]
\item\label{Tint.i} $\zeta\in L(X)$.
\item\label{Tint.ii} The predictable process $\eta$ defined by
\begin{align*}
\eta = \zeta c^X\zeta^\top + \int_{\R^d} ((\zeta x)^2\wedge1)F^X(\d x) 
+ \left| \zeta b^{X[1]} + \int_{\R^d} \left(\zeta x \indicator{|\zeta x|\leq 1} - \zeta h(x) \right)F^X(\d x)\right|
\end{align*} 
integrates $A$.
\end{enumerate}
Furthermore, if either of these conditions holds, then  one has 
\[
\eta = b^{(\id^2\wedge1)\circ (\zeta\sint X)} + \big|b^{\id\indicator{|\id|\leq1}\circ (\zeta\sint X)}\big|.
\]
\end{theorem}
\begin{proof}
\ref{Tint.i}$\implies$\ref{Tint.ii} and the sequel:\ $\zeta\in L(X)$ yields that $Y=\zeta\sint X$ is a semimartingale. Since $(\id^2\wedge1)\in\tI(X)$ and $\id\indicator{|\id|\leq 1}\in\tI(X)$, composition \cite[Remark~3.19]{cerny.ruf.22.ejp} yields that $(\zeta\mkern2mu\id)^2\wedge1\in\tI(X)$, $\zeta\mkern2mu\id\indicator{|\zeta\mkern1mu\id|\leq1}\in\tI(X)$ and 
\begin{align*}
\left(\id^2\wedge1\right)\circ (\zeta\sint X) ={}& \left((\zeta\mkern2mu\id)^2\wedge1\right)\circ X,\\
\id\indicator{|\id|\leq1}\circ (\zeta\sint X) ={}& \zeta\mkern2mu\id\indicator{|\zeta\mkern1mu\id|\leq1}\circ X.
\end{align*}
These two semimartingales are special since their jumps are bounded. An explicit expression for the drift rate of these two quantities via Lemma~\ref{L:240130} yields \ref{Tint.ii}. 

\ref{Tint.ii}$\implies$\ref{Tint.i} Let $\tilde h = \id\mkern2mu\indicator{|\id|\leq1}$ and $X[\tilde h] = \tilde h\circ X$. By invariance of truncations, one has 
\[
\eta = \zeta c^X\zeta^\top + \int_{\R^d} ( (\zeta x)^2\wedge1)F^X(\d x) 
+ \left| \zeta b^{X[\tilde h]} + \int_{\R^d} \left(\zeta x \indicator{|\zeta x|\leq 1} - \zeta \tilde h(x) \right)F^X(\d x)\right|.
\]
Observe that $\indicator{|\id|> 1}\in L(\nu^X)$, hence 
\[ \left|\int_{\R^d} \zeta x \indicator{|\zeta x|\leq 1}(\indicator{|x|\leq1}-1)F^X(\d x)\right| \leq \int_{\R^d} \indicator{|x|>1}F^X(\d x)\]
integrates $A$. Since $\eta$ integrates $A$, the triangle inequality yields
\[\zeta c^X\zeta^\top + \int_{\R^d} ( (\zeta x)^2\wedge1)\indicator{|x|\leq1}F^X(\d x) 
+ \left| \zeta b^{X[\tilde h]} + \int_{\R^d} \left(\zeta x \indicator{|\zeta x|\leq 1}\indicator{|x|\leq1} - \zeta \tilde h(x) \right)F^X(\d x)\right|  \]
integrates $A$. \citet*[Theorem~III.6.30]{js.03} now gives \ref{Tint.i}.
\end{proof}

\begin{corollary}\label{C:integrability}
Let $\zeta$ be an $\R^d$-valued predictable process and $X$ an $\R^d$-valued semimartingale. Then $\zeta^n = \zeta\indicator{|\zeta|\leq n}$ integrates $X$ and the following are equivalent.
\begin{enumerate}[(i)]
\item\label{Cint.i} $\zeta\in L(X)$.
\item\label{Cint.ii} $\lim_{n\uparrow \infty} \left(b^{((\zeta^n\mkern2mu\id)^2\wedge1)\circ X} + \left|b^{\zeta^n\mkern2mu\id\indicator{|\zeta^n\mkern1mu\id|\leq1}\circ X} \right| \right)$ integrates $A$.
\end{enumerate}
\end{corollary}
\begin{proof}
The boundedness of $\zeta^n$ for each $n\in\N$ yields $\zeta^n\in L(X)$. Theorem~\ref{T:int} with $\zeta^n$ in place of $\zeta$ now yields that 
\begin{align*}
\eta^n ={}& b^{(\id^2\wedge1)\circ (\zeta^n\sint X)} + \big|b^{\id\indicator{|\id|\leq1}\circ (\zeta^n\sint X)}\big|\\
={}&  \zeta^n c^X(\zeta^n)^\top + \int_{\R^d} ( (\zeta^n x)^2\wedge1)F^X(\d x) 
+ \left| \zeta^n b^{X[1]} + \int_{\R^d} \left(\zeta^n x \indicator{|\zeta^n x|\leq 1} - \zeta^n h(x) \right)F^X(\d x)\right|
\end{align*}
is well defined. In view of $\eta^n\uparrow\eta$, the claim follows by Theorem~\ref{T:int}.
\end{proof}




