The following proposition details one step in the proof of Theorem~\ref{T:MV}, whose notation we adopt without further reference.
\begin{proposition}\label{P:Cierne250106}
For the optimal local utility strategy $\lMV$ let $\lMVn = \lMV\indicator{|\lMV|\leq n}$ for $n\in\N$. Then we have $b^{\id\mkern1mu\indicator{|\id|\leq1}\circ (\lMVn\sint R)}\geq0$ and   
\begin{equation}\label{eq:Cierne250106}
b^{\utilMV\circ (\lMVn\sint R)}\leq b^{(\id^2\wedge1)\circ (\lMVn\sint R)} + b^{\id\mkern1mu\indicator{|\id|\leq1}\circ (\lMVn\sint R)} 
\leq 6 b^{\utilMV\circ (\lMVn\sint R)},\qquad n\in\N.
\end{equation}
\end{proposition}

\begin{proof}
Fix $n\in\N$ and let $X=\lMVn\sint R$. The first-order conditions yield that 
$\id\circ X$ and $\id^2\circ X$
are $\sigma$-special with $b^{\id\circ X} = b^{\id^2\circ X}$,
which in view of $\utilMV = \id-\frac{1}{2}\id^2$ gives 
$2b^{\utilMV\circ X} = b^{\id\circ X}  =  b^{\id^2\circ X}$
and also $b^{\id\indicator{\id\leq1}\circ X} \geq b^{(\id^2\indicator{\id\leq1})\circ X}\geq0$.
The latter yields the first claim. 

The easy inequalities $0\leq -\id \indicator{\id<-1}\leq \id^2 \indicator{\id<-1}$ give 
\[b^{\id\indicator{|\id|\leq1}\circ X} \leq b^{\id\circ X} + b^{\id^2 \indicator{\id<-1}\circ X}\leq4b^{\utilMV\circ X}.\]
Together with $b^{(\id^2\wedge1)\circ X}\leq b^{\id^2\circ X} = 2 b^{\utilMV\circ X}$, this establishes the second inequality in 
\eqref{eq:Cierne250106}. On the other hand, $\utilMV\leq\id\wedge1$ yields
$ 
b^{\utilMV\circ X} \leq{} b^{(\id\wedge1)\circ X}
\leq {} b^{\id\indicator{|\id|\leq1}\circ X} + b^{\indicator{\id>1}\circ X}
$
and the first inequality in \eqref{eq:Cierne250106} follows easily.
\end{proof}

%appx F
\begin{lemma}\label{L:London241228}
Suppose $X$ and $X'$ are $\R$-valued semimartingales such that $\Delta X'>-1$ and $X-X'$ is non-decreasing. Then $\frac{\Exp(X)}{\Exp(X')}$ is non-decreasing. 
\end{lemma}
\begin{proof}
By the generalised Yor formula and composition \cite[Proposition~4.1, Corollary~3.20]{cerny.ruf.22.ejp}, we have 
\[
\frac{\Exp(X)}{\Exp(X')}=\Exp\bigg(\bigg(\frac{1+\id_1}{1+\id_2}-1\bigg)\circ(X,X')\bigg)=\Exp\bigg(\frac{\id_1}{1+\id_2}\circ(X-X',X')\bigg).
\] 
Since $X-X'$ is of finite variation, the \'Emery formula in Lemma~\ref{L:241001} yields  
\[
\frac{\id_1}{1+\id_2}\circ(X-X',X') = (X-X')^c+[X',X']^c+\sum_{t\leq\cdot}\frac{\Delta (X-X')_t}{1+\Delta X'_t}
\] 
and the claim follows since the right-hand side is non-decreasing.
\end{proof}

%appx G
\begin{lemma}\label{L:Cierne250106}
Let $X$ be an $\R$-valued semimartingale with independent increments starting at $0$ such that $(\id^2\indicator{\id<-1})\circ X$ is special. Then $\sup_{t\in[0,T]}X_t^-\in L^2$. 
\end{lemma}
\begin{proof}
Observe that $Y=(\id\indicator{\id<1})\circ X$ has independent increments and is special. Since $\sup_{t\in[0,T]}X_t^-\leq \sup_{t\in[0,T]}Y_t^-$, it suffices to show the statement with $Y$ in place of $X$. We have $Y^-\leq (Y-B^Y)^-+(B^Y)^-$, hence
\[ \sup_{t\in[0,T]}Y_t^- \leq \sup_{t\in[0,T]}|Y_t-B^Y_t| + \sup_{t\in[0,T]}|B^Y_t|,\]
where the second term on the right-hand side is a deterministic constant. Since $\id^2\indicator{|\id|\leq1}\circ X$ has bounded jumps, we have $\id^2\circ Y = (\id^2\indicator{\id<-1})\circ X + \id^2\indicator{|\id|\leq1}\circ X$ is special.  
The Doob inequality and the fact that $\id^2\circ Y$ has independent increments now yield
\[\E\left[\left(\textstyle\sup_{t\in[0,T]}|Y_t-B^Y_t|\right)^2\right] \leq 4\E[\id^2\circ(Y-B^Y)_T] \leq 4B^{\id^2\circ Y}_T, \]
which completes the proof.
\end{proof}

The next theorem yields a simple proof that a semimartingale with independent increments is a local martingale if and only if it is a martingale, a claim previously established in \citet*[Theorem~5.8]{shiryaev.cherny.02}.

\begin{theorem}[Integrability of processes with independent increments] \label{T:200603}
For an $\R$-valued semimartingale $X$ with independent increments starting at $0$, the following are equivalent.
\begin{enumerate}[(i)]
\item\label{T:250107.1} $X^T$ is special.
\item\label{T:250107.2} $\sup_{t\in[0,T]} |X_t|\in L^1$.
\item\label{T:250107.3} $X_T\in L^1$. 
\end{enumerate}
Moreover, if one of these conditions holds, then $\E[X_t] = B^X_t$ for all $ t\in[0,T]$. In particular, if $X^T$ is a $\sigma$-martingale, then any of these conditions implies that $X^T$ is a martingale.
\end{theorem}

\begin{proof}
We first establish that the sum of two independent random variables is integrable if and only if each random variable is integrable. Indeed, let $U$ and $V$ be independent. Consider $v\geq0$ such that $\P[|V|\leq v]>0$. Then
\begin{align*}
\E[|U|] = \E\big[|U| \,\big|\, |V|\leq v\big]  = \E\big[|U+V-V| \,\big|\, |V|\leq v\big]\leq \E\big[|U+V| \,\big|\, |V|\leq v\big] + v<\infty,
\end{align*}
which asserts the claim.
\smallskip

\noindent \ref{T:250107.1} $\Rightarrow$ \ref{T:250107.2} Let $Y=|\id|\indicator{|\id|>1}\circ X^T$ and observe that $Y$ is an non-decreasing process with independent increments. By \cite[Proposition~II.2.29]{js.03}, $X^T$ is special if and only if $Y$ is special. Let $(\tau_n)_{n\in\N}$ be a localizing sequence for the local martingale $Y-B^Y$. By monotone convergence we have 
\[\E[Y_T]=\lim_{n\uparrow\infty}\E[Y_{\tau_n}]=\lim_{n\uparrow\infty}\E[B^Y_{\tau_n}]\leq B^Y_T,\]
hence $Y_T\in L^1$. Next, observe that $Z = \id\indicator{|\id|\leq 1}\circ X^T$ has independent increments with bounded jumps. Lemma~\ref{L:Cierne250106} yields $\sup_{t\in[0,T]}|Z_t|\in L^2\subset L^1$. The inequality 
$$\sup_{t\in[0,T]}|X_t|\leq Y_T+\sup_{t\in[0,T]}|Z_t|$$ 
now concludes.

\noindent \ref{T:250107.3} $\Rightarrow$ \ref{T:250107.1}
Since $X_T-X_t$ and $X_t$ are independent, we have that $X_t\in L^1$ for all $ t\in[0,T]$. For the deterministic process $B$ defined by $B_t=\E[X^T_t]$, $t\geq 0$,  $X-B$ has independent increments with zero mean, hence $X^T-B$ is a martingale with a version whose paths are c\`adl\`ag almost surely. Since $B$ is deterministic, this yields that $B$ is a finite-variation semimartingale and therefore $X^T=B+(X^T-B)$ is special. 
\end{proof}

