\subsection{Hyperparameters for the Multivariate Distributional Regression Model}\label{app:hyperparameters}

To align with the reproducible research best practices, as described in e.g \cite{lago2021forecasting}, we publish the reproduction code on \texttt{GitHub} at \url{https://github.com/simon-hirsch/online-mv-distreg}, allowing for full reproducibility of all experiments. Additionally, we take the following paragraph to describe the hyperparameters of the model: \begin{itemize}
    \item \emph{Information criteria and model selection:} We use the AIC for the multivariate distributional regression model and run the online coordinate descent on an exponential grid of 50 $\lambda$ values. We employ fast model selection based on the first derivatives for the CD-based models.
    \item \emph{Link functions:} We use the identity link for the location for all models. For the CD-based distributional models, we use the \texttt{InverseSoftPlusLink}. For the LRA-based models, we employ the \texttt{SqrtLink} for the diagonal matrix $\mat{A}$ as initial experiments showed a more robust convergence behavior and the \texttt{IdentityLink} for the matrix $\mat{V}$. For the degrees of freedom $\nu$, we employ the \texttt{LogShiftTwoLink}, which ensures that $\nu > 2$ and hence the covariance matrix is positive definite.
    \item \emph{Early stopping:} We employ early stopping for the path-based regularization of the scale matrix if the AIC does not improve, as described in Section \ref{sec:path_based_estimation}. We limit the number of off-diagonals for the CD-based parameterization to max 6, however note that the algorithm breaks after fitting 2-3 off-diagonals. We do not limit the number of columns fitted in the LRA-based model and note that the algorithm breaks after fitting the full rank-2 matrix $\mat{V}$.
    \item \emph{Number of iterations, step-size and dampening:} We dampen the estimation in the first iteration for the scale parameters only. We generally allow for a maximum of 30 inner and 10 outer iterations in the initial fit and the update steps.
\end{itemize}

\subsection{Derivation of Equation \ref{eq:newton_raphson_generic_first} and \ref{eq:newton_raphson_generic_second} for Newton-Raphson Scoring}\label{app:newton_raphson}
We aim to calculate ${\partial \ell}/{\partial \eta}$ and ${\partial^2 \ell}/{\partial \eta^2}$ for the calculation of the score and weight vectors (see Eq. \ref{eq:newton_raphson_generic_first} and Eq. \ref{eq:newton_raphson_generic_second}) using the partial derivatives of the log-likelihood with respect to the distribution parameter (resp. the coordinate of the distribution parameter in case of matrix-valued parameters), ${\partial \ell}/{\partial \theta}$ and ${\partial^2 \ell}/{\partial \theta^2}$. For continuous, twice differentiable link functions $\eta = g(\theta)$, we have
\begin{align}
    \frac{\partial \ell}{\partial \eta} &= \frac{\partial \ell}{\partial \theta} \left( \frac{\partial g(\theta)}{\partial\theta}\right)^{-1} 
\end{align}
and
\begin{align}
    \frac{\partial^2 \ell}{\partial \eta^2} &= \frac{
        \partial\left( 
            \dfrac{\partial \ell}{\partial \theta} \left( \dfrac{\partial g(\theta)}{\partial\theta}\right)^{-1} 
    \right)}{\partial \eta} = 
    \frac{
        \partial\left( 
            \dfrac{\partial \ell}{\partial \theta} \left( \dfrac{\partial g(\theta)}{\partial\theta}\right)^{-1} 
    \right)}{\partial \theta} \left( \dfrac{\partial g(\theta)}{\partial\theta}\right)^{-1} \nonumber
\end{align}
and by the quotient rule, we have
\begin{equation}
         \frac{\partial^2 \ell}{\partial \eta^2} = \left(\frac{ 
            \dfrac{\partial^2 \ell}{\partial \theta^2} \left( \dfrac{\partial g(\theta)}{\partial\theta}\right) -
            \dfrac{\partial \ell}{\partial \theta} \left( 
                \dfrac{\partial^2g(\theta)}{\partial\theta^2}\right)}{\left( \dfrac{\partial g(\theta)}{\partial\theta}\right)^2}\left( \dfrac{\partial g(\theta)}{\partial\theta}\right)^{-1}
    \right)  
\end{equation}
and the simplification
\begin{equation}
    \frac{\partial^2 \ell}{\partial \eta^2} = \left(
        \frac{\partial^2 \ell}{\partial \theta^2} \frac{\partial g(\theta)}{\partial\theta} - \frac{\partial \ell}{\partial \theta} \frac{\partial^2 g(\theta)}{\partial\theta^2}
    \right) \left( \frac{\partial g(\theta)}{\partial\theta}\right)^{-3}
\end{equation}
concludes the derivation $\blacksquare$


\subsection{Partial derivatives of the multivariate Gaussian Distribution}\label{app:derivatives_gaussian}

The probability density function of the multivariate normal distribution of dimension $D$ is given by:
\begin{equation}
    f(\vec{y} \mid \vec{\mu}, \mat{\Sigma}) = \frac{1}{(2\pi)^{D/2}|\mat{\Sigma}|^{1/2}}\exp\left(-\frac{1}{2}\transpose{\centy}\mat{\Sigma}^{-1}\centy\right)
\end{equation}
with the location or mean vector $\vec{\mu}$ and the scale respectively covariance matrix $\mat{\Sigma}$. We parameterize the PDF in terms of the inverse scale matrix $\mat{\Omega} = \mat{\Sigma}^{-1}$:
\begin{equation}\label{eq:normal_pdf_omega}
    f(\vec{y} \mid \vec{\mu}, \mat{\Sigma}) = \frac{1}{(2\pi)^{D/2}}|\mat{\Omega}|^{1/2}\exp\left(-\frac{1}{2}\transpose{\centy}\mat{\Omega}\centy\right)
\end{equation}
and calculate the log-likelihood as $\ell(\vec{y} \mid \vec{\mu}, \mat{\Omega}) = \log(f(\vec{y} \mid \vec{\mu}, \mat{\Omega}))$, which reads:
\begin{equation}
    \ell(\vec{y} \mid \vec{\mu}, \mat{\Sigma}) = -\frac{D}{2}\log(2\pi) - \frac{1}{2}\log(|\mat{\Sigma}|) - \frac{1}{2}\transpose{\centy}\mat{\Sigma}^{-1}\centy
\end{equation}
and parameterize the inverse covariance matrix through the Cholesky-decomposition $\mat{\Sigma} = \mat{A}\transpose{\mat{A}}$ and $\mat{\Sigma}^{-1} = \mat{\Omega} = \transpose{(\mat{A}^{-1})}(\mat{A}^{-1})$, which yields:
\begin{equation}
    \ell(\vec{y} \mid \vec{\mu}, \mat{A}^{-1}) = -\frac{D}{2}\log(2\pi) - \log(|\mat{A}^{-1}|) - \frac{1}{2}\transpose{\vec{z}}\vec{z}
\end{equation}
where $\vec{z} = \mat{A}^{-1}\centy$ and $z = \transpose{\vec{z}}\vec{z}$. The first derivatives with respect to the elements of $\vec{\mu}$ and $\mat{A}^{-1}$ are given in \cite{muschinski2022cholesky} and read
\begin{align}
    \frac{\partial \ell}{\partial \vec{\mu}_i} 
        &= \sum_{k=0}^D \mat{\Omega}_{ik}(\vec{y}_k - \vec{\mu}_k) \label{eq:partial_mu_gaussian} \\
    \frac{\partial \ell}{\partial (\mat{A}^{-1})_{ij}} 
        &= \frac{1}{(\mat{A}^{-1})_{ij}} - (\vec{y}_i - \vec{\mu}_i)\sum_{k=0}^D(\vec{y}_k - \vec{\mu}_k)(\mat{A}^{-1})_{kj} \label{eq:partial_chol_gaussian}
\end{align}
and the second derivatives are given by\begin{align}
    \frac{\partial \ell^2}{\partial \vec{\mu}_i^2} &= -\mat{\Omega}_{ii} \label{eq:partial_mu_gaussian_2} \\
    \frac{\partial \ell^2}{\partial (\mat{A}^{-1})_{ij}^2} &= - \frac{1}{(\mat{A}^{-1})^2_{ij}} - (\vec{y}_i - \vec{\mu}_i)^2 \label{eq:partial_chol_gaussian_2}
\end{align}
For the low-rank approximation, we parameterize Equation \ref{eq:normal_pdf_omega} in terms of the low-rank approximation $\mat{\Omega} = \mat{D} + \transpose{\mat{V}}\mat{V}$, which yields:
\begin{equation}
    \ell(\vec{y} \mid \vec{\mu}, \mat{U}, \mat{V}) = -\frac{D}{2}\log(2\pi) - \log(|(\mat{D} + \transpose{\mat{V}}\mat{V})^{-1}|) - \frac{1}{2}\transpose{\centy}(\mat{D} + \transpose{\mat{V}}\mat{V})\centy
\end{equation}
we note that the derivatives with respect to the elements of the mean vector $\vec{\mu}_i$ remain the same:\begin{align}
    \frac{\partial \ell}{\partial \vec{\mu}_i} 
        &= \sum_{k=0}^D \mat{\Omega}_{ik}(\vec{y}_k - \vec{\mu}_k) \\
    \frac{\partial \ell^2}{\partial \vec{\mu}_i^2} 
        &= -\mat{\Omega}_{ii}
\end{align}
and the derivatives with respect to the elements of $\mat{D}_{ii}$ are given by:
\begin{align}
    \frac{\partial \ell}{\partial \mat{D}_{ii}} 
        &= \frac{1}{2}\left(\mat{\Sigma}_{ii} - (\vec{y}_k - \vec{\mu}_k)^2\right) \\
    \frac{\partial \ell^2}{\partial \mat{D}_{ii}^2}
        &= -\frac{1}{2}\Sigma_{ii}^2.
\end{align}
The partial derivatives with respect to the elements of $\mat{V}$ are given by:
\begin{align}
   \frac{\partial \ell}{\partial \mat{V}_{ij}} &= 
        \sum_{k=0}^D \mat{\Sigma}_{ik}\mat{V}_{kj}
        \sum_{k=0}^D(\vec{y}_k - \vec{\mu}_k)(\vec{y}_i - \vec{\mu}_i)\mat{V}_{kj} \label{eq:partial_v_gaussian_1} \\
    \frac{\partial^2 \ell}{\partial \mat{V}_{ij}^2} \label{eq:partial_v_gaussian_2}
        &= \mat{\Sigma}_{ij} 
        - \sum_{k=0}^D \sum_{q=0}^D \mat{\Sigma}_{ii}\mat{V}_{qj}\mat{\Sigma}_{qk}\mat{V}_{kj}
        - \sum_{k=0}^D \sum_{q=0}^D \mat{\Sigma}_{iq}\mat{V}_{qj}\mat{\Sigma}_{ik}\mat{V}_{kj} \\ \nonumber
        &- \left(
            (\vec{y}_i - \vec{\mu}_i)^2 - \left(\sum_{k=0}^D(\vec{y}_k - \vec{\mu}_k)(\vec{y}_i - \vec{\mu}_i)\mat{V}_{kj}\right)^2
        \right)
\end{align}
which concludes the derivation of the partial derivatives $\blacksquare$


\subsection{Partial derivatives of the multivariate \textit{t}-distribution}
\label{app:derivatives_tdist}

The probability density function (PDF) of the multivariate $t$-distribution of dimension $D$ is given by:
$$
    f(\vec{y} \mid \vec{\mu}, \Sigma, \nu) 
    = \frac{\Gamma((\nu + D)/2)}{\Gamma(\nu/2)\nu^{D/2}\pi^{D/2 } |\mat{\Sigma}|^{1/2}} 
    \left(1 + \frac{1}{\nu}\transpose{\centy}\mat{\Sigma}^{-1}\centy\right)^{-(\nu+D)/2}
$$
with the location vector $\mu$, the shape matrix $\mat{\Sigma}$ and the degrees of freedom $\nu$. We parameterize the PDF in terms of the inverse shape matrix $\mat{\Omega} = \mat{\Sigma}^{-1}$:
\begin{equation}\label{eq:mvt_pdf_omega}
    f(\vec{y} \mid \vec{\mu}, \mat{\Omega}, \nu) 
    = \frac{\Gamma((\nu + D)/2)}{\Gamma(\nu/2)\nu^{D/2}\pi^{D/2 }}|\mat{\Omega}|^{1/2} 
    \left(1 + \frac{1}{\nu}\transpose{\centy}\mat{\Omega}\centy\right)^{-(\nu+D)/2}.
\end{equation}
We start with the partial derivatives for the CD-based parametrization. We have the Choleksy-decomposition $\mat{\Sigma} = \mat{A}\transpose{\mat{A}}$ and $\mat{\Sigma}^{-1} = \mat{\Omega} = \transpose{(\mat{A}^{-1})}(\mat{A}^{-1})$, which yields:
$$
    f(\vec{y} \mid \vec{\mu}, \mat{A}^{-1}, \nu) 
    = \frac{\Gamma((\nu + D)/2)}{\Gamma(\nu/2)\nu^{D/2}\pi^{D/2 }}|(\mat{A}^{-1})| 
    \left(1 + \frac{1}{\nu}\transpose{\centy}\transpose{(\mat{A}^{-1})}(\mat{A}^{-1})\centy\right)^{-(\nu+D)/2}.
$$ 
Let us introduce some notation to simply the following derivatives. Define:
\begin{align}
    \vec{z} &= \mat{A}^{-1}\centy \\
    z &= \transpose{\vec{z}}\vec{z}
\end{align}The log-likelihood is given by $\ell(\vec{y} \mid \vec{\mu}, \mat{A}^{-1}, \nu) = \log(f(\vec{y} \mid \vec{\mu}, \mat{A}^{-1}, \nu))$ and reads: 
\begin{equation}\label{eq:mvt_pdf_chol}
    \ell(\vec{y} \mid \vec{\mu}, \mat{A}^{-1}, \nu) = 
	\log\left(\frac{\Gamma((\nu + D)/2)}{\Gamma(\nu/2)\nu^{D/2}\pi^{D/2 }}\right) +
	\log\left(|(\mat{A}^{-1})|\right) + 
	\log\left(\left(1 + \frac{1}{\nu}(\vec{z}^T\vec{z})\right)^{-(\nu+D)/2}\right)
\end{equation}
For the partial derivatives with respect to the elements of $\vec{\mu}$ and $\mat{A}^{-1}$, we notice that $\transpose{\vec{z}}\vec{z}$ can be treated as a function of these elements and employ the chain rule. We see that:
\begin{align}
    \frac{\partial (\transpose{\vec{z}}\vec{z})}{\partial \vec{\mu}_i} &= 2 \sum_{j=1}^D\mat{\Omega}_{ij}(\vec{y}_j - \vec{\mu}_j)\label{eq:partial_zz_mu_1} \\ 
    \frac{\partial^2 (\transpose{\vec{z}}\vec{z})}{\partial \vec{\mu}_i^2} &= -2 \mat{\Omega}_{ij} \label{eq:partial_zz_mu_2} \\
    \frac{\partial (\transpose{\vec{z}}\vec{z})}{\partial (\mat{A}^{-1})_{ij}} &= 2(\vec{y}_i - \vec{\mu}_i)\sum_{m=1}^{M=j}(\vec{y}_m - \vec{\mu}_m)(\mat{A}^{-1})_{mj} \label{eq:partial_zz_chol_1} \\ 
    \frac{\partial (\transpose{\vec{z}}\vec{z})^2}{\partial (\mat{A}^{-1})_{ij}^2} &= (\vec{y}_i - \vec{\mu}_i)^2 \label{eq:partial_zz_chol_2} 
\end{align}
The chain rule for the last term of Equation \ref{eq:mvt_pdf_chol} yields:
\begin{align}
    \left[ \log\left(\left(1 + \frac{1}{\nu}(\zTz)\right)^{-(\nu+D)/2}\right)\right]' &=
        \frac{(D+\nu)}{2((\zTz)+\nu)}(\zTz)' \\
    \left[ \log\left(\left(1 + \frac{1}{\nu}(\zTz)\right)^{-(\nu+D)/2}\right)\right]'' &= 
        - \frac{(D+\nu)(((\zTz) + \nu) (\zTz)'' - ((\zTz)')^2)}{2((\zTz)+\nu)^2}
\end{align}
and plugging in the according partial derivatives in Equations \ref{eq:partial_zz_mu_1} to \ref{eq:partial_zz_chol_2} and applying integration by parts for the remainder of Equation \ref{eq:mvt_pdf_chol}, we have:
\begin{align}
    \frac{\partial l}{\partial \vec{\mu}_i} &= 
    \frac{(D+\nu)}{2(z+\nu)}\left(2 \sum_{j=1}^D \mat{\Omega}_{ij}(\vec{y}_j - \vec{\mu}_j)\right) \label{eq:partial_ll_mu_1} \\
    \frac{\partial^2}{\partial \vec{\mu}_i^2} &= 
    - \frac{
        (D+\nu)
        \left(
            (z + \nu)(-2 \mat{\Omega}_{ij}) 
            - \left(2 \sum_{j=1}^D \mat{\Omega}_{ij}(\vec{y}_j - \vec{\mu}_j)\right)^2
        \right)
    }{2(z+\nu)^2} \label{eq:partial_ll_mu_2} \\
    \frac{\partial \ell}{\partial(\mat{A}^{-1})_{ij}} &= 
        \frac{1}{(\mat{A}^{-1})_{ij}}\boldsymbol{1}_{i=j} + 
        \frac{(D+\nu)}{2(z+\nu)}\left(2(\vec{y}_i - \vec{\mu}_i)\sum_{m=1}^{M=i}(\vec{y}_m - \vec{\mu}_m)(\mat{A}^{-1})_{mj}\right) \label{eq:partial_ll_chol_1} \\
    \frac{\partial^2 l}{\partial (\mat{A}^{-1}){ij}^2} &= 
        - \frac{1}{(\mat{A}^{-1})_{ij}^2}\boldsymbol{1}_{i=j} 
        - \frac{
            (D+\nu)
            \left(
                (z + \nu)(\vec{y}_i - \vec{\mu}_i)^2  - 
                \left(2 \sum_{j=1}^D \mat{\Omega}_{ij}(\mat{y}_j - \mat{\mu}_j)\right)^2
            \right)
        }{2((\zTz)+\nu)^2} \label{eq:partial_ll_chol_2}
\end{align}
Where $\boldsymbol{1}$ is the indicator function for $i = j$, since the partial derivative of $\log\left(|\mat{A}^{-1}|\right)$ are only relevant for the partial derivatives of the diagonal elements of $\mat{A}^{-1}$. For the partial derivatives with respect to the degrees of freedom $\nu$, integration by parts yields:
\begin{align}
    \frac{\partial l}{\partial \nu} &= 
        -\frac{-\nu\operatorname{digamma(\frac{D+\nu}{2})}+D 
        + \nu\operatorname{digamma}(\frac{\nu}{2})}{2\nu} 
        + \frac{1}{2}\left(\frac{z(D + \nu)}{\nu(\nu + z)} 
        - \log\left(\frac{(\nu + z)}{ \nu}\right)\right) \\
    \frac{\partial^2 l}{\partial \nu^2} &= 
        \frac{1}{4}\left(\frac{2k}{\nu^2} + 
        \operatorname{trigamma(\frac{D+\nu}{2})} -
        \operatorname{trigamma}(\frac{\nu}{2})\right) + 
        \frac{z(\nu z - D(2\nu + z))}{2\nu^2(\nu + z)^2}.
\end{align}
For the low-rank approximation, we follow a similar notation. The LRA is given by $\mat{\Omega} = \mat{D} + \transpose{\mat{V}}\mat{V}$ and hence the PDF is given by:
\begin{equation}
    f(\vec{y} \mid \vec{\mu}, \mat{D}, \mat{V}, \nu) 
    = \frac{\Gamma((\nu + D)/2)}{\Gamma(\nu/2)\nu^{D/2}\pi^{D/2 }}|\mat{D} + \transpose{\mat{V}}\mat{V}|^{1/2} 
    \left(1 + \frac{1}{\nu}\transpose{\centy}(\mat{D} + \transpose{\mat{V}}\mat{V})\centy\right)^{-(\nu+D)/2}
\end{equation}
and the log-likelihood is given by
\begin{multline}
    \ell(\vec{y} \mid \vec{\mu}, \mat{A}^{-1}, \nu) = 
	    \log\left(\frac{\Gamma((\nu + D)/2)}{\Gamma(\nu/2)\nu^{D/2}\pi^{D/2 }}\right) +
	    \log\left(|(\mat{D} + \transpose{\mat{V}}\mat{V})|\right) + \\
	    \log\left(\left(1 + \frac{1}{\nu}\transpose{\centy}(\mat{D} + \transpose{\mat{V}}\mat{V})\centy\right)^{-(\nu+D)/2}\right)
\end{multline}
we follow a similar strategy as above and see that the partial derivatives with respect to the elements of $\vec{\mu}$ and with respect to the degrees of freedom $\nu$ are the same as above:\begin{align}
    \frac{\partial \ell}{\partial \vec{\mu}_i} &= 
    \frac{(D+\nu)}{2(z+\nu)}\left(2 \sum_{j=1}^D \mat{\Omega}_{ij}(\vec{y}_j - \vec{\mu}_j)\right) \label{eq:partial_ll_lra_mu_1} \\
    \frac{\partial^2 \ell}{\partial \vec{\mu}_i^2} &= 
    - \frac{
        (D+\nu)
        \left(
            (z + \nu)(-2 \mat{\Omega}_{ij}) 
            - \left(2 \sum_{j=1}^D \mat{\Omega}_{ij}(\vec{y}_j - \vec{\mu}_j)\right)^2
        \right)
    }{2(z+\nu)^2} \label{eq:partial_ll_lra_mu_2} \\
    \frac{\partial l}{\partial \nu} &= 
        -\frac{-\nu\operatorname{digamma(\frac{D+\nu}{2})}+D 
        + \nu\operatorname{digamma}(\frac{\nu}{2})}{2\nu} 
        + \frac{1}{2}\left(\frac{z(D + \nu)}{\nu(\nu + z)} 
        - \log\left(\frac{(\nu + z)}{ \nu}\right)\right) \\
    \frac{\partial^2 l}{\partial \nu^2} &= 
        \frac{1}{4}\left(\frac{2k}{\nu^2} + 
        \operatorname{trigamma(\frac{D+\nu}{2})} -
        \operatorname{trigamma}(\frac{\nu}{2})\right) + 
        \frac{z(\nu z - D(2\nu + z))}{2\nu^2(\nu + z)^2}.
\end{align}
where $z$ is now defined as \begin{equation}
    z = \transpose{\centy}(\mat{D} + \transpose{\mat{V}}\mat{V})\centy.
\end{equation}
For the partial derivatives with respect to the elements of $\mat{D}$, we note that the partial derivatives of the second term are given by:\begin{align}
    \fracpartial{}{\mat{D}_{ii}} 
        &= \frac{1}{2}\mat{\Sigma}_{ii} \label{eq:partial1_det_lra} \\
    \fracpartial{}{(\mat{D}_{ii})^2} 
        &= - \frac{1}{2}\left(\mat{\Sigma}_{ii}\right)^2 \label{eq:partial2_det_lra}
\end{align}
and the partial deriviatives of the third term are given by \begin{align}
    \fracpartial{}{\mat{D}_{ii}} 
        &= \frac{D+\nu}{2(z + \nu)}(\vec{y}_i - \vec{\mu}_i)^2 \label{eq:partial1_log_lra} \\
    \fracpartial{}{\mat{D}_{ii}^2} 
        &= 0
\end{align}
and the second defaults to 0. The partial derivatives of the log-likelihood with respect to the elements of $\mat{D}$ are hence given by:\begin{align}
    \frac{\partial \ell}{\partial\mat{D}_{ii}} &= 
        \frac{1}{2}\mat{\Sigma}_{ii} - 
        \frac{D+\nu}{2(z + \nu)}(\vec{y}_i - \vec{\mu}_i)^2 \label{eq:partial_ll_lra_d_1} \\
    \frac{\partial^2 \ell}{\partial \mat{D}_{ii}^2} &= 
        - \frac{1}{2}\left(\mat{\Sigma}_{ii}\right)^2
        - \frac{D+\nu}{2(z + \nu)^2} 
        \left(
            (\vec{y}_i - \vec{\mu}_i)^2
        \right)^2.\label{eq:partial_ll_lra_d_2}
\end{align}
For the partial derivatives with respect to the elements of $\mat{V}$, we have a more complex formulation for the second term involving the determinant:\begin{align}
    \frac{\partial}{\partial V_{ij}} 
        &=  \label{eq:partial_det_v_lra}\\
    \frac{\partial}{\partial V_{ij}^2} 
        &= \mat{\Sigma}_{ij} 
        - \sum_{k=0}^D \sum_{q=0}^D \mat{\Sigma}_{ii}\mat{V}_{qj}\mat{\Sigma}_{qk}\mat{V}_{kj}
        - \sum_{k=0}^D \sum_{q=0}^D \mat{\Sigma}_{iq}\mat{V}_{qj}\mat{\Sigma}_{ik}\mat{V}_{kj}\label{eq:partial2_det_v_lra}
\end{align}
and the partial derivatives of the third term are given by\begin{align}
    % note that I have shortened the 2, divide 2 here compared to python!
    \frac{\partial}{\partial V_{ij}} 
        &= \frac{D+\nu}{(z + \nu)}\sum_{k=0}^D(\vec{y}_k - \vec{\mu}_k)(\vec{y}_i - \vec{\mu}_i)\mat{V}_{kj} \label{eq:partial_log_v_lra_1} \\
    \frac{\partial}{\partial V_{ij}^2} 
        &= \frac{D+\nu}{(z + \nu)^2} (\vec{y}_i - \vec{\mu}_i)^2\label{eq:partial2_log_v_lra_1}
\end{align}
and hence integration by parts again gives us, similiar to the partial derivatives for the multivariate normal distribution in Equation \ref{eq:partial_v_gaussian_1} and \ref{eq:partial_v_gaussian_2}:\begin{align}
    \frac{\partial \ell}{\partial \mat{V}_{ij}} &= 
        \sum_{k=0}^D \mat{\Sigma}_{ik}\mat{V}_{kj}
        + \frac{D+\nu}{(z + \nu)}
        \sum_{k=0}^D(\vec{y}_k - \vec{\mu}_k)(\vec{y}_i - \vec{\mu}_i)\mat{V}_{kj} \label{eq:partial_ll_lra_v_1} \\
    \frac{\partial^2 \ell}{\partial \mat{V}_{ij}^2} &=
        \mat{\Sigma}_{ij} 
        - \sum_{k=0}^D \sum_{q=0}^D \mat{\Sigma}_{ii}\mat{V}_{qj}\mat{\Sigma}_{qk}\mat{V}_{kj}
        - \sum_{k=0}^D \sum_{q=0}^D \mat{\Sigma}_{iq}\mat{V}_{qj}\mat{\Sigma}_{ik}\mat{V}_{kj} \\ \nonumber
        &- \frac{D+\nu}{(z + \nu)^2} \left(
            (\vec{y}_i - \vec{\mu}_i)^2 - \left(\sum_{k=0}^D(\vec{y}_k - \vec{\mu}_k)(\vec{y}_i - \vec{\mu}_i)\mat{V}_{kj}\right)^2
        \right) \label{eq:partial_ll_lra_v_2}
\end{align}
which concludes the derivation of the partial derivatives for the multivariate $t$-distribution $\blacksquare$
