The following result can be found in \cite{meapp, DAL}.

\begin{Lemma}\label{App2}
    Suppose $1<p<\infty$ and $\nu\in M^p_0(\Omega)$ is a non-negative measure.  Then, there exists a non-negative increasing sequence of measures $\{\nu_n\}_{n\in\mb N}\subset W^{-1,p'}(\Omega)$ such that $\nu_n\to\nu$ in $\mathcal{M}(\Omega)$ (total variation norm), i.e., $|\nu_n-\nu|(\Omega)\to0$ as $n\to\infty$.
\end{Lemma}
For the next result we refer \cite[Proposition 2.7]{MD}. Before stating the result, we note that it is well-known that for every $u\in W^{1,p}(\Omega)$, there exists $\mathrm{cap}_p$-quasi continuous representative $\Tilde{u}$ of $u$, i.e.,
\begin{itemize}
    \item [(i)] $u=\Tilde{u}$ a.e. in $\Omega$,
    \item[(ii)] for every $\epsilon>0$, there exists a set $S\subset\Omega$ such that $\mathrm{cap}_p(S)<\epsilon$ and $\Tilde{u}$ is continuous in $\Omega\setminus S$. 
\end{itemize}

\begin{Lemma}\label{Bdd}
     Suppose $1<p<\infty$ and $\nu\in M^p_0(\Omega)$ is a non-negative measure. Assume that $u\in W^{1,p}_0(\Omega)\cap L^\infty(\Omega)$ is a non-negative function. Then, up to the choice of its $\mathrm{cap}_p$-quasi continuous representative, $u\in L^\infty(\Omega,\nu)$, and $$\int_\Omega u\;d\nu\leq \|u\|_{L^\infty(\Omega)}\,\nu(\Omega).$$
\end{Lemma}

\begin{Definition}\label{ntop}
A sequence {$\{\mu_n\}_{n\in\mathbb{N}}\subset M(\Omega)$} is said to converge to a measure $\mu\in M(\Omega)$ in narrow topology if for every $\phi\in C^\infty_c(\Omega)$, we have $$\lim_{n\to\infty}\int_\Omega \phi d\mu_n=\int_\Omega \phi d\mu.$$
\end{Definition}

Before stating our main results below, we define the condition $(P_{\epsilon,\delta_*})$ below.\\
\textbf{Condition $(P_{\epsilon,\delta_*})$:} We say that a continuous function $\delta:\overline{\Omega}\to (0,\infty)$, satisfies the condition $(P_{\epsilon,\delta_*})$, if there exist $\delta_*\geq 1$ and $\epsilon>0$ such that $\delta(x)\leq \delta_*$ for every $x\in\Omega_\epsilon$, where 
$
\Omega_\epsilon:=\{y\in\Omega:\text{dist\,}(y,\partial\Omega)<\epsilon\}.
$
\subsection{Main results}
We state our main existence results below.
\begin{Theorem}\label{Theorem1}(Variable singular exponent)
   Let $\delta:\overline{\Omega}\to(0,\infty)$ be a continuous function such that $\delta$ is locally Lipschitz continuous in $\Omega$, $|\nabla\delta|\in L^N(\Omega)$, and $\delta$ satisfies $P_{\epsilon,\delta_*}$ for some $\;\delta_*\geq 1$ and for some $\epsilon>0$.

     Suppose $\mu,\;\nu$ are non-negative bounded Radon measures on $\Omega$, with $\nu\in M^p_0(\Omega)\setminus\{0\}$ for some $1<p<\frac{N}{N-1}$. Then the problem $(\ref{ME})$ admits a weak solution $u\in W^{1,p}_{\mathrm{loc}}(\Omega)\cap L^1(\Omega)$ in the sense of Definition \ref{def1} such that
\begin{enumerate}
    \item[(i)]If $\delta_*=1$, then $u\in W^{1,p}_0(\Omega)$.
    \item[(ii)] If $\delta_*>1$, then $T_k(u)\in W^{1,2}_{\mathrm{loc}}(\Omega)$ such that $T_k^\frac{\delta_*+1}{2}(u)\in W^{1,2}_0(\Omega)$ for every $k>0$.
\end{enumerate}
\end{Theorem}
\begin{Remark}
   Furthermore, upon close examination of the proof of Theorem \ref{Theorem1}, it becomes evident that the condition $|\nabla\delta|\in L^N(\Omega)$ plays a crucial role in establishing the existence of the approximate solution as shown in Lemma \ref{Existence}. In contrast, as shown in \cite{BG}, this assumption was not required in the non-singular case. As a result, when $\nu$ is non-singular, Theorem \ref{Theorem1} agrees with \cite[Theorem 2.12]{BG}, provided the additional condition $|\nabla\delta|\in L^N(\Omega)$ holds. On the other hand, Theorem \ref{Theorem1} is completely new when $\nu$ is a singular measure. 
\end{Remark}

When $\delta>0$ is a constant and $\mu$ is a suitable Lebesgue integrable function, we have the following existence result for a more general class of measures $\nu$.

\begin{Theorem}\label{Theorem2}(Constant singular exponent)
    Assume that $\delta:\overline{\Omega}\to(0,\infty)$ is a constant function. We define
    $$p=\begin{cases}
    \frac{N(\delta+1)}{N+\delta-1}, \text{ if }0<\delta<1,\\
    2, \text{ if }\delta\geq 1.
\end{cases}$$
{Let $\mu\in L^\frac{N(\delta+1)}{N+2\delta}(\Omega )$ be a non-negative function in $\Omega$. 
 Further, assume that $\nu\in M^{p}_0(\Omega)\setminus\{0\}$ is a non-negative  bounded Radon measure on $\Omega$.} Then the equation (\ref{ME}) admits a weak solution $u\in W^{1,p}_{\mathrm{loc}}(\Omega)\cap L^1(\Omega)$ in the sense of Definition \ref{def1} such that
\begin{enumerate}
    \item [(i)] If $0<\delta\leq 1$, then $u\in W_0^{1,p}(\Omega)$.
    \item[(ii)] If $\delta>1$, then $u\in W_{\mathrm{loc}}^{1,2}(\Omega)$ such that $u^\frac{\delta+1}{2}\in W_0^{1,2}(\Omega)$. 
\end{enumerate}
\end{Theorem}

\begin{Remark}\label{mrmk}
One can observe along the lines of the proofs of our main existence results that Theorems \ref{Theorem1} and \ref{Theorem2} hold even for the purely local equation that can be obtained by replacing $\mathcal{M}$ with the operator $\mathcal{A}$ in the equation \eqref{ME} where $\mathcal{A}u=\text{div}(A(x)\nabla u)$ with $A:\Omega\to\mathbb{R}^{N^2}$ a bounded elliptic matrix satisfying \eqref{lkernel}. To the best of our knowledge, such results are new even in the purely local case.
\end{Remark}


