        u_n\rightharpoonup u \text{ weakly in } W^{1,p}_{\mathrm{loc}}(\Omega),\\
        u_n\to u \text{ pointwise in }\Omega.
    \end{cases}
\end{align*}
{In this case by repeating} the similar proof as in $(i)$ above, together with the similar argument as in the proof of the estimate (3.15) on \cite[page 15]{BG}, one can pass to the limit in all the integrals in {(\ref{A16})} and obtain
\begin{align*}
     \int_\Omega A(x)\nabla u\cdot\nabla\phi\, dx+\int_{\mathbb{R}^N}\int_{\mathbb{R}^N}&(u(x)-u(y))(\phi(x)-\phi(y))K(x,y)\, dxdy\nonumber\\
     &=\int_\Omega\frac{\phi}{u^\delta}\, d\nu+\int_\Omega \phi d\mu.
\end{align*}
Thus $u\in W^{1,p}_{\mathrm{loc}}(\Omega)$ solves the equation (\ref{ME}). {Moreover, by Lemma \ref{LD2}-$(b)$ and {Lemma \ref{emb}}, one has the sequence $\{G_1(u_n)\}_{n\in\mathbb{N}}$ is uniformly bounded in $L^1(\Omega)$. Taking this into account along with the fact that $|T_1(u_n)|\leq 1$ in $\Omega$ and $u_n=T_1(u_n)+G_1(u_n)$, we obtain that $\{u_n\}_{n\in\mathbb{N}}$ is uniformly bounded in $L^1(\Omega)$. Thus, by Fatou's Lemma, it follows that $u\in L^1(\Omega).$ Furthermore, using Lemma \ref{LD2}-$(b)$, one obtain that $T_k(u)\in W^{1,2}_{\mathrm{loc}}(\Omega)$ such that $T^\frac{\delta_*+1}{2}_k(u)\in W^{1,2}_0(\Omega)$ for every $k>0$.} 
\end{enumerate}

\subsection{Proof of Theorem \ref{Theorem2}} 
Suppose that $\nu\in M^{p}_0(\Omega)\setminus\{0\}$ is a non-negative bounded Radon measure on $\Omega$, which is singular with respect to the Lebesgue measure, and
 $\{\nu_n\}_{n\in\mathbb{N}}\subset W^{-1,p'}(\Omega)\setminus\{0\}$ is the same sequence discussed in the proof of Theorem \ref{Theorem1}. For each $n\in\mathbb{N}$, we consider the following approximation of the equation (\ref{ME}):
\begin{align}\label{BP}
    \begin{cases}
    \mathcal{M}u=\frac{\nu_n}{(u+\frac{1}{n})^\delta}+T_n(\mu) \text{ in } \Omega,\\
    u=0 \text{ in }\mathbb{R}^N\setminus\Omega \text{ and } u>0 \text{ in }\Omega,
    \end{cases}
\end{align}
where $\mu\in L^\frac{N(\delta+1)}{N+2\delta}(\Omega)$ is a non-negative function in $\Omega$. Finally, we pass to the limit in the weak formulation of \eqref{BP} to conclude the result. This follows by taking into account Lemma \ref{LD11}, Lemma \ref{BL2}-$(a), (b)$ along with Lemma \ref{BL2}-$(c)$ and proceeding along the lines of the proof of Theorem \ref{Theorem1}.

\section{Appendix}
\subsection{Approximate problem}
Throughout this subsection, we assume that $\delta:\overline{\Omega}\to(0,\infty)$ is a continuous function, which is locally Lipschitz continuous in $\Omega$ and  $|\nabla\delta|\in L^N(\Omega)$. Consequently, $|\nabla\delta|\in L^\infty_{\mathrm{loc}}(\Omega)\cap L^N(\Omega)$. We consider the problem
\begin{align}\label{APE0}
    \begin{cases}
        \mathcal{M}u=\frac{\Tilde{\nu}}{(u+\tau)^{\delta(x)}}+g \text{ in }\Omega,\\
        u=0 \text{ in }\mathbb{R}^N\setminus\Omega \text{ and } u>0 \text{ in }\Omega,
    \end{cases}\tag{$P_{\tau,\Tilde{\nu},g}$}
\end{align}
where $\tau>0$ is a constant, $\Tilde{\nu}\in W^{-1,2}(\Omega)\setminus\{0\}$ is a non-negative measure, and $g\in L^2(\Omega)$ is a non-negative function.

\begin{Lemma}\label{Existence}
    There exists a unique weak solution $u\in W^{1,2}_0(\Omega)$ of the problem (\ref{APE0}).
\end{Lemma}
\begin{proof}
Since $\Tilde{\nu}\in W^{-1,2}(\Omega)\setminus\{0\}$, by the Lax-Milgram theorem {\cite[page 315]{LC}}, there exists a unique $w\in W^{1,2}_0(\Omega)\setminus\{0\}$ such that 
\begin{equation}
        -\Delta w=\Tilde{\nu} \text{ in }\Omega,
\end{equation}
Furthermore, by \cite[Lemma 2.1]{MC18}, for each $n\in\N$, there exists a unique $w_n\in W^{1,2}_0(\Omega)$ such that $w_n\neq w_m$ for $n\neq m$ satisfying
\begin{equation}
        -\frac{1}{n}\Delta w_n+w_n=w \text{ in }\Omega,
\end{equation}
with $w_n\to w$ strongly in $W^{1,2}_0(\Omega)$ and observe that $\De w_n\in W^{1,2}_0(\Omega)$. As in \cite[Lemma A.1]{BG}, there exists $u_n\in W^{1,2}_0(\Omega)$ satisfying the equation
\begin{align}\label{APE01}
    \mathcal{M}u_n=\frac{-\De w_n}{(|u_n|+\tau)^{\delta(x)}}+g \text{ in }\Omega.
\end{align}
In order to prove the boundedness of the sequence $\{u_n\}_{n\in\N}$, we incorporate $u_n$ as a test function in the weak formulation of \eqref{APE01} and utilize \eqref{lkernel}, \eqref{nkernel} to obtain
\begin{align}\label{Ine}
   \alpha \int_\Omega|\nabla u_n|^2\;dx&\leq \int_\Omega \frac{u_n(-\De w_n)}{(|u_n|+\tau)^{\delta(x)}}\;dx+\int_\Omega u_ng\;dx\nonumber\\
   &= \int_\Omega \nabla w_n\cdot\nabla\left(\frac{u_n}{(|u_n|+\tau)^{\delta(x)}}\right)\;dx+\int_\Omega u_ng\;dx\nonumber\\
    &\leq \|\nabla w_n\|_{L^2(\Omega)}\Big\|\nabla\left(\frac{u_n}{(|u_n|+\tau)^{\delta(x)}}\right)\Big\|_{L^2(\Omega)}+\|g\|_{L^2(\Omega)}\|u_n\|_{L^2(\Omega)}.
\end{align}
Using Poincar\'{e} inequality, H\"{o}lder inequality, Lemma \ref{emb} and the fact $|\nabla\delta|\in L^N(\Omega)$, we deduce
\begin{align}\label{Ineq2}
    \int_\Omega \Big|\nabla\left(\frac{u_n}{(|u_n|+\tau)^{\delta(x)}}\right)\Big|^2\;dx&\leq C\Big(\int_\Omega\Big|\frac{\nabla u_n}{(|u_n|+\tau)^{\delta(x)}}\Big|^2\;dx+\int_\Omega \Big|\frac{u_n\nabla\delta}{(|u_n|+\tau)^{\delta(x)}}\mathrm{log}(|u_n|+\tau)\Big|^2\;dx\nonumber\\
    &+\int_\Omega \Big|\frac{\delta u_n\nabla u_n}{(|u_n|+\tau)^{\delta(x)+1}}\Big|^2\;dx\Big)\nonumber\\
    &\leq C\Big(\int_\Omega |\nabla u_n|^2\;dx+\int_\Omega |u_n|^2|\nabla\delta|^2\;dx+\int_\Omega |\nabla u_n|^2\;dx\Big)\nonumber\\
    &\leq C\Big (\int_\Omega |\nabla u_n|^2\;dx+\Big(\int_\Omega |u_n|^{2^*}\;dx\Big)^\frac{2}{2^*}\Big(\int_\Omega |\nabla\delta|^N\;dx\Big)^\frac{2}{N}\nonumber\\&+\int_\Omega |\nabla u_n|^2\;dx\Big)
    \leq C\int_\Omega |\nabla u_n|^2\;dx,
\end{align}
where $C>0$ is a constant independent of $n$. In the second line, we used the fact
\begin{align}\label{LC}
   \Big|\frac{\mathrm{log}(|u_n|+\tau)}{(|u_n|+\tau)^{\delta(x)}}\Big|=\Big|\Big(\frac{1}{(|u_n|+\tau)^{\delta(x)-r}}\Big)\Big(\frac{\mathrm{log}(|u_n|+\tau)}{(|u_n|+\tau)^r}\Big)\Big|\leq C\text{ in }\Omega,
\end{align}
where $r:=\inf_{\overline{\Omega}}\delta>0$, and $C>0$ is independent of $n$. Here, we used the boundedness of the function $\frac{\mathrm{log}t}{t^r}$ in $[\tau,\infty)$. Utilizing inequality (\ref{Ineq2}) along with the boundedness of $\{w_n\}_{n\in\mb N}$ in $W^{1,2}_0(\Omega)$, (\ref{Ine}) yields
$$\int_\Omega |\nabla u_n|^2\;dx\leq C,$$
where $C>0$ is independent of $n$ but depends on $\tau$. Hence, there exists $u\in W^{1,2}_0(\Omega)$ such that $u_n\rightharpoonup u$ weakly in $W^{1,2}_0(\Omega)$ and $u_n\to u$ pointwise a.e. in $\Omega$. Assume that $\phi\in W^{1,2}_0({\Omega})\cap L^\infty(\Omega)$ is a compactly supported function, and we have 
\begin{align}
    \int_\Omega &A(x)\nabla u_n\cdot\nabla \phi \, dx+\int_{\mathbb{R}^N}\int_{\mathbb{R}^N}(u_n(x)-u_n(y))(\phi(x)-\phi(y))K(x,y)\, dx dy\nonumber\\
&=\int_\Omega\frac{-\De w_n \phi}{(|u_n|+\tau)^{\delta(x)}}\;dx+\int_\Omega \phi g\, dx.\nonumber\\
&=\int_\Omega \nabla w_n\cdot \nabla\left(\frac{\phi}{(|u_n|+\tau)^{\delta(x)}}\right)\;dx+\int_\Omega \phi g\, dx.
\end{align}
Taking $n\to\infty$ in both the sides, we obtain
\begin{align}\label{ges1}
      \int_\Omega &A(x)\nabla u\cdot\nabla \phi \, dx+\int_{\mathbb{R}^N}\int_{\mathbb{R}^N}(u(x)-u(y))(\phi(x)-\phi(y))K(x,y)\, dx dy\nonumber\\
     &=\lim_{n\to\infty}\int_\Omega \nabla w_n\cdot \nabla\left(\frac{\phi}{(|u_n|+\tau)^{\delta(x)}}\right)\;dx+\int_\Omega \phi g\, dx.
\end{align}
In order to pass the limit to the integral in the second last term in \eqref{ges1}, we observe
\begin{equation}\label{gesnew1}
\begin{split}
    \int_\Omega \nabla w_n\cdot\nabla\left (\frac{\phi}{(|u_n|+\tau)^{\delta(x)}}\right )\, dx&=\int_\Omega\frac{\nabla w_n\cdot\nabla \phi}{(|u_n|+\tau)^{\delta(x)}}\, dx-\int_\Omega\frac{\nabla w_n\cdot\nabla\delta(x)}{(|u_n|+\tau)^{\delta(x)}}\log{\Big(|u_n|+\tau\Big)}\phi\, dx\\
&-\int_\Omega\frac{\delta(x)\nabla w_n\cdot\nabla |u_n|}{(|u_n|+\tau)^{\delta(x)+1}}\phi\, dx.
\end{split}
\end{equation}
Since $w_n\to w$ strongly in $W^{1,2}_0(\Omega)$, and the sequences $\Big\{\frac{\nabla \phi}{(|u_n|+\tau)^{\delta(x)}}\Big\}_{n\in\N}$ converges weakly to the function $\frac{\nabla \phi}{(|u|+\tau)^{\delta(x)}}$ in $L^2(\Omega)^N$, we get
$$\lim_{n\to\infty}\int_\Omega\frac{\nabla w_n\cdot\nabla \phi}{(|u_n|+\tau)^{\delta(x)}}\, dx=\int_\Omega\frac{\nabla w\cdot\nabla \phi}{(|u|+\tau)^{\delta(x)}}\, dx.$$
Furthermore, using the facts (\ref{LC}), $|\nabla\delta|\in L^\infty_{\mathrm{loc}}(\Omega)$, we conclude that $$\frac{\nabla\delta(x)}{(|u_n|+\tau)^{\delta(x)}}\log{\big(|u_n|+\tau\big)}\phi\rightharpoonup\frac{\nabla\delta(x)}{(|u|+\tau)^{\delta(x)}}\log{\big(|u|+\tau\big)}\phi\text{ weakly in }L^2(\Omega)^N$$ and hence
$$\lim_{n\to\infty} \int_\Omega\frac{\nabla w_n\cdot\nabla\delta(x)}{(|u_n|+\tau)^{\delta(x)}}\log{\big(|u_n|+\tau\big)}\phi\, dx=\int_\Omega\frac{\nabla w\cdot\nabla\delta(x)}{(|u|+\tau)^{\delta(x)}}\log{\big(|u|+\tau\big)}\phi\, dx.$$
Moreover, since $\phi\in L^\infty(\Omega)$ and $|u_n|\rightharpoonup |u|$ weakly in $W^{1,2}_0(\Omega)$, by a similar argument, we arrive at
$$\lim_{n\to\infty}\int_\Omega\frac{\delta(x)\nabla w_n\cdot\nabla |u_n|}{(|u_n|+\tau)^{\delta(x)+1}}\phi\, dx=\int_\Omega\frac{\delta(x)\nabla w\cdot\nabla |u|}{(|u|+\tau)^{\delta(x)+1}}\phi\, dx.$$
Combining the above facts in \eqref{gesnew1}, we deduce
\begin{align}\label{ges}
    \lim_{n\to\infty}\int_\Omega \nabla w_n\cdot \nabla\left(\frac{\phi}{(|u_n|+\tau)^{\delta(x)}}\right)\;dx=\int_\Omega \nabla w\cdot \nabla\left(\frac{\phi}{(|u|+\tau)^{\delta(x)}}\right)\;dx.
\end{align}
Using (\ref{ges}) in (\ref{ges1}), we obtain
\begin{align}\label{Weak11}
    \int_\Omega &A(x)\nabla u\cdot\nabla \phi \, dx+\int_{\mathbb{R}^N}\int_{\mathbb{R}^N}(u(x)-u(y))(\phi(x)-\phi(y))K(x,y)\, dx dy\nonumber\\
     &=\int_\Omega \nabla w\cdot \nabla\left(\frac{\phi}{(|u|+\tau)^{\delta(x)}}\right)\;dx+\int_\Omega \phi g\, dx.
\end{align}
Now for a non-negative function $v\in W^{1,2}_0(\Omega)\cap L^\infty(\Omega)$, there exists as sequence of compactly supported function $\{v_n\}\subset W^{1,2}_0(\Omega)\cap L^\infty(\Omega)$ (see, \cite[Lemma A.1]{Hirano04}) such that $0\leq v_1\leq v_2\leq...\leq v_n\leq v_{n+1}\leq...$ and $v_n$ converges to $v$ strongly in $W^{1,2}_0(\Omega)$. Thus, putting $\phi=v_n$ in (\ref{Weak11}) and then taking $n\to\infty$, we deduce
\begin{align}\label{Weak2}
    \int_\Omega &A(x)\nabla u\cdot\nabla v \, dx+\int_{\mathbb{R}^N}\int_{\mathbb{R}^N}(u(x)-u(y))(v(x)-v(y))K(x,y)\, dx dy\nonumber\\
     &=\lim_{n\to\infty}\int_\Omega \nabla w\cdot \nabla\left(\frac{v_n}{(|u|+\tau)^{\delta(x)}}\right)\;dx+\int_\Omega v g\, dx.
\end{align}
In order to pass the limit to the integral, we use the equality
\begin{equation}\label{WS}
    \int_\Omega \nabla w\cdot \nabla\left(\frac{v_n}{(|u|+\tau)^{\delta(x)}}\right)\;dx=\int_\Omega \nabla w\cdot\left(\frac{\nabla v_n}{(|u|+\tau)^{\delta(x)}}\right)\;dx+\int_\Omega \nabla w\cdot \nabla\left(\frac{1}{(|u|+\tau)^{\delta(x)}}\right)v_n\;dx.
\end{equation}

Since $v_n\to v$ in $W^{1,2}_0(\Omega)$, we have
$$\lim_{n\to\infty}\int_\Omega \nabla w\cdot\left(\frac{\nabla v_n}{(|u|+\tau)^{\delta(x)}}\right)\;dx=\int_\Omega \nabla w\cdot\left(\frac{\nabla v}{(|u|+\tau)^{\delta(x)}}\right)\;dx.$$
Since $v\in L^\infty(\Omega)$, utilizing monotone convergence theorem along with generalized dominated convergence theorem, we get 
\begin{equation}\label{boundedness}
    \lim_{n\to\infty}\int_\Omega \nabla w\cdot \nabla\left(\frac{1}{(|u|+\tau)^{\delta(x)}}\right)v_n\;dx=\int_\Omega \nabla w\cdot \nabla\left(\frac{1}{(|u|+\tau)^{\delta(x)}}\right)v\;dx.
\end{equation}
Combining these two estimates along with \eqref{WS}, \eqref{Weak2} yields that for every non-negative $v\in W^{1,2}_0(\Omega)\cap L^\infty(\Omega)$ we have
\begin{align}\label{Weak}
    \int_\Omega &A(x)\nabla u\cdot\nabla v \, dx+\int_{\mathbb{R}^N}\int_{\mathbb{R}^N}(u(x)-u(y))(v(x)-v(y))K(x,y)\, dx dy\nonumber\\
     &=\int_\Omega \nabla w\cdot \nabla\left(\frac{v}{(|u|+\tau)^{\delta(x)}}\right)\;dx+\int_\Omega v g\, dx.
\end{align}
For every $v\in W^{1,2}_0(\Omega)\cap L^\infty(\Omega)$, we write $v=v^+-v^-$ and \eqref{Weak} hold for $v^+$ and $v^-$. Using linearity, we can conclude that \eqref{Weak} hold for $v$.\\
Now we shall prove that $u>0$ in $\Omega$. To this concern, we incorporate $v=-T^-_l(u)$ in \eqref{Weak} and use \eqref{lkernel}, \eqref{nkernel} to deduce
\begin{align}
    \alpha\int_\Omega |\nabla T^-_l(u)|^2\;dx\leq 0,\text{ for all }l>0.
\end{align}
Taking $l\to\infty$ and using Fatou's lemma, we get $u^-=0$ in $\Omega$. Consequently, $u\geq 0$ in $\Omega$. Thus, \cite[Lemma 4.6]{GKK} ensures $u>0$ in $\Omega$, which implies that $u$ is a weak solution of (\ref{APE0}).\\
\textbf{Uniqueness:} Let us assume that $u_1$ and $u_2$ are two such solutions of (\ref{APE01}). Thus,
$$\mathcal{M}(u_1-u_2)=\left(\frac{1}{(u_1+\tau)^{\delta(x)}}-\frac{1}{(u_2+\tau)^{\delta(x)}}\right)\Tilde{\nu} \text{ in }\Omega.$$
Incorporating $v= T^+_l(u_1-u_2)$ in the weak formulation of the above equation and utilizing (\ref{lkernel}) and (\ref{nkernel}), we obtain
\begin{align*}
    \alpha\int_\Omega |\nabla T^+_l(u_1-u_2)|^2\leq \int_\Omega\left(\frac{1}{(u_1+\tau)^{\delta(x)}}-\frac{1}{(u_2+\tau)^{\delta(x)}}\right)T^+_l(u_1-u_2)\;d\Tilde{\nu}\leq 0,
\end{align*}
which yields
$$\int_\Omega|T^+_l(u_1-u_2)|^{2^*}\;dx\leq 0.$$
By Fatou's lemma, we get
$$\int_\Omega|(u_1-u_2)^+|^{2^*}\;dx\leq 0,$$
which implies $u_1\leq u_2$ in $\Omega.$ Interchanging the roles of $u_1$ and $u_2$, we have $u_2\leq u_1$ in $\Omega$. Consequently, $u_1=u_2$ in $\Omega$. This completes the proof.
\end{proof}


We assume that $\{\nu_n\}_{n\in\mathbb{N}}\subset W^{-1,2}(\Omega)\setminus\{0\}$ is an increasing sequence of non-negative measures and $\{g_n\}_{n\in\mathbb{N}}\subset L^2(\Omega)$ is a sequence of non-negative functions in $\Omega$. Then, by Lemma \ref{Existence}, for each fixed $n\in\mathbb{N}$, there exists a unique $u_n\in W^{1,2}_0(\Omega)$ that solves the equation \ref{APE0} with $\tau=\frac{1}{n},\,\Tilde{\nu}=\nu_n,\,g=g_n$. That is, $u_n$ solves the following approximated problem:
\begin{align}\label{APE1}
    \begin{cases}
        \mathcal{M}u=\frac{\nu_n}{(u+\frac{1}{n})^{\delta(x)}}+g_n \text{ in }\Omega,\\
        u=0 \text{ in }\mathbb{R}^N\setminus\Omega \text{ and } u>0 \text{ in }\Omega,
    \end{cases}
\end{align}
in the sense of the integral identity (\ref{Weak}).

\begin{Lemma}\label{LD11}(Uniform positivity)
    Let for each $n\in\mathbb{N}$, $u_n\in W^{1,2}_0(\Omega)$ denotes the unique solution of the equation (\ref{APE1}). Then, for every $\omega\Subset\Omega$, there exists a constant $C(\omega)>0$ (independent of $n$) such that $u_n\geq C(\omega)$ in $\omega$ for all $n$.
\end{Lemma}
\begin{proof}
Let $n\in\mathbb{N}$. To obtain a uniform lower bound of $u_n$, we compare $u_n$ with the solution $w\in W^{1,2}_0(\Omega)$ of the equation \ref{APE0} with $\tau=1,\,\Tilde{\nu}=\nu_1,\,g=0$. That is $w$ satisfies the following equation:
\begin{align}\label{A77}
    \begin{cases}
         \mathcal{M}w=\frac{\nu_1}{(w+1)^{\delta(x)}}\text{ in }\Omega,\\
     w=0 \text{ in }\mathbb{R}^N\setminus\Omega \text{ and } w>0 \text{ in }\Omega.
    \end{cases}
\end{align}
By incorporating the test function $v=T^+_l(w-u_n)$ in the weak formulations of (\ref{APE1}),(\ref{A77}) and subtracting one from the other, we obtain
\begin{align*}
    \int_\Omega A(x)&\nabla(w-u_n)\cdot\nabla v\, dx+\int_{\mathbb{R}^N}\int_{\mathbb{R}^N}((w-u_n)(x)-(w-u_n)(y))(v(x)-v(y))K(x,y)dx\, dy\nonumber\\
    &=\int_\Omega\frac{v}{(w+1)^{\delta(x)}}\, d\nu_1
    -\int_\Omega\frac{v}{(u_n+\frac{1}{n})^{\delta(x)}}\, d\nu_n-\int_\Omega vg_n \, dx\nonumber\\
    &\leq \int_\Omega \left ( \frac{1}{(w+1)^{\delta(x)}}-\frac{1}{(u_n+\frac{1}{n})^{\delta(x)}}\right )T^+_l(w-u_n)\, d\nu_n\leq 0.
\end{align*}
In the last line, we used the fact $\nu_1\leq\nu_n$. Due to the property (\ref{lkernel}) and (\ref{nkernel}), we have 
\begin{align*}
    \alpha\int_\Omega|\nabla v|^2 dx+\underbrace{\Lambda^{-1}\int_{\mathbb{R}^N}\int_{\mathbb{R}^N}\frac{((w-u_n)(x)-(w-u_n)(y))(v(x)-v(y))}{|x-y|^{N+2s}}\, dxdy}_{\geq 0}\leq 0,
\end{align*}
which implies
\begin{align*}
    0\leq\int_{\Omega}|\nabla T^+_l(w-u_n)|^2\, dx\leq 0, \text{ for all }l>0.
\end{align*}
 Thus, $T^+_l(w-u_n)=0$ in $\Omega$ for all $l>0$, which implies $ (w-u_n)^+=0$ in $\Omega$. Hence, $u_n\geq w$ in $\Omega$. Since $n\in\mathbb{N}$ is arbitrary, $u_n\geq w$ for all $n\in\mathbb{N}$. {From \cite[Lemma 4.6]{GKK}, we can conclude that for every $\omega\Subset\Omega$, there exists a constant $C(\omega)>0$ such that $w\geq C(\omega)$ in $\omega$ and consequently, $u_n\geq C(\omega)$ in $\omega$ for all $n$.}
\end{proof}

\subsection{A priori estimates for {Theorem \ref{Theorem1}}}
The following uniform boundedness results will be useful for the proofs of Theorem \ref{Theorem1}.
\begin{Lemma}\label{LD2}(Uniform boundedness)
Assume that $\delta:\overline{\Omega}\to(0,\infty)$ is a continuous function such that $\delta$ is locally Lipschitz continuous in $\Omega$, $|\nabla\delta|\in L^N(\Omega)$, and $\delta$ satisfies $P_{\epsilon,\delta_*}$ for some $\;\delta_*\geq 1$ and for some $\epsilon>0$.

   Further, we suppose that the sequence of non-negative non-zero measures $\{\nu_n\}_{n\in\N}\subset W^{-1,2}(\Omega)\cap M^2_0(\Omega)$ is uniformly bounded in $\mathcal{M}(\Omega)$ (in total variation norm). Let $n\in\mathbb{N}$ and assume that the solution of (\ref{APE1}) obtained in Lemma \ref{Existence} is denoted by $u_n$. If the sequence of non-negative functions $\{g_n\}_{n\in\mathbb{N}}\subset L^2(\Omega)$ in $\Omega$ is uniformly bounded in $L^1(\Omega)$, then the following conclusions hold:
    \begin{enumerate}
        \item[(a)] If $\delta_*=1$, then the sequence $\{u_n\}_{n\in \mathbb{N}}$ is uniformly bounded in $W^{1,q}_0(\Omega)$ for every $1<q<\frac{N}{N-1}$.
        \item[(b)] If $\delta_*>1$, then the sequence $\{u_n\}_{n\in \mathbb{N}}$ is uniformly bounded in $W^{1,q}_{\mathrm{loc}}(\Omega)\cap L^1(\Omega)$ for every $1<q<\frac{N}{N-1}$. {Moreover, the sequences $\{G_k(u_n)\}_{n\in\mathbb{N}}$, $\{T_k(u_n)\}_{n\in\mathbb{N}}$ and $\Big\{T_k^\frac{\delta_*+1}{2}(u_n)\Big\}_{n\in\mathbb{N}}$ are uniformly bounded in $W^{1,q}_0(\Omega)$, $W^{1,2}_{\mathrm{loc}}(\Omega)$ and $W^{1,2}_0(\Omega)$, respectively for every fixed $k>0$ and $1<q<\frac{N}{N-1}$.}
    \end{enumerate}
\end{Lemma}
\begin{proof}
\begin{enumerate}
\item[$(a)$] We assume $\delta_*=1,$ which implies $0<\delta(x)\leq 1$ in $\Omega_\epsilon$. We shall prove that $\{u_n\}_{n\in\mathbb{N}}$ is uniformly bounded in $W^{1,q}_0(\Omega)$ for every $1<q<\frac{N}{N-1}$. Due to the fact (\ref{maremb}), it is sufficient to prove that $\{u_n\}_{n\in\mathbb{N}}$ is bounded in {$M^\frac{N}{N-1}(\Omega).$} Since $\Omega$ is bounded, it is enough to estimate the measure, $|x\in\Omega:\{|\nabla u_n|\geq t\}|$ for all $t\geq 1$. For any $l,t\geq 1$, we observe that
\begin{align}\label{KZ}
    |\{ x\in\Omega: |\nabla u_n|\geq t\}|\leq \underbrace{|\{x\in\Omega: |\nabla u_n|\geq t, u_n\leq l\}|}_{=I_2}+\underbrace{|\{x\in\Omega: |\nabla u_n|\geq t, u_n\geq l\}|}_{=I_1}.
\end{align}
We shall estimate $I_1$ and $I_2$. In order to estimate $I_1$, we put $\phi=T_l(u_n)$ as a test function in the weak formulation of the equation $(\ref{APE1})$ and use (\ref{lkernel}) and (\ref{nkernel}) to deduce
\begin{align}\label{AT9}
    \alpha\int_\Omega |\nabla T_l(u_n)|^2\, dx+&\Lambda^{-1}\underbrace{\int_{\mathbb{R}^N}\int_{\mathbb{R}^N} \frac{(u_n(x)-u_n(y))(T_l(u_n(x))-T_l(u_n(y)))}{|x-y|^{N+2s}}\, dxdy}_{\geq 0}\nonumber\\
    &\leq \int_\Omega\frac{T_l(u_n)}{(u_n+\frac{1}{n})^{\delta(x)}}\, d\nu_n+\int_\Omega T_l(u_n)g_n\, dx\nonumber\\
    &\leq \underbrace{\int_\Omega\frac{T_l(u_n)}{(u_n+\frac{1}{n})^{\delta(x)}}\, d\nu_n}_{=J_1}+l||g_n||_{L^1(\Omega)}.
\end{align}
We observe that, since $T_l(s)$ is an increasing function in $s$, the nonlocal integral above becomes non-negative. Using Lemma \ref{Bdd} and boundedness of $\{\nu_n\}_{n\in\N}$ in $\mathcal{M}(\Omega)$, we obtain 
\begin{align}
J_1&=\int_{\Omega}\frac{T_l(u_n)}{(u_n+\frac{1}{n})^{\delta(x)}}\, d\nu_n\leq \Big\|\frac{T_l(u_n)}{(u_n+\frac{1}{n})^{\delta(x)}}\Big\|_{L^\infty(\Omega)}|\nu_n(\Omega)|\leq C\Big\|\frac{T_l(u_n)}{(u_n+\frac{1}{n})^{\delta(x)}}\Big\|_{L^\infty(\Omega)} .
\end{align}
By using the property $P_{\epsilon,\delta_*}$ and Lemma \ref{LD11}, we deduce
\begin{align*}
    \Big|\frac{T_l(u_n)}{(u_n+\frac{1}{n})^{\delta(x)}}\Big|&=\Big|\frac{T_l(u_n)}{(u_n+\frac{1}{n})^{\delta(x)}}\chi_{\Omega\cap\Omega_\epsilon^c}(x)\Big|+\Big|\frac{T_l(u_n)}{(u_n+\frac{1}{n})^{\delta(x)}}\chi_{\Omega_\epsilon}(x)\Big|\\
    &\leq Cl+\Big|\frac{T_l(u_n)}{(u_n+\frac{1}{n})^{\delta(x)}}\chi_{\{x\in\Omega_\epsilon:u_n(x)>1\}}(x)\Big|+\Big|\frac{T_l(u_n)}{(u_n+\frac{1}{n})^{\delta(x)}}\chi_{\{x\in\Omega_\epsilon:u_n(x)\leq 1\}}(x)\Big|\\
    &\leq Cl+Cl+\Big|\frac{T_l(u_n)}{(T_l(u_n)+\frac{1}{n})^{\delta(x)}}\chi_{\{x\in\Omega_\epsilon:u_n(x)\leq 1\}}(x)\Big|\\
    &\leq 2Cl+T_l^{1-\delta(x)}(u_n)\chi_{\{x\in\Omega_\epsilon:u_n(x)\leq1\}}(x)\\
    &\leq 2Cl+l\leq Cl,
\end{align*}
which yields
\begin{align}\label{ATheorem10}
    J_1\leq Cl,
\end{align}
where $C>0$ is a constant independent of $n$. It follows from (\ref{AT9}) and (\ref{ATheorem10}) along with the uniform $L^1$ bound of $g_n$ that 
\begin{align}\label{ATheorem12}
    \int_\Omega |\nabla T_l(u_n)|^2\, dx\leq Cl,
\end{align}
where $C>0$ is a constant independent of $n$. By Lemma \ref{emb}, one has
\begin{align*}
    \left (\int_{\{x\in\Omega: u_n(x)\geq l\}} |T_l{(u_n)}|^{2^*}\, dx\right )^\frac{2}{2^*}\leq Cl,
\end{align*}
where {$2^*=\frac{2N}{N-2}$}. Here, $C>0$ is a constant independent of $n$. This yields 
\begin{align*}
    |\{x\in\Omega: u_n(x)\geq l\}|^\frac{2}{2^*}\leq \frac{C}{l}.
\end{align*}
Thus, there exists a constant $C>0$ is a constant independent of $n$ such that
\begin{align}\label{ST2}
   I_1\leq \left |\{x\in\Omega: u_n(x)\geq l\}\right |\leq \frac{C}{l^{\frac{N}{N-2}}}, \text{ for all }l\geq 1.
\end{align}
Now we estimate $I_2$. To this concern, we deduce
\begin{align}\label{ATheorem14}
    I_2&=|\{x\in\Omega: |\nabla u_n|\geq t, u_n\leq l\}|\leq \frac{1}{t^2}\int_{\{x\in\Omega:u_n\leq l\}}|\nabla u_n|^2\, dx\nonumber\\
    &\leq \frac{1}{t^2}\int_\Omega |\nabla T_l(u_n)|^2\, dx\leq \frac{Cl}{t^2},
\end{align}
where $C>0$ is a constant independent of $n$. The rest of the proof follows by proceeding along the lines of the proof of \cite[Lemma A.2, page 23]{BG}.

\item[$(b)$] We suppose that $\delta_*>1$. We shall prove that for every fixed $k>0$, the sequence $\{G_k(u_n)\}_{n\in\mathbb{N}}$ is uniformly bounded in $W^{1,q}_0(\Omega)$ for every $1<q<\frac{N}{N-1}.$

To this end, similar to part $(a)$ above, we estimate the measure $|\{x\in\Omega:|\nabla G_k(u_n)|\geq t\}|$ for all $t\geq 1.$ Let $l>0$. Then, we observe that 
\begin{align}\label{ineq1}
    &|\{x\in\Omega:\nabla G_k(u_n)|\geq t\}|\nonumber\\
    &\leq \underbrace{|\{x\in\Omega:|\nabla G_k(u_n)|\geq t, G_k(u_n)\leq l\}}_{I_2}|+\underbrace{|\{x\in\Omega:|\nabla G_k(u_n)|\geq t, G_k(u_n)\geq l\}|}_{I_1}.
\end{align}
We estimate $I_1$ and $I_2$ using the same approach as in part $(a)$ above. By taking the test function $\phi=T_l(G_k(u_n))$ in the weak formulation of (\ref{APE1}) and applying Lemma \ref{Bdd} along with uniform bound of $\{\nu_n\}$ in $\mathcal{M}(\Omega)$, we obtain
\begin{align}\label{cl}
    \int_\Omega A(x)\nabla u_n\cdot \nabla T_l(G_k(u_n)) \, dx&+\underbrace{\int_{\mathbb{R}^N}\int_{\mathbb{R}^N}(u_n(x)-u_n(y))(\phi(x)-\phi(y)K(x,y)\, dxdy}_{\geq 0}\nonumber\\
    &=\int_\Omega \frac{T_l(G_k(u_n))}{(u_n+\frac{1}{n})^{\delta(x)}}\, d\nu_n+\int_\Omega g_nT_l(G_k(u_n))\, dx\nonumber\\
    &\leq l\left\lVert \frac{1}{k^{\delta(x)}}\right\rVert_{L^\infty(\Omega)}\nu_n(\Omega)+l\int_\Omega g_n\leq Cl,
\end{align}
where the constant $C>0$ is independent of $n.$ We observe that, since $T_l(s)$ is an increasing function in $s$, the nonlocal integral above becomes non-negative. We have used the fact that $u_n\geq k$ in $\mathrm{supp}\,T_l(G_k(u_n))$ to obtain the first inequality in \eqref{cl} above. Then the above inequality \eqref{cl} together with (\ref{lkernel}) leads to
\begin{align}\label{W4}
  \int_\Omega |\nabla T_l(G_k(u_n))|^2\, dx\leq Cl,
\end{align}
where $C>0$ is a constant independent of $n.$ The rest of the proof follows similar to that of claim 1 in \cite[Lemma A.2, page 24]{BG}.\\
 We are left with the proof of the facts that the sequences $\{T_k(u_n)\}_{n\in\mathbb{N}}$ and $\Big\{T_k(u_n)^\frac{\delta_*+1}{2}\Big\}_{n\in\mathbb{N}}$ are uniformly bounded in $W^{1,2}_{\mathrm{loc}}(\Omega)$ and $W^{1,2}_{0}(\Omega)$, respectively for every fixed $k>0$.

To this concern, we put $\phi=T^{\delta_*}_k(u_n)$ into the weak formulation of (\ref{APE1}) and use of the properties (\ref{lkernel}) and (\ref{nkernel}) to deduce
\begin{align}\label{W2}
    \frac{4\alpha\delta_*}{(\delta_*+1)^2}\int_\Omega \Big|\nabla T^\frac{\delta_*+1}{2}_k(u_n)\Big|^2\, dx&+\Lambda^{-1}\underbrace{\int_{\mathbb{R}^N}\int_{\mathbb{R}^N} \frac{(u_n(x)-u_n(y))(\phi(x)-\phi(y))}{|x-y|^{N+2s}}\, dxdy}_{\geq 0}\nonumber\\
    &\leq \int_\Omega \frac{T^{\delta_*}_k(u_n)}{(u_n+\frac{1}{n})^{\delta(x)}}\, d\nu_n+\int_\Omega T^{\delta_*}_k(u_n) g_n\, dx.
\end{align}
Using the uniform $L^1$ bound of $g_n$, and uniform bound of the total variation of $\{\nu_n\}$ along with Lemma \ref{Bdd}, (\ref{W2}) yields
\begin{align}\label{TB}
    \int_\Omega \Big|\nabla T^\frac{\delta_*+1}{2}_k(u_n)\Big|^2\, dx&\leq C\Big(  \|T^{\delta_*-\delta(x)}_k(u_n)\|_{L^\infty(\Omega)}|\nu_n(\Omega)|+k^{\delta_*}\int_\Omega g_n\, dx\Big)\nonumber\\
    &\leq C\Big(\|k^{\delta_*-\delta(x)}\|_{L^\infty(\Omega)}+k^{\delta_*}\Big)\leq C
\end{align}
where $C>0$ is a constant independent of $n$. Hence, the sequence $\Big\{T_k(u_n)^\frac{\delta_*+1}{2}\Big\}_{n\in\mathbb{N}}$ is uniformly bounded in $W^{1,2}_{0}(\Omega)$ for every fixed $k>0$.The rest of the proof follows similarly to \cite[Lemma A.2, page 26]{BG}.
\end{enumerate}
\end{proof}

\subsection{A priori estimates for Theorem \ref{Theorem2}}
\begin{Lemma}\label{BL2}
Assume that the function $\delta:\overline{\Omega}\to (0,\infty)$ is a constant function. Let $n\in\mathbb{N}$ and define $g_n(x)=T_n(g(x))=\min\{g(x),n\}$ {in \eqref{APE1}}, where $g\in L^{\frac{N(\delta+1)}{N+2\delta}}(\Omega)$ is a non-negative function in $\Omega$. {Suppose that the solution of \eqref{APE1} obtained in Lemma \ref{Existence} is denoted by $u_n$.} If the sequence of non-negative non-zero measures $\{\nu_n\}_{n\in\N}\subset W^{-1,2}(\Omega)\cap M^2_0(\Omega)$ is uniformly bounded in $\mathcal{M}(\Omega)$ (in total variation norm), then the following conclusions hold:
\begin{enumerate}
    \item[$(a)$] If $\delta=1$, then $\{u_n\}_{n\in\mathbb{N}}$ is uniformly bounded in $W^{1,2}_0(\Omega)$.
    \item[$(b)$] If $0<\delta<1$, then $\{u_n\}_{n\in\mathbb{N}}$ is uniformly bounded in $W^{1,q}_0(\Omega)$, where $q=\frac{N(\delta+1)}{N+\delta-1}$.
     \item[$(c)$] If $\delta>1$, then $\{u_n\}_{n\in\mathbb{N}}$ is uniformly bounded in $W^{1,2}_{\mathrm{loc}}(\Omega)$. Moreover, $\{u^\frac{\delta+1}{2}_n\}_{n\in\mathbb{N}}$ is uniformly bounded in $W^{1,2}_0(\Omega).$
\end{enumerate}
\end{Lemma}

\begin{proof}
\begin{enumerate}
\item[$(a)$] Choosing $v=T_l(u_n)$ as a test function in the weak formulation of (\ref{APE1}) and applying the properties (\ref{lkernel}), (\ref{nkernel}), we get
    \begin{align}\label{RR2}
        \alpha\int_\Omega |\nabla T_l(u_n)|^2\, dx+&\Lambda^{-1}\underbrace{\int_{\mathbb{R}^N}\int_{\mathbb{R}^N}\frac{(u_n(x)-u_n(y))(T_l(u_n)(x)-T_l(u_n)(y))}{|x-y|^{N+2s}}\, dxdy}_{\geq 0}\nonumber\\
        &\leq\int_\Omega\frac{T_l(u_n)}{(u_n+\frac{1}{n})}\, d\nu_n+\int_\Omega g_nT_l(u_n)\, dx.
    \end{align}
    Using H\"{o}lder's inequality, $\nu_n$ is bounded in $\mathcal{M}(\Omega)$ along with Lemma \ref{emb} and Lemma \ref{Bdd} in (\ref{RR2}), it follows that 
\begin{align}
    \alpha||T_l(u_n)||_{{W_0^{1,2}(\Omega)}}^2\leq \nu_n(\Omega)+\int gT_l(u_n)\, dx&\leq C+||g||_{L^{(2^*)'}(\Omega)}||T_l(u_n)||_{L^{2^*}(\Omega)}\nonumber\\
    &\leq C(1+||T_l(u_n)||_{{W_0^{1,2}(\Omega)}}),
\end{align}
where $C$ is a constant independent of $n,\,l$. Hence, $||T_l(u_n)||_{{W_0^{1,2}(\Omega)}}^2\leq C,$
where $C$ is independent of $n,l$. Taking $l\to\infty$ and using Fatou's lemma, we conclude that the sequence $\{u_n\}_{n\in\mathbb{N}}$ is uniformly bounded in $W^{1,2}_0(\Omega).$

\item[$(b)$] If $0<\delta<1$, then for $0<\epsilon<\frac{1}{n}$, choosing $\phi=(T_l(u_n)+\epsilon)^\delta-\epsilon^\delta$ as a test function in the weak formulation of (\ref{APE1}) and using the properties (\ref{lkernel}), (\ref{nkernel}), we obtain
\begin{align}\label{RR1}
     \alpha\int_\Omega\Big|\nabla (T_l(u_n)+\epsilon)^{\frac{\delta+1}{2}}\Big|^2\, dx+&\Lambda^{-1}\underbrace{\int_{\mathbb{R}^N}\int_{\mathbb{R}^N}\frac{(u_n(x)-u_n(y))(\phi(x)-\phi(y))}{|x-y|^{N+2s}}\, dxdy}_{\geq 0}\nonumber\\
     &\leq \int_\Omega\frac{\phi}{(u_n+\frac{1}{n})^\delta}\, d\nu_n+\int_\Omega g_n{\phi}\, dx\nonumber\\
     &\leq \int_\Omega \frac{(T_l(u_n)+\epsilon)^\delta}{(T_l(u_n)+\frac{1}{n})^\delta}\, d\nu_n+\int_\Omega g(T_l(u_n)+\epsilon)^\delta\, dx.
\end{align}
Using H\"{o}lder inequality, $\nu_n$ is bounded in $\mathcal{M}(\Omega)$ and Lemma \ref{Bdd}, (\ref{RR1}) yields
\begin{align}\label{BW}
    \int_\Omega\Big|\nabla (T_l(u_n)+\epsilon)^{\frac{\delta+1}{2}}\Big|^2\, dx&\leq \left [|\nu_n(\Omega)|+\left (\int_\Omega (T_l(u_n)+\epsilon)^\frac{2^*(\delta+1)}{2}\, dx\right )^\frac{2\delta}{2^*(\delta+1)}||g||_{L^r(\Omega)}\right ]\nonumber\\
    &\leq C\Big[1+\left (\int_\Omega (T_l(u_n)+\epsilon)^\frac{2^*(\delta+1)}{2}\, dx\right )^\frac{2\delta}{2^*(\delta+1)}\Big],
\end{align}
where $r=\frac{N(\delta+1)}{N+2\delta}$ and $2^*=\frac{2N}{N-2}$. Arguing as in \cite[Lemma A.3-(b)]{BG}, we derive
$$\int_\Omega|\nabla T_l(u_n)|^q\, dx\leq C,$$
where $q=\frac{N(\delta+1)}{N+\delta-1}$ and $C>0$ is independent of $n,\;l$. Taking $l\to\infty$ and applying Fatou's lemma, we obtain the result.

\item[$(c)$] Let $k>0$, then we choose $T_k^\delta(u_n)$ as a test function in the weak formulation of the equation (\ref{BP}) with $\delta>1$ and apply (\ref{lkernel}), (\ref{nkernel}) to obtain
\begin{align*}
\alpha\delta\int_\Omega\Big|\nabla T_k^\frac{\delta+1}{2}(u_n)\Big|^2\, dx+&\Lambda^{-1}\underbrace{\int_{\mathbb{R}^N}\int_{\mathbb{R}^N}\frac{(u_n(x)-u_n(y))(T_k^\delta(u_n(x))-T_k^\delta(u_n(y)))}{|x-y|^{N+2s}}\, dxdy}_{\geq 0}\\
    &\leq \int_\Omega \frac{T_k^\delta(u_n)}{(u_n+\frac{1}{n})^\delta}\, d\nu_n\nonumber+\int_\Omega g_nT_k^\delta(u_n)\, dx.
\end{align*}
Using the fact $T_k(s)\leq s$ for every $k,s>0$ and Lemma \ref{Bdd}, the above identity yields
\begin{align}
    \int_\Omega\Big|\nabla T_k^\frac{\delta+1}{2}(u_n)\Big|^2\, dx\leq \nu_n(\Omega)+\int_\Omega gT_k^\delta(u_n)\, dx\leq C+\int_\Omega gT_k^\delta(u_n)\, dx,
\end{align}
 where $C$ is an upper bound of the sequence $\{|\nu_n(\Omega)|\}$. The remainder of the proof proceeds similarly to the argument used in \cite[Lemma A.3, page 29]{BG}.
\end{enumerate}
\end{proof}
